    local adminDetector = a["Features/Game/AdminDetector"]()
    local autoAssassinate = a["Features/Combat/AutoAssassinate"]()
    local autoParry = a["Features/Combat/AutoParry"]()
    local ragdollFeint = a["Features/Combat/RagdollFeint"]()
    local depthsEscape = a["Features/Game/DepthsEscape"]()
    local charismaFarm = a["Features/Automation/CharismaFarm"]()
    local kaidoFarm2 = a["Features/Automation/KaidoFarm2"]()
    local effectShower = a["Features/Game/EffectShower"]()
    local effectReplicatorWrapper = a["Game/EffectReplicatorWrapper"]()
    local exploits = a["Features/Exploits/Exploits"]()
    local intelligenceFarm = a["Features/Automation/InteligenceFarm"]()
    local logger = a["Utility/Logger"]()
    local flingPlayers = a["Features/Exploits/FlingPlayers"]()
    local mobControl = a["Features/Exploits/MobControl"]()
    local monitoring = a["Features/Game/Monitoring"]()
    local features = a["Features/Features"]()
    local optimizations = a["Features/Game/Optimizations"]()
    local ownershipWatcher = a["Features/Game/OwnershipWatcher"]()
    local parryEffects = a["Features/Combat/ParryEffects"]()
    local buildStealer = a["Features/Exploits/BuildStealer"]()
    local fastEsp = a["Features/Visuals/FastESP"]()
    local noFall = a["Features/Game/NoFall"]()
    local removal = a["Features/Game/Removal"]()
    local rhythmSpoofer = a["Features/Combat/RhythmSpoofer"]()
    local mantraTricks = a["Features/Combat/MantraTricks"]()
    local spoofing = a["Features/Game/Spoofing"]()
    local talentCards = a["Features/Visuals/TalentCards"]()
    local teleport = a["Features/Game/Teleport"]()
    local visuals = a["Features/Visuals/Visuals"]()
    local runItBackSpoofer = a["Features/Exploits/RunItBackSpoofer"]()
    local animationSpeedChanger = a["Features/Exploits/AnimationSpeedChanger"]()
    local promptRange = a["Features/Game/PromptRange"]()

    function moduleTable.init()
        local runInit = function(featureName, initFn)
            if type(initFn) ~= 'function' then
                return
            end

            local success, err = pcall(initFn)

            if not success then
                logger.warn("Features init: '%s' failed \u{2014} %s (continuing).", featureName, tostring(err))
            end

            task.wait()
        end

        runInit('Visuals', visuals.init)
        runInit('Movement', features.init)
        runInit('Monitoring', monitoring.init)
        runInit('Removal', removal.init)
        runInit('NoFallDamage', noFall.start)
        runInit('BuildStealer', buildStealer.init)
        runInit('BillboardESP', fastEsp.init)
        runInit('Exploits', exploits.init)
        runInit('Spoofing', spoofing.init)
        runInit('TalentHighlighter', talentCards.init)
        runInit('OwnershipWatcher', ownershipWatcher.init)
        runInit('CharismaFarm', charismaFarm.init)
        -- Automation is the heaviest init (loads AutoProgression's 300KB+ state
        -- machine and starts its poll loops). Running it inline here blocks the
        -- whole init pipeline, delays Menu init, and -- because menu.show()
        -- calls KaidoFarm2.hasAny() -- can stall menu display on a live server.
        -- Defer it so the menu comes up first and automation boots afterwards.
        task.spawn(function()
            local automationOk, automationErr = pcall(kaidoFarm2.init)

            if not automationOk then
                logger.warn("Features init: 'Automation' failed (deferred) \u{2014} %s", tostring(automationErr))
            end
        end)
        runInit('IntelligenceFarm', intelligenceFarm.init)
        runInit('Teleport', teleport.init)
        runInit('AntiAFK', antiAfk.init)
        runInit('AdminDMs', adminDetector.init)
        runInit('MobControl', mobControl.init)
        runInit('FlingPlayers', flingPlayers.init)
        runInit('ParryEffects', parryEffects.init)
        runInit('RhythmSpoofer', rhythmSpoofer.init)
        runInit('MantraTricks', mantraTricks.init)
        runInit('AutoAssassinate', autoAssassinate.init)
        runInit('AutoRagdollCancel', ragdollFeint.init)
        runInit('DepthsEscape', depthsEscape.init)
        runInit('Optimizations', optimizations.init)
        runInit('EffectShower', effectShower.init)
        runInit('AutoParry', function()
            autoParry.load()
            autoParry.init()
        end)

        if not armorshield or armorshield.current_role == 'builder' then
            runInit('AnimationVisualizer', animationLogger.init)
            runInit('EventVisualizer', eventLogger.init)
        end

        runInit('EffectDebugger', defenseDebugger.init)
        runInit('Techs', runItBackSpoofer.init)
        runInit('AnimationSpeedChanger', animationSpeedChanger.init)
        runInit('PromptRange', promptRange.init)
        logger.warn('Features initialized.')
    end
    function moduleTable.detach()
        pcall(feature.disableAll)

        local runDetach = function(detachFn)
            if type(detachFn) ~= 'function' then
                return
            end

            task.spawn(function()
                pcall(detachFn)
            end)
        end

        if not armorshield or armorshield.current_role == 'builder' then
            runDetach(animationLogger.detach)
            runDetach(eventLogger.detach)
        end

        runDetach(defenseDebugger.detach)
        runDetach(runItBackSpoofer.detach)
        runDetach(animationSpeedChanger.detach)
        runDetach(promptRange.detach)
        runDetach(teleport.detach)
        runDetach(antiAfk.detach)
        runDetach(adminDetector.detach)
        runDetach(charismaFarm.detach)
        runDetach(intelligenceFarm.detach)
        runDetach(spoofing.detach)
        runDetach(talentCards.detach)
        runDetach(ownershipWatcher.detach)
        runDetach(features.detach)
        runDetach(removal.detach)
        runDetach(monitoring.detach)
        runDetach(exploits.detach)
        runDetach(visuals.detach)
        runDetach(mobControl.detach)
        runDetach(flingPlayers.detach)
        runDetach(parryEffects.detach)
        runDetach(rhythmSpoofer.detach)
        runDetach(mantraTricks.detach)
        runDetach(optimizations.detach)
        runDetach(effectShower.detach)
        runDetach(effectReplicatorWrapper.detach)
        runDetach(ragdollFeint.detach)
        runDetach(autoParry.detach)
        runDetach(fastEsp.detach)
        runDetach(kaidoFarm2.detach)
        logger.warn('Features detached.')
    end

    return moduleTable
end


return aa()

]=],
    ["Features/Automation/AuthorityMissionFarm"] = [=[
local aa = function()
    local delayedTask = a["Utility/DelayedTask"]()
    local noEffects = a["Features/Game/NoEffects"]()
    local automationStep = a["Features/Automation/AutomationStep"]()
    local placeIds = a["Game/PlaceIds"]()
    local travelRecovery = a["Features/Game/TravelRecovery"]()
    local regionTransfer = a["Features/Automation/RegionTransfer"]()
    local executorInfo = a["Utility/ExecutorInfo"]()
    local clickHolder = a["Features/Combat/ClickHolder"]()
    local playerScanning = a["Game/PlayerScanning"]()
    local aj
    local ak
    local startPosition = CFrame.new(-7502, 11, 3481)
    local am = {
        CFrame.new(-7054.04, 336.3, 2918.79),
        CFrame.new(-7004.74, 336.3, 2922.36),
        CFrame.new(-6965.99, 336.3, 2918.46),
        CFrame.new(-6959.16, 336.3, 2922.38),
    }
    local an
    local loadEffects = function()
        if not an then
            local effectReplicator = noEffects.services.ReplicatedStorage:FindFirstChild('EffectReplicator')
            local requireOk, effectsModule = effectReplicator and pcall(require, effectReplicator)

            if requireOk then
                an = effectsModule
            end
        end
        if not an then
            return false
        end

        local callOk, carryingEffect = pcall(an.FindEffect, an, 'Carrying')

        if callOk and carryingEffect then
            return true
        end

        for effectIndex, effect in pairs(an.Effects or {})do
            if effect.Class == 'Carrying' or effect.Value == 'Carrying' then
                return true
            end
        end

        return false
    end
    local canContinue = function()
        local humanoid = noEffects.localPlayer.humanoid

        return aj:armed() and not aj.hopRequested and humanoid and humanoid.Health > 0
    end
    local hasNearbyPlayers = function(position)
        position = position or (noEffects.localPlayer.root_part and noEffects.localPlayer.root_part.Position)

        if not position then
            return false
        end

        for playerIndex, player in ipairs(noEffects.services.Players:GetPlayers())do
            if player ~= noEffects.localPlayer.instance and player.Character then
                local targetRoot = player.Character:FindFirstChild('HumanoidRootPart')

                if targetRoot and Vector3.new(position.X - targetRoot.Position.X, 0, position.Z - targetRoot.Position.Z).Magnitude <= 200 then
                    return true
                end
            end
        end

        return false
    end
    local switchServer = function()
        if aj.hopRequested or aj.reported or ak and ak() then
            return
        end

        aj.hopRequested = true
        aj.progress = 'Player or moderator nearby; switching servers'

        clickHolder.set(false)
        travelRecovery.stopAll()

        local localRoot = noEffects.localPlayer.root_part

        if localRoot then
            localRoot.AssemblyLinearVelocity = Vector3.zero
            localRoot.CFrame = CFrame.new(localRoot.Position.X, 2000, localRoot.Position.Z) * localRoot.CFrame.Rotation
        end

        noEffects.hop(noEffects.localPlayer.instance:GetAttribute('DataSlot'), true)
    end
    local travelTo = function(target, speed)
        speed = speed or 225

        local currentRoot = noEffects.localPlayer.root_part
        local distance = currentRoot and (currentRoot.Position - target.Position).Magnitude or 0
        local deadline = os.clock() + math.max(12, distance / speed * 3 + 5)
        local recovery = travelRecovery.new(target, true, speed)

        while canContinue() and not recovery.status() do
            if os.clock() > deadline then
                recovery.stop()

                return false
            end

            task.wait(0.1)
        end

        local status = recovery.status()

        if not status then
            recovery.stop()
        end

        return status == 'arrived'
    end
    local flyToPoint = function(targetPoint, heightOffset, travelSpeed)
        local travelRoot = noEffects.localPlayer.root_part

        if not travelRoot or not canContinue() then
            return false
        end

        local altitude = 2000

        travelRoot.AssemblyLinearVelocity = Vector3.zero
        travelRoot.CFrame = CFrame.new(travelRoot.Position.X, altitude, travelRoot.Position.Z) * travelRoot.CFrame.Rotation

        if not travelTo(CFrame.new(targetPoint.Position.X, altitude, targetPoint.Position.Z), travelSpeed) then
            return false
        end

        travelRoot = noEffects.localPlayer.root_part

        if not travelRoot or not canContinue() then
            return false
        end

        travelRoot.AssemblyLinearVelocity = Vector3.zero
        travelRoot.CFrame = CFrame.new(targetPoint.Position + Vector3.new(0, heightOffset or 0, 0)) * targetPoint.Rotation

        return true
    end
    local au = function(args)
        local requests = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
        local sendDialogue = requests and requests:FindFirstChild('SendDialogue')

        if not sendDialogue then
            return false
        end

        return pcall(delayedTask.method, sendDialogue, 'FireServer', args)
    end
    local awaitDialogue = function(waitForGui)
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local dialogueGui = playerGui and playerGui:FindFirstChild('DialogueGui')

        if not dialogueGui then
            return false
        end
        if waitForGui then
            local openDeadline = os.clock() + 6

            while canContinue() and not dialogueGui.Enabled and os.clock() < openDeadline do
                task.wait(0.1)
            end

            if not dialogueGui.Enabled then
                return false
            end
        end

        local closeDeadline = os.clock() + 8

        while canContinue() and dialogueGui.Enabled and os.clock() < closeDeadline do
            au({exit = true})
            task.wait(0.25)
        end

        return not dialogueGui.Enabled
    end
    local findMission = function()
        local terrain = workspace:FindFirstChild('Terrain')

        for terrainIndex, terrainPart in ipairs(terrain and terrain:GetDescendants() or {})do
            if terrainPart:IsA('Attachment') then
                local jobGui = terrainPart:FindFirstChild('JobTrackerGui')
                local textLabel = jobGui and jobGui:FindFirstChild('TextLabel')
                local labelText = textLabel and textLabel.Text:lower() or ''
                local missionTag = labelText:find('hostage', 1, true) and 'Hostage' or (labelText:find('secure', 1, true) or labelText:find('takeover', 1, true)) and 'Secure the Perimeter' or (labelText:find('armament', 1, true) or labelText:find('arnament', 1, true) or labelText:find('armanent', 1, true)) and 'Armament Sabotage'

                if missionTag then
                    return missionTag, terrainPart.WorldCFrame
                end
            end
        end
    end
    local hasReportPrompt = function()
        local gui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')

        if not gui then
            return false
        end

        for guiIndex, guiItem in ipairs(gui:GetDescendants())do
            if guiItem:IsA('TextLabel') and guiItem.Text:lower():find('report back to captain', 1, true) then
                return true
            end
        end

        return false
    end

    ak = function()
        local hud = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local hasReport = false

        for hudIndex, hudItem in ipairs(hud and hud:GetDescendants() or {})do
            if hudItem:IsA('TextLabel') then
                local itemText = hudItem.Text:lower()

                if itemText:find('great work', 1, true) or itemText:find('report back to captain', 1, true) then
                    hasReport = true

                    break
                end
            end
        end

        if aj.reported then
            if not hasReport then
                aj.reported = false
            end

            return false
        end
        if hasReport then
            aj.missionComplete = true
        end

        return aj.missionComplete == true
    end

    local findCaptain = function()
        local npcs = workspace:FindFirstChild('NPCs')
        local captain = npcs and npcs:FindFirstChild('Captain Trist')

        return captain and captain:FindFirstChild('InteractPrompt', true), captain and captain:FindFirstChild('HumanoidRootPart')
    end
    local approachCaptain = function(takingMission)
        aj.progress = takingMission and 'Taking Authority mission' or 'Reporting to Captain Trist'

        local prompt, tristRoot = findCaptain()
        local fightCframe = tristRoot and tristRoot.CFrame * CFrame.new(0, 0, -4) or startPosition

        if not flyToPoint(fightCframe) then
            return false
        end

        task.wait(0.75)

        local awaitPromptTimeout = os.clock() + 10

        while canContinue() and not prompt and os.clock() < awaitPromptTimeout do
            task.wait(0.25)

            prompt = findCaptain()
        end

        if not prompt then
            return false
        end

        local requestStore = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
        local interactPrompt = requestStore and requestStore:FindFirstChild('InteractPrompt')
        local firedOk = interactPrompt and pcall(delayedTask.method, interactPrompt, 'FireServer', prompt)

        if not firedOk then
            firedOk = pcall(delayedTask.call, executorInfo.fire, prompt)
        end
        if not firedOk then
            return false
        end

        task.wait(0.75)

        if takingMission then
            local aI = os.clock() + 8

            repeat
                au({
                    choice = 'Yes, Sir.',
                })

                local jobName = findMission()

                if jobName then
                    return true
                end

                task.wait(0.5)
            until not canContinue() or os.clock() > aI

            return false
        end

        return awaitDialogue(true)
    end
    local reportMission = function()
        local reported = approachCaptain(false)

        if reported then
            local reportTimeout = os.clock() + 5

            while canContinue() and hasReportPrompt() and os.clock() < reportTimeout do
                task.wait(0.1)
            end

            reported = not hasReportPrompt()
        end
        if reported then
            aj.missionComplete = false
            aj.reported = true
        else
            aj.progress = 'Retrying report to Captain Trist'
        end

        return reported
    end
    local rescueHostage = function(targetPosition)
        if ak() then
            return true
        end

        aj.progress = 'Rescuing Authority hostage'

        local live = workspace:FindFirstChild('Live')
        local hostageRoot
        local locations = {targetPosition}

        for locIndex, locItem in ipairs(am)do
            if (locItem.Position - targetPosition.Position).Magnitude < 1000 then
                locations[#locations + 1] = locItem
            end
        end

        while canContinue() and not hostageRoot do
            for locIndex2, locItem2 in ipairs(locations)do
                if ak() then
                    return true
                end
                if not canContinue() then
                    break
                end

                aj.progress = 'Loading Authority hostage location'

                if not flyToPoint(locItem2) then
