        repeat
            if ak() then
                return true
            end

            task.wait(0.2)
        until not canContinue() or os.clock() > finalTimeout

        return false
    end
    local sabotageCrates = function(player)
        if ak() then
            return true
        end

        aj.progress = 'Sabotaging Authority crates'

        if not flyToPoint(player, 200) then
            return false
        end

        local timeout = os.clock() + 240
        local idleSince

        while canContinue() and os.clock() < timeout do
            if ak() then
                clickHolder.set(false)

                return true
            end

            local destructibles = workspace:FindFirstChild('Destructibles')
            local targetCrate, closestDist

            for index, crate in ipairs(destructibles and destructibles:GetChildren() or {})do
                if crate:IsA('Model') and crate.Name:find('KhanCrate', 1, true) and (tonumber(crate:GetAttribute('StructureHealth')) or 0) > 0 then
                    local distance = (crate:GetPivot().Position - player.Position).Magnitude

                    if distance < 1200 and (not closestDist or distance < closestDist) then
                        targetCrate, closestDist = crate, distance
                    end
                end
            end

            if targetCrate then
                idleSince = nil

                local character = noEffects.localPlayer.character
                local characterHandler = character and character:FindFirstChild('CharacterHandler')
                local requests = characterHandler and characterHandler:FindFirstChild('Requests')
                local drawWeapon = requests and requests:FindFirstChild('DrawWeapon')

                if drawWeapon then
                    pcall(delayedTask.method, drawWeapon, 'FireServer', true)
