            if ak() then
                return true
            end

            for i, child in ipairs(workspace:GetChildren())do
                if child:IsA('Model') and child.Name == 'Authority Checkpoint' and (child:GetPivot().Position - controller.Position).Magnitude < 1200 then
                    checkpoint = child

