            if not missionName then
                aj.progress = 'Waiting for Authority mission to appear'

                task.wait(2)

                continue
            end

            local selectedMissions = noEffects.value('auto_authority_selected', {
                Hostage = true,
                ['Armament Sabotage'] = true,
                ['Secure the Perimeter'] = true,
            })

            if selectedMissions[missionName] ~= true then
                if aj.reported or ak() then
                    task.wait(0.2)

                    continue
                end

                aj.progress = 'Finding another Authority mission server'

                local hopRoot = noEffects.localPlayer.root_part

                if hopRoot then
                    hopRoot.AssemblyLinearVelocity = Vector3.zero
                    hopRoot.CFrame = CFrame.new(hopRoot.Position.X, 2000, hopRoot.Position.Z) * hopRoot.CFrame.Rotation
                end

