            executionQueue.cancel(ax, 'travel could not start')

            return false
        end
        if not vault and region ~= 'Etrean' and not placeIds.isEastern() and not regionTransfer.toEastern(nil, function(
        )
            return isArmed(currentGeneration)
        end) then
            executionQueue.cancel(ax, 'travel could not start')

            return false
        end

        local localRoot = bo()

        if not localRoot or not isArmed(currentGeneration) then
            executionQueue.cancel(ax, 'travel could not start')

            return false
        end

        ax.travelFeatures = {
            Flight = noEffects.featureActive('Flight'),
            NoClip = noEffects.featureActive('NoClip'),
            NoFallDamage = noEffects.featureActive('NoFallDamage'),
        }

        for featureName in pairs(ax.travelFeatures)do
            noEffects.enableFeature(featureName)
        end

        noEffects.automation.movement = ax

        local success = true
        local shouldHop = false

        if vault then
            if noEffects.localPlayer.humanoid then
                noEffects.localPlayer.humanoid:UnequipTools()
            end

            localRoot.AssemblyLinearVelocity = Vector3.zero
            localRoot.CFrame = CFrame.new(localRoot.Position.X, -1050, localRoot.Position.Z)
            success = travelRecovery.new(CFrame.new(destination.Position.X, -1050, destination.Position.Z), true, 180).wait(math.huge)

            if success then
                success = travelRecovery.new(destination, true, 180).wait(math.huge)
            end
            if success and isArmed(currentGeneration) then
                localRoot.AssemblyLinearVelocity = Vector3.zero
                localRoot.CFrame = destination

                task.wait(0.5)
            end
        else
            local by

            success, by = travelAction.run(destination, {
                speed = 180,
                force = noEffects.automation.forceSkyAfterFortitude,
                alive = function()
                    return isArmed(currentGeneration)
                end,
                status = function(status)
                    ax.progress = tostring(label) .. ' \u{b7} ' .. status
                end,
            })

            if success then
                noEffects.automation.forceSkyAfterFortitude = nil
            elseif isArmed(currentGeneration) and by then
                ax.progress = 'Travel interrupted: ' .. by

                if by:find('server', 1, true) then
                    shouldHop = true
                    ax.hopRequested = true
                end
            end
        end

        ax:stopTravel()

        if shouldHop and ax.generation == currentGeneration and ax:armed() then
            ax.progress = 'Switching servers after travel rejection'

            noEffects.hop(getSession().slot, true)
        end

        return success
    end
    local br = function(guiObject)
        while guiObject do
            if guiObject:IsA('GuiObject') and not guiObject.Visible or guiObject:IsA('ScreenGui') and not guiObject.Enabled then
                return false
            end

            guiObject = guiObject.Parent
        end

        return true
    end
    local bs = function(query)
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local dialogueGui = playerGui and playerGui:FindFirstChild('DialogueGui')

        if not dialogueGui or not br(dialogueGui) then
            return
        end
        if query == 'shrine of chance' then
            local dialogueExtents = dialogueGui:FindFirstChild('DialogueExtents')

            dialogueExtents = dialogueExtents and dialogueExtents:FindFirstChild('ShopFrame')
            dialogueExtents = dialogueExtents and dialogueExtents:FindFirstChild('Category_Shrine of Chance')

            if dialogueExtents and br(dialogueExtents) then
                return dialogueGui
            end

            for index, descendant in ipairs(dialogueGui:GetDescendants())do
                if (descendant:IsA('TextLabel') or descendant:IsA('TextButton')) and br(descendant) and (descendant.Text == 'Talent Exchange' or descendant.Text == 'Talent Degradation' or descendant.Text == 'Talent Elevation') then
                    return dialogueGui
                end
            end

            return
        end

        for listIndex, child in ipairs(dialogueGui:GetDescendants())do
            if (child:IsA('TextLabel') or child:IsA('TextButton')) and br(child) and child.Text:lower():find(query, 1, true) then
                return dialogueGui
            end
        end
    end
    local bt = function()
        local generation = ax.generation

        if not isArmed(generation) then
            return false
        end
        if not bs('shrine of chance') then
            return true
        end

        delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})

        local deadline = os.clock() + 3

        repeat
            task.wait(0.1)

            if not isArmed(generation) then
                return false
            end
            if not bs('shrine of chance') then
                showProgress('Waiting for Shrine of Chance to settle', 2)

                return isArmed(generation)
            end
        until os.clock() >= deadline

        return false
    end
