                if connection.Enabled then
                    delayedTask.call(function()
                        connection:Fire()
                    end)

                    return true
                end
            end
        end

        if firesignal then
            return pcall(delayedTask.call, firesignal, button.MouseButton1Click, button)
        end

        return false
    end
