    local bA = function(weaponName)
        local normalized = sanitizeString(weaponName)

        return by[normalized] or weaponName
    end
    local bB = function(itemName, weaponType, targetWeapon)
        local targetHash = bA(targetWeapon)
        local expectedHash = bz[sanitizeString(itemName)]

        if expectedHash then
            return expectedHash == targetHash
        end
        if type(weaponType) ~= 'string' then
            return false
        end

        for segment in weaponType:gmatch('[^/]+')do
            if bA(segment) == targetHash then
                return true
            end
        end

        return false
    end
