    local bE = function(toolName)
        for index, container in ipairs({
            getBackpack(),
            noEffects.localPlayer.character,
        })do
            if container then
                for childIndex, child in ipairs(container:GetChildren())do
                    if child:IsA('Tool') and (child:GetAttribute('ItemName') == toolName or child.Name == toolName) then
                        return child
                    end
                end
            end
        end
    end
    local bF = function(options, weaponSpec)
        for containerIndex, parent in ipairs({
            getBackpack(),
            noEffects.localPlayer.character,
        })do
            if parent then
                for toolIndex, candidateTool in ipairs(parent:GetChildren())do
                    if candidateTool:IsA('Tool') then
                        local rawName = candidateTool:GetAttribute('ItemName') or candidateTool.Name:match('^(.-)%$') or candidateTool.Name
                        local meta = options.weaponMetadata and options.weaponMetadata[sanitizeString(rawName)]
                        local metaType = meta and meta.type

                        if bB(rawName, metaType, weaponSpec) then
                            return candidateTool
                        end
                    end
                end
            end
        end
    end
    local bG = function(loadout, weaponKey)
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local backpackGui = playerGui and playerGui:FindFirstChild('BackpackGui')
        local equipFrame = backpackGui and backpackGui:FindFirstChild('EquipFrame', true)

        if not equipFrame then
            return false
        end

        for slotIndex, slot in ipairs({
            'Weapon',
            'Offhand',
        })do
            local slotFrame = equipFrame:FindFirstChild(slot)

            if slotFrame and slotFrame:GetAttribute('Equipped') == true then
                local displayName = slotFrame:GetAttribute('DisplayName')
                local spec = bx[weaponKey]

                if displayName and spec and displayName == spec.item then
                    return true
                end

                local weaponMeta = displayName and loadout.weaponMetadata and loadout.weaponMetadata[sanitizeString(displayName)]
                local typeName = weaponMeta and weaponMeta.type

                if displayName and bB(displayName, typeName, weaponKey) then
                    return true
                end
            end
        end

        return false
    end
    local bH = function(tool, weaponName)
        if not tool or not tool.Parent or not noEffects.localPlayer.humanoid then
            return false
        end
        if tool.Parent ~= noEffects.localPlayer.character then
            delayedTask.method(noEffects.localPlayer.humanoid, 'EquipTool', tool)

            local equipTimeout = os.clock() + 2

            repeat
                task.wait(0.05)
            until tool.Parent == noEffects.localPlayer.character or not tool.Parent or os.clock() >= equipTimeout
        end
        if not tool.Parent then
            return false
        end

        local quickSwap = tool:FindFirstChild('QuickSwap')

        if quickSwap and quickSwap:IsA('RemoteEvent') then
            delayedTask.method(quickSwap, 'FireServer')

            local swapTimeout = os.clock() + 3

            repeat
                task.wait(0.1)
            until bG(ax.build, weaponName) or os.clock() >= swapTimeout or not isArmed(ax.generation)

            return bG(ax.build, weaponName)
        end

        return bG(ax.build, weaponName)
    end
    local bI = function(config, sourceKey)
        local lootSource = bD[sourceKey]

        if not lootSource then
            return false, 'source-unavailable'
        end
        if lootSource.depths and not placeIds.isDepths() then
            return false, 'depths-required'
        end
        if lootSource.position and not bq(lootSource.position, 'Searching for ' .. lootSource.item, lootSource.depths, lootSource.region) then
            return false, 'travel-failed'
        end

        local myPos = bo()
        local thrownContainer = workspace:FindFirstChild('Thrown')
        local bestChest, nearestPlayerDist, myLidDist

        for j, chest in ipairs(thrownContainer and thrownContainer:GetChildren() or {})do
            local lid = chest:FindFirstChild('Lid')
            local prompt = chest:FindFirstChildWhichIsA('ProximityPrompt', true)

            if lid and prompt and not chest:HasTag('looted') then
                local nearestDist = math.huge

                for o, player in ipairs(noEffects.services.Players:GetPlayers())do
                    local root = player ~= noEffects.localPlayer.instance and player.Character and player.Character:FindFirstChild('HumanoidRootPart')

                    if root then
                        nearestDist = math.min(nearestDist, (root.Position - lid.Position).Magnitude)
                    end
                end

                local myLidDistance = myPos and (myPos.Position - lid.Position).Magnitude or math.huge

                if not bestChest or nearestDist > nearestPlayerDist or nearestDist == nearestPlayerDist and myLidDistance < myLidDist then
                    bestChest, nearestPlayerDist, myLidDist = chest, nearestDist, myLidDistance
                end
            end
        end

        if not bestChest then
            return false, 'chest-missing'
        end

        local bestLid = bestChest:FindFirstChild('Lid')
        local bestPrompt = bestChest:FindFirstChildWhichIsA('ProximityPrompt', true)

        if not bestLid or not bestPrompt or not bq(bestLid.CFrame, 'Opening chest for ' .. lootSource.item, lootSource.depths, lootSource.region) then
            return false, 'chest-unavailable'
        end

        pcall(delayedTask.call, fire, bestPrompt)

        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local deadline = os.clock() + 8

        repeat
            task.wait(0.1)
        until playerGui and playerGui:FindFirstChild('ChoicePrompt') or os.clock() >= deadline or not isArmed(ax.generation)

        if not playerGui or not playerGui:FindFirstChild('ChoicePrompt') then
            return false, 'chest-timeout'
        end

        itemFilters.fromPrompt({
            lootSource.item,
        }, function()
            return isArmed(ax.generation)
        end, false, {
            exact = true,
            strict = false,
            rarities = {},
            timeout = 20,
        })
        bestChest:AddTag('looted')

        local result = bF(config, sourceKey) or bE(lootSource.item)

        if result then
            bH(result, sourceKey)
        end

        return result ~= nil, result and 'acquired' or 'not-found'
    end
    local bJ = function(weaponConfig, talents, d, e)
        local weaponTypes, seenWeaponTypes = {}, {}

        for talent in pairs(talents)do
            local talentMeta = weaponConfig.metadata[talent]
            local weaponType = talentMeta and talentMeta.requirements and talentMeta.requirements.weaponType

            if type(weaponType) == 'string' and weaponType ~= '' and talentPicker.eligible(d, talentMeta, e, weaponConfig.metadata) then
                for typeName in weaponType:gmatch('[^,/]+')do
                    typeName = bA(typeName:match('^%s*(.-)%s*$'))

                    if typeName ~= '' and not seenWeaponTypes[typeName] then
                        seenWeaponTypes[typeName] = true
                        weaponTypes[#weaponTypes + 1] = typeName
                    end
                end
            end
        end

        if #weaponTypes == 0 then
            return false
        end

        table.sort(weaponTypes, function(left, right)
            local ranks = {
                ['Light Weapon'] = 1,
                ['Medium Weapon'] = 2,
                ['Heavy Weapon'] = 3,
            }
            local leftRank, rightRank = ranks[left] or 4, ranks[right] or 4

            return leftRank == rightRank and left < right or leftRank < rightRank
        end)

        for h, weapon in ipairs(weaponTypes)do
            if bG(weaponConfig, weapon) then
                return false
            end
        end
        for h, itemName in ipairs(weaponTypes)do
