        end
        if equippedItem and not bH(equippedItem, fallbackWeapon) then
            showProgress('Could not equip ' .. fallbackSource.item, 2)
        end
        if not equippedItem then
            showProgress('Could not buy ' .. fallbackSource.item .. ' - waiting before retry', 6)
        end

        return true
    end
    local c = function(gui)
        if gui:IsA('TextButton') or gui:IsA('TextLabel') then
            if gui.Text ~= '' then
                return gui.Text
            end
        end

        local textLabel = gui:FindFirstChildWhichIsA('TextLabel', true)

        return textLabel and textLabel.Text or ''
    end
    local d = function(element)
        return c(element):gsub('^%s*%d+%.%s*', ''):match('^%s*(.-)%s*$')
    end
    local e = function()
        local window = bw()
        local choices = {}
        local isInChoiceScroll = function(widget)
            local parent = widget.Parent

            while parent and parent ~= window do
                if parent.Name == 'ChoiceScroll' then
                    return true
                end

                parent = parent.Parent
            end

            return false
        end

        for descendantIndex, descendant in ipairs(window and window:GetDescendants() or {})do
            local text = descendant:IsA('GuiButton') and br(descendant) and d(descendant)

            if text and text ~= '' and isInChoiceScroll(descendant) then
                choices[#choices + 1] = {
                    button = descendant,
                    text = text,
                }
            end
        end

        table.sort(choices, function(left, right)
            if left.button.AbsolutePosition.Y == right.button.AbsolutePosition.Y then
                return left.button.AbsolutePosition.X < right.button.AbsolutePosition.X
            end

            return left.button.AbsolutePosition.Y < right.button.AbsolutePosition.Y
        end)

        return choices
    end
    local f = function(targetText)
        local options = e()

        if targetText then
            local normalized = sanitizeString(targetText)

            for choiceIndex, choice in ipairs(options)do
                if sanitizeString(choice.text) == normalized then
                    return choice
                end
            end

            return nil
        end

        return options[1]
    end
    local g = function()
        local texts = {}

        for optionIndex, option in ipairs(e())do
            texts[#texts + 1] = option.text
        end

        return table.concat(texts, '|')
    end
    local h = function(prompt)
        if not prompt or not prompt.Parent then
            return false
        end
        if prompt:IsA('ProximityPrompt') and pcall(delayedTask.call, fire, prompt) then
            return true
        end

        local requests = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')

        requests = requests and requests:FindFirstChild('InteractPrompt')

        return requests and pcall(function()
            delayedTask.method(requests, 'FireServer', prompt)
        end) or false
    end
    local j = function(npcName)
        local npcs = workspace:FindFirstChild('NPCs')
        local npcInstance = npcs and npcs:FindFirstChild(npcName)

        return npcInstance and (npcInstance:FindFirstChild('InteractPrompt', true) or npcInstance:FindFirstChildWhichIsA('ProximityPrompt', true))
    end
    local interactWithNpc = function(npc)
        local generation = ax.generation

        for attempt = 1, 3 do
            if bw() then
                return true
            end
            if not isArmed(generation) or not h(npc) then
                return false
            end

            local timeout = os.clock() + 4

            repeat
                task.wait(0.1)
            until bw() or os.clock() >= timeout or not isArmed(generation)
        end

        return bw() ~= nil
    end
    local sendDialogueSequence = function(dialogueOptions, duration)
        local currentGeneration = ax.generation
        local remote = noEffects.services.ReplicatedStorage.Requests.SendDialogue
        local index = 1
        local deadline = os.clock() + (duration or 60)

        while isArmed(currentGeneration) and bw() and os.clock() < deadline do
            local selected = index <= #dialogueOptions and f(dialogueOptions[index]) or f('[End Dialogue]')

            if selected then
                local signature = g()
                local isEnd = selected.text:find('[End Dialogue]', 1, true) ~= nil

                if isEnd then
                    delayedTask.method(remote, 'FireServer', {exit = true})
                else
                    delayedTask.method(remote, 'FireServer', {
                        choice = selected.text,
                    })
                end

                local waitTimeout = os.clock() + 3

                repeat
                    task.wait(0.1)
                until not bw() or g() ~= signature or os.clock() >= waitTimeout or not isArmed(currentGeneration)

                if bw() and g() == signature then
                    bv(selected.button)

                    local clickTimeout = os.clock() + 2

                    repeat
                        task.wait(0.1)
                    until not bw() or g() ~= signature or os.clock() >= clickTimeout or not isArmed(currentGeneration)
                end
                if not isEnd and (not bw() or g() ~= signature) then
                    index = index + 1
                end
            else
                task.wait(0.1)
            end
        end

        return isArmed(currentGeneration) and not ax.depthsHealing and index > #dialogueOptions and not bw()
    end
    local selectDialogueOption = function(selectDialogue)
        local generation = ax.generation
        local dialogue = f(selectDialogue)

        if not dialogue then
            return false
        end

        local promptId = g()

        delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {
            choice = dialogue.text,
        })

        local deadline = os.clock() + 3

        repeat
            task.wait(0.1)
        until not bw() or g() ~= promptId or os.clock() >= deadline or not isArmed(generation)

        if isArmed(generation) and bw() and g() == promptId then
            bv(dialogue.button)

            deadline = os.clock() + 2

            repeat
                task.wait(0.1)
            until not bw() or g() ~= promptId or os.clock() >= deadline or not isArmed(generation)
        end

        return isArmed(generation) and (not bw() or g() ~= promptId)
    end
    local hasBreakthroughTalent = function(hasTalent)
        local talents = hasTalent.wantedTalents or hasTalent.talents or {}

        return talents.breakthroughdrive or talents.bustercall or talents.officersslash
    end
    local hasOtherCombatTalent = function(hasOtherTalent)
        local talents = hasOtherTalent.wantedTalents or hasOtherTalent.talents or {}

        return talents.backstabber or talents.executionersfrenzy or talents.fatalstealth or talents.flankingmaneuvers or talents.staturebreak or talents.tacetminimization
    end
    local hasThirdCombatTalent = function(hasThirdTalent)
        local talents = hasThirdTalent.wantedTalents or hasThirdTalent.talents or {}

        return talents.absoluteforce or talents.ampoverdrive or talents.martialbrutality or talents.shockingreverb
    end
    local getAttributeValue = function(getAttribute)
        local instance = noEffects.localPlayer.instance
        local character = noEffects.localPlayer.character

        return instance:GetAttribute(getAttribute) or character and character:GetAttribute(getAttribute)
    end
    local getAutomationHandler = function(getHandler)
        local saveData = getSession()
        local rankName = getAttributeValue('FactionRankName')

        if rankName == 'Seneschal' or rankName == 'Handler' or rankName == 'Operator' then
            return 'auto_ferryman'
        end
        if getAttributeValue('Faction') == 'Authority' and not placeIds.isDungeon() and (saveData.trialComplete or (talentPicker.power(getHandler) or 0) > 1) then
            return 'auto_authority_missions'
        end

        return 'auto_ferryman'
    end
    local shouldJoinAuthorityCommand = function()
        local generation = ax.generation

        if getAttributeValue('FactionRankDivision') == 'Leadership' then
            return true
        end
        if not handleAutomationChild(nil) then
            return false
        end

        ax.progress = 'Joining Authority Command division'

        local npcs = workspace:FindFirstChild('NPCs')

        npcs = npcs and npcs:FindFirstChild('WardenJericho')

        local root = npcs and npcs:FindFirstChild('HumanoidRootPart')

        if not root or not bq(root.CFrame * CFrame.new(0, 0, -4), 'Joining Authority Command division', false, 'Eastern') then
            return false
        end

        local playerRoot = bo()

        if not playerRoot or (playerRoot.Position - root.Position).Magnitude > 25 then
            return false
        end

        local prompt = npcs:FindFirstChild('InteractPrompt', true)

        if not prompt or not interactWithNpc(prompt) then
            return false
        end
        if not f('Yes, Warden.') then
            return false
        end
        if not selectDialogueOption('Yes, Warden.') then
            return false
        end

        local deadline = os.clock() + 8

        while isArmed(generation) and os.clock() < deadline do
            if getAttributeValue('FactionRankDivision') == 'Leadership' then
                if f('[End Dialogue]') then
                    delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {
                        choice = '[End Dialogue]',
                    })
                end

                return true
            end
            if f('[End Dialogue]') then
                delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {
                    choice = '[End Dialogue]',
                })
            end

            task.wait(0.2)
        end

        return getAttributeValue('FactionRankDivision') == 'Leadership'
    end
