    local isOathlessCharacter = function()
        local oathlessData = waitForTalentData()

        return oathlessData and sanitizeString(oathlessData.Oath) == 'oathless'
    end
    local chooseDialogueOption = function(option)
        return f(option) and selectDialogueOption(option)
    end
    local handleCeruleanDialogue = function(metDisciples)
        local cerulean = j('Cerulean')

        if not cerulean then
            return false
        end
        if not interactWithNpc(cerulean) then
            return isOathlessCharacter()
        end

        local lines = metDisciples and {
            "I've met the three disciples.",
            'I understand.',
            'I vow to walk my own path.',
        } or {
            'I walk my own path.',
            'I will stay on my own path.',
            'The path of an Oathless intrigues me.',
        }
        local done = true

        if not metDisciples and f("I've met the three disciples.") then
            lines = {
                "I've met the three disciples.",
                'I understand.',
                'I vow to walk my own path.',
            }
        end

        for index, dialogue in ipairs(lines)do
            if isOathlessCharacter() then
                break
            end
            if not chooseDialogueOption(dialogue) then
                done = false

                break
            end
        end

        if done and not isOathlessCharacter() and f('Where can I find the disciples?') then
            done = chooseDialogueOption('Where can I find the disciples?')
        end

        pcall(delayedTask.method, noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})

        return done or isOathlessCharacter()
    end
    local resetOathlessState = function(proceed, character)
        local state = getSession()

        if isOathlessCharacter() then
            state.activeTask = nil
            state.oathlessStage = nil

            setSession(state)

            return true
        end
        if character.Oath and character.Oath ~= '' then
            handleProgress(
"Selected build needs Oathless, but this character has another oath")

            return false
        end
        if not handleAutomationChild(nil) then
            return false
        end

        local stage = tonumber(state.oathlessStage) or 1
        local location = aY[stage] or aY[1]

        state.activeTask = 'oathless'

        setSession(state)

        ax.oathlessRetryAt = os.clock() + 10
        ax.progress = 'Oathless: travelling to ' .. location.name

        if not bq(location.position, ax.progress, false, 'Eastern') or not isArmed(proceed) then
            return false
        end
        if stage == 1 or stage >= 5 then
            ax.progress = 'Oathless: talking to Cerulean'

            if not handleCeruleanDialogue(stage >= 5) then
                if stage >= 5 then
                    state.oathlessStage = 1

                    setSession(state)
                end

                return false
            end
        else
            local npc = j(location.name)

            if not npc then
                return false
            end

            ax.progress = 'Oathless: interacting with ' .. location.name

            if not h(npc) then
                return false
            end

            task.wait(0.5)
        end
        if not isArmed(proceed) then
            return false
        end
        if isOathlessCharacter() then
            state.activeTask = nil
            state.oathlessStage = nil
        else
            state.oathlessStage = stage + 1
        end

        setSession(state)

        return isOathlessCharacter()
    end
    local runShrineOfTemptation = function(taskConfig, character)
        handleAutomationChild(nil)

        if not bq(waypoint16, false, false, 'Etrean') then
            return false, 'Could not reach Shrine of Temptation'
        end

        local shrinePrompt = j('Shrine of Temptation')

        if not shrinePrompt or not interactWithNpc(shrinePrompt) then
            return false, 'Could not open Shrine of Temptation dialogue'
        end
        if not selectDialogueOption('I wish to engage in a deal.') or not selectDialogueOption('I agree.') then
            return false, 'Shrine of Temptation dialogue changed'
        end

        local ownedMantras = talentPicker.owned(character, 'Mantras')
        local wantedMantras = taskConfig.wantedMantras or taskConfig.mantras
        local offerMantra

        for index, mantraItem in ipairs(e())do
            local mantraName = sanitizeString(mantraItem.text)

            if ownedMantras[mantraName] and not wantedMantras[mantraName] then
                offerMantra = mantraItem.text

                break
            end
        end

        if not offerMantra then
            delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})

            return false, 'No unneeded mantra to offer at Shrine of Temptation'
        end
        if not selectDialogueOption(offerMantra) then
            return false, 'Could not confirm offered mantra'
        end

        local deadline = os.clock() + 8
        local generation = ax.generation
        local dialogueEnded = false

        repeat
            task.wait(0.2)

            if not dialogueEnded and f('[End Dialogue]') then
                dialogueEnded = true

                if not selectDialogueOption('[End Dialogue]') then
                    return false, 'Shrine of Temptation dialogue did not close'
                end
            end

            local picker = waitForTalentData()
            local choice = picker and talentPicker.choice(picker)

            if choice and choice.Selection and #choice.Selection > 0 and not talentPicker.owned(picker, 'Mantras')[sanitizeString(offerMantra)] and not bw() then
                return true
            end
        until os.clock() >= deadline or not isArmed(generation)

        return false, 'Shrine of Temptation mantra hand was not confirmed'
    end
    local findUnifyTalentPrompt = function()
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')
        local descSheet = choicePrompt and choicePrompt:FindFirstChild('DescSheet', true)
        local prompt = descSheet and descSheet:FindFirstChild('Prompt')
        local scrollingFrame = descSheet and descSheet:FindFirstChild('ScrollingFrame')
        local talentChoice = choicePrompt and choicePrompt:FindFirstChild('TalentChoice')

        if choicePrompt and choicePrompt.Enabled and prompt and prompt.Text:find('Talent to Unify', 1, true) and scrollingFrame and talentChoice then
            return choicePrompt, scrollingFrame, talentChoice
        end
    end
    local collectTalentOffers = function(talentConfig)
        local promptFrame, talentScrollingFrame = findUnifyTalentPrompt()

        if not talentScrollingFrame then
            return nil
        end

        local wantedTalents = talentConfig.wantedTalents or talentConfig.talents
        local talentOffers = {}

        for buttonIndex, talentButton in ipairs(talentScrollingFrame:GetChildren())do
            if talentButton:IsA('TextButton') and talentButton.Visible and not wantedTalents[sanitizeString(talentButton.Name)] then
                talentOffers[#talentOffers + 1] = talentButton.Name
            end
        end

        table.sort(talentOffers)

        return talentOffers[1]
    end
    local handleUnificationOutput = function(unificationConfig)
        local state = getSession()
        local pickerGui = waitForTalentData()
        local selectedChoice = pickerGui and talentPicker.choice(pickerGui)

        if selectedChoice and selectedChoice.Type == 'Whisper' then
            state.activeTask = nil
            state.unificationStage = nil

            setSession(state)

            return true
        end
        if state.activeTask ~= 'unification' then
            state.activeTask = 'unification'
            state.unificationStage = 'opening'

            setSession(state)
        end

        handleAutomationChild(nil)

        if not findUnifyTalentPrompt() then
            if not bq(waypoint17, false, false, 'Eastern') then
                return false, 'Could not reach Shrine of Unification'
            end

            local unificationShrinePrompt = j('Shrine of Unification')

            if not unificationShrinePrompt or not interactWithNpc(unificationShrinePrompt) then
                return false, 'Could not open Shrine of Unification dialogue'
            end
            if not selectDialogueOption('I wish to engage in a deal.') or not selectDialogueOption('I agree.') then
                return false, 'Shrine of Unification dialogue changed'
            end

            local openingDeadline = os.clock() + 8

            repeat
                task.wait(0.1)
            until findUnifyTalentPrompt() or os.clock() >= openingDeadline or not isArmed(ax.generation)
        end
        if not findUnifyTalentPrompt() then
            return false, 'Shrine of Unification talent selection did not open'
        end

        for attempt = 1, 2 do
            local activePrompt, activeScrollingFrame, offerTalentChoice = findUnifyTalentPrompt()

            if not activePrompt then
                break
            end

            local talentName = collectTalentOffers(unificationConfig)

            if not talentName then
                return false, 'No safe talent to offer at Shrine of Unification'
            end

            local currentPrompt = activePrompt
            local promptText = activePrompt:FindFirstChild('Prompt', true)

            promptText = promptText and promptText.Text

            local invoked, response = pcall(delayedTask.method, offerTalentChoice, 'InvokeServer', talentName)

            if not invoked or not response then
                return false, 'Shrine of Unification rejected ' .. talentName
            end

            local offerDeadline = os.clock() + 8

            repeat
                task.wait(0.2)
            until not currentPrompt.Parent or not currentPrompt.Enabled or findUnifyTalentPrompt() ~= currentPrompt or (currentPrompt:FindFirstChild('Prompt', true) and currentPrompt:FindFirstChild('Prompt', true).Text ~= promptText) or not activeScrollingFrame:FindFirstChild(talentName) or os.clock() >= offerDeadline or not isArmed(ax.generation)

            state = getSession()
            state.unificationStage = 'offered'

            setSession(state)

            if findUnifyTalentPrompt() == currentPrompt and currentPrompt:FindFirstChild('Prompt', true) and currentPrompt:FindFirstChild('Prompt', true).Text == promptText and activeScrollingFrame:FindFirstChild(talentName) then
                return false, 'Shrine of Unification did not advance after ' .. talentName
            end
            if not findUnifyTalentPrompt() then
                break
            end
        end

        local confirmDeadline = os.clock() + 8

        repeat
            local confirmPicker = waitForTalentData()
            local whisperChoice = confirmPicker and talentPicker.choice(confirmPicker)

            if whisperChoice and whisperChoice.Type == 'Whisper' then
                state = getSession()
                state.activeTask = nil
                state.unificationStage = nil

                setSession(state)

                return true
            end

            task.wait(0.2)
        until os.clock() >= confirmDeadline or not isArmed(ax.generation)

        return false, 'Shrine of Unification Whisper hand was not confirmed'
    end
    local findMinistryReport = function()
        local character = noEffects.localPlayer.character
        local otherCharacter = getBackpack()

        return character and character:FindFirstChild('MinistryReport') or otherCharacter and otherCharacter:FindFirstChild('MinistryReport')
    end
    local tryStartMinistryQuest = function(stats)
        local questData = getSession()

        if questData.ministryReportQuest == 'complete' then
            return true
        end
        if (talentPicker.power(stats) or 0) < 20 then
            return false
        end

        handleAutomationChild(nil)
        progressionTraining.restorePassive()
        talentPicker.cancelSpend()
        talentPicker.cancelFavour()

        local report = findMinistryReport()

        if questData.ministryReportQuest == 'verify' then
            talentPicker.resetData()

            local talentData = waitForTalentData()

            if not report and talentData and (tonumber(talentData.TalentPointsTotal) or 0) > (tonumber(questData.ministryReportPoints) or 0) then
                questData.ministryReportQuest = 'complete'
                questData.ministryReportPoints = nil
                questData.ministryReportTurnInAt = nil

                setSession(questData)
                showProgress('Ministry report quest complete', 1)

                return true
            end
            if os.time() - (tonumber(questData.ministryReportTurnInAt) or 0) < 8 then
                showProgress('Verifying Ministry report reward', 1)

                return false
            end

            handleProgress('Ministry report reward needs verification')

            return false
        end
        if not report then
            ax.progress = 'Travelling to Ministry field report'

            if not bq(waypoint9, 'Ministry field report', false, 'Etrean') then
                return false
            end

            local bookNpc = j('MinistryBookNPC')

            if not bookNpc or not interactWithNpc(bookNpc) then
                showProgress('Waiting for Ministry field report', 2)

                return false
            end
            if not sendDialogueSequence({
                '[Inspect]',
                '[Take]',
            }, 15) then
                showProgress('Retrying Ministry field report', 2)

                return false
            end
            if not findMinistryReport() then
                showProgress('Waiting for MinistryReport', 2)

                return false
            end

            questData = getSession()
            questData.ministryReportQuest = 'report'

            setSession(questData)
        end

        ax.progress = 'Taking MinistryReport to Elykris'

        if not bq(waypoint10, 'Elykris', false, 'Etrean') then
            return false
        end

        local elykris = j('Elykris')

        if not elykris or not interactWithNpc(elykris) then
            showProgress('Waiting for Elykris', 2)

            return false
        end

        local talentSource = waitForTalentData()

        questData = getSession()
        questData.ministryReportPoints = tonumber(talentSource and talentSource.TalentPointsTotal) or 0
        questData.ministryReportQuest = 'verify'
        questData.ministryReportTurnInAt = os.time()

        setSession(questData)
        sendDialogueSequence({
            'What are you talking about?',
            'Tell me more about the nest.',
