    local stopFortitudeTraining = function(character)
        handleAutomationChild(nil)
        talentPicker.cancelSpend()
        talentPicker.cancelFavour()
        progressionTraining.restorePassive()

        ax.trainingStat = nil
        ax.trainingBusy = nil

        local state = getSession()

        if getOwnedTalents(character).fortitudeunbounded then
            resetUnboundFortitude(state)
            showProgress('Fortitude unbound complete', 1)

            return true
        end
        if state.activeTask ~= 'unbound_fortitude' then
            state.activeTask = 'unbound_fortitude'
            state.unboundFortitudeStage = 'talk'
            state.unboundFortitudeAttempts = 0
            state.unboundFortitudeTalkAt = nil
            state.ferrymanCycle = nil

            setSession(state)
        end

        ax.progress = 'Travelling to Brutus for Fortitude unbound'

        if not bq(waypoint7, 'Brutus', false, 'Eastern') then
            showProgress('Retrying travel to Brutus', 2)

            return true
        end

        local brutus = j('Brutus')

        if not brutus then
            showProgress('Waiting for Brutus', 2)

            return true
        end

        ax.progress = 'Talking to Brutus for Fortitude unbound'

        local generation = ax.generation
        local deadline = os.clock() + 30
        local nextRetryAt = 0

        while isArmed(generation) and os.clock() < deadline do
            if os.clock() >= nextRetryAt then
                talentPicker.resetData()

                local statData = waitForTalentData()

                if statData and getOwnedTalents(statData).fortitudeunbounded then
                    resetUnboundFortitude(getSession())
                    showProgress('Fortitude unbound complete', 1)

                    return true
                end

                nextRetryAt = os.clock() + 1
            end
            if bw() then
                pcall(delayedTask.method, noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})
            end

            pcall(h, brutus)
            task.wait(0.1)
        end

        showProgress('Retrying Brutus dialogue', 0.1)

        return true
    end
