    local clickButton = function(widget)
        local buttonData = f(widget)

        if not buttonData or not buttonData.button then
            return false
        end

        local button = buttonData.button
        local clickPosition = button.AbsolutePosition + button.AbsoluteSize / 2 + game:GetService('GuiService'):GetGuiInset()
        local inputManager = game:GetService('VirtualInputManager')

        return pcall(function()
            inputManager:SendMouseButtonEvent(clickPosition.X, clickPosition.Y, 0, true, game, 0)
            task.wait(0.08)
            inputManager:SendMouseButtonEvent(clickPosition.X, clickPosition.Y, 0, false, game, 0)
        end)
    end
    local findNearbyPurpFlame = function(position)
        local map = workspace:FindFirstChild('Map')
        local erisia = map and map:FindFirstChild('Erisia')
        local purpFlames = erisia and erisia:FindFirstChild('PurpFlames')

        for flameIndex, flame in ipairs(purpFlames and purpFlames:GetChildren() or {})do
            if flame.Name == 'PurpFlame' and flame:IsA('BasePart') and (flame.Position - position).Magnitude < 3 then
                return flame
            end
        end
    end
    local findNearestBluecap = function()
        local ingredients = workspace:FindFirstChild('Ingredients')
        local nearestBluecap, nearestDistance

        for bluecapIndex, bluecapPart in ipairs(ingredients and ingredients:GetChildren() or {})do
            if bluecapPart.Name == 'Bluecap' and bluecapPart:IsA('BasePart') then
                local distance = (bluecapPart.Position - waypoint21.Position).Magnitude

                if distance < 150 and (not nearestDistance or distance < nearestDistance) then
                    nearestBluecap, nearestDistance = bluecapPart, distance
                end
            end
        end

        return nearestBluecap
    end
    local stopIntelligenceTraining = function(target)
        handleAutomationChild(nil)
        talentPicker.cancelSpend()
        talentPicker.cancelFavour()
        progressionTraining.restorePassive()

        ax.trainingStat = nil
        ax.trainingBusy = nil

        local taskState = getSession()

        if getOwnedTalents(target).intelligenceunbounded then
            resetUnboundIntelligence(taskState)

            return true
        end
        if taskState.activeTask ~= 'unbound_intelligence' or not taskState.unboundIntelligenceStage then
            taskState.activeTask = 'unbound_intelligence'
            taskState.unboundIntelligenceStage = findItem('Soul Hearthgem') and 'flames' or 'hearthgem'
            taskState.unboundIntelligenceConsumedAt = nil
            taskState.unboundIntelligenceJob = game.JobId
            taskState.ferrymanCycle = nil

            setSession(taskState)
        end
        if taskState.unboundIntelligenceJob ~= game.JobId and taskState.unboundIntelligenceStage ~= 'verify' then
            taskState.unboundIntelligenceJob = game.JobId
            taskState.unboundIntelligenceStage = findItem('Soul Hearthgem') and 'flames' or 'hearthgem'

            setSession(taskState)
        end
        if taskState.unboundIntelligenceStage == 'verify' then
            talentPicker.resetData()

            if os.time() - (tonumber(taskState.unboundIntelligenceConsumedAt) or 0) < 12 then
                showProgress('Verifying Intelligence unbound', 2)
            else
                handleProgress('Intelligence unbound needs verification')
            end

            return true
        end
        if taskState.unboundIntelligenceStage == 'hearthgem' and findItem('Soul Hearthgem') then
            taskState.unboundIntelligenceStage = 'flames'

            setSession(taskState)
        end
        if taskState.unboundIntelligenceStage == 'hearthgem' or not findItem('Soul Hearthgem') then
            ax.progress = 'Getting Soul Hearthgem'

            if not bq(waypoint20, 'Soul Hearthgem', nil, 'Etrean') then
                showProgress('Retrying travel to Soul Hearthgem', 2)

                return true
            end

            local hearthgemPrompt = j('Soul Hearthgem')
            local promptDeadline = os.clock() + 5

            while not hearthgemPrompt and os.clock() < promptDeadline and isArmed(ax.generation) do
                task.wait(0.1)

                hearthgemPrompt = j('Soul Hearthgem')
            end

            if not hearthgemPrompt then
                handleProgress('Soul Hearthgem prompt was not found')

                return true
            end
            if not interactWithNpc(hearthgemPrompt) then
                showProgress('Retrying Soul Hearthgem interaction', 2)

                return true
            end

            local character = bw()
            local nameTag = character and character:FindFirstChild('NameTag', true)
            local dialogueDeadline = os.clock() + 5

            while not f('[Take it]') and os.clock() < dialogueDeadline and isArmed(ax.generation) do
                task.wait(0.1)
            end

            if not nameTag or nameTag.Text ~= 'Soul Hearthgem' or not clickButton('[Take it]') then
                handleProgress('Soul Hearthgem dialogue changed')

                return true
            end

            local consumeDeadline = os.clock() + 5

            repeat
                task.wait(0.1)
            until findItem('Soul Hearthgem') or os.clock() >= consumeDeadline or not isArmed(ax.generation)

            if not findItem('Soul Hearthgem') then
                showProgress('Waiting for Soul Hearthgem', 2)

                return true
            end

            delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})

            taskState = getSession()
            taskState.unboundIntelligenceStage = 'flames'

            setSession(taskState)
        end
        if taskState.unboundIntelligenceStage == 'flames' then
            local hearthgem = findItem('Soul Hearthgem')
            local humanoid = noEffects.localPlayer.humanoid

            if not hearthgem or not humanoid then
                return true
            end
            if hearthgem.Parent ~= noEffects.localPlayer.character then
                humanoid:EquipTool(hearthgem)
                task.wait(0.2)
            end
            if hearthgem.Parent ~= noEffects.localPlayer.character then
                showProgress('Equipping Soul Hearthgem', 1)

                return true
            end

            for flameSlot, flamePos in ipairs(aZ)do
                if not isArmed(ax.generation) then
                    return true
                end

                ax.progress = 'Lighting PurpFlame ' .. flameSlot .. ' of 4'

                if not bq(CFrame.new(flamePos + Vector3.new(4, 0, 0)), 'PurpFlame ' .. flameSlot, nil, 'Etrean') then
                    showProgress('Retrying travel to PurpFlame ' .. flameSlot, 2)

                    return true
                end

                local flamePart = findNearbyPurpFlame(flamePos)
                local flameDeadline = os.clock() + 5

                while not flamePart and os.clock() < flameDeadline and isArmed(ax.generation) do
                    task.wait(0.1)

                    flamePart = findNearbyPurpFlame(flamePos)
                end

                if not flamePart then
                    handleProgress('PurpFlame ' .. flameSlot .. ' was not found')

                    return true
                end

                hearthgem = findItem('Soul Hearthgem')

                if not hearthgem then
                    taskState.unboundIntelligenceStage = 'hearthgem'

                    setSession(taskState)

                    return true
                end
                if hearthgem.Parent ~= noEffects.localPlayer.character then
                    humanoid:EquipTool(hearthgem)
                    task.wait(0.2)
                end

                local interactPrompt = flamePart:FindFirstChild('InteractPrompt')

                if not interactPrompt or hearthgem.Parent ~= noEffects.localPlayer.character then
                    showProgress('Waiting to light PurpFlame ' .. flameSlot, 2)

                    return true
                end

                local fireLight = flamePart:FindFirstChild('FireLight', true)
                local lit = false

                for attempt = 1, 3 do
                    pcall(fire, interactPrompt)

                    local fireDeadline = os.clock() + 1

                    repeat
                        task.wait(0.1)
                    until fireLight and fireLight.Enabled or os.clock() >= fireDeadline or not isArmed(ax.generation)

                    if fireLight and fireLight.Enabled then
                        lit = true

                        break
                    end
                end

                if not lit then
                    showProgress('Retrying PurpFlame ' .. flameSlot, 2)

                    return true
                end
            end

            taskState = getSession()
            taskState.unboundIntelligenceStage = 'bluecap'

            setSession(taskState)
        end
        if taskState.unboundIntelligenceStage == 'bluecap' then
            ax.progress = 'Finding Bluecap for Intelligence unbound'

            if not bq(waypoint21, 'Bluecap', nil, 'Etrean') then
                showProgress('Retrying travel to Bluecap', 2)

                return true
            end

            local bluecap = findItem('Bluecap')

            if not bluecap then
                local nearbyBluecap = findNearestBluecap()

                if not nearbyBluecap then
                    showProgress('Waiting for a nearby Bluecap', 2)

                    return true
                end
                if not bq(CFrame.new(nearbyBluecap.Position + Vector3.new(0, 3, 0)), 'Bluecap harvest', nil, 'Etrean') then
                    showProgress('Retrying Bluecap harvest', 2)

                    return true
                end

                local harvestPrompt = nearbyBluecap:FindFirstChild('InteractPrompt')

                if harvestPrompt then
                    pcall(fire, harvestPrompt)
                end

                local harvestDeadline = os.clock() + 3

                repeat
                    task.wait(0.1)

                    bluecap = findItem('Bluecap')
                until bluecap or os.clock() >= harvestDeadline or not isArmed(ax.generation)
            end
            if not bluecap then
                showProgress('Waiting for harvested Bluecap', 2)

                return true
            end

            local bluecapHumanoid = noEffects.localPlayer.humanoid
            local quantityValue = bluecap:FindFirstChild('Quantity')
            local initialQuantity = tonumber(quantityValue and quantityValue.Value) or 1

            if bluecapHumanoid and bluecap.Parent ~= noEffects.localPlayer.character then
                bluecapHumanoid:EquipTool(bluecap)
                task.wait(0.2)
            end
            if bluecap.Parent ~= noEffects.localPlayer.character then
                showProgress('Equipping Bluecap', 1)

                return true
            end

            for consumeAttempt = 1, 5 do
                bluecap:Activate()
                task.wait(0.45)

                local remainingBluecap = findItem('Bluecap')
                local remainingQuantity = remainingBluecap and remainingBluecap:FindFirstChild('Quantity')

                if not remainingBluecap or (tonumber(remainingQuantity and remainingQuantity.Value) or 1) < initialQuantity then
                    taskState = getSession()
                    taskState.unboundIntelligenceStage = 'verify'
                    taskState.unboundIntelligenceConsumedAt = os.time()

                    setSession(taskState)
                    talentPicker.resetData()
                    showProgress('Verifying Intelligence unbound', 2)

                    return true
                end
            end

            showProgress('Retrying Bluecap consumption', 2)

            return true
        end

        return true
    end
    local isWillpowerUnboundable = function(stat, character, config)
        return (tonumber(character and character.Willpower) or 0) > 75 and (tonumber(stat and stat.StatWillpower) or 0) >= 75 and not config.willpowerunbounded
    end
    local bN = {
        WeaponHeavy = 'Heavy Weapons',
        WeaponMedium = 'Medium Weapons',
        WeaponLight = 'Light Weapons',
        ElementFire = 'Flamecharm',
        ElementIce = 'Frostdraw',
        ElementLightning = 'Thundercall',
        ElementWind = 'Galebreathe',
        ElementShadow = 'Shadowcast',
        ElementMetal = 'Ironsing',
        ElementBlood = 'Bloodrend',
    }
    local selectNextUnboundStat = function(charData, attrs, build, phase, completed)
        local statKey = talentPicker.nextStat(charData, attrs, build, phase)
        local statName = statKey and bN[statKey]
        local currentValue = statKey and (tonumber(charData['Stat' .. statKey] or charData['Stat_' .. statKey] or charData[statKey]) or 0) or 0
        local attributeValue = statKey and (tonumber(attrs and attrs[statKey]) or 0) or 0
        local limit = statKey and charData.AttributeLimits and charData.AttributeLimits[statKey]

        if statName and currentValue == 75 and attributeValue > currentValue and (limit or not (type(completed) == 'table' and completed[statKey])) then
            return statKey, statName
        end
    end
    local resetUnboundFerryman = function(state)
        for index, fieldName in ipairs({
            'unboundFerrymanStat',
            'unboundFerrymanStage',
            'unboundFerrymanCycle',
            'unboundFerrymanAttempts',
            'unboundFerrymanClaimAt',
            'unboundFerrymanClaimFailures',
        })do
            state[fieldName] = nil
        end

        if state.activeTask == 'unbound_ferryman' then
            state.activeTask = nil
        end

        setSession(state)
    end
    local invokeLimitAttribute = function(claimedStat)
        local requestsFolder = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
        local limitRemote = requestsFolder and requestsFolder:FindFirstChild('LimitAttribute')

        if not limitRemote then
            return false
        end

        local success, acknowledged = pcall(delayedTask.method, limitRemote, 'InvokeServer', claimedStat, true)

        return success and acknowledged ~= false
    end
    local handleFerrymanUnbound = function(bR, char, attributes)
        local data = getSession()
        local chosenStat, displayName = selectNextUnboundStat(char, attributes, ax.build, data.phase, data.unboundFerrymanCompleted)

        if data.unboundFerrymanStage and (not chosenStat or chosenStat ~= data.unboundFerrymanStat) then
            handleAutomationChild(nil)
            resetUnboundFerryman(data)

            return false
        end
        if not chosenStat then
            return false
        end
        if not data.unboundFerrymanStage then
            talentPicker.cancelSpend()
            talentPicker.cancelFavour()
            progressionTraining.restorePassive()

            ax.trainingStat = nil
            ax.trainingBusy = nil
            data.activeTask = 'unbound_ferryman'
            data.unboundFerrymanStat = chosenStat
            data.unboundFerrymanStage = 'fight'
            data.unboundFerrymanCycle = tonumber(noEffects.value('ferryman_cycle_ready_id')) or 0
            data.unboundFerrymanAttempts = 0
            data.unboundFerrymanClaimAt = nil
            data.unboundFerrymanClaimFailures = nil
            data.ferrymanCycle = nil

            setSession(data)
        elseif data.activeTask ~= 'unbound_ferryman' then
            data.activeTask = 'unbound_ferryman'

            setSession(data)
        end
        if data.unboundFerrymanStage == 'fight' then
            local readyCycle = tonumber(noEffects.value('ferryman_cycle_ready_id')) or 0
            local currentCycle = tonumber(data.unboundFerrymanCycle) or 0

            if readyCycle > currentCycle then
                if placeIds.isDungeon() then
                    handleAutomationChild('auto_ferryman')
                    showProgress('Leaving Ferryman after unbounding ' .. displayName, 2)

                    return true
                end

                handleAutomationChild(nil)

                data.unboundFerrymanStage = 'claim'

                setSession(data)
            else
                handleAutomationChild('auto_ferryman')
                showProgress('Unbounding ' .. displayName .. ' \u{b7} Auto Ferryman', 2)

                return true
            end
        end
        if data.unboundFerrymanStage == 'claim' then
            handleAutomationChild(nil)
            talentPicker.cancelSpend()

            local claimed = invokeLimitAttribute(chosenStat)

            if not claimed then
                data.unboundFerrymanClaimFailures = (tonumber(data.unboundFerrymanClaimFailures) or 0) + 1

                if data.unboundFerrymanClaimFailures >= 3 then
                    data.unboundFerrymanStage = 'fight'
                    data.unboundFerrymanCycle = tonumber(noEffects.value('ferryman_cycle_ready_id')) or 0
                    data.unboundFerrymanClaimFailures = nil

                    setSession(data)
                    showProgress('Retrying Ferryman for ' .. displayName .. ' unbound', 2)
                else
                    setSession(data)
                    showProgress('Retrying ' .. displayName .. ' unbound', 3)
                end

                return true
            end

            data.unboundFerrymanStage = 'verify'
            data.unboundFerrymanAttempts = (tonumber(data.unboundFerrymanAttempts) or 0) + 1
            data.unboundFerrymanClaimAt = os.time()

            setSession(data)
            talentPicker.resetData()
            showProgress('Verifying ' .. displayName .. ' unbound', 2)

            return true
        end
        if data.unboundFerrymanStage == 'verify' then
            talentPicker.resetData()

            if not (char.AttributeLimits and char.AttributeLimits[chosenStat]) then
                data.unboundFerrymanCompleted = data.unboundFerrymanCompleted or {}
                data.unboundFerrymanCompleted[chosenStat] = true

                resetUnboundFerryman(data)

                return true
            end
            if os.time() - (tonumber(data.unboundFerrymanClaimAt) or 0) < 5 then
                showProgress('Verifying ' .. displayName .. ' unbound', 2)

                return true
            end
            if (tonumber(data.unboundFerrymanAttempts) or 0) < 3 then
                data.unboundFerrymanStage = 'fight'
                data.unboundFerrymanCycle = tonumber(noEffects.value('ferryman_cycle_ready_id')) or 0
                data.unboundFerrymanClaimAt = nil

                setSession(data)
                showProgress('Retrying Ferryman for ' .. displayName .. ' unbound', 2)

                return true
            end

            handleProgress(displayName .. ' unbound needs verification')

            return true
        end

        data.unboundFerrymanStage = 'fight'

        setSession(data)

        return true
    end
    local shouldHeal = function(healState)
        local humanoid = noEffects.localPlayer.humanoid
        local ride = bo()

        if not humanoid or not ride or humanoid.MaxHealth <= 0 then
            return false
        end

        local healthRatio = humanoid.Health / humanoid.MaxHealth

        if not ax.depthsHealPosition and healthRatio > 0.35 then
            return false
        end
        if healthRatio >= 0.6 then
            ax.depthsHealPosition = nil

            return false
        end

        ax.depthsHealing = true

        handleAutomationChild(nil)
        ax:stopTravel()
        executionQueue.acquire(ax)
        executionQueue.checkpoint(ax, false, 'Depths emergency healing')
        clickHolder.set(false)
        progressionTraining.restorePassive()

        if bw() then
            delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})
        end

        local state = getSession()
        local heightOffset = state.activeTask == 'unbound_willpower' and 20 or 100

        ax.depthsHealPosition = ax.depthsHealPosition or (ride.CFrame + Vector3.new(0, heightOffset, 0))
        ax.progress = 'Healing safely in the Depths'

        while isArmed(healState) and placeIds.isDepths() do
            humanoid = noEffects.localPlayer.humanoid
            ride = bo()

            if not humanoid or humanoid.Health <= 0 or not ride then
                break
            end
            if humanoid.Health / math.max(humanoid.MaxHealth, 1) >= 0.6 then
                break
            end

            ride.AssemblyLinearVelocity = Vector3.zero
            ride.CFrame = ax.depthsHealPosition

            task.wait(0.2)
        end

        ax.depthsHealPosition = nil
        ax.depthsHealing = nil

        executionQueue.cancel(ax, 'Depths healing complete')

        return true
    end
    local resetUnboundWillpower = function(willpower)
        willpower.unboundWillpowerStage = nil
        willpower.unboundWillpowerAttempts = nil
        willpower.unboundWillpowerTeleportAt = nil
        willpower.unboundWillpowerJob = nil
        willpower.unboundWillpowerEventMissing = nil
        willpower.unboundWillpowerCastleAttempts = nil
        willpower.unboundWillpowerEventReadyAt = nil

        if willpower.activeTask == 'unbound_willpower' then
            willpower.activeTask = nil
        end
        if willpower.paused == 'Willpower unbound needs verification' then
            willpower.paused = nil
            willpower.pausedSignature = nil
        end

        setSession(willpower)
    end
    local onWillpowerUnbound = function(loopState, character)
        handleAutomationChild(nil)
        talentPicker.cancelSpend()
        talentPicker.cancelFavour()
        progressionTraining.restorePassive()

        ax.trainingStat = nil
        ax.trainingBusy = nil

        if getOwnedTalents(character).willpowerunbounded then
            teleport.stop()
            resetUnboundWillpower(getSession())
            showProgress('Willpower unbound complete', 1)

            return true
        end

        local stateData = getSession()

        if stateData.activeTask ~= 'unbound_willpower' then
            stateData.activeTask = 'unbound_willpower'
            stateData.unboundWillpowerStage = 'enter_depths'
            stateData.unboundWillpowerAttempts = 0
            stateData.unboundWillpowerJob = game.JobId
            stateData.unboundWillpowerEventMissing = nil
            stateData.unboundWillpowerCastleAttempts = nil
            stateData.unboundWillpowerEventReadyAt = nil
            stateData.ferrymanCycle = nil

            setSession(stateData)
        end
        if stateData.unboundWillpowerJob and stateData.unboundWillpowerJob ~= game.JobId then
            stateData.unboundWillpowerStage = placeIds.isDepths() and 'akira_event' or 'enter_depths'
            stateData.unboundWillpowerAttempts = 0
            stateData.unboundWillpowerTeleportAt = nil
            stateData.unboundWillpowerJob = game.JobId
            stateData.unboundWillpowerEventMissing = nil
            stateData.unboundWillpowerCastleAttempts = nil
            stateData.unboundWillpowerEventReadyAt = nil

            setSession(stateData)
        elseif not stateData.unboundWillpowerJob then
            stateData.unboundWillpowerJob = game.JobId

            setSession(stateData)
        end
        if not placeIds.isDepths() then
            stateData.unboundWillpowerStage = 'enter_depths'

            if not stateData.unboundWillpowerTeleportAt or os.time() - stateData.unboundWillpowerTeleportAt >= 20 then
                stateData.unboundWillpowerTeleportAt = os.time()

                setSession(stateData)
                teleport.start('Depths')
            end

            showProgress('Entering the Depths for Willpower unbound', 2)

            return true
        end

        teleport.stop()

        if stateData.unboundWillpowerStage == 'enter_depths' then
            stateData.unboundWillpowerStage = 'akira_event'
            stateData.unboundWillpowerTeleportAt = nil
            stateData.unboundWillpowerEventReadyAt = nil

            setSession(stateData)
        end
        if stateData.unboundWillpowerStage == 'akira_event' then
            if not stateData.unboundWillpowerEventReadyAt then
                ax.progress = 'Travelling to Akira event'

                if not bq(waypoint4, 'Akira event', true) then
                    showProgress('Retrying travel to Akira event', 2)

                    return true
                end

                stateData = getSession()
                stateData.unboundWillpowerEventReadyAt = os.time() + math.random(30, 45)

                setSession(stateData)
                showProgress('Waiting for Akira cutscene', 2)

                return true
            end
            if os.time() < stateData.unboundWillpowerEventReadyAt then
                showProgress('Waiting for Akira cutscene', 2)

                return true
            end

            local akiraEvent = j('AkiraEvent')

            if not akiraEvent then
                if os.time() < stateData.unboundWillpowerEventReadyAt + 15 then
                    showProgress('Waiting for Akira to appear', 2)

                    return true
                end

                stateData = getSession()
                stateData.unboundWillpowerStage = 'akira_finish'
                stateData.unboundWillpowerEventMissing = true
                stateData.unboundWillpowerCastleAttempts = 0
                stateData.unboundWillpowerEventReadyAt = nil

                setSession(stateData)
                showProgress('Akira event disappeared; checking Castle Light', 1)

                return true
            end

            ax.progress = 'Speaking with Akira event'

            if not interactWithNpc(akiraEvent) or not sendDiverJoinDialogue() then
                delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})

                if not akiraEvent.Parent or not j('AkiraEvent') then
                    stateData = getSession()
                    stateData.unboundWillpowerStage = 'akira_finish'
                    stateData.unboundWillpowerEventMissing = true
                    stateData.unboundWillpowerCastleAttempts = 0
                    stateData.unboundWillpowerEventReadyAt = nil

                    setSession(stateData)
                    showProgress('Akira event disappeared; checking Castle Light', 1)
                else
                    showProgress('Retrying Akira event dialogue', 2)
                end

                return true
            end

            stateData = getSession()
            stateData.unboundWillpowerStage = 'akira_finish'
            stateData.unboundWillpowerEventMissing = nil
            stateData.unboundWillpowerCastleAttempts = 0
            stateData.unboundWillpowerEventReadyAt = nil

            setSession(stateData)
        end
        if stateData.unboundWillpowerStage == 'akira_finish' then
            ax.progress = 'Travelling to Akira'

            if not bq(waypoint5, 'Akira', true) then
                showProgress('Retrying travel to Akira', 2)

                return true
            end

            local akiraBase = j('AkiraBase')

            if not akiraBase then
                stateData = getSession()
                stateData.unboundWillpowerCastleAttempts = (tonumber(stateData.unboundWillpowerCastleAttempts) or 0) + 1

                setSession(stateData)

                if stateData.unboundWillpowerEventMissing or stateData.unboundWillpowerCastleAttempts >= 3 then
                    ax.progress = 'Switching servers for Akira'
                    ax.hopRequested = true

                    noEffects.hop(stateData.slot, true)

                    return true
                end

                showProgress('Waiting for Castle Light Akira', 2)

                return true
            end

            ax.progress = 'Completing Willpower unbound'

            if not h(akiraBase) then
                stateData = getSession()
                stateData.unboundWillpowerCastleAttempts = (tonumber(stateData.unboundWillpowerCastleAttempts) or 0) + 1

                setSession(stateData)

                if stateData.unboundWillpowerEventMissing or stateData.unboundWillpowerCastleAttempts >= 3 then
                    ax.progress = 'Switching servers for Akira'
                    ax.hopRequested = true

                    noEffects.hop(stateData.slot, true)
                else
                    showProgress('Retrying Akira interaction', 2)
                end

                return true
            end

            local deadline = os.clock() + 4

            repeat
                task.wait(0.1)
            until bw() or os.clock() >= deadline or not isArmed(loopState)

            if not bw() or not sendDiverBraceDialogue() then
                delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})

                stateData = getSession()
                stateData.unboundWillpowerCastleAttempts = (tonumber(stateData.unboundWillpowerCastleAttempts) or 0) + 1

                setSession(stateData)

                if stateData.unboundWillpowerEventMissing or stateData.unboundWillpowerCastleAttempts >= 3 then
                    ax.progress = 'Switching servers for Akira'
                    ax.hopRequested = true

                    noEffects.hop(stateData.slot, true)
                else
                    showProgress('Retrying Castle Light Akira dialogue', 2)
                end

                return true
            end

            stateData = getSession()
            stateData.unboundWillpowerStage = 'verify'
            stateData.unboundWillpowerAttempts = (tonumber(stateData.unboundWillpowerAttempts) or 0) + 1

            setSession(stateData)
            talentPicker.resetData()
            showProgress('Verifying Willpower unbound', 2)

            return true
        end
        if stateData.unboundWillpowerStage == 'verify' then
            talentPicker.resetData()

            local verifiedChar = waitForTalentData()

            if verifiedChar and getOwnedTalents(verifiedChar).willpowerunbounded then
                resetUnboundWillpower(stateData)
                showProgress('Willpower unbound complete', 1)
            elseif (tonumber(stateData.unboundWillpowerAttempts) or 0) < 3 then
                stateData.unboundWillpowerStage = 'akira_finish'

                setSession(stateData)
                showProgress('Retrying final Akira verification', 2)
            else
                handleProgress('Willpower unbound needs verification')
            end

            return true
        end

        stateData.unboundWillpowerStage = 'enter_depths'

        setSession(stateData)

        return true
    end
    local travelToTarget = function(target, position, callback, _)
        ax.progress = 'Travelling to ' .. target

        if not bq(position, target, nil, _) then
            return false, 'Could not reach ' .. target
        end

        local found
        local deadline = os.clock() + 8

        repeat
            local npcs = workspace:FindFirstChild('NPCs')
            local npc = npcs and npcs:FindFirstChild(target)

            found = npc and (npc:FindFirstChild('Shrine') or npc:FindFirstChild('InteractPrompt', true) and npc)

            if found or not isArmed(ax.generation) then
                break
            end

            task.wait(0.2)
        until os.clock() >= deadline

        if not found then
            return false, target .. ' was not found'
        end

        local prompt = found:FindFirstChild('InteractPrompt', true) or found.Parent:FindFirstChild('InteractPrompt', true) or found:FindFirstChildWhichIsA('ProximityPrompt', true) or found.Parent:FindFirstChildWhichIsA('ProximityPrompt', true)

        if not prompt then
            return false, target .. ' interaction was not found'
        end

        local generation = ax.generation
        local identified = bs(target:lower())

        ax.progress = 'Opening ' .. target

        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')

        for attempt = 1, 3 do
            if identified or not isArmed(generation) then
                break
            end

            local dialogueGui = playerGui and playerGui:FindFirstChild('DialogueGui')

            if dialogueGui and br(dialogueGui) then
                delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})

                local closeDeadline = os.clock() + 2

                repeat
                    task.wait(0.1)
                until not br(dialogueGui) or os.clock() >= closeDeadline or not isArmed(generation)
            end

            pcall(delayedTask.call, fire, prompt)

            local identifyDeadline = os.clock() + 10

            repeat
                task.wait(0.1)

                identified = bs(target:lower())
            until identified or os.clock() >= identifyDeadline or not isArmed(generation)
        end

        if not isArmed(generation) then
            return false, 'Automation stopped'
        end
        if not identified then
            return false, target .. ' UI needs identification'
        end

        return callback(identified)
    end
    local collectStats = function(source)
        local result = {}

        for index, stat in ipairs(a_)do
            local value = source and tonumber(source['Stat' .. stat])

            if value == nil then
                return nil
            end

            result[stat] = value
        end

        return result
    end
    local meetsMasteryRequirements = function(statData)
        return (talentPicker.power(statData) or 0) >= 20 and tonumber(statData and statData.AvailableAttributePoints) == 0 and tonumber(statData and statData.FullAttributePoints) == 0
    end
    local closeMasteryDialogue = function()
        if not bs('shrine of mastery') then
            return true
        end

        local endDialogue = f('[End Dialogue]')

        if endDialogue then
            bv(endDialogue.button)
        end
        if bs('shrine of mastery') then
            delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})
        end

        local exitDeadline = os.clock() + 3

        repeat
            if not bs('shrine of mastery') then
                return true
            end

            task.wait(0.1)
        until os.clock() >= exitDeadline or not isArmed(ax.generation)

        return false
    end
    local checkMasteryReady = function()
        local currentGen = ax.generation
        local character = waitForTalentData()
        local buildState = getSession()
        local stats = collectStats(character)
        local knowledge = talentPicker.knowledge(character)

        if not stats or knowledge == nil then
            return false, 'Waiting for Shrine of Mastery data'
        end
        if not meetsMasteryRequirements(character) then
            return false, 
"Shrine of Mastery requires Power 20 with no attribute points available"
        end
        if buildState.pending or buildState.paused or buildState.phase ~= 'post' or not buildState.phaseConfirmed or buildState.inexact or buildCharacterKey(character) ~= buildState.characterFingerprint or buildState.build ~= ax.build.url then
            return false, 'Shrine of Mastery build state changed'
        end
        if statInference.required(ax.build.post, stats) > 3 - (tonumber(buildState.masteryPointsUsed) or 0) then
            return false, 
"Shrine of Mastery cannot correct all attribute excess within its remaining uses"
        end
        if knowledge < 1 then
            return false, 'Need Knowledge for Shrine of Mastery'
        end

        local dialogue = f('I wish to reevaluate my Attributes.')

        if dialogue then
            if not bv(dialogue.button) then
                return false, 'Shrine of Mastery dialogue could not be opened'
            end
        end

        local options, plan
        local planDeadline = os.clock() + 5

        repeat
            options = e()

            local labels = {}

            for optionIndex, option in ipairs(options)do
                labels[#labels + 1] = option.text
            end

            plan = statInference.plan(ax.build.post, stats, labels, tonumber(buildState.masteryPointsUsed) or 0, 3)

            if plan or not isArmed(currentGen) then
                break
            end

            task.wait(0.1)
        until os.clock() >= planDeadline

        if not isArmed(currentGen) then
            return false, 'Automation stopped'
        end
        if not plan then
            return false, 'Shrine of Mastery did not offer the exact build correction'
        end

        local choice

        for matchIndex, candidate in ipairs(options)do
            if candidate.text == plan.label then
                choice = candidate.button

                break
            end
        end

        if not choice then
            return false, 'Shrine of Mastery choice changed'
        end

        local currentCharacter = waitForTalentData()
        local freshStats = collectStats(currentCharacter)

        if not freshStats or not meetsMasteryRequirements(currentCharacter) or talentPicker.knowledge(currentCharacter) ~= knowledge or buildCharacterKey(currentCharacter) ~= buildCharacterKey(character) or not tablesEqual(stats, freshStats) or getSession().pending then
            return false, 'Shrine of Mastery data changed before selection'
        end

        buildState.pending = {
            kind = 'mastery',
            stat = plan.stat,
            before = plan.before,
            after = plan.after,
            knowledgeBefore = knowledge,
            statsBefore = stats,
            fingerprint = buildCharacterKey(character),
            build = ax.build.url,
            slot = tostring(buildState.slot),
            at = os.time(),
        }

        noEffects.setValue('mastery_transaction', buildState.pending)
        setSession(buildState)

        if not bv(choice) then
            return false, 'Shrine of Mastery choice needs verification'
        end

        talentPicker.resetData()

        return true
    end
    local findShrineOrderPrompt = function()
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')
        local title = choicePrompt and choicePrompt:FindFirstChild('Title', true)
        local desc = choicePrompt and choicePrompt:FindFirstChild('Desc', true)
        local yesButton = choicePrompt and choicePrompt:FindFirstChild('Yes', true)

        if choicePrompt and choicePrompt.Enabled and title and title.Text == 'Shrine of Order' and desc and desc.Text:find('Irreversibly change your attributes', 1, true) and yesButton and yesButton:IsA('GuiButton') and br(yesButton) then
            return choicePrompt, yesButton
        end
    end
    local confirmShrineOrder = function(root)
        local generation = ax.generation
        local findButton = function(text)
            for index, button in ipairs(root:GetDescendants())do
                if button:IsA('GuiButton') and br(button) and bu(button):match('^%s*' .. text .. '%s*$') then
                    return button
                end
            end
        end
        local choicePrompt, yesButton = findShrineOrderPrompt()
        local save = getSession()
        local character = waitForTalentData()

        if not character then
            return false, 'Waiting for character data'
        end
        if not save.pending or save.pending.kind ~= 'order' then
            save.pending = {
                kind = 'order',
                knowledge = talentPicker.knowledge(character),
                stats = {},
                fingerprint = buildCharacterKey(character),
                build = ax.build.url,
                at = os.time(),
            }

            for stat, Z in pairs(ax.build.pre)do
                save.pending.stats[stat] = character and character['Stat' .. stat] or 0
            end

            setSession(save)
        end
        if not choicePrompt then
            local button = findButton('i wish to engage in a deal%.')

            if button then
                if not bv(button) then
                    return false, 'Shrine of Order deal could not be opened'
                end

                local timeout = os.clock() + 5

                repeat
                    task.wait(0.1)

                    button = findButton('i agree%.')
                until button or os.clock() >= timeout or not isArmed(generation)
            else
                button = findButton('i agree%.') or findButton('very well%.')
            end
            if not isArmed(generation) then
                return false, 'Automation stopped'
            end
            if not button then
                return false, 'Shrine of Order confirmation needs identification'
            end
            if not bv(button) then
                return false, 'Shrine of Order confirmation could not be sent'
            end

            local timeout = os.clock() + 10

            repeat
                task.wait(0.1)

                choicePrompt, yesButton = findShrineOrderPrompt()
                button = findButton('very well%.')
            until choicePrompt or button or os.clock() >= timeout or not isArmed(generation)

            if not choicePrompt and button then
                if not bv(button) then
                    return false, 'Shrine of Order final dialogue could not be sent'
                end

                timeout = os.clock() + 10

                repeat
                    task.wait(0.1)

                    choicePrompt, yesButton = findShrineOrderPrompt()
                until choicePrompt or os.clock() >= timeout or not isArmed(generation)
            end
        end
        if not isArmed(generation) then
            return false, 'Automation stopped'
        end
        if not choicePrompt then
            return false, 'Shrine of Order result needs verification'
        end
        if not bv(yesButton) then
            return false, 'Shrine of Order result could not be accepted'
        end

        local timeout = os.clock() + 10

        repeat
            task.wait(0.1)
        until not choicePrompt.Parent or not choicePrompt.Enabled or os.clock() >= timeout or not isArmed(generation)

        if not isArmed(generation) then
            return false, 'Automation stopped'
        end
        if choicePrompt.Parent and choicePrompt.Enabled then
            return false, 'Shrine of Order result needs verification'
        end

        timeout = os.clock() + 5

        repeat
            for index, button in ipairs(root:GetDescendants())do
                if button:IsA('GuiButton') and br(button) and bu(button):match('^%s*%[end dialogue%]%s*$') then
                    bv(button)

                    return true
                end
            end

            task.wait(0.1)
        until os.clock() >= timeout or not isArmed(generation)

        return true
    end
    local clickShrineOption = function(root)
        local generation = ax.generation
        local findButton = function(text)
            for index, button in ipairs(root:GetDescendants())do
                if button:IsA('GuiButton') and br(button) and bu(button) == text then
                    return button
                end
            end
        end
        local findButtonWithWait = function(text)
            local timeout = os.clock() + 6

            repeat
                if not isArmed(generation) or not root.Parent then
                    return nil
                end

                local button = findButton(text)

                if button then
                    return button
                end

                task.wait(0.1)
            until os.clock() >= timeout
        end
        local clickButton = function(button)
            local center = button.AbsolutePosition + button.AbsoluteSize / 2 + game:GetService('GuiService'):GetGuiInset()
            local input = game:GetService('VirtualInputManager')
            local success = pcall(function()
                input:SendMouseButtonEvent(center.X, center.Y, 0, true, game, 0)
                task.wait(0.08)
                input:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)
            end)

            return success
        end
        local readDialogue = function()
            local dialogueFrame = root:FindFirstChild('DialogueFrame', true)
            local dialogueSheet = dialogueFrame and dialogueFrame:FindFirstChild('DialogueSheet', true)
            local container = dialogueSheet and dialogueSheet:FindFirstChild('Container')
            local texts = {}

            for index, child in ipairs(container and container:GetChildren() or {})do
                if child:IsA('TextLabel') and child.Visible then
                    texts[#texts + 1] = child.Text
                end
            end

            return table.concat(texts):upper():gsub('%s+', '')
        end
        local character = waitForTalentData()
        local power = talentPicker.power(character)

        if not power or power < 5 or power > 7 then
            return false, 'Shrine of Blasphemy Power changed'
        end

        for index, pair in ipairs({
            {
                'i wish to engage in a deal.',
                'i agree.',
            },
            {
                'i agree.',
                'very well.',
            },
        })do
            local button = findButtonWithWait(pair[1])

            if not button or not clickButton(button) or not findButtonWithWait(pair[2]) then
                return false, 'Shrine of Blasphemy dialogue changed'
            end
        end

        if not readDialogue():find('YOUAREWEAK.FRAGILE.', 1, true) then
            return false, 'Shrine of Blasphemy Power deal was not confirmed'
        end

        local button = findButton('very well.')

        if not button or not clickButton(button) then
            return false, 'Shrine of Blasphemy confirmation could not be sent'
        end

        local button = findButtonWithWait('[end dialogue]')

        if not button or not readDialogue():find('YOURSKULLISSTURDY.', 1, true) then
            return false, 'Shrine of Blasphemy result needs identification'
        end

        local save = getSession()

        save.pending = {
            kind = 'blasphemy',
            power = power,
            fingerprint = buildCharacterKey(character),
            build = ax.build.url,
            at = os.time(),
        }

        setSession(save)

        if not clickButton(button) then
            return false, 'Shrine of Blasphemy ending could not be sent'
        end

        talentPicker.resetData()

        return true
    end
    local computeMissingTalents = function(build)
        local preTalentsSet = talentPicker.preTalents(build)
        local targetTalents = getOwnedTalents(waitForTalentData())
        local missingTalents = talentPicker.missing(build, preTalentsSet, targetTalents)

        return missingTalents, preTalentsSet
    end
    local buildProgressionSnapshot = function(preset, state, character)
        for statIndex, statName in ipairs(a_)do
            if tonumber(character and character['Stat' .. statName]) == nil then
                state.phaseEvidence = 'waiting for ' .. statName .. ' data'

                return false, 'waiting_data'
            end
        end

        local fingerprint = buildCharacterKey(character)
        local snapshot = {
            characterFingerprint = state.characterFingerprint,
            phase = state.phase,
            phaseConfirmed = state.phaseConfirmed,
            phaseSource = state.phaseSource,
            phaseEvidence = state.phaseEvidence,
            reconcileState = state.reconcileState,
            inexact = state.inexact,
        }
        local prevMissingTalents = state.missingTalents
        local prevMissingMantras = state.missingMantras

        if state.characterFingerprint and state.characterFingerprint ~= fingerprint then
            resetSession(state)
        end

        state.characterFingerprint = fingerprint

        local buildTalents = getOwnedTalents(character)
        local ownedMantras = talentPicker.owned(character, 'Mantras')
        local presetMissingTalents = talentPicker.missing(preset, talentPicker.preTalents(preset), buildTalents)
        local presetMissingMantras = talentPicker.missing(preset, talentPicker.preMantras(preset), ownedMantras)
        local targetsMet = talentPicker.targetsMet(character, preset.pre)
        local preMismatch = talentPicker.mismatch(character, preset.pre)
        local postMismatch = talentPicker.mismatch(character, preset.post)
        local power = sumCharacterStats(character)
        local orderPower = sumValues(preset.pre)
        local newPhase, reconcileState, phaseSource

        if preset.noShrine then
            newPhase, reconcileState, phaseSource = 'post', 'partial_post', 'inferred'
        elseif state.orderVerifiedFor == fingerprint .. ':' .. preset.url then
            newPhase, reconcileState, phaseSource = 'post', 'partial_post', 'verified'
        elseif snapshot.characterFingerprint == fingerprint and snapshot.phase == 'post' and snapshot.phaseConfirmed and snapshot.phaseSource == 'verified' then
            newPhase, reconcileState, phaseSource = 'post', 'partial_post', 'verified'
        elseif statPostInference.inferPost(character, preset.pre, preset.post, talentPicker.power(character)) then
            newPhase, reconcileState, phaseSource = 'post', 'partial_post', 'inferred'
        elseif targetsMet and not preMismatch and (next(presetMissingTalents) or next(presetMissingMantras)) then
            newPhase, reconcileState, phaseSource = 'pre', 'pre_cards', 'inferred'
        elseif power > orderPower and not postMismatch then
            newPhase, reconcileState, phaseSource = 'post', 'partial_post', 'inferred'
        elseif not preMismatch and not targetsMet then
            newPhase, reconcileState, phaseSource = 'pre', 'partial_pre', 'inferred'
        elseif targetsMet and power == orderPower then
            newPhase, reconcileState, phaseSource = 'pre', 'ready_order', 'inferred'
        elseif preMismatch and not postMismatch then
            newPhase, reconcileState, phaseSource = 'post', 'partial_post', 'inferred'
        elseif preMismatch and postMismatch then
            reconcileState = 'incompatible'
            state.inexact = true
        else
            newPhase, reconcileState, phaseSource = 'pre', (talentPicker.power(character) or 0) < 8 and 'pre_power' or 'ready_order', 'inferred'
        end
        if reconcileState ~= 'incompatible' and not state.declinedWipeFor then
            state.inexact = nil
        end

        state.missingTalents = talentPicker.missing(preset, preset.talents, buildTalents)
        state.missingMantras = talentPicker.missing(preset, preset.mantras, ownedMantras)
        state.reconcileState = reconcileState

        if newPhase then
            state.phase = newPhase
            state.phaseConfirmed = true
            state.phaseSource = phaseSource
            state.phaseEvidence = phaseSource == 'verified' and (state.orderVerifiedFor or 'verified character history') or (phaseSource == 'inferred' and buildProfileSignature(character) or 'build has no Shrine of Order')
        else
            state.phase = nil
            state.phaseConfirmed = nil
            state.phaseSource = nil
            state.phaseEvidence = 'ambiguous stat distribution'
        end
        if snapshot.characterFingerprint ~= state.characterFingerprint or snapshot.phase ~= state.phase or snapshot.phaseConfirmed ~= state.phaseConfirmed or snapshot.phaseSource ~= state.phaseSource or snapshot.phaseEvidence ~= state.phaseEvidence or snapshot.reconcileState ~= state.reconcileState or snapshot.inexact ~= state.inexact or not tablesEqual(prevMissingTalents, state.missingTalents) or not tablesEqual(prevMissingMantras, state.missingMantras) then
            setSession(state)
        end

        return newPhase ~= nil, reconcileState
    end
    local collectDependencyIds = function(talentSpec)
        if type(talentSpec) ~= 'table' then
            return nil
        end

        local resultIds = {}

        for fieldIndex, fieldName in ipairs({
            'from_ids',
            'requires',
            'prerequisites',
        })do
            if type(talentSpec[fieldName]) == 'table' then
                for fieldKey, talentId in pairs(talentSpec[fieldName])do
                    resultIds[#resultIds + 1] = talentId
                end
            end
        end

        local requirementTalents = talentSpec.requirements and talentSpec.requirements.talents

        if type(requirementTalents) == 'table' then
            for reqKey, reqTalentId in pairs(requirementTalents)do
                resultIds[#resultIds + 1] = reqTalentId
            end
        end

        return resultIds
    end
    local buildTalentMetadataMap = function(talentTree)
        local talents, idMap, visited = talentPicker.preTalents(talentTree), {}, {}

        for metaKey, metadata in pairs(talentTree.metadata)do
            local metadataId = metadata.id or metadata._id

            if metadataId then
                idMap[metadataId] = metaKey
            end
        end

        local function protect(talentKey)
            if visited[talentKey] then
                return
            end

            visited[talentKey] = true
            talents[talentKey] = true

            local meta = talentTree.metadata[talentKey]

            for prereqIndex, prereqId in ipairs(collectDependencyIds(meta) or {})do
                local dependencyKey = idMap[prereqId] or type(prereqId) == 'string' and sanitizeString(prereqId)

                if dependencyKey and talentTree.metadata[dependencyKey] then
                    protect(dependencyKey)
                end
            end
        end

        local keys = table.clone(talents)

        for startingKey in pairs(keys)do
            protect(startingKey)
        end

        return talents
    end
    local shouldProcessTalent = function(config, talentId, points, allocated, times)
        local talent = config.metadata[talentId]

        if getSession().talentCleanup and ((config.wantedTalents or config.talents)[talentId] or not talentPicker.isStatTalent(talent)) then
            return false
        end
        if not talent or not points[talentId] and not allocated or talent.autotalent or talent.vaulted or talent.dontcounttowardstotal or not collectDependencyIds(talent) then
            return false
        end

        local wanted = (config.wantedTalents or config.talents)[talentId]
        local timeMap = buildTalentMetadataMap(config)

        if wanted and (getSession().mode == 'talents' or not times or not timeMap[times] or timeMap[talentId]) then
            return false
        end

        local source = getSession().mode == 'talents' and talentPicker.statTalents(config) or times and timeMap or config.talents

        for otherId in pairs(source)do
            local otherTalent = config.metadata[otherId]

            if not otherTalent then
                return false
            end

            local conflicts = collectDependencyIds(otherTalent)

            if not conflicts then
                return false
            end

            for conflictKey, conflictRef in pairs(conflicts)do
                if conflictRef == (talent.id or talent._id) or type(conflictRef) == 'string' and talentId == sanitizeString(conflictRef) then
                    return false
                end
            end
        end

        return true, wanted and 2 or 1
    end
    local normalizeRarity = function(talentInfo)
        local rarityText = talentInfo and tostring(talentInfo.rarity or talentInfo.Rarity or ''):lower()

        return rarityText == 'advanced' and 'common' or rarityText
    end
    local resolveChanceChain = function(talentList, currentTimes, candidates, touched)
        local best
        local chain = getSession().chanceChain

        if chain and currentTimes[chain.target] and candidates[chain.donor] and (not touched or touched[chain.donor]) then
            local targetMeta = talentList.metadata[chain.target]
            local donorMeta = talentList.metadata[chain.donor]
            local targetRarity = normalizeRarity(targetMeta)
            local donorRarity = normalizeRarity(donorMeta)

            if targetRarity == donorRarity and shouldProcessTalent(talentList, chain.donor, candidates, false, chain.target) then
                return {
                    target = chain.target,
                    donor = chain.donor,
                    deal = 'Talent Exchange',
                    cost = 5,
                    totalCost = 5,
                }
            end
        end

        for targetId in pairs(currentTimes)do
            local currentTalent = talentList.metadata[targetId]
            local currentRarity = normalizeRarity(currentTalent)

            if currentRarity == 'rare' or currentRarity == 'common' then
                for cg in pairs(candidates)do
                    local donorTalent = talentList.metadata[cg]
                    local donorRarity = normalizeRarity(donorTalent)
                    local valid, rank = shouldProcessTalent(talentList, cg, candidates, false, targetId)

                    if valid and (not touched or touched[cg]) and (donorRarity == 'rare' or donorRarity == 'common') then
                        local cost = currentRarity == 'rare' and donorRarity ~= 'rare' and 10 or 5
                        local deal = currentRarity == 'rare' and donorRarity ~= 'rare' and 'Talent Elevation' or currentRarity ~= 'rare' and donorRarity == 'rare' and 'Talent Degradation' or 'Talent Exchange'
                        local isConversion = deal ~= 'Talent Exchange'
                        local candidate = {
                            target = targetId,
                            donor = cg,
                            deal = deal,
                            cost = cost,
                            totalCost = cost + (isConversion and 5 or 0),
                            conversion = isConversion,
                            outputRarity = currentRarity,
                            rank = rank,
                        }

                        if not best or rank < best.rank or rank == best.rank and (not isConversion and best.conversion or isConversion == best.conversion and candidate.totalCost < best.totalCost) then
                            best = candidate
                        end
                    end
                end
            end
        end

        return best
    end
    local collectProtectedTalents = function(talentPool, allotted)
        local protectedById, byId, visiting = {}, {}, {}

        for talentId, meta in pairs(talentPool.metadata)do
            local externalId = meta.id or meta._id

            if externalId then
                byId[externalId] = talentId
            end
        end

        local function protectTalent(talentId)
            if visiting[talentId] then
                return true
            end

            visiting[talentId] = true
            protectedById[talentId] = true

            local deps = collectDependencyIds(talentPool.metadata[talentId])

            if not deps then
                return false
            end

            for depId, depRef in pairs(deps)do
                local resolved = byId[depRef] or type(depRef) == 'string' and sanitizeString(depRef)

                if not resolved or not talentPool.metadata[resolved] or not protectTalent(resolved) then
                    return false
                end
            end

            return true
        end

        for talentId in pairs(talentPool.wantedTalents or talentPool.talents)do
            if not protectTalent(talentId) then
                return nil
            end
        end

        local result = {}

        for talentId in pairs(allotted)do
            if not protectedById[talentId] and talentPicker.isStatTalent(talentPool.metadata[talentId]) and shouldProcessTalent(talentPool, talentId, allotted) then
                result[talentId] = true
            end
        end

        return result
    end
    local b9, ca
    local performChanceTransaction = function(shrine, deal)
        if getSession().pending then
            return false, 'Shrine of Chance transaction is already pending'
        end
        if deal.deal ~= 'Talent Exchange' and deal.deal ~= 'Talent Elevation' and deal.deal ~= 'Talent Degradation' then
            return false, 'Shrine of Chance normal talent deal was not identified'
        end

        local item = shrine:FindFirstChild('DialogueExtents')

        item = item and item:FindFirstChild('ShopFrame')
        item = item and item:FindFirstChild('Category_Shrine of Chance')
        item = item and item:FindFirstChild('Items')
        item = item and item:FindFirstChild(deal.deal)

        local contextFrame = item and item:FindFirstChild('ContextFrame')
        local buyButton = contextFrame and contextFrame:FindFirstChild('Buy')
        local costFrame = contextFrame and contextFrame:FindFirstChild('CostFrame')

        costFrame = costFrame and costFrame:FindFirstChild('Amount')

        local character = waitForTalentData()

        if not isArmed(ax.generation) or not buyButton or not costFrame or not br(buyButton) or not buyButton.AutoButtonColor or tonumber(costFrame.Text) ~= deal.cost or not character or (talentPicker.knowledge(character) or 0) < (deal.totalCost or deal.cost) + ((getSession().mode == 'talents' or getSession().phase == 'post') and 0 or 10) then
            return false, 'Shrine of Chance deal could not be verified'
        end

        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')

        if not playerGui or choicePrompt and choicePrompt.Enabled then
            return false, 'Shrine of Chance donor prompt needs verification'
        end

        local errorMsg
        local connection = playerGui.DescendantAdded:Connect(function(descendant)
            if descendant:IsA('TextLabel') and descendant:FindFirstAncestor('SimplePrompt') and descendant.Text == 'You do not currently meet the requirements for any Talents.' then
                errorMsg = 'No eligible talents offered by Shrine of Chance'
            end
        end)
        local state = getSession()

        state.pending = {
            kind = 'chance',
            stage = 'shop',
            job = game.JobId,
            target = deal.target,
            donor = deal.donor,
            deal = deal.deal,
            cost = deal.cost,
            totalCost = deal.totalCost,
            conversion = deal.conversion,
            outputRarity = deal.outputRarity,
            knowledge = talentPicker.knowledge(character),
            at = os.time(),
        }

        setSession(state)
        delayedTask.methodWithDelay(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', 3, {
            shopchoice = deal.deal,
        })

        local deadline = os.clock() + 15
        local prompt

        repeat
            prompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')

            if errorMsg or prompt and prompt.Enabled then
                break
            end

            task.wait(0.2)
        until os.clock() > deadline or not isArmed(ax.generation)

        connection:Disconnect()

        if errorMsg then
            state.pending = nil

            setSession(state)
            bt()

            return false, errorMsg
        end

        local choiceFrame = prompt and prompt:FindFirstChild('ChoiceFrame')

        choiceFrame = choiceFrame and choiceFrame:FindFirstChild('DescSheet')

        local promptLabel = choiceFrame and choiceFrame:FindFirstChild('Prompt')
        local choicesFrame = choiceFrame and choiceFrame:FindFirstChild('ScrollingFrame')

        if not promptLabel or not promptLabel.Text:find('Choose a Talent', 1, true) or not choicesFrame then
            if isArmed(ax.generation) then
                ax.hopRequested = true
                ax.progress = 'Switching servers: Shrine of Chance did not respond'

                noEffects.hop(getSession().slot, true)
            end

            return false, 'Shrine of Chance donor prompt needs verification'
        end

        local selectedButton

        for index, button in ipairs(choicesFrame:GetChildren())do
            if button:IsA('TextButton') and br(button) and sanitizeString(button.Name) == deal.donor and shouldProcessTalent(ax.build, deal.donor, getOwnedTalents(character), true, deal.target) then
                selectedButton = button

                break
            end
        end

        if not selectedButton then
            local knowledge = getOwnedTalents(character)
            local rarity = deal.deal == 'Talent Elevation' and 'common' or deal.deal == 'Talent Degradation' and 'rare' or normalizeRarity(ax.build.metadata[deal.target])

            for buttonIndex, card in ipairs(choicesFrame:GetChildren())do
                local talentMeta = ax.build.metadata[sanitizeString(card.Name)]

                if card:IsA('TextButton') and card.Visible and talentMeta and normalizeRarity(talentMeta) == rarity and shouldProcessTalent(ax.build, sanitizeString(card.Name), knowledge, true, deal.target) then
                    selectedButton = card

                    break
                end
            end
        end
        if not selectedButton then
            local cp = prompt:FindFirstChild('TalentChoice')

            if cp then
                pcall(delayedTask.methodWithDelay, cp, 'InvokeServer', 1.5, false)
            end

            state.pending = nil

            setSession(state)
            bt()

            return false, 'Safe donor talent was not offered'
        end

        state = getSession()
        state.pending.stage = 'donor'
        state.pending.donor = sanitizeString(selectedButton.Name)
        state.pending.at = os.time()

        setSession(state)

        local confirmRemote = prompt:FindFirstChild('TalentChoice')

        if not isArmed(ax.generation) or not confirmRemote or not pcall(delayedTask.methodWithDelay, confirmRemote, 'InvokeServer', 1.5, selectedButton.Name) then
            return false, 'Shrine of Chance donor was not confirmed'
        end

        return b9(deal)
    end

    b9 = function(options)
        local shrine
        local deadline = os.clock() + 10
        local snapshot
        local choice, pickToken

        repeat
            task.wait(0.2)

            snapshot = talentPicker.data()
            choice, pickToken = talentPicker.choice(snapshot)

            if choice and choice.Selection and #choice.Selection > 0 then
                break
            end
        until os.clock() > deadline or not isArmed(ax.generation)

        if not choice or not choice.Selection or #choice.Selection == 0 then
            return false, 'Shrine of Chance card hand needs verification'
        end

        local selected

        for index, card in ipairs(choice.Selection)do
            local key = sanitizeString(card.RichName or card.Name)

            if key == options.target or sanitizeString(card.Name) == options.target then
                selected = card

                break
            end
        end

        if not selected and not options.conversion then
            local talentMap = getSession().mode == 'talents' and talentPicker.statTalents(ax.build) or ax.build.talents

            for candidate, candidate in ipairs(choice.Selection)do
                local nameKey = sanitizeString(candidate.RichName or candidate.Name)

                if (talentMap[nameKey] or talentMap[sanitizeString(candidate.Name)]) and not getOwnedTalents(snapshot)[nameKey] then
                    selected = candidate

                    break
                end
            end
        end
        if not selected then
            local known = getOwnedTalents(snapshot)

            for candidate, candidate in ipairs(choice.Selection)do
                local nameKey = sanitizeString(candidate.RichName or candidate.Name)
                local meta = ax.build.metadata[nameKey]
                local valid = meta and (not options.outputRarity or normalizeRarity(meta) == options.outputRarity) and shouldProcessTalent(ax.build, nameKey, known, true, options.target)
                local talents = getSession().mode == 'talents' and talentPicker.statTalents(ax.build) or ax.build.talents

                for talentKey in pairs(talents)do
                    local cr = ax.build.metadata[talentKey]

                    if not cr then
                        valid = false

                        break
                    end

                    for idx, exclusiveId in ipairs(meta and meta.exclusive_with_ids or {})do
                        if exclusiveId == cr.id then
                            valid = false
                        end
                    end
                    for idx, exclusiveId in ipairs(cr.exclusive_with_ids or {})do
                        if meta and exclusiveId == meta.id then
                            valid = false
                        end
                    end
                end

                if valid then
                    selected = candidate

                    break
                end
            end
        end
        if not selected then
            return false, 'No safe Shrine of Chance card was offered'
        end

        shrine = getSession()

        if not shrine.pending or shrine.pending.kind ~= 'chance' then
            return false, 'Shrine of Chance transaction changed'
        end
        if shrine.pending.stage ~= 'card' then
            shrine.pending.stage = 'card'
            shrine.pending.selected = selected.Name
            shrine.pending.selectedKey = sanitizeString(selected.RichName or selected.Name)
            shrine.pending.at = os.time()

            setSession(shrine)

            if not isArmed(ax.generation) or not talentPicker.pick(selected, pickToken) then
                return false, 'Shrine of Chance card selection was not confirmed'
            end
        end

        deadline = os.clock() + 8

        repeat
            task.wait(0.2)

            snapshot = waitForTalentData()

            if snapshot and canAffordTalent(shrine.pending, snapshot) then
                if not bt() then
                    return false, 'Shrine dialogue did not close'
                end

                ca(shrine.pending)

                return true
            end
        until os.clock() > deadline or not isArmed(ax.generation)

        return false, 'Shrine of Chance result needs verification'
    end

    local finalizeTomeUse = function(knowledge)
        local tool = ax.tomeUse and ax.tomeUse.tool or findMoonseyeTome()
        local knownKnowledge = ax.tomeUse and ax.tomeUse.knowledge or talentPicker.knowledge(knowledge)
        local generation = ax.generation

        if ax.tomeUse and (talentPicker.knowledge(knowledge) or 0) > knownKnowledge then
            showProgress('Waiting for Moonseye Tome effects', 2)

            ax.tomeUse = nil

            return isArmed(generation)
        end
        if ax.tomeUse and (not tool.Parent or tool.Parent ~= getBackpack() and tool.Parent ~= noEffects.localPlayer.character) then
            return false, 'use-unconfirmed'
        end
        if not tool then
            return false, 'no-tome'
        end
        if not knownKnowledge or not noEffects.localPlayer.humanoid then
            return false
        end
        if tool.Parent ~= noEffects.localPlayer.character then
            delayedTask.method(noEffects.localPlayer.humanoid, 'EquipTool', tool)
        end

        local deadline = os.clock() + 6

        while isArmed(generation) and tool.Parent ~= noEffects.localPlayer.character and os.clock() < deadline do
            task.wait(0.1)
        end

        if not isArmed(generation) then
            return false, 'cancelled'
        end
        if tool.Parent ~= noEffects.localPlayer.character then
            return false, findMoonseyeTome() and 'equip-failed' or 'no-tome'
        end

        showProgress('Preparing Moonseye Tome', 0.75)

        if not isArmed(generation) then
            return false, 'cancelled'
        end
        if tool.Parent ~= noEffects.localPlayer.character or not tool.Enabled then
            return false, 'equip-not-ready'
        end

        ax.tomeUse = {
            tool = tool,
            knowledge = knownKnowledge,
        }

        delayedTask.method(tool, 'Activate')

        deadline = os.clock() + 10

        repeat
            task.wait(0.2)

            local currentKnowledge = talentPicker.knowledge(waitForTalentData())

            if currentKnowledge and currentKnowledge > knownKnowledge then
                showProgress('Waiting for Moonseye Tome effects', 2)

                ax.tomeUse = nil

                return isArmed(generation)
            end
        until os.clock() > deadline or not isArmed(generation)

        return false, isArmed(generation) and 'use-unconfirmed' or 'cancelled'
    end

    function ax.cb(gui)
        if not gui then
            return
        end

        local choicePrompt = gui.Parent and gui.Parent:FindFirstChild('ChoicePrompt')

        if choicePrompt and choicePrompt:IsA('ScreenGui') then
            choicePrompt.Enabled = false
        end

        local exitButton = gui:FindFirstChild('Exit', true)

        if exitButton and exitButton:IsA('GuiButton') then
            pcall(bv, exitButton)
        end

        pcall(function()
            gui.Enabled = false
        end)
    end
    function ax.bt(shards)
        local generation = ax.generation

        if not placeIds.isEastern() or not workspace:FindFirstChild('NPCs') or not workspace.NPCs:FindFirstChild('Banker') then
            if not bq(CFrame.new(-7495.73633, 45.3529663, 3191.0415), 'Checking bank for Moonseye Tome') then
                return false, 'travel-failed'
            end
        end
        if not isArmed(generation) then
            return false, 'cancelled'
        end

        local npcs = workspace:FindFirstChild('NPCs')

        npcs = npcs and npcs:FindFirstChild('Banker')

        local bankerRoot = npcs and npcs:FindFirstChild('HumanoidRootPart')

        if not bankerRoot then
            return false, 'banker-missing'
        end

        local playerRoot = bo()

        if not playerRoot or (playerRoot.Position - bankerRoot.Position).Magnitude > 8 then
            if not bq(bankerRoot.CFrame * CFrame.new(0, 0, -3), 'Checking bank for Moonseye Tome') then
                return false, 'travel-failed'
            end
        end

        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')

        if not playerGui then
            return false, 'bank-ui-missing'
        end

        local deadline = os.clock() + 15

        repeat
            if not isArmed(generation) then
                return false, 'cancelled'
            end

            local bankGui = playerGui:FindFirstChild('BankGui')

            if bankGui and bankGui.Enabled then
                break
            end

            local dialogueGui = playerGui:FindFirstChild('DialogueGui')

            if dialogueGui and dialogueGui.Enabled then
                pcall(delayedTask.method, noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {
                    choice = 'Can I access my account?',
                })
            else
                pcall(delayedTask.call, fire, npcs:FindFirstChild('InteractPrompt'))
            end

            task.wait(0.75)
        until os.clock() >= deadline

        local bankGui = playerGui:FindFirstChild('BankGui')

        if not bankGui or not bankGui.Enabled then
            return false, 'bank-ui-missing'
        end

        local itemScroll = bankGui:FindFirstChild('ItemScroll', true)
        local loadingIndicator = bankGui:FindFirstChild('Loading', true)

        deadline = os.clock() + 8

        while isArmed(generation) and (not itemScroll or loadingIndicator and loadingIndicator.Visible) and os.clock() < deadline do
            task.wait(0.2)

            itemScroll = bankGui:FindFirstChild('ItemScroll', true)
        end

        if not isArmed(generation) then
            ax.cb(bankGui)

            return false, 'cancelled'
        end
        if not itemScroll or loadingIndicator and loadingIndicator.Visible then
            ax.cb(bankGui)

            return false, 'bank-loading'
        end

        local foundItem

        for index, item in ipairs(itemScroll:GetChildren())do
            local label = item:FindFirstChild('Label')

            if label and label:IsA('TextLabel') and label.Text == 'Moonseye Tome' then
                foundItem = item

                break
            end
        end

        if not foundItem then
            ax.cb(bankGui)

            return false, 'not-found'
        end

        local sellContext = foundItem:FindFirstChild('SellContext')
        local sellButton = sellContext and sellContext:FindFirstChild('SellOne')
        local connections

        if sellButton and getconnections then
            local ok, cs = pcall(getconnections, sellButton.MouseButton1Click)

            if ok then
                connections = cs
            end
        end

        local itemId

        if connections and debug.getupvalues then
            for index, connection in ipairs(connections)do
                if connection.Function then
                    local ok, upvalues = pcall(debug.getupvalues, connection.Function)

                    if ok then
                        for index, upvalue in pairs(upvalues)do
                            if type(upvalue) == 'table' and type(upvalue.Tools) == 'table' then
                                local tool = upvalue.Tools[1]

                                if tool and tool.id then
                                    itemId = tool.id

                                    break
                                end
                            end
                        end
                    end
                end
                if itemId then
                    break
                end
            end
        end

        local choiceButton = bankGui:FindFirstChild('Choice')

        if not itemId or not choiceButton then
            ax.cb(bankGui)

            return false, 'bank-item-id-missing'
        end

        delayedTask.method(choiceButton, 'FireServer', 'withdraw', {itemId})

        deadline = os.clock() + 5

        local confirmed = false

        repeat
            if not isArmed(generation) then
                ax.cb(bankGui)

                return false, 'cancelled'
            end
            if findMoonseyeTome() then
                ax.cb(bankGui)
                showProgress('Waiting for bank withdrawal to settle', 2)

                if not isArmed(generation) then
                    return false, 'cancelled'
                end

                return true
            end

            local choicePrompt = playerGui:FindFirstChild('ChoicePrompt')

            if choicePrompt and choicePrompt.Enabled and choicePrompt:GetAttribute('Title') == 'Vow of Safekeeping' and not confirmed then
                local choiceButton = choicePrompt:FindFirstChild('Choice')

                if not choiceButton then
                    ax.cb(bankGui)

                    return false, 'bank-confirmation-missing'
                end

                delayedTask.method(choiceButton, 'FireServer', shards >= 1)

                if shards < 1 then
                    ax.cb(bankGui)

                    return false, 'insufficient-knowledge'
                end

                confirmed = true
            end

            task.wait(0.25)
        until os.clock() >= deadline

        local hasShards = findMoonseyeTome() ~= nil

        ax.cb(bankGui)

        if hasShards then
            showProgress('Waiting for bank withdrawal to settle', 2)

            if not isArmed(generation) then
                return false, 'cancelled'
            end
        end
        if hasShards then
            return true
        end

        return false, 'withdraw-unconfirmed'
    end

    local waitForKnowledgeTarget = function(character, state, phase, targetKnowledge)
        local knowledge = talentPicker.knowledge(character)

        if not knowledge then
            showProgress('Waiting for Knowledge data', 2)

            return true
        end
        if knowledge >= targetKnowledge then
            if ax.tomeUse and knowledge > ax.tomeUse.knowledge then
                showProgress('Waiting for Moonseye Tome effects', 2)

                ax.tomeUse = nil

                ax.recovery:clear('tome')
            end

            handleAutomationChild(nil)
            migrateTitusSettings()

            local resumeState = getSession()

            if resumeState.resume then
                resumeState.resume = nil

                setSession(resumeState)
            end

            return false
        end
        if findMoonseyeTome() or ax.tomeUse then
            if placeIds.isDungeon() then
                showProgress('Leaving Titus with Moonseye Tome', 2)

                return true
            end

            handleAutomationChild(nil)

            ax.progress = 'Using Moonseye Tome'

            local usedTome, tomeStatus = finalizeTomeUse(character)

            if usedTome then
                ax.recovery:clear('tome')
                migrateTitusSettings()

                local nextState = getSession()

                nextState.resume = nil

                setSession(nextState)
            elseif tomeStatus ~= 'no-tome' and tomeStatus ~= 'cancelled' then
                if ax.recovery:retry('tome') then
                    talentPicker.resetData()
                    showProgress('Rechecking Moonseye Tome use', 3)
                else
                    ax.hopRequested = true
                    ax.progress = 'Switching servers: Moonseye Tome use unconfirmed'

                    noEffects.hop(getSession().slot, true)
                end
            end

            return true
        end
        if state.resume ~= phase then
            state.resume = phase

            setSession(state)
        end
        if not placeIds.isDungeon() and itemFilters.full() then
            handleAutomationChild(nil)
            showProgress('Inventory full', 2)

            return true
        end
        if not placeIds.isDungeon() then
            local bankKey = phase .. ':' .. tostring(knowledge)

            if state.bankCheckedFor ~= bankKey then
                handleAutomationChild(nil)

                ax.progress = 'Checking bank for Moonseye Tome'

                local bankSuccess, bankResult = ax.bt(knowledge)

                if bankSuccess then
                    ax.recovery:clear('bank:' .. bankKey)

                    return true
                end
                if bankResult == 'cancelled' then
                    return true
                end
                if bankResult ~= 'not-found' and bankResult ~= 'insufficient-knowledge' then
                    if ax.recovery:retry('bank:' .. bankKey) then
                        showProgress('Retrying bank check: ' .. tostring(bankResult), 3)

                        return true
                    end
                end

                state.bankCheckedFor = bankKey

                setSession(state)
            end
        end
        if ax.child ~= 'auto_titus' then
            local relics = noEffects.value('auto_titus_relics', {})
            local updatedRelics = table.clone(relics)

            updatedRelics['Moonseye Tome'] = true
            state.titusRelics = relics
            state.titusBankItems = noEffects.value('auto_titus_bank_items', {})

            setSession(state)
            noEffects.setValue('auto_titus_relics', updatedRelics)
            noEffects.setValue('auto_titus_bank_items', {})
        end
        if not placeIds.isDungeon() and not handleAutomationChild('auto_titus') then
            showProgress('Waiting to start Titus', 2)
        else
            showProgress('Farming Moonseye Tome', 2)
        end

        return true
    end
    local isInTrialOfOne = function()
        return workspace:FindFirstChild('One') ~= nil or tostring(noEffects.localPlayer.instance:GetAttribute('CurrentArea') or ''):find('Trial of One', 1, true) ~= nil
    end
    local cf = {
        'Head',
        'Ears',
        'Face',
        'Torso',
        'Arms',
        'Legs',
        'Ring1',
        'Ring2',
        'Ring3',
        'Ring4',
    }
    local findEquipFrame = function()
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local backpackGui = playerGui and playerGui:FindFirstChild('BackpackGui')
        local rightFrame = backpackGui and backpackGui:FindFirstChild('RightFrame')
        local journalFrame = rightFrame and rightFrame:FindFirstChild('JournalFrame')
        local panels = journalFrame and journalFrame:FindFirstChild('Panels')

        return panels and panels:FindFirstChild('EquipFrame')
    end
    local isEquipmentEquipped = function(character, player, equipmentName)
        local equipment = character and character.Equipment
        local slotValue = type(equipment) == 'table' and equipment[equipmentName]

        if slotValue ~= nil and slotValue ~= false and slotValue ~= '' then
            return true
        end

        local item = player and player:FindFirstChild(equipmentName)

        return item and item:GetAttribute('Equipped') == true or false
    end
    local unequipPlayerEquipment = function(targetPlayer)
        local requests = game:GetService('ReplicatedStorage'):FindFirstChild('Requests')
        local unequipRemote = requests and requests:FindFirstChild('Unequip')

        if not unequipRemote then
            return false
        end

        local unequipOwner = findEquipFrame()
        local currentCharacter = waitForTalentData()

        if not isArmed(targetPlayer) or not currentCharacter then
            return false
        end

        for index, slotName in ipairs(cf)do
            if not isArmed(targetPlayer) then
                return false
            end
            if isEquipmentEquipped(currentCharacter, unequipOwner, slotName) then
                ax.progress = 'Unequipping ' .. slotName .. ' for Trial of One'

                local success, result = pcall(delayedTask.method, unequipRemote, 'InvokeServer', slotName, true)

                if not success or not result then
                    return false
                end

                talentPicker.resetData()
                task.wait(0.2)

                currentCharacter = waitForTalentData()
                unequipOwner = findEquipFrame()

                if not currentCharacter or isEquipmentEquipped(currentCharacter, unequipOwner, slotName) then
                    return false
                end
            end
        end

        return true
    end
    local isInDepthsTrial = function()
        return workspace:FindFirstChild('DepthsTrial') ~= nil or workspace:FindFirstChild('DepthTrialArena') ~= nil
    end

    ca = function(pendingAction)
        local progressionState = getSession()

        if pendingAction.conversion and pendingAction.selectedKey ~= pendingAction.target then
            progressionState.chanceChain = {
                target = pendingAction.target,
                donor = pendingAction.selectedKey,
            }
        elseif progressionState.chanceChain and progressionState.chanceChain.target == pendingAction.target then
            progressionState.chanceChain = nil
        end

        progressionState.pending = nil
        progressionState.paused = nil
        progressionState.pausedSignature = nil

        setSession(progressionState)
    end

    local processPendingChanceState = function(order, state, talentCharacter)
        local choices = getOwnedTalents(talentCharacter)
        local changed = false

        if state.chanceChain and (choices[state.chanceChain.target] or not choices[state.chanceChain.donor]) then
            state.chanceChain = nil
            changed = true
        end
        if state.pending then
            local pending = state.pending

            if pending.kind == 'chance' then
                if canAffordTalent(pending, talentCharacter) then
                    ca(pending)

                    state = getSession()
                else
                    local choice = talentPicker.choice(talentCharacter)
                    local knowledge = talentPicker.knowledge(talentCharacter)

                    if choice and knowledge and pending.knowledge and knowledge < pending.knowledge then
                        pending.stage = 'donor'
                        pending.at = 0
                        changed = true
                    elseif not choice or pending.stage == 'shop' then
                        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')

                        playerGui = playerGui and playerGui:FindFirstChild('ChoicePrompt')

                        local talentPrompt = playerGui and playerGui:FindFirstChild('TalentChoice')

                        if talentPrompt then
                            pcall(delayedTask.method, talentPrompt, 'InvokeServer', false)
                        end

                        state.pending = nil
                        changed = true
                    end
                end
            elseif pending.kind == 'order' then
                local differs = false

                for stat, expectedValue in pairs(pending.stats or {})do
                    if (talentCharacter['Stat' .. stat] or 0) ~= expectedValue then
                        differs = true

                        break
                    end
                end

                if differs then
                    state.phase = 'post'
                    state.phaseConfirmed = true
                    state.phaseSource = 'verified'
                    state.orderVerifiedFor = buildCharacterKey(talentCharacter) .. ':' .. order.url
                    state.reconcileState = 'partial_post'
                end

                state.pending = nil
                changed = true
            end
        end
        if state.paused or state.pausedSignature then
            state.paused = nil
            state.pausedSignature = nil
            changed = true
        end
        if changed then
            setSession(state)
        end
    end
    local saveSessionFeatures = function()
        noEffects.enableFeature('PlayerProximity')
        noEffects.enableFeature('NotifyMod')

        ax.sessionFeatures = ax.sessionFeatures or {
            Flight = noEffects.featureActive('Flight'),
            NoClip = noEffects.featureActive('NoClip'),
            FastSwing = noEffects.featureActive('FastSwing'),
            NoStun = noEffects.featureActive('NoStun'),
            NoFire = noEffects.featureActive('NoFire'),
            NoAcidWater = noEffects.featureActive('NoAcidWater'),
            NoKillBricks = noEffects.featureActive('NoKillBricks'),
            NoSpeedDebuff = noEffects.featureActive('NoSpeedDebuff'),
            AutoWisp = noEffects.featureActive('AutoWisp'),
            MantraSilentAim = noEffects.featureActive('MantraSilentAim'),
            AutoDeclineGuild = noEffects.featureActive('AutoDeclineGuild'),
            AutoDeclineSquad = noEffects.featureActive('AutoDeclineSquad'),
            EnableAutoParry = noEffects.featureActive('EnableAutoParry'),
            BlockInput = noEffects.featureActive('BlockInput'),
        }

        for feature in pairs(ax.sessionFeatures)do
            noEffects.enableFeature(feature)
        end

        local userInput = noEffects.services.UserInputService
        local localPlayer = noEffects.localPlayer.instance

        if not ax.shiftLockState then
            ax.shiftLockState = {
                mouseBehavior = userInput.MouseBehavior,
                enabled = localPlayer.DevEnableMouseLock,
            }
            ax.shiftLockConnections = {
                userInput:GetPropertyChangedSignal('MouseBehavior'):Connect(function(
                )
                    if ax:armed() and userInput.MouseBehavior ~= Enum.MouseBehavior.Default then
                        userInput.MouseBehavior = Enum.MouseBehavior.Default
                    end
                end),
                localPlayer:GetPropertyChangedSignal('DevEnableMouseLock'):Connect(function(
                )
                    if ax:armed() and localPlayer.DevEnableMouseLock then
                        localPlayer.DevEnableMouseLock = false
                    end
                end),
            }
        end

        pcall(function()
            localPlayer.DevEnableMouseLock = false
        end)

        userInput.MouseBehavior = Enum.MouseBehavior.Default
    end

    function ax:stopTraining()
        if not self.trainingFeatures then
            return
        end

        for featureName, featureValue in pairs(self.trainingFeatures)do
            noEffects.setFeature(featureName, featureValue)
        end

        self.trainingFeatures = nil
    end

    local restoreSessionFeatures = function()
        if not ax.sessionFeatures then
            return
        end

        for sessionFeatureName, sessionFeatureValue in pairs(ax.sessionFeatures)do
            noEffects.setFeature(sessionFeatureName, sessionFeatureValue)
        end

        ax.sessionFeatures = nil

        if ax.shiftLockConnections then
            for index, connection in ipairs(ax.shiftLockConnections)do
                connection:Disconnect()
            end

            ax.shiftLockConnections = nil
        end
        if ax.shiftLockState then
            local userInputService = noEffects.services.UserInputService
            local player = noEffects.localPlayer.instance
            local shiftLockState = ax.shiftLockState

            pcall(function()
                player.DevEnableMouseLock = shiftLockState.enabled
            end)

            userInputService.MouseBehavior = shiftLockState.mouseBehavior
            ax.shiftLockState = nil
        end
    end
    local hasFatePrompt = function()
        if not isInTrialOfOne() then
            return false
        end

        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')
        local choiceFrame = choicePrompt and choicePrompt:FindFirstChild('ChoiceFrame')
        local title = choiceFrame and choiceFrame:FindFirstChild('Title')
        local options = choiceFrame and choiceFrame:FindFirstChild('Options')
        local deathButton = options and options:FindFirstChild('Death')

        if not title or title.Text ~= 'Fate of One' or not deathButton or not deathButton:IsA('GuiButton') or not br(choicePrompt) or not br(choiceFrame) or not br(deathButton) then
            return false
        end

        ax.progress = 'Trial: choosing Death'

        clickHolder.set(false)

        local trialState = getSession()

        if not trialState.trialDeathChosen and os.clock() >= (ax.trialDeathAt or 0) then
            ax.trialDeathAt = os.clock() + 2

            local clickSuccess, clickResult = pcall(bv, deathButton)

            if clickSuccess and clickResult then
                trialState.trialDeathChosen = true
                trialState.trialActive = nil
                trialState.trialJob = nil
                trialState.trialStep = nil

                setSession(trialState)
            end
        end

        return true
    end
    local startStatsLoop = function(config)
        ax.statsThread = task.spawn(function()
            local lastActionTime = 0

            while isArmed(config) do
                if hasFatePrompt() then
                    task.wait(0.2)

                    continue
                end
                if os.clock() >= lastActionTime then
                    saveSessionFeatures()

                    lastActionTime = os.clock() + 1
                end

                local pcallOk = pcall(function()
                    local state = getSession()
                    local build = ax.build
                    local talentData = talentPicker.data()
                    local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

                    if build and talentData and (not dataSlot or tostring(dataSlot) == tostring(state.slot)) then
                        updateMantraTraining(build, talentData)
                    end
                    if state.ministryReportQuest == 'verify' or state.arthurQuest == 'verify' or state.atraQuest == 'verify' then
                        return
                    end
                    if not ax.child and not state.paused and not state.talentCleanup and state.activeTask ~= 'unbound_willpower' and state.activeTask ~= 'unbound_strength' and state.activeTask ~= 'unbound_fortitude' and state.activeTask ~= 'unbound_intelligence' and state.activeTask ~= 'unbound_ferryman' and not state.unboundFerrymanStage and build and talentData and (not dataSlot or tostring(dataSlot) == tostring(state.slot)) then
                        talentPicker.favour(talentData, build)
                    end
                    if state.mode ~= 'talents' and not state.talentCleanup and state.activeTask ~= 'unbound_willpower' and state.activeTask ~= 'unbound_strength' and state.activeTask ~= 'unbound_fortitude' and state.activeTask ~= 'unbound_intelligence' and state.activeTask ~= 'unbound_ferryman' and state.activeTask ~= 'unification' and not state.unboundFerrymanStage and state.phaseConfirmed and state.reconcileState ~= 'pre_cards' and not state.paused and not state.pending and not ax.prompt and build and talentData and noEffects.localPlayer.humanoid and noEffects.localPlayer.humanoid.Health > 0 and (not dataSlot or tostring(dataSlot) == tostring(state.slot)) then
                        local buildPhase = state.phase == 'post' and build.post or build.pre

                        if selectNextUnboundStat(talentData, buildPhase, build, state.phase, state.unboundFerrymanCompleted) then
                            talentPicker.cancelSpend()
                            progressionTraining.restorePassive()

                            ax.trainingStat = nil

                            return
                        end

                        local weakMismatch = state.phase ~= 'post' and talentPicker.mismatch(talentData, build.pre) and (talentPicker.power(talentData) or 99) <= 5 and state.declinedWipeFor ~= build.url

                        if not weakMismatch then
                            if ax.trainingBusy then
                                if ax.trainingBusy ~= 'Intelligence' and ax.trainingBusy ~= 'Charisma' then
                                    progressionTraining.restorePassive()
                                end

                                return
                            end

                            local autoAuthorityMissions = getAutomationHandler(talentData) == 'auto_authority_missions'

                            if not autoAuthorityMissions and not ax.child and not isInTrialOfOne() and not ax.trialFeatures and not state.trialActive then
                                progressionTraining.enablePassive(talentData, buildPhase)
                            else
                                progressionTraining.restorePassive()
                            end

                            local preTalents = state.phase == 'post' and {} or talentPicker.preTalents(build)

                            if talentPicker.choice(talentData) then
                                ax.trainingStat = nil
                                preTalents = table.clone(preTalents)

                                for mantraName, mantraId in pairs(state.phase == 'post' and {} or talentPicker.preMantras(build))do
                                    preTalents[mantraName] = mantraId
                                end
                                for trainingMantra, mantraValue in pairs(talentPicker.trainingMantras(talentData))do
                                    preTalents[trainingMantra] = mantraValue
                                end

                                talentPicker.choose(talentData, preTalents, build)

                                return
                            end

                            local charFortitude = tonumber(talentData.StatFortitude) or 0
                            local buildFortitude = tonumber(buildPhase.Fortitude) or 0
                            local trainingMet = talentData.AttributeTrainingMet
                            local fortitudeTrained = type(trainingMet) == 'table' and (trainingMet.Fortitude or trainingMet.StatFortitude or trainingMet.Stat_Fortitude)
                            local nextStat = talentPicker.nextStat(talentData, buildPhase, build, state.phase)

                            if not autoAuthorityMissions and not isInTrialOfOne() and not ax.trialFeatures and not state.trialActive and nextStat == 'Fortitude' and charFortitude < buildFortitude and fortitudeTrained ~= true and fortitudeTrained ~= 1 and (tonumber(talentData.FreeAttributePoints) or 0) <= 0 and (tonumber(talentData.FullAttributePoints) or 0) <= 0 then
                                ax.trainingStat = 'Fortitude'
                            else
                                local spendResult, spendStatus, spendValue = talentPicker.spend(talentData, buildPhase, build, state.phase)

                                ax.trainingStat = not autoAuthorityMissions and spendStatus == 'training' and spendValue or nil
                            end
                        end
                    else
                        progressionTraining.restorePassive()
                    end
                end)

                task.wait(pcallOk and 0.05 or 1)
            end

            progressionTraining.restorePassive()
        end)
    end
    local startTraining = function(cp, playerData, targets)
        if ax.child and not executionQueue.request(ax, 'training') then
            return false
        end
        if isInTrialOfOne() or ax.trialFeatures or getSession().trialActive then
            progressionTraining.restorePassive()

            return false
        end

        local state = getSession()
        local nextStat = talentPicker.nextStat(playerData, targets, ax.build, state.phase)

        ax.goalStat = nextStat

        local shouldWipe = state.phase ~= 'post' and talentPicker.mismatch(playerData, ax.build.pre) and (talentPicker.power(playerData) or 99) <= 5 and state.declinedWipeFor ~= ax.build.url

        if nextStat and state.mode ~= 'talents' and not state.talentCleanup and not shouldWipe and not state.paused and not state.pending and state.phaseConfirmed and state.reconcileState ~= 'pre_cards' and not talentPicker.choice(playerData) and (tonumber(playerData.FullAttributePoints) or 0) > 0 then
            showProgress('Allocating ' .. nextStat, 0.1)

            return true
        end
        if (state.activeTask == 'intelligence' or state.activeTask == 'charisma') and state.activeTask ~= (nextStat and nextStat:lower()) then
            state.activeTask = nil

            setSession(state)
        end

        local trainingStat = state.activeTask == 'fortitude' and 'Fortitude' or ax.trainingRetryStat == 'Fortitude' and 'Fortitude' or nextStat == 'Fortitude' and 'Fortitude' or (nextStat == 'Intelligence' or nextStat == 'Charisma') and nextStat or ax.trainingStat

        if not trainingStat or trainingStat ~= 'Fortitude' and trainingStat ~= 'Intelligence' and trainingStat ~= 'Charisma' and (not talentPicker.trainingNeeded(playerData, trainingStat) or talentPicker.points(playerData) <= 0) then
            return false
        end
        if trainingStat == 'Fortitude' and nextStat ~= 'Fortitude' then
            if state.activeTask == 'fortitude' then
                noEffects.automation.forceSkyAfterFortitude = true
            end

            state.activeTask = nil

            setSession(state)

            ax.trainingRetryStat = nil
            ax.trainingRetry = nil
            ax.trainingStat = nil

            return false
        end
        if trainingStat ~= ax.trainingRetryStat then
            ax.trainingRetryStat = trainingStat
            ax.trainingRetry = nil
        end
        if trainingStat == 'Intelligence' or trainingStat == 'Charisma' then
            if nextStat ~= trainingStat or (tonumber(playerData['Stat' .. trainingStat]) or 0) >= (tonumber(targets[trainingStat]) or 0) then
                if state.activeTask == trainingStat:lower() then
                    state.activeTask = nil

                    setSession(state)
                end

                return false
            end
            if talentPicker.points(playerData) <= 0 then
                ax.trainingRetry = nil

                if handleAutomationChild(getAutomationHandler(playerData)) then
                    showProgress('Farming XP for ' .. trainingStat, 1)
                else
                    showProgress('Waiting to farm XP for ' .. trainingStat, 1)
                end

                return true
            end
            if placeIds.isDungeon() or not placeIds.isEastern() then
                return false
            end
            if state.activeTask ~= trainingStat:lower() then
                state.activeTask = trainingStat:lower()
                state.ferrymanCycle = nil

                setSession(state)
            end
            if type(playerData.AttributeTrainingMet) == 'table' and not talentPicker.trainingNeeded(playerData, trainingStat) then
                ax.trainingRetry = nil

                if talentPicker.points(playerData) <= 0 then
                    handleAutomationChild(getAutomationHandler(playerData))
                    showProgress('Farming XP for ' .. trainingStat, 1)
                else
                    handleAutomationChild(nil)
                    showProgress('Allocating ' .. trainingStat, 0.5)
                end

                return true
            end
            if tick() < (ax.trainingRetry or 0) then
                showProgress('Waiting to retry ' .. trainingStat .. ' training', 1)

                return true
            end
            if not handleAutomationChild(nil) then
                showProgress('Waiting for movement control', 2)

                return true
            end

            local bookName = trainingStat == 'Intelligence' and 'Math Textbook' or 'How to Make Friends'
            local nearbyCharacter = getBackpack()
            local playerCharacter = noEffects.localPlayer.character

            if not (nearbyCharacter and nearbyCharacter:FindFirstChild(bookName) or playerCharacter and playerCharacter:FindFirstChild(bookName)) then
                ax.trainingBusy = true
                ax.progress = 'Funding ' .. bookName

                local funded, fundMessage = progressionTraining.ensureTrainingFunds(function()
                    return isArmed(cp)
                end, bp, bv)

                if not funded then
                    ax.trainingBusy = nil
                    ax.trainingRetry = tick() + 15

                    showProgress('Waiting to fund ' .. bookName .. (fundMessage and ': ' .. fundMessage or ''), 2)

                    return true
                end

                ax.progress = 'Getting ' .. bookName

                local cabinet = bq(CFrame.new(-7213.19043, 560.882446, 2667.2688), 'Training gear cabinet')
                local bought, buyMessage

                if cabinet and isArmed(cp) then
                    bought, buyMessage = progressionTraining.buyBook(bookName, function()
                        return isArmed(cp)
                    end, bp, bv)
                end

                ax.trainingBusy = nil

                if not bought then
                    ax.trainingRetry = tick() + 15

                    showProgress('Waiting for ' .. bookName .. (buyMessage and ': ' .. buyMessage or ''), 2)

                    return true
                end
            end
            if trainingStat == 'Charisma' then
                local nearestNpc, bestDistance
                local npcsFolder = workspace:FindFirstChild('NPCs')
                local root = bo()

                for index, npc in ipairs(npcsFolder and npcsFolder:GetChildren() or {})do
                    if not npc:IsA('Model') then
                        continue
                    end

                    local npcRoot = npc:FindFirstChild('HumanoidRootPart') or npc.PrimaryPart
                    local humanoid = npc:FindFirstChildOfClass('Humanoid')
                    local prompt = npc:FindFirstChild('InteractPrompt', true) or npc:FindFirstChildWhichIsA('ProximityPrompt', true)

                    if npcRoot and prompt and (not humanoid or humanoid.Health > 0) and root then
                        local distance = (npcRoot.Position - root.Position).Magnitude

                        if not bestDistance or distance < bestDistance then
                            nearestNpc, bestDistance = npc, distance
                        end
                    end
                end

                local targetCframe = nearestNpc and nearestNpc:GetPivot() * CFrame.new(0, 0, -5) or CFrame.new(
-2803.5481, 144.320007, 3013.43604)

                if not bestDistance or bestDistance > 12 then
                    ax.progress = nearestNpc and 'Travelling to nearby NPC' or 'Finding a friendly NPC'

                    if not bq(targetCframe, 'Charisma training') then
                        showProgress('Waiting for a friendly NPC', 2)

                        return true
                    end
                end
                if not nearestNpc then
                    nearestNpc = npcsFolder and npcsFolder:WaitForChild('Blacksmith', 10)

                    if not nearestNpc then
                        showProgress('Waiting for a friendly NPC', 2)

                        return true
                    end
                end
            end

            ax.trainingBusy = trainingStat

            progressionTraining.restorePassive()

            ax.progress = 'Training ' .. trainingStat

            local booked, bookStatus = progressionTraining.book(playerData, trainingStat, tonumber(targets[trainingStat]) or 0, function(
            )
                return isArmed(cp) and getSession().activeTask == trainingStat:lower()
            end, bp, talentPicker.data)

            ax.trainingBusy = nil

            if bookStatus == 'complete' then
                ax.trainingRetry = nil
            elseif bookStatus == 'stalled' or bookStatus == 'unavailable' then
                ax.trainingRetry = tick() + 10
            end
            if bookStatus == 'missing-tool' then
                showProgress('Need ' .. bookName, 2)
            end

            return booked or bookStatus ~= 'not-needed'
        end
        if trainingStat == 'Fortitude' then
            if placeIds.isDungeon() or not placeIds.isEastern() then
                return false
            end
            if state.activeTask ~= 'fortitude' then
                state.activeTask = 'fortitude'
                state.ferrymanCycle = nil

                setSession(state)
            end
            if type(playerData.AttributeTrainingMet) == 'table' and not talentPicker.trainingNeeded(playerData, trainingStat) then
                if talentPicker.points(playerData) <= 0 then
                    handleAutomationChild(getAutomationHandler(playerData))
                    showProgress('Farming XP for Fortitude', 1)

                    return true
                end

                handleAutomationChild(nil)
                showProgress('Allocating Fortitude', 0.5)

                return true
            end
            if tick() < (ax.trainingRetry or 0) then
                handleAutomationChild(nil)
                showProgress('Waiting to retry Brutus training', 1)

                return true
            end

            ax.trainingBusy = true

            if not handleAutomationChild(nil) then
                ax.trainingBusy = nil

                showProgress('Waiting for movement control', 2)

                return true
            end

            ax.trainingFeatures = {
                Flight = noEffects.featureActive('Flight'),
                NoClip = noEffects.featureActive('NoClip'),
                NoFallDamage = noEffects.featureActive('NoFallDamage'),
            }

            for feature in pairs(ax.trainingFeatures)do
                noEffects.enableFeature(feature)
            end

            talentPicker.cancelSpend()

            ax.progress = 'Training Fortitude'

            local fortitudeSuccess, fortitudeStatus = progressionTraining.fortitude(playerData, targets, function()
                return isArmed(cp)
            end, bp, talentPicker.data)

            ax:stopTraining()

            ax.trainingBusy = nil

            if fortitudeStatus and fortitudeStatus:find('server', 1, true) then
                handleProgress('Brutus travel paused: ' .. fortitudeStatus)

                return true
            end
            if fortitudeStatus == 'complete' then
                ax.trainingRetry = nil
                noEffects.automation.forceSkyAfterFortitude = true
            end
            if fortitudeStatus == 'unavailable' or fortitudeStatus == 'sync-missing' or fortitudeStatus == 'timeout' or fortitudeStatus == 'attempted' then
                ax.trainingRetry = nil
            end

            return fortitudeSuccess or fortitudeStatus ~= 'not-needed'
        end
        if not progressionTraining.canPassive(playerData, targets, trainingStat) then
            return false
        end
        if not handleAutomationChild(nil) then
            showProgress('Waiting for movement control', 2)

            return true
        end

        local passiveResult = progressionTraining.enablePassive(playerData, targets)

        if passiveResult[trainingStat] then
            showProgress('Training ' .. trainingStat, 2)

            return true
        end

        return false
    end
    local findTarget = function(name, from, maxDistance)
        local liveFolder = workspace:FindFirstChild('Live')
        local closest, closestDistance

        for index, child in ipairs(liveFolder and liveFolder:GetChildren() or {})do
            if child.Name:lower():find(name:lower(), 1, true) then
                local humanoid = child:FindFirstChildOfClass('Humanoid')

                if (not humanoid or humanoid.Health > 0) and not (name == 'Megalodaunt' and child.Name:lower():find('alpha', 1, true)) then
                    if not from then
                        return child
                    end

                    local npcRoot = child:FindFirstChild('HumanoidRootPart')
                    local distance = npcRoot and (npcRoot.Position - from).Magnitude

                    if distance and distance <= (maxDistance or math.huge) and (not closestDistance or distance < closestDistance) then
                        closest, closestDistance = child, distance
                    end
                end
            end
        end

        return closest
    end
    local fireTouch = function(part)
        local character = noEffects.localPlayer.character
        local head = character and character:FindFirstChild('Head')

        if part and head then
            pcall(firetouchinterest, part, head, 0)
            pcall(firetouchinterest, part, head, 1)
        end
    end
    local runNomadTrial = function(cs, carryPart, secondCarry)
        ax.progress = 'Trial: Nomad'

        local deadline = os.clock() + 120
        local prevPoints, prevChoices
        local prepTimeout = os.clock() + 10

        if secondCarry then
            local targetPos = CFrame.new(76, 1257, 255)
            local playerRoot = bo()

            if playerRoot and (playerRoot.Position - targetPos.Position).Magnitude > 8 then
                ax.progress = 'Trial: positioning for second Nomad carry'

                if not travelRecovery.new(targetPos, true, 200).wait(8) then
                    return false, 'position'
                end
            end
        end

        while isArmed(cs) and not findTarget('Nomad') do
            local preparing = false

            if not secondCarry then
                local talentData = talentPicker.data()
                local talentChoice = talentData and talentPicker.choice(talentData)
                local talentPoints = talentData and talentPicker.points(talentData)
                local choiceList = {}

                for choiceIndex, choiceItem in ipairs(talentChoice and talentChoice.Selection or {})do
                    choiceList[#choiceList + 1] = tostring(choiceItem.Name or choiceItem.RichName)
                end

                choiceList = table.concat(choiceList, ':')

                if talentData and (talentPoints ~= prevPoints or choiceList ~= prevChoices) then
                    prevPoints, prevChoices = talentPoints, choiceList
                    deadline = os.clock() + 120
                end

                local buildData = getSession()
                local buildStage = buildData.phase == 'post' and ax.build.post or ax.build.pre
                local nextStat = talentData and talentPicker.nextStat(talentData, buildStage, ax.build, buildData.phase)
                local hasPoints = nextStat and talentPoints > 0

                preparing = not talentData or talentChoice ~= nil or hasPoints and os.clock() < prepTimeout
                ax.progress = preparing and 'Trial: preparing stats and cards' or 'Trial: waiting for Nomad'

                if not preparing then
                    fireTouch(carryPart)
                end
            end
            if os.clock() >= deadline then
                return false, preparing and 'preparation' or 'spawn'
            end

            task.wait(0.3)
        end

        if not findTarget('Nomad') then
            return false
        end

        local isCarrying = function()
            local effectReplicator = game:GetService('ReplicatedStorage'):FindFirstChild('EffectReplicator')

            if not effectReplicator then
                return false
            end

            local success, effectModule = pcall(require, effectReplicator)

            if not success or type(effectModule) ~= 'table' then
                return false
            end
            if type(effectModule.FindEffect) == 'function' then
                local found, carryingEffect = pcall(effectModule.FindEffect, effectModule, 'Carrying')

                if found and carryingEffect then
                    return true
                end
            end

            for key, effect in pairs(effectModule.Effects or {})do
                if effect.Value == 'Carrying' then
                    return true
                end
            end

            return false
        end
        local carryTimeout = os.clock() + 20
        local carrying = false
        local nextCarry = 0

        while isArmed(cs) and findTarget('Nomad') and os.clock() < carryTimeout do
            if isCarrying() then
                carrying = true

                break
            end

            local nomad = findTarget('Nomad')
            local nomadRoot = nomad and nomad:FindFirstChild('HumanoidRootPart')
            local myRoot = bo()

            if nomadRoot and myRoot then
                local carryPos = nomadRoot.Position + Vector3.new(0, 2, 3)

                if (myRoot.Position - carryPos).Magnitude > 8 then
                    ax.progress = 'Trial: approaching Nomad to carry'

                    if not travelRecovery.new(CFrame.lookAt(carryPos, nomadRoot.Position), true, 180).wait(8) then
                        return false
                    end
                end
            end

            local playerCharacter = noEffects.localPlayer.character
            local characterHandler = playerCharacter and playerCharacter:FindFirstChild('CharacterHandler')
            local requests = characterHandler and characterHandler:FindFirstChild('Requests')
            local carryRequest = requests and requests:FindFirstChild('Carry')

            if carryRequest and os.clock() >= nextCarry then
                ax.progress = 'Trial: carrying Nomad'

                pcall(delayedTask.method, carryRequest, 'FireServer')

                nextCarry = os.clock() + 0.75
            end

            task.wait(secondCarry and 0.1 or 0.8)
        end

        if not isArmed(cs) then
            return false
        end

        local localCharacter = noEffects.localPlayer.character
        local handler = localCharacter and localCharacter:FindFirstChild('CharacterHandler')
        local requestFolder = handler and handler:FindFirstChild('Requests')
        local carry = requestFolder and requestFolder:FindFirstChild('Carry')

        if findTarget('Nomad') and not (carrying or isCarrying()) then
            return false, 'carry'
        end
        if secondCarry and bo() and findTarget('Nomad') then
            local carryCFrame = bo().CFrame

            task.wait(2.5)

            if not isArmed(cs) or not bo() then
                return false
            end

            bo().CFrame = CFrame.new(carryCFrame.X, 0, carryCFrame.Z)

            task.wait(1)

            if carry and (carrying or isCarrying()) then
                pcall(delayedTask.method, carry, 'FireServer')
            end

            task.wait(1)

            if bo() then
                bo().CFrame = carryCFrame + Vector3.new(0, 10, 0)
            end
        end

        deadline = os.clock() + 25

        while isArmed(cs) and findTarget('Nomad') and os.clock() < deadline do
            task.wait(0.2)
        end

        return isArmed(cs) and not findTarget('Nomad')
    end
    local runTrial = function(character, trialName, aimOffset, isSharko, cx)
        ax.progress = isSharko and 'Finding Sharko' or 'Trial: ' .. trialName

        local deadline = os.clock() + 100
        local target

        while isArmed(character) and os.clock() < deadline and not target do
            target = findTarget(trialName, isSharko, cx)

            task.wait(0.2)
        end

        if not target then
            return false
        end
        if trialName == 'Angel' then
            noEffects.disableFeature('VoidMobs')
            noEffects.enableFeature('PathfindBreaker')
        elseif trialName == 'Enforcer' then
            noEffects.disableFeature('VoidMobs')
            noEffects.disableFeature('PathfindBreaker')
            task.wait(0.3)

            if not isArmed(character) then
                return false
            end

            noEffects.enableFeature('PathfindBreaker')
        elseif trialName == 'StoneKnight' then
            noEffects.disableFeature('PathfindBreaker')
        end

        local isAngel = trialName == 'Angel'
        local nextCriticalClick = 0
        local nextActionTime = 0
        local nextFeintTime = 0
        local killZone = workspace:FindFirstChild('One')
        local triggerPart = killZone and killZone:FindFirstChild('OneTrigger')
        local killY = triggerPart and triggerPart.Position.Y - 60
        local waitStart
        local targetDefeated = false
        local equipAttempts = 0
        local nextEquipTime = 0

        while isArmed(character) do
            local targetHumanoid = target:FindFirstChildOfClass('Humanoid')

            if not target.Parent or targetHumanoid and targetHumanoid.Health <= 0 then
                if isSharko then
                    targetDefeated = targetHumanoid ~= nil and targetHumanoid.Health <= 0

                    break
                end

                target = findTarget(trialName, isSharko, cx)

                if not target then
                    break
                end
            end

            local charRoot = bo()
            local targetRoot = target:FindFirstChild('HumanoidRootPart')
            local enemyHumanoid = target:FindFirstChildOfClass('Humanoid')
            local localHumanoid = noEffects.localPlayer.humanoid

            if not charRoot or not localHumanoid or localHumanoid.Health <= 0 then
                clickHolder.set(false)

                return false
            end
            if not targetRoot or not enemyHumanoid then
                clickHolder.set(false)

                waitStart = waitStart or os.clock()
                ax.progress = isSharko and 'Waiting for Sharko' or 'Trial: waiting for ' .. trialName .. ' to load'

                if os.clock() - waitStart >= 10 then
                    return false
                end

                task.wait(0.1)

                continue
            end

            waitStart = nil

            if killY and targetRoot.Position.Y < killY then
                clickHolder.set(false)

                ax.progress = isSharko and 'Checking Sharko defeat' or 'Trial: waiting for ' .. trialName .. ' to despawn'

                if charRoot.Position.Y < killY then
                    if not travelRecovery.new(CFrame.new(triggerPart.Position - Vector3.new(0, 20, 0)), true, 150).wait(15) then
                        return false
                    end
                end

                task.wait(0.1)

                continue
            end

            ax.progress = isSharko and 'Fighting Sharko' or 'Trial: ' .. trialName

            if (charRoot.Position - targetRoot.Position).Magnitude > 50 then
                clickHolder.set(false)

                if not travelRecovery.new(function()
                    if not targetRoot.Parent or enemyHumanoid.Health <= 0 or killY and targetRoot.Position.Y < killY then
                        return bo() and bo().CFrame
                    end

                    return CFrame.lookAt((targetRoot.CFrame * aimOffset).Position, targetRoot.Position)
                end, true, 150).wait(15) then
                    clickHolder.set(false)

                    return false
                end

                continue
            else
                charRoot.AssemblyLinearVelocity = Vector3.zero
                charRoot.CFrame = CFrame.lookAt((targetRoot.CFrame * aimOffset).Position, targetRoot.Position)
            end
            if isSharko and not effectTracker.has('Equipped') then
                clickHolder.set(false)

                ax.progress = 'Equipping weapon'

                if os.clock() >= nextEquipTime then
                    if equipAttempts >= 3 then
                        handleProgress('Could not equip weapon for Sharko')

                        return false
                    end

                    equipAttempts = equipAttempts + 1
                    nextEquipTime = os.clock() + 1

                    local weapon = getBackpack() and getBackpack():FindFirstChild('Weapon')

                    if weapon and weapon:IsA('Tool') then
                        pcall(delayedTask.method, localHumanoid, 'EquipTool', weapon)
                    end

                    local charHandler = noEffects.localPlayer.character and noEffects.localPlayer.character:FindFirstChild('CharacterHandler')
                    local requests = charHandler and charHandler:FindFirstChild('Requests')
                    local drawWeaponRemote = requests and requests:FindFirstChild('DrawWeapon')

                    if drawWeaponRemote then
                        pcall(delayedTask.method, drawWeaponRemote, 'FireServer', true)
                    end
                end

                task.wait(0.1)

                continue
            end

            equipAttempts = 0

            local hasPendingAction = actionRunner.pending(target) > 0
            local now = os.clock()

            if isAngel and not hasPendingAction and now >= nextFeintTime and now >= nextActionTime and effectTracker.has('LightAttack') then
                local timeSinceLightAttack = effectTracker.since('LightAttack')

                if timeSinceLightAttack and timeSinceLightAttack >= 0.12 and timeSinceLightAttack <= 0.32 then
                    clickHolder.set(false)

                    if characterActions.feint() then
                        nextFeintTime = now + 1.8
                        nextActionTime = now + 0.2
                    end
                end
            end
            if isAngel and not hasPendingAction and now >= nextCriticalClick and now >= nextActionTime then
                clickHolder.set(false)

                if now >= nextCriticalClick + 0.1 then
                    local criticalClickRemote = keyHandling.getRemote('CriticalClick')

                    if criticalClickRemote then
                        fireServer(criticalClickRemote, {
                            S = false,
                            NOAERIALS = false,
                            Space = false,
                            Right = false,
                            W = false,
                            Left = true,
                        }, false)

                        nextCriticalClick = now + 0.8
                        nextActionTime = now + 0.25
                    end
                end
            end

            clickHolder.set(not hasPendingAction and now >= nextActionTime and (not isAngel or now < nextCriticalClick or now >= nextCriticalClick + 0.1))
            task.wait()
        end

        clickHolder.set(false)

        if isSharko then
            return isArmed(character) and targetDefeated
        end

        return isArmed(character) and not findTarget(trialName)
    end
    local doArthurMegalodaunt = function(character)
        ax.progress = 'Travelling to Arthur\u{2019}s Megalodaunt'

        if not bq(waypoint11, 'Arthur quest checkpoint one', false, 'Etrean') then
            return false
        end
        if not bq(waypoint12, 'Arthur quest checkpoint two', false, 'Etrean') then
            return false
        end

        local megalodaunt = findTarget('Megalodaunt', waypoint12.Position, 180)

        if not megalodaunt then
            return false
        end

        local previousTarget = shared.Palantir_KaidoTarget

        shared.Palantir_KaidoTarget = megalodaunt

        local result = runTrial(character, 'Megalodaunt', CFrame.new(0, -20, 0), waypoint12.Position, 180)

        shared.Palantir_KaidoTarget = previousTarget

        return result
    end
    local checkRepaymentChat = function()
        local ok, found = pcall(function()
            local experienceChat = game:GetService('CoreGui'):FindFirstChild('ExperienceChat')
            local bubbleChat = experienceChat and experienceChat:FindFirstChild('bubbleChat')

            for index, chatLabel in ipairs(bubbleChat and bubbleChat:GetDescendants() or {})do
                if chatLabel:IsA('TextLabel') and chatLabel.Visible and chatLabel.Text:find("I don't know how else to repay you", 1, true) and chatLabel.Text:find('helped me find peace', 1, true) then
                    return true
                end
            end

            return false
        end)

        return ok and found
    end
    local checkCeremonyChat = function()
        local success, matched = pcall(function()
            local chatGui = game:GetService('CoreGui'):FindFirstChild('ExperienceChat')
            local chatBubble = chatGui and chatGui:FindFirstChild('bubbleChat')

            for loopIndex, labelChild in ipairs(chatBubble and chatBubble:GetDescendants() or {})do
                if labelChild:IsA('TextLabel') and labelChild.Visible and labelChild.Text:find("I'll let my comrades know", 1, true) and labelChild.Text:find('hold a ceremony in his honor', 1, true) then
                    return true
                end
            end

            return false
        end)

        return success and matched
    end
    local canStartArthurQuest = function(player, context)
        local profile = getSession()

        if profile.arthurQuest == 'complete' then
            return true
        end
        if (talentPicker.power(player) or 0) < 20 then
            return false
        end

        handleAutomationChild(nil)
        progressionTraining.restorePassive()
        talentPicker.cancelSpend()
        talentPicker.cancelFavour()

        if profile.arthurQuest == 'verify' then
            talentPicker.resetData()

            local talentData = waitForTalentData()
            local rewardReady = talentData and (tonumber(talentData.TalentPointsTotal) or 0) > (tonumber(profile.arthurQuestPoints) or 0)

            if not rewardReady and os.time() - (tonumber(profile.arthurQuestTurnInAt) or 0) >= 8 then
                ax.progress = 'Checking Arthur\u{2019}s reward'

                if not bq(waypoint13, 'Arthur', false, 'Etrean') then
                    return false
                end

                local arthur = j('Arthur')

                if arthur then
                    for attempt = 1, 3 do
                        if not isArmed(context) then
                            return false
                        end

                        fire(arthur)

                        local deadline = os.clock() + 3

                        repeat
                            task.wait(0.1)

                            rewardReady = checkRepaymentChat()
                        until rewardReady or not isArmed(context) or os.clock() >= deadline

                        if rewardReady then
                            break
                        end
                    end
                end
            end
            if rewardReady then
                profile.arthurQuest = 'complete'
                profile.arthurQuestPoints = nil
                profile.arthurQuestTurnInAt = nil

                if profile.paused == 'Arthur quest reward needs verification' then
                    profile.paused = nil
                end

                setSession(profile)
                showProgress('Arthur quest complete', 1)

                return true
            end
            if os.time() - (tonumber(profile.arthurQuestTurnInAt) or 0) < 8 then
                showProgress('Verifying Arthur\u{2019}s talent point', 1)

                return false
            end

            handleProgress('Arthur quest reward needs verification')

            return false
        end
        if not profile.arthurQuest then
            ax.progress = 'Travelling to Arthur in Etrean'

            if not bq(waypoint13, 'Arthur quest start', false, 'Etrean') then
                return false
            end

            local arthurNpc = j('Arthur')

            if not arthurNpc or not interactWithNpc(arthurNpc) then
                showProgress('Waiting for Arthur', 2)

                return false
            end
            if f("Maria's been avenged.") then
                profile.arthurQuest = 'killed'
            elseif f("I haven't been able to avenge her yet.") then
                profile.arthurQuest = 'accepted'
            elseif sendDialogueSequence({
                'What happened?',
                'Are you the only survivor?',
                'What happened next?',
                'Is there anything I can do to help?',
                "I'll avenge her.",
            }, 30) then
                profile.arthurQuest = 'accepted'
            else
                showProgress('Retrying Arthur quest dialogue', 2)

                return false
            end
            if bw() then
                pcall(delayedTask.method, noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})
            end

            setSession(profile)
        end
        if profile.arthurQuest == 'accepted' then
            ax.progress = 'Fighting Sharko'

            if not doArthurMegalodaunt(context) then
                showProgress('Looking for Sharko', 2)

                return false
            end

            profile = getSession()
            profile.arthurQuest = 'killed'

            setSession(profile)
        end
        if profile.arthurQuest == 'killed' then
            ax.progress = 'Returning to Arthur for quest reward'

            if not bq(waypoint13, 'Arthur quest reward', false, 'Etrean') then
                return false
            end

            local arthurModel = j('Arthur')

            if not arthurModel or not interactWithNpc(arthurModel) then
                showProgress('Waiting for Arthur\u{2019}s reward dialogue', 2)

                return false
            end
            if not f("Maria's been avenged.") then
                if f("I haven't been able to avenge her yet.") then
                    profile.arthurQuest = 'accepted'

                    setSession(profile)
                end

                pcall(delayedTask.method, noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})
                showProgress('Arthur has not confirmed Maria\u{2019}s defeat', 2)

                return false
            end

            local talentStats = waitForTalentData()

            profile.arthurQuestPoints = tonumber(talentStats and talentStats.TalentPointsTotal) or 0
            profile.arthurQuestTurnInAt = os.time()
            profile.arthurQuest = 'verify'

            setSession(profile)
            sendDialogueSequence({
                "Maria's been avenged.",
            }, 12)

            if bw() then
                pcall(delayedTask.method, noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {exit = true})
            end

            showProgress('Verifying Arthur\u{2019}s talent point', 1)
        end

        return false
    end
    local canStartAtraQuest = function(player)
        local state = getSession()

        if state.atraQuest == 'complete' then
            return true
        end
        if (talentPicker.power(player) or 0) < 20 then
            return false
        end

        handleAutomationChild(nil)
        progressionTraining.restorePassive()
        talentPicker.cancelSpend()
        talentPicker.cancelFavour()

        if state.atraQuest == 'verify' then
            talentPicker.resetData()

            local talentData = waitForTalentData()

            if state.atraRewardConfirmed or talentData and (tonumber(talentData.TalentPointsTotal) or 0) > (tonumber(state.atraQuestPoints) or 0) then
                state.atraQuest = 'complete'
                state.atraQuestPoints = nil
                state.atraQuestTurnInAt = nil
                state.atraRewardConfirmed = nil

                if state.paused == 'Atra\u{2019}s Legion Scout reward needs verification' then
                    state.paused = nil
                end

                setSession(state)
                showProgress('Legion Scout quest complete', 1)

                return true
            end
            if os.time() - (tonumber(state.atraQuestTurnInAt) or 0) < 8 then
                showProgress('Verifying Atra\u{2019}s quest reward', 1)

                return false
            end

            handleProgress('Atra\u{2019}s Legion Scout reward needs verification')

            return false
        end
        if not state.atraQuest then
            ax.progress = 'Talking to Atra about Lars'

            if not bq(waypoint14, 'Atra quest start', false, 'Etrean') then
                return false
            end

            local atra = j('Atra')

            if not atra or not interactWithNpc(atra) then
                showProgress('Waiting for Atra', 2)

                return false
            end
            if not sendDialogueSequence({
                'Nope.',
                '...',
                'An argument, what happened?',
            }, 30) then
                showProgress('Retrying Atra\u{2019}s quest dialogue', 2)

                return false
            end

            state = getSession()
            state.atraQuest = 'find_lars'

            setSession(state)
        end
        if state.atraQuest == 'find_lars' then
            ax.progress = 'Finding Lars in the Bluecap Library'

            if not bq(waypoint15, 'Lars', false, 'Etrean') then
                return false
            end

            local lars = j('Lars')

            if not lars or not interactWithNpc(lars) then
                showProgress('Waiting for Lars', 2)

                return false
            end
            if not sendDialogueSequence({}, 12) then
                showProgress('Retrying Lars interaction', 2)

                return false
            end

            state = getSession()
            state.atraQuest = 'return_to_atra'

            setSession(state)
        end
        if state.atraQuest == 'return_to_atra' then
            ax.progress = 'Reporting Lars\u{2019}s death to Atra'

            if not bq(waypoint14, 'Atra quest reward', false, 'Etrean') then
                return false
            end

            local rewardAtra = j('Atra')

            if not rewardAtra or not interactWithNpc(rewardAtra) then
                showProgress('Waiting for Atra\u{2019}s reward dialogue', 2)

                return false
            end

            local talentInfo = waitForTalentData()
            local confirmed = false
            local polling = true
            local pollThread = task.spawn(function()
                local deadline = os.clock() + 12

                while polling and os.clock() < deadline do
                    if checkCeremonyChat() then
                        confirmed = true

                        break
                    end

                    task.wait(0.05)
                end
            end)
            local interacted = sendDialogueSequence({}, 12)

            if not confirmed then
                task.wait(0.2)

                confirmed = checkCeremonyChat()
            end

            polling = false

            if coroutine.status(pollThread) == 'suspended' then
                pcall(task.cancel, pollThread)
            end
            if not interacted and not confirmed then
                showProgress('Retrying Atra\u{2019}s reward dialogue', 2)

                return false
            end

            state = getSession()
            state.atraQuestPoints = tonumber(talentInfo and talentInfo.TalentPointsTotal) or 0
            state.atraQuestTurnInAt = os.time()
            state.atraRewardConfirmed = confirmed or nil
            state.atraQuest = 'verify'

            setSession(state)
            showProgress('Verifying Atra\u{2019}s quest reward', 1)
        end

        return false
    end
    local isWipeEligible = function(trailTask)
        if not isInTrialOfOne() then
            local character = waitForTalentData()

            if not character or (talentPicker.power(character) or 99) > 1 or sanitizeString(character.Origin) == 'deepbound' then
                return false, 'ineligible'
            end
            if not unequipPlayerEquipment(trailTask) then
                return false, 'equipment'
            end
        end

        progressionTraining.restorePassive()

        ax.trainingStat = nil

        local featureFlags = {
            Flight = noEffects.featureActive('Flight'),
            NoClip = noEffects.featureActive('NoClip'),
            NoFallDamage = noEffects.featureActive('NoFallDamage'),
            PathfindBreaker = noEffects.featureActive('PathfindBreaker'),
            AggressiveMode = noEffects.featureActive('AggressiveMode'),
            EnableAutoParry = noEffects.featureActive('EnableAutoParry'),
            AutoFeint = noEffects.featureActive('AutoFeint'),
            BlockInput = noEffects.featureActive('BlockInput'),
        }

        for featureName in pairs(featureFlags)do
            noEffects.enableFeature(featureName)
        end

        featureFlags.VoidMobs = noEffects.featureActive('VoidMobs')

        noEffects.disableFeature('VoidMobs')

        ax.trialFeatures = featureFlags
        noEffects.automation.movement = ax
        ax.progress = 'Entering Trial of One'

        if not isInTrialOfOne() then
            teleport.start('TrialOfOne')
        end

        local deadline = os.clock() + 60

        while isArmed(trailTask) and os.clock() < deadline do
            local onePart = workspace:FindFirstChild('One')

            if onePart and onePart:FindFirstChild('OneStartTrigger') and onePart:FindFirstChild('OneTrigger') and bo() then
                break
            end

            task.wait(0.2)
        end

        teleport.stop()

        local trialZone = workspace:FindFirstChild('One')
        local startTrigger = trialZone and trialZone:FindFirstChild('OneStartTrigger')
        local trigger = trialZone and trialZone:FindFirstChild('OneTrigger')
        local success = false
        local result

        if startTrigger and trigger and bo() and isArmed(trailTask) then
            local trialData = getSession()

            if trialData.trialJob ~= game.JobId then
                trialData.trialStep = 0
            end

            trialData.trialJob = game.JobId

            setSession(trialData)

            noEffects.automation.trial_parry = {
                timings = a["Game/Timings/Mobs/TrialMobs"](),
                entities = {},
            }

            local character = noEffects.localPlayer.character
            local characterHandler = character and character:FindFirstChild('CharacterHandler')
            local requests = characterHandler and characterHandler:FindFirstChild('Requests')
            local drawWeaponRemote = requests and requests:FindFirstChild('DrawWeapon')

            if drawWeaponRemote then
                pcall(delayedTask.method, drawWeaponRemote, 'FireServer', true)
            end

            local weapon = getBackpack() and getBackpack():FindFirstChild('Weapon')

            if weapon and noEffects.localPlayer.humanoid then
                delayedTask.method(noEffects.localPlayer.humanoid, 'EquipTool', weapon)
            end

            success = true

            if (trialData.trialStep or 0) == 0 then
                fireTouch(startTrigger)

                success = travelRecovery.new(CFrame.new(114.923668, 1120.30823, 256.767151), true, 200).wait(30)

                if success then
                    success, result = runNomadTrial(trailTask, trigger)
                end
                if success then
                    trialData.trialStep = 1

                    setSession(trialData)

                    success = travelRecovery.new(CFrame.new(114.923668, 1130.30823, 256.767151), true, 150).wait(30)
                end
            end
            if success then
                for index, cO in ipairs({
                    {
                        'Megalodaunt',
                        CFrame.new(0, -20, 0),
                    },
                    {
                        'Golem',
                        CFrame.new(0, 15, 0),
                    },
                    {
                        'Crocco',
                        CFrame.new(0, -6, 8),
                    },
                    {
                        'Angel',
                        CFrame.new(0, -5, 2),
                    },
                    {
                        'Enforcer',
                        CFrame.new(0, -6, 0),
                    },
                    {
                        'StoneKnight',
                        CFrame.new(0, 8, 8),
                    },
                    {
                        'Nomad',
                        CFrame.new(0, 0, 0),
                    },
                    {
                        'Megalodaunt_Alpha',
                        CFrame.new(0, -20, 0),
                    },
                })do
                    if index < (trialData.trialStep or 1) then
                        continue
                    end
                    if index == 5 and not travelRecovery.new(CFrame.new(76, 1257, 255), true, 200).wait(30) then
                        success = false

                        break
                    end
                    if index > 1 and not travelRecovery.new(CFrame.new(114.923668, 1120.30823, 256.767151), true, 150).wait(30) then
                        success = false

                        break
                    end
                    if not (cO[1] == 'Nomad' and runNomadTrial(trailTask, trigger, true) or cO[1] ~= 'Nomad' and runTrial(trailTask, cO[1], cO[2])) then
                        success = false

                        break
                    end

                    trialData.trialStep = index + 1

                    setSession(trialData)

                    if index == 8 then
                        break
                    end
                end
            end
        end

        ax:stopTrial()

        return success and isArmed(trailTask), result
    end

    function ax:stopTrial()
        clickHolder.set(false)

        local trialParry = noEffects.automation.trial_parry

        noEffects.automation.trial_parry = nil

        if trialParry then
            local actionRunner = a["Game/Timings/ActionRunner"]()

            for entity in pairs(trialParry.entities)do
                actionRunner.cancel(entity, 'anim', true)
                actionRunner.cancel(entity, 'effect', true)
            end
        end
        if self.trialFeatures or self.routingTrial then
            teleport.stop()
        end

        self.routingTrial = nil

        travelRecovery.stopAll()

        if noEffects.automation.movement == self then
            noEffects.automation.movement = nil
        end
        if self.trialFeatures then
            for featureName, featureValue in pairs(self.trialFeatures)do
                noEffects.setFeature(featureName, featureValue)
            end

            self.trialFeatures = nil
        end
    end

    local showWipePrompt = function(build, slotNumber)
        if ax.prompt then
            return
        end

        local screenGui = Instance.new('ScreenGui')

        screenGui.Name = 'PalantirXProgressionWipe'
        screenGui.ResetOnSpawn = false
        screenGui.Parent = noEffects.localPlayer.instance:WaitForChild('PlayerGui')

        local frame = Instance.new('Frame')

        frame.Size = UDim2.fromOffset(390, 140)
        frame.Position = UDim2.new(0.5, -195, 0.5, -70)
        frame.BackgroundColor3 = Color3.fromRGB(23, 23, 23)
        frame.Parent = screenGui

        local label = Instance.new('TextLabel')

        label.Size = UDim2.new(1, -20, 0, 75)
        label.Position = UDim2.fromOffset(10, 5)
        label.BackgroundTransparency = 1
        label.TextWrapped = true
        label.TextColor3 = Color3.new(1, 1, 1)
        label.Text = 'Slot ' .. tostring(slotNumber) .. 
" cannot fit this build. Wiping permanently resets this slot. Wipe it?"
        label.Parent = frame

        local makeButton = function(labelText, xOffset)
            local button = Instance.new('TextButton')

            button.Size = UDim2.fromOffset(175, 40)
            button.Position = UDim2.fromOffset(xOffset, 87)
            button.Text = labelText
            button.Parent = frame

            return button
        end

        ax.prompt = screenGui

        makeButton('Wipe slot', 10).Activated:Connect(function()
            if ax.prompt ~= screenGui or not ax:armed() then
                return
            end

            screenGui:Destroy()

            ax.prompt = nil
            ax.pendingWipe = {
                slot = tostring(slotNumber),
                build = build.url,
                fingerprint = buildCharacterKey(waitForTalentData()),
            }
        end)
        makeButton('Keep character', 205).Activated:Connect(function()
            if ax.prompt ~= screenGui then
                return
            end

            screenGui:Destroy()

            ax.prompt = nil

            local wipeState = getSession()

            wipeState.declinedWipeFor = build.url
            wipeState.inexact = true

            setSession(wipeState)
        end)
    end
    local canWipeSlot = function(wipePlan)
        if wipePlan.mode == 'talents' or not placeIds.isDepths() then
            return false
        end

        local currentArea = tostring(noEffects.localPlayer.instance:GetAttribute('CurrentArea') or '')
        local selfPosition = bo()
        local npcs = workspace:FindFirstChild('NPCs')

        npcs = npcs and npcs:FindFirstChild('Self')

        local nearSelf = selfPosition and npcs and (selfPosition.Position - npcs:GetPivot().Position).Magnitude < 250

        if not currentArea:find('Fragments of Self', 1, true) and not nearSelf then
            return false
        end

        local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

        if not wipePlan.slot and dataSlot then
            wipePlan.slot = dataSlot

            setSession(wipePlan)
        end
        if not wipePlan.slot or dataSlot and tostring(dataSlot) ~= tostring(wipePlan.slot) then
            handleProgress(
"Cannot wipe Fragments of Self: selected slot is unavailable or changed")

            return true
        end

        handleAutomationChild(nil)

        ax.progress = 'Wiping slot in Fragments of Self'

        ax:detach()
        a["Game/Wipe"]().invoke(wipePlan.slot)

        return true
    end
    local applyProgression = function(progression)
        local state = getSession()
        local build, loadError

        if canWipeSlot(state) then
            return
        end
        if state.mode ~= 'talents' then
            handleAutomationChild(nil)
        end

        for attempt = 1, 3 do
            if not isArmed(progression) then
                return
            end

            build, loadError = talentPicker.load(state.build, function(progress)
                ax.progress = progress
            end, state.mode)

            if build then
                break
            end
            if loadError and loadError:find('timed out', 1, true) then
                break
            end

            task.wait(2)
        end

        if not build then
            ax.progress = loadError

            return
        end

        ax.build = build

        local transaction = noEffects.value('mastery_transaction')

        if transaction and transaction.kind == 'mastery' then
            if tostring(transaction.slot) == tostring(state.slot) then
                state.pending = transaction

                setSession(state)
            else
                noEffects.setValue('mastery_transaction', nil)
            end
        end

        updateMantraTraining(build)

        local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

        if dataSlot and state.slot and tostring(dataSlot) ~= tostring(state.slot) then
            handleProgress('Selected slot changed')

            return
        end
        if state.mode ~= 'talents' and characterCreation.active() then
            ax.progress = 'Creating character from selected build'

            local created, creationError = characterCreation.run(build, function()
                return isArmed(progression)
            end)

            if not isArmed(progression) then
                return
            end
            if not created then
                handleProgress(creationError or 'Character creation could not be completed')

                return
            end

            talentPicker.resetData()

            ax.progress = 'Character created; waiting for data'

            local creationTimeout = os.clock() + 8

            repeat
                task.wait(0.1)
            until not characterCreation.active() or os.clock() >= creationTimeout or not isArmed(progression)

            if not isArmed(progression) then
                return
            end
            if characterCreation.active() then
                handleProgress('Character creation did not close')

                return
            end
        end
        if state.paused == 'Stat point allocation could not be confirmed' or state.paused == 'Card selection could not be confirmed' or state.paused == 'Shrine of Chance UI needs identification' or state.paused == 'No verified safe talent for Shrine of Chance' or state.paused == 'Shrine of Chance was not found' or state.paused == 
"Build stats remain at maximum Power without spendable points" or state.paused == 'Build stats remain at maximum Power without pending points' or state.paused == 
"Build targets remain at maximum Power without pending points" or state.paused == 
"Build targets met, but attribute points remain without a build target" then
            state.paused = nil
            state.pausedSignature = nil

            setSession(state)
        end
        if build.noShrine and (state.phase ~= 'post' or not state.phaseConfirmed or state.inexact) then
            state.phase = 'post'
            state.phaseConfirmed = true
            state.inexact = nil

            setSession(state)
        end
        if state.mode == 'talents' and state.pending and state.pending.kind == 'chance' and state.pending.stage == 'shop' and state.paused == 'Safe donor talent was not offered' then
            state.paused = nil
        end

        local controlsDeadline = os.clock() + 30

        if not Toggles or not Toggles.NoClip then
            ax.progress = 'Waiting for automation controls'
        end

        while isArmed(progression) and (not Toggles or not Toggles.NoClip) and os.clock() < controlsDeadline do
            task.wait(0.2)
        end

        if not Toggles or not Toggles.NoClip then
            handleProgress('Waiting for automation controls')
        end

        ax.progress = 'Waiting for character resources'

        while isArmed(progression) do
            local player = noEffects.localPlayer.instance
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass('Humanoid')
            local ether = character and character:FindFirstChild('Ether', true)
            local breakMeter = character and character:FindFirstChild('BreakMeter', true)

            if character and character:FindFirstChild('CharacterHandler') and noEffects.services.CollectionService:HasTag(player.Backpack, 'Loaded') and humanoid and humanoid.MaxHealth > 0 and humanoid.Health > 0 and ether and ether:IsA('ValueBase') and breakMeter and breakMeter:IsA('ValueBase') then
                break
            end

            task.wait(0.2)
        end

        if not isArmed(progression) then
            return
        end

        saveSessionFeatures()

        ax.progress = state.mode == 'talents' and 'Reading character data' or 'Reconciling character progress'

        local characterData

        while isArmed(progression) and not characterData do
            if canWipeSlot(getSession()) then
                return
            end

            characterData = waitForStableData(progression)

            if not characterData then
                showProgress('Waiting for stable character data', 1)
            end
        end

        if not isArmed(progression) then
            return
        end
        if state.mode ~= 'talents' then
            processPendingChanceState(build, state, characterData)

            state = getSession()

            buildProgressionSnapshot(build, state, characterData)

            state = getSession()
        end
        if state.mode == 'talents' or state.phaseConfirmed then
            startStatsLoop(progression)
        end

        local loadedCharacter = noEffects.localPlayer.character

        while isArmed(progression) do
            state = getSession()

            if canWipeSlot(state) then
                return
            end

            local transactionEntry = noEffects.value('mastery_transaction')

            if transactionEntry and transactionEntry.kind == 'mastery' and not state.pending then
                if tostring(transactionEntry.slot) == tostring(state.slot) then
                    state.pending = transactionEntry

                    setSession(state)
                else
                    noEffects.setValue('mastery_transaction', nil)
                end
            end

            local characterSnapshot = waitForTalentData()

            if not characterSnapshot then
                showProgress('Waiting for character data', 2)

                continue
            end
            if noEffects.localPlayer.character ~= loadedCharacter then
                talentPicker.cancelSpend()
                talentPicker.cancelFavour()

                loadedCharacter = noEffects.localPlayer.character
                characterSnapshot = waitForStableData(progression)

                if not characterSnapshot then
                    showProgress('Waiting for stable character data', 1)

                    continue
                end
                if state.mode ~= 'talents' then
                    buildProgressionSnapshot(build, state, characterSnapshot)

                    state = getSession()
                end
            end
            if state.mode ~= 'talents' and state.characterFingerprint and state.characterFingerprint ~= buildCharacterKey(characterSnapshot) then
                buildProgressionSnapshot(build, state, characterSnapshot)

                state = getSession()
            end
            if state.paused == 'No verified safe talent for Shrine of Chance' and state.pausedSignature and state.pausedSignature ~= buildProfileSignature(characterSnapshot) then
                state.paused = nil
                state.pausedSignature = nil

                setSession(state)
            end
            if state.paused == 'Shrine of Order result needs verification' and state.pending and state.pending.kind == 'order' and findShrineOrderPrompt() then
                state.paused = nil
                state.pending = nil

                setSession(state)
            end

            updateMantraTraining(build, characterSnapshot)

            local ringTargets = state.mode ~= 'talents' and state.phase == 'post' and ringData.targets(build.post) or {}

            noEffects.automation.progressionScalingRingsNeeded = ringData.missing(ringTargets, characterSnapshot)

            if #ringTargets > 0 and not ax.child and not noEffects.automation.movement and (not executionQueue.active or executionQueue.active.checkpoint) and placeIds.isOverworld() and not isInTrialOfOne() and not isFerrymanTargetValid() and not state.paused and os.clock() >= (ax.scalingRingAt or 0) then
                ax.scalingRingAt = os.clock() + 5

                if ringData.equipOne(ringTargets, characterSnapshot) then
                    ax.progress = 'Equipping post-Shrine scaling ring'

                    task.wait(0.3)
                    talentPicker.resetData()

                    characterSnapshot = waitForTalentData() or characterSnapshot
                    noEffects.automation.progressionScalingRingsNeeded = ringData.missing(ringTargets, characterSnapshot)
                end
            end
            if not noEffects.featureActive('Flight') then
                noEffects.enableFeature('Flight')
            end
            if not noEffects.featureActive('NoClip') then
                noEffects.enableFeature('NoClip')
            end

            local selectedSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

            if selectedSlot and state.slot and tostring(selectedSlot) ~= tostring(state.slot) then
                handleProgress('Selected slot changed')

                continue
            end
            if not noEffects.localPlayer.humanoid or noEffects.localPlayer.humanoid.Health <= 0 then
                if hasFatePrompt() then
                    task.wait(0.2)

                    continue
                end

                handleAutomationChild(nil)

                if state.ferrymanCycle ~= nil then
                    state.ferrymanCycle = nil

                    setSession(state)
                end

                showProgress('Waiting for respawn', 2)

                continue
            end

            local buildTarget = state.phase == 'post' and build.post or build.pre
            local willpowerUnbounded = getOwnedTalents(characterSnapshot).willpowerunbounded

            if willpowerUnbounded and (state.activeTask == 'unbound_willpower' or state.unboundWillpowerStage) then
                resetUnboundWillpower(state)

                state = getSession()
            elseif state.mode ~= 'talents' and (state.activeTask == 'unbound_willpower' or not placeIds.isDungeon() and not isInTrialOfOne() and not state.pending and not state.paused and isWillpowerUnboundable(characterSnapshot, buildTarget, getOwnedTalents(characterSnapshot))) then
                onWillpowerUnbound(progression, characterSnapshot)

                continue
            end
            if state.activeTask == 'escape_depths' and placeIds.isOverworld() then
                state.activeTask = nil

                setSession(state)
            end
            if placeIds.isDepths() or isInDepthsTrial() or state.activeTask == 'escape_depths' then
                if state.activeTask ~= 'escape_depths' then
                    state.activeTask = 'escape_depths'
                    state.ferrymanCycle = nil

                    setSession(state)
                end
                if not state.resume then
                    state.resume = state.phase

                    setSession(state)
                end

                handleAutomationChild('auto_escape_depths')
                showProgress(isInDepthsTrial() and 'Completing the Depths Trial' or 'Escaping the Depths', 2)

                continue
            end
            if state.activeTask == 'oathless' and (sanitizeString(build.oath) ~= 'oathless' or sanitizeString(characterSnapshot.Oath) == 'oathless') then
                state.activeTask = nil
                state.oathlessStage = nil

                setSession(state)
            end
            if state.mode ~= 'talents' and sanitizeString(build.oath) == 'oathless' and placeIds.isOverworld() and not isInTrialOfOne() and not state.trialActive and not state.paused and not state.pending and not isFerrymanTargetValid() and (not state.activeTask or state.activeTask == 'oathless') and sanitizeString(characterSnapshot.Oath) ~= 'oathless' then
                if os.clock() >= (ax.oathlessRetryAt or 0) then
                    resetOathlessState(progression, characterSnapshot)
                end

                showProgress('Oathless: checking quest progress', 1)

                continue
            end
            if state.mode ~= 'talents' and (hasBreakthroughTalent(build) and (hasOtherCombatTalent(build) or hasThirdCombatTalent(build)) or hasOtherCombatTalent(build) and hasThirdCombatTalent(build)) and getAttributeValue('Faction') == 'Authority' and getAttributeValue('FactionRankName') == 'Lance Corporal' and getAttributeValue('FactionRankDivision') == 'Default' then
                handleProgress('Build contains talents from multiple Authority divisions')

                continue
            end
            if state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and not state.paused and not state.pending and hasBreakthroughTalent(build) and getAttributeValue('Faction') == 'Authority' and getAttributeValue('FactionRankName') == 'Lance Corporal' and getAttributeValue('FactionRankDivision') == 'Default' then
                if os.clock() >= (ax.commandRetryAt or 0) then
                    if shouldJoinAuthorityCommand() then
                        ax.progress = 'Joined Authority Command division'
                    else
                        ax.commandRetryAt = os.clock() + 5
                    end
                end

                showProgress('Joining Authority Command division', 1)

                continue
            end
            if state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and not state.paused and not state.pending and hasOtherCombatTalent(build) and getAttributeValue('Faction') == 'Authority' and getAttributeValue('FactionRankName') == 'Lance Corporal' and getAttributeValue('FactionRankDivision') == 'Default' then
                if os.clock() >= (ax.inqRetryAt or 0) then
                    if shouldJoinInquisition() then
                        ax.progress = 'Joined Authority Inquisition division'
                    else
                        ax.inqRetryAt = os.clock() + 60
                    end
                end
                if getAttributeValue('FactionRankDivision') == 'Default' then
                    if handleAutomationChild('auto_authority_missions') then
                        showProgress('Farming solo Authority missions for Inquisition', 2)
                    else
                        showProgress('Waiting for Authority missions before Inquisition', 2)
                    end
                else
                    showProgress('Joined Authority Inquisition division', 1)
                end

                continue
            end
            if state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and not state.paused and not state.pending and hasThirdCombatTalent(build) and getAttributeValue('Faction') == 'Authority' and getAttributeValue('FactionRankName') == 'Lance Corporal' and getAttributeValue('FactionRankDivision') == 'Default' then
                if os.clock() >= (ax.shockRetryAt or 0) then
                    if shouldJoinShockCorps() then
                        ax.progress = 'Joined Authority Shock Corps division'
                    else
                        ax.shockRetryAt = os.clock() + 60
                    end
                end
                if getAttributeValue('FactionRankDivision') == 'Default' then
                    if handleAutomationChild('auto_authority_missions') then
                        showProgress('Farming Authority missions for Shock Corps', 2)
                    else
                        showProgress('Waiting for Authority missions before Shock Corps', 2)
                    end
                else
                    showProgress('Joined Authority Shock Corps division', 1)
                end

                continue
            end
            if state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and not state.paused and (tonumber(buildTarget and buildTarget.Charisma) or 0) > 75 and (tonumber(characterSnapshot.StatCharisma) or 0) >= 75 and not getOwnedTalents(characterSnapshot).charismaunbounded then
                local bugMessage = 
"Charisma unbound is bugged; if fixed, tell the Palantir X developer at .gg/palantirx"

                talentPicker.cancelSpend()
                talentPicker.cancelFavour()
                progressionTraining.restorePassive()
                handleProgress(bugMessage)
                logger.warnNotify(bugMessage)
                showProgress(bugMessage, 2)

                continue
            end

            local fortitudeUnbounded = getOwnedTalents(characterSnapshot).fortitudeunbounded

            if fortitudeUnbounded and (state.activeTask == 'unbound_fortitude' or state.unboundFortitudeStage) then
                resetUnboundFortitude(state)

                state = getSession()
            elseif state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and (state.activeTask == 'unbound_fortitude' or not state.pending and not state.paused and isUnboundedFortitudeEligible(characterSnapshot, buildTarget, getOwnedTalents(characterSnapshot))) then
                stopFortitudeTraining(characterSnapshot)

                continue
            end

            local agilityUnbounded = getOwnedTalents(characterSnapshot).agilityunbounded

            if agilityUnbounded and (state.activeTask == 'unbound_agility' or state.unboundAgilityStage) then
                resetUnboundAgility(state)

                state = getSession()
            elseif state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and (state.activeTask == 'unbound_agility' or not state.pending and not state.paused and isAgilityUnboundable(characterSnapshot, buildTarget, getOwnedTalents(characterSnapshot))) then
                stopAgilityTraining(characterSnapshot)

                continue
            end

            local strengthUnbounded = getOwnedTalents(characterSnapshot).strengthunbounded

            if strengthUnbounded and (state.activeTask == 'unbound_strength' or state.unboundStrengthStage) then
                resetUnboundStrength(state)

                state = getSession()
            elseif state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and (state.activeTask == 'unbound_strength' or not state.pending and not state.paused and isStrengthUnboundable(characterSnapshot, buildTarget, getOwnedTalents(characterSnapshot))) then
                stopStrengthTraining(characterSnapshot)

                continue
            end

            local intelligenceUnbounded = getOwnedTalents(characterSnapshot).intelligenceunbounded

            if intelligenceUnbounded and (state.activeTask == 'unbound_intelligence' or state.unboundIntelligenceStage) then
                resetUnboundIntelligence(state)

                state = getSession()
            elseif state.mode ~= 'talents' and placeIds.isOverworld() and not isInTrialOfOne() and not state.paused and (state.activeTask == 'unbound_intelligence' or not state.pending and isIntelligenceUnboundable(characterSnapshot, buildTarget, getOwnedTalents(characterSnapshot))) then
                stopIntelligenceTraining(characterSnapshot)

                continue
            end
            if state.paused == 'Arthur quest reward needs verification' and state.arthurQuest == 'verify' then
                canStartArthurQuest(characterSnapshot, progression)

                continue
            end
            if state.paused and not (state.pending and (state.pending.kind == 'mastery' or state.pending.kind == 'order' or state.pending.kind == 'chance' and (state.paused == 'Shrine of Chance result needs verification' or state.paused == 'Shrine of Chance card hand needs verification' or state.paused == 'Shrine of Chance card selection was not confirmed'))) then
                showProgress(state.paused, 2)

                continue
            end
            if isInTrialOfOne() or state.trialActive then
                if state.ferrymanCycle ~= nil then
                    state.ferrymanCycle = nil

                    setSession(state)
                end
                if ax.child == 'auto_ferryman' then
                    handleAutomationChild(nil)
                end
            end
            if state.mode ~= 'talents' and not isInTrialOfOne() and not state.trialActive and not state.pending and not state.paused and (state.unboundFerrymanStage or state.activeTask == 'unbound_ferryman' or selectNextUnboundStat(characterSnapshot, buildTarget, build, state.phase, state.unboundFerrymanCompleted)) then
                if handleFerrymanUnbound(progression, characterSnapshot, buildTarget) then
                    continue
                end

                state = getSession()
            end
            if state.mode ~= 'talents' and state.phase == 'post' and state.phaseConfirmed and not state.inexact and not state.pending and not state.paused and meetsMasteryRequirements(characterSnapshot) and (state.phaseSource == 'verified' or state.phaseEvidence == buildProfileSignature(characterSnapshot)) then
                local inferredAttrs = collectStats(characterSnapshot)

                if inferredAttrs and next(statInference.overshoots(build.post, inferredAttrs)) then
                    if isInTrialOfOne() or isFerrymanTargetValid() or placeIds.isDungeon() then
                        showProgress('Waiting to correct post-Shrine attributes', 2)
                    elseif statInference.required(build.post, inferredAttrs) > 3 - (tonumber(state.masteryPointsUsed) or 0) then
                        handleProgress('Shrine of Mastery three-point limit reached')
                    elseif not waitForKnowledgeTarget(characterSnapshot, state, 'mastery', 1) then
                        if handleAutomationChild(nil) then
                            local shrineOk, shrineError = travelToTarget('Shrine of Mastery', waypoint19, checkMasteryReady, 'Eastern')

                            if shrineOk then
                                showProgress('Verifying Shrine of Mastery reduction', 1)
                            else
                                handleProgress(shrineError or 'Shrine of Mastery correction needs verification')
                            end
                        else
                            showProgress('Waiting for movement control before Shrine of Mastery', 1)
                        end
                    end

                    continue
                end
            end

            ax.goalStat = talentPicker.nextStat(characterSnapshot, buildTarget, build, state.phase)

            if not placeIds.isDungeon() and not isInTrialOfOne() and not state.pending and not state.paused and getAutomationHandler(characterSnapshot) ~= 'auto_authority_missions' and startTraining(progression, characterSnapshot, buildTarget) then
                state = getSession()

                if state.ferrymanCycle ~= nil and not (state.activeTask == 'fortitude' and ax.child == 'auto_ferryman') then
                    state.ferrymanCycle = nil

                    setSession(state)
                end

                continue
            end
            if state.ferrymanCycle ~= nil and getAutomationHandler(characterSnapshot) == 'auto_authority_missions' then
                state.ferrymanCycle = nil

                setSession(state)
            end
            if state.ferrymanCycle ~= nil then
                if placeIds.isDungeon() or (tonumber(noEffects.value('ferryman_rounds')) or 0) <= state.ferrymanCycle then
                    handleAutomationChild('auto_ferryman')
                    showProgress('Completing Ferryman run', 2)

                    continue
                end

                handleAutomationChild(nil)

                state.ferrymanCycle = nil

                setSession(state)
            end
            if isFerrymanTargetValid() then
                showProgress('Progressing with Ferryman', 2)

                continue
            end
            if state.pending then
                local pending = state.pending

                if pending.at and os.time() - pending.at < 8 then
                    showProgress('Verifying shrine response', 1)

                    continue
                end
                if pending.kind == 'chance' then
                    if canAffordTalent(pending, characterSnapshot) then
                        if not bt() then
                            handleProgress('Shrine dialogue did not close')

                            continue
                        end

                        ca(pending)
                    elseif pending.stage == 'donor' and talentPicker.choice(characterSnapshot) then
                        ax.progress = 'Choosing build talent'

                        local pendingOk, pendingError = b9(pending)

                        if not pendingOk then
                            handleProgress(pendingError)
                        end

                        continue
                    elseif pending.stage == 'shop' and talentPicker.knowledge(characterSnapshot) == pending.knowledge then
                        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
                        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')

                        if pending.job and pending.job ~= game.JobId and not (choicePrompt and choicePrompt.Enabled) and not talentPicker.choice(characterSnapshot) then
                            state.pending = nil
                            state.paused = nil

                            setSession(state)
                            showProgress('Retrying Shrine of Chance in the new server', 2)

                            continue
                        end

                        showProgress('Waiting for Shrine donor prompt; no new request sent', 2)

                        continue
                    else
                        showProgress('Waiting for Shrine result: check the pending talent cards', 2)

                        continue
                    end
                elseif pending.kind == 'mastery' then
                    talentPicker.resetData()

                    local masteryData = waitForTalentData()
                    local masteryAttrs = collectStats(masteryData)

                    if not masteryData or not masteryAttrs or talentPicker.knowledge(masteryData) == nil then
                        showProgress('Waiting for Shrine of Mastery result data', 2)

                        continue
                    end
                    if pending.slot ~= tostring(state.slot) or pending.fingerprint ~= buildCharacterKey(masteryData) then
                        handleProgress('Shrine of Mastery character changed')

                        continue
                    end
                    if statInference.verified(pending, masteryAttrs, talentPicker.knowledge(masteryData)) then
                        state.masteryPointsUsed = (tonumber(state.masteryPointsUsed) or 0) + 1
                        state.pending = nil
                        state.paused = nil

                        setSession(state)
                        noEffects.setValue('mastery_transaction', nil)

                        if not closeMasteryDialogue() then
                            handleProgress('Shrine of Mastery dialogue did not close')
                        end
                    else
                        handleProgress('Shrine of Mastery result needs verification')

                        continue
                    end
                elseif pending.kind == 'order' then
                    local statMismatch = false

                    for statName, expectedValue in pairs(pending.stats or {})do
                        if (characterSnapshot['Stat' .. statName] or 0) ~= expectedValue then
                            statMismatch = true

                            break
                        end
                    end

                    if statMismatch then
                        state.phase = 'post'
                        state.phaseConfirmed = true
                        state.phaseSource = 'verified'
                        state.orderVerifiedFor = (pending.fingerprint or buildCharacterKey(characterSnapshot)) .. ':' .. (pending.build or build.url)
                        state.reconcileState = 'partial_post'
                        state.pending = nil
                        state.paused = nil

                        setSession(state)
                    else
                        handleProgress('Shrine of Order result needs verification')

                        continue
                    end
                elseif pending.kind == 'blasphemy' then
                    talentPicker.resetData()

                    local refreshData = waitForTalentData() or characterSnapshot

                    if buildCharacterKey(refreshData) ~= pending.fingerprint then
                        state.pending = nil

                        setSession(state)
                    elseif (talentPicker.power(refreshData) or 0) >= (tonumber(pending.power) or 0) + 3 then
                        state.blasphemyUsedFor = pending.build
                        state.pending = nil

                        setSession(state)
                    else
                        handleProgress('Shrine of Blasphemy result needs verification')

                        continue
                    end
                end
            end
            if state.mode == 'talents' then
                if not handleAutomationChild(nil) then
                    showProgress('Waiting for movement control', 2)

                    continue
                end
                if not talentPicker.canRead(characterSnapshot, 'Talents') then
                    showProgress('Waiting for owned talents', 2)

                    continue
                end
                if placeIds.isDepths() or placeIds.isDungeon() then
                    handleProgress('Leave the Depths or dungeon to use Shrine of Chance')

                    continue
                end

                local stats = getOwnedTalents(characterSnapshot)
                local missingStatTalents = talentPicker.missing(build, talentPicker.statTalents(build), stats)

                if not tablesEqual(state.missingTalents, missingStatTalents) then
                    state.missingTalents = missingStatTalents

                    setSession(state)
                end
                if not next(missingStatTalents) then
                    if not bt() then
                        handleProgress('Shrine dialogue did not close')

                        continue
                    end

                    state.complete = true

                    setSession(state)

                    ax.progress = 'Stat talents complete'

                    logger.notify('Auto Talents: all build stat talents owned.')
                    ax:stop()

                    return
                end

                local eligible = {}

                for talentId, talentEntry in pairs(missingStatTalents)do
                    if talentPicker.eligible(characterSnapshot, build.metadata[talentId], stats, build.metadata) then
                        eligible[talentId] = talentEntry
                    end
                end

                if talentPicker.choice(characterSnapshot) then
                    local choiceOk, choiceMessage = talentPicker.choose(characterSnapshot, eligible, build)

                    if choiceOk then
                        showProgress('Choosing build talent', 1)

                        continue
                    elseif choiceMessage then
                        handleProgress(choiceMessage)

                        continue
                    end
                end
                if not next(eligible) then
                    handleProgress('Missing build talents are not currently eligible')

                    continue
                end

                local safeOffer = resolveChanceChain(build, eligible, stats)

                if not safeOffer then
                    handleProgress('No verified safe talent for Shrine of Chance')

                    continue
                end
                if not talentPicker.knowledge(characterSnapshot) then
                    showProgress('Waiting for Knowledge data', 2)

                    continue
                end
                if talentPicker.knowledge(characterSnapshot) < safeOffer.totalCost then
                    handleProgress('Need Knowledge for Shrine of Chance')

                    continue
                end

                local chanceOk, chanceError = travelToTarget('Shrine of Chance', waypoint1, function(navNode)
                    return performChanceTransaction(navNode, safeOffer)
                end)

                if chanceOk then
                    showProgress('Verifying reroll', 2)
                elseif chanceError == 'Shrine of Chance UI needs identification' then
                    ax.progress = 'Switching servers for Shrine of Chance'

                    noEffects.hop(state.slot, true)

                    return
                else
                    handleProgress(chanceError)
                end

                continue
            end

            local inTrial = isInTrialOfOne()
            local needsTrial = (talentPicker.power(characterSnapshot) or 99) <= 1 and sanitizeString(characterSnapshot.Origin) ~= 'deepbound'

            if not inTrial and not needsTrial and state.trialActive then
                state.trialActive = nil
                state.trialJob = nil
                state.trialStep = nil

                setSession(state)
            end
            if not placeIds.isDepths() and not state.trialDeathChosen and (inTrial or needsTrial and (state.trialActive or not state.trialComplete and (state.trialAttempts or 0) < 3 and not placeIds.isDungeon())) then
                if not handleAutomationChild(nil) then
                    showProgress('Waiting for movement control', 2)

                    continue
                end
                if state.trialComplete or (state.trialAttempts or 0) >= 3 then
                    state.trialActive = nil

                    setSession(state)

                    if inTrial then
                        if state.trialComplete then
                            showProgress('Trial complete: waiting for exit', 2)

                            continue
                        end

                        state.trialAttempts = 0
                        state.trialActive = true

                        setSession(state)
                        showProgress('Continuing active Trial', 2)

                        continue
                    end
                else
                    state.trialActive = true

                    if not state.phaseConfirmed and (talentPicker.power(characterSnapshot) or 99) <= 1 then
                        state.phase = 'pre'
                        state.phaseConfirmed = true
                    end

                    setSession(state)

                    if not inTrial then
                        if placeIds.isEastern() then
                            ax.progress = 'Travelling to Etrean for Trial of One'
                            ax.routingTrial = true

                            local transferred = regionTransfer.toEtrean(nil, function()
                                return isArmed(progression)
                            end)

                            ax.routingTrial = nil

                            if not isArmed(progression) then
                                return
                            end
                            if not transferred then
                                handleProgress(
"Could not reach Etrean; restart Auto Progression to retry travel")

                                continue
                            end
                        elseif placeIds.isDungeon() then
                            ax.progress = 'Leaving dungeon for Trial of One'

                            noEffects.hop(state.slot, true)

                            return
                        elseif not placeIds.isEtrean() then
                            handleProgress('Trial of One needs Etrean Luminant')

                            continue
                        end
                    end

                    local didCompleteTrial, trialStatus = isWipeEligible(progression)

                    if not isArmed(progression) then
                        return
                    end

                    state = getSession()

                    if trialStatus == 'ineligible' then
                        state.trialActive = nil
                        state.trialJob = nil
                        state.trialStep = nil

                        setSession(state)
                        showProgress('Trial: character is not eligible', 2)

                        continue
                    end
                    if trialStatus == 'equipment' then
                        showProgress('Trial: waiting to unequip accessories', 2)

                        continue
                    end
                    if trialStatus == 'preparation' then
                        showProgress('Trial: waiting for starting stats or cards', 2)

                        continue
                    end
                    if didCompleteTrial then
                        state.trialComplete = true
                        state.trialActive = nil
                    elseif isInTrialOfOne() then
                        state.trialActive = true
                    else
                        state.trialAttempts = (state.trialAttempts or 0) + 1
                        state.trialActive = state.trialAttempts < 3 or nil
                    end

                    setSession(state)

                    if isInTrialOfOne() then
                        showProgress(didCompleteTrial and 'Trial complete: waiting for exit' or 'Trial interrupted: waiting for recovery', 2)

                        continue
                    end

                    showProgress(didCompleteTrial and 'Trial complete' or 'Preparing Trial retry', 2)
                end

                continue
            end
            if not talentPicker.canRead(characterSnapshot, 'Talents') or not talentPicker.canRead(characterSnapshot, 'Mantras') then
                showProgress('Waiting for owned cards', 2)

                continue
            end
            if state.mode ~= 'talents' then
                local reconciled, reconcileStatus = buildProgressionSnapshot(build, state, characterSnapshot)

                state = getSession()

                if not reconciled then
                    handleAutomationChild(nil)

                    if reconcileStatus == 'incompatible' then
                        handleProgress(
"Cannot determine Shrine of Order phase from current attributes")
                    else
                        showProgress('Rechecking Shrine of Order status', 2)
                    end

                    continue
                end
                if not ax.statsThread then
                    startStatsLoop(progression)
                end
                if reconcileStatus == 'pre_cards' then
                    ax.progress = 'Resolving pre-shrine cards'
                end
            end
            if (state.resume == 'chance' or state.resume == 'order' or state.resume == 'temptation' or state.resume == 'unification' or state.resume == 'blasphemy') and state.titusRelics and placeIds.isDungeon() then
                handleAutomationChild('auto_titus')
                showProgress('Leaving Titus with Moonseye Tome', 2)

                continue
            end

            local phaseTarget = state.phase == 'post' and build.post or build.pre
            local baseAttrs = getOwnedTalents(characterSnapshot)
            local missingMainTalents = talentPicker.missing(build, build.talents, baseAttrs)
            local missingMantras = talentPicker.missing(build, build.mantras, talentPicker.owned(characterSnapshot, 'Mantras'))
            local missingPreMantras = talentPicker.missing(build, talentPicker.preMantras(build), talentPicker.owned(characterSnapshot, 'Mantras'))

            if not tablesEqual(state.missingTalents, missingMainTalents) or not tablesEqual(state.missingMantras, missingMantras) then
                state.missingTalents = missingMainTalents
                state.missingMantras = missingMantras

                setSession(state)
            end
            if state.phase ~= 'post' and talentPicker.mismatch(characterSnapshot, build.pre) then
                if not state.inexact then
                    state.inexact = true

                    setSession(state)
                end

                local powerValue = talentPicker.power(characterSnapshot)

                if powerValue and powerValue <= 5 and state.declinedWipeFor ~= build.url then
                    handleAutomationChild(nil)

                    local pendingWipe = ax.pendingWipe

                    if pendingWipe and pendingWipe.slot == tostring(state.slot) and pendingWipe.build == build.url and pendingWipe.fingerprint == buildCharacterKey(characterSnapshot) then
                        ax.pendingWipe = nil
                        state.inexact = nil
                        state.trialAttempts = 0
                        state.phase = 'pre'

                        setSession(state)

                        ax.progress = 'Wiping incompatible slot by player choice'

                        ax:detach()
                        a["Game/Wipe"]().invoke(state.slot)

                        return
                    end

                    ax.pendingWipe = nil

                    showWipePrompt(build, state.slot)
                    showProgress('Build mismatch: choose Wipe slot or Keep character', 1)

                    continue
                end
            end
            if state.activeTask == 'unification' then
                local mantraOk, mantraMessage = handleUnificationOutput(build)

                if not mantraOk then
                    handleProgress(mantraMessage)
                else
                    showProgress('Choosing shrine mantra', 2)
                end

                continue
            end
            if talentPicker.choice(characterSnapshot) then
                if state.talentCleanup then
                    local chooseOk, chooseMessage = talentPicker.choose(characterSnapshot, talentPicker.statTalents(build), build)

                    if not chooseOk and chooseMessage then
                        handleProgress(chooseMessage)
                    end
                elseif state.reconcileState == 'pre_cards' then
                    local preTalentList = talentPicker.preTalents(build)

                    for preMantraId, preMantra in pairs(talentPicker.preMantras(build))do
                        preTalentList[preMantraId] = preMantra
                    end

                    local preChooseOk, preChooseMessage = talentPicker.choose(characterSnapshot, preTalentList, build)

                    if not preChooseOk and preChooseMessage then
                        showProgress(preChooseMessage, 2)
                    end
                end

                showProgress('Choosing cards', 0.5)

                continue
            end
            if state.phase ~= 'post' and talentPicker.targetsMet(characterSnapshot, build.pre) then
                if state.inexact then
                    handleProgress('Build stats are incompatible with Shrine of Order')

                    continue
                end

                local preTalentPlan = talentPicker.preTalents(build)

                if preTalentPlan.ardourscream and not getOwnedTalents(characterSnapshot).murmurardour then
                    local kaido = getLoader().get('auto_kaido')
                    local kaidoProgress = kaido and kaido.progress or ''

                    if kaidoProgress:find('failed', 1, true) or kaidoProgress:find('stalled', 1, true) or kaidoProgress:find('did not spawn', 1, true) or kaidoProgress:find('needs verification', 1, true) or kaidoProgress:find('paused', 1, true) then
                        handleAutomationChild(nil)
                        handleProgress('Auto Kaido: ' .. kaidoProgress)

                        continue
                    end

                    local backpack = noEffects.localPlayer.instance:FindFirstChild('Backpack')
                    local localCharacter = noEffects.localPlayer.character
                    local ardourManifestation = backpack and backpack:FindFirstChild('Ardour Manifestation') or localCharacter and localCharacter:FindFirstChild('Ardour Manifestation')

                    noEffects.automation.kaidoManifestationNeeded = not ardourManifestation

                    if ardourManifestation then
                        if handleAutomationChild('auto_kaido') then
                            showProgress('Getting Ardour from Dread Serpent', 2)
                        else
                            showProgress('Waiting to start Auto Kaido', 2)
                        end
                    elseif handleAutomationChild('auto_ferryman') then
                        showProgress('Farming Ardour Manifestation', 2)
                    else
                        showProgress('Waiting for Ferryman', 2)
                    end

                    continue
                end

                noEffects.automation.kaidoManifestationNeeded = nil

                local currentPreTalents = computeMissingTalents(build)

                if next(currentPreTalents) then
                    if bJ(build, currentPreTalents, characterSnapshot, baseAttrs) then
                        continue
                    end

                    local preEligible = {}

                    for preTalentId, preTalentData in pairs(currentPreTalents)do
                        local talentMeta = build.metadata[preTalentId]
                        local weaponType = talentMeta and talentMeta.requirements and talentMeta.requirements.weaponType
                        local noWeapon = type(weaponType) ~= 'string' or weaponType == ''

                        if type(weaponType) == 'string' and weaponType ~= '' then
                            for weaponName in weaponType:gmatch('[^,/]+')do
                                if bG(build, bA(weaponName:match('^%s*(.-)%s*$'))) then
                                    noWeapon = true

                                    break
                                end
                            end
                        end
                        if noWeapon and talentPicker.eligible(characterSnapshot, talentMeta, baseAttrs, build.metadata) then
                            preEligible[preTalentId] = preTalentData
                        end
                    end

                    if not next(preEligible) then
                        handleAutomationChild(nil)
                        showProgress('Missing pre-shrine talent requirements', 2)

                        continue
                    end

                    local preSafeOffer = resolveChanceChain(build, preEligible, baseAttrs)

                    if not preSafeOffer then
                        handleProgress('No verified safe talent for Shrine of Chance')

                        continue
                    end
                    if waitForKnowledgeTarget(characterSnapshot, state, 'chance', preSafeOffer.totalCost + 10) then
                        continue
                    end

                    local preChanceOk, preChanceError = travelToTarget('Shrine of Chance', waypoint1, function(
                        pathNode
                    )
                        return performChanceTransaction(pathNode, preSafeOffer)
                    end)

                    if not preChanceOk then
                        if preChanceError == 'Shrine of Chance UI needs identification' then
                            ax.progress = 'Switching servers for Shrine of Chance'

                            noEffects.hop(state.slot, true)

                            return
                        end

                        handleProgress(preChanceError)
                    else
                        showProgress('Verifying reroll', 2)
                    end

                    continue
                end
                if next(missingPreMantras) then
                    local unwantedMantra

                    for ownedMantraId in pairs(talentPicker.owned(characterSnapshot, 'Mantras'))do
                        if not (build.wantedMantras or build.mantras)[ownedMantraId] then
                            unwantedMantra = true

                            break
                        end
                    end

                    local shrineType = unwantedMantra and 'temptation' or 'unification'

                    if shrineType == 'unification' then
                        local spareTalents = 0

                        for ownedTalentId in pairs(talentPicker.owned(characterSnapshot, 'Talents'))do
                            if not (build.wantedTalents or build.talents)[ownedTalentId] then
                                spareTalents = spareTalents + 1
                            end
                        end

                        if spareTalents < 2 then
                            handleAutomationChild(nil)
                            showProgress('Waiting for two spare talents for Shrine of Unification', 2)

                            continue
                        end
                    end
                    if waitForKnowledgeTarget(characterSnapshot, state, shrineType, 5) then
                        continue
                    end

                    ax.progress = unwantedMantra and 'Rerolling pre-shrine mantra' or 'Unifying talents for pre-shrine mantra'

                    local shrineResult, shrineNote

                    if unwantedMantra then
                        shrineResult, shrineNote = runShrineOfTemptation(build, characterSnapshot)
                    else
                        shrineResult, shrineNote = handleUnificationOutput(build)
                    end
                    if not shrineResult and shrineNote == 'No unneeded mantra to offer at Shrine of Temptation' then
                        if waitForKnowledgeTarget(waitForTalentData() or characterSnapshot, getSession(), 'unification', 5) then
                            continue
                        end

                        shrineType = 'unification'
                        shrineResult, shrineNote = handleUnificationOutput(build)
                    end
                    if shrineResult then
                        showProgress('Choosing shrine mantra', 2)
                    else
                        if shrineType == 'unification' then
                            handleProgress(shrineNote)
                        else
                            showProgress(shrineNote or 'Waiting for Shrine of Temptation', 3)
                        end
                    end

                    continue
                end

                local power = talentPicker.power(characterSnapshot) or 0

                if power >= 5 and power <= 7 then
                    if state.blasphemyUsedFor == build.url then
                        handleProgress('Shrine of Blasphemy was already used for this build')

                        continue
                    end
                    if waitForKnowledgeTarget(characterSnapshot, state, 'blasphemy', 5) then
                        continue
                    end

                    handleAutomationChild(nil)

                    local blasphemyOk, blasphemyError = travelToTarget('Shrine of Blasphemy', waypoint18, clickShrineOption, 'Etrean')

                    if not blasphemyOk then
                        handleProgress(blasphemyError)
                    else
                        showProgress('Verifying Shrine of Blasphemy Power ups', 1)
                    end

                    continue
                end
                if power < 8 then
                    if handleAutomationChild(getAutomationHandler(characterSnapshot)) then
                        showProgress('Reaching Power 8 before Shrine of Order', 2)
                    else
                        showProgress('Waiting for XP farm', 2)
                    end

                    continue
                end
                if waitForKnowledgeTarget(characterSnapshot, state, 'order', 10) then
                    continue
                end

                handleAutomationChild(nil)

                local orderOk, orderError = travelToTarget('Shrine of Order', waypoint2, confirmShrineOrder)

                if orderOk then
                    local orderTimeout = os.clock() + 10

                    repeat
                        task.wait(0.3)

                        local orderData = waitForTalentData()

                        if orderData and not talentPicker.targetsMet(orderData, build.pre) then
                            state.phase = 'post'
                            state.phaseConfirmed = true
                            state.phaseSource = 'verified'
                            state.orderVerifiedFor = buildCharacterKey(orderData) .. ':' .. build.url
                            state.reconcileState = 'partial_post'

                            setSession(state)

                            break
                        end
                    until os.clock() >= orderTimeout or not isArmed(progression)

                    if state.phase ~= 'post' then
                        handleProgress('Shrine of Order result could not be verified')
                    end
                else
                    handleProgress(orderError)
                end

                continue
            end
            if state.phase == 'post' and state.phaseConfirmed and not state.inexact and (talentPicker.power(characterSnapshot) or 0) >= 20 then
                local postAttributes = collectStats(characterSnapshot)

                if not postAttributes then
                    showProgress('Waiting for exact post-Shrine attributes', 2)

                    continue
                end
                if next(statInference.overshoots(build.post, postAttributes)) then
                    if not meetsMasteryRequirements(characterSnapshot) then
                        if tonumber(characterSnapshot.FullAttributePoints) == nil then
                            showProgress('Waiting for attribute points', 1)
                        elseif (tonumber(characterSnapshot.FullAttributePoints) or 0) > 0 and talentPicker.nextStat(characterSnapshot, build.post, build, state.phase) then
                            showProgress('Spending remaining points', 0.2)
                        elseif (tonumber(characterSnapshot.AvailableAttributePoints) or 0) > 0 then
                            if handleAutomationChild('auto_ferryman') then
                                showProgress('Farming XP for pending attribute points', 2)
                            else
                                showProgress('Waiting for Ferryman to earn attribute points', 2)
                            end
                        else
                            handleProgress(
"Mastery needs zero remaining points; no build stat can use them")
                        end

                        continue
                    end
                    if isInTrialOfOne() or isFerrymanTargetValid() or placeIds.isDungeon() then
                        showProgress('Waiting to correct post-Shrine attributes', 2)

                        continue
                    end
                    if statInference.required(build.post, postAttributes) > 3 - (tonumber(state.masteryPointsUsed) or 0) then
                        handleProgress('Shrine of Mastery three-point limit reached')

                        continue
                    end
                    if waitForKnowledgeTarget(characterSnapshot, state, 'mastery', 1) then
                        continue
                    end
                    if not handleAutomationChild(nil) then
                        showProgress('Waiting for movement control before Shrine of Mastery', 1)

                        continue
                    end

                    local masteryOk, masteryError = travelToTarget('Shrine of Mastery', waypoint19, checkMasteryReady, 'Eastern')

                    if masteryOk then
                        showProgress('Verifying Shrine of Mastery reduction', 1)
                    else
                        handleProgress(masteryError or 'Shrine of Mastery correction needs verification')
                    end

                    continue
                end
                if not talentPicker.targetsMet(characterSnapshot, build.post) and (tonumber(characterSnapshot.FullAttributePoints) or 0) <= 0 then
                    if handleAutomationChild('auto_ferryman') then
                        showProgress('Progressing remaining build stats with Ferryman', 2)
                    else
                        showProgress('Waiting for Ferryman to progress build stats', 2)
                    end

                    continue
                end
                if not talentPicker.targetsMet(characterSnapshot, build.post) or not talentPicker.traitsMet(characterSnapshot, build) then
                    showProgress('Finishing post-Shrine allocation', 0.2)

                    continue
                end
                if not ringData.complete(ringTargets, characterSnapshot) then
                    if #noEffects.automation.progressionScalingRingsNeeded > 0 or placeIds.isDungeon() then
                        handleAutomationChild('auto_ferryman')
                        showProgress('Farming post-Shrine scaling rings', 2)
                    else
                        handleAutomationChild(nil)
                        showProgress('Equipping post-Shrine scaling rings', 2)
                    end

                    continue
                end

                local questsPending = state.ministryReportQuest ~= 'complete' or state.arthurQuest ~= 'complete' or state.atraQuest ~= 'complete'

                if questsPending and not placeIds.isEtrean() then
                    if not handleAutomationChild(nil) then
                        showProgress('Waiting for movement control before Echo talent quests', 1)

                        continue
                    end
                    if placeIds.isDungeon() then
                        ax.progress = 'Leaving dungeon for Echo talent quests in Etrean'

                        setSession(state)
                        noEffects.hop(state.slot, true)

                        return
                    end

                    ax.progress = 'Travelling to Etrean for Echo talent quests'

                    if not executionQueue.request(ax, 'Echo talent quests in Etrean') or not executionQueue.acquire(ax) then
                        showProgress('Waiting for movement control before Etrean', 1)

                        continue
                    end

                    local transferOk, transferError = regionTransfer.toEtrean(nil, function()
                        return isArmed(progression)
                    end)

                    executionQueue.cancel(ax, 'Echo quest region travel ended')

                    if not isArmed(progression) then
                        return
                    end
                    if not transferOk or not placeIds.isEtrean() then
                        handleProgress('Etrean transfer failed: ' .. tostring(transferError or 'region not confirmed'))
                    end

                    continue
                end
                if not tryStartMinistryQuest(characterSnapshot) then
                    continue
                end
                if not canStartArthurQuest(characterSnapshot, progression) then
                    continue
                end
                if not canStartAtraQuest(characterSnapshot) then
                    continue
                end

                local cleanupAttrs = getOwnedTalents(characterSnapshot)
                local cleanupMissing = talentPicker.missing(build, build.wantedTalents or build.talents, cleanupAttrs)
                local cleanupTalents = {}

                for cleanupTalentId, cleanupTalent in pairs(cleanupMissing)do
                    if talentPicker.eligible(characterSnapshot, build.metadata[cleanupTalentId], cleanupAttrs, build.metadata) then
                        cleanupTalents[cleanupTalentId] = cleanupTalent
                    end
                end

                if next(cleanupTalents) then
                    if not state.talentCleanup then
                        state.talentCleanup = true

                        setSession(state)
                    end

                    local isSafe = collectProtectedTalents(build, cleanupAttrs)
                    local cleanupOffer = isSafe and resolveChanceChain(build, cleanupTalents, cleanupAttrs, isSafe)

                    if cleanupOffer and (talentPicker.knowledge(characterSnapshot) or 0) >= cleanupOffer.totalCost then
                        if not handleAutomationChild(nil) then
                            showProgress('Waiting to finish build talents', 1)

                            continue
                        end

                        local cleanupOk, cleanupError = travelToTarget('Shrine of Chance', waypoint1, function(
                            cleanupNode
                        )
                            return performChanceTransaction(cleanupNode, cleanupOffer)
                        end)

                        if cleanupOk then
                            showProgress('Verifying build talent', 2)

                            continue
                        end
                        if cleanupError ~= 'Shrine of Chance UI needs identification' and cleanupError ~= 'No eligible talents offered by Shrine of Chance' and cleanupError ~= 'Safe donor talent was not offered' then
                            handleProgress(cleanupError or 'Build talent reroll needs verification')

                            continue
                        end
                    end
                end
                if not handleAutomationChild(nil) then
                    showProgress('Waiting for movement control', 1)

                    continue
                end
                if not bt() then
                    handleProgress('Shrine dialogue did not close')

                    continue
                end

                state.talentCleanup = nil
                state.complete = true

                setSession(state)

                ax.progress = next(cleanupMissing) and 'Build complete; remaining talents need another source' or 'Build complete'
                ax.completedAt = os.clock()

                ax:stop()

                return
            end
            if state.phase == 'post' and (talentPicker.power(characterSnapshot) or 0) >= 20 then
                if (tonumber(characterSnapshot.FullAttributePoints) or 0) > 0 and talentPicker.nextStat(characterSnapshot, build.post, build, state.phase) then
                    if startTraining(progression, characterSnapshot, build.post) then
                        continue
                    end

                    handleAutomationChild(nil)
                    showProgress('Spending remaining points', 0.2)
                else
                    if handleAutomationChild('auto_ferryman') then
                        showProgress('Progressing remaining build stats with Ferryman', 2)
                    else
                        showProgress('Waiting for Ferryman to progress build stats', 2)
                    end
                end

                continue
            end
            if isInTrialOfOne() or getSession().trialActive or isFerrymanTargetValid() then
                task.wait(0.05)

                continue
            end
            if getAutomationHandler(characterSnapshot) ~= 'auto_authority_missions' and startTraining(progression, characterSnapshot, phaseTarget) then
                continue
            end
            if getAutomationHandler(characterSnapshot) == 'auto_authority_missions' then
                if handleAutomationChild('auto_authority_missions') then
                    showProgress('Progressing with Authority missions', 2)
                else
                    showProgress('Waiting for Authority missions', 2)
                end
            elseif handleAutomationChild('auto_ferryman') then
                showProgress('Progressing with Ferryman', 2)
            else
                showProgress('Waiting for Ferryman', 2)
            end
        end
    end

    function ax:armed()
        return noEffects.flag('auto_progression', false)
    end
    function ax:displayProgress()
        local childWorker = self.child and getLoader().get(self.child)

        if childWorker and childWorker.progress then
            return childWorker.progress
        end

        local progress = self.progress or 'Preparing progression'
        local detection = getSession()

        if progress == 'Preparing progression' or progress == 'Reconciling character progress' then
            progress = 'Checking your build'
        elseif detection.phaseEvidence == 'ambiguous stat distribution' and not detection.phaseConfirmed then
            progress = 'Paused: cannot confirm Shrine of Order use'
        end

        local labelMap = {
            ['Travelling to Etrean for Echo talent quests'] = 'Travelling to Etrean',
            ['Travelling to Arthur\u{2019}s Megalodaunt'] = 'Finding Sharko',
            ['Travelling to Ministry field report'] = 'Finding the quest book',
            ['Waiting for current task checkpoint'] = 'Finishing current task',
            ['Waiting for movement control'] = 'Finishing current task',
            ['Finishing post-Shrine allocation'] = 'Spending remaining points',
        }

        progress = labelMap[progress] or progress

        local stat = self.goalStat or self.trainingStat
        local statNames = {
            ElementIce = 'Frostdraw',
            ElementFire = 'Flamecharm',
            ElementLightning = 'Thundercall',
            ElementWind = 'Galebreathe',
            ElementShadow = 'Shadowcast',
            ElementMetal = 'Ironsing',
            ElementBlood = 'Bloodrend',
            WeaponHeavy = 'Heavy Weapons',
            WeaponMedium = 'Medium Weapons',
            WeaponLight = 'Light Weapons',
        }

        stat = statNames[stat] or stat

        local lowerProgress = progress:lower()

        if lowerProgress:find('wait', 1, true) or lowerProgress:find('pause', 1, true) or lowerProgress:find('need', 1, true) or lowerProgress:find('verif', 1, true) or lowerProgress:find('missing', 1, true) or lowerProgress:find('could not', 1, true) or lowerProgress:find('full', 1, true) or lowerProgress:find('no ', 1, true) == 1 or lowerProgress:find('switching', 1, true) == 1 or lowerProgress:find('unwanted', 1, true) == 1 then
            return progress
        end
        if self.child == 'auto_ferryman' then
            local ferrymanWorker = getLoader().get(self.child)
            local ferrymanProgress = ferrymanWorker and ferrymanWorker.progress

            if ferrymanProgress then
                return ferrymanProgress
            end
            if ferrymanProgress and (ferrymanProgress:find('Waiting', 1, true) or ferrymanProgress:find('Retrying', 1, true) or ferrymanProgress:find('campfires', 1, true) or ferrymanProgress == 'Finding another server' or ferrymanProgress == 'Healing' or ferrymanProgress == 'Inventory full') then
                return ferrymanProgress
            end

            return string.format('Farming %s \u{b7} Auto Ferryman', stat or 'build XP')
        elseif self.child == 'auto_titus' then
            return 'Farming Knowledge \u{b7} Auto Titus'
        elseif progress == 'Allocating Fortitude' then
            return 'Spending Fortitude points'
        elseif progress == 'Training Fortitude' then
            return 'Training Fortitude'
        elseif progress == 'Training Intelligence' then
            return 'Training Intelligence'
        elseif progress == 'Training Charisma' then
            return 'Training Charisma'
        elseif progress:find('Trial:', 1, true) == 1 then
            return 'Trial \u{b7} ' .. progress:sub(8)
        elseif progress:find('Shrine of Chance', 1, true) then
            return 'Choosing build talents'
        elseif progress:find('Shrine of Order', 1, true) then
            return 'Using Shrine of Order'
        elseif progress:find('Shrine of Blasphemy', 1, true) then
            return 'Using Shrine of Blasphemy'
        elseif progress:find('Shrine of Mastery', 1, true) then
            return 'Correcting build stats'
        end

        return progress
    end
    function ax:start()
        if self.running or not self:armed() then
            return
        end

        self.running = true
        self.completedAt = nil

        talentPicker.resetData()

        self.mode = getSession().mode or 'progression'
        self.progress = self.mode == 'talents' and 'Checking build talents' or 'Preparing progression'
        self.hopRequested = false
        self.ferrymanMantraTraining = nil
        self.goalStat = nil
        noEffects.automation.ferrymanMantraTraining = nil
        noEffects.automation.kaidoManifestationNeeded = nil
        noEffects.automation.progressionScalingRingsNeeded = nil
        self.generation = self.generation + 1
        self.startedAt = os.clock()
        self.recovery = self.recoveryPolicy.new(self.startedAt)
        self.tomeUse = nil

        local session = getSession()

        if type(session.sessionStartedAt) ~= 'number' then
            session.sessionStartedAt = os.time()

            setSession(session)
        end

        self.sessionStartedAt = session.sessionStartedAt

        if canWipeSlot(session) then
            return
        end

        local generation = self.generation

        self.watchdogThread = task.spawn(function()
            while isArmed(generation) do
                local state = getSession()
                local stallFingerprint = buildProfileSignature(talentPicker.data()) .. '|' .. tostring(state.phase) .. '|' .. tostring(state.orderVerifiedFor)
                local activeJob = executionQueue.active
                local lastProgress

                if activeJob and activeJob.lastProgress and (activeJob.owner == self or self.child and activeJob.owner == getLoader().get(self.child)) then
                    lastProgress = activeJob.lastProgress
                end
                if self.recovery:stalled(stallFingerprint, lastProgress, os.clock()) then
                    self.hopRequested = true
                    self.progress = 'Switching servers: task stalled'

                    self:stopTravel()
                    noEffects.hop(getSession().slot, true)

                    return
                end

                task.wait(5)
            end
        end)
        self.nearbyThread = task.spawn(function()
            while isArmed(generation) do
                if canWipeSlot(getSession()) then
                    return
                end
                if playerScanning.hasModerators() or bp() then
                    self.hopRequested = true

                    if self.statsThread then
                        pcall(task.cancel, self.statsThread)
                    end

                    self.statsThread = nil

                    talentPicker.cancelSpend()
                    talentPicker.cancelFavour()

                    if self.thread then
                        pcall(task.cancel, self.thread)
                    end

                    self.thread = nil

                    for farmName, farm in pairs(getLoader().farms)do
                        if farm:armed() then
                            farm:setArmed(false)
                        end
                    end

                    self.child = nil
                    self.switching = false

                    self:stopTravel()
                    self:stopTrial()

                    self.travelFeatures = {
                        Flight = noEffects.featureActive('Flight'),
                        NoClip = noEffects.featureActive('NoClip'),
                        NoFallDamage = noEffects.featureActive('NoFallDamage'),
                    }

                    for feature in pairs(self.travelFeatures)do
                        noEffects.enableFeature(feature)
                    end

                    self.progress = 'Switching servers'

                    noEffects.hop(getSession().slot, true)

                    return
                end

                task.wait(0.5)
            end
        end)
        self.depthsSafetyThread = task.spawn(function()
            while isArmed(generation) do
                local humanoid = noEffects.localPlayer.humanoid

                if placeIds.isDepths() and not self.depthsHealing and humanoid and humanoid.MaxHealth > 0 and humanoid.Health > 0 and humanoid.Health / humanoid.MaxHealth <= 0.35 then
                    shouldHeal(generation)
                end

                task.wait(0.1)
            end
        end)
        self.thread = task.spawn(function()
            local success, cG = pcall(applyProgression, generation)

            if not success and isArmed(generation) then
                if self.statsThread then
                    pcall(task.cancel, self.statsThread)
                end

                self.statsThread = nil

                talentPicker.cancelSpend()
                talentPicker.cancelFavour()
                progressionTraining.restorePassive()

                if self.trialFeatures then
                    self:stopTrial()
                end

                self:stopTravel()
                self:stopTraining()
                handleAutomationChild(nil)

                self.progress = 'Progression paused: ' .. tostring(cG)
            end

            self.running = false
        end)
    end
    function ax:stop()
        executionQueue.cancel(self, 'progression stopped')
        delayedTask.cancel()

        noEffects.automation.forceSkyAfterFortitude = nil

        if not self:armed() and not self.running and not self.child then
            return
        end

        self.generation = self.generation + 1

        if self.statsThread then
            pcall(task.cancel, self.statsThread)
        end

        self.statsThread = nil

        if self.watchdogThread and self.watchdogThread ~= coroutine.running() then
            pcall(task.cancel, self.watchdogThread)
        end

        self.watchdogThread = nil

        if self.nearbyThread and self.nearbyThread ~= coroutine.running() then
            pcall(task.cancel, self.nearbyThread)
        end

        self.nearbyThread = nil

        if self.depthsSafetyThread and self.depthsSafetyThread ~= coroutine.running() then
            pcall(task.cancel, self.depthsSafetyThread)
        end

        self.depthsSafetyThread = nil

        talentPicker.resetData()
        noEffects.setFlag('auto_progression', false)

        if self.prompt then
            self.prompt:Destroy()

            self.prompt = nil
        end

        self.pendingWipe = nil
        self.ferrymanMantraTraining = nil
        noEffects.automation.ferrymanMantraTraining = nil
        noEffects.automation.kaidoManifestationNeeded = nil
        noEffects.automation.progressionScalingRingsNeeded = nil
        self.trainingBusy = nil
        self.trainingStat = nil
        self.goalStat = nil
        self.depthsHealPosition = nil
        self.depthsHealing = nil

        progressionTraining.restorePassive()
        self:stopTrial()
        self:stopTravel()
        self:stopTraining()

        if self.child then
            getLoader().set(self.child, false)

            self.child = nil
        end

        migrateTitusSettings()

        local state = getSession()

        disableTarget(state)
        setSession(state)
        restoreSessionFeatures()

        if self.thread and self.thread ~= coroutine.running() then
            pcall(task.cancel, self.thread)
        end

        self.thread = nil
        self.running = false
    end
    function ax:enable(buildLink, slot, mode)
        buildLink = tostring(buildLink or ''):gsub('%s+', '')

        if not buildLink or not buildLink:match('^https?://[%w%.]*deepwoken%.co/builder%?id=[%w]+') then
            logger.notify('Enter a deepwoken.co builder link first.')

            return false
        end
        if getLoader().hasAny() then
            logger.notify('Stop the active automation first.')

            return false
        end

        local config = getSession()

        mode = mode or 'progression'

        local isNewSession = config.enabled ~= true or config.build ~= buildLink or (config.mode or 'progression') ~= mode or tostring(config.slot) ~= tostring(slot)

        if config.build ~= buildLink or (config.mode or 'progression') ~= mode then
            if tostring(config.slot) == tostring(slot) then
                config.build = buildLink
                config.mode = mode
                config.phase = nil
                config.phaseConfirmed = nil
                config.phaseSource = nil
                config.phaseEvidence = nil
                config.reconcileState = nil
                config.inexact = nil
                config.paused = nil
                config.orderVerifiedFor = nil
                config.activeTask = nil
                config.oathlessStage = nil
                config.ferrymanCycle = nil
            else
                config = {
                    build = buildLink,
                    slot = slot,
                }
            end
        end

        config.mode = mode

        if isNewSession then
            config.sessionStartedAt = os.time()
        end

        config.enabled = true
        config.slot = slot
        config.paused = nil

        noEffects.setValue('progression_build_link', buildLink)
        setSession(config)
        noEffects.setFlag('auto_progression', true)
        self:start()

        return true
    end
    function ax:init()
        if self:armed() and getSession().enabled ~= false then
            for farmName, farm in pairs(getLoader().farms)do
                if farm:armed() then
                    self.child = farmName

                    break
                end
            end

            self:start()
        end
    end
    function ax:detach()
        self.generation = self.generation + 1

        if self.statsThread then
            pcall(task.cancel, self.statsThread)
        end

        self.statsThread = nil

        talentPicker.cancelSpend()
        talentPicker.cancelFavour()

        if self.nearbyThread and self.nearbyThread ~= coroutine.running() then
            pcall(task.cancel, self.nearbyThread)
        end

        self.nearbyThread = nil

        if self.depthsSafetyThread and self.depthsSafetyThread ~= coroutine.running() then
            pcall(task.cancel, self.depthsSafetyThread)
        end

        self.depthsSafetyThread = nil
        self.ferrymanMantraTraining = nil
        noEffects.automation.ferrymanMantraTraining = nil
        self.trainingBusy = nil
        self.trainingStat = nil
        self.depthsHealPosition = nil
        self.depthsHealing = nil

        progressionTraining.restorePassive()
        self:stopTrial()
        self:stopTravel()
        self:stopTraining()
        restoreSessionFeatures()

        if self.prompt then
            self.prompt:Destroy()

            self.prompt = nil
        end
        if self.thread and self.thread ~= coroutine.running() then
            pcall(task.cancel, self.thread)
        end

        self.thread = nil
        self.running = false
    end

    return ax
end


return aa()

