                    delayedTask.method(sendDialogue, 'FireServer', {exit = true})
                end)
                task.wait(2.5)
            end
        end

        local waitStart = tick()
        local leverFired = false

        repeat
            local trial = workspace:FindFirstChild('DepthsTrial')
            local platform = trial and trial:FindFirstChild('CircularPlatform')
            local lever = platform and platform:FindFirstChild('DepthsTrialDungeonLever')
            local leverPrompt = lever and lever:FindFirstChild('InteractPrompt')

            if leverPrompt then
                pcall(delayedTask.call, fireScript, leverPrompt)

                leverFired = true
            elseif leverFired then
                break
            end

            task.wait(0.5)
        until tick() - waitStart > 15 or not an:armed()

        config.fightTrial()
    end
    function config.fightTrial()
        config.applyCombatMode()

        while an:armed() do
            local searchStart = tick()

            repeat
                task.wait()
            until config.foundMobs() or tick() - searchStart > 15 or not an:armed()

            if not config.foundMobs() then
                break
            end

            repeat
                config.healCheck()
                pcall(function()
                    local mob = config.closestMob()

                    if not mob then
                        return
                    end
                    if config.voiding() then
                        mobVoider.voidMob(mob, function()
                            return an:armed()
                        end)

                        return
                    end

                    config.killTarget(mob)
                end)
                task.wait()
            until not config.foundMobs() or not an:armed()
        end

        config.autoM1(false)
    end

    an = automationStep.construct({
        id = 'auto_escape_depths',
        persistentFlag = 'auto_escape_depths',
        features = {
            'NoFallDamage',
            'NoClip',
            'NoFire',
            'NoStun',
            'FastSwing',
            'PathfindBreaker',
        },
        notAllowed = function()
            if as() then
                noEffects.setFlag('auto_escape_depths', false)

                return true
            end

            return false
        end,
        stateMachine = stateMachine.create({
            initial = 'idle',
            events = {
                {
                    name = 'start',
                    from = {
                        'idle',
                        '_enter_trial',
                        '_begin_trial',
                    },
                    to = '_check_area',
                },
                {
                    name = 'enter',
                    from = '_check_area',
                    to = '_enter_trial',
                },
                {
                    name = 'begin',
                    from = '_check_area',
                    to = '_begin_trial',
                },
                {
                    name = 'complete',
                    from = '_check_area',
                    to = '_complete',
                },
                {
                    name = 'retry',
                    from = '_check_area',
                    to = 'idle',
                },
            },
            callbacks = {
                onenter_check_area = function(node)
                    local currentArea = noEffects.localPlayer.instance:GetAttribute('CurrentArea')
                    local rootPartPos = ap()
                    local npcsSelf = workspace:FindFirstChild('NPCs')
                    local selfNpc = npcsSelf and npcsSelf:FindFirstChild('Self')
                    local nearSelf = rootPartPos and selfNpc and (rootPartPos.Position - Vector3.new(2910, 1133.03, 1474)).Magnitude < 250

                    if currentArea and currentArea:find('Fragments of Self', 1, true) or nearSelf then
                        if noEffects.flag('auto_progression', false) then
                            local progression = noEffects.value('progression_session', {})
                            local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

                            if progression.enabled and progression.mode ~= 'talents' and progression.slot and dataSlot and tostring(progression.slot) == tostring(dataSlot) then
                                an:setArmed(false)
                                logger.notify('Auto Progression: wiping slot in Fragments of Self.')

                                if not persistentData.get('wdata') then
                                    task.defer(function()
                                        a["Game/Wipe"]().invoke(progression.slot)
                                    end)
                                end

                                return
                            end
                        end

                        logger.notify(
"Auto Escape Depths: ended up in Fragments of Self, disarming.")
                        an:setArmed(false)

                        return
                    end
                    if ar() then
                        return node:enter()
                    end
                    if placeIds.isDungeon() then
                        if workspace:WaitForChild('DepthsTrial', 120) then
                            return node:begin()
                        end

                        return node:retry()
                    end
                    if as() then
                        return node:complete()
                    end

                    return node:retry()
                end,
                onenteridle = function(idleNode)
                    an:delay(3, function()
                        if an:armed() then
                            pcall(function()
                                idleNode:start()
                            end)
                        end
                    end)
                end,
                onenter_enter_trial = function(enterNode)
                    config.enterTrial()
                    an:defer(enterNode.start, enterNode)
                end,
                onenter_begin_trial = function(beginNode)
                    config.beginTrial()
                    an:defer(beginNode.start, beginNode)
                end,
                onenter_complete = function()
                    an:setArmed(false)
                    logger.notify('Successfully escaped the Depths.')
                    noEffects.hop(noEffects.localPlayer.instance:GetAttribute('DataSlot') or 'A', false)
                end,
            },
        }),
    })
    an.logic = config

    return an
end


return aa()

]=],
    ["Features/Automation/AutomationManager"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local noEffects = a["Features/Game/NoEffects"]()
    local kaidoFarm2 = a["Features/Automation/KaidoFarm2"]()
    local logger = a["Utility/Logger"]()
    local quickToggles = a["Features/Game/QuickToggles"]()
    local toggleFarm = function(farmKey, farmName)
        local farmToggler = kaidoFarm2.get(farmKey)

        if not farmToggler then
            return logger.notify('%s is not available in this build.', farmName)
        end

        local targetState = not farmToggler:armed()

        if not kaidoFarm2.set(farmKey, targetState) then
            return
        end

        logger.notify('%s [%s]', farmName, targetState and 'ON' or 'OFF')
    end

    function module.initResources(window)
        local resourcesTab = window:AddTab('Resources')
        local optionsTab = window:AddTab('Options')

        resourcesTab:AddButton({
            Text = 'Titus Relic Farm',
            Func = function()
                task.spawn(function()
                    if kaidoFarm2.get('auto_titus'):armed() and noEffects.flag('auto_titus_echo_mode', false) then
                        logger.notify('Stop Titus Echo Farm before starting Titus Relic Farm.')

                        return
                    end

                    noEffects.setFlag('auto_titus_echo_mode', false)
                    noEffects.setValue('auto_titus_relics', configuration.expectOptionValue('TitusFarmRelics') or {})
                    noEffects.setValue('auto_titus_bank_items', configuration.expectOptionValue('TitusBankItems') or {})
                    toggleFarm('auto_titus', 'Auto Titus')
                end)
            end,
            Tooltip = 'Start anywhere.',
        })
        resourcesTab:AddButton({
            Text = 'Titus Echo Farm',
            Func = function()
                local titusToggler = kaidoFarm2.get('auto_titus')

                if titusToggler:armed() then
                    if not noEffects.flag('auto_titus_echo_mode', false) then
                        logger.notify('Stop Titus Relic Farm before starting Titus Echo Farm.')

                        return
                    end

                    kaidoFarm2.set('auto_titus', false)
                    noEffects.setFlag('auto_titus_echo_mode', false)
                    logger.notify('Titus Echo Farm [OFF]')

                    return
                end

                noEffects.setFlag('auto_titus_echo_mode', true)

                if not kaidoFarm2.set('auto_titus', true) then
                    noEffects.setFlag('auto_titus_echo_mode', false)

                    return
                end

                noEffects.setValue('auto_titus_echo_started_at', os.time())
                noEffects.setValue('auto_titus_echo_start_runs', tonumber(noEffects.value('auto_titus_echo_runs', 0)) or 0)
                noEffects.setValue('auto_titus_echo_start_earned', tonumber(noEffects.value('auto_titus_echo_earned', 0)) or 0)
                logger.notify('Titus Echo Farm [ON]')
            end,
            Tooltip = 
"Start anywhere. Defeat Titus, collect Echo relics, wipe the selected slot, and recreate a Merit Pathfinder character.",
        })

        local relicsDropdown = optionsTab:AddDropdown('TitusFarmRelics', {
            Text = 'Relics',
            Values = {
                'Moonseye Tome',
                "Idol of Yun'Shul",
                "Armorer's Needle",
                "Smith's Alloy",
                'Enchant Stone',
            },
            Default = {
                "Idol of Yun'Shul",
            },
            Multi = true,
            AllowNull = true,
            Tooltip = 'What relics you would like the farm to loot.',
        })

        relicsDropdown:SetValue(noEffects.value('auto_titus_relics', relicsDropdown.Value))
        relicsDropdown:OnChanged(function(newRelics)
            noEffects.setValue('auto_titus_relics', newRelics)
        end)

        local bankDropdown = optionsTab:AddDropdown('TitusBankItems', {
            Text = 'Bank At 25',
            Values = {
                'Moonseye Tome',
                "Idol of Yun'Shul",
                "Armorer's Needle",
                "Smith's Alloy",
                'Enchant Stone',
            },
            Default = {},
            Multi = true,
            AllowNull = true,
            Tooltip = 
"Once 25 of any selected relic are held, the farm detours to a banker.",
        })

        bankDropdown:SetValue(noEffects.value('auto_titus_bank_items', bankDropdown.Value))
        bankDropdown:OnChanged(function(newBankItems)
            noEffects.setValue('auto_titus_bank_items', newBankItems)
        end)
    end

    local setupLootConfig = function(tab, sectionPrefix, configPrefix, allItems)
        local lootAllToggle = tab:AddToggle(sectionPrefix .. 'LootAll', {
            Text = 'Loot everything (ignore selections)',
            Default = noEffects.value(configPrefix .. '_loot_all', false),
        })

        lootAllToggle:OnChanged(function(newValue)
            noEffects.setValue(configPrefix .. '_loot_all', newValue)
        end)

        local godrollToggle = tab:AddToggle(sectionPrefix .. 'GodrollRings', {
            Text = 'Godroll rings only',
            Default = noEffects.value(configPrefix .. '_godroll_rings', false),
            Tooltip = 
"Only loot two-star rings with 6 HP / 2 Posture, 7 HP / 1 Posture, or 3 HP / 3 Posture, even with Loot All.",
        })

        godrollToggle:OnChanged(function(newGodroll)
            noEffects.setValue(configPrefix .. '_godroll_rings', newGodroll)
        end)

        local selectedItems = a["Game/Items/ItemFilters"]().selection(noEffects.value(configPrefix .. '_selected', {}), allItems)

        noEffects.setValue(configPrefix .. '_selected', selectedItems)

        for catIndex, category in ipairs(allItems)do
            local checkedMap = {}

            for itemIdx, itemName in ipairs(category.items)do
                if selectedItems[itemName] == true then
                    checkedMap[itemName] = true
                end
            end

            local categoryDropdown = tab:AddDropdown(sectionPrefix .. 'LootV2' .. category.name:gsub('%W', ''), {
                Text = category.name,
                Values = category.items,
                Multi = true,
                AllowNull = true,
                Tooltip = 
"Only checked items are collected. Unchecked items stay in the chest.",
            })

            categoryDropdown:SetValue(checkedMap)
            categoryDropdown:OnChanged(function(newCategorySel)
                local clonedSelection = table.clone(noEffects.value(configPrefix .. '_selected', {}))

                for entryIndex, itemKey in ipairs(category.items)do
                    clonedSelection[itemKey] = newCategorySel[itemKey] == true or nil
                end

                noEffects.setValue(configPrefix .. '_selected', clonedSelection)
            end)
        end

        local customInput = tab:AddInput(sectionPrefix .. 'LootItems', {
            Text = 'Custom loot names',
            Default = table.concat(noEffects.value(configPrefix .. '_items', {}), '; '),
            Finished = true,
            Tooltip = 
"Exact item names separated by semicolons. These are added to your checked items.",
        })

        customInput:OnChanged(function(inputText)
            local parsedItems = {}

            for token in tostring(inputText or ''):gmatch('[^;]+')do
                local trimmedName = token:match('^%s*(.-)%s*$')

                if trimmedName ~= '' then
                    parsedItems[#parsedItems + 1] = trimmedName
                end
            end

            noEffects.setValue(configPrefix .. '_items', parsedItems)
        end)
    end

    function module.initBosses(tabs)
        local ferrymanBox = tabs:AddRightTabbox()
        local ferrymanTab = ferrymanBox:AddTab('Ferryman')
        local bossOptionsTab = ferrymanBox:AddTab('Options')
        local kaidoBox = tabs:AddRightTabbox()
        local kaidoTab = kaidoBox:AddTab('Kaido')
        local kaidoOptionsTab = kaidoBox:AddTab('Options')

        kaidoTab:AddButton({
            Text = 'Auto Kaido',
            Func = function()
                toggleFarm('auto_kaido', 'Auto Kaido')
            end,
            Tooltip = 
"Summon and fight the Dread Serpent with an Ardour Manifestation.",
        })
        setupLootConfig(kaidoOptionsTab, 'Kaido', 'auto_kaido', a["Game/Items/ItemFilters"]().kaidoGroups)

        local parasolBox = tabs:AddRightTabbox()
        local parasolTab = parasolBox:AddTab('Parasol')
        local parasolOptionsTab = parasolBox:AddTab('Options')

        parasolTab:AddButton({
            Text = 'Auto Parasol',
            Func = function()
                toggleFarm('auto_parasol', 'Parasol Relic Farm')
            end,
            Tooltip = 
"Only in the Parasol place. Voids .parasol1, then loots the relic chests (checked items only).",
        })
        setupLootConfig(parasolOptionsTab, 'Parasol', 'auto_parasol', a["Game/Items/ItemFilters"]().parasolGroups)

        i = bossOptionsTab

        ferrymanTab:AddButton({
            Text = 'Auto Ferryman',
            Func = function()
                toggleFarm('auto_ferryman', 'Auto Ferryman')
            end,
            Tooltip = 'Farm Ferryman until Stop automation is pressed.',
        })

        local lootAllToggle = i:AddToggle('FerrymanLootAll', {
            Text = 'Loot everything (ignore selections)',
            Default = noEffects.value('auto_ferryman_loot_all', false),
        })

        lootAllToggle:OnChanged(function(lootAllValue)
            noEffects.setValue('auto_ferryman_loot_all', lootAllValue)
        end)

        local godrollToggle = i:AddToggle('FerrymanGodrollRings', {
            Text = 'Godroll rings only',
            Default = noEffects.value('auto_ferryman_godroll_rings', false),
            Tooltip = 
"Only loot two-star rings with 6 HP / 2 Posture, 7 HP / 1 Posture, or 3 HP / 3 Posture, even with Loot All. Other loot is unchanged.",
        })

        godrollToggle:OnChanged(function(godrollValue)
            noEffects.setValue('auto_ferryman_godroll_rings', godrollValue)
        end)

        local selectedItems = a["Game/Items/ItemFilters"]().selection(noEffects.value('auto_ferryman_selected', noEffects.value('auto_ferryman_pool', {})), a["Game/Items/ItemFilters"]().ferrymanGroups)

        noEffects.setValue('auto_ferryman_selected', selectedItems)

        for groupIndex, group in ipairs(a["Game/Items/ItemFilters"]().ferrymanGroups)do
            local checkedItems = {}

            for itemIndex, item in ipairs(group.items)do
                if selectedItems[item] == true then
                    checkedItems[item] = true
                end
            end

            local lootDropdown = i:AddDropdown('FerrymanLootV2' .. group.name:gsub('%W', ''), {
                Text = group.name,
                Values = group.items,
                Multi = true,
                AllowNull = true,
                Tooltip = 
"Only checked items are collected. Unchecked items stay in the chest.",
            })

            lootDropdown:SetValue(checkedItems)
            lootDropdown:OnChanged(function(dropdownSelection)
                local selectedCopy = table.clone(noEffects.value('auto_ferryman_selected', {}))

                for itemLoopIndex, itemValue in ipairs(group.items)do
                    selectedCopy[itemValue] = dropdownSelection[itemValue] == true or nil
                end

                noEffects.setValue('auto_ferryman_selected', selectedCopy)
            end)
        end

        local lootInput = i:AddInput('FerrymanLootItems', {
            Text = 'Custom loot names',
            Default = table.concat(noEffects.value('auto_ferryman_items', {}), '; '),
            Finished = true,
            Tooltip = 
"Exact item names separated by semicolons. These are added to your checked items.",
        })

        lootInput:OnChanged(function(inputText)
            local customNames = {}

            for entry in inputText:gmatch('[^;]+')do
                local trimmedName = entry:match('^%s*(.-)%s*$')

                if trimmedName ~= '' then
                    customNames[#customNames + 1] = trimmedName
                end
            end

            noEffects.setValue('auto_ferryman_items', customNames)
        end)
    end
    function module.initUtility(utilityTabs)
        local utilityTab = utilityTabs:AddTab('Utility')
        local utilityOptionsTab = utilityTabs:AddTab('Options')

        utilityTab:AddButton({
            Text = 'Escape Depths',
            Func = function()
                task.spawn(function()
                    noEffects.setFlag('escape_depths_hard_trial', configuration.expectOptionValue('EscapeDepthsDifficulty') == 'Hard Trial')
                    noEffects.setFlag('escape_depths_voiding', configuration.expectOptionValue('EscapeDepthsCombat') == 'Voiding')
                    toggleFarm('auto_escape_depths', 'Escape Depths')
                end)
            end,
            Tooltip = 'Does the Depths Trial to escape the Depths.',
        })
        utilityTab:AddButton({
            Text = 'Disarm All',
            Func = function()
                kaidoFarm2.progression:stop()

                for farmFlag in next, kaidoFarm2.farms do
                    kaidoFarm2.set(farmFlag, false)
                end

                logger.notify('All automation disarmed.')
            end,
            Tooltip = 
"Clears every stored farm flag, including ones armed on a previous server.",
        })
        utilityTab:AddButton({
            Text = 'Show Armed',
            Func = function()
                local armedNames = {}

                if kaidoFarm2.progression:armed() then
                    armedNames[#armedNames + 1] = kaidoFarm2.progression.mode == 'talents' and 'auto_talents' or 'auto_progression'
                end

                for farmKey, farmObject in next, kaidoFarm2.farms do
                    if farmObject:armed() then
                        armedNames[#armedNames + 1] = farmKey
                    end
                end

                if #armedNames == 0 then
                    return logger.notify('No automation is armed.')
                end

                logger.notify('Armed: %s', table.concat(armedNames, ', '))
            end,
        })
        utilityOptionsTab:AddDropdown('EscapeDepthsCombat', {
            Text = 'Combat Mode',
            Values = {
                'Normal',
                'Voiding',
            },
            Default = 'Normal',
            Tooltip = 
"Normal fights with Pathfind Breaker + Aggressive Mode so nothing can hit you. " .. 
"Voiding rides each mob upward until it falls out of the world, like Auto Titus does to Titus.",
        })
        utilityOptionsTab:AddDropdown('EscapeDepthsDifficulty', {
            Text = 'Trial Difficulty',
            Values = {
                'Normal Trial',
            },
            Default = 'Normal Trial',
            Tooltip = 'Hard Trial is not supported yet.',
        })
    end
    function module.initProgression(progressionTabbox)
        local progressionTab = progressionTabbox:AddTab('Progression')
        local buildLink = noEffects.value('progression_build_link')

        if type(buildLink) ~= 'string' or buildLink == '' then
            buildLink = noEffects.value('progression_session', {}).build or ''
        end

        local setBuild = function(link)
            local normalized = tostring(link or ''):gsub('%s+', '')

            if normalized == '' then
                return normalized
            end

            local session = noEffects.value('progression_session', {})

            session.build = normalized

            noEffects.setValue('progression_session', session)
            noEffects.setValue('progression_build_link', normalized)

            return normalized
        end
        local input = progressionTab:AddInput(nil, {
            Text = 'deepwoken.co build link',
            Default = buildLink,
            Callback = function(value)
                setBuild(value)
            end,
        })

        progressionTab:AddButton({
            Text = 'Auto Progression',
            Func = function()
                local buildResult = setBuild(input.Value)

                if kaidoFarm2.progression:armed() then
                    logger.notify('%s [OFF]', kaidoFarm2.progression.mode == 'talents' and 'Auto Talents' or 'Auto Progression')
                    kaidoFarm2.progression:stop()

                    return
                end

                local slot = noEffects.localPlayer.instance:GetAttribute('DataSlot') or noEffects.value('auto_ferryman_slot')

                if not slot then
                    logger.notify('Select a slot before starting Auto Progression.')

                    return
                end
                if kaidoFarm2.progression:enable(buildResult, slot) then
                    logger.notify('Auto Progression [ON]')
                end
            end,
        })
        progressionTab:AddButton({
            Text = 'Auto Talents',
            Tooltip = 
"Uses Shrine of Chance for eligible missing build talents. Pauses when Knowledge is low.",
            Func = function()
                local build = setBuild(input.Value)

                if kaidoFarm2.progression:armed() then
                    logger.notify('%s [OFF]', kaidoFarm2.progression.mode == 'talents' and 'Auto Talents' or 'Auto Progression')
                    kaidoFarm2.progression:stop()

                    return
                end

                local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot') or noEffects.value('auto_ferryman_slot')

                if not dataSlot then
                    logger.notify('Select a slot before starting Auto Talents.')

                    return
                end
                if kaidoFarm2.progression:enable(build, dataSlot, 'talents') then
                    logger.notify('Auto Talents [ON]')
                end
            end,
        })
    end
    function module.initAuthority(authorityTabbox)
        local authorityTab = authorityTabbox:AddTab('Authority')

        authorityTab:AddButton({
            Text = 'Auto Authority Missions',
            Func = function()
                toggleFarm('auto_authority_missions', 'Auto Authority Missions')
            end,
            Tooltip = 
"Complete selected Authority missions from Captain Trist in Eastern Luminant.",
        })

        local dropdown = authorityTab:AddDropdown('AuthorityMissions', {
            Text = 'Missions',
            Values = {
                'Hostage',
                'Armament Sabotage',
                'Secure the Perimeter',
            },
            Default = {
                'Hostage',
                'Armament Sabotage',
                'Secure the Perimeter',
            },
            Multi = true,
            AllowNull = true,
            Tooltip = 'Unselected missions are skipped by changing servers.',
        })

        dropdown:SetValue(noEffects.value('auto_authority_selected', {
            Hostage = true,
            ['Armament Sabotage'] = true,
            ['Secure the Perimeter'] = true,
        }))
        dropdown:OnChanged(function(selection)
            noEffects.setValue('auto_authority_selected', selection)
        end)
    end
    function module.init(tabbox)
        local automationTab = tabbox:AddTab('Automation')

        module.initResources(automationTab:AddLeftTabbox())
        module.initBosses(automationTab)
        module.initUtility(automationTab:AddRightTabbox())
        module.initProgression(automationTab:AddLeftTabbox())
        module.initAuthority(automationTab:AddRightTabbox())
        quickToggles.init()
    end
    function module.detach()
        quickToggles.detach()
        kaidoFarm2.detach()
    end

    return module
end


return aa()

]=],
    ["Features/Automation/AutomationStep"] = [=[
local aa = function()
    local executionQueue = a["Features/Automation/ExecutionQueue"]()
    local noEffects = a["Features/Game/NoEffects"]()
    local logger = a["Utility/Logger"]()
    local ad = {}

    ad.__index = ad

    function ad.construct(spec)
        local step = setmetatable({}, ad)

        step.id = spec.id
        step.persistentFlag = spec.persistentFlag or spec.id
        step.stateMachine = spec.stateMachine
        step.features = spec.features or {}

        for index, featureName in ipairs({
            'Flight',
            'NoClip',
            'NoStun',
            'FastSwing',
        })do
            if not table.find(step.features, featureName) then
                table.insert(step.features, featureName)
            end
        end

        step.conflicts = spec.conflicts or {}
        step.notAllowed = spec.notAllowed
        step.onRun = spec.onRun
        step.onStop = spec.onStop
        step.restoreFeatures = spec.restoreFeatures
        step.generation = 0
        step.activeFeatures = {}
        step.threads = {}
        step.connections = {}

        return step
    end
    function ad:armed()
        return noEffects.flag(self.persistentFlag, false) == true
    end
    function ad:setArmed(armed)
        noEffects.setFlag(self.persistentFlag, armed)

        if not armed then
            self:stop()
        end
    end
    function ad:spawn(spawnCallback, ...)
        for threadIndex = #self.threads, 1, -1 do
            if coroutine.status(self.threads[threadIndex]) == 'dead' then
                table.remove(self.threads, threadIndex)
            end
        end

        local generation = self.generation
        local activeQueue = executionQueue.active
        local thread = task.defer(function(...)
            if self:armed() and self.generation == generation and (not activeQueue or activeQueue.owner ~= self or executionQueue.valid(activeQueue)) then
                spawnCallback(...)
            end
        end, ...)

        self.threads[#self.threads + 1] = thread

        return thread
    end
    function ad:defer(deferCallback, ...)
        return self:spawn(deferCallback, ...)
    end
    function ad:delay(delaySeconds, delayCallback, ...)
        local delayGeneration = self.generation

        return self:spawn(function(...)
            task.wait(delaySeconds)

            if self:armed() and self.generation == delayGeneration then
                delayCallback(...)
            end
        end, ...)
    end
    function ad:connect(signal, connectCallback)
        local connectGeneration = self.generation
        local connection = signal:Connect(function(...)
            if self.generation == connectGeneration then
                self:spawn(connectCallback, ...)
            end
        end)

        self.connections[#self.connections + 1] = connection

        return connection
    end
    function ad:stop()
        executionQueue.cancel(self, 'stopped')

        self.generation = self.generation + 1

        for connectionIndex, connection2 in ipairs(self.connections)do
            connection2:Disconnect()
        end
        for threadIndex2, thread2 in ipairs(self.threads)do
            if thread2 ~= coroutine.running() then
                pcall(task.cancel, thread2)
            end
        end

        table.clear(self.connections)
        table.clear(self.threads)

        if self.onStop then
            self.onStop()
        end
        if noEffects.automation.movement == self then
            noEffects.automation.movement = nil
        end
        if self.previousFeatures then
            for featureKey, wasActive in pairs(self.previousFeatures)do
                noEffects.setFeature(featureKey, wasActive)
            end

            self.previousFeatures = nil
        end

        self.running = false
        self.progress = nil

        if self.stateMachine then
            self.stateMachine.current = 'idle'
            self.stateMachine.asyncState = 'none'
        end
    end

    ad.run = LPH_NO_VIRTUALIZE(function(automation)
        if not executionQueue.acquire(automation) then
            automation.running = false

            return
        end

        automation.activeFeatures = {}
        noEffects.automation.movement = automation

        if not automation.previousFeatures then
            automation.previousFeatures = {}

            if automation.restoreFeatures then
                for featureListIndex, featureList in ipairs({
                    automation.features,
                    automation.conflicts,
                })do
                    for featureIndex, featureName2 in ipairs(featureList)do
                        automation.previousFeatures[featureName2] = noEffects.featureActive(featureName2)
                    end
                end
            end

            for hardcodeIndex, hardcodeName in ipairs({
                'NoStun',
                'FastSwing',
            })do
                automation.previousFeatures[hardcodeName] = noEffects.featureActive(hardcodeName)
            end
        end

        for conflictIndex, conflictName in ipairs(automation.conflicts)do
            noEffects.disableFeature(conflictName)
        end
        for featureIndex2, featureName3 in ipairs(automation.features)do
            if noEffects.enableFeature(featureName3) then
                automation.activeFeatures[featureName3] = true
            else
                logger.warn("[Automation] %s: toggle '%s' not found", tostring(automation.id), tostring(featureName3))
            end
        end

        local deadline = os.clock() + 5

        repeat
            local needsRetry = false

            for activeCheckIndex, activeCheckFeature in ipairs(automation.features)do
                if not noEffects.featureActive(activeCheckFeature) then
                    needsRetry = true

                    noEffects.enableFeature(activeCheckFeature)
                end
            end

            if not needsRetry then
                break
            end

            task.wait()
        until os.clock() > deadline

        for verifyIndex, verifyFeature in ipairs(automation.features)do
            if not noEffects.featureActive(verifyFeature) then
                logger.warn("[Automation] %s: '%s' did not come up", tostring(automation.id), tostring(verifyFeature))
            end
        end

        automation.movementThread = automation:spawn(function()
            while automation:armed() do
                noEffects.enableFeature('PlayerProximity')
                noEffects.enableFeature('NotifyMod')
                noEffects.enableFeature('Flight')
                noEffects.enableFeature('NoClip')
                noEffects.enableFeature('NoStun')
                noEffects.enableFeature('FastSwing')
                task.wait(0.2)
            end
        end)

        if automation.onRun then
            automation:spawn(automation.onRun)
        end
        if not automation.stateMachine then
            return
        end

        automation:spawn(function()
            local success, err = pcall(function()
                automation.stateMachine:start()
            end)

            if not success then
                logger.warn('[Automation] %s errored: %s', tostring(automation.id), tostring(err))
            end
        end)
    end)

    return ad
end


return aa()

]=],
    ["Features/Automation/CharacterCreation"] = [=[
local aa = function()
    local delayedTask = a["Utility/DelayedTask"]()
    local talentPicker = a["Features/Automation/TalentPicker"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local requests = replicatedStorage:WaitForChild('Requests')
    local af = {}
    local ag = {
        'Strength',
        'Fortitude',
        'Agility',
        'Intelligence',
        'Willpower',
        'Charisma',
        'WeaponHeavy',
        'WeaponMedium',
        'WeaponLight',
        'ElementFire',
        'ElementIce',
        'ElementLightning',
        'ElementWind',
        'ElementShadow',
        'ElementMetal',
        'ElementBlood',
    }
    local ah = {
        Flamecharm = 'ElementFire',
        Frostdraw = 'ElementIce',
        Thundercall = 'ElementLightning',
        Galebreathe = 'ElementWind',
        Shadowcast = 'ElementShadow',
        Ironsing = 'ElementMetal',
        Bloodrend = 'ElementBlood',
    }
    local ai = 0.6
    local sanitizeKey = function(normalizeKey)
        return tostring(normalizeKey or ''):lower():gsub('[^%w]', '')
    end
    local getCharacterCreator = function()
        local localPlayer = players.LocalPlayer
        local playerGui = localPlayer and localPlayer:FindFirstChild('PlayerGui')
        local characterCreator = playerGui and playerGui:FindFirstChild('CharacterCreator')

        return characterCreator and characterCreator.Enabled ~= false and characterCreator
    end
    local fetchReplicatedData = function(timeout)
        local deadline = os.clock() + (timeout or 2)

        repeat
            local infoHolder = replicatedStorage:FindFirstChild('Info') and replicatedStorage.Info:FindFirstChild('DataReplication')
            local ok, dataModule

            if infoHolder then
                ok, dataModule = pcall(require, infoHolder)
            end

            local data = ok and type(dataModule) == 'table' and dataModule.data

            if type(data) ~= 'table' or data.IronVow == nil then
                data = talentPicker.data()
            end
            if data then
                return data
            end

            task.wait(0.1)
        until os.clock() >= deadline
    end
    local invokeServer = function(creatorGui, isOpen, ao, ...)
        if not creatorGui or not isOpen() then
            return false, 'Character creation was closed'
        end

        local done, ok, result, detail = false, false
        local thread = task.spawn(function(...)
            ok, result, detail = pcall(delayedTask.method, creatorGui, 'InvokeServer', ...)
            done = true
        end, ...)
        local deadline = os.clock() + 5

        while not done and isOpen() and os.clock() < deadline do
            task.wait(0.05)
        end

        if not done then
            pcall(task.cancel, thread)

            return false, 'Character creation request timed out'
        end

        task.wait(ao or ai)

        if not ok then
            return false, tostring(result)
        end

        return true, result, detail
    end
    local waitForData = function(check, isOpen, timeout)
        local deadline = os.clock() + (timeout or 2)

        repeat
            local data = fetchReplicatedData(0.15)

            if data and check(data) then
                return data
            end

            task.wait(0.1)
        until os.clock() >= deadline or not isOpen()
    end
    local buildLabelMap = function(list)
        local mapping = {}

        for key, value in pairs(list or {})do
            local label = type(value) == 'table' and (value.Name or value.name) or value

            if label then
                mapping[sanitizeKey(label)] = tostring(label)
            end
        end

        return mapping
    end
    local findEntry = function(list, wanted, unlocks, kind)
        for name, entry in pairs(list or {})do
            if sanitizeKey(name) == sanitizeKey(wanted) then
                if entry.Disabled then
                    return nil, 'Disabled ' .. tostring(kind) .. ': ' .. tostring(wanted)
                end
                if entry.Unlock and not (unlocks and unlocks[entry.Unlock]) then
                    return nil, tostring(wanted) .. ' requires the ' .. tostring(entry.Unlock) .. ' account unlock'
                end

                return tostring(name), entry
            end
        end

        return nil, 'Unknown ' .. tostring(kind) .. ': ' .. tostring(wanted)
    end
    local sumCosts = function(names, data)
        local total = 0

        for index, name in ipairs(names)do
            local entry

            for key, value in pairs(data or {})do
                if sanitizeKey(key) == sanitizeKey(name) then
                    entry = value

                    break
                end
            end

            total = total + (tonumber(entry and entry.Points) or 0)
        end

        return total
    end
    local resolveCharacterBuild = function(selection, unlocks)
        local flawData = replicatedStorage:WaitForChild('Info'):WaitForChild('FlawData')
        local buildData = require(flawData)

        if type(buildData) ~= 'table' or type(buildData.Boons) ~= 'table' or type(buildData.Flaws) ~= 'table' then
            return nil, 'Character creation boon data could not be loaded'
        end

        local boons = table.clone(selection.boons or {})
        local flaws = table.clone(selection.flaws or {})

        if #boons == 0 and #flaws == 0 then
            boons, flaws = {
                'Autodidact',
                'Maverick',
            }, {
                'Manic',
                'Obvious',
            }
        elseif #boons == 0 then
            local flawCost = sumCosts(flaws, buildData.Flaws or {})
            local candidates = {
                'Autodidact',
                'Maverick',
            }

            for index, candidate in ipairs(candidates)do
                if sumCosts(boons, buildData.Boons or {}) >= flawCost then
                    break
                end

                boons[#boons + 1] = candidate
            end
        elseif #flaws == 0 then
            local boonCost = sumCosts(boons, buildData.Boons or {})
            local candidates = {
                'Manic',
                'Obvious',
            }

            for index, candidate in ipairs(candidates)do
                if sumCosts(flaws, buildData.Flaws or {}) >= boonCost then
                    break
                end

                flaws[#flaws + 1] = candidate
            end
        end

        local chosenBoons, chosenFlaws = {}, {}
        local seen = {}

        for index, name in ipairs(boons)do
            if not seen[sanitizeKey(name)] then
                seen[sanitizeKey(name)] = true

                local entry, reason = findEntry(buildData.Boons, name, unlocks, 'boon')

                if not entry then
                    return nil, reason
                end

                chosenBoons[#chosenBoons + 1] = entry
            end
        end

        table.clear(seen)

        for index, name in ipairs(flaws)do
            if not seen[sanitizeKey(name)] then
                seen[sanitizeKey(name)] = true

                local entry, reason = findEntry(buildData.Flaws, name, unlocks, 'flaw')

                if not entry then
                    return nil, reason
                end

                chosenFlaws[#chosenFlaws + 1] = entry
            end
        end

        if sumCosts(chosenBoons, buildData.Boons or {}) ~= sumCosts(chosenFlaws, buildData.Flaws or {}) then
            return nil, 
"Builder boons and flaws do not spend the same number of points"
        end

        return {
            boons = chosenBoons,
            flaws = chosenFlaws,
        }
    end
    local applyConfiguredSelections = function(config, category, items, gui, monitor)
        local configured = buildLabelMap(config[category])
        local selected = {}
        local picker = gui:FindFirstChild(category == 'Boons' and 'PickBoon' or 'PickFlaw')

        for index, item in ipairs(items)do
            selected[sanitizeKey(item)] = item
        end
        for key, entry in pairs(configured)do
            if not selected[key] then
                local ok, err = invokeServer(picker, monitor, nil, entry)

                if not ok then
                    return false, err
                end

                local updated = waitForData(function(state)
                    return not buildLabelMap(state[category])[key]
                end, monitor)

                if not updated then
                    return false, 'Could not remove ' .. entry
                end

                config = updated
            end
        end
        for index, item in ipairs(items)do
            if not buildLabelMap(config[category])[sanitizeKey(item)] then
                local ok, err = invokeServer(picker, monitor, nil, item)

                if not ok then
                    return false, err
                end

                local updated = waitForData(function(state)
                    return buildLabelMap(state[category])[sanitizeKey(item)] ~= nil
                end, monitor)

                if not updated then
                    return false, 'Could not select ' .. item
                end

                config = updated
            end
        end

        return config
    end
    local selectOrigin = function(config, character, gui, monitor)
        local module = replicatedStorage:WaitForChild('Info'):WaitForChild('OriginData')
        local data = require(module)

        if type(data) ~= 'table' or type(data.origins) ~= 'table' then
            return false, 'Character creation origin data could not be loaded'
        end

        local origins = data.origins
        local originName = config.origin or 'Lone Warrior'
        local chosenOrigin

        for key, origin in pairs(origins)do
            if sanitizeKey(key) == sanitizeKey(originName) then
                chosenOrigin, originName = origin, key

                break
            end
        end

        if not chosenOrigin then
            return false, 'Unknown build origin: ' .. tostring(originName)
        end
        if chosenOrigin.unlock and not (character.AccountUnlocks or {})[chosenOrigin.unlock] then
            return false, 'Build requires the ' .. originName .. ' origin, but ' .. chosenOrigin.unlock .. ' is not unlocked'
        end

        local aC = chosenOrigin.spawns and chosenOrigin.spawns[1]

        if not aC then
            return false, 'No spawn is available for ' .. originName
        end

        local spawnLocation = character.SpawnLocation
        local luminant = type(spawnLocation) == 'table' and (spawnLocation.EtreanLuminant or spawnLocation.EasternLuminant)

        if sanitizeKey(character.Origin) == sanitizeKey(originName) and sanitizeKey(luminant) == sanitizeKey(aC) then
            return character
        end

        local ok, err = invokeServer(gui:FindFirstChild('PickSpawn'), monitor, nil, aC)

        if not ok then
            return false, err
        end

        local updated = waitForData(function(state)
            return sanitizeKey(state.Origin) == sanitizeKey(originName)
        end, monitor)

        return updated or false, updated and nil or 'Could not select ' .. originName
    end
    local applyAllModifiers = function(config, character, isOpen)
        if not config.echoModifiersAll then
            return character
        end

        local allSelected = function(ax)
            local activeModifiers = ax.ActiveModifiers

            if type(activeModifiers) ~= 'table' then
                return false
            end
            if activeModifiers.All or activeModifiers.all then
                return true
            end

            local uiRoot = getCharacterCreator()
            local windowsFrame = uiRoot and uiRoot:FindFirstChild('Windows')
            local modifiersFrame = windowsFrame and windowsFrame:FindFirstChild('Modifiers')
            local listSection = modifiersFrame and modifiersFrame:FindFirstChild('ListSection')

            if not listSection then
                return false
            end

            local buttonCount, activeCount = 0, 0

            for index, descendant in ipairs(listSection:GetDescendants())do
                if descendant:IsA('TextButton') and descendant.Name == 'Button' and descendant.Text:find('\u{2605}', 1, true) then
                    buttonCount = buttonCount + 1
                end
            end
            for modifier, enabled in pairs(activeModifiers)do
                if type(modifier) == 'string' and enabled == true then
                    activeCount = activeCount + 1
                end
            end

            return buttonCount > 0 and activeCount >= buttonCount
        end

        if allSelected(character) then
            return character
        end

        local remote = requests:FindFirstChild('ToggleMetaModifier')

        if not remote then
            return false, 'Echo modifier request is unavailable'
        end
        if not character.UnlockedEchoes then
            return false, 'Echo modifiers are not unlocked'
        end
        if not isOpen() then
            return false, 'Character creation was closed'
        end

        delayedTask.method(remote, 'FireServer', 'All')

        local confirmed = waitForData(allSelected, isOpen, 4)

        return confirmed or false, confirmed and nil or 'Echo modifiers were not confirmed'
    end
    local changeWeapon = function(character, weapon, gui, callback)
        if sanitizeKey(character.PrimaryWeapon) == sanitizeKey(weapon) then
            return character
        end

        local okFlag, failReason = invokeServer(gui:FindFirstChild('ChangeWeapon'), callback, nil, weapon)

        if not okFlag then
            return false, failReason
        end

        local selectedChar = waitForData(function(candidate)
            return sanitizeKey(candidate.PrimaryWeapon) == sanitizeKey(weapon)
        end, callback)

        return selectedChar or false, selectedChar and nil or 'Could not select ' .. weapon
    end
    local changeAttunements = function(currentChar, attunements, creationGui, predicate)
        if #attunements == 0 then
            return currentChar
        end

        for index, attunement in ipairs(attunements)do
            local attuneButton = ah[attunement]

            if attuneButton and sanitizeKey(currentChar.Attunement) ~= sanitizeKey(attunement) and sanitizeKey(currentChar.AttunementAlt) ~= sanitizeKey(attunement) then
                local worked, errorMsg = invokeServer(creationGui:FindFirstChild('ChangeAttunement'), predicate, nil, attuneButton)

                if not worked then
                    return false, errorMsg
                end

                local chosenChar = waitForData(function(candidateChar)
                    return sanitizeKey(candidateChar.Attunement) == sanitizeKey(attunement) or sanitizeKey(candidateChar.AttunementAlt) == sanitizeKey(attunement)
                end, predicate)

                if not chosenChar then
                    return false, 'Could not select ' .. attunement
                end

                currentChar = chosenChar
            end
        end

        return currentChar
    end
    local decreaseAttributes = function(data, attributeGui, checkActive)
        local decreaseButton = attributeGui:FindFirstChild('DecreaseAttribute')

        if not decreaseButton then
            return false, 'Character creation attribute request is unavailable'
        end

        local elementMap = {}
        local characterGui = getCharacterCreator()

        for i, descendant in ipairs(characterGui and characterGui:GetDescendants() or {})do
            if descendant:FindFirstChild('Take') and descendant:FindFirstChild('Value') then
                elementMap[descendant.Name] = descendant
            end
        end
        for j, stat in ipairs(ag)do
            local statElement = elementMap[stat]
            local readStat = function()
                if statElement and statElement.Parent then
                    return tonumber(statElement.Value.Text)
                end

                local getStat = fetchReplicatedData(0.15)

                return getStat and tonumber(getStat['Stat' .. stat])
            end
            local remaining = readStat() or tonumber(data['Stat' .. stat]) or 0

            while remaining > 0 do
                local currentStat

                for attempt = 1, 2 do
                    local successFlag, failure = invokeServer(decreaseButton, checkActive, nil, stat)

                    if not successFlag then
                        return false, failure
                    end

                    local deadline = os.clock() + 3

                    repeat
                        currentStat = readStat()

                        if currentStat and currentStat < remaining then
                            break
                        end

                        task.wait(0.1)
                    until not checkActive() or os.clock() >= deadline

                    if not checkActive() then
                        return false, 'Automation stopped'
                    end
                    if currentStat and currentStat < remaining then
                        break
                    end
                end

                if not currentStat or currentStat >= remaining then
                    return false, 'Could not clear ' .. stat
                end

                remaining = currentStat
            end
        end

        return data
    end

    function af.active()
        return getCharacterCreator() ~= nil
    end

    local finalizeCreation = function(active)
        local playerGui = players.LocalPlayer:FindFirstChild('PlayerGui')
        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')
        local requested, succeeded, completionError = false, false
        local spawnTask

        if not choicePrompt then
            spawnTask = task.spawn(function()
                local callOk, callResult = pcall(delayedTask.method, requests.CharacterCreator.FinishCreation, 'InvokeServer')

                requested, succeeded = true, callOk and callResult == true

                if not callOk then
                    completionError = tostring(callResult)
                end
            end)
        end

        local timeout = os.clock() + 20
        local handledPrompt = {}

        while getCharacterCreator() and active() and os.clock() < timeout do
            local prompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')
            local choiceFrame = prompt and prompt:FindFirstChild('ChoiceFrame')
            local title = choiceFrame and choiceFrame:FindFirstChild('Title')
            local descSheet = choiceFrame and choiceFrame:FindFirstChild('DescSheet')
            local yesButton = descSheet and descSheet:FindFirstChild('Yes')
            local choice = prompt and prompt:FindFirstChild('Choice')

            if title and title.Text == 'Unspent Attribute Points' and yesButton and yesButton.AutoButtonColor and choice and not handledPrompt[prompt] then
                task.wait(ai)

                if not active() then
                    break
                end
                if prompt.Parent and yesButton.AutoButtonColor then
                    handledPrompt[prompt] = true

                    delayedTask.method(choice, 'FireServer', true)
                end
            end
            if requested and not succeeded then
                break
            end

            task.wait(0.1)
        end

        if spawnTask and not requested then
            pcall(task.cancel, spawnTask)
        end
        if not getCharacterCreator() then
            return true
        end

        return false, completionError or 
"Character creation could not finalize; waiting for confirmation or server response"
    end
    local selectGameMode = function(state, shouldContinue)
        local screen = getCharacterCreator()
        local gameMode = screen and screen:FindFirstChild('GameMode')

        if not gameMode then
            return false, 'Character creation gamemode screen is unavailable'
        end
        if not gameMode.Visible and state.IronVow == false then
            return state
        end

        local clickButton = function(button)
            if not button then
                return false
            end
            if getconnections then
                for index, connection in ipairs(getconnections(button.MouseButton1Click))do
                    if connection.Enabled then
                        local success = pcall(delayedTask.call, function()
                            connection:Fire()
                        end)

                        if success then
                            return true
                        end
                    end
                end
            end

            return false
        end

        if not gameMode.Visible and not clickButton(screen:FindFirstChild('CurrentMode')) then
            return false, 'Could not open the Pathfinder selection screen'
        end

        local deadline = os.clock() + 3

        repeat
            task.wait(0.1)
        until gameMode.Visible or os.clock() >= deadline or not shouldContinue()

        if not gameMode.Visible then
            return false, 'Pathfinder selection screen did not open'
        end

        local options = gameMode:FindFirstChild('Options')
        local standard = options and options:FindFirstChild('Standard')
        local element = standard and standard:FindFirstChild('Element')

        if not clickButton(element) then
            return false, 'Could not select Pathfinder'
        end

        local result = waitForData(function(character)
            return character.IronVow == false and not gameMode.Visible
        end, shouldContinue, 5)

        return result or false, result and nil or 'Pathfinder selection was not confirmed'
    end

    function af.run(build, additionalCheck)
        if not getCharacterCreator() then
            return true
        end

        local isOpen = function()
            return getCharacterCreator() ~= nil and (not additionalCheck or additionalCheck())
        end
        local data = fetchReplicatedData()

        if not data then
            return false, 'Waiting for character creation data'
        end
        if not isOpen() then
            return false, 'Character creation was closed'
        end

        local creation = build and build.creation

        if not creation then
            return false, 'Selected build has no character creation data'
        end

        local metaProgress = data.MetaProg or {}
        local accountUnlocks = data.AccountUnlocks or {}

        if creation.elementalist and not metaProgress.Elementalist then
            return false, 
"Build needs Elementalist. Enable Auto Echo Farm and buy Elementalist first."
        end
        if creation.multifaceted and not (metaProgress.NoRaceBonus or metaProgress.Multifaceted or accountUnlocks.Multifaceted or accountUnlocks.UnlockedMultifaceted) then
            return false, 
"Build needs Multifaceted. Enable Auto Echo Farm and buy Multifaceted first."
        end

        local selections, aI = resolveCharacterBuild(creation, accountUnlocks)

        if not selections then
            return false, aI
        end

        data, aI = selectGameMode(data, isOpen)

        if not data then
            return false, aI
        end

        data, aI = selectOrigin(creation, data, requests.CharacterCreator, isOpen)

        if not data then
            return false, aI
        end

        data, aI = applyAllModifiers(creation, data, isOpen)

        if not data then
            return false, aI
        end

        data, aI = changeWeapon(data, creation.weapon, requests.CharacterCreator, isOpen)

        if not data then
            return false, aI
        end

        data, aI = changeAttunements(data, creation.elements, requests.CharacterCreator, isOpen)

        if not data then
            return false, aI
        end

        data, aI = decreaseAttributes(data, requests.CharacterCreator, isOpen)

        if not data then
            return false, aI
        end

        data, aI = applyConfiguredSelections(data, 'Flaws', selections.flaws, requests.CharacterCreator, isOpen)

        if not data then
            return false, aI
        end

        data, aI = applyConfiguredSelections(data, 'Boons', selections.boons, requests.CharacterCreator, isOpen)

        if not data then
            return false, aI
        end

        return finalizeCreation(isOpen)
    end

    return af
end


return aa()

]=],
    ["Features/Automation/CharismaFarm"] = [=[
local aa = function()
    local delayedTask = a["Utility/DelayedTask"]()
    local ab = {}
    local attributes = a["Utility/Attributes"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local signal = a["Utility/Signal"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local renderStepped = signal.new(runService.RenderStepped)
    local activeMaid = maid.new()
    local al = 0
    local am, an, ao = 0
    local onChoicePromptAdded = function()
        local player = players.LocalPlayer
        local playerGui = player and player:FindFirstChild('PlayerGui')
        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')

        if not choicePrompt then
            return
        end

        local choiceFrame = choicePrompt:FindFirstChild('ChoiceFrame')
        local desc = choiceFrame and choiceFrame:FindFirstChild('Desc')
        local chatChoice = choicePrompt:FindFirstChild('ChatChoice')
        local descLines = desc and desc.Text:split('\n') or {}
        local replyText = descLines[2] and descLines[2]:sub(2, -2)

        if chatChoice and replyText and replyText ~= '' then
            pcall(function()
                delayedTask.methodWithDelay(chatChoice, 'InvokeServer', 0.1, replyText)
            end)
        end

        task.delay(0.5, function()
            if choicePrompt.Parent and not (player.Character and player.Character:FindFirstChild('How to Make Friends')) then
                choicePrompt:Destroy()
            end
        end)
    end
    local updateCharismaFarm = function()
        local toggle = Toggles['AutoCharisma']

        if not toggle or not toggle.Value then
            return
        end
        if os.clock() - al < 0.1 then
            return
        end

        al = os.clock()

        local capOption = Options['CharismaCap']

        if not capOption then
            return
        end

        local localPlayer = players.LocalPlayer
        local character = localPlayer.Character

        if not character then
            return
        end
        if not attributes.isNotAtCap(character, 'Stat_Charisma', capOption.Value) then
            logger.warnNotify('Charisma farm auto-stopped.')

            return toggle:SetValue(false)
        end

        local humanoid = character:FindFirstChild('Humanoid')

        if not humanoid then
            return
        end

        local backpack = localPlayer:FindFirstChild('Backpack')

        if not backpack then
            return
        end

        local equippedTool = character:FindFirstChild('How to Make Friends')
        local backpackTool = backpack:FindFirstChild('How to Make Friends')

        if not equippedTool and backpackTool then
            return delayedTask.methodWithDelay(humanoid, 'EquipTool', 0.1, backpackTool)
        end

        local promptGui = localPlayer.PlayerGui:FindFirstChild('ChoicePrompt')

        if not promptGui then
            return equippedTool and delayedTask.methodWithDelay(equippedTool, 'Activate', 0.1)
        end

        local frame = promptGui:FindFirstChild('ChoiceFrame')

        if not frame then
            return
        end

        local choiceRemote = promptGui:FindFirstChild('ChatChoice')

        if not choiceRemote then
            return
        end

        local descLabel = frame:FindFirstChild('Desc')

        if not descLabel then
            return
        end

        local promptLines = descLabel.Text:split('\n')
        local selectedText = promptLines[2] and promptLines[2]:sub(2, -2)

        if not selectedText or selectedText == '' or promptGui == an and selectedText == ao and os.clock() - am < 1 then
            return
        end

        an, ao, am = promptGui, selectedText, os.clock()

        delayedTask.methodWithDelay(choiceRemote, 'InvokeServer', 0.1, selectedText)
    end

    function ab.init()
        activeMaid:add(renderStepped:connect('AttributeFarmCharisma_OnPreRender', updateCharismaFarm))
    end
    function ab.detach()
        activeMaid:clean()
        onChoicePromptAdded()

        local currentPlayer = players.LocalPlayer
        local char = currentPlayer and currentPlayer.Character
        local charHumanoid = char and char:FindFirstChildOfClass('Humanoid')
        local tool = char and char:FindFirstChild('How to Make Friends')

        if tool then
            pcall(function()
                tool:Deactivate()
            end)

            if charHumanoid then
                charHumanoid:UnequipTools()
            end
        end

        an, ao, am = nil, nil, 0
    end

    do
        local feature = a["Features/Feature"]()
        local featureModule = feature.new('AutoCharisma')

        function featureModule:onEnable()
            ab.init()
        end
        function featureModule:onDisable()
            ab.detach()
        end
    end

    return ab
end


return aa()

]=],
    ["Features/Automation/DrillFarm"] = [=[
local aa = function()
    local delayedTask = a["Utility/DelayedTask"]()
    local executorFire = a["Utility/ExecutorInfo"]().fire
    local noEffects = a["Features/Game/NoEffects"]()
    local automationStep = a["Features/Automation/AutomationStep"]()
    local placeIds = a["Game/PlaceIds"]()
    local travelRecovery = a["Features/Game/TravelRecovery"]()
    local regionTransfer = a["Features/Automation/RegionTransfer"]()
    local itemFilters = a["Game/Items/ItemFilters"]()
    local clickHolder = a["Features/Combat/ClickHolder"]()
    local aj
    local farmPosition = CFrame.new(-2856.81104, 135.674957, 3375.38403, 0.541101158, 0, 
-0.840957522, 0, 1, 0, 0.840957522, 0, 0.541101158)
    local isPlayerAlive = function()
        return aj:armed() and noEffects.localPlayer.humanoid and noEffects.localPlayer.humanoid.Health > 0
    end
    local getPlayerRoot = function()
        return noEffects.localPlayer.root_part
    end
    local travelToLocation = function(travelTo, offset)
        local trip = travelRecovery.new(travelTo, true, offset or 170)

        while isPlayerAlive() and not trip.status() do
            task.wait(0.1)
        end

        local tripStatus = trip.status()

        if not tripStatus then
            trip.stop()
        end

        return tripStatus == 'arrived'
    end
    local findSummerRifle = function()
        for container, stack in ipairs({
            noEffects.localPlayer.instance:FindFirstChild('Backpack'),
            noEffects.localPlayer.character,
        })do
            for index, item in ipairs(stack and stack:GetChildren() or {})do
                if item:IsA('Tool') and (item:GetAttribute('ItemName') == 'Summer Rifle' or item.Name:match('^Summer Rifle')) then
                    return item
                end
            end
        end
    end
    local findNearestMob = function()
        local live = workspace:FindFirstChild('Live')
        local playerRoot = getPlayerRoot()
        local nearest, nearestDist

        for index, player in ipairs(live and live:GetChildren() or {})do
            local humanoid = player:FindFirstChildOfClass('Humanoid')
            local root = player:FindFirstChild('HumanoidRootPart') or player.PrimaryPart

            if player ~= noEffects.localPlayer.character and player.Name:sub(1, 1) == '.' and humanoid and humanoid.Health > 0 and root then
                local distance = playerRoot and (playerRoot.Position - root.Position).Magnitude or math.huge

                if not nearestDist or distance < nearestDist then
                    nearest, nearestDist = player, distance
                end
            end
        end

        return nearest
    end
    local clearSaramaedMobs = function()
        local target = findNearestMob()

        while isPlayerAlive() and target do
            aj.progress = 'Clearing Saramaed mobs'

            local handler = noEffects.localPlayer.character and noEffects.localPlayer.character:FindFirstChild('CharacterHandler')
            local drawWeapon = handler and handler:FindFirstChild('Requests') and handler.Requests:FindFirstChild('DrawWeapon')

            if drawWeapon then
                delayedTask.method(drawWeapon, 'FireServer', true)
            end

            local humanoid = target:FindFirstChildOfClass('Humanoid')
            local root = target:FindFirstChild('HumanoidRootPart') or target.PrimaryPart

            clickHolder.set(true)

            while isPlayerAlive() and target.Parent and humanoid and humanoid.Health > 0 and root do
                local isBuncle = target.Name:lower():find('buncle', 1, true) or target.Name:lower():find('knight', 1, true)
                local attackPos = root.CFrame * CFrame.new(0, isBuncle and -8 or 8, 0) * CFrame.Angles(math.rad(isBuncle and 90 or 
-90), 0, 0)
                local humanoidRoot = getPlayerRoot()

                if humanoidRoot then
                    humanoidRoot.AssemblyLinearVelocity = Vector3.zero

                    if (humanoidRoot.Position - attackPos.Position).Magnitude > 30 then
                        travelToLocation(attackPos, 100)
                    else
                        humanoidRoot.CFrame = attackPos
                    end
                end

                task.wait()
            end

            clickHolder.set(false)

            target = findNearestMob()
        end

        clickHolder.set(false)

        return isPlayerAlive()
    end
    local findNearestOre = function()
        local oreRoot = getPlayerRoot()
        local nearest, nearestDist

        for index, ore in ipairs(workspace:GetDescendants())do
            local prompt = ore:IsA('MeshPart') and ore.Name:find('MagmaOre', 1, true) and ore:FindFirstChild('InteractPrompt')

            if prompt then
                local distance = oreRoot and (oreRoot.Position - ore.Position).Magnitude or math.huge

                if not nearestDist or distance < nearestDist then
                    nearest, nearestDist = ore, distance
                end
            end
        end

        return nearest
    end
    local mineTaggedOre = function()
        for attempt = 1, 6 do
            if not isPlayerAlive() then
                return false
            end

            local ore = findNearestOre()

            if not ore then
                return false
            end

            aj.progress = 'Mining Saramaed ore'

            travelToLocation(ore.CFrame, 170)

            local deadline = os.clock() + 8

            repeat
                local prompt = ore:FindFirstChild('InteractPrompt')

                if prompt then
                    pcall(delayedTask.call, executorFire, prompt)
                end

                task.wait(0.1)
            until not ore:FindFirstChild('InteractPrompt') or os.clock() >= deadline or not isPlayerAlive()
        end

        local drill = workspace:FindFirstChild('Deepdrill')
        local fuelPort = drill and drill:FindFirstChild('DungeonDrill') and drill.DungeonDrill:FindFirstChild('FuelPort')
        local hit = fuelPort and fuelPort:FindFirstChild('Hit')

        if not hit then
            return false
        end

        aj.progress = 'Fueling Saramaed drill'

        return travelToLocation(hit.CFrame, 170)
    end
    local lootChest = function()
        aj.progress = 'Looting Saramaed chest'

        local thrownContainer = workspace:FindFirstChild('Thrown')
        local chest

        for index, child in ipairs(thrownContainer and thrownContainer:GetChildren() or {})do
            if child:FindFirstChild('Lid') and child:FindFirstChildWhichIsA('ProximityPrompt', true) then
                chest = child

                break
            end
        end

        if not chest then
            return false
        end
        if not travelToLocation(chest.Lid.CFrame, 170) then
            return false
        end

        pcall(delayedTask.call, executorFire, chest:FindFirstChildWhichIsA('ProximityPrompt', true))

        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local timeout = os.clock() + 8

        repeat
            task.wait(0.1)
        until playerGui and playerGui:FindFirstChild('ChoicePrompt') or os.clock() >= timeout or not isPlayerAlive()

        if not playerGui or not playerGui:FindFirstChild('ChoicePrompt') then
            return false
        end

        itemFilters.fromPrompt({
            'Summer Rifle',
        }, isPlayerAlive, false, {
            exact = true,
            strict = false,
            rarities = {},
            timeout = 20,
        })

        return findSummerRifle() ~= nil
    end
    local activateDrill = function()
        local deepdrill = workspace:FindFirstChild('Deepdrill')
        local dungeonDrill = deepdrill and deepdrill:FindFirstChild('DungeonDrill')
        local drillevator = deepdrill and deepdrill:FindFirstChild('Drillevator')
        local candidates = {dungeonDrill, drillevator}
        local ay, bestDistance

        for itemIndex, candidate in ipairs(candidates)do
            local switchObject = candidate and candidate:FindFirstChild('Switch')
            local caseObject = switchObject and switchObject:FindFirstChild('Case')
            local interactPrompt = switchObject and switchObject:FindFirstChild('InteractPrompt')

            if caseObject and interactPrompt then
                local distance = (getPlayerRoot().Position - caseObject.Position).Magnitude

                if not bestDistance or distance < bestDistance then
                    ay, bestDistance = switchObject, distance
                end
            end
        end

        if not ay then
            return false
        end

        aj.progress = 'Starting Saramaed drill'

        travelToLocation(ay.Case.CFrame, 170)
        pcall(delayedTask.call, executorFire, ay.InteractPrompt)
        task.wait(2)

        return true
    end
    local resetDrill = function()
        local deepdrillPart = workspace:FindFirstChild('Deepdrill')
        local drillUnit = deepdrillPart and deepdrillPart:FindFirstChild('DungeonDrill')
        local switchPart = drillUnit and drillUnit:FindFirstChild('Switch')
        local radio = drillUnit and drillUnit:FindFirstChild('Radio')

        if not switchPart or not radio or not radio:FindFirstChild('InteractPrompt') then
            return false
        end

        aj.progress = 'Resetting Saramaed drill'

        travelToLocation(switchPart.Case.CFrame, 170)
        pcall(delayedTask.call, executorFire, radio.InteractPrompt)

        local gui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local waitDeadline = os.clock() + 8

        repeat
            task.wait(0.1)
        until gui and gui:FindFirstChild('ChoicePrompt') or os.clock() >= waitDeadline or not isPlayerAlive()

        local choicePrompt = gui and gui:FindFirstChild('ChoicePrompt')
        local choice = choicePrompt and choicePrompt:FindFirstChild('Choice')

        if choice then
            pcall(delayedTask.method, choice, 'FireServer', true)
        end

        return choice ~= nil
    end
    local enterSaramaed = function()
        if not placeIds.isEastern() and not regionTransfer.toEastern(nil, isPlayerAlive) then
            return false
        end

        aj.progress = 'Entering Saramaed'

        local character = getPlayerRoot()
        local offset = Vector3.new(0, math.random(8000, 10000), 0)

        character.CFrame = character.CFrame + offset

        if not travelToLocation(farmPosition + offset, 170) then
            return false
        end

        character.CFrame = farmPosition

        local malisae = workspace:FindFirstChild('NPCs') and workspace.NPCs:FindFirstChild('Malisae')
        local npcDeadline = os.clock() + 15

        repeat
            malisae = workspace:FindFirstChild('NPCs') and workspace.NPCs:FindFirstChild('Malisae')

            task.wait(0.1)
        until malisae or os.clock() >= npcDeadline or not isPlayerAlive()

        local prompt = malisae and malisae:FindFirstChild('InteractPrompt', true)

        if not prompt then
            return false
        end

        delayedTask.method(noEffects.services.ReplicatedStorage.Requests.InteractPrompt, 'FireServer', prompt)
        task.wait(1)
        delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {
            choice = 'Enter alone.',
        })

        return true
    end
    local handleFarmSetup = function()
        if placeIds.isEastern() or placeIds.isEtrean() then
            if not enterSaramaed() then
                aj.progress = 'Could not enter Saramaed'
            end

            return
        end
        if not placeIds.isDungeon() or not workspace:FindFirstChild('Deepdrill') then
            aj.progress = 'Waiting for Saramaed'

            return
        end

        while isPlayerAlive() and not findSummerRifle() do
            if not activateDrill() or not clearSaramaedMobs() or not mineTaggedOre() then
                task.wait(1)

                continue
            end
            if lootChest() then
                break
            end
            if not resetDrill() then
                noEffects.hop(noEffects.localPlayer.instance:GetAttribute('DataSlot'), true)

                return
            end

            task.wait(2)
        end

        if findSummerRifle() then
            aj.progress = 'Summer Rifle acquired'

            aj:setArmed(false)

            local ax = getPlayerRoot()

            if ax then
                ax.CFrame = ax.CFrame * CFrame.new(0, 10000, 0)
            end

            noEffects.hop(noEffects.localPlayer.instance:GetAttribute('DataSlot'), true)
        end
    end

    aj = automationStep.construct({
        id = 'auto_saramaed',
        features = {
            'Flight',
            'NoClip',
            'NoFallDamage',
            'NoStun',
            'FastSwing',
        },
        onRun = handleFarmSetup,
        onStop = function()
            clickHolder.set(false)
            travelRecovery.stopAll()
        end,
        restoreFeatures = true,
    })

    return aj
end


return aa()

]=],
    ["Features/Automation/EchoFarm"] = [=[
local aa = function()
    local delayedTask = a["Utility/DelayedTask"]()
    local fire = a["Utility/ExecutorInfo"]().fire
    local noEffects = a["Features/Game/NoEffects"]()
    local logger = a["Utility/Logger"]()
    local travelRecovery = a["Features/Game/TravelRecovery"]()
    local stateMachine = a["Utility/StateMachine"]()
    local placeIds = a["Game/PlaceIds"]()
    local automationStep = a["Features/Automation/AutomationStep"]()
    local regionTransfer = a["Features/Automation/RegionTransfer"]()
    local characterCreation = a["Features/Automation/CharacterCreation"]()
    local persistentData = a["Utility/PersistentData"]()
    local drinkingWaterWaypoints = a["Game/Waypoints/DrinkingWater"]()
    local promptRange = a["Features/Game/PromptRange"]()
    local virtualInput = Instance.new('VirtualInputManager')
    local module = {}

    module.lastBankAt = 0
    module.l = false

    local ap
    local isEchoModeActive = function()
        return noEffects.flag('auto_titus_echo_mode', false) and not noEffects.flag('auto_progression', false)
    end

    function module.ensureEchoModifiers()
        if not isEchoModeActive() then
            return
        end
        if module.echoModifiersPrevious == nil then
            module.echoModifiersPrevious = noEffects.featureActive('NoEchoModifiers')
        end

        noEffects.enableFeature('NoEchoModifiers')

        local promptRangeMultiplier = Options and Options.PromptRangeMultiplier
        local as = Toggles and Toggles.PromptRange

        if promptRangeMultiplier and as then
            if module.pr == nil then
                module.pr = {
                    as.Value,
                    promptRangeMultiplier.Value,
                }
            end
            if promptRangeMultiplier.Value ~= 5 then
                promptRangeMultiplier:SetValue(5)
            end

            noEffects.enableFeature('PromptRange')
        end
    end

    local getRootPart = function()
        return noEffects.localPlayer.root_part
    end

    function module.dryCFrame(cframe)
        if isEchoModeActive() and not module.echoWiping and (placeIds.isOverworld() or placeIds.isDungeon()) and cframe.Y < 12 then
            return cframe + Vector3.new(0, 12 - cframe.Y, 0)
        end

        return cframe
    end
    function module.playerNearby(distance, position)
        local rootPart = getRootPart()
        local origin = position or (rootPart and rootPart.Position)

        if not origin then
            return false
        end

        for index, player in ipairs(noEffects.services.Players:GetPlayers())do
            if player == noEffects.localPlayer.instance then
                continue
            end

            local character = player.Character
            local otherRoot = character and character:FindFirstChild('HumanoidRootPart')

            if not otherRoot then
                continue
            end
            if (origin - otherRoot.Position).Magnitude <= distance then
                return true
            end
        end

        return false
    end
    function module.serverHop()
        ap.progress = 'Switching servers'

        local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

        noEffects.hop(dataSlot, true)
    end
    function module.tween(tweenCFrame, at)
        travelRecovery.new(module.dryCFrame(tweenCFrame), true, at or 150).wait(math.huge)
    end
    function module.safeTween(targetCFrame, duration, au)
        targetCFrame = module.dryCFrame(targetCFrame)

        if module.playerNearby(200) then
            module.serverHop()

            while task.wait() do end
        end

        local root = getRootPart()

        if not root then
            return
        end

        local verticalOffset = au and 0 or math.random(8000, 10000)

        root.CFrame = root.CFrame + Vector3.new(0, verticalOffset, 0)

        module.tween(targetCFrame + Vector3.new(0, verticalOffset, 0), duration)

        if module.playerNearby(200, targetCFrame.Position) then
            module.serverHop()

            while task.wait() do end
        end

        root.AssemblyLinearVelocity = Vector3.zero
        root.CFrame = targetCFrame
    end
    function module.countItem(itemName)
        local backpack = noEffects.localPlayer.instance:FindFirstChild('Backpack')

        if not backpack then
            return 0
        end

        local count = 0

        for slotIndex, item in ipairs(backpack:GetChildren())do
            if item.Name == itemName then
                count = count + 1
            end
        end

        return count
    end
    function module.needFood()
        local foodCharacter = noEffects.localPlayer.character
        local water = foodCharacter and foodCharacter:FindFirstChild('Water')
        local stomach = foodCharacter and foodCharacter:FindFirstChild('Stomach')

        if not water or not stomach then
            return false
        end

        return water.Value <= water.MaxValue * 0.3 and stomach.Value <= stomach.MaxValue * 0.3
    end
    function module.refillFood()
        ap.progress = 'Refilling supplies'

        local refillCharacter = noEffects.localPlayer.character
        local waterAttribute = refillCharacter and refillCharacter:FindFirstChild('Water')

        if not waterAttribute or waterAttribute.Value >= waterAttribute.MaxValue * 0.75 then
            return
        end

        module.safeTween(drinkingWaterWaypoints.cf, 250)

        local waterWaypoint
        local deadline = tick() + 30

        repeat
            waterWaypoint = drinkingWaterWaypoints.find()

            if waterWaypoint and waterWaypoint:FindFirstChild('InteractPrompt') then
                pcall(delayedTask.call, fire, waterWaypoint.InteractPrompt)
            end

            task.wait(0.2)
        until waterAttribute.Value >= waterAttribute.MaxValue * 0.75 or tick() >= deadline or not ap:armed()
    end
    function module.enterDungeon()
        ap.progress = 'Travelling to Titus'

        local requests = noEffects.services.ReplicatedStorage.Requests
        local target = CFrame.new(-6875.86, 336.2, 2827.95)

        pcall(function()
            delayedTask.method(requests.UpdateUXSettings, 'FireServer', 'FriendlyFire', true)
        end)
        noEffects.enableFeature('Flight')
        noEffects.enableFeature('NoClip')

        local ok, err = pcall(module.safeTween, target, 170)

        if not ok then
            error(err, 0)
        end

        pcall(function()
            delayedTask.method(requests.UpdateUXSettings, 'FireServer', 'FriendlyFire', true)
        end)

        local meritEntry = workspace.Map:WaitForChild('MeritEntry', 10)
        local startTime = tick()

        repeat
            noEffects.enableFeature('Flight')
            noEffects.enableFeature('NoClip')

            if module.playerNearby(200, target.Position) then
                module.serverHop()

                while task.wait() do end
            end
            if meritEntry and meritEntry:FindFirstChild('InteractPrompt') then
                pcall(delayedTask.call, fire, meritEntry.InteractPrompt)
            end

            task.wait(0.1)
        until tick() - startTime > 30 or game.PlaceId ~= placeIds.EASTERN or not ap:armed()
    end
    function module.attachToTitus()
        local titus

        repeat
            for index, child in ipairs(workspace.Live:GetChildren())do
                if child.Name:lower():find('titus') then
                    titus = child

                    break
                end
            end

            task.wait()
        until titus or not ap:armed()

        if not titus then
            return
        end

        local torso = titus:WaitForChild('Torso', 10)

        if not torso then
            return
        end

        ap:spawn(function()
            while titus and titus.Parent and ap:armed() and not module.l do
                virtualInput:SendKeyEvent(true, Enum.KeyCode.Q, false, game)
                task.wait(0.05)
                virtualInput:SendKeyEvent(false, Enum.KeyCode.Q, false, game)
                task.wait(0.3)
            end
        end)
        ap:spawn(function()
            local character = getRootPart()

            if not character then
                return
            end

            local teleportPos = CFrame.new(torso.CFrame.X, 288, torso.CFrame.Z)

            if module.l then
                return
            end

            character.AssemblyLinearVelocity = Vector3.zero

            travelRecovery.new(teleportPos, true, 250).wait()
            task.wait(0.5)

            if module.l then
                return
            end

            travelRecovery.new(teleportPos, true, 250).wait()

            local recovery

            while task.wait() do
                character = getRootPart()

                if module.l or not titus or not titus.Parent or not torso.Parent or not character or not ap:armed() then
                    if recovery then
                        recovery.stop()
                    end

                    break
                end
                if torso.Position.Y > 2000 then
                    return module.serverHop()
                end

                local target = CFrame.new((torso.CFrame * CFrame.new(0, 1, 0)).Position) * CFrame.Angles(math.rad(
-90), 0, 0)

                character.AssemblyLinearVelocity = Vector3.zero

                local minY = isEchoModeActive() and 12 or -3

                if target.Position.Y < minY then
                    target = target + Vector3.new(0, minY - target.Y, 0)

                    if character.Position.Y < minY then
                        character.CFrame = character.CFrame + Vector3.new(0, minY - character.Position.Y, 0)
                    end
                end

                local currentPos = Vector3.new(character.Position.X, 0, character.Position.Z)
                local targetPos = Vector3.new(target.Position.X, 0, target.Position.Z)

                if (currentPos - targetPos).Magnitude > 35 then
                    if recovery then
                        recovery.stop()
                    end

                    recovery = travelRecovery.new(target, true, 200)

                    pcall(function()
                        noEffects.localPlayer.character.CharacterHandler.Requests.DrawWeapon:FireServer(true)
                    end)
                else
                    if recovery then
                        recovery.stop()

                        recovery = nil
                    end

                    character.CFrame = target
                end
            end
        end)
    end

    local normalizeSearchText = function(text)
        return tostring(text):gsub('<[^>]*>', ''):lower():gsub('[%s%p]', '')
    end
    local countItems = function(itemName)
        local count = 0

        for containerIndex, container in pairs({
            noEffects.localPlayer.instance:FindFirstChild('Backpack'),
            noEffects.localPlayer.character,
        })do
            for childIndex, child in ipairs(container:GetChildren())do
                if child:IsA('Tool') and normalizeSearchText(child.Name):find(normalizeSearchText(itemName), 1, true) then
                    local quantity = child:FindFirstChild('Quantity')

                    count = count + (quantity and tonumber(quantity.Value) or 1)
                end
            end
        end

        return count
    end

    function module.grabChest()
        ap.progress = 'Finding chest'

        local chest = module.chest
        local searchStart = tick()

        while not chest and ap:armed() and tick() - searchStart < 15 do
            local position = getRootPart()
            local bestDistance, bestModel = 1000

            for thrownIndex, thrownModel in ipairs(workspace.Thrown:GetChildren())do
                local lid = thrownModel:FindFirstChild('Lid')

                if position and lid and (position.Position - lid.Position).Magnitude < bestDistance then
                    bestModel = thrownModel
                    bestDistance = (position.Position - lid.Position).Magnitude
                end
            end

            if bestModel then
                chest = {
                    model = bestModel,
                    picked = 0,
                }
                module.chest = chest
            else
                task.wait(0.1)
            end
        end

        if not chest then
            return false
        end

        local playerGui = noEffects.localPlayer.instance.PlayerGui
        local lastMenu
        local menuTime = tick()
        local lastFire = -math.huge

        searchStart = tick()

        while ap:armed() and tick() - searchStart < 45 do
            if chest.pending and countItems(chest.pending.item) > chest.pending.count then
                chest.picked = chest.picked + 1
                chest.pending = nil
                lastMenu = nil
                menuTime = tick()
                searchStart = tick()

                task.wait(0.3)
            end
            if chest.pending and countItems(chest.pending.item) >= 25 then
                chest.pending = nil
                menuTime = tick()
            end
            if not chest.model.Parent then
                return chest.picked > 0 and not chest.pending
            end

            local playerPos = getRootPart()
            local chestLid = chest.model:FindFirstChild('Lid')
            local prompt = chest.model:FindFirstChildWhichIsA('ProximityPrompt', true)

            if isEchoModeActive() and prompt then
                promptRange.extend(prompt)
            end
            if not playerPos or not chestLid then
                return false
            end

            local range = prompt and prompt.MaxActivationDistance * 0.75 or 6

            if not isEchoModeActive() then
                range = math.min(6, range)
            end
            if (playerPos.Position - chestLid.Position).Magnitude > range then
                ap.progress = 'Approaching chest'

                local travel = travelRecovery.new(module.dryCFrame(chestLid.CFrame), true, 150)
                local travelStart = tick()

                repeat
                    task.wait(0.1)

                    playerPos = getRootPart()
                until not ap:armed() or not playerPos or not chestLid.Parent or (playerPos.Position - chestLid.Position).Magnitude <= range or tick() - travelStart >= 15

                travel.stop()

                lastMenu = nil
                menuTime = tick()

                continue
            end

            ap.progress = 'Collecting chest loot'

            local choicePrompt = playerGui:FindFirstChild('ChoicePrompt')
            local choiceFrame = choicePrompt and choicePrompt:FindFirstChild('ChoiceFrame')
            local options = choiceFrame and choiceFrame:FindFirstChild('Options')
            local choice = choicePrompt and choicePrompt:FindFirstChild('Choice')

            if not options or not choice then
                lastMenu = nil
                menuTime = tick()

                if not choicePrompt and prompt and tick() - lastFire >= 0.5 then
                    pcall(delayedTask.call, fire, prompt)

                    lastFire = tick()
                end

                task.wait(0.1)

                continue
            end

            local chosenButton, chosenName
            local entries = {}

            for buttonIndex, button in ipairs(options:GetChildren())do
                if not button:IsA('TextButton') or not button.Visible then
                    continue
                end

                local title = button:FindFirstChild('Title', true)
                local label = normalizeSearchText((title and title.Text ~= '' and title.Text) or (button.Text ~= '' and button.Text) or button.Name)

                entries[#entries + 1] = button.Name .. ':' .. label

                local wishlist = isEchoModeActive() and {
                    "Idol of Yun'Shul",
                    'Enchant Stone',
                } or noEffects.value('auto_titus_relics', {})

                for wishIndex, wishItem in pairs(wishlist)do
                    local name = type(wishIndex) == 'number' and wishItem or (wishItem and wishIndex)

                    if type(name) == 'string' and normalizeSearchText(name) ~= '' and label:find(normalizeSearchText(name), 1, true) then
                        if countItems(name) >= 25 then
                            break
                        end
                        if not chest.pending or normalizeSearchText(chest.pending.item) == normalizeSearchText(name) then
                            chosenButton, chosenName = button, name
                        end

                        break
                    end
                end
            end

            table.sort(entries)

            local signature = table.concat(entries, '|')

            if lastMenu ~= signature or chest.menu ~= choicePrompt then
                lastMenu = signature
                chest.menu = choicePrompt
                menuTime = tick()
            end
            if chosenButton then
                if not chest.pending then
                    chest.pending = {
                        item = chosenName,
                        count = countItems(chosenName),
                        sent = -math.huge,
                    }
                end
                if tick() - chest.pending.sent >= 1 then
                    chest.pending.sent = tick()

                    pcall(function()
                        delayedTask.method(choice, 'FireServer', chosenButton.Name)
                    end)
                end

                menuTime = tick()
            elseif chest.pending then
                menuTime = tick()
            elseif tick() - menuTime >= 3 then
                local success = pcall(function()
                    delayedTask.method(choice, 'FireServer', 'EXIT')
                end)

                return success
            end

            task.wait(0.1)
        end

        return false
    end

    local findToolInInventory = function(toolName)
        local player = noEffects.localPlayer.instance
        local backpack = player and player:FindFirstChild('Backpack')

        for containerIndex, container in ipairs({
            backpack,
            noEffects.localPlayer.character,
        })do
            if container then
                for childIndex, child in ipairs(container:GetChildren())do
                    if child:IsA('Tool') and child.Name:find(toolName, 1, true) then
                        return child
                    end
                end
            end
        end
    end
    local getChoicePrompt = function()
        local playerInstance = noEffects.localPlayer.instance
        local playerGui = playerInstance and playerInstance:FindFirstChild('PlayerGui')
        local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')

        if choicePrompt and choicePrompt:IsA('ScreenGui') and not choicePrompt.Enabled then
            return nil, nil
        end

        return choicePrompt and choicePrompt:FindFirstChild('Choice'), choicePrompt
    end
    local waitForChoicePrompt = function(timeout)
        local deadline = os.clock() + timeout

        repeat
            local result = getChoicePrompt()

            if result then
                return result
            end

            task.wait(0.1)
        until os.clock() >= deadline or not ap:armed()
    end
    local waitForChoiceConsumed = function(item, duration)
        local cutoff = os.clock() + duration

        repeat
            if not getChoicePrompt() and not item.Parent then
                return true
            end

            task.wait(0.1)
        until os.clock() >= cutoff or not ap:armed()

        return false
    end
    local validateEchoRelicPrep = function()
        local humanoid = noEffects.localPlayer.humanoid

        if not humanoid then
            return false, 'Character not ready for Echo relics'
        end
        if not findToolInInventory("Idol of Yun'Shul") or not findToolInInventory('Enchant Stone') then
            return false, 'Idol or Enchant Stone was not collected'
        end

        local choice = getChoicePrompt()

        if choice then
            delayedTask.method(choice, 'FireServer', 'EXIT')

            local closeDeadline = os.clock() + 3

            repeat
                task.wait(0.1)
            until not getChoicePrompt() or os.clock() >= closeDeadline or not ap:armed()

            if getChoicePrompt() then
                return false, 'Chest choice prompt did not close'
            end
        end

        local idol = findToolInInventory("Idol of Yun'Shul")

        if idol and ap:armed() then
            ap.progress = "Using Idol of Yun'Shul"

            humanoid:EquipTool(idol)
            task.wait(0.3)

            for attempt = 1, 3 do
                if not ap:armed() then
                    return false, 'Stopped'
                end

                idol:Activate()

                if waitForChoicePrompt(1) then
                    break
                end
            end

            local idolChoice = getChoicePrompt()

            if not idolChoice then
                return false, 'Idol choice was not offered'
            end

            delayedTask.method(idolChoice, 'FireServer', 'Give me relief from my Flaws.')

            if not waitForChoiceConsumed(idol, 8) then
                return false, 'Idol use was not confirmed'
            end
        end

        local enchantStone = findToolInInventory('Enchant Stone')

        if enchantStone and ap:armed() then
            ap.progress = 'Using Enchant Stone'

            local weaponBackpack = noEffects.localPlayer.instance:FindFirstChild('Backpack')

            weaponBackpack = weaponBackpack and weaponBackpack:FindFirstChild('Weapon')
            weaponBackpack = weaponBackpack and weaponBackpack:FindFirstChild('Weapon')

            local weapon = weaponBackpack and weaponBackpack.Value

            if not weapon then
                return false, 'Equipped weapon was not found'
            end

            pcall(delayedTask.method, noEffects.services.ReplicatedStorage.Requests.Unequip, 'InvokeServer', 'Weapon', true)
            task.wait(0.5)

            local weaponTool = findToolInInventory(weapon)

            if not weaponTool then
                return false, 'Weapon tool was not found'
            end

            humanoid:EquipTool(weaponTool)
            task.wait(0.1)
            weaponTool:Activate()
            humanoid:EquipTool(enchantStone)
            task.wait(0.5)
            enchantStone:Activate()

            local enchantChoice = getChoicePrompt()

            if not enchantChoice then
                waitForChoicePrompt(5)

                enchantChoice = getChoicePrompt()
            end
            if not enchantChoice then
                return false, 'Enchant Stone choice was not offered'
            end

            delayedTask.method(enchantChoice, 'FireServer', true)

            if not waitForChoiceConsumed(enchantStone, 8) then
                return false, 'Enchant Stone use was not confirmed'
            end
        end

        return true
    end
    local createEchoCharacter = function()
        ap.progress = 'Creating Echo character'

        local creationConfig = {
            creation = {
                origin = 'Authority Ensign',
                weapon = 'Sword',
                elements = {},
                echoModifiersAll = true,
                boons = {
                    'Autodidact',
                    'Maverick',
                },
                flaws = {
                    'Manic',
                    'Obvious',
                },
            },
        }
        local created, creationError = characterCreation.run(creationConfig, function()
            return ap:armed() and isEchoModeActive()
        end)

        if not created then
            return false, creationError
        end

        local deadline = os.clock() + 30

        repeat
            local character = noEffects.localPlayer.character
            local humanoid = noEffects.localPlayer.humanoid
            local backpack = noEffects.localPlayer.instance:FindFirstChild('Backpack')

            if not characterCreation.active() and character and character:FindFirstChild('HumanoidRootPart') and humanoid and humanoid.Health > 0 and backpack and noEffects.services.CollectionService:HasTag(backpack, 'Loaded') then
                break
            end

            task.wait(0.2)
        until os.clock() >= deadline or not ap:armed()

        local backpack = noEffects.localPlayer.instance:FindFirstChild('Backpack')

        if characterCreation.active() or not noEffects.localPlayer.root_part or not noEffects.localPlayer.humanoid or noEffects.localPlayer.humanoid.Health <= 0 or not backpack or not noEffects.services.CollectionService:HasTag(backpack, 'Loaded') then
            return false, 'Waiting for created Echo character'
        end

        local echoData = persistentData.get('efdata')

        if type(echoData) == 'table' and echoData.wiped then
            persistentData.set('efdata', nil)
        end

        return true
    end
    local shouldWipeEcho = function()
        if module.echoWiping then
            return true
        end
        if not module.relicsDone then
            ap.progress = 'Echo wipe waiting for Idol and Enchant Stone'

            return false
        end

        local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

        if not dataSlot then
            ap.progress = 'Echo wipe paused: character slot unavailable'

            return false
        end

        module.echoWiping = true
        ap.progress = 'Wiping Titus Echo character'

        persistentData.set('efdata', {
            slot = tostring(dataSlot),
            wiped = false,
            relicsDone = true,
        })
        noEffects.setValue('auto_titus_echo_pending_slot', tostring(dataSlot))
        a["Game/Wipe"]().invoke(dataSlot)

        return true
    end

    function module.runDungeon()
        module.chest = nil
        module.relicsDone = nil
        ap.progress = 'Fighting Titus'
        module.l = false

        local fightStart = tick()

        repeat
            task.wait(0.2)
        until (noEffects.localPlayer.instance:GetAttribute('CurrentArea') and noEffects.localPlayer.instance:GetAttribute('CurrentArea'):match('Detainment')) or not ap:armed()

        task.wait(1)
        module.attachToTitus()

        local humanoid = noEffects.localPlayer.humanoid

        if humanoid then
            ap:connect(humanoid.Died, function()
                if isEchoModeActive() then
                    ap.progress = 'Echo run ended before relics were confirmed'
                else
                    noEffects.hop(noEffects.localPlayer.instance:GetAttribute('DataSlot'), true)
                end
            end)
        end

        local exitFound = false
        local detainmentCore = workspace:WaitForChild('DetainmentCore', 30)
        local childConnection = detainmentCore and ap:connect(detainmentCore.ChildAdded, function(child)
            if child.Name == 'DungeonExitFinal' then
                exitFound = true
            end
        end)

        exitFound = detainmentCore and detainmentCore:FindFirstChild('DungeonExitFinal') ~= nil or false

        repeat
            task.wait(0.2)

            if tick() - fightStart > 30 then
                if childConnection then
                    childConnection:Disconnect()
                end

                module.serverHop()

                while task.wait() do end
            end
        until exitFound or not ap:armed()

        if childConnection then
            childConnection:Disconnect()
        end
        if not exitFound or not ap:armed() then
            return false
        end
        if isEchoModeActive() and noEffects.value('auto_titus_echo_run_job') ~= game.JobId then
            local aH = persistentData.get('auto') or {}

            aH.auto_titus_echo_run_job = game.JobId
            aH.auto_titus_echo_runs = (tonumber(aH.auto_titus_echo_runs) or 0) + 1

            persistentData.set('auto', aH)
        end

        module.l = true

        travelRecovery.stopAll()
        task.wait(0.5)

        local retries, ok, result = 0

        repeat
            ok, result = pcall(module.grabChest)

            if not ok or result ~= true then
                retries = retries + 1

                if isEchoModeActive() and retries >= 2 then
                    ap.progress = 'Chest pickup failed; finding another Titus server'

                    module.serverHop()

                    return false
                end

                ap.progress = 'Retrying chest pickup'

                task.wait(1)
            end
        until (ok and result == true) or not ap:armed()

        if isEchoModeActive() and ap:armed() then
            local relicsOk, relicsError = validateEchoRelicPrep()

            if not relicsOk then
                ap.progress = 'Echo relics incomplete; finding another Titus server: ' .. tostring(relicsError)

                module.serverHop()

                return false
            end

            module.relicsDone = true

            shouldWipeEcho()

            return false
        end

        return ap:armed()
    end

    local shouldPauseAutoProgression = function()
        if isEchoModeActive() or noEffects.flag('auto_progression', false) then
            return false
        end

        local progressionSession = noEffects.value('progression_session', nil)

        if progressionSession and progressionSession.bankFull then
            return false
        end

        local bankItems = noEffects.value('auto_titus_bank_items', nil)

        if not bankItems then
            return false
        end
        if tick() - module.lastBankAt <= 45 then
            return false
        end

        for itemId, count in next, bankItems do
            if count and module.countItem(itemId) >= 25 then
                return true
            end
        end

        return false
    end

    ap = automationStep.construct({
        id = 'auto_titus',
        persistentFlag = 'auto_titus',
        features = {
            'Flight',
            'NoFallDamage',
            'NoClip',
            'PathfindBreaker',
            'AggressiveMode',
        },
        notAllowed = function()
            return placeIds.isDepths() and not isEchoModeActive()
        end,
        onRun = function()
            ap.connections[#ap.connections + 1] = noEffects.services.RunService.PreSimulation:Connect(function(
            )
                if not ap:armed() or not isEchoModeActive() then
                    return
                end

                local part = getRootPart()

                if not part then
                    return
                end

                local dryCFrame = module.dryCFrame(part.CFrame)

                if dryCFrame.Y > part.Position.Y then
                    part.AssemblyLinearVelocity = Vector3.zero
                    part.CFrame = dryCFrame
                end
            end)

            while ap:armed() do
                module.ensureEchoModifiers()
                noEffects.enableFeature('Flight')
                noEffects.enableFeature('NoFallDamage')
                noEffects.enableFeature('NoClip')
                noEffects.enableFeature('PathfindBreaker')
                noEffects.enableFeature('AggressiveMode')
                task.wait(0.2)
            end
        end,
        onStop = function()
            module.creationFailures = nil

            if module.pr then
                local promptRangeMultiplier = Options and Options.PromptRangeMultiplier

                if promptRangeMultiplier then
                    promptRangeMultiplier:SetValue(module.pr[2])
                end

                noEffects.setFeature('PromptRange', module.pr[1])

                module.pr = nil
            end
            if module.echoModifiersPrevious ~= nil then
                noEffects.setFeature('NoEchoModifiers', module.echoModifiersPrevious)

                module.echoModifiersPrevious = nil
            end
        end,
        stateMachine = stateMachine.create({
            initial = 'idle',
            events = {
                {
                    name = 'start',
                    from = 'idle',
                    to = '_check_area',
                },
                {
                    name = 'continuation',
                    from = '_check_area',
                    to = '_check_area',
                },
                {
                    name = 'bank',
                    from = '_check_area',
                    to = '_bank_relics',
                },
                {
                    name = 'continuation',
                    from = '_bank_relics',
                    to = '_check_area',
                },
                {
                    name = 'enter',
                    from = '_check_area',
                    to = '_enter_dungeon',
                },
                {
                    name = 'run',
                    from = '_check_area',
                    to = '_run_dungeon',
                },
                {
                    name = 'exit',
                    from = '_run_dungeon',
                    to = '_exit',
                },
            },
            callbacks = {
                onenter_check_area = function(ctx)
                    if isEchoModeActive() then
                        local echoData = persistentData.get('efdata')

                        if type(echoData) == 'table' and not echoData.wiped then
                            if not echoData.relicsDone then
                                persistentData.set('efdata', nil)
                            else
                                local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

                                if dataSlot and tostring(dataSlot) ~= tostring(echoData.slot) then
                                    ap.progress = 'Echo wipe paused: selected slot changed'

                                    return
                                end

                                ap.progress = 'Continuing pending Echo wipe'

                                a["Game/Wipe"]().invoke(echoData.slot)

                                return
                            end
                        end
                    end
                    if isEchoModeActive() and characterCreation.active() then
                        local success, aF = createEchoCharacter()

                        if not success then
                            module.creationFailures = (module.creationFailures or 0) + 1

                            if module.creationFailures >= 3 then
                                ap.progress = 'Echo character creation failed 3 times; switching servers'

                                return module.serverHop()
                            end

                            ap.progress = 'Retrying Echo character creation (' .. module.creationFailures .. '/3): ' .. tostring(aF)

                            ap:delay(3, ctx.continuation, ctx)

                            return
                        end

                        module.creationFailures = nil

                        ap:defer(ctx.continuation, ctx)

                        return
                    end

                    module.creationFailures = nil

                    if isEchoModeActive() then
                        local currentEchoData = persistentData.get('efdata')

                        if type(currentEchoData) == 'table' and currentEchoData.wiped then
                            persistentData.set('efdata', nil)
                        end
                    end
                    if placeIds.isEtrean() then
                        logger.notify('Auto Titus: travelling to the Eastern Luminant.')

                        if not regionTransfer.toEastern(nil, function()
                            return ap:armed()
                        end) then
                            logger.notify('Auto Titus: could not reach Eastern, hopping.')

                            return module.serverHop()
                        end
                    end
                    if placeIds.isEastern() then
                        if shouldPauseAutoProgression() then
                            module.lastBankAt = tick()

                            return ctx:bank()
                        end
                        if module.needFood() then
                            module.refillFood()
                        end

                        return ctx:enter()
                    end
                    if placeIds.isDungeon() then
                        return ctx:run()
                    end
                    if placeIds.isDepths() then
                        if isEchoModeActive() then
                            ap.progress = 'Echo run ended before relics were confirmed; wipe cancelled'
                        else
                            ap.progress = 'Waiting to leave the Depths'
                        end

                        return
                    end
                end,
                onenter_bank_relics = function(ctxBank)
                    module.bankRelics()
                    ctxBank:continuation()
                end,
                onenter_enter_dungeon = function(ctxDungeon)
                    module.enterDungeon()
                    ap:defer(ctxDungeon.start, ctxDungeon)
                end,
                onenter_run_dungeon = function(ctxRun)
                    if module.runDungeon() == false then
                        return
                    end

                    task.wait(2)

                    local characterPart = getRootPart()

                    if characterPart then
                        characterPart.CFrame = characterPart.CFrame * CFrame.new(0, 10000, 0)
                    end

                    local humanoid = noEffects.localPlayer.humanoid
                    local dangerExpiration = humanoid and humanoid:GetAttribute('DangerExpiration')

                    if dangerExpiration and dangerExpiration > 0 then
                        repeat
                            task.wait()

                            humanoid = noEffects.localPlayer.humanoid
                            dangerExpiration = humanoid and humanoid:GetAttribute('DangerExpiration')
                        until not (dangerExpiration and dangerExpiration > 0)
                    end

                    ap:defer(ctxRun.exit, ctxRun)
                end,
                onenter_exit = function()
                    module.serverHop()
                end,
            },
        }),
    })

    function module.bankSubmit()
        if noEffects.flag('auto_progression', false) or not ap:armed() then
            return false
        end

        local playerGui = noEffects.localPlayer.instance.PlayerGui
        local choicePrompt = playerGui:FindFirstChild('ChoicePrompt')

        if not choicePrompt then
            return false
        end

        local maxChoice = choicePrompt:GetAttribute('Max')
        local choice = choicePrompt:FindFirstChild('Choice')

        if not maxChoice or not choice then
            return false
        end
        if not choicePrompt.Enabled then
            return false
        end

        local submitResult = pcall(delayedTask.method, choice, 'InvokeServer', maxChoice)

        return submitResult
    end
    function module.bankFull()
        local playerGuiFull = noEffects.localPlayer.instance.PlayerGui
        local choicePromptFull = playerGuiFull:FindFirstChild('ChoicePrompt')
        local descSheet = choicePromptFull and choicePromptFull:FindFirstChild('DescSheet', true)

        if not descSheet or not descSheet:FindFirstChild('Ok') then
            return false
        end

        local descText = descSheet:FindFirstChild('Desc', true)

        return descText ~= nil and descText.Text == "You don't have any bank slots free."
    end

    local hideChoicePrompt = function()
        local playerGuiHide = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local choicePromptHide = playerGuiHide and playerGuiHide:FindFirstChild('ChoicePrompt')
        local bankGuiHide = playerGuiHide and playerGuiHide:FindFirstChild('BankGui')

        if choicePromptHide and choicePromptHide:IsA('ScreenGui') then
            choicePromptHide.Enabled = false
        end
        if bankGuiHide and bankGuiHide:IsA('ScreenGui') then
            bankGuiHide.Enabled = false
        end
    end

    function module.returnToMenu()
        local player = noEffects.localPlayer.instance
        local returnStartTime = tick()

        while player.Character and tick() - returnStartTime < 15 do
            pcall(function()
                delayedTask.method(noEffects.services.ReplicatedStorage.Requests.ReturnToMenu, 'FireServer')
            end)
            noEffects.services.RunService.PreRender:Wait()

            local choicePromptMenu = player.PlayerGui:FindFirstChild('ChoicePrompt')

            if choicePromptMenu then
                pcall(function()
                    choicePromptMenu.Enabled = false
                end)
                pcall(function()
                    delayedTask.method(choicePromptMenu.Choice, 'FireServer', true)
                end)
            end

            pcall(function()
                delayedTask.method(noEffects.services.ReplicatedStorage.Requests.TeleportFailed, 'FireServer')
            end)
        end
    end
    function module.bankRelics()
        if noEffects.flag('auto_progression', false) then
            hideChoicePrompt()

            return false, 'progression-banking-disabled'
        end

        ap.progress = 'Banking relics'

        local banker = workspace.NPCs:WaitForChild('Banker', 10)

        if not banker or not banker:FindFirstChild('HumanoidRootPart') then
            return
        end

        local targetCframe = banker.HumanoidRootPart.CFrame * CFrame.new(0, 0, -3)

        noEffects.enableFeature('Flight')
        noEffects.enableFeature('NoFallDamage')
        noEffects.enableFeature('NoClip')
        module.safeTween(targetCframe, 150, true)

        local playerGuiBank = noEffects.localPlayer.instance.PlayerGui
        local bankTimeoutStart = tick()

        repeat
            local dialogueGui = playerGuiBank:FindFirstChild('DialogueGui')

            if noEffects.flag('auto_progression', false) or not ap:armed() then
                hideChoicePrompt()

                return false, 'cancelled'
            end
            if dialogueGui and dialogueGui.Enabled then
                pcall(function()
                    delayedTask.method(noEffects.services.ReplicatedStorage.Requests.SendDialogue, 'FireServer', {
                        choice = 'Can I access my account?',
                    })
                end)
            else
                pcall(delayedTask.call, fire, banker.InteractPrompt)
            end

            task.wait(0.5)
        until playerGuiBank:FindFirstChild('BankGui') or tick() - bankTimeoutStart > 15

        local bankGui = playerGuiBank:FindFirstChild('BankGui')
        local bankItems = noEffects.value('auto_titus_bank_items', nil)

        if not bankGui or not bankGui.Enabled or not bankItems then
            hideChoicePrompt()

            return false, 'bank-unavailable'
        end

        for itemName, itemInfo in next, bankItems do
            if not itemInfo or module.countItem(itemName) < 25 then
                continue
            end

            local tryCount = 0

            while module.countItem(itemName) > 0 and tryCount < 6 do
                if noEffects.flag('auto_progression', false) or not ap:armed() then
                    hideChoicePrompt()

                    return false, 'cancelled'
                end

                tryCount = tryCount + 1

                local itemCount = module.countItem(itemName)
                local items = {}

                for index, backpackItem in ipairs(noEffects.localPlayer.instance.Backpack:GetChildren())do
                    if backpackItem.Name == itemName then
                        items[#items + 1] = backpackItem
                    end
                end

                if #items == 0 then
                    break
                end

                local depositChoice = bankGui:FindFirstChild('Choice')

                if not depositChoice then
                    hideChoicePrompt()

                    return false, 'bank-choice-missing'
                end

                task.wait(1)

                if noEffects.flag('auto_progression', false) or not ap:armed() then
                    hideChoicePrompt()

                    return false, 'cancelled'
                end

                delayedTask.method(depositChoice, 'FireServer', 'deposit', items)

                local depositStartedAt = tick()

                repeat
                    if noEffects.flag('auto_progression', false) or not ap:armed() then
                        hideChoicePrompt()

                        return false, 'cancelled'
                    end
                    if module.bankFull() then
                        ap.progress = 'Bank full - continuing Titus'

                        hideChoicePrompt()
                        noEffects.setValue('auto_titus_bank_items', {})

                        local aS = noEffects.value('progression_session', nil)

                        if aS then
                            aS.bankFull = true

                            noEffects.setValue('progression_session', aS)
                        end

                        module.lastBankAt = tick()

                        return false, 'bank-full'
                    end

                    local choicePromptBank = playerGuiBank:FindFirstChild('ChoicePrompt')

                    if choicePromptBank and choicePromptBank.Enabled then
                        module.bankSubmit()
                        task.wait(1)
                    else
                        task.wait(0.25)
                    end
                until module.countItem(itemName) < itemCount or tick() - depositStartedAt > 8

                task.wait(1)
            end
        end

        hideChoicePrompt()

        module.lastBankAt = tick()

        return true
    end

    ap.ensureEchoModifiers = module.ensureEchoModifiers

    return ap
end


return aa()

]=],
    ["Features/Automation/ExecutionQueue"] = [=[
local aa = function()
    local module = {
        log = {},
        active = nil,
        pending = nil,
    }
    local logEvent = function(event, reason)
        local log = module.log

        log[#log + 1] = {
            at = os.clock(),
            event = event,
            reason = reason,
        }

        if #log > 80 then
            table.remove(log, 1)
        end
    end

    function module.acquire(owner)
        local active = module.active

        if active and active.owner == owner and module.valid(active) then
            return active
        end
        if active and module.valid(active) then
            return nil
        end
        if active then
            module.cancel(active.owner, 'expired execution')
        end

        local entry = {
            owner = owner,
            generation = owner.generation,
            character = game.Players.LocalPlayer.Character,
            checkpoint = true,
        }

        module.active = entry

        logEvent('acquire', owner.id)

        return entry
    end
    function module.valid(execution)
        return execution and not execution.cancelled and module.active == execution and execution.owner.generation == execution.generation and execution.character == game.Players.LocalPlayer.Character
    end
    function module.cancel(target, cause)
        local current = module.active

        if current and current.owner == target then
            current.cancelled = true

            if current.stopMovement then
                current.stopMovement()
            end

            module.active = nil

            logEvent('cancel', cause)
        end
    end
    function module.request(requester, detail, force)
        local existing = module.active

        if existing and module.valid(existing) and existing.owner ~= requester and not force and (not existing.checkpoint or existing.stopMovement) then
            module.pending = {
                owner = requester,
                reason = detail,
            }

            return false
        end

        module.pending = nil

        return true
    end
    function module.checkpoint(player, checkpoint, message)
        local live = module.active

        if live and live.owner == player then
            live.checkpoint = checkpoint
        end

        logEvent(checkpoint and 'checkpoint' or 'busy', message)
    end
    function module.progress(holder, note)
        local present = module.active

        if present and present.owner == holder then
            present.lastProgress = os.clock()
        end

        logEvent('progress', note)
    end

    return module
end


return aa()

