        ['Ice Skate'] = true,
        ['Flame Leap'] = true,
        ['Metal Fakeout'] = true,
        ['Spark Swap'] = true,
        ['Lightning Cloak'] = true,
        ['Blood Wisp'] = true,
        ['Flame Wisp'] = true,
        ['Frost Wisp'] = true,
        ['Thunder Wisp'] = true,
        ['Metal Wisp'] = true,
        ['Shade Wisp'] = true,
        ['Gale Wisp'] = true,
        ['Graceful Flame'] = true,
        ['Wind Passage'] = true,
        ['Flame of Denial'] = true,
    }
    local au = {}

    for mantraName, aliasName in pairs(mantraAliases)do
        if not at[mantraName] then
            au[mantraName] = aliasName:match(':([%a]+)$')
            au[aliasName] = au[mantraName]
        end
    end

    local av = {
        ['Fire Blade'] = true,
        ['Flame Grab'] = true,
        ['Burning Servants'] = true,
        ['Wind Blade'] = true,
        ['Air Force'] = true,
        ['Frozen Servants'] = true,
        ['Ice Beam'] = true,
        ["Warden's Blades"] = true,
        ['Clutching Shadow'] = true,
        ['Shadow Gun'] = true,
        ['Dark Blade'] = true,
        ['Blood Orb'] = true,
        ['Crucifixion'] = true,
        ['Metal Eruption'] = true,
        ['Needle Barrage'] = true,
        ['Lightning Beam'] = true,
        ['Electro Carve'] = true,
        ['Lightning Blade'] = true,
        ['Tornado Kick'] = true,
    }
    local aw = {
        Flamecharm = 'Fire',
        Frostdraw = 'Ice',
        Thundercall = 'Lightning',
        Galebreathe = 'Wind',
        Shadowcast = 'Shadow',
        Ironsing = 'Metal',
        Bloodrend = 'Blood',
    }
    local getRootPart = function()
        return noEffects.localPlayer.root_part
    end
    local getBackpack = function()
        return noEffects.localPlayer.instance:FindFirstChild('Backpack')
    end
    local findItem = function(itemName)
        return (getBackpack() and getBackpack():FindFirstChild(itemName)) or (noEffects.localPlayer.character and noEffects.localPlayer.character:FindFirstChild(itemName))
    end
    local aA
    local getEffectReplicator = function()
        if aA then
            return aA
        end

        local effectReplicator = noEffects.services.ReplicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local loadOk, effectModule = pcall(require, effectReplicator)

        aA = loadOk and effectModule or nil

