        return aq:armed() and aq.runId == aq.generation and aq.character == noEffects.localPlayer.character and humanoid and humanoid.Health > 0
    end
    local isInFerrymanDungeon = function()
        local dungeon = noEffects.localPlayer.instance:GetAttribute('Dungeon')

        return type(dungeon) == 'string' and dungeon:find('Ferryman', 1, true) ~= nil
    end
    local hasToolLockCooldown = function(tool, toolName)
        if not tool or type(tool.GetEffects) ~= 'function' then
            return false
        end

        local getOk, effects = pcall(tool.GetEffects, tool)

        if not getOk or type(effects) ~= 'table' then
            return false
        end

        for index, effect in pairs(effects)do
            if type(effect) == 'table' and (effect.Class or (effect.index and effect.index.Class)) == 'ToolLockCD' and tostring(effect.Value or (effect.index and effect.index.Value)) == toolName.Name then
                return true
            end
        end

