        if type(trainingConfig) ~= 'table' or tick() < (aq.nextMantra or 0) or actionRunner.pending(noEffects.automation.ferryman_target) > 0 then
            return
        end

        local backpack = getBackpack()
        local character = noEffects.localPlayer.character
        local ether = character and character:FindFirstChild('Ether')
        local effectReplicator = getEffectReplicator()

        if not backpack or (ether and ether.Value <= 0) or hasActiveAction(effectReplicator) then
            aq.nextMantra = tick() + 0.25

