        end

        local candidates = {}
        local tools = backpack:GetChildren()

        for index, child in ipairs(character and character:GetChildren() or {})do
            tools[#tools + 1] = child
        end
        for index, tool in ipairs(tools)do
            if not tool:IsA('Tool') or not tool.Name:match('^Mantra:') then
                continue
            end

            local mantraName = tool:GetAttribute('DefaultName') or tool.Name:match('{{(.-)}}') or tool.Name:gsub('^Mantra:', '')
            local element = tool:GetAttribute('Element') or au[mantraName]

            element = aw[element] or element

            if element and trainingConfig[element] and av[mantraName] and au[mantraName] and tick() >= ((aq.mantraRetries or {})[tool] or 0) and not hasToolLockCooldown(effectReplicator, tool) and (not ether or ether.Value > (tool:GetAttribute('SpellCost') or 0)) then
                candidates[#candidates + 1] = tool
            end
        end

        if #candidates == 0 then
            aq.nextMantra = tick() + 0.25

