            local toolBName = toolB:GetAttribute('DefaultName') or toolB.Name

            if toolAName ~= toolBName and toolAName == 'Electro Carve' then
                return true
            end
            if toolAName ~= toolBName and toolBName == 'Electro Carve' then
                return false
            end

            return toolAName < toolBName
        end)

        aq.mantraIndex = (aq.mantraIndex or 0) % #candidates + 1

        local selectedMantra = candidates[aq.mantraIndex]
        local characterHandler = character and character:FindFirstChild('CharacterHandler')
        local requests = characterHandler and characterHandler:FindFirstChild('Requests')
        local activateMantra = requests and requests:FindFirstChild('ActivateMantra')

        if not activateMantra then
