    end
    local cancelFerrymanTarget = function()
        local ferrymanTarget = noEffects.automation.ferryman_target

        if ferrymanTarget then
            actionRunner.cancel(ferrymanTarget, 'ferryman', true)

            noEffects.automation.ferryman_target = nil
        end
    end
    local markStageTime = function()
        aq.stageAt = tick()
    end
    local stopTween = function()
        if aq.tween then
            aq.tween.stop()

            aq.tween = nil
        end

        aq.tweenGoal = nil
        aq.tweenDistance = nil
    end
    local clearTravelPath = function()
        aq.travelRoot = nil
        aq.travelOrigin = nil
        aq.travelGoal = nil
    end
