    local keepAfloat = function()
        for attempt = 1, 5 do
            local humanoid = noEffects.localPlayer.humanoid
            local root = getRootPart()

            if not humanoid or not root or humanoid:GetState() ~= Enum.HumanoidStateType.Swimming then
                return
            end

            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = root.CFrame + Vector3.new(0, 8, 0)

            task.wait(0.1)
        end
    end

    function ar.tween(target, speed, splashfix)
        if not isRunActive() then
            error('cancelled', 0)
        end

        local offset = getRootPart().Position - target.Position

        if not isInFerrymanDungeon() and Vector3.new(offset.X, 0, offset.Z).Magnitude > 700 then
            return ar.safeTween(target, speed, splashfix)
        end

        stopTween()

        noEffects.automation.requesting_mob_ai_breaker_stop = true
        aq.tweenGoal = target

        local distance = (getRootPart().Position - target.Position).Magnitude

        aq.tweenDistance = distance
        aq.tween = travelRecovery.new(target, true, speed)

        local succeeded = aq.tween.wait(math.huge)

        stopTween()

        if not succeeded or not isRunActive() then
            error('movement', 0)
        end
        if distance >= 3 then
            markStageTime()
        end
        if not splashfix then
            keepAfloat()
        end
    end
    function ar.playerNear(origin, range)
        local position = origin or (getRootPart() and getRootPart().Position)

        if not position then
            return false
        end

        for index, player in ipairs(noEffects.services.Players:GetPlayers())do
            if player == noEffects.localPlayer.instance or not player.Character then
                continue
            end
            if (position - player.Character:GetPivot().Position).Magnitude <= (range or 200) then
                return true
            end
        end

        return false
    end
    function ar.serverHop()
        aq.hopRequested = true

        error('recover', 0)
    end
    function ar.safeTween(target, speed, splashfix)
        if not isRunActive() then
            error('cancelled', 0)
        end
        if ar.playerNear() then
            return ar.serverHop()
        end
        if isInFerrymanDungeon() then
            noEffects.automation.forceSkyAfterFortitude = nil

            return ar.tween(target, speed, splashfix)
        end

        stopTween()

        noEffects.automation.requesting_mob_ai_breaker_stop = true

        local success, reason = travelAction.run(target, {
            speed = speed or 180,
            force = noEffects.automation.forceSkyAfterFortitude,
            alive = isRunActive,
            nearby = function()
                return ar.playerNear()
            end,
        })

        if not success then
            if reason == 'nearby' then
                return ar.serverHop()
            end
            if reason and reason:find('server', 1, true) then
                aq.hopRequested = true
            end

            error(reason or 'movement', 0)
