    local countItem = function(itemName)
        local count = 0

        for itemIndex, container in pairs({
            getBackpack(),
            noEffects.localPlayer.character,
        })do
            if container then
                for childIndex, child in ipairs(container:GetChildren())do
                    if child.Name == itemName then
                        local quantity = child:FindFirstChild('Quantity')

                        count = count + (quantity and quantity.Value or 1)
                    end
                end
            end
        end

        return count
    end
    local countFlintUses = function()
        local totalUses = 0

        for flintIndex, flintType in ipairs({
            'Flint',
            'Umbral Flint',
        })do
            local flint = findItem(flintType)

            if flint and flint:FindFirstChild('Uses') then
                totalUses = totalUses + flint.Uses.Value
            end
        end

        return totalUses
    end
    local findNearest = function(folder, predicate)
        local nearest
        local origin = getRootPart() and getRootPart().Position

        if not folder or not origin then
            return nil
        end

        for candidateIndex, candidate in ipairs(folder:GetChildren())do
            if not predicate(candidate) then
                continue
            end

            local candidatePos = (candidate:IsA('Model') and candidate:GetPivot() or candidate).Position

            if not nearest then
                nearest = candidate

                continue
            end

            local nearestPos = (nearest:IsA('Model') and nearest:GetPivot() or nearest).Position

            if (origin - candidatePos).Magnitude < (origin - nearestPos).Magnitude then
                nearest = candidate
            end
        end

        return nearest
    end
    local findNearestTree = function()
        return findNearest(workspace:FindFirstChild('Destructibles'), function(
            obj
        )
            return obj.Name:match('Tree') and obj:GetAttribute('StructureHealth') and obj:GetAttribute('StructureHealth') > 0
        end)
    end
    local respondToPrompt = function(prompt)
        if not prompt then
            return
        end

        local playerGui = noEffects.localPlayer.instance.PlayerGui

        for attempt = 1, 3 do
            if not isRunActive() then
                error('cancelled', 0)
            end
            if playerGui:FindFirstChild('ChoicePrompt') ~= prompt or prompt.Enabled == false then
                return
            end

            itemFilters.close(prompt)

            local startTime = tick()

            repeat
                task.wait(0.1)
            until playerGui:FindFirstChild('ChoicePrompt') ~= prompt or prompt.Enabled == false or tick() - startTime >= 3 or not isRunActive()
        end

        if playerGui:FindFirstChild('ChoicePrompt') == prompt and prompt.Enabled ~= false then
            error('chest close', 0)
        end
    end

    function ar.grabChests(materials, items, radius)
        aq.lootedChests = aq.lootedChests or {}
        aq.chestPickups = aq.chestPickups or {}

        local thrownFolder = workspace:FindFirstChild('Thrown')
        local chests = {}

        for descendantIndex, descendant in ipairs(thrownFolder and thrownFolder:GetDescendants() or {})do
            if descendant.Name == 'Lid' and descendant:IsA('BasePart') and (getRootPart().Position - descendant.Position).Magnitude <= (radius or 2000) then
                if not table.find(chests, descendant.Parent) then
                    chests[#chests + 1] = descendant.Parent
                end
            end
        end
        for pickedChest in pairs(aq.chestPickups)do
            if not pickedChest.Parent and not table.find(chests, pickedChest) then
                chests[#chests + 1] = pickedChest
            end
        end

        if not materials and #chests == 0 then
            error('chest', 0)
        end

        local gui = noEffects.localPlayer.instance.PlayerGui
        local results = {}

        for chestIndex, chest in ipairs(chests)do
            if not materials and aq.lootedChests[chest] then
                results[#results + 1] = chest

                continue
            end

            local done = false
            local attempts = 0

            while isRunActive() and not done and attempts < (materials and 3 or 1) do
                if not chest.Parent or not chest:FindFirstChild('Lid') then
                    done = aq.chestPickups[chest] == true and not chest.Parent

                    break
                end

                while itemFilters.full() and isRunActive() do
                    aq.progress = 'Inventory full'
                    aq.paused = true

                    task.wait(0.5)
                end

                aq.paused = false
                aq.progress = materials and 'Gathering materials' or 'Collecting loot'

                respondToPrompt(gui:FindFirstChild('ChoicePrompt'))
                ar.tween(chest.Lid.CFrame, 170)
                delayedTask.call(ae, chest:FindFirstChildWhichIsA('ProximityPrompt', true))

                local promptStarted = tick()

                repeat
                    task.wait(0.1)
                until (gui:FindFirstChild('ChoicePrompt') and gui:FindFirstChild('ChoicePrompt').Enabled ~= false) or tick() - promptStarted >= 8 or not isRunActive()

                local wantedItems = table.clone(items or noEffects.value('auto_ferryman_items', {}))
                local ringsNeeded = noEffects.automation.progressionScalingRingsNeeded or {}

                for ringIndex, ring in ipairs(ringsNeeded)do
                    if not table.find(wantedItems, ring) then
                        wantedItems[#wantedItems + 1] = ring
                    end
                end

                if noEffects.automation.kaidoManifestationNeeded and not table.find(wantedItems, 'Ardour Manifestation') then
                    wantedItems[#wantedItems + 1] = 'Ardour Manifestation'
                end
                if not materials and not table.find(wantedItems, "Ferryman's Coat Cloth") then
                    wantedItems[#wantedItems + 1] = "Ferryman's Coat Cloth"
                end

                local success, completed, status = itemFilters.fromPrompt(wantedItems, isRunActive, not materials and noEffects.value('auto_ferryman_loot_all', false), {
                    rarities = materials and {} or noEffects.value('auto_ferryman_rarities', itemFilters.defaults),
                    godrollRings = not materials and noEffects.value('auto_ferryman_godroll_rings', false),
                    forcedItems = not materials and ringsNeeded or nil,
                    progress = markStageTime,
                    exact = not materials,
                    timeout = not materials and 20 or 30,
                    settings = not materials and function()
                        local settingsItems = table.clone(noEffects.value('auto_ferryman_items', {}))
                        local settingsRings = noEffects.automation.progressionScalingRingsNeeded or {}

                        for settingsRingIndex, settingsRing in ipairs(settingsRings)do
                            if not table.find(settingsItems, settingsRing) then
                                settingsItems[#settingsItems + 1] = settingsRing
                            end
                        end

                        if noEffects.automation.kaidoManifestationNeeded and not table.find(settingsItems, 'Ardour Manifestation') then
                            settingsItems[#settingsItems + 1] = 'Ardour Manifestation'
                        end

                        for selectedItem, enabled in pairs(noEffects.value('auto_ferryman_selected', noEffects.value('auto_ferryman_pool', {})))do
                            if enabled then
                                settingsItems[#settingsItems + 1] = selectedItem
                            end
                        end

                        if not table.find(settingsItems, "Ferryman's Coat Cloth") then
                            settingsItems[#settingsItems + 1] = "Ferryman's Coat Cloth"
                        end

                        return settingsItems, noEffects.value('auto_ferryman_loot_all', false), {}, noEffects.value('auto_ferryman_godroll_rings', false), settingsRings
                    end or nil,
                })

                if success then
                    aq.chestPickups[chest] = true
                end

                done = completed or (aq.chestPickups[chest] and not chest.Parent)

                if status == 'cancelled' then
                    error('cancelled', 0)
                elseif success then
                    attempts = 0
                elseif status ~= 'full' then
                    attempts = attempts + 1
                end
                if status ~= 'full' and not done then
                    respondToPrompt(gui:FindFirstChild('ChoicePrompt'))
                end
            end

            if not done then
                continue
            end

            respondToPrompt(gui:FindFirstChild('ChoicePrompt'))

            aq.lootedChests[chest] = true
            results[#results + 1] = chest

            markStageTime()
        end

        return results
    end

    local runResourceReset = function(progressLabel)
        local player = noEffects.localPlayer.instance
        local dataSlot = tostring(player:GetAttribute('DataSlot') or noEffects.value('auto_ferryman_slot', 'A'))

        if player:GetAttribute('PalantirXFerrymanResourceResetJob') == game.JobId or noEffects.value('ferryman_resource_reset_slot') == dataSlot then
            error('resource reset already used for this character', 0)
        end

        aq.progress = progressLabel

        local resetOk, resetError = pcall(voidTeleport)

        if not resetOk or not resetError then
            error('character reset', 0)
        end

        player:SetAttribute('PalantirXFerrymanResourceResetJob', game.JobId)
        noEffects.setValue('ferryman_resource_reset_slot', dataSlot)

        local resetTimeout = tick() + 15

        while isRunActive() and tick() < resetTimeout do
            task.wait(0.1)
        end

        if isRunActive() then
            error('character reset timed out', 0)
        end
    end

    function ar.refillWater()
        local waterValue = noEffects.localPlayer.character:WaitForChild('Water', 10)

        if not waterValue then
            error('water', 0)
        end
        if waterValue.Value <= waterValue.MaxValue * 0.3 then
            local playerInstance = noEffects.localPlayer.instance
            local slotName = tostring(playerInstance:GetAttribute('DataSlot') or noEffects.value('auto_ferryman_slot', 'A'))

            if playerInstance:GetAttribute('PalantirXFerrymanResourceResetJob') ~= game.JobId and noEffects.value('ferryman_resource_reset_slot') ~= slotName then
                runResourceReset('Resetting character to refill thirst')

                return
            end
            if not placeIds.isEastern() then
                error('drinking spot unavailable', 0)
            end

            aq.progress = "Drinking at Miner's Landing"

            ar.safeTween(drinkingWater.cf, 170)

            local drinkTimeout = tick() + 30

            while isRunActive() and waterValue.Value < waterValue.MaxValue * 0.75 and tick() < drinkTimeout do
                local drinkingSpot = drinkingWater.find()

                if drinkingSpot then
                    pcall(delayedTask.call, ae, drinkingSpot.InteractPrompt)
                end

                task.wait(0.2)
            end

            if waterValue.Value < waterValue.MaxValue * 0.75 then
                error('water refill', 0)
            end
        end
    end

    local clickButton = function(button)
        if getconnections then
            for connIndex, connection in ipairs(getconnections(button.MouseButton1Click))do
                if connection.Enabled then
                    local fired = pcall(delayedTask.call, function()
                        connection:Fire()
                    end)

                    if fired then
                        return true
                    end
                end
            end
        end

        local center = button.AbsolutePosition + button.AbsoluteSize / 2 + game:GetService('GuiService'):GetGuiInset()

        virtualInputManager:SendMouseButtonEvent(center.X, center.Y, 0, true, game, 0)
        task.wait(0.08)
        virtualInputManager:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)

        return true
    end
    local findBuyButton = function(itemName)
        for guiIndex, screenGui in ipairs(noEffects.localPlayer.instance.PlayerGui:GetChildren())do
            if not screenGui:IsA('ScreenGui') or not screenGui.Enabled then
                continue
            end

            for descIndex, descendant in ipairs(screenGui:GetDescendants())do
                if descendant:IsA('GuiObject') and descendant.Name == itemName and descendant.Visible then
                    local titleLabel = descendant:FindFirstChild('Title', true)
                    local buyButton = descendant:FindFirstChild('Buy', true)

                    if titleLabel and titleLabel:IsA('TextLabel') and titleLabel.Text == itemName and buyButton and buyButton:IsA('GuiButton') and buyButton.Visible and buyButton.Active then
                        return screenGui, buyButton
                    end
                end
            end
        end
    end
    local exitDialogue = function()
        local requestsFolder = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
        local sendDialogue = requestsFolder and requestsFolder:FindFirstChild('SendDialogue')

        if not sendDialogue then
            return false
        end

        delayedTask.method(sendDialogue, 'FireServer', {exit = true})

        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local dialogueTimeout = tick() + 3

        repeat
            local dialogueGui = playerGui and playerGui:FindFirstChild('DialogueGui')

            if not dialogueGui or not dialogueGui.Enabled then
                return true
            end

            task.wait(0.1)
        until tick() >= dialogueTimeout or not isRunActive()

        return false
    end
    local buyFromBlacksmith = function(purchaseName)
        if findItem(purchaseName) then
            return
        end

        ar.safeTween(CFrame.new(-2803.5481, 144.320007, 3013.43604), 170)

        local blacksmith = workspace.NPCs:WaitForChild('Blacksmith', 10)
        local prompt = blacksmith and (blacksmith:FindFirstChild('InteractPrompt', true) or blacksmith:FindFirstChildWhichIsA('ProximityPrompt', true))

        if not prompt then
            error('blacksmith', 0)
        end

        ar.tween(blacksmith:GetPivot() * CFrame.new(0, 0, -4), 125)

        for attempt = 1, 3 do
            if findItem(purchaseName) then
                return
            end

            local shopGui, buyBtn = findBuyButton(purchaseName)
            local startTime = tick()

            if not buyBtn then
                delayedTask.call(ae, prompt)

                repeat
                    task.wait(0.1)

                    shopGui, buyBtn = findBuyButton(purchaseName)
                until buyBtn or tick() - startTime >= 10 or not isRunActive()
            end
            if not isRunActive() then
                error('cancelled', 0)
            end
            if buyBtn then
                clickButton(buyBtn)

                startTime = tick()

                repeat
                    task.wait(0.1)
                until findItem(purchaseName) or tick() - startTime >= 5 or not isRunActive()

                if not isRunActive() then
                    error('cancelled', 0)
                end
                if not findItem(purchaseName) and shopGui and shopGui.Parent then
                    for btnIndex, textButton in ipairs(shopGui:GetDescendants())do
                        if textButton:IsA('TextButton') and textButton.Visible and (textButton.Text:lower() == 'buy' or textButton.Text:lower() == 'purchase') then
                            clickButton(textButton)

                            break
                        end
                    end
                end

                startTime = tick()

                repeat
                    task.wait(0.1)
                until findItem(purchaseName) or tick() - startTime >= 5 or not isRunActive()
            end
        end

        if not findItem(purchaseName) then
            error(purchaseName .. ' purchase', 0)
        end
        if not exitDialogue() then
            error(purchaseName .. ' shop dialogue did not close', 0)
        end
    end

    function ar.buyAxe()
        return buyFromBlacksmith('Lumber Axe')
    end
    function ar.buyPickaxe()
        return buyFromBlacksmith('Pickaxe')
    end
    function ar.refill()
        local markerCframe = noEffects.services.ReplicatedStorage.MarkerWorkspace.AreaMarkers["Boatman's Watch"].AreaMarker.CFrame
        local refillPosition = CFrame.new(markerCframe.X, 8, markerCframe.Z)

        if countFlintUses() < 2 then
            runResourceReset('Resetting character to replenish flint')

            return
        end
        if countItem('Campfire Pit') < 4 then
            ar.safeTween(refillPosition, 170)
            task.wait(5)

            local hasEnoughFuel = function(targetCount)
                local fuelCount = countItem('Wood') + countItem('Campfire Pit')

                fuelCount = fuelCount + math.floor(countItem('Stick') / 3)

                return fuelCount >= targetCount
            end
            local stove = findNearestTree()

            if stove then
                ar.tween(stove:GetPivot(), 170)

                repeat
                    if not stove or stove.Parent == nil or (stove:GetAttribute('StructureHealth') or 0) <= 0 then
                        stove = findNearestTree()

                        if stove then
                            ar.tween(stove:GetPivot(), 170)
                        end
                    end
                    if stove then
                        ar.tween(stove:GetPivot(), 170)

                        local axe = ar.equipAxe()

                        if axe then
                            pcall(function()
                                delayedTask.method(axe, 'Activate')
                            end)
                        end
                    end

                    task.wait(0.5)
                until hasEnoughFuel(4) or not aq:armed()
            end

            ar.safeTween(refillPosition, 170)

            for index, material in ipairs({
                'Stick',
                'Wood',
            })do
                pcall(function()
                    if not isRunActive() or countItem(material) < (material == 'Stick' and 3 or 1) then
                        return
                    end

                    craftItem({[material] = true})

                    local playerGui = noEffects.localPlayer.instance.PlayerGui
                    local startTime = tick()
                    local startingCount = countItem('Campfire Pit')
                    local lastRemote, lastInvokedRemote, lastRemoteTime

                    repeat
                        task.wait()
                    until playerGui:FindFirstChild('ChoicePrompt') or tick() - startTime > 20 or not isRunActive()
                    repeat
                        if not isRunActive() then
                            return
                        end

                        local choicePrompt = playerGui:FindFirstChild('ChoicePrompt')

                        if not choicePrompt then
                            break
                        end

                        pcall(function()
                            local title = choicePrompt:FindFirstChild('Title', true)

                            if title and title.Text:find('Craft') and choicePrompt.Choice:IsA('RemoteEvent') and lastRemote ~= choicePrompt.Choice then
                                lastRemote = choicePrompt.Choice

                                delayedTask.method(choicePrompt.Choice, 'FireServer', 'Campfire Pit')
                            end
                        end)
                        pcall(function()
                            local slider = choicePrompt.ChoiceFrame.DescSheet.SliderSheet.GenericSlider

                            if not choicePrompt.Choice:IsA('RemoteFunction') or lastInvokedRemote == choicePrompt.Choice then
                                return
                            end

                            slider.Set:Fire(25)
                            task.wait(0.15)

                            if not isRunActive() then
                                return
                            end

                            local amount = tonumber(slider.Number.Text) or math.min(25, math.floor(countItem(material) / (material == 'Stick' and 3 or 1)))

                            lastInvokedRemote = choicePrompt.Choice
                            lastRemoteTime = tick()

                            delayedTask.method(choicePrompt.Choice, 'InvokeServer', math.max(1, amount))
                        end)
                        task.wait(0.1)

                        if countItem('Campfire Pit') > startingCount then
                            markStageTime()

                            break
                        end
                        if lastRemoteTime and tick() - lastRemoteTime >= 5 then
                            local prompt = playerGui:FindFirstChild('ChoicePrompt')
                            local exitButton = prompt and prompt:FindFirstChild('Exit', true)

                            if exitButton and exitButton:IsA('GuiButton') then
                                local fired = false

                                if getconnections then
                                    for connectionIndex, connection in ipairs(getconnections(exitButton.Activated))do
                                        if connection.Enabled then
                                            connection:Fire()

                                            fired = true

                                            break
                                        end
                                    end
                                end
                                if not fired and firesignal then
                                    pcall(firesignal, exitButton.MouseButton1Click, exitButton)
                                end
                                if not fired and not firesignal then
                                    pcall(exitButton.Activate, exitButton)
                                end
                            end

                            task.wait(0.5)

                            if playerGui:FindFirstChild('ChoicePrompt') == prompt and prompt:FindFirstChild('Choice') then
                                if prompt.Choice:IsA('RemoteEvent') then
                                    pcall(delayedTask.method, prompt.Choice, 'FireServer', 'EXIT')
                                elseif prompt.Choice:IsA('RemoteFunction') then
                                    pcall(delayedTask.method, prompt.Choice, 'InvokeServer', 'EXIT')
                                end
                            end

                            local timeout = tick() + 2

                            repeat
                                task.wait(0.1)
                            until playerGui:FindFirstChild('ChoicePrompt') ~= prompt or tick() >= timeout

                            break
                        end
                    until tick() - startTime >= 12
                end)
            end
        end
        if countFlintUses() < 2 or countItem('Campfire Pit') < 4 then
            error('materials', 0)
        end
    end
    function ar.createInstance()
        local findFlintRemote = function()
            for flintIndex, flintName in ipairs({
                'Flint',
                'Umbral Flint',
            })do
                local flint = findItem(flintName)
                local uses = flint and flint:FindFirstChild('Uses')
                local activateRemote = flint and flint:FindFirstChild('ActivateRt')

                if activateRemote and uses and uses.Value > 0 then
                    return activateRemote
                end
            end
        end
        local boatmanWatchCF = noEffects.services.ReplicatedStorage.MarkerWorkspace.AreaMarkers["Boatman's Watch"].AreaMarker.CFrame
        local root = getRootPart()

        if root and (root.Position - boatmanWatchCF.Position).Magnitude >= 700 then
            ar.safeTween(boatmanWatchCF, 250)
        end

        task.wait(1)

        if not workspace:FindFirstChild('MakeFires') then
            ar.tween(boatmanWatchCF, 250)

            local loadDeadline = tick() + 15

            repeat
                task.wait(0.1)
            until workspace:FindFirstChild('MakeFires') or not isRunActive() or tick() >= loadDeadline

            if not workspace:FindFirstChild('MakeFires') then
                error('Summoning area did not load', 0)
            end
        end

        repeat
            task.wait()
        until noEffects.localPlayer.character

        pcall(function()
            noEffects.localPlayer.character.CharacterHandler.Requests.DrawWeapon:FireServer(false)
        end)

        local spoofMouse = false
        local mouseCF

        shared.Palantir_FerrymanMouseSpoof = true

        aq:spawn(function()
            while task.wait(1 / 30) do
                if not spoofMouse or not mouseCF then
                    continue
                end

                local mouseBuffer = buffer.create(24)

                buffer.writef64(mouseBuffer, 0, mouseCF.X)
                buffer.writef64(mouseBuffer, 8, mouseCF.Y)
                buffer.writef64(mouseBuffer, 16, mouseCF.Z)

                local requestsFolder = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
                local updateMouseRemote = requestsFolder and requestsFolder:FindFirstChild('UpdateMouse')

                if updateMouseRemote then
                    updateMouseRemote:FireServer(mouseBuffer)
                end
            end
        end)
        task.wait(1.5)

        local campfires = workspace.MakeFires:GetChildren()
        local countNearbyCampfires = function()
            local destructibles = workspace:FindFirstChild('Destructibles')

            if not destructibles then
                return 0
            end

            local count = 0

            for destructibleIndex, destructible in ipairs(destructibles:GetChildren())do
                if destructible.Name:match('Campfire') then
                    local destructiblePos = (destructible:IsA('Model') and destructible:GetPivot() or destructible).Position

                    for campfireIndex, makeFire in ipairs(campfires)do
                        if (destructiblePos - makeFire.Position).Magnitude <= 200 then
                            count = count + 1

                            break
                        end
                    end
                end
            end

            return count
        end
        local hasCampfireNear = function(position, radius)
            local destructibleFolder = workspace:FindFirstChild('Destructibles')

            if not destructibleFolder then
                return false
            end

            for childIndex, candidate in ipairs(destructibleFolder:GetChildren())do
                if candidate.Name:match('Campfire') then
                    local candidatePos = (candidate:IsA('Model') and candidate:GetPivot() or candidate).Position

                    if (candidatePos - position).Magnitude <= radius then
                        return true
                    end
                end
            end

            return false
        end
        local getCampfirePit = function()
            local character = noEffects.localPlayer.character
            local campfirePit = character and character:FindFirstChild('Campfire Pit')

            if campfirePit then
                return campfirePit
            end

            local heldPit = getBackpack() and getBackpack():FindFirstChild('Campfire Pit')

            if not heldPit or not character then
                return nil
            end

            heldPit.Parent = character

            local startTick = tick()

            repeat
                task.wait()

                character = noEffects.localPlayer.character
            until (character and character:FindFirstChild('Campfire Pit')) or tick() - startTick >= 3

            return character and character:FindFirstChild('Campfire Pit')
        end
        local lightCampfire = function(campfire)
            local initialCount = countNearbyCampfires()

            for attempt = 1, 16 do
                spoofMouse = true
                mouseCF = campfire.MouseCF

                ar.tween(campfire.CFrame, 250)

                local rootPart = getRootPart()

                if rootPart then
                    rootPart.AssemblyLinearVelocity = Vector3.zero
                end

                task.wait(0.5)

                local pit = getCampfirePit()

                if not pit then
                    if not (getBackpack() and getBackpack():FindFirstChild('Campfire Pit')) then
                        spoofMouse = false
                        shared.Palantir_FerrymanMouseSpoof = nil

                        return false
                    end

                    continue
                end

                pcall(function()
                    pit:Activate()
                end)

                local litStartTick = tick()

                repeat
                    task.wait()
                until countNearbyCampfires() > initialCount or tick() - litStartTick >= 4 or not isRunActive()

                if countNearbyCampfires() > initialCount then
                    markStageTime()

                    return true
                end
            end

            spoofMouse = false
            shared.Palantir_FerrymanMouseSpoof = nil

            return false
        end
        local campfireSpots = {
            {
                MouseCF = CFrame.new(-4092.21118, 62.9762077, 9410.96094),
                CFrame = CFrame.new(-4091.36743, 65.8562164, 9406.87793),
            },
            {
                MouseCF = CFrame.new(-4108.79053, 62.763382, 9421.04004),
                CFrame = CFrame.new(-4109.85938, 65.8506699, 9417.92773),
            },
            {
                MouseCF = CFrame.new(-4096.95654, 62.7243958, 9440.11621),
                CFrame = CFrame.new(-4098.92334, 65.8594055, 9440.22363),
            },
            {
                MouseCF = CFrame.new(-4080.64844, 62.9762077, 9428.41309),
                CFrame = CFrame.new(-4078.77832, 65.7046738, 9424.35156),
            },
        }

        for spotIndex, spot in ipairs(campfireSpots)do
            if not hasCampfireNear(spot.CFrame.Position, 12) and not lightCampfire(spot) then
                error('campfire', 0)
            end
        end
        for checkIndex, campfireSpot in ipairs(campfireSpots)do
            if not hasCampfireNear(campfireSpot.CFrame.Position, 12) then
                error('campfire', 0)
            end
        end

        spoofMouse = false
        shared.Palantir_FerrymanMouseSpoof = nil

        local validateCampfires = function()
            if not isRunActive() then
                error('cancelled', 0)
            end
            if not placeIds.isEastern() then
                return false
            end

            for validateIndex, targetSpot in ipairs(campfireSpots)do
                if not hasCampfireNear(targetSpot.CFrame.Position, 12) then
                    error('Campfire disappeared; rebuilding campfires', 0)
                end
            end

            return true
        end
        local useFlint = function()
            if not validateCampfires() then
                return false
            end

            local flintRemote = findFlintRemote()

            if not flintRemote or countFlintUses() < 1 then
                error('Flint needs replenishing', 0)
            end

            delayedTask.method(flintRemote, 'FireServer')

            return true
        end

        for cycle = 1, 3 do
            if not validateCampfires() then
                return
            end

            aq.progress = 'Lighting Ferryman campfires'

            ar.tween(CFrame.new(-4103.17822, 65.7434998, 9413.24609), 200)
            task.wait(0.5)

            if not useFlint() then
                return
            end

            task.wait(3)

            if not validateCampfires() then
                return
            end

            ar.tween(CFrame.new(-4086.92041, 65.7434998, 9437.04395), 200)
            task.wait(0.5)

            if not useFlint() then
                return
            end

            task.wait(3)

            local timeoutTick = tick()

            repeat
                task.wait(0.5)

                if not validateCampfires() then
                    return
                end
            until not isRunActive() or not placeIds.isEastern() or tick() - timeoutTick >= 30

            if not isRunActive() or not placeIds.isEastern() then
                return
            end
        end

        error('Ferryman summoning timed out', 0)
    end

    local a_ = function()
        return isInFerrymanDungeon()
    end
    local interactWithNpc = function(npc, choices, awaitReply)
        ar.tween(npc.HumanoidRootPart.CFrame, 125)

        local playerGui = noEffects.localPlayer.instance.PlayerGui

        for interactAttempt = 1, 3 do
            delayedTask.call(ae, npc.InteractPrompt)
            task.wait(0.5)

            if playerGui:FindFirstChild('DialogueGui') and playerGui.DialogueGui.Enabled then
                for choiceIndex, choice in ipairs(choices)do
                    if awaitReply then
                        local replyReceived = false
                        local replyConnection = noEffects.services.ReplicatedStorage.Requests.SendDialogue.OnClientEvent:Connect(function(
                        )
                            replyReceived = true
                        end)

                        aq.connections[#aq.connections + 1] = replyConnection

                        for sendAttempt = 1, 3 do
                            aD(choice)

                            local waitStart = tick()

                            repeat
                                task.wait(0.1)
                            until replyReceived or (choice.exit and not playerGui.DialogueGui.Enabled) or tick() - waitStart >= 8 or not isRunActive()

                            if replyReceived or (choice.exit and not playerGui.DialogueGui.Enabled) or not isRunActive() then
                                break
                            end
                        end

                        replyConnection:Disconnect()

                        if not isRunActive() or not (replyReceived or (choice.exit and not playerGui.DialogueGui.Enabled)) then
                            error('dialogue', 0)
                        end

                        markStageTime()
                    else
                        aD(choice)
                        task.wait(0.5)
                    end
                end

                return true
            end
        end

        error('dialogue', 0)
    end
    local findFerryman = function()
        local liveFolder = workspace:FindFirstChild('Live')

        for liveIndex, candidate in ipairs(liveFolder and liveFolder:GetChildren() or {})do
            if candidate ~= noEffects.localPlayer.character and candidate.Name:lower():find('ferryman', 1, true) then
                return candidate
            end
        end
    end
    local recordFerrymanJob = function()
        if noEffects.value('ferryman_counted_job') == game.JobId then
            return
        end

        local dataStore = a["Utility/PersistentData"]()
        local persisted = dataStore.get('auto')

        persisted.ferryman_rounds = noEffects.value('ferryman_rounds', 0) + 1
        persisted.ferryman_counted_job = game.JobId

        dataStore.set('auto', persisted)
    end
    local markCycleReady = function()
        noEffects.setValue('miner_journey', nil)

        local persistStore = a["Utility/PersistentData"]()
        local persistedData = persistStore.get('auto')

        persistedData.ferryman_cycle_ready_round = tonumber(noEffects.value('ferryman_rounds')) or 0
        persistedData.ferryman_cycle_ready_id = (tonumber(persistedData.ferryman_cycle_ready_id) or 0) + 1

        persistStore.set('auto', persistedData)
    end

    function ar.kill()
        aq.progress = 'Waiting for Ferryman'

        if workspace.NPCs:FindFirstChild('The Ferryman, Defeated') then
            recordFerrymanJob()

            return
        end

        local ferryman = findFerryman()

        if not ferryman then
            interactWithNpc(workspace.NPCs['The Ferryman'], {
                {
                    choice = 'Who are you?',
                },
                {
                    choice = '[Tell him your name]',
                },
                {
                    choice = 'A wager?',
                },
                {
                    choice = 'Deal.',
                },
            })
        end

        local waitDeadline = tick()

        markStageTime()

        repeat
            ferryman = findFerryman()

            task.wait(0.1)
        until ferryman or tick() - waitDeadline >= 90

        if not ferryman then
            error('boss', 0)
        end

        aq.progress = 'Fighting Ferryman'
        aq.limit = 180

        markStageTime()

        local teleportAt = 0
        local spearAt = 0
        local ferrymanHumanoid = ferryman.Humanoid
        local lastHealth = ferrymanHumanoid.Health
        local healing = false
        local playerStatus = getEffectReplicator()
        local lastOffAt = 0
        local inPosition = false
        local healMoved = false
        local healHealth = 0

        noEffects.automation.ferryman_target = ferryman

        local animConnection = aq:connect(ferryman.Humanoid.Animator.AnimationPlayed, function(
            track
        )
            local animId = track.Animation.AnimationId

            if animId:find('5968282214', 1, true) or animId:find('5968288116', 1, true) then
                teleportAt = tick() + 1.5

                clickHolder.set(false)

                if animId:find('5968288116', 1, true) then
                    actionRunner.run(ferryman, a["Game/Timings/AnimationTiming"]().new({
                        _id = '5968288116',
                        name = 'FerrymanTeleport',
                        umoa = true,
                        smod = 'FerrymanTeleport',
                        ndfb = true,
                        after = 1,
                        fhb = false,
                        imxd = 1000,
                    }), {
                        kind = 'ferryman',
                        track = track,
                    })
                end
            elseif animId:find('8183996606', 1, true) then
                spearAt = tick() + 1

                aq:spawn(function()
                    task.wait(0.4)

                    if not isRunActive() or noEffects.automation.ferryman_target ~= ferryman then
                        return
                    end

                    local inZone = function(cframe, size, offset)
                        local playerRoot = getRootPart()
                        local localPos = playerRoot and (cframe * CFrame.new(0, 0, offset)):PointToObjectSpace(playerRoot.Position)

                        return localPos and math.abs(localPos.X) <= size.X / 2 and math.abs(localPos.Y) <= size.Y / 2 and math.abs(localPos.Z) <= size.Z / 2
                    end
                    local ferrymanRoot = ferryman:FindFirstChild('HumanoidRootPart')

                    if ferrymanRoot and inZone(ferrymanRoot.CFrame, Vector3.new(15, 20, 30), -15) then
                        a["Game/CharacterActions"]().dodge(true)

                        return
                    end
                    if ferrymanRoot and inZone(ferrymanRoot.CFrame, Vector3.new(15, 20, 35), -10) then
                        return
                    end

                    local watchStart = tick()
                    local spearSeen = false

                    repeat
                        spearSeen = false

                        local thrownFolder = workspace:FindFirstChild('Thrown')

                        for throwIndex, thrown in ipairs(thrownFolder and thrownFolder:GetChildren() or {})do
                            if thrown.Name == 'SpearPart' and thrown:IsA('BasePart') then
                                spearSeen = true

                                if inZone(thrown.CFrame, Vector3.new(10, 10, 80), 
-40) then
                                    a["Game/CharacterActions"]().dodge(true)

                                    return
                                end
                            end
                        end

                        task.wait()
                    until not isRunActive() or noEffects.automation.ferryman_target ~= ferryman or tick() - watchStart >= 5 or (tick() - watchStart >= 1 and not spearSeen)
                end)
            end
        end)

        ar.readyWeapon()

        while isRunActive() and ferryman.Parent and ferrymanHumanoid.Health > 0 do
            local playerHumanoid = noEffects.localPlayer.humanoid
            local playerRootPart = getRootPart()
            local ferrymanRootPart = ferryman:FindFirstChild('HumanoidRootPart')

            if not playerHumanoid or playerHumanoid.Health <= 0 or not ferrymanRootPart then
                error('character', 0)
            end
            if ferryman.Humanoid.Health < lastHealth then
                lastHealth = ferryman.Humanoid.Health

                markStageTime()
            end
            if playerHumanoid.Health <= playerHumanoid.MaxHealth * 0.35 then
                healing = true
            end
            if healing and playerHumanoid.Health >= playerHumanoid.MaxHealth * 0.85 then
                healing = false
                healMoved = false

                stopTween()
                markStageTime()
            end
            if healing then
                aq.progress = 'Healing'

                if playerHumanoid.Health > healHealth then
                    markStageTime()
                end

                healHealth = playerHumanoid.Health

                clickHolder.set(false)

                noEffects.automation.requesting_mob_ai_breaker_stop = true

                if not healMoved then
                    ar.tween(CFrame.new(-3799, 8, 7788), 125)

                    healMoved = true
                end
            elseif tick() < teleportAt or tick() < spearAt or (playerStatus and (playerStatus:FindEffect('Knocked') or playerStatus:FindEffect('Ragdoll'))) then
                stopTween()
                clickHolder.set(false)

                noEffects.automation.requesting_mob_ai_breaker_stop = true

                if tick() < spearAt and math.abs(playerRootPart.Position.Y) > 1 then
                    ar.tween(CFrame.new(playerRootPart.Position.X, 8, playerRootPart.Position.Z), 125)
                end
            else
                aq.progress = 'Fighting Ferryman'

                local targetPos = ferrymanRootPart.CFrame * CFrame.new(0, -7, 4)
                local torso = ferryman:FindFirstChild('Torso')
                local torsoVisible = torso and torso.Transparency < 1
                local arrived = false

                if torsoVisible and (playerRootPart.Position - targetPos.Position).Magnitude > 30 then
                    noEffects.automation.requesting_mob_ai_breaker_stop = true

                    clickHolder.set(false)

                    if not aq.tween or aq.tween.status() then
                        stopTween()

                        aq.tween = travelRecovery.new(function()
                            return ferrymanRootPart.Parent and ferrymanRootPart.CFrame * CFrame.new(0, 
-7, 4) or playerRootPart.CFrame
                        end, true, 400)
                    end
                else
                    stopTween()

                    if torsoVisible then
                        playerRootPart.AssemblyLinearVelocity = Vector3.zero
                        playerRootPart.CFrame = CFrame.lookAt(targetPos.Position, ferrymanRootPart.Position)
                        arrived = true
                    end

                    clickHolder.set(torsoVisible == true)

                    if not arrived then
                        lastOffAt = tick()
                    end
                    if arrived or (ferrymanRootPart.Position - Vector3.new(-4095.33, 68.5, 9425.35)).Magnitude > 13.5 then
                        inPosition = true
                    end

                    noEffects.automation.requesting_mob_ai_breaker_stop = not inPosition or (not arrived and tick() - lastOffAt >= 0.2)

                    if arrived and not noEffects.automation.requesting_mob_ai_breaker_stop then
                        trainFerrymanMantra()
                    end
                end
            end

            task.wait()
        end

        animConnection:Disconnect()
        stopTween()
        clickHolder.set(false)

        noEffects.automation.requesting_mob_ai_breaker_stop = true

        if not isRunActive() then
            error('cancelled', 0)
        end
        if ferrymanHumanoid.Health > 0 and not workspace.NPCs:FindFirstChild('The Ferryman, Defeated') then
            error('boss lost', 0)
        end

        recordFerrymanJob()
    end
    function ar.loot()
        local chests = {}

        while isRunActive() do
            local thrownFolder = workspace:FindFirstChild('Thrown')
            local hasLoot = false

            for descIndex, descendant in ipairs(thrownFolder and thrownFolder:GetDescendants() or {})do
                if descendant.Name == 'Lid' and descendant:IsA('BasePart') and not (aq.lootedChests and aq.lootedChests[descendant.Parent]) then
                    hasLoot = true

                    break
                end
            end

            if hasLoot then
                for chestIndex, chest in ipairs(ar.grabChests())do
                    if not table.find(chests, chest) then
                        table.insert(chests, chest)
                    end
                end
            end

            for pickupChest in pairs(aq.chestPickups or {})do
                if not pickupChest.Parent and not table.find(chests, pickupChest) then
                    aq.lootedChests[pickupChest] = true
                    chests[#chests + 1] = pickupChest
                end
            end

            if #chests >= 3 then
                return
            end

            task.wait(0.2)
        end
    end
    function ar.rewards()
        interactWithNpc(workspace.NPCs['The Ferryman, Defeated'], {
            {
                choice = 'Who are you?',
            },
            {exit = true},
        }, true)

        local lastLootTick = tick()

        repeat
            local thrownRoot = workspace:FindFirstChild('Thrown')

            for descIdx, descendantLid in ipairs(thrownRoot and thrownRoot:GetDescendants() or {})do
                if descendantLid.Name == 'Lid' and descendantLid:IsA('BasePart') and not (aq.lootedChests and aq.lootedChests[descendantLid.Parent]) then
                    lastLootTick = tick()

                    ar.grabChests()

                    break
                end
            end

            task.wait(0.2)
        until tick() - lastLootTick >= 30 or not isRunActive()
    end
    function ar.leave()
        for leaveAttempt = 1, 8 do
            ar.tween(workspace.Ferryman.FerrymanExit.CFrame, 125)
            firetouchinterest(getRootPart(), workspace.Ferryman.FerrymanExit, 0)
            firetouchinterest(getRootPart(), workspace.Ferryman.FerrymanExit, 1)
            task.wait(3)
        end

        error('exit', 0)
    end

    local ferryRouteCframe = CFrame.new(-2763.25928, 152.919952, 3038.83789, -0.573599219, 0, 0.81913656, 0, 1, 0, 
-0.81913656, 0, -0.573599219)
    local ferryRouteCoordinate = Vector2.new(-4096, 9424)
    local getReplicatedData = function()
        local infoFolder = noEffects.services.ReplicatedStorage:FindFirstChild('Info')
        local dataReplication = infoFolder and infoFolder:FindFirstChild('DataReplication')

        if not dataReplication then
            return
        end

        local success, data = pcall(function()
            return require(dataReplication).data
        end)

        return success and type(data) == 'table' and data or nil
    end
    local selectDialogueChoice = function(choiceId)
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local dialogueGui = playerGui and playerGui:FindFirstChild('DialogueGui')

        if not dialogueGui or not dialogueGui.Enabled then
            return false
        end

        local dialogueExtents = dialogueGui:FindFirstChild('DialogueExtents')
        local dialogueFrame = dialogueExtents and dialogueExtents:FindFirstChild('DialogueFrame')
        local dialogueContainer = dialogueFrame and dialogueFrame:FindFirstChild('DialogueContainer')
        local choiceSheet = dialogueContainer and dialogueContainer:FindFirstChild('ChoiceSheet')
        local choiceScroll = choiceSheet and choiceSheet:FindFirstChild('ChoiceScroll')

        for choiceIndex, choice in ipairs(choiceScroll and choiceScroll:GetChildren() or {})do
            if choice:GetAttribute('ChoiceID') == choiceId then
                return true
            end
        end

        return false
    end
    local exitInnDialogue = function()
        if not aq.innDialogue then
            return
        end

        aq.innDialogue = nil

        local requestsFolder = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
        local sendDialogue = requestsFolder and requestsFolder:FindFirstChild('SendDialogue')

        if sendDialogue then
            pcall(sendDialogue.FireServer, sendDialogue, {exit = true})

            local dialoguePlayerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
            local dialogueGuiNode = dialoguePlayerGui and dialoguePlayerGui:FindFirstChild('DialogueGui')
            local closeDeadline = os.clock() + 2

            while dialogueGuiNode and dialogueGuiNode.Enabled and os.clock() < closeDeadline do
                task.wait(0.1)
            end
        end
    end
    local startFerrymanJourney = function()
        if not isRunActive() or not getRootPart() or not placeIds.isEastern() or isInFerrymanDungeon() then
            return false, 'not ready'
        end
        if ar.playerNear() then
            return false, 'players nearby'
        end

        local dataSlot = tostring(noEffects.localPlayer.instance:GetAttribute('DataSlot') or '')
        local minerJourney = noEffects.value('miner_journey')

        if type(minerJourney) ~= 'table' or minerJourney.slot ~= dataSlot or minerJourney.destination ~= 'Ferryman' then
            minerJourney = {
                slot = dataSlot,
                destination = 'Ferryman',
                job = game.JobId,
                state = 'evaluate',
            }
        end

        local setMinerState = function(state)
            minerJourney.state = state
            minerJourney.job = game.JobId

            noEffects.setValue('miner_journey', minerJourney)
            executionQueue.progress(aq, 'Miner inn: ' .. state)
        end

        if minerJourney.state == 'respawn_requested' or minerJourney.state == 'await_character' then
            local character = noEffects.localPlayer.instance.Character

            if character and minerJourney.requestId and character:GetAttribute('PalantirXInnRequest') == minerJourney.requestId then
                if os.time() - (minerJourney.requestedAt or 0) < 15 then
                    aq.progress = 'Waiting for requested inn respawn'

                    task.wait(1)

                    return false, 'inn transition pending'
                end

                setMinerState('continue_direct')

                return false, 'Miner reset already used in this server'
            end

            local backpack = getBackpack()

            if not backpack or not noEffects.services.CollectionService:HasTag(backpack, 'Loaded') then
                aq.progress = 'Waiting for backpack after inn respawn'

                return false, 'inn transition pending'
            end

            local nearFerryRoute = (Vector2.new(getRootPart().Position.X, getRootPart().Position.Z) - Vector2.new(ferryRouteCframe.Position.X, ferryRouteCframe.Position.Z)).Magnitude < 350

            setMinerState(nearFerryRoute and 'arrival_confirmed' or 'continue_direct')
        end
        if minerJourney.state == 'arrival_confirmed' or minerJourney.state == 'continue_direct' then
            return false, 'Miner reset already used in this server'
        end

        local characterPosition = getRootPart().Position
        local nearFerry = (Vector2.new(characterPosition.X, characterPosition.Z) - Vector2.new(ferryRouteCframe.Position.X, ferryRouteCframe.Position.Z)).Magnitude < 350

        if (Vector2.new(characterPosition.X, characterPosition.Z) - ferryRouteCoordinate).Magnitude < 2000 then
            return false, 'already near Ferryman'
        end

        local innData = getReplicatedData()

        for dataAttempt = 1, 3 do
            if innData and type(innData.SpawnLocation) == 'table' then
                break
            end

            aq.progress = 'Waiting for replicated inn data'

            task.wait(1)

            if not isRunActive() then
                return false, 'not ready'
            end

            innData = getReplicatedData()
        end

        if not innData or type(innData.SpawnLocation) ~= 'table' then
            setMinerState('continue_direct')

            return false, 'Miner reset already used in this server'
        end

        local spawnLocation = innData.SpawnLocation
        local isMinerInn = type(spawnLocation) == 'table' and spawnLocation.EtreanLuminant == 'Miner'

        if isMinerInn and (nearFerry or minerJourney.state == 'booking' or minerJourney.state == 'verify_booking') then
            setMinerState('arrival_confirmed')
            exitInnDialogue()

            return true
        end
        if not isMinerInn and (tonumber(innData.Notes) or 0) < 5 then
            aq.progress = 'Farming Notes for Miner\u{2019}s Landing inn'

            local fundsSuccess, fundsError = progressionTraining.ensureTrainingFunds(isRunActive, function()
                return ar.playerNear()
            end, nil, 5)

            if not fundsSuccess then
                error('inn notes: ' .. tostring(fundsError), 0)
            end

            innData = getReplicatedData()

            if not innData or (tonumber(innData.Notes) or 0) < 5 then
                error('inn notes unconfirmed', 0)
            end
        end

        aq.fastTraveling = true

        local finish = function(result)
            exitInnDialogue()

            aq.fastTraveling = false

            return result
        end

        if not isMinerInn then
            minerJourney.attempts = (tonumber(minerJourney.attempts) or 0) + 1

            if minerJourney.attempts > 3 then
                setMinerState('continue_direct')

                return finish(false), 'Miner reset already used in this server'
            end

            setMinerState('booking')

            aq.progress = 'Booking Miner\u{2019}s Landing inn'

            local sendDialogueChoice = function(dialogueChoice)
                local dialogueRequests = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
                local dialogueRemote = dialogueRequests and dialogueRequests:FindFirstChild('SendDialogue')

                if not dialogueRemote then
                    return false
                end

                return pcall(dialogueRemote.FireServer, dialogueRemote, dialogueChoice)
            end
            local streamThrottle = 0
            local streamAround = function()
                if os.clock() < streamThrottle then
                    return
                end

                streamThrottle = os.clock() + 0.25

                task.spawn(function()
                    pcall(noEffects.localPlayer.instance.RequestStreamAroundAsync, noEffects.localPlayer.instance, ferryRouteCframe.Position, 2)
                end)
            end

            streamAround()
            ar.safeTween(ferryRouteCframe * CFrame.new(0, 0, -4), 125)

            local innkeeper
            local innkeeperDeadline = os.clock() + 6

            while isRunActive() and os.clock() < innkeeperDeadline do
                local npcs = workspace:FindFirstChild('NPCs')

                for npcIndex, npc in ipairs(npcs and npcs:GetChildren() or {})do
                    local spawnRef = npc:FindFirstChild('SpawnRef')

                    if npc.Name == 'Innkeep' and spawnRef and spawnRef.Value == 'Miner' then
                        innkeeper = npc

                        break
                    end
                end

                if innkeeper then
                    break
                end

                streamAround()
                task.wait(0.1)
            end

            if not innkeeper or not isRunActive() then
                return finish(false), 'Miner innkeeper unavailable'
            end

            ar.safeTween(innkeeper:GetPivot() * CFrame.new(0, 0, -4), 125)

            local dialogueDeadline = os.clock() + 4
            local interactThrottle = 0

            while isRunActive() and os.clock() < dialogueDeadline and not selectDialogueChoice('How much is it to stay here?') and not selectDialogueChoice('Alright, book me in.') do
                local interactPrompt = innkeeper:FindFirstChild('InteractPrompt')

                if interactPrompt and os.clock() >= interactThrottle then
                    interactThrottle = os.clock() + 1
                    aq.innDialogue = true

                    pcall(ae, interactPrompt)
                end

                task.wait()
            end

            aq.innDialogue = true

            if not selectDialogueChoice('Alright, book me in.') then
                if not selectDialogueChoice('How much is it to stay here?') then
                    return finish(false), 'Miner inn dialogue unavailable'
                end
                if not sendDialogueChoice({
                    choice = 'How much is it to stay here?',
                }) then
                    return finish(false), 'Miner dialogue remote unavailable'
                end
            end

            local bookingDeadline = os.clock() + 3

            repeat
                task.wait()
            until selectDialogueChoice('Alright, book me in.') or not isRunActive() or os.clock() >= bookingDeadline

            if not selectDialogueChoice('Alright, book me in.') then
                return finish(false), 'Miner booking choice unavailable'
            end

            setMinerState('verify_booking')

            if not sendDialogueChoice({
                choice = 'Alright, book me in.',
            }) then
                return finish(false), 'Miner booking remote unavailable'
            end

            local confirmDeadline = os.clock() + 5

            repeat
                task.wait(0.2)

                innData = getReplicatedData()
                spawnLocation = innData and innData.SpawnLocation
                isMinerInn = type(spawnLocation) == 'table' and spawnLocation.EtreanLuminant == 'Miner'
            until isMinerInn or not isRunActive() or os.clock() >= confirmDeadline

            if not isMinerInn then
                return finish(false), 'Miner booking was not confirmed'
            end

            setMinerState('arrival_confirmed')

            return finish(true)
        end
        if not isRunActive() then
            return finish(false)
        end

        aq.progress = 'Respawning at Miner\u{2019}s Landing'

        local characterDistance = (Vector2.new(characterPosition.X, characterPosition.Z) - ferryRouteCoordinate).Magnitude
        local ferryDistance = (Vector2.new(ferryRouteCframe.Position.X, ferryRouteCframe.Position.Z) - ferryRouteCoordinate).Magnitude

        if characterDistance - ferryDistance < 1000 then
            setMinerState('continue_direct')

            return finish(true)
        end

        minerJourney.requestId = noEffects.services.HttpService:GenerateGUID(false)
        minerJourney.requestedAt = os.time()

        noEffects.localPlayer.instance.Character:SetAttribute('PalantirXInnRequest', minerJourney.requestId)
        setMinerState('respawn_requested')

        local teleportSuccess, teleportResult = pcall(voidTeleport)

        if not teleportSuccess or not teleportResult then
            setMinerState('continue_direct')

            return finish(false), 'Miner reset already used in this server'
        end

        setMinerState('await_character')

        local respawnStart = os.clock()

        while isRunActive() and noEffects.localPlayer.humanoid and noEffects.localPlayer.humanoid.Health > 0 do
            if os.clock() - respawnStart >= 15 then
                setMinerState('continue_direct')

                break
            end

            task.wait(0.1)
        end

        return finish(true)
    end
    local executeStage = function(stage, timeout, action)
        executionQueue.checkpoint(aq, false, stage)

        aq.progress = stage
        aq.limit = timeout

        markStageTime()

        local finished = false
        local succeeded = false
        local errorMsg
        local deadline = tick() + math.max(300, timeout * 3)

        aq:spawn(function()
            succeeded, errorMsg = pcall(action)
            finished = true
        end)

        local lastMaterials

        while isRunActive() and not finished do
            task.wait(0.1)

            if aq.travelling or aq.travelGoal or (aq.tween and not aq.tween.status()) then
                aq.stageAt = tick()
                deadline = tick() + math.max(300, timeout * 3)
            end
            if (a_() and #noEffects.services.Players:GetPlayers() > 1) or (not a_() and not aq.fastTraveling and ar.playerNear()) then
                aq.hopRequested = true

                break
            end
            if stage == 'Gathering materials' then
                local materialKey = table.concat({
                    countItem('Wood'),
                    countItem('Stick'),
                    countItem('Campfire Pit'),
                    countFlintUses(),
                    countItem('Coal'),
                    countItem('Rock'),
                    countItem('Umbral Obsidian'),
                }, ':')

                if lastMaterials ~= materialKey then
                    lastMaterials = materialKey

                    markStageTime()
                end
            end
            if aq.tweenGoal and getRootPart() then
                local distance = (getRootPart().Position - aq.tweenGoal.Position).Magnitude

                if aq.tweenDistance - distance >= 1 then
                    aq.tweenDistance = distance

                    markStageTime()
                end
            end
            if aq.paused then
                markStageTime()
            end
            if tick() - aq.stageAt >= aq.limit or (stage ~= 'Waiting for Ferryman' and tick() >= deadline) then
                errorMsg = stage .. ' timed out'

                break
            end
        end

        for threadIndex = #aq.threads, 1, -1 do
            if aq.threads[threadIndex] ~= coroutine.running() and aq.threads[threadIndex] ~= aq.movementThread then
                pcall(task.cancel, aq.threads[threadIndex])
                table.remove(aq.threads, threadIndex)
            end
        end
        for connIndex = #aq.connections, 1, -1 do
            aq.connections[connIndex]:Disconnect()
            table.remove(aq.connections, connIndex)
        end

        cancelFerrymanTarget()
        stopTween()
        clearTravelPath()
        exitInnDialogue()

        aq.fastTraveling = false

        clickHolder.set(false)

        aq.paused = false
        noEffects.automation.requesting_mob_ai_breaker_stop = true

        executionQueue.checkpoint(aq, true, stage)
        task.wait(0.1)

        if isRunActive() and finished and succeeded and not aq.hopRequested then
            if aq.failedStage == stage then
                aq.failedStage = nil
                aq.failedCount = nil
            end

            return true
        end
        if aq.failedStage == stage then
            aq.failedCount = (aq.failedCount or 0) + 1
        else
            aq.failedStage = stage
            aq.failedCount = 1
        end
        if isRunActive() and not aq.hopRequested then
            aq.progress = 'Retrying ' .. stage:lower() .. ': ' .. tostring(errorMsg or 'interrupted')
        end

        return false
    end
    local hasFerrymanGear = function()
        return (findItem('Lumber Axe') or countItem('Campfire Pit') >= 4) and (findItem('Pickaxe') or countFlintUses() >= 2)
    end

    function ar.run()
        aq.runId = aq.generation
        aq.character = noEffects.localPlayer.character
        aq.hopping = false
        aq.hopRequested = false
        aq.fastTraveling = false
        aq.failedStage = nil
        aq.failedCount = nil
        aq.lootedChests = {}
        aq.chestPickups = {}
        aq.nextMantra = 0
        aq.mantraIndex = 0
        aq.combatCalmAt = nil
        noEffects.automation.ferryman = true
        noEffects.automation.requesting_mob_ai_breaker_stop = true

        if type(noEffects.value('ferryman_rounds')) ~= 'number' then
            noEffects.setValue('ferryman_rounds', 0)
        end

        local dataSlot = noEffects.localPlayer.instance:GetAttribute('DataSlot')

        if dataSlot then
            noEffects.setValue('auto_ferryman_slot', dataSlot)
        end

        while isRunActive() do
            aq.hopRequested = false

            while isRunActive() and (placeIds.isDepths() or (not a_() and not hasFerrymanGear() and (findItem('Lumber Axe') or countItem('Campfire Pit') >= 4)) or itemFilters.full()) do
                aq.progress = placeIds.isDepths() and 'Waiting to leave the Depths' or (itemFilters.full() and 'Inventory full' or 'Waiting for equipment')

                if not placeIds.isDepths() and ((a_() and #noEffects.services.Players:GetPlayers() > 1) or (not a_() and ar.playerNear())) then
                    return ar.recover()
                end

                task.wait(0.5)
            end

            if not isRunActive() then
                return
            end

            local ok = true

            if not a_() then
                ok = executeStage('Travelling to Ferryman', math.huge, function()
                    if placeIds.isEtrean() then
                        aq.travelling = true

                        local transferred = regionTransfer.toEastern(nil, isRunActive)

                        aq.travelling = false

                        if not transferred then
                            error('travel', 0)
                        end
                    end
                    if not placeIds.isEastern() then
                        error('region', 0)
                    end

                    local success, status = startFerrymanJourney()

                    while status == 'inn transition pending' and isRunActive() do
                        task.wait(0.5)

                        success, status = startFerrymanJourney()
                    end

                    if not success and status ~= 'already at Miner' and status ~= 'already near Ferryman' and status ~= 'Miner reset already used in this server' then
                        error('Miner fast travel: ' .. tostring(status), 0)
                    end
                end)

                if ok and not findItem('Lumber Axe') and countItem('Campfire Pit') < 4 then
                    ok = executeStage('Buying Lumber Axe', 120, ar.buyAxe)
                end
                if ok and not findItem('Pickaxe') then
                    ok = executeStage('Buying Pickaxe', 120, ar.buyPickaxe)
                end
                if ok and countFlintUses() < 2 then
                    ok = executeStage('Resetting for flint', 30, function()
                        runResourceReset('Resetting character to replenish flint')
                    end)
                end
                if ok and not hasFerrymanGear() then
                    aq.progress = 'Waiting for equipment'

                    task.wait(0.5)

                    continue
                end
                if ok then
                    ok = executeStage('Refilling water', 120, ar.refillWater)
                end
                if ok then
                    ok = executeStage('Gathering materials', 300, ar.refill)
                end
                if ok then
                    ok = executeStage('Summoning Ferryman', 180, ar.createInstance)
                end
            else
                if noEffects.value('ferryman_counted_job') ~= game.JobId then
                    ok = executeStage('Waiting for Ferryman', 90, ar.kill)
                end
                if ok then
                    ok = executeStage('Collecting loot', 120, ar.loot)
                end
                if ok then
                    ok = executeStage('Claiming Ferryman rewards', 90, ar.rewards)
                end
                if ok then
                    markCycleReady()

                    ok = executeStage('Leaving the instance', 90, ar.leave)
                end
            end
            if not ok then
                if aq.hopRequested or (aq.failedCount or 0) >= 3 then
                    return ar.recover()
                end

                task.wait(2)
            else
                task.wait(1)
            end
        end
    end
    function ar.recover()
        shared.Palantir_FerrymanMouseSpoof = nil

        if not isRunActive() or aq.hopping then
            return
        end

        aq.hopping = true
        aq.progress = 'Finding another server'

        for threadIndex = #aq.threads, 1, -1 do
            if aq.threads[threadIndex] ~= coroutine.running() and aq.threads[threadIndex] ~= aq.movementThread then
                pcall(task.cancel, aq.threads[threadIndex])
                table.remove(aq.threads, threadIndex)
            end
        end

        for connectionIndex, connection in ipairs(aq.connections)do
            connection:Disconnect()
        end

        table.clear(aq.connections)
        cancelFerrymanTarget()
        stopTween()
        clearTravelPath()
        clickHolder.set(false)

        aq.paused = false
        noEffects.automation.requesting_mob_ai_breaker_stop = true

        stopTravel()
        noEffects.hop(noEffects.value('auto_ferryman_slot', 'A'), true)
    end

    aq = automationStep.construct({
        id = 'auto_ferryman',
        restoreFeatures = true,
        notAllowed = function()
            return placeIds.isDepths()
        end,
        features = {
            'NoFallDamage',
            'NoClip',
            'NoKillBricks',
            'PathfindBreaker',
            'NoFire',
            'AutoWisp',
            'AutoDeclineGuild',
            'AutoDeclineSquad',
            'EnableAutoParry',
        },
        onRun = function()
            local success = pcall(ar.run)

            shared.Palantir_FerrymanMouseSpoof = nil

            if not success then
                ar.recover()
            end
        end,
        onStop = function()
            shared.Palantir_FerrymanMouseSpoof = nil

