            clearTravelPath()
            clickHolder.detach()
            stopTravel()
            a["Game/ServerHop"]().detach()

            noEffects.automation.ferryman = false
            noEffects.automation.requesting_mob_ai_breaker_stop = false
        end,
    })

    return aq
end


return aa()

]=],
    ["Features/Automation/InteligenceFarm"] = [=[
local aa = function()
    local module = {}
    local attributes = a["Utility/Attributes"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local signal = a["Utility/Signal"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local renderStepped = signal.new(runService.RenderStepped)
    local maidInstance = maid.new()
    local aj, al
    local counter = 0
    local farmIntelligence = function()
        local autoToggle = Toggles['AutoIntelligence']

        if not autoToggle or not autoToggle.Value then
            return
        end

        local intelCapOption = Options['IntelligenceCap']

        if not intelCapOption then
            return
        end

        local player = players.LocalPlayer
        local character = player.Character

        if not character then
            return
        end
        if not attributes.isNotAtCap(character, 'Stat_Intelligence', intelCapOption.Value) then
            logger.warnNotify('Intel farm auto-stopped.')

            return autoToggle:SetValue(false)
        end

        local humanoid = character:FindFirstChild('Humanoid')

        if not humanoid then
            return
        end

        local backpack = player:FindFirstChild('Backpack')

        if not backpack then
            return
        end

        local textbookInChar = character:FindFirstChild('Math Textbook')
        local textbookInBackpack = backpack:FindFirstChild('Math Textbook')

        if not textbookInChar and textbookInBackpack then
            return humanoid:EquipTool(textbookInBackpack)
        end

        local choicePrompt = player.PlayerGui:FindFirstChild('ChoicePrompt')

        if not choicePrompt then
            aj, al = nil, nil

            if textbookInChar and os.clock() - counter >= 0.1 then
                counter = os.clock()

                return textbookInChar:Activate()
            end

            return
        end

        local choiceButton = choicePrompt:FindFirstChild('Choice')

        if not choiceButton then
            return
        end

        local choiceFrame = choicePrompt:FindFirstChild('ChoiceFrame')

        if not choiceFrame then
            return
        end

        local descSheet = choiceFrame:FindFirstChild('DescSheet')
        local desc = descSheet and descSheet:FindFirstChild('Desc')

        if not desc then
            return
        end

        local optionsFrame = choiceFrame:FindFirstChild('Options')

        if not optionsFrame then
            return
        end

        local promptText = tostring(desc.Text)

        if choicePrompt == aj and promptText == al then
            return
        end

        local cleanedText = promptText:gsub('What is', ''):gsub(' ', ''):gsub('?', ''):gsub('by', '')
        local operator

        if cleanedText:match('divided') then
            operator = 'divided'
        end
        if cleanedText:match('times') then
            operator = 'times'
        end
        if cleanedText:match('plus') then
            operator = 'plus'
        end
        if cleanedText:match('minus') then
            operator = 'minus'
        end
        if not operator then
            return
        end

        local parts = cleanedText:split(operator)
        local left = tonumber(parts[1] or '')
        local right = tonumber(parts[2] or '')

        if not left or not right then
            return
        end

        local answer

        if operator == 'divided' then
            if right == 0 then
                return
            end

            answer = left / right
            answer = math.round(answer * 100) / 100
        end
        if operator == 'times' then
            answer = left * right
        end
        if operator == 'plus' then
            answer = left + right
        end
        if operator == 'minus' then
            answer = left - right
        end
        if not answer or answer ~= answer then
            return
        end

        local chosenName

        for index, child in ipairs(optionsFrame:GetChildren())do
            if child:IsA('TextButton') and child.Visible then
                local numValue = tonumber(child.Name)

                if numValue and math.abs(numValue - answer) < 1e-6 then
                    chosenName = child.Name

                    break
                end
            end
        end

        if not chosenName then
            return
        end

        aj, al = choicePrompt, promptText

        choiceButton:FireServer(chosenName)
    end

    function module.init()
        maidInstance:add(renderStepped:connect('AttributeFarmIntelligence_OnPreRender', farmIntelligence))
    end
    function module.detach()
        maidInstance:clean()

        aj, al = nil, nil
        counter = 0
    end

    do
        local feature = a["Features/Feature"]()
        local autoIntelligence = feature.new('AutoIntelligence')

        function autoIntelligence:onEnable()
            module.init()
        end
        function autoIntelligence:onDisable()
            module.detach()
        end
    end

    return module
end


return aa()

]=],
    ["Features/Automation/KaidoFarm"] = [=[
local aa = function()
    local executionQueue = a["Features/Automation/ExecutionQueue"]()
    local noEffects = a["Features/Game/NoEffects"]()
    local placeIds = a["Game/PlaceIds"]()
    local travelRecovery = a["Features/Game/TravelRecovery"]()
    local clickHolder = a["Features/Combat/ClickHolder"]()
    local automationStep = a["Features/Automation/AutomationStep"]()
    local itemFilters = a["Game/Items/ItemFilters"]()
    local executorInfo = a["Utility/ExecutorInfo"]()
    local delayedTask = a["Utility/DelayedTask"]()
    local aj
    local ak
    local al = {
        CFrame.new(-4600, -1, 12000),
        CFrame.new(-4600, -1, 14500),
    }
    local am = 4
    local getRootPart = function()
        return noEffects.localPlayer.root_part
    end
    local findArdourManifestation = function()
        local character = noEffects.localPlayer.character
        local backpack = noEffects.localPlayer.instance:FindFirstChild('Backpack')

        return character and character:FindFirstChild('Ardour Manifestation') or backpack and backpack:FindFirstChild('Ardour Manifestation')
    end
    local findKaido = function()
        local liveFolder = workspace:FindFirstChild('Live')

        for index, child in ipairs(liveFolder and liveFolder:GetChildren() or {})do
            local nameLower = child.Name:lower()

            if nameLower:find('dreadserpent', 1, true) or nameLower:find('dread serpent', 1, true) or nameLower:find('kaido', 1, true) then
                local humanoid = child:FindFirstChildOfClass('Humanoid')

                if humanoid and humanoid.Health > 0 then
                    return child, humanoid
                end
            end
        end
    end
    local getItems = function()
        local items = table.clone(noEffects.value('auto_kaido_items', {}))
        local selected = noEffects.value('auto_kaido_selected', {})

        for key, value in pairs(selected)do
            if value and not table.find(items, key) then
                items[#items + 1] = key
            end
        end

        return items
    end
    local getPosition = function(instance)
        local parent = instance.Parent

        if not parent then
            return nil
        end
        if parent:IsA('Attachment') then
            return parent.WorldPosition
        end
        if parent:IsA('BasePart') then
            return parent.Position
        end

        local model = instance:FindFirstAncestorWhichIsA('Model')

        return model and model:GetPivot().Position
    end
    local findNearbyPrompts = function(position)
        local results = {}
        local thrownFolder = workspace:FindFirstChild('Thrown')

        for i, thrownChild in ipairs(thrownFolder and thrownFolder:GetChildren() or {})do
            local prompt = thrownChild:FindFirstChildWhichIsA('ProximityPrompt', true)
            local promptPosition = prompt and getPosition(prompt)

            if promptPosition and (promptPosition - position).Magnitude <= 2000 then
                results[#results + 1] = prompt
            end
        end

        return results
    end
    local waitForChests = function(target)
        if not aj.defeatPosition then
            return false
        end

        aj.progress = 'Waiting for Dread Serpent chests'

        local prompts = findNearbyPrompts(aj.defeatPosition)
        local deadline = os.clock() + 30

        while ak(target) and #prompts == 0 and os.clock() < deadline do
            task.wait(0.25)

            prompts = findNearbyPrompts(aj.defeatPosition)
        end

        if #prompts == 0 then
            aj.progress = 'Dread Serpent chest did not appear'

            return false
        end

        for chestIndex, chest in ipairs(prompts)do
            if not ak(target) then
                return false
            end
            if itemFilters.full() then
                aj.progress = 'Inventory full'

                return false
            end

            local chestPosition = getPosition(chest)

            if not chestPosition then
                continue
            end

            aj.progress = string.format('Looting Dread Serpent chest %d/%d', chestIndex, #prompts)

            local root = getRootPart()

            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(root.Position.X, 100, root.Position.Z) * root.CFrame.Rotation

            local travel = travelRecovery.new(CFrame.new(chestPosition.X, 100, chestPosition.Z), true, 220)

            while ak(target) and not travel.status() do
                task.wait(0.1)
            end

            if travel.status() ~= 'arrived' then
                travel.stop()

                return false
            end

            root = getRootPart()

            if not root then
                return false
            end

            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(chestPosition + Vector3.new(0, 3, 0))

            local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
            local timeout = os.clock() + 8

            repeat
                pcall(delayedTask.call, executorInfo.fire, chest)
                task.wait(0.2)
            until not ak(target) or playerGui and playerGui:FindFirstChild('ChoicePrompt') and playerGui.ChoicePrompt.Enabled ~= false or os.clock() > timeout

            if not ak(target) then
                return false
            end

            local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')

            if not choicePrompt then
                aj.progress = 'Could not open Dread Serpent chest'

                return false
            end

            itemFilters.fromPrompt(getItems(), function()
                return ak(target)
            end, noEffects.value('auto_kaido_loot_all', false), {
                exact = true,
                godrollRings = noEffects.value('auto_kaido_godroll_rings', false),
                timeout = 25,
                settings = function()
                    return getItems(), noEffects.value('auto_kaido_loot_all', false), {}, noEffects.value('auto_kaido_godroll_rings', false), {}
                end,
            })
            itemFilters.close(choicePrompt)
        end

        return true
    end
    local getBodyDirection = function(model, bodyPart)
        local head = model:FindFirstChild('Head')
        local torso = model:FindFirstChild('Torso3')

        if not head or not torso then
            return nil
        end

        local direction = torso.Position - head.Position

        direction = Vector3.new(direction.X, 0, direction.Z)

        if direction.Magnitude < 1 then
            return nil
        end

        direction = direction.Unit

        local partCFrame = bodyPart.CFrame
        local bodyRadius = math.abs(direction:Dot(partCFrame.RightVector)) * bodyPart.Size.X / 2 + math.abs(direction:Dot(partCFrame.UpVector)) * bodyPart.Size.Y / 2 + math.abs(direction:Dot(partCFrame.LookVector)) * bodyPart.Size.Z / 2
        local standPosition = bodyPart.Position + direction * (bodyRadius + am) + Vector3.new(0, -7, 0)

        return CFrame.lookAt(standPosition, bodyPart.Position)
    end

    ak = function(generation)
        local humanoid = noEffects.localPlayer.humanoid

        return aj:armed() and aj.generation == generation and humanoid and humanoid.Health > 0
    end

    local av, aw
    local flyToHighPoint = function(destination, gen)
        if av then
            av()
        end

        local player = getRootPart()

        if not player or not ak(gen) then
            return false
        end

        local verticalDelta = Vector3.new(0, destination.Position.Y + 8500 - player.Position.Y, 0)

        noEffects.localPlayer.humanoid:UnequipTools()

        player.AssemblyLinearVelocity = Vector3.zero
        player.CFrame = player.CFrame + verticalDelta

        local recoveryResult = travelRecovery.new(destination + Vector3.new(0, 8500, 0), true, 180).wait(math.huge)

        if not recoveryResult or not ak(gen) then
            return false
        end

        player.AssemblyLinearVelocity = Vector3.zero
        player.CFrame = destination

        aw(destination, gen)
        task.wait(0.5)

        return ak(gen)
    end
    local teleportToHighPoint = function(position, targetGen)
        av()

        local currentPlayer = getRootPart()

        if not currentPlayer or not ak(targetGen) then
            return
        end

        local liftOffset = Vector3.new(0, position.Position.Y + 8500 - currentPlayer.Position.Y, 0)

        currentPlayer.AssemblyLinearVelocity = Vector3.zero
        currentPlayer.CFrame = currentPlayer.CFrame + liftOffset

        if travelRecovery.new(position + Vector3.new(0, 8500, 0), true, 220).wait(math.huge) and ak(targetGen) then
            currentPlayer.AssemblyLinearVelocity = Vector3.zero
            currentPlayer.CFrame = position
        end
    end
    local isInVoidSea = function()
        local areaName = tostring(noEffects.localPlayer.instance:GetAttribute('CurrentArea') or ''):lower()

        return areaName:find('voidsea', 1, true) ~= nil or areaName:find('void sea', 1, true) ~= nil
    end
    local trySwimToSummon = function(spawnPosition, summonGen)
        local swimHumanoid = noEffects.localPlayer.humanoid

        for index, offset in ipairs({
            -1,
            -3,
            -5,
        })do
            if not ak(summonGen) then
                return false
            end

            local cframe = CFrame.new(spawnPosition.Position.X, offset, spawnPosition.Position.Z)

            aw(cframe, summonGen)
            task.wait(0.3)

            if swimHumanoid:GetState() == Enum.HumanoidStateType.Swimming then
                return true
            end
        end

        return false
    end

    av = function()
        if aj.hoverConnection then
            aj.hoverConnection:Disconnect()

            aj.hoverConnection = nil
        end
    end
    aw = function(hoverPosition, hoverGen)
        av()

        aj.hoverConnection = game:GetService('RunService').PreSimulation:Connect(function(
        )
            local aE = getRootPart()

            if not aE or not ak(hoverGen) then
                av()

                return
            end

            aE.AssemblyLinearVelocity = Vector3.zero

            local target = type(hoverPosition) == 'function' and hoverPosition() or hoverPosition

            if target then
                aE.CFrame = target
            end
        end)
    end

    local startKaidoFarmJourney = function()
        executionQueue.checkpoint(aj, false, 'Kaido journey')

        local farmGeneration = aj.generation
        local safeOrigin = getRootPart() and getRootPart().CFrame

        aj.safeOrigin = safeOrigin
        aj.defeated = false

        if not placeIds.isEastern() then
            aj.progress = 'Auto Kaido needs Eastern Luminant'

            return
        end
        if not findArdourManifestation() and not findKaido() then
            aj.progress = 'Need Ardour Manifestation'

            return
        end
        if noEffects.localPlayer.humanoid.Health < noEffects.localPlayer.humanoid.MaxHealth * 0.8 then
            aj.progress = 'Waiting for health before Auto Kaido'

            return
        end

        local serpent, boss = findKaido()

        if not serpent then
            aj.progress = 'Travelling to the Voidsea'

            local chosenWaypoint

            for waypointIndex, waypoint in ipairs(al)do
                if not flyToHighPoint(waypoint, farmGeneration) then
                    aj.progress = 'Could not reach the Voidsea'

                    return
                end
                if isInVoidSea() then
                    chosenWaypoint = waypoint

                    break
                end
            end

            if not isInVoidSea() then
                aj.progress = 'Voidsea location needs verification'

                return
            end
            if not trySwimToSummon(chosenWaypoint, farmGeneration) then
                aj.progress = 'Could not reach Voidsea water for summoning'

                return
            end

            local summonTool = findArdourManifestation()

            if not summonTool then
                aj.progress = 'Need Ardour Manifestation'

                return
            end

            aj.progress = 'Summoning Dread Serpent'

            noEffects.localPlayer.humanoid:EquipTool(summonTool)
            task.wait(0.2)

            if not ak(farmGeneration) or not isInVoidSea() or noEffects.localPlayer.humanoid:GetState() ~= Enum.HumanoidStateType.Swimming then
                return
            end

            summonTool:Activate()
            aw(CFrame.new(getRootPart().Position.X, 350, getRootPart().Position.Z), farmGeneration)

            local deadline = os.clock() + 45

            repeat
                task.wait(0.2)

                serpent, boss = findKaido()
            until serpent or os.clock() >= deadline or not ak(farmGeneration)

            av()

            if not serpent then
                aj.progress = 'Dread Serpent did not spawn'

                return
            end
        end

        executionQueue.checkpoint(aj, false, 'Kaido encounter')

        aj.progress = 'Fighting Dread Serpent'
        shared.Palantir_KaidoTarget = serpent

        local lowestHealth = boss.Health
        local defeatPosition = serpent:GetPivot().Position
        local lastDamageTime = os.clock()
        local recovery
        local healing = false
        local healCFrame

        pcall(function()
            noEffects.localPlayer.character.CharacterHandler.Requests.DrawWeapon:FireServer(true)
        end)

        while ak(farmGeneration) and serpent.Parent and boss.Health > 0 do
            local playerRoot = getRootPart()
            local root = serpent:FindFirstChild('Torso2') or serpent:FindFirstChild('HumanoidRootPart') or serpent.PrimaryPart

            if not playerRoot or not root then
                break
            end

            defeatPosition = root.Position

            if boss.Health < lowestHealth then
                lowestHealth = boss.Health
                lastDamageTime = os.clock()

                executionQueue.progress(aj, 'Boss health decreased')
            end

            local playerHumanoid = noEffects.localPlayer.humanoid

            if not healing and playerHumanoid.Health <= playerHumanoid.MaxHealth * 0.35 then
                healing = true
                healCFrame = CFrame.new(root.Position + Vector3.new(0, 300, 0))

                if recovery then
                    recovery.stop()

                    recovery = nil
                end

                av()
            end
            if healing then
                clickHolder.set(false)

                aj.progress = 'Healing 300 studs above Dread Serpent'

                if playerHumanoid.Health >= playerHumanoid.MaxHealth * 0.85 then
                    healing = false
                    healCFrame = nil

                    if recovery then
                        recovery.stop()

                        recovery = nil
                    end

                    av()

                    lastDamageTime = os.clock()
                else
                    local healSpot = healCFrame

                    if healSpot and (playerRoot.Position - healSpot.Position).Magnitude > 5 then
                        av()

                        if not recovery or recovery.status() then
                            if recovery then
                                recovery.stop()
                            end

                            recovery = travelRecovery.new(healSpot, true, 240)
                        end
                    elseif healSpot then
                        if recovery then
                            recovery.stop()

                            recovery = nil
                        end
                        if not aj.hoverConnection then
                            aw(healSpot, farmGeneration)
                        end
                    end

                    lastDamageTime = os.clock()

                    task.wait(0.05)

                    continue
                end
            end
            if root.Position.Y < 0 then
                if recovery then
                    recovery.stop()

                    recovery = nil
                end

                clickHolder.set(false)

                aj.progress = 'Waiting above water for Dread Serpent'
                playerRoot.AssemblyLinearVelocity = Vector3.zero
                playerRoot.CFrame = CFrame.new(playerRoot.Position.X, 30, playerRoot.Position.Z)
                lastDamageTime = os.clock()

                task.wait(0.05)

                continue
            end

            aj.progress = 'Fighting Dread Serpent'

            if os.clock() - lastDamageTime > 25 then
                aj.progress = 'Dread Serpent fight stalled'

                break
            end

            local aim = getBodyDirection(serpent, root)

            if not aim then
                clickHolder.set(false)
                task.wait(0.05)

                continue
            end
            if (playerRoot.Position - aim.Position).Magnitude > 30 then
                clickHolder.set(false)

                if not recovery or recovery.status() then
                    if recovery then
                        recovery.stop()
                    end

                    recovery = travelRecovery.new(function()
                        local rootPart = serpent:FindFirstChild('Torso2') or serpent:FindFirstChild('HumanoidRootPart')

                        return rootPart and getBodyDirection(serpent, rootPart) or playerRoot.CFrame
                    end, true, 240)
                end
            else
                if recovery then
                    recovery.stop()

                    recovery = nil
                end

                playerRoot.AssemblyLinearVelocity = Vector3.zero
                playerRoot.CFrame = aim

                clickHolder.set(true)
            end

            task.wait(0.05)
        end

        if recovery then
            recovery.stop()
        end

        executionQueue.checkpoint(aj, true, 'Kaido encounter ended')
        clickHolder.set(false)

        shared.Palantir_KaidoTarget = nil

        if boss.Health <= 0 then
            aj.defeated = true
            aj.defeatPosition = defeatPosition
            aj.progress = 'Dread Serpent defeated'
        end
    end

    aj = automationStep.construct({
        id = 'auto_kaido',
        restoreFeatures = true,
        features = {
            'NoFallDamage',
            'NoClip',
            'NoKillBricks',
            'EnableAutoParry',
        },
        notAllowed = function()
            return not placeIds.isEastern()
        end,
        onRun = function()
            local success, errorMessage = pcall(startKaidoFarmJourney)

            clickHolder.set(false)
            av()

            local chestLooted

            if success and aj.defeated and ak(aj.generation) then
                local chestSuccess, chestError = pcall(waitForChests, aj.generation)

                chestLooted = chestSuccess and chestError == true

                if not chestSuccess then
                    aj.progress = 'Dread Serpent chest error: ' .. tostring(chestError)
                end
            end
            if aj.safeOrigin and getRootPart() and ak(aj.generation) and isInVoidSea() then
                local progress = aj.progress or 'Auto Kaido finished'

                aj.progress = 'Returning from the Voidsea: ' .. progress

                pcall(teleportToHighPoint, aj.safeOrigin, aj.generation)
            end

            av()

            shared.Palantir_KaidoTarget = nil

            if not success then
                aj.progress = 'Auto Kaido failed: ' .. tostring(errorMessage)
            elseif aj.defeated then
                aj.progress = chestLooted and 'Dread Serpent chests looted' or 'Dread Serpent defeated; chest not collected'
            end

            aj.safeOrigin = nil
            aj.defeatPosition = nil

            if success and aj.defeated then
                aj:setArmed(false)

                aj.progress = chestLooted and 'Dread Serpent chests looted' or 'Dread Serpent defeated; chest not collected'
            end
        end,
        onStop = function()
            clickHolder.set(false)
            av()

            shared.Palantir_KaidoTarget = nil

            travelRecovery.stopAll()
        end,
    })

    return aj
end


return aa()

]=],
    ["Features/Automation/KaidoFarm2"] = [=[
local aa = function()
    local delayedTask = a["Utility/DelayedTask"]()
    local noEffects = a["Features/Game/NoEffects"]()
    local logger = a["Utility/Logger"]()
    local travelRecovery = a["Features/Game/TravelRecovery"]()
    local taskSpawner = a["Utility/TaskSpawner"]()
    local ferrymanRoute = a["Features/Automation/FerrymanRoute"]()
    local echoFarm = a["Features/Automation/EchoFarm"]()
    local autoProgression3 = a["Features/Automation/AutoProgression3"]()
    local autoProgression = a["Features/Automation/AutoProgression"]()
    local drillFarm = a["Features/Automation/DrillFarm"]()
    local kaidoFarm = a["Features/Automation/KaidoFarm"]()
    local parasolFarm = a["Features/Automation/ParasolFarm"]()
    local authorityMissionFarm = a["Features/Automation/AuthorityMissionFarm"]()
    local placeIds = a["Game/PlaceIds"]()
    local ao = {}

    ao.farms = {
        [ferrymanRoute.id] = ferrymanRoute,
        [echoFarm.id] = echoFarm,
        [autoProgression3.id] = autoProgression3,
        [drillFarm.id] = drillFarm,
        [kaidoFarm.id] = kaidoFarm,
        [parasolFarm.id] = parasolFarm,
        [authorityMissionFarm.id] = authorityMissionFarm,
    }
    ao.progression = autoProgression
    autoProgression.loader = ao

    local ap = false
    local aq
    local ar
    local as
    local at
    local au
    local getKillGuiTargets = function()
        local playerGui = noEffects.services.Players.LocalPlayer:FindFirstChild('PlayerGui')

        if not playerGui then
            return false
        end

        local killGui = playerGui:FindFirstChild('KillGUI')
        local splash = killGui and killGui:FindFirstChild('Splash')
        local confirm = splash and splash:FindFirstChild('Confirm')
