            ferrymanRoute:setArmed(false)

            ao.kaidoFarming = nil

            noEffects.setValue('auto_kaido_farming', false)

            noEffects.automation.kaidoManifestationNeeded = nil
        end

        farm:setArmed(armed)

        if key == 'auto_kaido' and armed and not autoProgression:armed() and not findArdourManifestation() then
