            noEffects.disableFeature('AggressiveMode')
        end

        noEffects.automation.requesting_mob_ai_breaker_stop = false

        if aq then
            pcall(task.cancel, aq)

            aq = nil
        end
    end
    function ao.init()
        if ap then
            return
        end

        ap = true
        au = task.spawn(function()
            while ap do
                if ao.kaidoFarming and kaidoFarm:armed() and findArdourManifestation() and not placeIds.isDungeon() then
                    ao.start()
                end
