            pcall(task.cancel, aq)

            aq = nil
        end

        for farmIdent, farmObject in next, ao.farms do
            farmObject:stop()

            if farmObject.stateMachine then
                farmObject.stateMachine.current = 'idle'
                farmObject.stateMachine.asyncState = 'none'
            end
        end
    end

    return ao
end


