]=],
    ["Features/Automation/MobVoider"] = [=[
local aa = function()
    local noEffects = a["Features/Game/NoEffects"]()
    local travelRecovery = a["Features/Game/TravelRecovery"]()
    local ac = {}
    local virtualInputManager = Instance.new('VirtualInputManager')
    local getRootPart = function()
        return noEffects.localPlayer.root_part
    end

    function ac.ride(character, condition)
        local root = character:FindFirstChild('Torso') or character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart

        if not root then
            return false
        end

        local keyThread = task.spawn(function()
            while character.Parent and root.Parent and condition() do
                virtualInputManager:SendKeyEvent(true, Enum.KeyCode.Q, false, game)
                task.wait(0.05)
                virtualInputManager:SendKeyEvent(false, Enum.KeyCode.Q, false, game)
                task.wait(0.3)
            end
        end)
        local target = getRootPart()

        if not target then
            pcall(task.cancel, keyThread)

            return false
        end

        target.AssemblyLinearVelocity = Vector3.zero

        local recovery = travelRecovery.new(function()
            local anchor = root.Parent and root

            return anchor and CFrame.new(anchor.Position) or CFrame.new(target.Position)
        end, true, 250)

        recovery.wait()
        recovery.stop()

        local reached = false
        local offset = 0

        while task.wait() do
            target = getRootPart()

            if not character.Parent or not root.Parent or not target or not condition() then
                break
            end
            if root.Position.Y > 20000 then
                break
            end
            if root.Position.Y > 8000 then
                reached = true

                break
            end

            offset = offset + 12

            local targetCFrame = CFrame.new((root.CFrame * CFrame.new(0, 1, 0)).Position) * CFrame.Angles(math.rad(
-90), 0, 0)

            target.AssemblyLinearVelocity = Vector3.zero
            target.Velocity = Vector3.zero
            target.CFrame = targetCFrame + Vector3.new(0, math.min(offset, 8000), 0)
        end

        pcall(task.cancel, keyThread)

        return reached
    end
    function ac.voidMob(mob, predicate)
        if not mob or not mob.Parent then
            return false
        end

        local result = ac.ride(mob, predicate)

        if not result then
            return false
        end

        local startTime = tick()

        repeat
            task.wait(0.2)
        until not mob.Parent or tick() - startTime > 15 or not predicate()

        return not mob.Parent
    end

    return ac
end


return aa()

