        local eventGui = playerGui and playerGui:FindFirstChild('WorldEventCallGui')
        local container = eventGui and eventGui:FindFirstChild('Container')
        local contents = container and container:FindFirstChild('Contents')
        local title = contents and contents:FindFirstChild('Title')
        local joinButton = contents and contents:FindFirstChild('Join')

        if not (eventGui and eventGui.Enabled and container and container.Visible and title and title:IsA('TextLabel') and title.Text == 'Interluminary Interloper' and joinButton and joinButton:IsA('GuiButton') and joinButton.Visible) then
