                local inputManager = game:GetService('VirtualInputManager')
                local position = joinButton.AbsolutePosition + joinButton.AbsoluteSize / 2 + game:GetService('GuiService'):GetGuiInset()

                inputManager:SendMouseMoveEvent(position.X, position.Y, game)
                inputManager:SendMouseButtonEvent(position.X, position.Y, 0, true, game, 0)
