                    local normalizedText = ((titleLabel and titleLabel.Text) or (descendant:IsA('TextButton') and descendant.Text) or descendant.Name):lower():gsub('[%s%p]', '')
                    local visible, parent = true, descendant

                    while parent and parent ~= prompt do
                        if parent:IsA('GuiObject') and not parent.Visible then
                            visible = false

                            break
                        end

                        parent = parent.Parent
                    end

                    local normalizedName = descendant.Name:lower():gsub('[%s%p]', '')

                    if visible and (normalizedText == 'lootall' or normalizedText == 'takeall' or normalizedName == 'lootall') then
                        lootButton = descendant

                        break
                    end
                end
            end

            if lootButton and lootCount < 2 and os.clock() - lastActionTime >= 1.5 then
                local fired = false

                for signalIndex, signal in ipairs({
                    lootButton.Activated,
                    lootButton.MouseButton1Click,
                })do
                    for connectionIndex, connection in ipairs(getconnections(signal))do
                        if connection.Enabled then
                            fired = pcall(function()
                                delayedTask.call(function()
                                    connection:Fire()
                                end)
                            end)

                            if fired then
                                break
                            end
                        end
                    end

                    if fired then
                        break
                    end
                end

                if not fired then
                    return false
                end

                lootCount, lastActionTime = lootCount + 1, os.clock()
            end

            task.wait(0.1)
        end

        return false
    end
    local interactChest = function(prompt)
        local chest = getWorldPosition(prompt)

        if not chest then
            return false
        end

        enablePromptRange()

        local originalMax = prompt:GetAttribute('OriginalMax') or prompt.MaxActivationDistance

        prompt:SetAttribute('OriginalMax', originalMax)

        prompt.MaxActivationDistance = originalMax * aj

        local root = getLocalRootPart()

        if not root or not am:armed() or not prompt.Parent or itemFilters.full() then
            return false
        end

        local cover = findNearestParasolPoint(chest, math.max(0, prompt.MaxActivationDistance - 6))

        if not cover then
            am.progress = 'Waiting for covered chest access'

            return false
        end

        am.progress = 'Travelling to chest cover'

        if not flyToPosition(cover) then
            return false
        end

        local playerGui = noEffects.localPlayer.instance and noEffects.localPlayer.instance:FindFirstChildOfClass('PlayerGui')

        if not playerGui then
            return false
        end

        local choicePrompt = playerGui:FindFirstChild('ChoicePrompt')

        if choicePrompt then
            itemFilters.close(choicePrompt)

            local closeTimeout = tick() + 0.4

            repeat
                task.wait(0.05)
            until not choicePrompt.Parent or choicePrompt.Enabled == false or tick() >= closeTimeout
        end

        local closed = not choicePrompt or not choicePrompt.Parent or choicePrompt.Enabled == false

        if not closed then
            return false
        end

        local lootTimeout = tick() + 1.5
        local openPrompt

        repeat
            pcall(executorFire, prompt)
            task.wait(0.5)

            openPrompt = playerGui:FindFirstChild('ChoicePrompt')
        until openPrompt and openPrompt.Enabled ~= false and (openPrompt ~= choicePrompt or closed) or tick() >= lootTimeout or not am:armed()

        if not openPrompt or openPrompt.Enabled == false or (openPrompt == choicePrompt and not closed) then
            return false
        end

        ak[prompt] = true
        am.progress = 'Looting from cover'

        if noEffects.value('auto_parasol_loot_all', false) and lootPromptLoop(openPrompt) then
            itemFilters.close(openPrompt)

            return true
        end

        local confirmed, looted, status = itemFilters.fromPrompt(getSelectedParasols(), function()
            return am:armed()
        end, noEffects.value('auto_parasol_loot_all', false), {
            timeout = 12,
            fast = true,
            exact = true,
            forcedItems = noEffects.value('auto_parasol_items', {}),
            godrollRings = noEffects.value('auto_parasol_godroll_rings', false),
            settings = function()
                return getSelectedParasols(), noEffects.value('auto_parasol_loot_all', false), {}, noEffects.value('auto_parasol_godroll_rings', false), noEffects.value('auto_parasol_items', {})
            end,
        })

        itemFilters.close(openPrompt)

        return looted or status == 'complete' or status == 'full' or (confirmed and status == 'closed')
    end
    local executeFarmLoop = function()
        local results = {}
        local attempts = {}
        local cooldowns = {}
        local deadline = tick() + 8

        while am:armed() and tick() < deadline do
            if itemFilters.full() then
                logger.notify('Auto Parasol: inventory full')

                return
            end

            local characterRoot = getLocalRootPart()

            if not characterRoot then
                return
            end

            local selected
            local bestDistance = math.huge
            local selectedOpened = true

            for index, candidate in ipairs(findThrownPrompts())do
                local chestPart = getWorldPosition(candidate)

                if chestPart and not al[candidate] and not results[candidate] and (attempts[candidate] or 0) < 3 and tick() >= (cooldowns[candidate] or 0) then
                    local distance = (characterRoot.Position - chestPart).Magnitude
                    local opened = (ak[candidate] or candidate:GetAttribute('Opened') == true or candidate.Parent and candidate.Parent:GetAttribute('Opened') == true) == true

                    if not selected or (not opened and selectedOpened) or opened == selectedOpened and distance < bestDistance then
                        selected, bestDistance, selectedOpened = candidate, distance, opened
                    end
                end
            end

            if selected then
                results[selected] = interactChest(selected)

                if results[selected] then
                    al[selected] = true
                end
                if not results[selected] then
                    attempts[selected] = (attempts[selected] or 0) + 1
                    cooldowns[selected] = tick() + 3
                end

                deadline = tick() + 6
            else
                task.wait(0.1)
            end
        end
    end

    am = automationStep.construct({
        id = 'auto_parasol',
        features = {},
        notAllowed = function()
            return game.PlaceId ~= ah and game.PlaceId ~= ai
        end,
        onRun = function()
            while am:armed() do
                if game.PlaceId == ai then
                    if not isInterloperEventActive() then
                        am.progress = 'Waiting for Parasol invitation'
                    end

                    task.wait(0.5)
                elseif game.PlaceId == ah and findParasolCharacter() then
                    enablePromptRange()

                    if performParasolAttack() then
                        executeFarmLoop()
                    end

                    task.wait(0.5)
                elseif game.PlaceId == ah then
                    if #findThrownPrompts() > 0 then
                        executeFarmLoop()
                    end

                    local coverPoint = getLocalRootPart()
                    local nearestCover = coverPoint and findNearestParasolPoint(coverPoint.Position, 500)

                    if nearestCover and (nearestCover - coverPoint.Position).Magnitude > 3 then
                        flyToPosition(nearestCover)
                    end

                    am.progress = nearestCover and 'Waiting in cover' or 'Waiting for map cover'

                    task.wait(1)
                else
                    task.wait(0.5)
                end
            end
        end,
    })

    return am
end


return aa()

]=],
