    local findNearestAntiquarian = function()
        local playerRoot = noEffects.localPlayer.root_part
        local npcFolder = workspace:FindFirstChild('NPCs')
        local aY, nearestDist

        if not playerRoot or not npcFolder then
            return
        end

        for idx, descendant in ipairs(npcFolder:GetDescendants())do
            if descendant.Name == 'Antiquarian' and (descendant:IsA('Model') or descendant:IsA('BasePart')) then
                local interactPrompt = descendant:FindFirstChild('InteractPrompt', true)

                if interactPrompt then
                    local distance = (playerRoot.Position - descendant:GetPivot().Position).Magnitude

