        if not npcPrompt or not interactRemote or not dialogueRemote or not sellRemote then
            return false, 'seller-unavailable'
        end

        delayedTask.method(interactRemote, 'FireServer', npcPrompt)
        task.wait(0.4)
        delayedTask.method(dialogueRemote, 'FireServer', {
            choice = 'Could you tell me the value of an item?',
        })
        task.wait(0.4)
        delayedTask.method(dialogueRemote, 'FireServer', {
            choice = "I'd like to sell something.",
        })
        task.wait(0.6)

        for itemIndex, itemEntry in ipairs(sellItems or {})do
            local itemValue = itemEntry.item

            if itemValue and itemValue.Parent and itemValue.Name ~= "Ferryman's Coat Cloth" then
