            noEffects.localPlayer.character,
        })do
            local cloth = container and container:FindFirstChild("Ferryman's Coat Cloth")

            if cloth then
                local quantityValue = cloth:FindFirstChild('Quantity')

                delayedTask.method(sellRemote, 'FireServer', cloth, tonumber(quantityValue and quantityValue.Value) or 1)
            end
        end

        task.wait(0.5)

        local dialogPlayerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local dialogueGui = dialogPlayerGui and dialogPlayerGui:FindFirstChild('DialogueGui')

        for attempt = 1, 3 do
            if not dialogueGui or not isGuiVisible(dialogueGui) then
                break
