    local fundProgressionTraining = function(character, target, trainingType, targetAmount)
        targetAmount = tonumber(targetAmount) or 25

        enableFlightAndNoClip()

        if getNotesAmount() >= targetAmount then
            clearLootInfo()

            return true, 'funded'
        end

        local sourceItem = restoreSourceLoot()

        if sourceItem then
            local success, reason = goSellToAntiquarian(character, target, trainingType, sourceItem, targetAmount)

            if success then
                clearLootInfo()
            elseif not restoreSourceLoot() then
                clearLootInfo()
            end

            return success, reason
        end
        if getTrinketCount() >= 75 or getCarryLoad() >= 75 then
            local bestItem = getInventoryItems()

            persistLootInfo(bestItem)

            local didFund, fundReason = goSellToAntiquarian(character, target, trainingType, bestItem, targetAmount)

            if didFund or not restoreSourceLoot() then
                clearLootInfo()
            end

            return didFund, fundReason
        end

