        local openOk, openStatus, lootItem = openChest(character, target, trainingType, ao)

        if not openOk and (openStatus == 'chest-missing' or openStatus == 'chest-timeout') then
            local backupOk, backupMsg = startTraining(ap, tick() + 120, character, target)

            if not backupOk then
                return false, backupMsg
            end

            local backupDeadline = tick() + 8

            repeat
                if findBestChest(ap) then
