        if not openOk then
            return false, openStatus
        end

        persistLootInfo(lootItem)

        local fundedOk, fundedMsg = goSellToAntiquarian(character, target, trainingType, lootItem, targetAmount)

        if fundedOk or not restoreSourceLoot() then
            clearLootInfo()
        end

        return fundedOk, fundedMsg
    end

    function ah.ensureTrainingFunds(player, goal, kind, amount)
