        for idx, descendant in ipairs(workspace:GetDescendants())do
            if descendant:IsA('ProximityPrompt') and descendant.Name == 'InteractPrompt' and (descendant.ActionText:lower():find('browse gear', 1, true) or descendant.ObjectText:lower():find('gearcabinet', 1, true) or descendant.ObjectText:lower():find('gear cabinet', 1, true)) then
                local parent = descendant.Parent
                local pivotPos = parent:IsA('Attachment') and parent.WorldPosition or parent:IsA('BasePart') and parent.Position or parent:IsA('Model') and parent:GetPivot().Position
                local distance = pivotPos and (pivotPos - an.Position).Magnitude

                if distance and distance <= 500 and (not bestRange or distance < bestRange) then
                    bestPrompt, bestRange = descendant, distance
                end
            end
