    local onGearGuiClick = function(click)
        local playerGui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
        local gearGui = playerGui and playerGui:FindFirstChild('GearCabinetGui')

        if not gearGui or not isGuiVisible(gearGui) then
            return true
        end

        local choiceFrame = gearGui:FindFirstChild('ChoiceFrame')
        local exitBtn = choiceFrame and choiceFrame:FindFirstChild('Exit')

        if exitBtn and exitBtn:IsA('GuiButton') and isGuiVisible(exitBtn) then
            local clickPos = exitBtn.AbsolutePosition + exitBtn.AbsoluteSize / 2 + game:GetService('GuiService'):GetGuiInset()
            local virtInput = noEffects.services.VirtualInputManager or game:GetService('VirtualInputManager')

            pcall(function()
                virtInput:SendMouseButtonEvent(clickPos.X, clickPos.Y, 0, true, game, 0)
                task.wait(0.08)
                virtInput:SendMouseButtonEvent(clickPos.X, clickPos.Y, 0, false, game, 0)
            end)
        elseif exitBtn and exitBtn:IsA('GuiButton') and click then
            pcall(click, exitBtn)
        end

        local waitDeadline = tick() + 1

        repeat
            task.wait(0.1)
        until not gearGui.Parent or not isGuiVisible(gearGui) or tick() >= waitDeadline

        if gearGui.Parent and isGuiVisible(gearGui) then
            local choiceRemote = gearGui:FindFirstChild('Choice')

            if choiceRemote and choiceRemote:IsA('RemoteEvent') then
                pcall(delayedTask.method, choiceRemote, 'FireServer', 'EXIT')
            end
        end

        waitDeadline = tick() + 2

        repeat
            task.wait(0.1)
        until not gearGui.Parent or not isGuiVisible(gearGui) or tick() >= waitDeadline

        return not gearGui.Parent or not isGuiVisible(gearGui)
