    function ah.buyBook(book, character, root, callback)
        enableFlightAndNoClip()

        if findItem(book) then
            onGearGuiClick(callback)

            return true, 'owned'
        end
        if not isAlive(character) then
            return false, 'cancelled'
        end
        if isNearby(root) then
            return false, 'nearby'
        end

        local valid, reason = fundProgressionTraining(character, root, callback)

        if not valid then
            return false, reason
        end

        local ok, cabinet = startTraining(an * CFrame.new(0, 0, -4), tick() + 120, character, root)

        if not ok then
            return false, cabinet
        end

        local deadline = tick() + 8

        repeat
            cabinet = findGearCabinetPrompt()

            if cabinet then
                break
            end
            if not isAlive(character) then
                return false, 'cancelled'
            end
            if isNearby(root) then
                return false, 'nearby'
