                    if findItem(book) then
                        onGearGuiClick(callback)

                        return true, 'bought'
                    end
                    if not isAlive(character) then
                        onGearGuiClick(callback)

                        return false, 'cancelled'
                    end

                    task.wait(0.1)
                until tick() >= timeout
            end
        end

        onGearGuiClick(callback)

        return false, 'purchase-unconfirmed'
    end
    function ah.fortitude(stat, targetValue, player, targetRoot, update)
        if type(targetValue) == 'table' then
            targetValue = getDictionaryStat(targetValue, 'Fortitude')
        end

        targetValue = tonumber(targetValue) or 0

        if not needsTraining(stat, 'Fortitude', targetValue) then
            return false, 'not-needed'
        end
        if not isAlive(player) then
            return false, 'cancelled'
        end
        if isNearby(targetRoot) then
            return false, 'nearby'
        end

        local playerCharacter = noEffects.localPlayer.character
        local playerRoot = noEffects.localPlayer.root_part
        local humanoid = noEffects.localPlayer.humanoid

        if not playerCharacter or not playerRoot or not humanoid or humanoid.Health <= 0 then
            return false, 'unavailable'
        end

        local npcs = workspace:FindFirstChild('NPCs')
        local brutus = npcs and npcs:FindFirstChild('Brutus')
        local brutusRoot = brutus and (brutus:FindFirstChild('HumanoidRootPart') or brutus.PrimaryPart)
        local prompt = brutus and (brutus:FindFirstChild('InteractPrompt') or brutus:FindFirstChildWhichIsA('ProximityPrompt', true))
        local bb, bc

        if not brutusRoot or not prompt then
            bb, bc = startTraining(CFrame.new(-7612, 671, 3013), nil, player, targetRoot)

            if not bb then
                return false, bc
            end
        end

        local timer = tick() + 15

        while(not brutusRoot or not prompt) and tick() < timer do
            if not isAlive(player) then
                return false, 'cancelled'
            end
            if isNearby(targetRoot) then
                return false, 'nearby'
            end

            task.wait(0.2)

            npcs = workspace:FindFirstChild('NPCs')
            brutus = npcs and npcs:FindFirstChild('Brutus')
            brutusRoot = brutus and (brutus:FindFirstChild('HumanoidRootPart') or brutus.PrimaryPart)
            prompt = brutus and (brutus:FindFirstChild('InteractPrompt') or brutus:FindFirstChildWhichIsA('ProximityPrompt', true))
        end

        if not playerCharacter or not playerRoot or not humanoid or humanoid.Health <= 0 or not brutus or not brutusRoot or not prompt then
            return false, 'unavailable'
        end

        bb, bc = startTraining(brutusRoot.CFrame, nil, player, targetRoot)

        if not bb then
            return false, bc
        end

        local requestsFolder = noEffects.services.ReplicatedStorage:FindFirstChild('Requests')
        local sendDialogue = requestsFolder and requestsFolder:FindFirstChild('SendDialogue')

        while isAlive(player) do
            if not isAlive(player) then
                return false, 'cancelled'
            end
            if isNearby(targetRoot) then
                return false, 'nearby'
            end
            if noEffects.localPlayer.character ~= playerCharacter or humanoid.Health <= 0 then
                return false, 'cancelled'
            end

            local progress = update and update()

            if (progress and not needsTraining(progress, 'Fortitude', targetValue)) or getStatAttribute(playerCharacter, 'Fortitude', stat) >= targetValue then
                return true, 'complete'
            end
            if sendDialogue then
                local gui = noEffects.localPlayer.instance:FindFirstChild('PlayerGui')
                local dialogueGui = gui and gui:FindFirstChild('DialogueGui')

                if dialogueGui and dialogueGui.Enabled then
                    pcall(sendDialogue.FireServer, sendDialogue, {exit = true})
                end
            end

            pcall(executorFire, prompt)
            task.wait(0.05)
        end

        return false, 'cancelled'
    end

    return ah
end


return aa()

]=],
    ["Features/Automation/RegionTransfer"] = [=[
local aa = function()
    local placeIds = a["Game/PlaceIds"]()
    local teleport = a["Features/Game/Teleport"]()
    local transfers = {}
    local ad = function(destination, isArrived, cancelled)
        if isArrived() then
            return true
        end

        for attempt = 1, 3 do
            if cancelled and not cancelled() then
                return false, 'cancelled'
            end

            teleport.start(destination)

            repeat
                task.wait(0.2)

                if cancelled and not cancelled() then
                    teleport.stop(true)

                    return false, 'cancelled'
                end
                if isArrived() then
                    teleport.stop(true)

                    return true
                end

                local status = teleport.regionStatus()

                if not status or status.state == 'failed' then
                    local reason = status and status.reason or 'Region transfer was interrupted'

                    teleport.stop(true)

                    if attempt == 3 then
                        return false, reason
                    end

                    break
                end
            until false
        end
    end

    function transfers.toEastern(ae, cancelled)
        return ad('EasternLuminant', placeIds.isEastern, cancelled)
    end
    function transfers.toEtrean(ae, cancelled)
        if placeIds.isEtrean() then
            return true
        end
        if not placeIds.isEastern() or cancelled and not cancelled() then
            return false
        end

        return ad('EtreanLuminant', placeIds.isEtrean, cancelled)
    end

    return transfers
end


return aa()

