                end
            end
        end

        return aE
    end

    local buildRequirementMap = function(spec, source, isMantra)
        local result = {}
        local requirements = spec.requirements or {}

        for reqIndex, reqName in ipairs(requirements[isMantra and 'mantras' or 'talents'] or {})do
            result[normalizeName(reqName)] = reqName
        end
        for fromIndex, fromId in ipairs(spec[isMantra and 'from_mantras' or 'from_ids'] or {})do
            for metaKey, metaEntry in pairs(isMantra and source.mantraMetadata or source.metadata)do
                if (metaEntry.id or metaEntry._id) == fromId then
                    result[metaKey] = metaEntry.name

                    break
                end
            end
        end

        return result
    end
    local expandBuildRequirements = function(build)
        build.wantedTalents = table.clone(build.talents)
        build.wantedMantras = table.clone(build.mantras)

        local visited = {}

        local function visit(nodeName, isMantraMode)
            local nodeKey = (isMantraMode and 'mantra:' or 'talent:') .. nodeName

            if visited[nodeKey] then
                return
            end

            visited[nodeKey] = true

            local metadata = (isMantraMode and build.mantraMetadata or build.metadata)[nodeName]

            if not metadata then
                return
            end

            for modeIndex, isMantraFlag in ipairs({false, true})do
                for reqKey, reqValue in pairs(buildRequirementMap(metadata, build, isMantraFlag))do
                    (isMantraFlag and build.wantedMantras or build.wantedTalents)[reqKey] = reqValue

                    visit(reqKey, isMantraFlag)
                end
            end
        end

        for talent in pairs(build.talents)do
            visit(talent, false)
        end
        for mantra in pairs(build.mantras)do
            visit(mantra, true)
        end
    end
    local fetchUrl = function(url)
        local aE = request or (syn and syn.request) or http_request or (http and http.request)

        if not aE then
            return nil, 'HTTP request is unavailable.'
        end

        local success, outcome, done
        local thread = task.spawn(function()
            success, outcome = pcall(function()
                local response = aE({
                    Url = url,
                    Method = 'GET',
                    Headers = {
                        ['Content-Type'] = 'application/json',
                        Accept = 'application/json',
                        Origin = 'https://deepwoken.co',
                        Referer = 'https://deepwoken.co/builder',
                        ['Sec-Fetch-Site'] = 'same-origin',
                        ['Sec-Fetch-Mode'] = 'cors',
                        ['Sec-Fetch-Dest'] = 'empty',
                    },
                })

                if not response or response.StatusCode ~= 200 or not response.Body then
                    error('Builder request failed: ' .. tostring(response and response.StatusCode or 'no response'), 0)
                end

                return httpService:JSONDecode(response.Body)
            end)
            done = true
        end)
        local deadline = os.clock() + 12

        while not done and os.clock() < deadline do
            task.wait(0.1)
        end

        if not done then
            pcall(task.cancel, thread)

            return nil, 'Builder request timed out.'
        end
        if success then
            return outcome
        end

        return nil, tostring(outcome)
    end
    local buildStatMap = function(data)
        local statMap = {}

        for statIndex, category in ipairs({
            'base',
            'weapon',
            'attunement',
        })do
            for statKey, statValue in pairs(data and data[category] or {})do
                local normalizedKey = resolveStatName(statKey)

                if normalizedKey then
                    statMap[normalizedKey] = tonumber(statValue) or 0
                end
            end
        end

        return statMap
    end
    local buildNameMap = function(list)
        local nameMap = {}

        for pairKey, pairValue in pairs(list or {})do
            local displayName = type(pairValue) == 'table' and (pairValue.name or pairValue.Name) or pairValue

            if displayName then
                nameMap[normalizeName(displayName)] = tostring(displayName)
            end
        end

        return nameMap
    end
    local parseOrderedItems = function(input, prefix)
        local items = {}

        for itemKey, itemValue in pairs(input or {})do
            local orderStr = tostring(itemKey):lower():match('^' .. prefix .. '(%d+)$')
            local itemName = tostring(itemValue or '')

            if orderStr and itemName ~= '' and normalizeName(itemName) ~= 'none' then
                items[#items + 1] = {
                    order = tonumber(orderStr) or 99,
                    name = itemName,
                }
            end
        end

        table.sort(items, function(left, right)
            return left.order == right.order and left.name < right.name or left.order < right.order
        end)

        local names = {}

        for namesIndex, sortedItem in ipairs(items)do
            names[#names + 1] = sortedItem.name
        end

        return names
    end
    local buildElementBonuses = function(build, statValues)
        local buildStats = type(build and build.stats) == 'table' and build.stats or {}
        local statMeta = type(buildStats.meta) == 'table' and buildStats.meta or {}
        local origin = tostring(statMeta.Origin or buildStats.origin or '')

        if normalizeName(origin) == 'none' then
            origin = ''
        end

        local elements, elementNameMap = {}, {
            ElementFire = 'Flamecharm',
            ElementIce = 'Frostdraw',
            ElementLightning = 'Thundercall',
            ElementWind = 'Galebreathe',
            ElementShadow = 'Shadowcast',
            ElementMetal = 'Ironsing',
            ElementBlood = 'Bloodrend',
        }

        for elementStat, elementLabel in pairs(elementNameMap)do
            if (tonumber(statValues[elementStat]) or 0) > 0 then
                elements[#elements + 1] = elementLabel
            end
        end

        table.sort(elements)

        local bestWeaponStat, bestWeapon

        for weaponIndex, weaponEntry in ipairs({
            {
                stat = 'WeaponHeavy',
                weapon = 'Battleaxe',
            },
            {
                stat = 'WeaponMedium',
                weapon = 'Sword',
            },
            {
                stat = 'WeaponLight',
                weapon = 'Stiletto',
            },
        })do
            local weaponStatValue = tonumber(statValues[weaponEntry.stat]) or 0

            if weaponStatValue > 0 and (not bestWeaponStat or weaponStatValue > bestWeaponStat) then
                bestWeaponStat, bestWeapon = weaponStatValue, weaponEntry.weapon
            end
        end

        return {
            boons = parseOrderedItems(buildStats, 'boon'),
            flaws = parseOrderedItems(buildStats, 'flaw'),
            origin = origin ~= '' and origin or nil,
            weapon = bestWeapon or 'Sword',
            elements = elements,
            elementalist = #elements > 1,
            multifaceted = build and (build.multifaceted == true or build.multifaceted == 1 or tostring(build.multifaceted):lower() == 'true') or false,
        }
    end

    function ab.load(buildUrl, progress, mode)
        local buildId = buildUrl and buildUrl:match('^https?://[%w%.]*deepwoken%.co/builder%?id=([%w]+)')

        if not buildId then
            return nil, 'Enter a deepwoken.co builder link.'
        end
        if progress then
            progress('Loading selected build')
        end

        local aM, loadError = fetchUrl('https://new.deepwoken.co/api/proxy/builds/' .. buildId)

        if not aM then
            return nil, loadError or 'Could not load the selected build.'
        end
        if progress then
            progress('Checking talent requirements')
        end

        local talentData, talentError

        if mode == 'talents' then
            talentData = {
                talents = a["Game/Data/TalentData"](),
            }
        else
            talentData, talentError = fetchUrl('https://new.deepwoken.co/api/proxy/get?type=all')
        end
        if not talentData then
            return nil, talentError or 'Could not load talent requirements.'
        end

        local preShrineStats = buildStatMap(aM.preShrine)
        local postShrineStats = buildStatMap(aM.postShrine)
        local hasPostShrine = false

        for postStatName, postStatValue in pairs(postShrineStats)do
            if postStatValue > 0 then
                hasPostShrine = true

                break
            end
        end

        if not hasPostShrine then
            postShrineStats = buildStatMap(aM.attributes)
        end

        local requiredStats = table.clone(postShrineStats)

        for preStatName, preStatValue in pairs(preShrineStats)do
            requiredStats[preStatName] = math.max(requiredStats[preStatName] or 0, preStatValue)
        end

        local result = {
            url = buildUrl,
            pre = preShrineStats,
            post = postShrineStats,
            oath = aM.stats and aM.stats.meta and aM.stats.meta.Oath,
            talents = buildNameMap(aM.talents),
            mantras = buildNameMap(aM.mantras),
            stats = aM.stats or {},
            metadata = {},
            mantraMetadata = {},
            weaponMetadata = {},
            creation = buildElementBonuses(aM, requiredStats),
        }

        for talentIndex, talent in pairs(talentData.talents or {})do
            if talent.name and not talent.VOI and (not result.metadata[normalizeName(talent.name)] or not talent.vaulted) then
                result.metadata[normalizeName(talent.name)] = talent
            end
        end
        for mantraIndex, mantra in pairs(talentData.mantras or {})do
            if mantra.name and not mantra.VOI and (not result.mantraMetadata[normalizeName(mantra.name)] or not mantra.vaulted) then
                result.mantraMetadata[normalizeName(mantra.name)] = mantra
            end
        end

        local isMantraAllowed = function(mantraId)
            local mantraData = result.mantraMetadata[mantraId]
            local mantraType = mantraData and normalizeName(mantraData.type or mantraData.mantra_type or mantraData.source)

            return mantraData and not mantraData.VOI and not mantraData.exclusive and mantraType ~= 'monster' and mantraType ~= 'oath' and mantraType ~= 'exclusive'
        end

        for mantraName in pairs(result.mantras)do
            if not isMantraAllowed(mantraName) then
                result.mantras[mantraName] = nil
            end
        end
        for weaponKey, weapon in pairs(talentData.weapons or {})do
            if weapon.name then
                result.weaponMetadata[normalizeName(weapon.name)] = weapon
            end
        end

        result.noShrine = true

        for preKey, preValue in pairs(result.pre)do
            if preValue > 0 then
                result.noShrine = false

                break
            end
        end

        if result.noShrine then
            result.pre = table.clone(result.post)
        end

        expandBuildRequirements(result)

        for wantedMantraName in pairs(result.wantedMantras)do
            if not isMantraAllowed(wantedMantraName) then
                result.wantedMantras[wantedMantraName] = nil
            end
        end

        if progress then
            progress('Matching selected talents')
        end

        return result
    end
    function ab.cancelSpend()
        if ap and ap.thread then
            pcall(task.cancel, ap.thread)
        end

        ap = nil
    end
    function ab.cancelFavour()
        if aq and aq.thread then
            pcall(task.cancel, aq.thread)
        end

        aq = nil
    end
    function ab.resetData()
        as = nil
        at = {
            names = {},
            at = 0,
        }

        ab.cancelSpend()
        ab.cancelFavour()
        table.clear(ar)

        ao = ao + 1

        for slotIndex, slotEntry in ipairs(aj)do
            if slotEntry.thread then
                pcall(task.cancel, slotEntry.thread)
            end
        end

        aj = {{}, {}}
        ak = nil
        al = 0
        am = localPlayer.Character
        an = localPlayer:GetAttribute('DataSlot')
    end

    local scheduleSlotRead = function(index, callback)
        local slot = aj[index]
        local now = os.clock()

        if slot.thread then
            if now - slot.started >= 5 then
                slot.active = false

                pcall(task.cancel, slot.thread)

                aj[index] = {
                    nextRead = now + 2,
                }
            end

            return
        end
        if now < (slot.nextRead or 0) then
            return
        end

        local generation = ao

        slot.active = true
        slot.started = now
        slot.thread = task.defer(function()
            local success, result = pcall(callback)

            if not slot.active or generation ~= ao or localPlayer.Character ~= am or localPlayer:GetAttribute('DataSlot') ~= an then
                return
            end
            if success and type(result) == 'table' and tonumber(result.StatStrength) and (index == 1 or slot.started >= al) then
                ak = result
                al = os.clock()
            end

            slot.active = false
            slot.thread = nil
            slot.nextRead = os.clock() + (index == 1 and 0 or 2)
        end)
    end

    function ab.data()
        if localPlayer.Character ~= am or localPlayer:GetAttribute('DataSlot') ~= an then
            ab.resetData()
        end
        if ak and os.clock() - al < 1 then
            for statIndex, statName in ipairs({
                'WeaponHeavy',
                'WeaponMedium',
                'WeaponLight',
                'Strength',
                'Fortitude',
                'Agility',
                'Intelligence',
                'Willpower',
                'Charisma',
                'ElementFire',
                'ElementIce',
                'ElementLightning',
                'ElementWind',
                'ElementShadow',
                'ElementMetal',
                'ElementBlood',
            })do
                if tonumber(ak['Stat' .. statName]) == nil then
                    return nil
                end
            end

            return ak
        end

        scheduleSlotRead(1, function()
            local info = replicatedStorage:FindFirstChild('Info')
            local dataReplication = info and info:FindFirstChild('DataReplication')

            if dataReplication then
                return require(dataReplication).GetData()
            end
        end)
        scheduleSlotRead(2, function()
            local requests = replicatedStorage:FindFirstChild('Requests')
            local getRemote = requests and requests:FindFirstChild('Get')

            if getRemote then
                return getRemote:InvokeServer()
            end
        end)
    end
    function ab.power(data)
        return tonumber(data and (data.Power or data.Level or data.CurrentPower)) or tonumber(localPlayer:GetAttribute('Power'))
    end
    function ab.knowledge(knowledgeData)
        return tonumber(knowledgeData and (knowledgeData.ShrinePoints or knowledgeData.Knowledge or knowledgeData.KnowledgePoints))
    end
    function ab.points(pointsData)
        return (tonumber(pointsData and pointsData.AvailableAttributePoints) or 0) + (tonumber(pointsData and pointsData.FullAttributePoints) or 0)
    end
    function ab.owned(ownedData, category)
        local owned = {}

        for key, value in pairs(ownedData and ownedData[category] or {})do
            local name = type(value) == 'table' and (category == 'Mantras' and resolveMantraName(value, ownedData) or value.RichName or value.Name or value.name) or (type(value) == 'string' and value) or (type(key) == 'string' and key)

            if category == 'Mantras' then
                name = av[normalizeName(name)] or name
            end
            if name then
                owned[normalizeName(name)] = true
            end
        end

        if category == 'Talents' and not next(owned) then
            local playerGui = localPlayer:FindFirstChild('PlayerGui')

            playerGui = playerGui and playerGui:FindFirstChild('BackpackGui')
            playerGui = playerGui and playerGui:FindFirstChild('RightFrame')
            playerGui = playerGui and playerGui:FindFirstChild('TalentSheet')
            playerGui = playerGui and playerGui:FindFirstChild('Container')
            playerGui = playerGui and playerGui:FindFirstChild('TalentScroll')

            if playerGui and (at.root ~= playerGui or os.clock() >= at.at) then
                local names = {}

                for descendantIndex, descendant in ipairs(playerGui:GetDescendants())do
                    local title = descendant:FindFirstChild('Title')

                    if title and title:IsA('TextLabel') and not descendant.Name:find('Missing_') then
                        names[normalizeName(title.Text)] = true
                    end
                end

                at = {
                    root = playerGui,
                    names = names,
                    at = os.clock() + 0.25,
                }
            end
            if playerGui then
                for talentName in pairs(at.names)do
                    owned[talentName] = true
                end
            end
        end

        return owned
    end
    function ab.canRead(section, key)
        if type(section and section[key]) == 'table' then
            return true
        end
        if key ~= 'Talents' then
            return false
        end

        local playerGui = localPlayer:FindFirstChild('PlayerGui')

        playerGui = playerGui and playerGui:FindFirstChild('BackpackGui')
        playerGui = playerGui and playerGui:FindFirstChild('RightFrame')
        playerGui = playerGui and playerGui:FindFirstChild('TalentSheet')
        playerGui = playerGui and playerGui:FindFirstChild('Container')

        return playerGui and playerGui:FindFirstChild('TalentScroll') ~= nil
    end
    function ab.preTalents(talentBook)
        local result = {}

        for name, value in pairs(talentBook.wantedTalents or talentBook.talents)do
            local metadata = talentBook.metadata[name]
            local isQuest = metadata and tostring(metadata.rarity or metadata.Rarity or ''):lower() == 'quest'

            if not isQuest and #paths(metadata, talentBook.pre) > 0 and #paths(metadata, talentBook.post) == 0 then
                result[name] = value
            end
        end

        local visited = {}

        local function addReq(talentName)
            if visited[talentName] then
                return
            end

            visited[talentName] = true

            local talentData = talentBook.metadata[talentName]

            if not talentData then
                return
            end

            for reqName, reqValue in pairs(buildRequirementMap(talentData, talentBook, false))do
                result[reqName] = reqValue

                addReq(reqName)
            end
        end

        for talentName in pairs(table.clone(result))do
            addReq(talentName)
        end

        return result
    end
    function ab.obtainableAfterShrine(talentBook, talentName)
        local data = talentBook.metadata[talentName]

        return data ~= nil and not data.vaulted and #paths(data, talentBook.post) > 0
    end
    function ab.isStatTalent(talent)
        local statData = talent and extractRequiredStats(talent)
        local rarity = talent and tostring(talent.rarity or talent.Rarity or ''):lower()

        return (rarity == 'common' or rarity == 'rare') and statData and next(statData) ~= nil and not talent.autotalent and not talent.vaulted and not talent.dontcounttowardstotal and talent.countTowardsTalentTotal ~= false and not talent.orRequirements and not (talent.from_mantras and #talent.from_mantras > 0)
    end
    function ab.statTalents(talentBook)
        if talentBook.statTalentTargets then
            return talentBook.statTalentTargets
        end

        local result = {}

        for name, value in pairs(talentBook.talents)do
            if ab.isStatTalent(talentBook.metadata[name]) then
                result[name] = value
            end
        end

        talentBook.statTalentTargets = result

        return result
    end
    function ab.preMantras(mantraBook)
        local result = {}

        for name, value in pairs(mantraBook.wantedMantras or mantraBook.mantras)do
            if #paths(mantraBook.mantraMetadata[name], mantraBook.pre) > 0 and #paths(mantraBook.mantraMetadata[name], mantraBook.post) == 0 then
                result[name] = value
            end
        end

        return result
    end
    function ab.trainingMantras(build)
        local ownedMantras = ab.owned(build, 'Mantras')
        local result = {}

        for mantra, stat in pairs(ai)do
            if (tonumber(build and (build['Stat' .. stat] or build['Stat_' .. stat] or build[stat])) or 0) > 0 then
                local isOwned = false

                for ownedName, ownedStat in pairs(ai)do
                    if ownedStat == stat and ownedMantras[ownedName] then
                        isOwned = true

                        break
                    end
                end

                if not isOwned then
                    result[mantra] = mantra
                end
            end
        end

        return result
    end
    function ab.missing(build, owned, known)
        local missing = {}

        for name, value in pairs(owned)do
            if not known[name] then
                missing[name] = value
            end
        end

        return missing
    end
    function ab.eligible(build, talent, ownedMap, talentPool)
        local requirements = extractRequiredStats(talent)

        if not requirements or talent.vaulted or talent.autotalent or talent.orRequirements or (tonumber(talent.power) or 0) > (ab.power(build) or 0) then
            return false
        end

        for stat, requirement in pairs(requirements)do
            if (tonumber(build['Stat' .. stat]) or 0) < requirement then
                return false
            end
        end

        if talent.from_mantras and #talent.from_mantras > 0 then
            return false
        end

        for _index, reqName in ipairs(talent.requirements and talent.requirements.talents or {})do
            if not ownedMap[normalizeName(reqName)] then
                return false
            end
        end
        for _index, fromId in ipairs(talent.from_ids or {})do
            local found = false

            for name, data in pairs(talentPool)do
                if data.id == fromId and ownedMap[name] then
                    found = true

                    break
                end
            end

            if not found then
                return false
            end
        end
        for _index, exclusiveId in ipairs(talent.exclusive_with_ids or {})do
            for name, data in pairs(talentPool)do
                if data.id == exclusiveId and ownedMap[name] then
                    return false
                end
            end
        end

        return true
    end
    function ab.mismatch(stats, targetMap)
        for statIndex, statName in pairs(ag)do
            if tonumber(stats['Stat' .. statName]) and stats['Stat' .. statName] > (targetMap[statName] or 0) then
                return true
            end
        end

        return false
    end
    function ab.targetsMet(currentStats, goalTargets)
        if not next(goalTargets) then
            return false
        end

        for targetStat, targetLevel in pairs(goalTargets)do
            if (tonumber(currentStats['Stat' .. targetStat]) or 0) < targetLevel then
                return false
            end
        end

        return true
    end

    local meetsStatRequirements = function(requiredStats, statsToCheck)
        for reqStat, reqAmount in pairs(requiredStats)do
            if (statsToCheck[reqStat] or 0) < reqAmount then
                return false
            end
        end

        return true
    end
    local anyRouteSatisfies = function(routeList, needed)
        for routeIndex, route in ipairs(routeList)do
            if meetsStatRequirements(route, needed) then
                return true
            end
        end

        return false
    end

    function ab.nextStat(data, targets, build, phase)
        local curStats, targetClone = {}, table.clone(targets)

        for statPos, statKey in pairs(ag)do
            curStats[statKey] = tonumber(data['Stat' .. statKey]) or 0
            targetClone[statKey] = math.max(targetClone[statKey] or 0, curStats[statKey])
        end

        local owned = {
            talents = ab.owned(data, 'Talents'),
            mantras = ab.owned(data, 'Mantras'),
        }
        local sigParts = {
            tostring(phase),
            tostring(ab.power(data) or 0),
        }

        for applyStat, applyValue in pairs(curStats)do
            sigParts[#sigParts + 1] = 'stat:' .. applyStat .. ':' .. applyValue
        end
        for goalStat, goalValue in pairs(targets)do
            sigParts[#sigParts + 1] = 'target:' .. goalStat .. ':' .. goalValue
        end
        for category, items in pairs(owned)do
            for item in pairs(items)do
                sigParts[#sigParts + 1] = category .. ':' .. item
            end
        end

        table.sort(sigParts)

        sigParts = table.concat(sigParts, '|')

        if as and as.build == build and as.signature == sigParts then
            return as.stat, as.amount
        end

        local candidates = {}

        for catIndex, kind in ipairs({
            'talents',
            'mantras',
        })do
            local wanted = kind == 'talents' and (build.wantedTalents or build.talents) or (build.wantedMantras or build.mantras)
            local metadata = kind == 'talents' and build.metadata or build.mantraMetadata

            for entryName in pairs(wanted)do
                local node = metadata[entryName]

                if not owned[kind][entryName] and node and not node.vaulted then
                    local routes = paths(node, targetClone)

                    if #routes > 0 and not anyRouteSatisfies(routes, curStats) then
                        local weight = 1

                        for flagIndex, useMantra in ipairs({false, true})do
                            for edgeName in pairs(buildRequirementMap(node, build, useMantra))do
                                if not owned[useMantra and 'mantras' or 'talents'][edgeName] then
                                    weight = 0.25
                                end
                            end
                        end

                        local powerReq = tonumber(node.power or node.requirements and node.requirements.stats and node.requirements.stats.Power) or 0

                        weight = weight / (1 + math.max(0, powerReq - (ab.power(data) or 1) - 1))

                        if phase ~= 'post' and #paths(node, build.pre) > 0 and #paths(node, build.post) == 0 then
                            weight = weight * 4
                        end

                        candidates[#candidates + 1] = {
                            routes = routes,
                            weight = weight,
                            key = kind .. ':' .. entryName,
                        }
                    end
                end
            end
        end

        table.sort(candidates, function(left, right)
            return left.key < right.key
        end)

        local bestRoute, bestScore, bestCost, bestSig

        for pos, candidate in ipairs(candidates)do
            for rtIndex, rtPath in ipairs(candidate.routes)do
                local costNeeded, pathSig = 0, {}
                local routeStats = table.clone(curStats)

                for pathStat, pathVal in pairs(rtPath)do
                    routeStats[pathStat] = math.max(curStats[pathStat] or 0, pathVal)
                    costNeeded = costNeeded + routeStats[pathStat] - (curStats[pathStat] or 0)
                    pathSig[#pathSig + 1] = pathStat .. ':' .. tostring(pathVal)
                end

                table.sort(pathSig)

                pathSig = table.concat(pathSig, ',')

                if costNeeded > 0 then
                    local totalWeight = 0

                    for entryIndex, entryItem in ipairs(candidates)do
                        if anyRouteSatisfies(entryItem.routes, routeStats) then
                            totalWeight = totalWeight + entryItem.weight
                        end
                    end

