    ["Features/Automation/TravelAction"] = [=[
local aa = function()
    local executionQueue = a["Features/Automation/ExecutionQueue"]()
    local travelRecovery = a["Features/Game/TravelRecovery"]()
    local players = game:GetService('Players')
    local module = {}

    function module.run(destination, options)
        local character = players.LocalPlayer.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')
        local queue = executionQueue.active
        local shouldContinue = function()
            return root and root.Parent and players.LocalPlayer.Character == character and (not queue or executionQueue.valid(queue)) and (not options.alive or options.alive())
        end
        local validate = function()
            if not shouldContinue() then
                return false, 'cancelled'
            end
            if options.nearby and options.nearby() then
                return false, 'nearby'
            end

            return true
        end
        local ok, reason = validate()

        if not ok then
            return false, reason
        end
        if queue and queue.stopMovement then
            queue.stopMovement()
        end

        local deltaVector = root.Position - destination.Position
        local needsRise = options.force or Vector3.new(deltaVector.X, 0, deltaVector.Z).Magnitude > 700 or deltaVector.Y > 700
        local launchTarget = needsRise and destination + Vector3.new(0, 8500, 0) or destination
        local targetY = launchTarget.Position.Y
        local attemptCount = 0

        if queue then
            executionQueue.checkpoint(queue.owner, false, 'travelling')
        end

        while shouldContinue() do
            ok, reason = validate()

            if not ok then
                return false, reason
            end
            if needsRise then
                if options.status then
                    options.status('Travelling')
                end

                local humanoid = character:FindFirstChildOfClass('Humanoid')

                if humanoid then
                    humanoid:UnequipTools()
                end

                root.AssemblyLinearVelocity = Vector3.zero
                root.CFrame = root.CFrame + Vector3.new(0, targetY - root.Position.Y, 0)

                task.wait(0.1)

                ok, reason = validate()

                if not ok then
                    return false, reason
                end
            end

            local traveler

            if not needsRise or math.abs(root.Position.Y - targetY) <= 100 then
                traveler = travelRecovery.new(launchTarget, true, options.speed or 180)

                while not traveler.status() do
                    ok, reason = validate()

                    if not ok then
                        traveler.stop()

                        return false, reason
                    end
                    if needsRise and math.abs(root.Position.Y - targetY) > 100 then
                        traveler.stop()

                        break
                    end

                    task.wait(0.05)
                end

                local travelStatus = traveler.status()

                if travelStatus == 'arrived' then
                    ok, reason = validate()

                    if not ok then
                        return false, reason
                    end
                    if needsRise then
                        traveler.stop()

                        local onTarget = false

                        for attempt = 0, 2 do
                            ok, reason = validate()

                            if not ok then
                                return false, reason
                            end
                            if options.status then
                                options.status('Travelling')
                            end

                            root.AssemblyLinearVelocity = Vector3.zero
                            root.AssemblyAngularVelocity = Vector3.zero
                            root.CFrame = destination
                            onTarget = true

                            for waitIndex = 1, 5 do
                                task.wait(0.1)

                                ok, reason = validate()

                                if not ok then
                                    return false, reason
                                end
                                if (root.Position - destination.Position).Magnitude > 25 then
                                    onTarget = false

                                    break
                                end
                            end

                            if onTarget then
                                break
                            end
                        end

                        if not onTarget then
                            return false, 'server repeatedly rejected sky landing'
                        end
                    end
                    if queue then
                        executionQueue.checkpoint(queue.owner, true, 'arrived')
                    end

                    return true, 'arrived'
                end
                if not needsRise or math.abs(root.Position.Y - targetY) <= 100 then
                    return false, travelStatus
                end
            end

            attemptCount = attemptCount + 1

            if attemptCount > 2 then
                return false, 'server repeatedly rejected sky altitude'
            end
        end

        return false, 'cancelled'
    end

    return module
end


return aa()

