    local action4Priority = Enum.AnimationPriority.Action4
    local al = {
        'rbxassetid://72537613591894',
        'rbxassetid://94401200412230',
        'rbxassetid://100615685249881',
    }
    local am = {
        M1 = true,
        Mantra = true,
        Critical = true,
    }
    local random = Random.new(os.clock() * 1000)
    local collectTimingIds = function()
        local seenIds = {}
        local ids = {}
        local data = ad and ad.as
        local filterTimingsByTag = function(source)
            if not source or not source.timings then
                return
            end

            for id, timing in next, source.timings do
                if not timing then
                    continue
                end
                if not am[timing.tag] then
                    continue
                end

                local assetId = tostring(id)

                if not assetId:match('rbxassetid://') then
                    continue
                end
                if seenIds[assetId] then
                    continue
                end

                seenIds[assetId] = true
                ids[#ids + 1] = assetId
            end
        end

        if data then
            filterTimingsByTag(data.internal)
            filterTimingsByTag(data.config)
        end
        if #ids == 0 then
            for index, fallbackId in ipairs(al)do
                if not seenIds[fallbackId] then
                    seenIds[fallbackId] = true
                    ids[#ids + 1] = fallbackId
                end
            end
        end

        for shuffleIndex = #ids, 2, -1 do
            local swapIndex = random:NextInteger(1, shuffleIndex)

            ids[shuffleIndex], ids[swapIndex] = ids[swapIndex], ids[shuffleIndex]
        end

        if #ids > 32 then
            for trimIndex = #ids, 32 + 1, -1 do
                ids[trimIndex] = nil
            end
