    local createAnimation = function(animId)
        local animation = Instance.new('Animation')

        animation.AnimationId = animId
        animation.Name = 'PALANTIRX'

        return animation
    end
    local aq = function(character)
        if not character then
            return function() end
        end

        local humanoid = character:FindFirstChildOfClass('Humanoid')

        if not humanoid then
            return function() end
        end

        local animator = humanoid:FindFirstChildOfClass('Animator')

        if not animator then
            return function() end
        end

        local active = true
        local connection
        local swapping = false

        connection = animator.AnimationPlayed:Connect(LPH_NO_VIRTUALIZE(function(track)
            if not active then
                return
            end
            if weakSet[track] then
                return
            end
            if track.Priority == Enum.AnimationPriority.Core then
                return
            end
            if track.Priority == Enum.AnimationPriority.Idle then
                return
            end
            if swapping then
                return
            end

            local playedAnimation = track.Animation

            if not playedAnimation then
                return
            end

            local entry = ad.as:index(tostring(playedAnimation.AnimationId))

            if not entry then
                return
            end

            local swapTags = configuration.expectOptionValue('ApBreakerSwapTags')

            if type(swapTags) ~= 'table' or not swapTags[entry.tag] then
                return
            end
            if track.Looped or track.Length <= 0 then
                return
