            end
            if apc.fadeCheck and track.IsPlaying and target > 0 and weight < target * apc.fadeRatio then
                return reject(state, character, track, seq, aid, 'FadeTime AP break (WC=%.4f / WT=%.4f at 0.05s)', weight, target)
            end
            if apc.windowCheck and weight <= apc.earlyWeight then
                return reject(state, character, track, seq, aid, 'early-window AP break (WC=%.6f)', weight)
            end
        end)

        local rampDelay = state.flagged and 0.06 or 0.08

        task.delay(rampDelay, function()
            if state.seq ~= seq or state.track ~= track then
                return
            end

            local weight = readWeights(track)
            local playing = track.IsPlaying
            local length = track.Length or 0
            local position = track.TimePosition or 0

            if not timing.iae and not playing and position < length then
                return reject(state, character, track, seq, aid, 'ramp check (track killed at %.3fs)', position)
            end
            if playing and type(weight) == 'number' and weight < apc.judgeWeight then
                return reject(state, character, track, seq, aid, 'ramp check (WC=%.4f at %.2fs)', weight, rampDelay)
            end
        end)

        task.delay(0.25, function()
            if state.seq ~= seq or state.track ~= track then
                return
            end

            local weight, target = readWeights(track)

            if type(weight) ~= 'number' or not track.IsPlaying then
                return
            end
            if apc.lateCheck and weight < apc.lateWeight then
                return reject(state, character, track, seq, aid, 'post check (WC=%.4f at 0.25s)', weight)
            end
            if apc.windowCheck and type(target) == 'number' and target > 0 and weight <= target * apc.lateRatio and weight <= apc.lateCeiling then
                return reject(state, character, track, seq, aid, 'late-window AP break (WC=%.6f, WT=%.4f)', weight, target)
            end
        end)
    end
    function apc.count(character)
        local state = character and states[character]

        if not state then
            return 0
        end

        return state.seq
    end
    function apc.flagged(character)
        local state = character and states[character]

        return state ~= nil and state.flagged or false
    end
    function apc.reset(character)
        if character then
            states[character] = nil

            return
        end

        states = setmetatable({}, {
            __mode = 'k',
        })
    end

    return apc
end


return aa()

]=],
    ["Features/Combat/AnimationFilter"] = [=[
local aa = function()
    local players = game:GetService('Players')
    local logger = a["Utility/Logger"]()
    local apcGuard = a["Features/Combat/APCGuard"]()
    local config = {}

    config.on = false
    -- APC Guard is the default engine: it mirrors the reference
    -- AnimatorDefender (Lycoris/Luma) AP-break detection.
    config.apc = true
    -- The granular bank below stays available, but only runs when enabled.
    config.legacy = false
    config.corePriority = false
    config.idlePriority = false
    config.movementPriority = false
    config.actionPriority = false
    config.speedFilter = false
    config.maxSpeed = 10
    config.minSpeed = 0.5
    config.wtFilter = false
    config.wtMin = 0.1
    config.wtMax = 0.4
    config.wcFilter = false
    config.wcMin = 0.1
    config.wcMax = 10
    config.endSkip = false
    config.endSkipPct = 90
    config.lengthFilter = false
    config.minLengthMs = 0
    config.ghostFilter = false
    config.spam = false
    config.spamWindow = 1
    config.spamThreshold = 2
    config.spamPermaBlock = false
    config.highFade = false
    config.maxFadeSec = 3
    config.minFadeMs = 1
    config.fadeSampleMs = 16
    config.animGap = false
    config.minGap = 0.05
    config.globalSpam = false
    config.globalSpamWindow = 2
    config.globalSpamThreshold = 4
    config.maxActive = false
    config.maxActiveCount = 4
    config.earlyStop = false
    config.earlyStopMs = 150
    config.ignoreAnimEnd = false
    config.forceIgnoreAnimEnd = false
    config.forceIgnoreM1Only = false
    config.ignoreEarlyAnimEnd = false
    config.ignoreEarlyAnimEndMs = 50
    config.debugAnimCancels = false

    local localFlags = setmetatable({}, {
        __mode = 'k',
    })
    local animStates = setmetatable({}, {
        __mode = 'k',
    })
    local remoteCache = setmetatable({}, {
        __mode = 'k',
    })
    local handlerRegistry = setmetatable({}, {
        __mode = 'k',
    })
    local getFlags = function(character)
        return character ~= nil and players:GetPlayerFromCharacter(character) ~= nil
    end
    local setFlags = function(times, now, window)
        local count = 0

        for index = 1, #times do
            if now - times[index] <= window then
                count = count + 1
                times[count] = times[index]
            end
        end
        for index = #times, count + 1, -1 do
            times[index] = nil
        end
    end

    function config.quick(character, animation, animType)
        if not config.on then
            return false
        end
        if config.apc and apcGuard.quick(character, animation, animType) then
            return true
        end
        if not config.legacy then
            return false
        end

        local priority = animation.Priority

        if config.corePriority and priority == Enum.AnimationPriority.Core then
            return true
        end
        if config.idlePriority and priority == Enum.AnimationPriority.Idle then
            return true
        end
        if config.movementPriority and priority == Enum.AnimationPriority.Movement then
            return true
        end
        if config.actionPriority and priority == Enum.AnimationPriority.Action then
            return true
        end
        if config.speedFilter and animation.Speed >= config.maxSpeed then
            return true
        end
        if not getFlags(character) then
            return false
        end
        if config.wtFilter and (animation.WeightTarget < config.wtMin or animation.WeightTarget > config.wtMax) then
            return true
        end
        if config.wcFilter and (animation.WeightCurrent < config.wcMin or animation.WeightCurrent > config.wcMax) then
            return true
        end
        if config.endSkip and animation.Length > 0 and animation.TimePosition >= animation.Length * (config.endSkipPct / 100) then
            return true
        end
        if config.lengthFilter and config.minLengthMs > 0 and animation.Length * 1000 < config.minLengthMs then
            return true
        end
        if config.speedFilter and config.minSpeed > 0 and animation.Speed < config.minSpeed then
            return true
        end
        if config.ghostFilter and animation.IsPlaying then
            local humanoid = character:FindFirstChildOfClass('Humanoid')

            if humanoid and not table.find(humanoid:GetPlayingAnimationTracks(), animation) then
                return true
            end
        end
        if config.spam and animType then
            local states = animStates[character]

            if states and states[animType] then
                return true
            end

            local flags = localFlags[character]

            if not flags then
                flags = {}
                localFlags[character] = flags
            end

            local times = flags[animType]

            if not times then
                times = {}
                flags[animType] = times
            end

            local now = os.clock()

            setFlags(times, now, config.spamWindow)

            times[#times + 1] = now

            if #times > config.spamThreshold then
                if config.spamPermaBlock then
                    if not states then
                        states = {}
                        animStates[character] = states
                    end

                    states[animType] = true
                end

                return true
            end
        end

        return false
    end
    function config.sample(character, animation, callback)
        if not (config.on and config.legacy and config.highFade and getFlags(character)) then
            callback(true)

            return
        end

        local fadeSampleSec = config.fadeSampleMs / 1000

        task.delay(fadeSampleSec, function()
            local weightTarget = animation.WeightTarget or 0
            local weightCurrent = animation.WeightCurrent or 0

            if not animation.IsPlaying then
                return callback(config.minFadeMs <= 0)
            end
            if weightTarget <= 0.05 then
                return callback(true)
            end

            local fadeTime = weightCurrent <= 1e-5 and math.huge or (fadeSampleSec * weightTarget / weightCurrent)

            if fadeTime > config.maxFadeSec then
                return callback(false)
            end
            if config.minFadeMs > 0 and fadeTime < config.minFadeMs / 1000 then
                return callback(false)
            end

            callback(true)
        end)
    end
    function config.watchEarlyStop(character, animation, animType, callback, state)
        if not (config.on and config.legacy and config.earlyStop and getFlags(character)) then
            return
        end

        task.delay(config.earlyStopMs / 1000, function()
            if animation.IsPlaying then
                return
            end
            if state and state.iae then
                local notEnded = (animation.TimePosition or 0) < (animation.Length or 0)

                if not notEnded or state.ieae then
                    if config.debugAnimCancels then
                        logger.trace(
"suppressed early-stop cancel (timing outlives the animation)")
                    end

                    return
                end
            end
            if config.ignoreAnimEnd or (config.forceIgnoreAnimEnd and not config.forceIgnoreM1Only) then
                if config.debugAnimCancels then
                    logger.trace('suppressed early-stop cancel (ignore anim end)')
                end

                return
            end
            if config.forceIgnoreM1Only and animType == 'm1' then
                if config.debugAnimCancels then
                    logger.trace('suppressed early-stop cancel (m1 only)')
                end

                return
            end
            if config.ignoreEarlyAnimEnd and config.earlyStopMs <= config.ignoreEarlyAnimEndMs then
                if config.debugAnimCancels then
                    logger.trace('suppressed early-stop cancel (below ignore threshold)')
                end

                return
            end
            if config.debugAnimCancels then
                logger.trace('early-stop cancelled a pending reaction')
            end

            callback()
        end)
    end
    function config.postMatch(animationName, activeCount)
        if not (config.on and config.legacy and getFlags(animationName)) then
            return false
        end

        local currentTime = os.clock()

        if config.animGap then
            local lastHandler = handlerRegistry[animationName]

            if lastHandler and currentTime - lastHandler < config.minGap then
                return true
            end
        end
        if config.globalSpam then
            local remoteQueue = remoteCache[animationName]

            if not remoteQueue then
                remoteQueue = {}
                remoteCache[animationName] = remoteQueue
            end

            setFlags(remoteQueue, currentTime, config.globalSpamWindow)

            remoteQueue[#remoteQueue + 1] = currentTime

            if #remoteQueue > config.globalSpamThreshold then
                return true
            end
        end
        if config.maxActive and (activeCount or 0) >= config.maxActiveCount then
            return true
        end

        handlerRegistry[animationName] = currentTime

        return false
    end
    -- Asynchronous dispatch gate for entities flagged as AP breakers. Calls
    -- back with (allow, gateDelaySeconds); the caller must shift its reaction
    -- timing by gateDelay to stay aligned with the animation start.
    function config.gate(character, animation, animId, callback)
        if not (config.on and config.apc) then
            return callback(true, 0)
        end

        apcGuard.gate(character, animation, animId, callback)
    end
    -- Registers an animation that produced a timing so the APC post-dispatch
    -- checks (fade inference, weight windows, ramp, late sample) can run.
    function config.observe(character, animation, animId, timing)
        if not (config.on and config.apc) then
            return
        end

        apcGuard.observe(character, animation, animId, timing)
    end

    return config
end


return aa()

]=],
    ["Features/Combat/ArdourSpam"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local feature = a["Features/Feature"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local ae = 0
    local af = false
    local findRemote = function()
        local localPlayer = players.LocalPlayer

        if not localPlayer then
            return nil
        end

        local backpack = localPlayer:FindFirstChild('Backpack')
        local talent = backpack and backpack:FindFirstChild('Talent:Ardour Scream')

        if not talent then
            local character = localPlayer.Character

            talent = character and character:FindFirstChild('Talent:Ardour Scream')
        end
        if not talent then
            return nil
        end

        return talent:FindFirstChild('ActivateRt')
    end
    local getInterval = function()
        local interval = tonumber(configuration.expectOptionValue('ArdourSpamInterval'))

        if not interval or interval < 0.03 then
            return 0.03
        end

        return interval
    end
    local fireRemote = function()
        local remote = findRemote()

        if not remote then
            return false
        end

        local success = pcall(function()
            remote:FireServer()
        end)

        return success
    end
    local isOnceMode = function()
        return configuration.expectOptionValue('ArdourSpamMode') == 'Once'
    end
    local disableToggle = function()
        if Toggles and Toggles.ArdourSpam then
            pcall(function()
                Toggles.ArdourSpam:SetValue(false)
            end)
        end
    end
    local ardourSpam = feature.new('ArdourSpam', runService.Heartbeat, function()
        if isOnceMode() then
            if af then
                return
            end

            af = true

            fireRemote()
            disableToggle()

            return
        end

        local now = os.clock()

        if now < ae then
            return
        end

        ae = now + getInterval()

        fireRemote()
    end)

    function ardourSpam:onEnable()
        ae = 0
        af = false
    end

    return ardourSpam
end


return aa()

]=],
    ["Features/Combat/AutoAssassinate"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local ac = {
        left = function() end,
    }
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local playerScanning = a["Game/PlayerScanning"]()
    local signal = a["Utility/Signal"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')

    game:GetService('RunService')

    local newMaid = maid.new()
    local al
    local am
    local an
    local ao
    local ap = false
    local aq = 0
    local ar = {}
    local as = {}
    local getEffectReplicator = function()
        local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local ok, effectModule = pcall(require, effectReplicator)

        return ok and effectModule or nil
    end
    local hasCrouchEffect = function()
        local replicator = getEffectReplicator()

        return replicator ~= nil and replicator:FindEffect('ClientCrouch') and true or false
    end
    local isBehindTarget = function(source, target)
        local targetCFrame = target.CFrame
        local lookVector = targetCFrame.LookVector
        local backVector = -lookVector
        local anchorPoint = target.Position + backVector * 1.5
        local fromAnchor = source.Position - anchorPoint
        local distance = fromAnchor.Magnitude

        if distance > 15 then
            return false
        end
        if distance < 0.01 then
            return false
        end

        local toSource = (source.Position - target.Position)

        if toSource.Magnitude < 0.01 then
            return false
        end
        if backVector:Dot(toSource.Unit) < 0.8 then
            return false
        end

        local toTarget = (target.Position - source.Position)

        if toTarget.Magnitude < 0.01 then
            return false
        end

        local toTargetUnit = toTarget.Unit
        local camera = workspace.CurrentCamera

        if camera then
            if camera.CFrame.LookVector:Dot(toTargetUnit) < 0.7 then
                return false
            end
        end
        if source.CFrame.LookVector:Dot(toTargetUnit) < 0.7 then
            return false
        end

        return true, distance
    end
    local findNearestTarget = function(checkAllies)
        local localPlayer = players.LocalPlayer
        local character = localPlayer and localPlayer.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')

        if not root then
            return nil
        end

        local now = os.clock()
        local bestTarget
        local bestDistance = math.huge

        for index, candidate in ipairs(players:GetPlayers())do
            if candidate == localPlayer then
                continue
            end
            if checkAllies and playerScanning.isAlly and playerScanning.isAlly(candidate) then
                continue
            end

            local cooldown = ar[candidate.Name]

            if cooldown and cooldown > now then
                continue
            end

            local otherCharacter = candidate.Character
            local targetRoot = otherCharacter and otherCharacter:FindFirstChild('HumanoidRootPart')

            if not targetRoot then
                continue
            end

            local targetHumanoid = otherCharacter:FindFirstChildOfClass('Humanoid')

            if not targetHumanoid or targetHumanoid.Health <= 0 then
                continue
            end

            local visible, targetDistance = isBehindTarget(root, targetRoot)

            if visible and targetDistance < bestDistance then
                bestTarget = targetRoot
                bestDistance = targetDistance
            end
        end

        return bestTarget
    end
    local getCharacterHandler = function()
        local me = players.LocalPlayer
        local myCharacter = me and me.Character

        if not myCharacter then
            return nil
        end

        local characterHandler = myCharacter:FindFirstChild('CharacterHandler')

        if not characterHandler then
            return nil
        end

        return characterHandler:FindFirstChild('Requests')
    end
    local fireCharacterRequest = function(requestName, ...)
        local requests = getCharacterHandler()

        if not requests then
            return false
        end

        local remote = requests:FindFirstChild(requestName)

        if not remote then
            return false
        end

        remote:FireServer(...)

        return true
    end
    local findCrouchAnimation = function()
        local assets = replicatedStorage:FindFirstChild('Assets')
        local anims = assets and assets:FindFirstChild('Anims')
        local movement = anims and anims:FindFirstChild('Movement')

        return movement and movement:FindFirstChild('Crouch')
    end
    local playCrouchAnimation = function()
        local selfPlayer = players.LocalPlayer
        local playerCharacter = selfPlayer and selfPlayer.Character
        local humanoid = playerCharacter and playerCharacter:FindFirstChildOfClass('Humanoid')

        if not humanoid then
            return
        end

        local crouchAnim = findCrouchAnimation()

        if crouchAnim and not ao then
            local loaded, animTrack = pcall(function()
                return humanoid:LoadAnimation(crouchAnim)
            end)

            if loaded and animTrack then
                pcall(function()
                    animTrack:Play()
                end)

                ao = animTrack
            end
        end

        fireCharacterRequest('ServerCrouch', true)

        local fxReplicator = getEffectReplicator()

        if fxReplicator and not (an and an.Parent) then
            local success, effect = pcall(function()
                return fxReplicator:CreateEffect('ClientCrouch')
            end)

            if success then
                an = effect
            end
        end
    end
    local cancelCrouch = function()
        fireCharacterRequest('ServerCrouch', false)

        if ao then
            pcall(function()
                ao:Stop()
            end)

            ao = nil
        end
        if an and an.Parent then
            pcall(function()
                an:Remove()
            end)
        end

        an = nil
    end
    local checkDustlungeTalent = function()
        local now = os.clock()

        if now - aq < 2 then
            return ap
        end

        aq = now

        local player = players.LocalPlayer
        local playerGui = player and player:FindFirstChild('PlayerGui')
        local backpackGui = playerGui and playerGui:FindFirstChild('BackpackGui')
        local rightFrame = backpackGui and backpackGui:FindFirstChild('RightFrame')
        local talentSheet = rightFrame and rightFrame:FindFirstChild('TalentSheet')
        local container = talentSheet and talentSheet:FindFirstChild('Container')
        local talentScroll = container and container:FindFirstChild('TalentScroll')
        local owned = talentScroll and talentScroll:FindFirstChild('Owned')
        local dustlunge = owned and owned:FindFirstChild('Dustlunge')

        ap = dustlunge ~= nil

        return ap
    end
    local toggleNoSprint = function(enabled)
        local effects = getEffectReplicator()

        if not effects then
            return
        end
        if enabled then
            if not (al and al.Parent) then
                local ok, effect = pcall(function()
                    return effects:CreateEffect('NoSprint')
                end)

                if ok then
                    al = effect
                end
            end
            if not (am and am.Parent) then
                local succeeded, createdEffect = pcall(function()
                    return effects:CreateEffect('NoSlide')
                end)

                if succeeded then
                    am = createdEffect
                end
            end
        else
            if al and al.Parent then
                pcall(function()
                    al:Remove()
                end)
            end

            al = nil

            if am and am.Parent then
                pcall(function()
                    am:Remove()
                end)
            end

            am = nil
        end
    end
    local zeroHorizontalVelocity = function(rootPart)
        local velocity = rootPart.AssemblyLinearVelocity

        rootPart.AssemblyLinearVelocity = Vector3.new(0, velocity.Y, 0)
    end
    local aG = false
    local startAutoAssassinate = function()
        if aG then
            return
        end

        aG = true

        local runAutoAssassinateChecks, errorMsg = pcall(function()
            if not configuration.expectToggleValue('AutoAssassinate') then
                logger.warnNotify('Assassinate \u{2014} feature toggle is off.')

                return
            end

            local requireDustlunge = configuration.expectToggleValue('AutoAssassinateRequireDustlunge') == true

            if requireDustlunge and not checkDustlungeTalent() then
                logger.warnNotify('Assassinate \u{2014} Dustlunge talent required (toggle on).')

                return
            end

            local localPlayer = players.LocalPlayer
            local character = localPlayer and localPlayer.Character
            local root = character and character:FindFirstChild('HumanoidRootPart')

            if not root then
                logger.warnNotify('Assassinate \u{2014} no HumanoidRootPart.')

                return
            end

            zeroHorizontalVelocity(root)

            local blockSprint = configuration.expectToggleValue('AutoAssassinateBlockSprint') == true

            if blockSprint then
                toggleNoSprint(true)
            end

            local filterAllies = configuration.expectToggleValue('AutoAssassinateFilterAllies') == true
            local target = findNearestTarget(filterAllies)

            if not target then
                if blockSprint then
                    toggleNoSprint(false)
                end

                logger.warnNotify('Assassinate \u{2014} no valid target (behind, facing, in range, off cooldown).')

                return
            end

            local dashed = false

            if not hasCrouchEffect() then
                playCrouchAnimation()

                dashed = true

                task.wait(0.05)
            end

            local timestamp = os.clock()
            local targetCharacter = target:FindFirstAncestorWhichIsA('Model')
            local targetPlayer = targetCharacter and players:GetPlayerFromCharacter(targetCharacter)

            if targetPlayer then
                as[targetPlayer.Name] = timestamp + 1.5
            end

            local clicked = pcall(ac.left, CFrame.new(target.Position), true)

            if not clicked then
                logger.warn('AutoAssassinate: InputClient.left failed.')
            end

            task.delay(0.25, function()
                if dashed then
                    cancelCrouch()
                end
                if blockSprint then
                    toggleNoSprint(false)
                end
            end)
        end)

        aG = false

        if not runAutoAssassinateChecks then
            logger.warn('Assassinate: %s', tostring(errorMsg))
        end
    end

    function module.attempt()
        startAutoAssassinate()
    end

    local onDamagedAnother = function(effect)
        if not effect or effect.Class ~= 'DamagedAnother' then
            return
        end

        local targetName = effect.Value

        if type(targetName) ~= 'string' or targetName == '' then
            return
        end

        local localPlayer = players.LocalPlayer

        if localPlayer and targetName == localPlayer.Name then
            return
        end

        local cooldown = as[targetName]

        if not cooldown or cooldown < os.clock() then
            return
        end

        as[targetName] = nil
        ar[targetName] = os.clock() + 120

        logger.warn('AutoAssassinate: %s assassinated \u{2014} %ds cooldown.', targetName, 120)
    end

    function module.init()
        task.spawn(function()
            task.wait(0.5)

            local localTile = getEffectReplicator()

            if not localTile then
                return
            end

            for index, effectName in ipairs({
                'NoSprint',
                'NoSlide',
            })do
                while true do
                    local foundEffect = localTile:FindEffect(effectName)

                    if not foundEffect or not foundEffect.Parent then
                        break
                    end

                    local success = pcall(function()
                        foundEffect:Remove()
                    end)

                    if not success then
                        break
                    end
                end
            end
        end)
        task.spawn(function()
            local ok, replicator = pcall(function()
                local replicatorInstance = replicatedStorage:WaitForChild('EffectReplicator', 10)

                return replicatorInstance and require(replicatorInstance)
            end)

            if not ok or not replicator then
                logger.warn('AutoAssassinate: EffectReplicator unavailable \u{2014} cooldown disabled.')

                return
            end

            newMaid:add(signal.new(replicator.EffectAdded):connect('AutoAssassinate_EffectAdded', onDamagedAnother))
        end)
        logger.warn('AutoAssassinate initialized.')
    end
    function module.detach()
        toggleNoSprint(false)
        cancelCrouch()
        newMaid:clean()
    end

    return module
end


return aa()

]=],
    ["Features/Combat/AutoParry"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local animationHooks = a["Game/AnimationHooks"]()
    local animationFilter = a["Features/Combat/AnimationFilter"]()
    local effectReplicator = a["Game/EffectReplicator"]()
    local effectTracker = a["Game/EffectTracker"]()
    local autoParry = a["Features/Combat/AutoParry2"]()
    local hitboxProbe = a["Game/HitboxProbe"]()
    local feintCue = a["Game/Timings/FeintCue"]()
    local autoParryBlockers = a["Features/Combat/AutoParryBlockers"]()
    local effectBatcher = a["Game/EffectBatcher"]()
    local actionRunner = a["Game/Timings/ActionRunner"]()
    local moduleManager = a["Game/Timings/ModuleManager"]()
    local configSection = a["Menu/ConfigSection"]()
    local partTriggers = a["Game/Timings/PartTriggers"]()
    local queuedBlocking = a["Game/QueuedBlocking"]()
    local scheduler = a["Game/Timings/Scheduler"]()
    local audioScanner = a["Game/Timings/AudioScanner"]()
    local stateListener = a["Features/Combat/StateListener"]()
    local targetScanner = a["Game/TargetScanner"]()
    local players = game:GetService('Players')
    local av = {}
    local shouldExecuteChance = function(shouldTrigger)
        return shouldTrigger and shouldTrigger > 0 and math.random(1, 100) <= shouldTrigger
    end

    function av.find(fullMarker)
        local kind, marker = fullMarker:match('^(%a+):(.*)$')

        if not kind then
            return nil
        end

        local section

        if kind == 'anim' then
            section = configSection.as
            marker = marker:match('(%d+)%s*$') or marker
        elseif kind == 'sound' then
            section = configSection.ss
            marker = marker:match('(%d+)%s*$') or marker
        elseif kind == 'part' then
            section = configSection.ps
        elseif kind == 'effect' then
            section = configSection.es
        end
        if not section then
            return nil
        end

        return section:index(marker), kind
    end

    local handleParryAttack = function(attacker, marker, track, part, queue, argC, data, meta)
        if attacker and attacker == a["Features/Game/NoEffects"]().automation.ferryman_target then
            local animId = marker:match('^anim:.-(%d+)$')

            if animId == '8183996606' or animId == '5968288116' then
                return
            end
        end
        if not configuration.expectToggleValue('EnableAutoParry') then
            return
        end

        local timing, sourceKind = av.find(marker)
        local trialParry = a["Features/Game/NoEffects"]().automation.trial_parry

        if trialParry and attacker and not players:GetPlayerFromCharacter(attacker) then
            local animId = marker:match('^anim:.-(%d+)$')

            if animId and trialParry.timings[animId] then
                timing, sourceKind = trialParry.timings[animId], 'anim'
                trialParry.entities[attacker] = true
            elseif marker == 'effect:GolemLaserFire' and data and typeof(data.aimPos) == 'Vector3' then
                local char = players.LocalPlayer.Character
                local root = char and char:FindFirstChild('HumanoidRootPart')
                local target = attacker:FindFirstChild('Target')

                if root and (root.Position - data.aimPos).Magnitude <= 30 and (not target or target.Value == char) then
                    timing, sourceKind = trialParry.timings[marker], 'effect'
                    trialParry.entities[attacker] = true
                end
            end
        end
        if not timing then
            effectBatcher.add(marker, attacker)

            return
        end

        local localChar = players.LocalPlayer and players.LocalPlayer.Character

        if sourceKind == 'sound' and not timing.alp and attacker and attacker == localChar then
            return actionRunner.note(timing, 'Sound came from the local player.')
        end
        if sourceKind == 'effect' then
            if timing.ilp and attacker and attacker == localChar then
                return actionRunner.note(timing, 'Effect came from the local player.')
            end
            if timing.flp and attacker ~= localChar then
                return actionRunner.note(timing, 'Effect did not come from the local player.')
            end
        end
        if sourceKind == 'anim' and attacker and timing.ftag and timing.ftag ~= 'Any' then
            local isPlayer = players:GetPlayerFromCharacter(attacker) ~= nil

            if timing.ftag == 'Mob' and isPlayer then
                return actionRunner.note(timing, 'Mob animation played by a player, likely an AP breaker.')
            end
            if timing.ftag == 'Player' and not isPlayer then
                return actionRunner.note(timing, 'Player animation played by a mob.')
            end
        end
        if sourceKind == 'anim' and attacker and not players:GetPlayerFromCharacter(attacker) then
            local root = attacker:FindFirstChild('HumanoidRootPart')

            if root and root:FindFirstChild('MegalodauntBroken') then
                return actionRunner.note(timing, 'Entity is block broken.')
            end
        end

        local blockedNote = autoParryBlockers.blocked()

        if blockedNote then
            actionRunner.note(timing, blockedNote)

            return
        end
        if attacker and sourceKind ~= 'part' and not targetScanner.is(attacker) then
            if targetScanner.near(attacker) then
                actionRunner.note(timing, 'Not a viable target.')
            end

            return
        end
        if attacker and sourceKind ~= 'part' then
            if players:GetPlayerFromCharacter(attacker) then
                if shouldExecuteChance(configuration.expectOptionValue('APIgnorePlayers')) then
                    return
                end
            elseif shouldExecuteChance(configuration.expectOptionValue('APIgnoreMobs')) then
                return
            end
        end
        if attacker and animationFilter.postMatch(attacker, actionRunner.pending(attacker)) then
            actionRunner.note(timing, 'Blocked by anti-exploit filters.')

            return
        end

        local allowFailure = configuration.expectToggleValue('APAllowFailure')

        if allowFailure and shouldExecuteChance(configuration.expectOptionValue('APFailureRate')) then
            actionRunner.note(timing, 'Intentionally did not run.')

            return
        end

        if attacker and sourceKind == 'anim' and track then
            animationFilter.observe(attacker, track, marker, timing)
        end

        actionRunner.run(attacker, timing, {
            kind = sourceKind,
            track = track,
            part = part,
            data = data,
            gateDelay = meta and meta.gateDelay or nil,
            rollInstead = allowFailure and shouldExecuteChance(configuration.expectOptionValue('APRollInsteadOfParryRate')) or false,
        })

        if attacker then
            feintCue.watch(attacker, track, timing, function()
                actionRunner.cancel(attacker, sourceKind)
                actionRunner.note(timing, 'Feinted; dropped everything pending for this attacker.')
            end)
        end
        if attacker and track then
            animationFilter.watchEarlyStop(attacker, track, nil, function()
                actionRunner.cancel(attacker, sourceKind)
            end, timing)
        end
    end

    function av.load()
        configSection.init()
    end
    function av.init()
        scheduler.start()
        effectTracker.init()
        queuedBlocking.init()
        moduleManager.refresh()
        stateListener.init()
        autoParry.watch()
        configSection.init()
        actionRunner.onAction(function(source, kind, detail, params)
            if params then
                feintCue.drop(params)
            end
        end)
        animationHooks.onTrigger(handleParryAttack)
        audioScanner.onTrigger(handleParryAttack)
        partTriggers.onTrigger(handleParryAttack)
        effectReplicator.onTrigger(handleParryAttack)
        animationHooks.init()
        audioScanner.init()
        targetScanner.init()
        partTriggers.init()
        effectReplicator.init()
    end
    function av.detach()
        stateListener.detach()
        moduleManager.detach()
        configSection.detach()
        partTriggers.detach()
        effectReplicator.detach()
        animationHooks.detach()
        audioScanner.detach()
        targetScanner.detach()
        effectBatcher.detach()
        feintCue.detach()
        autoParry.unupgrade()
        hitboxProbe.clearVisuals()
        queuedBlocking.detach()
        effectTracker.detach()
        scheduler.stop()
    end

    return av
end


return aa()

]=],
    ["Features/Combat/AutoParry2"] = [=[
local aa = function()
    local action = a["Game/Timings/Action"]()
    local configuration = a["Utility/Configuration"]()
    local effectTracker = a["Game/EffectTracker"]()
    local hitboxProbe = a["Game/HitboxProbe"]()
    local characterActions = a["Game/CharacterActions"]()
    local queuedBlocking = a["Game/QueuedBlocking"]()
    local scheduler = a["Game/Timings/Scheduler"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local module = {}

    module.allowed = {
        Block = true,
        Dodge = true,
    }
    module.blockHold = 0.3
    module.highPosture = 80
    module.facingDot = 0

    local getBreakMeterPercent = function()
        local localPlayer = players.LocalPlayer
        local breakMeter = localPlayer and localPlayer.Character and localPlayer.Character:FindFirstChild('BreakMeter')

        if not breakMeter or not breakMeter.MaxValue or breakMeter.MaxValue <= 0 then
            return 0
        end

        return breakMeter.Value / breakMeter.MaxValue * 100
    end
    local isTargetBehind = function(target)
        local player = players.LocalPlayer
        local localRoot = player and player.Character and hitboxProbe.root(player.Character)
        local targetRoot = target and hitboxProbe.root(target)

        if not (localRoot and targetRoot) then
            return true
        end

        local cframe = localRoot.CFrame
        local lookVector = cframe and cframe.LookVector
        local direction = targetRoot.Position - localRoot.Position

        if not lookVector or direction.Magnitude < 0.01 then
            return true
        end

        return lookVector:Dot(direction.Unit) > module.facingDot
    end
    local pickFlagValue = function(source, fallback, flag)
        if source and source[flag] ~= nil then
            return source[flag]
        end

        return fallback and fallback[flag]
    end
    local canBlockSafely = function(primaryFlags, fallbackFlags)
        if not pickFlagValue(fallbackFlags, primaryFlags, 'ihp') and getBreakMeterPercent() >= module.highPosture then
            return false, 'posture is too high to block safely'
        end

        return true
    end
    local shouldBlock = function(character, attacker, flags)
        if not pickFlagValue(flags, character, 'ibfc') and not isTargetBehind(attacker) then
            return false, 'the attacker is behind us'
        end

        return canBlockSafely(character, flags)
    end
    local hasMantraSubstitution = function()
        local mantraSub = configuration.expectOptionValue('MantraSubstitution')

        if type(mantraSub) ~= 'table' then
            return false
        end

        for key, value in next, mantraSub do
            if value then
                return true
            end
        end

        return false
    end
    local aq = {
        {
            any = {
                'DodgedFrame',
            },
            why = 'already in dodge frames',
            flag = 'idf',
        },
    }
    local ar = {
        {
            any = {
                'AutoParry',
            },
            why = 'an auto parry is already running',
            flag = 'iapf',
            pvp = true,
        },
    }

    module.apframes = ar

    local concatLists = function(...)
        local result = {}

        for i = 1, select('#', ...)do
            local list = select(i, ...)

            for j = 1, #list do
                result[#result + 1] = list[j]
            end
        end

        return result
    end
    local at = concatLists(aq, {
        {
            any = {
                'Immortal',
            },
            why = 'immortal',
        },
        {
            any = {
                'iframe',
            },
            why = 'in i-frames',
        },
        {
            any = {
                'SpellActive',
            },
            why = 'a spell is active',
        },
    })
    local au = {
        Parry = concatLists(at, ar, {
            {
                need = 'Equipped',
                why = 'nothing is equipped',
            },
            {
                any = {
                    'ParryCool',
                },
                why = 'parry is on cooldown',
                flag = 'ipc',
            },
            {
                any = {
                    'MidAttack',
                },
                why = 'mid attack',
            },
            {
                any = {
                    'PaybackHealTally',
                    'DelayedPayback',
                },
                why = 'payback is banking damage',
                filter = 'Disable While In Payback',
            },
        }),
        Block = concatLists(at, ar, {
            {
                need = 'Equipped',
                why = 'nothing is equipped',
            },
            {
                any = {
                    'Stun',
                },
                why = 'stunned',
            },
            {
                any = {
                    'ShakyBlock',
                },
                why = 'guard is shaken',
            },
        }),
        Mantra = concatLists(aq, ar, {
            {
                any = {
                    'SpellActive',
                },
                why = 'a spell is active',
            },
            {
                any = {
                    'MidAttack',
                },
                why = 'mid attack',
            },
        }),
        Dodge = concatLists(at, {
            {
                any = {
                    'ShakyBlock',
                },
                why = 'guard is shaken',
            },
            {
                any = {
                    'Action',
                    'NoParkour',
                    'Knocked',
                    'Unconscious',
                    'Pinned',
                    'Carried',
                },
                why = 'cannot move right now',
            },
            {
                any = {
                    'UsingSpell',
                    'CastingSpell',
                    'ClientSlide',
                    'MidAttack',
                    'Dodged',
                    'Dodge',
                    'NoRoll',
                    'PreventRoll',
                    'MobileAction',
                    'Stun',
                },
                why = 'cannot roll right now',
            },
            {
                all = {
                    'SwimRestrict',
                    'Swimming',
                },
                why = 'cannot roll while swimming',
            },
            {
                any = {
                    'NoAttack',
                },
                unless = 'CanRoll',
                why = 'rolling is disabled',
            },
        }),
    }

    module.gates = au

    local isEffectIgnored = function(effect)
        local ignoredEffects = configuration.expectOptionValue('APIgnoreEffects')

        return type(ignoredEffects) == 'table' and ignoredEffects[effect] == true
    end
    local isEffectActive = function(effect)
        return effectTracker.has(effect) and not isEffectIgnored(effect)
    end

    function module.gateEffects()
        local seen, effects = {}, {}
        local collect = function(effect)
            if effect and not seen[effect] then
                seen[effect] = true
                effects[#effects + 1] = effect
            end
        end

        for actionType, gates in next, au do
            for index = 1, #gates do
                local gate = gates[index]

                collect(gate.need)

                if gate.all then
                    for index = 1, #gate.all do
                        collect(gate.all[index])
                    end
                end
                if gate.any then
                    for index = 1, #gate.any do
                        collect(gate.any[index])
                    end
                end
            end
        end

        table.sort(effects)

        return effects
    end

    local passesCondition = function(condition, character, root, target, ignorePvp)
        if condition.flag and pickFlagValue(root, character, condition.flag) then
            return false
        end
        if condition.pvp and not ignorePvp then
            local player = target and players.GetPlayerFromCharacter and players:GetPlayerFromCharacter(target)

            if not player then
                return false
            end
        end
        if condition.filter then
            local filters = configuration.expectOptionValue('APFilters') or {}

            if not filters[condition.filter] then
                return false
            end
        end
        if condition.need then
            return not isEffectActive(condition.need)
        end
        if condition.all then
            for index = 1, #condition.all do
                if not isEffectActive(condition.all[index]) then
                    return false
                end
            end

            return true
        end
        if condition.any then
            if condition.unless and effectTracker.has(condition.unless) then
                return false
            end

            for index = 1, #condition.any do
                if isEffectActive(condition.any[index]) then
                    return true
                end
            end
        end

        return false
    end
    local passesActionGates = function(actionType, character, root, target)
        local gates = au[actionType]

        for index = 1, #gates do
            if passesCondition(gates[index], character, root, target) then
                return false, gates[index].why
            end
        end

        return true
    end

    function module.iframed(character, root, target, aC)
        for index = 1, #aq do
            local gate = aq[index]

            if passesCondition(gate, character, root, target) then
                return gate.why
            end
        end

        if aC == 'Dodge' or aC == 'Forced Full Dodge' then
            return nil
        end

        for index = 1, #ar do
            local gate = ar[index]

            if passesCondition(gate, character, root, target) then
                return gate.why
            end
        end
    end
    function module.blockers(actionType, character)
        local result = {}
        local gates = au[actionType]

        if not gates then
            return result
        end

        for index = 1, #gates do
            local gate = gates[index]

            if passesCondition(gate, character, nil, nil, true) then
                result[#result + 1] = {
                    why = gate.why,
                    missing = gate.need,
                    effects = gate.need and {
                        gate.need,
                    } or gate.all or gate.any or {},
                }
            end
        end

        return result
    end

    local az = {
        {
            id = 'Parry',
            can = function(character, target, root)
                return passesActionGates('Parry', character, root, target)
            end,
            go = function()
                return queuedBlocking.invoke(queuedBlocking.DEFLECT, 'Executor_Parry', nil) ~= false
            end,
        },
        {
            id = 'Block',
            flag = 'nbfb',
            can = function(character, target, root)
                local allowed, reason = passesActionGates('Block', character, root, target)

                if not allowed then
                    return false, reason
                end

                return shouldBlock(character, target, root)
            end,
            go = function(character, target, root)
                local callback

                if root and not (character and character.ibfc) then
                    callback = function()
                        return isTargetBehind(root)
                    end
                end

                return queuedBlocking.invoke(queuedBlocking.NORMAL, 'Executor_Block', (target and target.bfht) or (character and character.bfht) or module.blockHold, callback) ~= false
            end,
        },
        {
            id = 'Mantra',
            can = function(character, target, root)
                local allowed, reason = passesActionGates('Mantra', character, root, target)

                if not allowed then
                    return false, reason
                end
                if not hasMantraSubstitution() then
                    return false, 'mantra substitution is off'
                end
                if not characterActions.pickMantra(nil) then
                    return false, 'every mantra is on cooldown'
                end

                return true
            end,
            go = function()
                return characterActions.mantra(nil)
            end,
        },
        {
            id = 'Dodge',
            flag = 'ndfb',
            can = function(character, target, root)
                return passesActionGates('Dodge', character, root, target)
            end,
            go = function(character, target)
                return characterActions.dodge(pickFlagValue(target, character, 'nrc'))
            end,
        },
    }

    module.chain = az

    function module.watch()
        if module.watching then
            return
        end

        module.watching = true

        effectTracker.onAdded(function(effectName)
            if effectName == 'ShakyBlock' then
                queuedBlocking.stop('Executor_Block')

                return
            end
            if effectName == 'BlockedHit' and getBreakMeterPercent() >= module.highPosture then
                queuedBlocking.stop('Executor_Block')
            end
        end)
    end
    function module.equip(notify)
        local player = players.LocalPlayer
        local backpack = player and player:FindFirstChild('Backpack')
        local humanoid = player and player.Character and player.Character:FindFirstChildOfClass('Humanoid')

        if not (backpack and humanoid) then
            return nil
        end

        for index, child in next, backpack:GetChildren()do
            if child:IsA('Tool') and not child.Name:find('Mantra:') then
                humanoid:EquipTool(child)

                if notify then
                    notify('Equipped %s.', child.Name)
                end

                return child
            end
        end

        if notify then
            notify('Nothing in the backpack to equip.')
        end

        return nil
    end

    local aA

    function module.unupgrade()
        if aA then
            aA:Disconnect()

            aA = nil
        end
    end

    local runQueuedBlock = function(character, notify, timing, hitboxArgs, startIndex, endIndex)
        module.unupgrade()

        if endIndex <= startIndex then
            return
        end

        aA = runService.Heartbeat:Connect(function()
            if not queuedBlocking.held('Executor_Block') then
                return module.unupgrade()
            end

            for index = startIndex, endIndex - 1 do
                local fallback = az[index]

                if module.allowed[fallback.id] ~= false and not (fallback.flag and pickFlagValue(timing, character, fallback.flag)) then
                    if fallback.can(character or {}, hitboxArgs, timing) then
                        module.unupgrade()
                        queuedBlocking.stop('Executor_Block')

                        if fallback.go(character, timing, hitboxArgs) then
                            if notify then
                                notify('%s came back; upgraded out of the block.', fallback.id)
                            end
                        end

                        return
                    end
                end
            end
        end)
    end

    function module.run(character, notify, stopFlag, timing, hitboxArgs, fallbackId, aI)
        if not effectTracker.has('Equipped') and configuration.expectToggleValue('APAutoEquip') then
            module.equip(notify)
        end

        local startIndex = 1

        if fallbackId then
            for index = 1, #az do
                if az[index].id == fallbackId then
                    startIndex = index

                    break
                end
            end
        end

        for index = startIndex, #az do
            local fallback = az[index]

            if module.allowed[fallback.id] == false then
                if notify then
                    notify('%s fallback is turned off.', fallback.id)
                end
            elseif fallback.flag and pickFlagValue(timing, character, fallback.flag) then
                if notify then
                    notify('%s fallback is disabled by this timing.', fallback.id)
                end
            else
                local ok, reason = fallback.can(character or {}, hitboxArgs, timing)

                if not ok then
                    if notify then
                        notify('Cannot %s: %s.', string.lower(fallback.id), reason or 'unavailable')
                    end
                else
                    local override = timing and action.FALLBACKS[fallback.id] and timing[action.FALLBACKS[fallback.id] ]
                    local effective = override or timing

                    if override and aI then
                        local triggerTime = aI + override:when()
                        local waitTime = triggerTime - scheduler._now()

                        if waitTime > 0 then
                            if notify then
                                notify('%s replaced by its own timing, in %.0fms.', fallback.id, waitTime * 1000)
                            end

                            scheduler.after(waitTime, function()
                                local hitbox = timing and timing.hitbox

                                if hitbox and (hitbox.X > 0 or hitbox.Y > 0 or hitbox.Z > 0) and not (timing and timing.ihbc) then
                                    if hitboxArgs and not hitboxProbe.resolve(hitboxArgs, hitbox, character, timing) then
                                        if notify then
                                            notify('%s dropped: no longer in the hitbox.', fallback.id)
                                        end

                                        return
                                    end
                                end

                                fallback.go(character, override, hitboxArgs)
                            end, 'Fallback_' .. fallback.id)

                            return fallback.id
                        end
                    end
                    if fallback.go(character, effective, hitboxArgs) then
                        if notify and index > startIndex then
                            notify('Fell back to %s.', fallback.id)
                        end

                        runQueuedBlock(character, notify, timing, hitboxArgs, startIndex, index)

                        return fallback.id
                    elseif notify then
                        notify('%s was refused by the input layer.', fallback.id)
                    end
                end
            end
            if stopFlag then
                return nil
            end
        end

        if notify then
            notify('No parry, block, mantra or dodge was available.')
        end

        return nil
    end

    return module
end


return aa()

