    ["Features/Combat/AutoParryBlockers"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local inputState = a["Utility/InputState"]()
    local stateListener = a["Features/Combat/StateListener"]()
    local ad = {}
    local ae = {
        {
            'Disable When Textbox Focused',
            inputState.textboxFocused,
            'User is typing in a text box.',
        },
        {
            'Disable When Window Not Active',
            inputState.windowUnfocused,
            'Window is not active.',
        },
        {
            'Disable While Holding Block',
            stateListener.hblock,
            'User is pressing down on a key bound to Block.',
        },
        {
            'Disable While Using Sightless Beam',
            stateListener.csb,
            "User is using the 'Sightless Beam' move.",
        },
        {
            'Disable During Chime Countdown',
            stateListener.ccd,
            'Chime countdown is active.',
        },
    }

    function ad.blocked()
        local filters = configuration.expectOptionValue('APFilters')

        if type(filters) ~= 'table' then
            return nil
        end

        for index = 1, #ae do
            local filterEntry = ae[index]

            if filters[filterEntry[1] ] then
                local success, value = pcall(filterEntry[2])

                if success and value then
                    return filterEntry[3]
                end
            end
        end

        return nil
    end

    return ad
end


return aa()

]=],
    ["Features/Combat/ClickHolder"] = [=[
local aa = function()
    local keyHandling = a["Game/KeyHandling"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local userInputService = game:GetService('UserInputService')
    local fireServer = Instance.new('UnreliableRemoteEvent').FireServer
    local config = {}

    config.held = false

    local character
    local humanoid
    local root
    local setup = function()
        if root then
            return root
        end

        local effectReplicator = game:GetService('ReplicatedStorage'):FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local status, effectModule = pcall(require, effectReplicator)

        root = status and effectModule or nil

        return root
    end
    local connect = function()
        local playerCharacter = players.LocalPlayer and players.LocalPlayer.Character

        if humanoid and playerCharacter and humanoid:IsDescendantOf(playerCharacter) and humanoid.Parent then
            return humanoid
        end

        humanoid = keyHandling.getRemote('LeftClick')

        return humanoid
    end

    config.step = LPH_NO_VIRTUALIZE(function()
        if not config.held then
            return
        end

        local currentEffect = setup()

        if currentEffect and not currentEffect:FindEffect('Equipped') then
            return
        end

        local clickRemote = connect()

        if not clickRemote then
            return
        end

        local player = players.LocalPlayer
        local mouse = player and player:GetMouse()
        local target = shared.Palantir_KaidoTarget
        local targetPart = target and (target:FindFirstChild('Torso2') or target:FindFirstChild('Head') or target:FindFirstChild('HumanoidRootPart') or target.PrimaryPart)

        fireServer(clickRemote, false, targetPart and targetPart.CFrame or mouse and mouse.Hit, {
            S = false,
            NOAERIALS = true,
            Space = false,
            Right = userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2),
            W = false,
            Left = true,
            ctrl = userInputService:IsKeyDown(Enum.KeyCode.LeftControl),
        })
    end)

    function config.init()
        if character then
            return
        end

        pcall(function()
            game:GetService('ReplicatedStorage').Requests.UpdateUXSettings:FireServer('HoldM1', false)
        end)

        character = runService.RenderStepped:Connect(config.step)
    end
    function config.set(held)
        if held then
            config.init()
        end

        config.held = held and true or false
    end
    function config.detach()
        config.held = false
        humanoid = nil

        if character then
            character:Disconnect()

            character = nil
        end
    end

    return config
end


return aa()

]=],
    ["Features/Combat/DefenseDebugger"] = [=[
local aa = function()
    local aa = a["Utility/CoreGuiManager"]()
    local effectTracker = a["Game/EffectTracker"]()
    local autoParry = a["Features/Combat/AutoParry2"]()
    local stateListener = a["Features/Combat/StateListener"]()
    local library = a["GUI/Library"]()
    local maid = a["Utility/Maid"]()
    local helpers = {}
    local runService = game:GetService('RunService')
    local maidCleaner = maid.new()
    local monoFont = Font.new('rbxasset://fonts/families/RobotoMono.json')
    local boldMonoFont = Font.new('rbxasset://fonts/families/RobotoMono.json', Enum.FontWeight.Bold)
    local textColor = Color3.fromRGB(226, 226, 226)
    local dimColor = Color3.fromRGB(124, 124, 124)
    local warningColor = Color3.fromRGB(230, 130, 130)
    local colors = {
        'Parry',
        'Block',
        'Mantra',
        'Dodge',
    }
    local createElement = function()
        local entries = {}

        if effectTracker.has('DodgedFrame') then
            entries[#entries + 1] = {
                'DodgedFrame',
                'already in dodge frames',
                'idf',
            }
        end

        local ok, attacking = pcall(stateListener.astun)

        if ok and attacking then
            entries[#entries + 1] = {
                nil,
                'committed to our own attack',
                nil,
            }
        end

        return entries
    end
    local enabled = false
    local frames = {}
    local makeFrame = function(className, properties, parent)
        local instance = Instance.new(className)

        for propertyName, propertyValue in next, properties do
            instance[propertyName] = propertyValue
        end

        instance.Parent = parent

        return instance
    end
    local screenGui = aa.imark(Instance.new('ScreenGui'))

    screenGui.Name = 'EffectDebugger'
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    screenGui.DisplayOrder = 1
    screenGui.Enabled = false

    local mainFrame = makeFrame('Frame', {
        Name = 'Outer',
        BackgroundColor3 = Color3.fromRGB(8, 8, 8),
        BorderColor3 = Color3.fromRGB(42, 42, 42),
        BorderSizePixel = 1,
        Position = UDim2.new(0, 24, 0.5, -332 / 2),
        Size = UDim2.new(0, 320, 0, 332),
        ZIndex = 100,
    }, screenGui)
    local timeFrame = makeFrame('Frame', {
        Name = 'TitleBar',
        BackgroundColor3 = Color3.fromRGB(14, 14, 14),
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 28),
        ZIndex = 101,
    }, mainFrame)

    makeFrame('TextLabel', {
        Name = 'Title',
        FontFace = boldMonoFont,
        Text = 'WHY NOT?',
        TextColor3 = Color3.fromRGB(255, 255, 255),
        TextSize = 12,
        TextXAlignment = Enum.TextXAlignment.Left,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 10, 0, 0),
        Size = UDim2.new(0, 90, 1, 0),
        ZIndex = 102,
    }, timeFrame)

    local timeLabel = makeFrame('TextLabel', {
        Name = 'Summary',
        FontFace = monoFont,
        Text = '',
        TextColor3 = dimColor,
        TextSize = 11,
        TextXAlignment = Enum.TextXAlignment.Right,
        BackgroundTransparency = 1,
        Position = UDim2.new(1, -150, 0, 0),
        Size = UDim2.new(0, 140, 1, 0),
        ZIndex = 102,
    }, timeFrame)
    local scrollContainer = makeFrame('Frame', {
        Name = 'Panel',
        BackgroundColor3 = Color3.fromRGB(16, 16, 16),
        BorderSizePixel = 0,
        Position = UDim2.new(0, 8, 0, 36),
        Size = UDim2.new(1, -16, 1, -36 - 8),
        ZIndex = 101,
    }, mainFrame)

    makeFrame('UICorner', {
        CornerRadius = UDim.new(0, 4),
    }, scrollContainer)

    local scrollingFrame = makeFrame('ScrollingFrame', {
        Name = 'Scroll',
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Position = UDim2.new(0, 6, 0, 6),
        Size = UDim2.new(1, -12, 1, -12),
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = Color3.fromRGB(70, 70, 70),
        ZIndex = 102,
    }, scrollContainer)
    local updateEntries = function(row)
        local entryRow = frames[row]

        if not entryRow then
            entryRow = makeFrame('TextLabel', {
                FontFace = monoFont,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                BackgroundColor3 = Color3.fromRGB(24, 24, 24),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Size = UDim2.new(1, -4, 0, 16),
                ZIndex = 103,
            }, scrollingFrame)
            frames[row] = entryRow
        end

        entryRow.Visible = true

        return entryRow
    end
    local refreshHighlight = function(highlightEntry)
        local remaining = effectTracker.left(highlightEntry)

        if remaining then
            if remaining <= 0 then
                return 'expiring'
            end

            return string.format('%.2fs left', remaining)
        end

        local elapsed = effectTracker.since(highlightEntry)

        if elapsed then
            return string.format('%.1fs up, no timer', elapsed)
        end

        return 'no timer'
    end

    helpers._remaining = refreshHighlight

    local buildUi = function()
        local rowCount = 0
        local blockedCount = 0
        local elements = createElement()

        if #elements > 0 then
            rowCount = rowCount + 1

            local warningEntry = updateEntries(rowCount)

            warningEntry.Position = UDim2.new(0, 0, 0, 0)
            warningEntry.FontFace = boldMonoFont
            warningEntry.BackgroundTransparency = 1
            warningEntry.TextColor3 = warningColor
            warningEntry.Text = 'ENGINE  -  blocking every action'

            for elementIndex = 1, #elements do
                rowCount = rowCount + 1

                local engineEntry = updateEntries(rowCount)

                engineEntry.Position = UDim2.new(0, 0, 0, (rowCount - 1) * 16)
                engineEntry.FontFace = monoFont
                engineEntry.BackgroundTransparency = 1
                engineEntry.TextColor3 = textColor

                local effectName, description, ignoreKey = elements[elementIndex][1], elements[elementIndex][2], elements[elementIndex][3]

                if effectName then
                    engineEntry.Text = string.format('    %s  %s  (%s, %s to ignore)', effectName, refreshHighlight(effectName), description, ignoreKey)
                else
                    engineEntry.Text = '    ' .. description
                end
            end

            rowCount = rowCount + 1
            updateEntries(rowCount).Text = ''
            updateEntries(rowCount).Position = UDim2.new(0, 0, 0, (rowCount - 1) * 16)
            updateEntries(rowCount).BackgroundTransparency = 1
        end

        for colorIndex = 1, #colors do
            local colorName = colors[colorIndex]
            local blockers = autoParry.blockers(colorName)
            local turnedOff = autoParry.allowed[colorName] == false

            rowCount = rowCount + 1

            local colorEntry = updateEntries(rowCount)

            colorEntry.Position = UDim2.new(0, 0, 0, (rowCount - 1) * 16)
            colorEntry.FontFace = boldMonoFont
            colorEntry.BackgroundTransparency = 1

            if turnedOff then
                colorEntry.Text = colorName .. '  -  turned off'
                colorEntry.TextColor3 = dimColor
            elseif #blockers == 0 then
                colorEntry.Text = colorName .. '  -  available'
                colorEntry.TextColor3 = Color3.fromRGB(150, 220, 150)
            else
                blockedCount = blockedCount + 1
                colorEntry.Text = colorName .. '  -  blocked'
                colorEntry.TextColor3 = warningColor
            end

            for blockerIndex = 1, #blockers do
                local blockerEntry = blockers[blockerIndex]

                if blockerEntry.missing then
                    rowCount = rowCount + 1

                    local missingEntry = updateEntries(rowCount)

                    missingEntry.Position = UDim2.new(0, 0, 0, (rowCount - 1) * 16)
                    missingEntry.FontFace = monoFont
                    missingEntry.BackgroundTransparency = 1
                    missingEntry.TextColor3 = textColor
                    missingEntry.Text = string.format('    %s missing  (%s)', blockerEntry.missing, blockerEntry.why)
                else
                    for effectIndex = 1, #blockerEntry.effects do
                        local effect = blockerEntry.effects[effectIndex]

                        if effectTracker.has(effect) then
                            rowCount = rowCount + 1

                            local effectEntry = updateEntries(rowCount)

                            effectEntry.Position = UDim2.new(0, 0, 0, (rowCount - 1) * 16)
                            effectEntry.FontFace = monoFont
                            effectEntry.BackgroundTransparency = 1
                            effectEntry.TextColor3 = textColor
                            effectEntry.Text = string.format('    %s  %s  (%s)', effect, refreshHighlight(effect), blockerEntry.why)
                        end
                    end
                end
            end
        end
        for frameIndex = rowCount + 1, #frames do
            frames[frameIndex].Visible = false
        end

        if #elements > 0 then
            timeLabel.Text = 'engine is refusing'
        elseif blockedCount == 0 then
            timeLabel.Text = 'everything available'
        else
            timeLabel.Text = string.format('%d of %d blocked', blockedCount, #colors)
        end

        scrollingFrame.CanvasSize = UDim2.new(0, 0, 0, rowCount * 16)

        return rowCount
    end

    helpers._rebuild = buildUi

    local destroy = function()
        if not screenGui.Enabled then
            return
        end

        buildUi()
    end
    local toggle = function()
        screenGui.Enabled = (enabled and not shared.Palantir_PanicHide) and true or false
    end

    function helpers.visible(aG)
        enabled = aG and true or false

        toggle()
    end
    function helpers.init()
        if helpers.inited then
            return
        end

        helpers.inited = true

        library:MakeDraggable(timeFrame, mainFrame)
        maidCleaner:add(runService.RenderStepped:Connect(destroy))
    end
    function helpers.detach()
        maidCleaner:clean()

        helpers.inited = false
        screenGui.Enabled = false
        enabled = false
    end

    return helpers
end


return aa()

]=],
    ["Features/Combat/EntityHistory"] = [=[
local aa = function()
    local module = {}
    local entityHistory = setmetatable({}, {
        __mode = 'k',
    })

    module.add = function(id, position, velocity, timestamp)
        local entry = entityHistory[id]

        if not entry then
            entry = {
                items = {},
                head = 1,
                tail = 0,
            }
            entityHistory[id] = entry
        end

        local items = entry.items

        entry.tail = entry.tail + 1
        items[entry.tail] = {
            position = position,
            timestamp = timestamp,
            velocity = velocity,
        }

        local cutoffTime = tick() - 3
        local scanIndex = entry.head

        while scanIndex <= entry.tail do
            local item = items[scanIndex]

            if not item or item.timestamp >= cutoffTime then
                break
            end

            items[scanIndex] = nil
            scanIndex = scanIndex + 1
        end

        entry.head = scanIndex

        if entry.head > 1024 then
            local newItems = {}
            local newCount = 0

            for index = entry.head, entry.tail do
                newCount = newCount + 1
                newItems[newCount] = items[index]
            end

            entry.items = newItems
            entry.head = 1
            entry.tail = newCount
        end
    end
    module.vall = function(targetId, timeWindow)
        local histEntry = entityHistory[targetId]

        if not histEntry then
            return nil
        end

        local histItems = histEntry.items
        local velocities = {}
        local count = 0
        local windowCutoff = tick() - timeWindow

        for historyIndex = histEntry.head, histEntry.tail do
            local velocityItem = histItems[historyIndex]

            if velocityItem and velocityItem.timestamp >= windowCutoff then
                count = count + 1
                velocities[count] = velocityItem.velocity
            end
        end

        return velocities
    end
    module.yrate = function(sourceId)
        local rateEntry = entityHistory[sourceId]

        if not rateEntry or (rateEntry.tail - rateEntry.head + 1) < 2 then
            return nil
        end

        local moveItems = rateEntry.items
        local current = moveItems[rateEntry.tail]
        local previous = moveItems[rateEntry.tail - 1]

        if not current or not previous then
            return nil
        end

        local deltaTime = current.timestamp - previous.timestamp

        if deltaTime <= 1e-4 then
            return nil
        end

        local prevDirection = Vector3.new(previous.position.LookVector.X, 0, previous.position.LookVector.Z).Unit
        local nextDirection = Vector3.new(current.position.LookVector.X, 0, current.position.LookVector.Z).Unit
        local dot = prevDirection:Dot(nextDirection)
        local crossY = prevDirection:Cross(nextDirection).Y
        local yawAngle = math.atan2(crossY, dot)

        return yawAngle / deltaTime
    end
    module.pstepped = function(characterId, sampleCount, timeRange)
        local history = entityHistory[characterId]

        if not history or history.tail < history.head then
            return nil
        end
        if not sampleCount or sampleCount <= 0 then
            return nil
        end

        local stepItems = history.items
        local latest = stepItems[history.tail]

        if not latest then
            return nil
        end

        local latestTime = latest.timestamp
        local positions = {}
        local collected = 0

        for posIndex = history.head, history.tail do
            local stepItem = stepItems[posIndex]

            if stepItem and (latestTime - stepItem.timestamp) <= timeRange then
                collected = collected + 1
                positions[collected] = stepItem.position
            end
        end

        if collected == 0 then
            return {}
        end

        local size = math.min(sampleCount, collected)
        local result = table.create(size)

        for bucketIndex = 1, size do
            result[bucketIndex] = positions[math.max(math.floor((bucketIndex * collected) / size), 1)]
        end

        return result
    end
    module.pclosest = function(entityId, targetTime)
        local closestEntry = entityHistory[entityId]

        if not closestEntry then
            return nil
        end

        local closeItems = closestEntry.items
        local bestDiff
        local bestPosition

        for closeIndex = closestEntry.head, closestEntry.tail do
            local closeItem = closeItems[closeIndex]

            if closeItem then
                local diff = math.abs(targetTime - closeItem.timestamp)

                if not bestDiff or diff < bestDiff then
                    bestPosition = closeItem.position
                    bestDiff = diff
                end
            end
        end

        return bestPosition
    end

    return module
end


return aa()

]=],
    ["Features/Combat/MantraTricks"] = [=[
local aa = function()
    local module = {}
    local config = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local maidFactory = a["Utility/Maid"]()
    local weakSet = a["Utility/WeakSet"]()
    local signal = a["Utility/Signal"]()
    local taskSpawner = a["Utility/TaskSpawner"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')
    local localPlayer = players.LocalPlayer
    local maid = maidFactory.new()
    local an = false
    local ao = 0
    local startTime = os.clock()
    local loadEffectReplicator = function()
        local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local success, as = pcall(require, effectReplicator)

        return success and as or nil
    end
    local findBackstabMantraTool = function()
        local backpack = localPlayer and localPlayer:FindFirstChild('Backpack')

        if not backpack then
            return nil
        end

        local mantras = config.expectOptionValue('BackstabMovestackMantras')

        if type(mantras) ~= 'table' then
            return nil
        end

        local mantraMap = {}
        local hasMantra = false

        for name, value in pairs(mantras)do
            mantraMap[name] = value

            if value then
                hasMantra = true
            end
        end

        if not hasMantra then
            return nil
        end

        local replicator = loadEffectReplicator()

        if replicator and replicator.GetEffects then
            for effectIndex, effect in pairs(replicator:GetEffects())do
                if type(effect) ~= 'table' then
                    continue
                end

                local effectClass = effect.Class or (effect.index and effect.index.Class)
                local effectValue = effect.Value or (effect.index and effect.index.Value)

                if effectClass == 'ToolLockCD' and effectValue then
                    local tool = backpack:FindFirstChild(tostring(effectValue))

                    if tool and tool:GetAttribute('DefaultName') then
                        mantraMap[tool:GetAttribute('DefaultName')] = nil
                    end
                end
            end
        end

        local mantraName = next(mantraMap)

        if not mantraName then
            return nil
        end

        for backpackIndex, child in pairs(backpack:GetChildren())do
            if child:IsA('Tool') then
                local defaultName = child:GetAttribute('DefaultName')

                if defaultName == mantraName then
                    return child
                end
            end
        end

        return nil
    end
    local applyBackstabMovestack = function()
        if not config.expectToggleValue('BackstabMovestack') then
            return false
        end

        local foundTool = findBackstabMantraTool()

        if not foundTool then
            return false
        end

        local character = localPlayer and localPlayer.Character
        local characterHandler = character and character:FindFirstChild('CharacterHandler')
        local requests = characterHandler and characterHandler:FindFirstChild('Requests')
        local activateMantra = requests and requests:FindFirstChild('ActivateMantra')

        if activateMantra then
            activateMantra:FireServer(foundTool)

            return true
        end

        return false
    end
    local hasBlockingActionEffect = function()
        local effectModule = loadEffectReplicator()

        if not effectModule then
            return false
        end

        return effectModule:HasAny('Action', 'MobileAction', 'UsingAbility', 'LightAttack')
    end
    local getBackstabDelay = function()
        local au = config.expectOptionValue('BackstabMovestackDelay') or 0.05

        return math.max(au, 0)
    end
    local scheduleBackstabDelay = function(taskName)
        taskSpawner.delay(taskName, function()
            return getBackstabDelay()
        end, function()
            an = false

            applyBackstabMovestack()
        end)
    end
    local isBackstabMantraAnimation = function(animation)
        if not animation or not animation.Animation then
            return false
        end

        local animationId = tostring(animation.Animation.AnimationId)

        if animationId == 'rbxassetid://139745984749680' then
            return true
        end

        return animationId:match('%d+') == '139745984749680'
    end
    local onCharacterBackstabTrigger = LPH_NO_VIRTUALIZE(function(triggeredCharacter)
        if weakSet[triggeredCharacter] then
            return
        end
        if not config.expectToggleValue('BackstabMovestack') then
            return
        end
        if not isBackstabMantraAnimation(triggeredCharacter) then
            return
        end
        if os.clock() - ao <= 0.15 then
            return
        end

        logger.warn('[MantraTricks] Backstab trigger anim detected \u{2014} attempting activation.')

        an = true
        ao = os.clock()

        if not hasBlockingActionEffect() and applyBackstabMovestack() then
            an = false

            return
        end

        taskSpawner.spawn('MantraTricks_BackstabImmediateRetry', function()
            local ay = os.clock()

            while os.clock() - ay <= 0.35 do
                if not an then
                    return
                end
                if not config.expectToggleValue('BackstabMovestack') then
                    return
                end
                if not hasBlockingActionEffect() and applyBackstabMovestack() then
                    an = false

                    return
                end

                runService.RenderStepped:Wait()
            end

            scheduleBackstabDelay('MantraTricks_BackstabFromAnimation')
        end)
    end)
    local bindAnimatorListener = function(character)
        if not character then
            return
        end

        local animator = character:FindFirstChildWhichIsA('Animator', true)

        if not animator then
            logger.warn('[MantraTricks] bindBackstabAnimationListener \u{2014} no Animator found on character (%s).', tostring(character))

            return
        end

        local animationSignal = signal.new(animator.AnimationPlayed)

        maid['MantraTricks_BackstabAnimationPlayed'] = animationSignal:connect('MantraTricks_BackstabAnimationPlayed', onCharacterBackstabTrigger)

        logger.warn(
"[MantraTricks] Bound Backstab AnimationPlayed listener on %s.", tostring(animator:GetFullName()))
    end
    local bindCharacterAnimator = function(character)
        if not character then
            return
        end

        bindAnimatorListener(character)

        local descendantSignal = signal.new(character.DescendantAdded)

        maid['MantraTricks_BackstabCharacterDescendantAdded'] = descendantSignal:connect('MantraTricks_BackstabCharacterDescendantAdded', function(
            descendant
        )
            if not descendant:IsA('Animator') then
                return
            end

            bindAnimatorListener(character)
        end)
    end
    local performAutoAirCounter = LPH_NO_VIRTUALIZE(function()
        if not config.expectToggleValue('AutoAirCounter') then
            return
        end
        if os.clock() - startTime < 0.1 then
            return
        end

        startTime = os.clock()

        local character = localPlayer and localPlayer.Character

        if not character then
            return
        end

        local characterHandler = character:FindFirstChild('CharacterHandler')
        local requests = characterHandler and characterHandler:FindFirstChild('Requests')
        local antiAir = requests and requests:FindFirstChild('AntiAir')

        if not antiAir then
            return
        end

        local humanoidRootPart = character:FindFirstChild('HumanoidRootPart')

        if not humanoidRootPart then
            return
        end
        if not config.expectToggleValue('AutoAirCounterOnGround') then
            local isOnGround = false
            local controllerManager = character:FindFirstChild('ControllerManager')

            if controllerManager then
                local groundSensor = controllerManager:FindFirstChild('GroundSensor')

                if groundSensor and groundSensor.SensedPart then
                    isOnGround = true
                end
            end
            if not isOnGround then
                local humanoid = character:FindFirstChildWhichIsA('Humanoid')

                if humanoid and humanoid.FloorMaterial ~= Enum.Material.Air then
                    isOnGround = true
                end
            end
            if not isOnGround then
                local raycastParams = RaycastParams.new()

                raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                raycastParams.FilterDescendantsInstances = {
                    workspace:FindFirstChild('Live'),
                    workspace:FindFirstChild('NPCs'),
                    workspace:FindFirstChild('Thrown'),
                }

                local raycastResult = workspace:Raycast(humanoidRootPart.Position, Vector3.new(0, 
-4, 0), raycastParams)

                if raycastResult and raycastResult.Instance then
                    isOnGround = true
                end
            end
            if isOnGround then
                return
            end
        end

        local liveFolder = workspace:FindFirstChild('Live')

        if not liveFolder then
            return
        end

        local range = config.expectOptionValue('AutoAirCounterRange') or 60
        local allyCheck = config.expectToggleValue('AutoAirCounterAllyCheck')

        for index, aM in next, liveFolder:GetChildren()do
            if aM == character then
                continue
            end
            if aM.Name:sub(1, 1) == '.' then
                continue
            end

            local otherRoot = aM:FindFirstChild('HumanoidRootPart')

            if not otherRoot then
                continue
            end
            if (otherRoot.Position - humanoidRootPart.Position).Magnitude > range then
                continue
            end
            if allyCheck then
                local player = players:GetPlayerFromCharacter(aM)

                if player then
                    local pvpEnabled = aM:GetAttribute('PVPEnabled')

                    if pvpEnabled == false then
                        continue
                    end
                end
            end

            antiAir:FireServer(aM)
        end
    end)
    local onBackstabDebounceMessage = function(message)
        if not config.expectToggleValue('BackstabMovestack') then
            return
        end
        if message.Class == 'backstabDebounce' then
            an = true

            task.delay(3, function()
                an = false
            end)
        end
    end
    local onActionTriggered = function(effect)
        if not config.expectToggleValue('BackstabMovestack') then
            return
        end
        if os.clock() - ao <= 1 then
            return
        end
        if effect.Class ~= 'Action' or not an then
            return
        end

        scheduleBackstabDelay('MantraTricks_BackstabMovestack')
    end

    function module.init()
        logger.warn('[MantraTricks] init starting\u{2026}')

