    ["Features/Combat/ParryEffects"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local players = game:GetService('Players')
    local tweens = game:GetService('TweenService')
    local lighting = game:GetService('Lighting')
    local maidInstance = maid.new()
    local ai = {
        ['Ultrakill Parry'] = 'rbxassetid://122841357244559',
        ['Damn'] = 'rbxassetid://17787027130',
        ['Crit'] = 'rbxassetid://8255306220',
    }
    local aj = {
        ['Damn'] = 'rbxassetid://17787027130',
        ['Crit'] = 'rbxassetid://8255306220',
        ['FAHH'] = 'rbxassetid://72298953503422',
    }
    local getParrySoundId = function()
        local parrySoundPreset = configuration.expectOptionValue('ParrySoundPreset')

        if parrySoundPreset and parrySoundPreset ~= 'Custom' then
            return ai[parrySoundPreset]
        end

        return configuration.expectOptionValue('ParrySoundId')
    end
    local getBlockBreakSoundId = function()
        local blockBreakSoundPreset = configuration.expectOptionValue('BlockBreakSoundPreset')

        if blockBreakSoundPreset and blockBreakSoundPreset ~= 'Custom' then
            return aj[blockBreakSoundPreset]
        end

        local blockBreakSoundId = configuration.expectOptionValue('BlockBreakSoundId')

        return (blockBreakSoundId and #blockBreakSoundId > 0) and blockBreakSoundId or 'rbxassetid://2885026620'
    end
    local findCharacter = function(instance)
        local current = instance

        while current do
            if current:IsA('Model') and current:FindFirstChildOfClass('Humanoid') then
                return current
            end

            current = current.Parent
        end

        return nil
    end
    local isPlayerCharacter = function(instance)
        local character = findCharacter(instance)

        if not character then
            return false
        end

        local localPlayer = players.LocalPlayer and players.LocalPlayer.Character
        local localRoot = localPlayer and localPlayer:FindFirstChild('HumanoidRootPart')

        if not localRoot then
            return false
        end

        local targetRoot = character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart

        if not targetRoot then
            return false
        end

        local distance = (targetRoot.Position - localRoot.Position).Magnitude

        return distance <= 100
    end
    local createFreezeFrameGui = function()
        local player = players.LocalPlayer
        local playerGui = player:FindFirstChild('PlayerGui')

        if not playerGui then
            return
        end

        local freezeColor = configuration.expectOptionValue('ParryFreezeFrameColor') or Color3.fromRGB(255, 255, 255)
        local screenGui = Instance.new('ScreenGui')

        screenGui.Name = 'ParryFreezeFrameGui'
        screenGui.ResetOnSpawn = false
        screenGui.IgnoreGuiInset = true
        screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

        local frame = Instance.new('Frame')

        frame.Size = UDim2.fromScale(1, 1)
        frame.Position = UDim2.fromScale(0, 0)
        frame.BackgroundColor3 = freezeColor
        frame.BackgroundTransparency = 0.55
        frame.BorderSizePixel = 0
        frame.Parent = screenGui
        screenGui.Parent = playerGui

        local blur = Instance.new('BlurEffect')

        blur.Size = 14
        blur.Parent = lighting

        task.delay(0.2, function()
            if not screenGui.Parent then
                blur:Destroy()

                return
            end

            local frameTween = tweens:Create(frame, TweenInfo.new(0.15, Enum.EasingStyle.Linear), {BackgroundTransparency = 1})
            local blurTween = tweens:Create(blur, TweenInfo.new(0.15, Enum.EasingStyle.Linear), {Size = 0})

            frameTween:Play()
            blurTween:Play()
            frameTween.Completed:Connect(function()
                screenGui:Destroy()
                blur:Destroy()
            end)
        end)
    end

    function module.onSoundAdded(sound)
        local isParrySound = sound.Name == 'CLIENT_SOUND_4954186776'

        if isParrySound then
            local localCharacter = players.LocalPlayer.Character
            local isLocalSound = localCharacter and sound:IsDescendantOf(localCharacter)

            if isLocalSound and configuration.expectToggleValue('CustomParrySound') then
                local parrySoundId = getParrySoundId()

                if parrySoundId and #parrySoundId > 0 then
                    sound:Stop()

                    local parryBasePart = sound:FindFirstAncestorWhichIsA('BasePart')
                    local replacementSound = Instance.new('Sound')

                    replacementSound.SoundId = parrySoundId
                    replacementSound.Volume = sound.Volume
                    replacementSound.Parent = parryBasePart or sound.Parent

                    replacementSound:Play()
                    game:GetService('Debris'):AddItem(replacementSound, 5)
                end
            end
            if configuration.expectToggleValue('ParryFreezeFrame') and isLocalSound then
                createFreezeFrameGui()
            end
        end

        local isBlockBreakSound = sound.Name == 'REP_SOUND_2885026620'

        if isBlockBreakSound and configuration.expectToggleValue('CustomBlockBreakSound') and isPlayerCharacter(sound) then
            local blockBreakSoundId = getBlockBreakSoundId()
            local doubleBlockBreak = configuration.expectToggleValue('BlockBreakDouble')

            if not doubleBlockBreak then
                sound:Stop()
            end

            local breakBasePart = sound:FindFirstAncestorWhichIsA('BasePart')
            local replacementSound = Instance.new('Sound')

            replacementSound.SoundId = blockBreakSoundId
            replacementSound.Volume = sound.Volume
            replacementSound.Parent = breakBasePart or sound.Parent

            replacementSound:Play()
            game:GetService('Debris'):AddItem(replacementSound, 5)
        end
    end
    function module.onAudioPlayerAdded(audioPlayer)
        local isClientSound = audioPlayer.Name == 'CLIENT_SOUND_4954186776'

        if isClientSound then
            local character = players.LocalPlayer.Character
            local isFromCharacter = character and audioPlayer:IsDescendantOf(character)

            if isFromCharacter and configuration.expectToggleValue('CustomParrySound') then
                local parrySoundId = getParrySoundId()

                if parrySoundId and #parrySoundId > 0 then
                    audioPlayer:Stop()

                    audioPlayer.AssetId = parrySoundId

                    audioPlayer:Play()
                end
            end
            if configuration.expectToggleValue('ParryFreezeFrame') and isFromCharacter then
                createFreezeFrameGui()
            end

            return
        end

        local isBlockBreakSound = audioPlayer.Name == 'REP_SOUND_2885026620'

        if isBlockBreakSound and configuration.expectToggleValue('CustomBlockBreakSound') and isPlayerCharacter(audioPlayer) then
            local blockBreakSoundId = getBlockBreakSoundId()
            local blockBreakDouble = configuration.expectToggleValue('BlockBreakDouble')

            if not blockBreakDouble then
                audioPlayer:Stop()

                audioPlayer.AssetId = blockBreakSoundId

                audioPlayer:Play()
            else
                local soundInstance = Instance.new('Sound')

                soundInstance.SoundId = blockBreakSoundId
                soundInstance.Volume = 1
                soundInstance.Parent = workspace.CurrentCamera

                soundInstance:Play()
                game:GetService('Debris'):AddItem(soundInstance, 5)
            end
        end
    end
    function module.init()
        logger.warn('ParryEffects \u{2014} ready.')
    end
    function module.detach()
        maidInstance:clean()
        logger.warn('ParryEffects \u{2014} detached.')
    end

    return module
end


return aa()

]=],
    ["Features/Combat/RagdollFeint"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local effectTracker = a["Game/EffectTracker"]()
    local keyHandling = a["Game/KeyHandling"]()
    local taskSpawner = a["Utility/TaskSpawner"]()
    local players = game:GetService('Players')
    local ag = {
        A = false,
        Left = false,
        S = false,
        NOAERIALS = false,
        Space = false,
        Right = true,
        W = false,
        D = false,
    }
    local ah = {
        A = false,
        Left = false,
        S = false,
        NOAERIALS = false,
        Space = false,
        Right = false,
        W = false,
        D = false,
    }
    local ai = false
    local findFeintRelease = function()
        local player = players.LocalPlayer
        local character = player and player.Character
        local characterHandler = character and character:FindFirstChild('CharacterHandler')

        return characterHandler and characterHandler:FindFirstChild('FeintRelease', true)
    end
    local performFeint = function()
        local feintRemote = keyHandling.getRemote('FeintClick')
        local feintRelease = findFeintRelease()

        if not (feintRemote and feintRelease) then
            return
        end

        for index = 1, 4 do
            task.wait()

            if not ai then
                return
            end

            pcall(feintRemote.FireServer, feintRemote, ag)
            pcall(feintRelease.FireServer, feintRelease, ah)
        end
    end
    local onStateChanged = function(newState)
        if newState ~= 'Knocked' and newState ~= 'Ragdoll' then
            return
        end
        if not (ai and configuration.expectToggleValue('AutoRagdollRecover')) then
            return
        end

        taskSpawner.spawn('AutoRagdollCancel', performFeint)
    end

    function module.init()
        ai = true

        effectTracker.onAdded(onStateChanged)
    end
    function module.detach()
        ai = false
    end

    return module
end


return aa()

