            return
        end
        if not configurationClass.expectToggleValue('RhythmSpoofer') then
            return
        end
        if hasRhythmTalent() then
            return
        end

        local expectedKey = getRhythmKeybind()

        if input.KeyCode ~= expectedKey then
            return
        end
        if ap then
            if hasMinElapsed() then
                resetSpoofer()
            else
                ar = true
            end
        else
            if isSyncEligible() then
                startSpoofer()
            end
        end
    end
    local onTick = function()
        if not ap then
            return
        end
        if not configurationClass.expectToggleValue('RhythmSpoofer') then
            resetSpoofer()

            return
        end
        if hasMinElapsed() then
            local syncState = isSyncEligible()

            if ar or not syncState then
                resetSpoofer()
            end
        end
    end

    function rhythmSpoofer.init()
        cleanup:add(userInputService.InputBegan:Connect(onInputBegan))
        cleanup:add(runService.Heartbeat:Connect(onTick))
        cleanup:add(localPlayer.CharacterAdded:Connect(function()
            at = nil
            au = nil

            disconnectSync(true)

            if ap then
                resetSpoofer()
            end
        end))
        getRhythmKeybind()
    end
    function rhythmSpoofer.detach()
        if ap then
            resetSpoofer()
        end

        cleanup:clean()

        if as then
            as:Destroy()

            as = nil
        end
    end

    return rhythmSpoofer
end


return aa()

]=],
    ["Features/Combat/StateListener"] = [=[
local aa = function()
    local effectTracker = a["Game/EffectTracker"]()
    local latency = a["Game/Latency"]()
    local configSection = a["Menu/ConfigSection"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local userInputService = game:GetService('UserInputService')
    local ag = {}

    ag.lAnimationValidTrack = nil
    ag.lAnimTiming = nil
    ag.lAnimFaction = nil
    ag.lAnimTimestamp = nil
    ag.lAnimLatency = nil
    ag.lMantraActivated = nil
    ag.lMantraActiveTick = nil

    local ah = setmetatable({}, {
        __mode = 'k',
    })
    local ai = {}

    function ag.own(ownedTrack)
        if ownedTrack then
            ah[ownedTrack] = true
        end
    end

    local getLatestAction = function(state)
        local actions = state and state.actions and state.actions:stack()

        if not actions or #actions == 0 then
            return nil
        end

        local latestAction = actions[1]

        for index = 2, #actions do
            if actions[index]:when() > latestAction:when() then
                latestAction = actions[index]
            end
        end

        return latestAction
    end

    function ag.hblock()
        local keybinds = replicatedStorage:FindFirstChild('KeyBinds')

        if not keybinds then
            return false
        end

        local success, keybindModule = pcall(require, keybinds)

        if not success or not keybindModule or not keybindModule.Current or type(keybindModule.GetBindings) ~= 'function' then
            return false
        end

        local getOk, bindings = pcall(keybindModule.GetBindings, keybindModule)

        if not getOk or type(bindings) ~= 'table' then
            return false
        end

        for bindingIndex, bindingName in next, (bindings.Block or {})do
            local enumName = tostring(bindingName):match('[^.]+$')

            if enumName then
                local enumOk, mouseButton = pcall(function()
                    return Enum.UserInputType[enumName]
                end)

                if enumOk and mouseButton then
                    local au, av = pcall(userInputService.IsMouseButtonPressed, userInputService, mouseButton)

                    if au and av then
                        return true
                    end
                end

                local codeOk, keyCode = pcall(function()
                    return Enum.KeyCode[enumName]
                end)

                if codeOk and keyCode and userInputService:IsKeyDown(keyCode) then
                    return true
                end
            end
        end

        return false
    end
    function ag.csb()
        local mantraName = ag.lMantraActivated

        if not mantraName or not tostring(mantraName):match('Sightless Beam') then
            return false
        end

        local player = players.LocalPlayer
        local root = player and player.Character and player.Character:FindFirstChild('HumanoidRootPart')

        if not root then
            return false
        end
        if root:FindFirstChild('REP_SOUND_376107250') then
            return true
        end

        for childIndex, child in next, root:GetChildren()do
            if child:IsA('Sound') and child.Name == 'Telekin' and child.IsPlaying then
                return true
            end
        end

        return false
    end
    function ag.ccd()
        return game.PlaceId == 6832944305 and workspace.DistributedGameTime < 15
    end
    function ag.astun()
        if effectTracker.has('Stun') then
            return false
        end
        if effectTracker.has('LightAttack') and (effectTracker.since('LightAttack') or math.huge) <= 0.5 then
            return true
        end

        return effectTracker.has('UsingSpell')
    end
    function ag.cfeint()
        if effectTracker.any('Feint', 'ClientFeint', 'Feinted') then
            return false
        end
        if effectTracker.any('Knocked', 'Stun', 'Unconscious') then
            return false
        end

        return effectTracker.any('LightAttack', 'MidAttack', 'Action')
    end
    function ag.untilFeint()
        local faction = ag.lAnimFaction
        local timestamp = ag.lAnimTimestamp

        if not (faction and timestamp) then
            return nil
        end

        return faction:when() - (os.clock() - timestamp) - (ag.lAnimLatency or 0)
    end

    local onAnimationPlayed = function(animationTrack)
        if ah[animationTrack] then
            return
        end

        local animation = animationTrack.Animation
        local animationId = animation and animation.AnimationId

        if not animationId then
            return
        end

        ag.lAnimationValidTrack = animationTrack
        ag.lAnimTimestamp = os.clock()
        ag.lAnimLatency = latency.rtt() or 0

        local direction = configSection.as
        local timing = direction and direction:index(animationId:match('(%d+)%s*$') or animationId) or nil

        ag.lAnimTiming = timing
        ag.lAnimFaction = getLatestAction(timing)
    end
    local connectAnimator = function(onCharacterShown)
        if not onCharacterShown then
            return
        end

        local humanoid = onCharacterShown:FindFirstChildOfClass('Humanoid')
        local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')

        if animator then
            ai[#ai + 1] = animator.AnimationPlayed:Connect(onAnimationPlayed)

            return
        end
        if not humanoid then
            return
        end

        ai[#ai + 1] = humanoid.ChildAdded:Connect(function(child)
            if child:IsA('Animator') then
                ai[#ai + 1] = child.AnimationPlayed:Connect(onAnimationPlayed)
            end
        end)
    end

    function ag.init()
        if ag.inited then
            return
        end

        ag.inited = true

        local player = players.LocalPlayer

        connectAnimator(player and player.Character)

        if player then
            ai[#ai + 1] = player.CharacterAdded:Connect(function(character)
                ag.lAnimationValidTrack = nil
                ag.lAnimTiming = nil
                ag.lAnimFaction = nil

                connectAnimator(character)
            end)
        end
    end
    function ag.detach()
        for index = 1, #ai do
            pcall(function()
                ai[index]:Disconnect()
            end)
        end

        ai = {}
        ag.inited = false
        ag.lAnimationValidTrack = nil
        ag.lAnimTiming = nil
        ag.lAnimFaction = nil
        ag.lAnimTimestamp = nil
        ag.lAnimLatency = nil
        ag.lMantraActivated = nil
        ag.lMantraActiveTick = nil
    end

    return ag
end


return aa()

