]=],
    ["Features/Exploits/AnimationSpeedChanger"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local effectTracker = a["Game/EffectTracker"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local af
    local ag = 0
    local ah = setmetatable({}, {
        __mode = 'k',
    })
    local findAnimator = function()
        local player = shared.Palantir_LP or players.LocalPlayer
        local character = player and player.Character
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')

        return humanoid and humanoid:FindFirstChildOfClass('Animator')
    end
    local getTargetSpeed = function(elapsed)
        local minSpeed = tonumber(configuration.expectOptionValue('AnimationSpeedMinimum')) or 1
        local maxSpeed = tonumber(configuration.expectOptionValue('AnimationSpeedMaximum')) or 1

        if minSpeed > maxSpeed then
            minSpeed, maxSpeed = maxSpeed, minSpeed
        end

        ag = ag + elapsed

        if configuration.expectToggleValue('SwitchBetweenSpeeds') then
            return (math.floor(ag * 2) % 2 == 0) and minSpeed or maxSpeed
        end

        return minSpeed + (maxSpeed - minSpeed) * ((math.sin(ag * 4) + 1) / 2)
    end
    local shouldSpeedApply = function()
        local combatLimits = configuration.expectOptionValue('LimitToCombatAnimationCategories')

        if type(combatLimits) ~= 'table' then
            return true
        end
        if combatLimits.M1 and effectTracker.any('LightAttack', 'HeavyAttack') then
            return true
        end
        if combatLimits.Mantra and effectTracker.any('CastingSpell', 'UsingSpell') then
            return true
        end
        if combatLimits.Critical and effectTracker.has('UsingCritical') then
            return true
        end

        return false
    end
    local restoreAnimationSpeeds = function()
        for queuedTrack, originalSpeed in next, ah do
            pcall(function()
                queuedTrack:AdjustSpeed(originalSpeed)
            end)

            ah[queuedTrack] = nil
        end
    end
    local updateAnimationSpeed = function(deltaTime)
        if not configuration.expectToggleValue('AnimationSpeedChanger') then
            if next(ah) then
                restoreAnimationSpeeds()
            end

            return
        end
        if configuration.expectToggleValue('LimitToCombatAnimations') and not shouldSpeedApply() then
            if next(ah) then
                restoreAnimationSpeeds()
            end

            return
        end

        local animator = findAnimator()

        if not animator then
            return
        end

        local newSpeed = getTargetSpeed(deltaTime)
        local tracks = animator:GetPlayingAnimationTracks()

        for index = 1, #tracks do
            local track = tracks[index]

            if ah[track] == nil then
                ah[track] = track.Speed
            end

            pcall(function()
                track:AdjustSpeed(newSpeed)
            end)
        end
    end

    function module.init()
        if af then
            return
        end

        af = runService.Heartbeat:Connect(updateAnimationSpeed)
    end
    function module.detach()
        if af then
            af:Disconnect()

            af = nil
        end

        restoreAnimationSpeeds()
    end

    return module
end


return aa()

]=],
    ["Features/Exploits/BuildStealer"] = [=[
local aa = function()
    local aa = {}
    local config = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local players = game:GetService('Players')
    local httpService = game:GetService('HttpService')
    local enableFeature = function()
        return (syn and syn.request) or request or http_request or (http and http.request)
    end
    local loadSettings = function()
        local targetName = config.expectOptionValue('BuildStealerTarget')

        if type(targetName) == 'string' and #targetName > 0 then
            return players:FindFirstChild(targetName)
        end

        return nil
    end

    function aa.stealPlayer(player, copyToClipboard)
        if not player then
            return
        end

        local character = player.Character

        if not character then
            return logger.warnNotify('Build Stealer \u{2014} %s has no character loaded.', player.Name)
        end

        local humanoid = character:FindFirstChildOfClass('Humanoid')

        if not humanoid then
            return
        end

        local backpack = player:FindFirstChild('Backpack')

        if not backpack then
            return logger.warnNotify('Build Stealer \u{2014} %s has no Backpack (out of range?).', player.Name)
        end

        local getAttribute = function(attributeName)
            return character:GetAttribute(attributeName)
        end
        local statPoints = 0

        for statName, statValue in pairs(character:GetAttributes())do
            if type(statName) == 'string' and statName:match('Stat') and type(statValue) == 'number' then
                statPoints = statPoints + statValue
            end
        end

        local powerCount = 0

        for iteration = 1, 20 do
            if statPoints <= 15 then
                break
            end

            statPoints = statPoints - 15
            powerCount = powerCount + 1
        end

        local power = math.min(20, math.max(1, powerCount))
        local build = {
            version = 3,
            stats = {
                buildName = string.format("%s %s's Stolen Build", os.date('%B %d %Y'), player.Name),
                buildDescription = 
"Talents are not stealable anymore - this is just the opponent's stats.",
                buildAuthor = 'PalantirX',
                power = power,
                pointsUntilNextPower = 67,
                points = 67,
                pointSpent = 67,
                traitPoints = 0,
                traits = {
                    Vitality = getAttribute('Trait_Health'),
                    Erudition = getAttribute('Trait_Ether'),
                    Songchant = getAttribute('Trait_MantraDamage'),
                    Proficiency = getAttribute('Trait_WeaponDamage'),
                },
                meta = {
                    Race = 'None',
                    Oath = 'None',
                    Murmur = 'None',
                    Bell = 'None',
                    Origin = 'Castaway',
                    Outfit = 'None',
                },
            },
            attributes = {
                weapon = {
                    ['Heavy Wep.'] = getAttribute('Stat_WeaponHeavy'),
                    ['Medium Wep.'] = getAttribute('Stat_WeaponMedium'),
                    ['Light Wep.'] = getAttribute('Stat_WeaponLight'),
                },
                base = {
                    Strength = getAttribute('Stat_Strength'),
                    Fortitude = getAttribute('Stat_Fortitude'),
                    Agility = getAttribute('Stat_Agility'),
                    Intelligence = getAttribute('Stat_Intelligence'),
                    Willpower = getAttribute('Stat_Willpower'),
                    Charisma = getAttribute('Stat_Charisma'),
                },
                attunement = {
                    Flamecharm = getAttribute('Stat_ElementFire'),
                    Frostdraw = getAttribute('Stat_ElementIce'),
                    Thundercall = getAttribute('Stat_ElementLightning'),
                    Galebreathe = getAttribute('Stat_ElementWind'),
                    Shadowcast = getAttribute('Stat_ElementShadow'),
                    Ironsing = getAttribute('Stat_ElementMetal'),
                    Bloodrend = getAttribute('Stat_ElementBlood'),
                },
            },
            content = {
                mantraModifications = {},
                notes = '',
            },
            meta = {
                tags = {},
                isPrivate = true,
            },
            talents = {},
            mantras = {},
            weapons = '',
            enchant = '',
            motif = '',
            preShrine = {
                base = {
                    Strength = 100,
                    Fortitude = 100,
                    Agility = 100,
                    Intelligence = 100,
                    Willpower = 100,
                    Charisma = 100,
                },
                weapon = {
                    ['Heavy Wep.'] = 100,
                    ['Medium Wep.'] = 100,
                    ['Light Wep.'] = 100,
                },
                attunement = {
                    Flamecharm = 100,
                    Frostdraw = 100,
                    Thundercall = 100,
                    Galebreathe = 100,
                    Shadowcast = 100,
                    Ironsing = 100,
                    Bloodrend = 100,
                },
            },
            postShrine = nil,
            favoritedTalents = {},
        }

        build.postShrine = build.attributes

        local statsMeta = build.stats.meta
        local notes = {}

        for itemIndex, item in next, backpack:GetChildren()do
            if item.Name:match('Resonance:') then
                statsMeta.Bell = item.Name:gsub('Resonance:', '')
            end
            if item.Name:match('Mantra') and item:GetAttribute('DisplayName') then
                local recalled = item.Name:match('RecalledMantra')
                local richStats = item:GetAttribute('RichStats')

                notes[#notes + 1] = (recalled and '[RECALLED MANTRA]' or '[USED MANTRA]') .. ' ' .. (richStats and richStats:gsub('\n', ' | ') or 'NO RICH STATS?')

                if not recalled then
                    build.mantras[#build.mantras + 1] = item:GetAttribute('DisplayName')
                    build.content.mantraModifications[item:GetAttribute('DisplayName')] = {}
                end
            end
            if item.Name == 'Weapon' then
                local weaponStats = item:GetAttribute('RichStats')

                notes[#notes + 1] = '[USED WEAPON] ' .. (weaponStats and weaponStats:gsub('\n', ' | ') or item.Name)
            end
        end
        for childIndex, child in next, character:GetChildren()do
            if child.Name == 'Ring' then
                local equipName = child:GetAttribute('DisplayName') or child:GetAttribute('EquipmentRef') or child.Name
                local equipStats = child:GetAttribute('RichStats')

                notes[#notes + 1] = string.format('[EQUIPPED RING] %s\n', equipName) .. (equipStats and equipStats:gsub('\n', ' | ') or child.Name)
            elseif child.Name == 'Shirt' then
                notes[#notes + 1] = '[EQUIPPED SHIRT ID] ' .. tostring(child.ShirtTemplate)
            elseif child.Name == 'Pants' then
                notes[#notes + 1] = '[EQUIPPED PANTS ID] ' .. tostring(child.PantsTemplate)
            elseif child.Name:match('Equipment') and child:GetAttribute('RichStats') and child:GetAttribute('DisplayName') then
                local gearStats = child:GetAttribute('RichStats')

                notes[#notes + 1] = string.format('[EQUIPPED EQUIPMENT] [%s] %s', child.Name, child:GetAttribute('DisplayName')) .. (gearStats and gearStats:gsub('\n', ' | ') or '')
            end
        end

        notes[#notes + 1] = string.format('[HEALTH] %.2f/%.2f', humanoid.Health, humanoid.MaxHealth)
        build.content.notes = table.concat(notes, '\n\n')

        local httpRequest = enableFeature()

        if not httpRequest then
            return logger.warnNotify('Build Stealer \u{2014} executor exposes no HTTP request function.')
        end

        local ok, response = pcall(httpRequest, {
            Url = 'https://deepwoken.co/api/proxy/builds',
            Method = 'POST',
            Headers = {
                ['Content-Type'] = 'application/json',
                ['Accept'] = 'application/json',
                ['Origin'] = 'https://deepwoken.co',
                ['Referer'] = 'https://deepwoken.co/builder',
                ['Sec-Fetch-Site'] = 'same-origin',
                ['Sec-Fetch-Mode'] = 'cors',
                ['Sec-Fetch-Dest'] = 'empty',
            },
            Body = httpService:JSONEncode(build),
        })

        if not ok or not response or not response.Success or not response.Body then
            return logger.warnNotify('Build Stealer \u{2014} deepwoken.co request failed for %s.', player.Name)
        end

        local decodeOk, decoded = pcall(function()
            return httpService:JSONDecode(response.Body)
        end)

        if not decodeOk or type(decoded) ~= 'table' or not decoded.id then
            return logger.warnNotify('Build Stealer \u{2014} bad response from deepwoken.co.')
        end

        local url = string.format('https://deepwoken.co/builder?id=%s', decoded.id)

        if copyToClipboard and type(setclipboard) == 'function' then
            pcall(setclipboard, url)
        end

        pcall(function()
            if type(makefolder) == 'function' and type(isfolder) == 'function' and type(writefile) == 'function' then
                if not isfolder('PalantirX/Stolen Builds') then
                    makefolder('PalantirX/Stolen Builds')
                end

                local buildPath = string.format('PalantirX/Stolen Builds/%s %s.txt', os.date('%B %d %Y'), player.Name)

                writefile(buildPath, string.format('stolen on %s\nbuild url: %s\n\n%s', os.date('%B %d %Y'), url, build.content.notes))
            end
        end)
        logger.notify("Stole %s's build \u{2192} %s (copied to clipboard).", player.Name, url)

        return url
    end
    function aa.stealSelected()
        local settings = loadSettings()

        if not settings then
            return logger.warnNotify('Build Stealer \u{2014} no valid target selected (pick one + Refresh).')
        end

        aa.stealPlayer(settings, true)
    end
    function aa.init() end

    return aa
end


return aa()

