    ["Features/Exploits/Exploits"] = [=[
local aa = function()
    local instanceWrapper = a["Utility/InstanceWrapper"]()
    local maid = a["Utility/Maid"]()
    local cleanupMaid = maid.new()

    return (function()
        local state = {
            forceVoid = false,
            ownershipTimestamp = 0,
            ownershipItem = nil,
            currentRootPart = nil,
        }
        local configuration = a["Utility/Configuration"]()
        local logger = a["Utility/Logger"]()
        local originalStore = a["Utility/OriginalStore"]()
        local signal = a["Utility/Signal"]()

        game:GetService('UserInputService')

        local tacetCrouch = {
            Enabled = false,
            Keybind = Enum.KeyCode.T,
        }
        local getRequests = function()
            local players = game:GetService('Players')
            local localPlayer = players.LocalPlayer

            if not localPlayer then
                return nil
            end

            local character = localPlayer.Character or localPlayer.CharacterAdded:Wait()

            if not character then
                return nil
            end

            local characterHandler = character:FindFirstChild('CharacterHandler') or character:WaitForChild('CharacterHandler')
            local requests = characterHandler:FindFirstChild('Requests') or characterHandler:WaitForChild('Requests')

            return requests
        end

        function tacetCrouch.Enable()
            if tacetCrouch.Enabled then
                return
            end

            tacetCrouch.Enabled = true

            local success, err = pcall(function()
                local reqFolder = getRequests()

                if not reqFolder then
                    return
                end

                local serverCrouch = reqFolder:FindFirstChild('ServerCrouch')

                if serverCrouch then
                    serverCrouch:FireServer(true)
                end

                local tacetRemote = reqFolder:FindFirstChild('Tacet')

                if tacetRemote then
                    tacetRemote:FireServer()
                end
            end)

            if not success then
                if not LPH_OBFUSCATED then
                    warn('TacetCrouch Enable error:', err)
                end
            end
        end
        function tacetCrouch.Disable()
            if not tacetCrouch.Enabled then
                return
            end

            tacetCrouch.Enabled = false

            local didEnable, failure = pcall(function()
                local requestHandler = getRequests()

                if not requestHandler then
                    return
                end

                local crouchRemote = requestHandler:FindFirstChild('ServerCrouch')

                if crouchRemote then
                    crouchRemote:FireServer(false)
                end
            end)

            if not didEnable then
                if not LPH_OBFUSCATED then
                    warn('TacetCrouch Disable error:', failure)
                end
            end
        end
        function tacetCrouch.Toggle()
            if tacetCrouch.Enabled then
                tacetCrouch.Disable()
            else
                tacetCrouch.Enable()
            end
        end
        function tacetCrouch.SetKeybind(keybind)
            if typeof(keybind) == 'EnumItem' and keybind.EnumType == Enum.KeyCode then
                tacetCrouch.Keybind = keybind
            elseif type(keybind) == 'string' then
                local resolved, keyCode = pcall(function()
                    return Enum.KeyCode[keybind]
                end)

                if resolved and keyCode then
                    tacetCrouch.Keybind = keyCode
                end
            end
        end

        local runService = game:GetService('RunService')
        local playersService = game:GetService('Players')
        local physicsService = game:GetService('PhysicsService')
        local replicatedStorage = game:GetService('ReplicatedStorage')
        local groupName = tostring(state)
        local aq = maid.new()
        local highlightMaid = maid.new()
        local heartbeatSignal = signal.new(runService.Heartbeat)
        local preRenderSignal = signal.new(runService.PreRender)
        local storedVelocity
        local part = Instance.new('Part')

        part.Parent = workspace

        local networkOwner = gethiddenproperty(part, 'NetworkOwnerV3')

        part:Destroy()

        local swingEffects = {
            'OffhandAttack',
            'HeavyAttack',
            'MediumAttack',
            'LightAttack',
            'UsingSpell',
        }
        local fpdhStore = originalStore.new()
        local originalFpdh
        local voidActive = false
        local isMine = function(candidate)
            local gotOwner, partOwner = pcall(gethiddenproperty, candidate, 'NetworkOwnerV3')

            return gotOwner and partOwner == networkOwner
        end
        local disableVoid = function()
            if not voidActive then
                return
            end

            voidActive = false

            fpdhStore:restore()

            originalFpdh = nil
        end
        local enableVoid = function()
            local player = playersService.LocalPlayer

            if not player then
                return
            end
            if setsimulationradius then
                setsimulationradius(math.huge, math.huge)
            else
                sethiddenproperty(player, 'MaxSimulationRadius', 9e9)
                sethiddenproperty(player, 'SimulationRadius', 9e9)
            end
            if originalFpdh == nil then
                originalFpdh = workspace:GetAttribute('OriginalFPDH') or workspace.FallenPartsDestroyHeight

                workspace:SetAttribute('OriginalFPDH', originalFpdh)
                fpdhStore:set(workspace, 'FallenPartsDestroyHeight', 0 / 0)

                voidActive = true
            end

            local fallHeight = originalFpdh
            local liveFolder = workspace:FindFirstChild('Live')

            if not liveFolder then
                return
            end

            for index, model in pairs(liveFolder:GetChildren())do
                if model.Name:sub(1, 1) ~= '.' then
                    continue
                end
                if model.Name:find('chaser') then
                    continue
                end
                if model.Name:lower():find('hostage', 1, true) then
                    continue
                end

                local rootPart = model:FindFirstChild('HumanoidRootPart')

                if not rootPart then
                    continue
                end

                for childIndex, childPart in pairs(model:GetChildren())do
                    if childPart:IsA('BasePart') and isMine(childPart) then
                        childPart.CFrame = CFrame.new(rootPart.Position.X, fallHeight - 50, rootPart.Position.Z)
                        childPart.Velocity = Vector3.new(0, -12500, 0)
                    end
                end
            end
        end
        local getWeapon = function()
            local currentPlayer = playersService.LocalPlayer

            if not currentPlayer then
                return
            end

            local backpack = currentPlayer:FindFirstChild('Backpack')

            if not backpack then
                return
            end

            local weapon

            for itemIndex, tool in pairs(backpack:GetChildren())do
                if tool.Name:match('Talent') then
                    continue
                end
                if not tool:IsA('Tool') then
                    continue
                end
                if not tool:FindFirstChildOfClass('BasePart') then
                    continue
                end

                weapon = tool
            end

            if not weapon then
                weapon = currentPlayer.Character and currentPlayer.Character:FindFirstChild('Weapon')
                weapon = weapon or backpack:FindFirstChild('Weapon')
            end

            return weapon
        end
        local moveWhileKnocked = function()
            local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')
            local effects = require(effectReplicator)

            if not effects:FindEffect('Knocked') then
                return
            end

            local activePlayer = playersService.LocalPlayer

            if not activePlayer then
                return
            end

            local currentCharacter = activePlayer.Character

            if not currentCharacter then
                return
            end

            local charRoot = currentCharacter:FindFirstChild('HumanoidRootPart')

            if not charRoot then
                return
            end

            local humanoid = currentCharacter:FindFirstChild('Humanoid')

            if not humanoid then
                return
            end

            local invBackpack = activePlayer:FindFirstChild('Backpack')

            if not invBackpack then
                return
            end

            local chosenWeapon = state.ownershipItem or getWeapon()

            if not chosenWeapon then
                return
            end
            if not state.ownershipItem or not state.ownershipItem:IsDescendantOf(game) then
                state.ownershipItem = chosenWeapon
            end
            if tick() - state.ownershipTimestamp <= 0.15 then
                return
            end

            local leftHand = currentCharacter:FindFirstChild('LeftHand')
            local rightHand = currentCharacter:FindFirstChild('RightHand')
            local hasHandWeapon = false

            if leftHand and leftHand:FindFirstChild('HandWeapon') then
                hasHandWeapon = true
            end
            if rightHand and rightHand:FindFirstChild('HandWeapon') then
                hasHandWeapon = true
            end

            local charHandler = currentCharacter:FindFirstChild('CharacterHandler')
            local equipRequests = charHandler and charHandler:FindFirstChild('Requests')
            local equipWeapon = equipRequests and equipRequests:FindFirstChild('EquipWeapon')

            if chosenWeapon.Name == 'Weapon' and hasHandWeapon then
                return equipWeapon and equipWeapon:FireServer(false)
            end
            if chosenWeapon.Name == 'Weapon' and not hasHandWeapon then
                return equipWeapon and equipWeapon:FireServer(true)
            end
            if chosenWeapon.Parent == currentCharacter then
                return humanoid:UnequipTools()
            end
            if chosenWeapon.Parent == invBackpack then
                humanoid:EquipTool(chosenWeapon)
            end

            state.ownershipTimestamp = tick()
        end
        local pathfindBreaker = function()
            local automation = a["Features/Game/NoEffects"]().automation

            if automation.ferryman and automation.requesting_mob_ai_breaker_stop then
                storedVelocity = nil

                return highlightMaid:clean()
            end

            local pathCharacter = playersService.LocalPlayer.Character

            if not pathCharacter then
                return
            end

            local pathRoot = pathCharacter:FindFirstChild('HumanoidRootPart')

            if not pathRoot then
                return
            end

            storedVelocity = pathRoot.AssemblyLinearVelocity

            if configuration.expectToggleValue('AggressiveMode') then
                pathRoot.AssemblyLinearVelocity = Vector3.new(0, -1e5, 0)
            else
                pathRoot.AssemblyLinearVelocity = Vector3.new(0, -9e9, 0)
            end
            if not configuration.expectToggleValue('PathfindBreakerHighlight') then
                return highlightMaid:clean()
            end

            local highlight = instanceWrapper.create(highlightMaid, 'PathfindBreakerHighlight', 'Highlight')

            highlight.FillColor = configuration.expectOptionValue('PathfindBreakerHighlightColor')
            highlight.OutlineColor = configuration.expectOptionValue('PathfindBreakerHighlightOutlineColor')

            if pathRoot.Parent then
                highlight.Parent = pathRoot.Parent
            end
        end
        local fastSwing = function()
            local fxReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

            if not fxReplicator then
                return
            end

            local effectsModule = require(fxReplicator)

            effectsModule.EffectAdded:Connect(function(effect)
                if configuration.expectToggleValue('FastSwing') and table.find(swingEffects, effect.Class) then
                    pcall(function()
                        effect:Remove(true)
                    end)
                end
            end)
        end
        local lastRun = 0
        local heartbeatLoop = function()
            if configuration.expectToggleValue('PathfindBreaker') then
                pathfindBreaker()
            else
                if storedVelocity then
                    storedVelocity = nil

                    highlightMaid:clean()
                end
            end
            if configuration.expectToggleValue('VoidMobs') then
                enableVoid()
            else
                disableVoid()
            end
            if os.clock() - lastRun < 0.5 then
                return
            end

            lastRun = os.clock()

            local heartbeatPlayer = playersService.LocalPlayer

            if not heartbeatPlayer then
                return
            end
            if configuration.expectToggleValue('MoveWhileKnocked') then
                moveWhileKnocked()
            end
            if tacetCrouch then
                local tacetEnabled = configuration.expectToggleValue('TacetCrouch')

                if tacetEnabled then
                    pcall(tacetCrouch.Enable)
                else
                    pcall(tacetCrouch.Disable)
                end

                local keybindStr = configuration.expectOptionValue('TacetCrouchKeyBind')

                if keybindStr and type(keybindStr) == 'string' and keybindStr ~= 'N/A' then
                    local lookupOk, bindKey = pcall(function()
                        return Enum.KeyCode[keybindStr]
                    end)

                    if lookupOk and bindKey and tacetCrouch.SetKeybind then
                        pcall(tacetCrouch.SetKeybind, bindKey)
                    end
                end
            end
        end
        local restoreVelocity = function()
            if not storedVelocity then
                return
            end

            local restoreCharacter = playersService.LocalPlayer and playersService.LocalPlayer.Character

            if not restoreCharacter then
                return
            end

            local restoreRootPart = restoreCharacter:FindFirstChild('HumanoidRootPart')

            if not restoreRootPart then
                return
            end

            restoreRootPart.AssemblyLinearVelocity = storedVelocity
        end

        function state.init()
            aq:add(heartbeatSignal:connect('Exploits_Heartbeat', heartbeatLoop))
            aq:add(preRenderSignal:connect('Exploits_PreRender', restoreVelocity))
            task.delay(1.5, fastSwing)
            pcall(function()
                physicsService:RegisterCollisionGroup(groupName)
                physicsService:CollisionGroupSetCollidable(groupName, groupName, false)
                physicsService:CollisionGroupSetCollidable(groupName, 'Default', false)
                physicsService:CollisionGroupSetCollidable(groupName, 'Player', false)
                physicsService:CollisionGroupSetCollidable(groupName, 'WalkThrough', false)
            end)
            logger.warn('Exploits initialized.')
        end
        function state.detach()
            aq:clean()
            cleanupMaid:clean()
            highlightMaid:clean()
            disableVoid()
            logger.warn('Exploits detached.')
        end

        return state
    end)()
end


return aa()

]=],
    ["Features/Exploits/FakeAnimSpammer"] = [=[
local aa = function()
    local module = {}
    local config = a["Utility/Configuration"]()
    local apBreakerCore = a["Features/Combat/APBreakerCore"]()
    local players = game:GetService('Players')
    local random = Random.new()
    local af = 0
    local ag = setmetatable({}, {
        __mode = 'k',
    })
    local animatorState = setmetatable({animator = nil}, {
        __mode = 'v',
    })
    local loadAnimations = function(animator)
        local cachedAnims = ag[animator]

        if cachedAnims then
            return cachedAnims
        end

        local loadedAnimations = {}
        local animIds = apBreakerCore.collectCombatAnims()

        for animIndex, animId in ipairs(animIds)do
            local loadSuccess, loadedTrack = pcall(function()
                local animation = Instance.new('Animation')

                animation.AnimationId = animId
                animation.Name = 'PALANTIRX_FAKE'

                return animator:LoadAnimation(animation)
            end)

            if loadSuccess and loadedTrack then
                loadedAnimations[#loadedAnimations + 1] = loadedTrack
            end
        end

        ag[animator] = loadedAnimations

        return loadedAnimations
    end
    local stopAnimatorTracks = function(targetAnimator)
        local cachedTracks = targetAnimator and ag[targetAnimator]

        if not cachedTracks then
            return
        end

        for trackIndex, activeTrack in ipairs(cachedTracks)do
            pcall(function()
                activeTrack:Stop(0)
            end)
        end
    end
    local clearAnimator = function()
        if animatorState.animator then
            stopAnimatorTracks(animatorState.animator)

            animatorState.animator = nil
        end
    end
    local findVictimPlayer = function()
        local victimName = config.expectOptionValue('FakeAnimSpammerVictim')

        if type(victimName) ~= 'string' or #victimName == 0 then
            return nil
        end

        for playerIndex, player in ipairs(players:GetPlayers())do
            if player ~= players.LocalPlayer and player.Name == victimName then
                return player
            end
        end

        return nil
    end

    function module.tick(deltaTime)
        if not config.expectToggleValue('FakeAnimSpammer') then
            clearAnimator()

            return
        end

        local intensity = tonumber(config.expectOptionValue('FakeAnimSpammerIntensity')) or 15

        af = af + (deltaTime or 0.016)

        local interval = 1 / math.max(1, intensity)

        if af < interval then
            return
        end

        af = 0

        local victim = findVictimPlayer()

        if not victim then
            clearAnimator()

            return
        end

        local character = victim.Character
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')
        local currentAnimator = humanoid and humanoid:FindFirstChildOfClass('Animator')

        if not currentAnimator then
            clearAnimator()

            return
        end
        if animatorState.animator and animatorState.animator ~= currentAnimator then
            stopAnimatorTracks(animatorState.animator)
        end

        animatorState.animator = currentAnimator

        local animationTracks = loadAnimations(currentAnimator)

        if #animationTracks == 0 then
            return
        end

        local randomTrack = animationTracks[random:NextInteger(1, #animationTracks)]

        pcall(function()
            randomTrack:Play(0.05, 1, random:NextNumber(0.8, 1.2))
        end)
        task.delay(0.25, function()
            pcall(function()
                randomTrack:Stop(0.1)
            end)
        end)
    end

    return module
end


return aa()

]=],
    ["Features/Exploits/FlingPlayers"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local signal = a["Utility/Signal"]()
    local runService = game:GetService('RunService')
    local players = game:GetService('Players')

    game:GetService('TweenService')

    local newMaid = maid.new()
    local ai
    local aj
    local al = 1
    local am = false
    local getLocalRoot = function()
        local character = players.LocalPlayer and players.LocalPlayer.Character

        return character and character:FindFirstChild('HumanoidRootPart')
    end
    local findNearestEnemyRoot = function(origin, radius)
        local nearestRoot, nearestDistance

        for index, player in ipairs(players:GetPlayers())do
            if player == players.LocalPlayer then
                continue
            end

            local candidateCharacter = player.Character
            local candidateRoot = candidateCharacter and candidateCharacter:FindFirstChild('HumanoidRootPart')

            if not candidateRoot then
                continue
            end

            local playerDistance = (candidateRoot.Position - origin).Magnitude

            if playerDistance <= radius and (not nearestDistance or playerDistance < nearestDistance) then
                nearestRoot, nearestDistance = candidateRoot, playerDistance
            end
        end

        return nearestRoot
    end
    local applyFlingVelocity = function(flingPart, flingVelocity)
        ai = flingPart.Velocity
        aj = flingPart.AssemblyAngularVelocity
        al = -al
        flingPart.Velocity = flingVelocity
        flingPart.AssemblyAngularVelocity = Vector3.new(9e9, 9e9, 9e9) * al
    end
    local restorePartVelocity = function(restorePart)
        if ai == nil then
            return
        end
        if restorePart then
            restorePart.Velocity = ai

            if aj ~= nil then
                restorePart.AssemblyAngularVelocity = aj
            end
        end

        ai = nil
        aj = nil
    end
    local startFlingPlayers = function()
        if am then
            return
        end
        if not configuration.expectToggleValue('FlingPlayers') then
            return
        end

        local selfRoot = getLocalRoot()

        if not selfRoot then
            return
        end
        if not findNearestEnemyRoot(selfRoot.Position, 8) then
            return
        end

        applyFlingVelocity(selfRoot, Vector3.new(0, 9e9, 0))
    end
    local stopFlingPlayers = function()
        if am then
            return
        end

        restorePartVelocity(getLocalRoot())
    end
    local trackToDestination = function(destination)
        local deadline = os.clock() + 8

        while os.clock() < deadline do
            local currentRoot = getLocalRoot()

            if not currentRoot then
                return
            end

            local currentPos = currentRoot.Position
            local distance = (destination - currentPos).Magnitude

            if distance <= 2 then
                currentRoot.CFrame = CFrame.new(destination)

                return
            end

            local deltaTime = runService.Heartbeat:Wait()
            local step = math.min(distance, 2500 * deltaTime)

            currentRoot.CFrame = CFrame.new(currentPos + (destination - currentPos).Unit * step)
        end
    end
    local applyFlingForDuration = function(velocity, duration)
        local heartConnection, renderConnection

        heartConnection = runService.Heartbeat:Connect(function()
            local activeRoot = getLocalRoot()

            if activeRoot then
                applyFlingVelocity(activeRoot, velocity)
            end
        end)
        renderConnection = runService.PreRender:Connect(function()
            restorePartVelocity(getLocalRoot())
        end)

        task.wait(duration)
        heartConnection:Disconnect()
        renderConnection:Disconnect()
        restorePartVelocity(getLocalRoot())
    end
    local getComboTargetRoot = function()
        local targetName = configuration.expectOptionValue('FlingComboTarget')

        if not targetName or targetName == '' then
            return nil
        end

        local comboPlayer = players:FindFirstChild(targetName)
        local comboCharacter = comboPlayer and comboPlayer.Character

        return comboCharacter and comboCharacter:FindFirstChild('HumanoidRootPart')
    end

    function module.runCombo()
        if am then
            return logger.warn('Fling combo already running.')
        end
        if not getComboTargetRoot() then
            return logger.warn('Fling combo: pick a valid Combo Target first.')
        end

        am = true

        task.spawn(function()
            local localPlayer = players.LocalPlayer
            local character = localPlayer and localPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass('Humanoid')
            local isAlive = function()
                return character and character.Parent and humanoid and humanoid.Health > 0 and localPlayer.Character == character
            end
            local snapToTarget = function(targetRoot)
                local playerRoot = getLocalRoot()

                if not playerRoot then
                    return nil
                end

                playerRoot.CFrame = targetRoot.CFrame
                playerRoot.AssemblyLinearVelocity = Vector3.zero

                return playerRoot
            end
            local success, err = pcall(function()
                if not isAlive() then
                    return
                end

                local comboPlayerRoot = getLocalRoot()

                if not comboPlayerRoot then
                    return
                end

                trackToDestination(comboPlayerRoot.Position + Vector3.new(0, 4000, 0))

                if not isAlive() then
                    return
                end

                local comboTargetRoot = getComboTargetRoot()

                if not comboTargetRoot then
                    return
                end

                trackToDestination(comboTargetRoot.Position + Vector3.new(0, 4000, 0))

                if not isAlive() then
                    return
                end

                comboTargetRoot = getComboTargetRoot()

                if not comboTargetRoot or not snapToTarget(comboTargetRoot) then
                    return
                end

                applyFlingForDuration(Vector3.new(0, 9e9, 0), 0.2)
                task.wait(0.1)

                if not isAlive() then
                    return
                end

                comboTargetRoot = getComboTargetRoot()

                if not comboTargetRoot or not snapToTarget(comboTargetRoot) then
                    return
                end

                applyFlingForDuration(Vector3.new(0, 9e9, 0), 0.2)
            end)

            am = false

            local finalRoot = getLocalRoot()

            if finalRoot then
                finalRoot.AssemblyLinearVelocity = Vector3.zero
            end
            if not success then
                logger.warn('Fling combo error: %s', tostring(err))
            end
        end)
    end
    function module.init()
        local heartbeatSignal = signal.new(runService.Heartbeat)
        local preRenderSignal = signal.new(runService.PreRender)

        newMaid:add(heartbeatSignal:connect('FlingPlayers_Heartbeat', startFlingPlayers))
        newMaid:add(preRenderSignal:connect('FlingPlayers_PreRender', stopFlingPlayers))
        logger.warn('FlingPlayers initialized.')
    end
    function module.detach()
        newMaid:clean()
        restorePartVelocity(getLocalRoot())
        logger.warn('FlingPlayers detached.')
    end

    return module
end


return aa()

]=],
    ["Features/Exploits/InputExploit"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local feature = a["Features/Feature"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local userInputService = game:GetService('UserInputService')
    local infiniteJumpFeature = feature.new('InfiniteJump', runService.PreSimulation, function()
        if configuration.expectToggleValue('Flight') then
            return
        end
        if not userInputService:IsKeyDown(Enum.KeyCode.Space) then
            return
        end

        local character = players.LocalPlayer and players.LocalPlayer.Character

        if not character then
            return
        end

        local rootPart = character:FindFirstChild('HumanoidRootPart')

        if not rootPart then
            return
        end

        rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
        rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity + Vector3.new(0, configuration.expectOptionValue('InfiniteJumpBoost'), 0)
    end)

    return infiniteJumpFeature
end


return aa()

]=],
    ["Features/Exploits/MobControl"] = [=[
local aa = function()
    local mobControl = {}
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local maidClass = a["Utility/Maid"]()
    local signal = a["Utility/Signal"]()
    local runService = game:GetService('RunService')
    local players = game:GetService('Players')
    local maid = maidClass.new()
    local part = Instance.new('Part')

    part.Parent = workspace

    local networkOwner = gethiddenproperty(part, 'NetworkOwnerV3')

    part:Destroy()

    local al = function(isNetworkOwner)
        local success, owner = pcall(gethiddenproperty, isNetworkOwner, 'NetworkOwnerV3')

        return success and owner == networkOwner
    end
    local am = 0
    local an = false
    local ao = false
    local ap = 0
    local updateReplicationFocus = function()
        local localPlayer = players.LocalPlayer
        local rootPart = localPlayer and localPlayer.Character and localPlayer.Character:FindFirstChild('HumanoidRootPart')

        if localPlayer and rootPart then
            pcall(function()
                localPlayer.ReplicationFocus = rootPart
            end)
        end
    end
    local stopMobControl = function()
        if not an then
            return
        end

        an = false
        ao = false

        updateReplicationFocus()
    end
    local handleTick = function(mobList)
        local currentTime = os.clock()

        if ao then
            if currentTime - ap >= 0.15 then
                ao = false
                ap = currentTime

                updateReplicationFocus()
            end

            return
        end
        if currentTime - ap < (0.6 - 0.15) then
            return
        end
        if #mobList == 0 then
            return
        end

        ap = currentTime
        ao = true
        an = true
        am = (am % #mobList) + 1

        local selectedPart = mobList[am]

        if selectedPart and selectedPart.Parent then
            pcall(function()
                players.LocalPlayer.ReplicationFocus = selectedPart
            end)
            pcall(sethiddenproperty, selectedPart, 'NetworkIsSleeping', false)
        end
    end
    local setSimulationRadius = function(simTarget)
        if setsimulationradius then
            setsimulationradius(math.huge, math.huge)
        else
            sethiddenproperty(simTarget, 'MaxSimulationRadius', 9e9)
            sethiddenproperty(simTarget, 'SimulationRadius', 9e9)
        end
    end
    local getBringOffset = function()
        local offsetX = configuration.expectOptionValue('BringMobsOffsetX') or 0
        local offsetY = configuration.expectOptionValue('BringMobsOffsetY') or 0
        local offsetZ = configuration.expectOptionValue('BringMobsOffsetZ') or 0

        return Vector3.new(offsetX, offsetY, offsetZ)
    end
    local forEachMob = function(callback)
        local player = players.LocalPlayer

        if not player then
            return
        end

        setSimulationRadius(player)

        local liveFolder = workspace:FindFirstChild('Live')

        if not liveFolder then
            return
        end

        local extendRange = configuration.expectToggleValue('MobExtendRange') == true
        local character = player.Character
        local queue = extendRange and {} or nil

        for index, part in ipairs(liveFolder:GetChildren())do
            if part.Name:sub(1, 1) ~= '.' then
                continue
            end
            if part == character then
                continue
            end

            local root = part:FindFirstChild('HumanoidRootPart')

            if not root then
                continue
            end
            if al(root) then
                callback(root)
            elseif extendRange then
                queue[#queue + 1] = root
            end
        end

        if extendRange then
            handleTick(queue)
        end
    end
    local bringMobsToPosition = function(position)
        local offsetPosition = position + getBringOffset()
        local targetCFrame = CFrame.new(offsetPosition.X, offsetPosition.Y, offsetPosition.Z)

        forEachMob(function(mobPart)
            mobPart.CFrame = targetCFrame
            mobPart.AssemblyLinearVelocity = Vector3.zero

            sethiddenproperty(mobPart, 'NetworkIsSleeping', false)
        end)
    end
    local teleportMobsTo = function(teleportCFrame)
        forEachMob(function(teleportPart)
            teleportPart.CFrame = teleportCFrame
            teleportPart.AssemblyLinearVelocity = Vector3.zero

            sethiddenproperty(teleportPart, 'NetworkIsSleeping', false)
        end)
    end
    local findTargetPlayer = function()
        local targetName = configuration.expectOptionValue('TPMobsTarget')

        if type(targetName) ~= 'string' or #targetName == 0 then
            return nil
        end

        return players:FindFirstChild(targetName)
    end
    local teleportMobs = function()
        if configuration.expectToggleValue('TPMobs') then
            local targetPlayer = findTargetPlayer()
            local targetRoot = targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChild('HumanoidRootPart')

            if targetRoot then
                if configuration.expectToggleValue('AttachMobsBack') then
                    teleportMobsTo(targetRoot.CFrame * CFrame.new(0, 0, 3))
                else
                    bringMobsToPosition(targetRoot.Position)
                end

                return
            end
        end
        if configuration.expectToggleValue('BringMobs') then
            local selfCharacter = players.LocalPlayer and players.LocalPlayer.Character
            local selfRoot = selfCharacter and selfCharacter:FindFirstChild('HumanoidRootPart')

            if selfRoot then
                bringMobsToPosition(selfRoot.Position)

                return
            end
        end

        stopMobControl()
    end

    function mobControl.init()
        local updateSignal = signal.new(runService.Heartbeat)

        maid:add(updateSignal:connect('MobControl_Update', teleportMobs))
        logger.warn('MobControl initialized.')
    end
    function mobControl.detach()
        maid:clean()
        stopMobControl()
        logger.warn('MobControl detached.')
    end

    return mobControl
end


return aa()

]=],
    ["Features/Exploits/RaceMorph"] = [=[
local aa = function()
    local module = {}
    local logger = a["Utility/Logger"]()
    local assetFolder = Instance.new('Folder')

    assetFolder.Name = 'PalantirX_RaceMorph'

    local guiAssetPath = 'PalantirX/Morphs' .. '/GuiItself.rbxm'
    local decodeBase64 = function(encoded)
        if crypt and crypt.base64decode then
            return crypt.base64decode(encoded)
        end
        if crypt and crypt.base64 and crypt.base64.decode then
            return crypt.base64.decode(encoded)
        end
        if type(base64_decode) == 'function' then
            return base64_decode(encoded)
        end
        if base64 and base64.decode then
            return base64.decode(encoded)
        end

        return nil
    end
    local getColorValue = function(parent, childName)
        local child = parent and (parent:FindFirstChild(childName) or (parent.Parent and parent.Parent:FindFirstChild(childName)))

        return (child and child.Value) or Color3.new(1, 1, 1)
    end
    local setupAssetStorage = function()
        if not (type(writefile) == 'function' and type(isfile) == 'function') then
            return false, 'executor exposes no filesystem access'
        end
        if type(makefolder) == 'function' then
            pcall(makefolder, 'PalantirX')
            pcall(makefolder, 'PalantirX/Morphs')
            pcall(makefolder, 'PalantirX/Morphs' .. '/CustomRaces')
            pcall(makefolder, 'PalantirX/Morphs' .. '/CustomEnchantments')
            pcall(makefolder, 'PalantirX/Morphs' .. '/CustomGlobalOrnaments')
            pcall(makefolder, 'PalantirX/Morphs' .. '/Preferences')
        end
        if isfile(guiAssetPath) then
            return true
        end

        local success, decoded = pcall(function()
            return decodeBase64(a["Game/Data/ExplicitJointsBlob"]())
        end)

        if success and type(decoded) == 'string' and #decoded > 1000 then
            pcall(writefile, guiAssetPath, decoded)

            if isfile(guiAssetPath) then
                return true
            end
        end

        local content
        local fetchedOk, fetchedData = pcall(function()
            return game:HttpGet(
"https://raw.githubusercontent.com/steelgeem-sketch/PalantirX/master/assets/Morphs/GuiItself.rbxm", true)
        end)

        if fetchedOk and type(fetchedData) == 'string' then
            content = fetchedData
        else
            local am = (syn and syn.request) or request or http_request or (http and http.request)

            if am then
                local requestOk, response = pcall(am, {
                    Url = 
"https://raw.githubusercontent.com/steelgeem-sketch/PalantirX/master/assets/Morphs/GuiItself.rbxm",
                    Method = 'GET',
                })

                if requestOk and type(response) == 'table' and type(response.Body) == 'string' then
                    content = response.Body
                end
            end
        end
        if type(content) ~= 'string' or #content < 1000 then
            return false, 'no base64 decoder and download failed'
        end

        pcall(writefile, guiAssetPath, content)

        return isfile(guiAssetPath) == true
    end

    function module.open()
        if getgenv().race_morph_menu_loaded then
            if getgenv().race_morph_menu_frame then
                getgenv().race_morph_menu_frame.Visible = true
            end

            return
        end
        if not game:IsLoaded() then
            game.Loaded:Wait()
        end

        game:GetService('StarterGui'):SetCore('SendNotification', {
            Title = "Morph Gui's Loading...",
            Text = '(F4 is the current shortcut.)',
            Duration = 10,
        })

        local runService = game:GetService('RunService')
        local tweenService = game:GetService('TweenService')
        local replicatedStorage = game:GetService('ReplicatedStorage')
        local players = game:GetService('Players')
        local userInput = game:GetService('UserInputService')
        local textService = game:GetService('TextService')

        game:GetService('HttpService')

        local localPlayer = players.LocalPlayer
        local guiParent = ((runService:IsStudio() and localPlayer.PlayerGui) or (typeof(gethui) == 'function' and gethui()) or game.CoreGui)
        local dataSlot = localPlayer:GetAttribute('DataSlot')
        local scriptConsentCache = {}
        local warningActive = false

        if (not dataSlot or dataSlot == '') then
            if runService:IsStudio() then
                dataSlot = 'STUDIO'
            else
                local startTime = os.clock()

                repeat
                    task.wait()

                    dataSlot = localPlayer:GetAttribute('DataSlot')
                until (not (not dataSlot or dataSlot == '')) or (os.clock() - startTime > 8)

                if (not dataSlot or dataSlot == '') then
                    dataSlot = 'DEFAULT'

                    logger.warn('[RaceMorph] DataSlot never set after 8s \u{2014} using DEFAULT (are you in a loaded slot?).')
                end
            end
        end

        logger.warn('[RaceMorph] DataSlot=%s \u{2014} loading GUI asset...', tostring(dataSlot))

        local customRaceFiles = {}
        local raceData = {}
        local guildMates = {}
        local configDefaults = {
            RespectOathEyeColor = true,
            ReplicateToGuildMates = false,
            HideOathOrnaments = false,
            CosmeticOnlyMode = false,
            LastRace = 'Adret',
        }
        local raceConfig = {
            ['CON_FIG_DEEZ_NUTS_IN_YO_MOUF'] = configDefaults,
        }
        local morphGui

        if runService:IsStudio() then
            morphGui = assetFolder:WaitForChild('MorphGui')
        else
            if type(getcustomasset) ~= 'function' then
                logger.warnNotify("Race Morph \u{2014} executor has no getcustomasset; can't load the morph GUI.")

                return
            end

            local loadOk, loadErr = setupAssetStorage()

            if not loadOk then
                logger.warnNotify("Race Morph \u{2014} couldn't get the morph GUI (%s).", tostring(loadErr))

                return
            end

            morphGui = game:GetObjects(getcustomasset(guiAssetPath))[1]

            if typeof(morphGui) ~= 'Instance' then
                logger.warnNotify("Race Morph \u{2014} GetObjects returned no GUI (asset didn't load; base64/executor issue). Aborting.")

                return
            end

            logger.warn('[RaceMorph] loaded MainGui=%s, GlobalOrnaments=%s \u{2014} building...', morphGui.ClassName, tostring(morphGui:FindFirstChild('GlobalOrnaments') ~= nil))
        end

        local globalOrnaments = morphGui:WaitForChild('GlobalOrnaments')

        globalOrnaments.Parent = assetFolder

        local enchantmentEffects = morphGui:WaitForChild('EnchantmentEffects')

        enchantmentEffects.Parent = assetFolder

        if not runService:IsStudio() then
            if isfolder('PalantirX/Morphs/CustomEnchantments') then
                local enchantFiles = listfiles('PalantirX/Morphs/CustomEnchantments')

                for index, filePath in pairs(enchantFiles)do
                    local loadedEffect = game:GetObjects(getcustomasset(filePath))[1]

                    if enchantmentEffects:FindFirstChild(loadedEffect.Name) then
                        enchantmentEffects[loadedEffect.Name]:Destroy()
                    end

