        local oathOrnaments = morphGui:WaitForChild('OathOrnaments')

        oathOrnaments.Parent = assetFolder

        local customAccoutrements = morphGui:WaitForChild('CustomAccourtments')

        customAccoutrements.Parent = assetFolder

        local extraDeepFaces = morphGui:WaitForChild('ExtraDeepFaces')

        extraDeepFaces.Parent = assetFolder

        local characterFrame = morphGui:WaitForChild('CharacterFrame')
        local templateButtons = morphGui:WaitForChild('TemplateButtons')

        templateButtons.Parent = assetFolder

        local colorPicker = characterFrame:WaitForChild('ColorPicker')
        local characters = characterFrame:WaitForChild('Characters')
        local pageLayout = characters:WaitForChild('UIPageLayout')
        local gradient = characterFrame:WaitForChild('Gradient')
