        local configMain = characterFrame:WaitForChild('ConfigMain')
        local humanoidDescription = players:GetHumanoidDescriptionFromUserId(localPlayer.UserId)
        local racesFolder = replicatedStorage:WaitForChild('Info'):WaitForChild('Races')
        local assetsFolder = replicatedStorage:WaitForChild('Assets')
        local waitForChild = function(folder, childName, timeout)
            return folder:WaitForChild(childName, timeout or 5)
        end
        local facesFolder = waitForChild(assetsFolder, 'Faces')
        local faceAssets = waitForChild(assetsFolder, 'FaceAssets')
        local raceMarking = faceAssets and waitForChild(faceAssets, 'RaceMarking')
        local browsFolder = faceAssets and waitForChild(faceAssets, 'Brows')
