        local outfitsCache = {}
        local runSvc = game:GetService('RunService')
        local httpService = game:GetService('HttpService')
        local loadCode = function(source, ornament, character, currentVariant)
            local ok, scriptFunc

            if runSvc:IsStudio() then
                ok, scriptFunc = pcall(function()
                    return function()
                        for envIndex, envEntry in pairs(getfenv(1)) do end
                    end
                end)
            else
                ok, scriptFunc = pcall(function()
                    return loadstring(source)
                end)
            end
            if ok then
                local env = getfenv(scriptFunc)

                env.Character = character
                env.CurrentVarient = currentVariant
                env.Ornament = ornament

                setfenv(scriptFunc, env)

                local thread = task.spawn(scriptFunc)

                return thread
            else
                return nil
            end
        end
        local fetchUserOutfits = function(userId)
            local ok, response
            local outfitData = {
                UserId = userId,
                Outfits = {},
            }

            if outfitsCache[userId] then
                return outfitsCache[userId]
            end
            if runSvc:IsStudio() then
                ok, response = pcall(function()
                    return replicatedStorage.HttpRequest:InvokeServer('https://avatar.roproxy.com/v1/users/' .. userId .. '/outfits?page=1&itemsPerPage=100')
                end)
            else
                ok, response = pcall(function()
                    return game:HttpGet('https://avatar.roblox.com/v1/users/' .. userId .. '/outfits?page=1&itemsPerPage=100')
                end)
            end
            if ok then
                local outfits = httpService:JSONDecode(response).data

                for key, outfit in pairs(outfits)do
                    if typeof(outfit) == 'table' then
                        outfitData.Outfits[key] = outfit.id
                    end
                end
            else
            end

            outfitsCache[userId] = outfitData

            return outfitData
        end
        local nameCache = {
            UserNames = {},
            Descriptions = {},
        }
        local getUserIdFromName = function(name)
            if nameCache.UserNames[name] then
                return nameCache.UserNames[name]
            end

            local ok, resolvedId = pcall(function()
                return players:GetUserIdFromNameAsync(name)
            end)

            if ok then
                nameCache.UserNames[name] = resolvedId

                return resolvedId
            else
                return false
            end
        end
        local fetchUserDescription = function(userId)
            if nameCache.Descriptions[userId] then
                return nameCache.Descriptions[userId]
            end

            local ok, response

            if runSvc:IsStudio() then
                ok, response = pcall(function()
                    return replicatedStorage.HttpRequest:InvokeServer('https://users.roproxy.com/v1/users/' .. userId)
                end)
            else
                ok, response = pcall(function()
                    return game:HttpGet('https://users.roblox.com/v1/users/' .. userId)
                end)
            end
            if ok then
                local userInfo = httpService:JSONDecode(response)

                if userInfo.description then
                    nameCache.Descriptions[userId] = userInfo.description

                    return userInfo.description
                else
                    nameCache.Descriptions[userId] = "Woah It's You!"

                    return "Woah It's You!"
                end
            else
                return "Woah It's You!"
            end
        end
        local createTween = function(target, goal, duration, easingStyle, easingDirection, repeats, reverses, delayTime)
            local tweenInfo = TweenInfo.new(duration or 1, easingStyle or Enum.EasingStyle.Linear, easingDirection or Enum.EasingDirection.Out, repeats or 0, reverses or false, delayTime or 0)
            local tween = tweenService:Create(target, tweenInfo, goal)

            tween:Play()

            return tween
        end
        local animateWings = function(wings)
            local a9 = 0
            local loopThread
            local helioWings = wings.Parent.HelioWings
            local wingSegments = {
                Left = {
                    wings['Wing1.L'],
                    wings['Wing1.L']['Wing2.L'],
                    wings['Wing1.L']['Wing2.L']['Wing3.L'],
                    wings['Wing1.L']['Wing2.L']['Wing3.L']['Wing4.L'],
                    wings['Wing1.L']['Wing2.L']['Wing3.L']['Wing4.L']['Wing5.L'],
                    wings['Wing1.L']['Wing2.L']['Wing3.L']['Wing4.L']['Wing5.L']['Wing6.L'],
                    wings['Wing1.L']['Wing2.L']['Wing3.L']['Wing4.L']['Wing5.L']['Wing6.L']['Wing7.L'],
                    wings['Wing1.L']['Wing2.L']['Wing3.L']['Wing4.L']['Wing5.L']['Wing6.L']['Wing7.L']['Wing8.L'],
                },
                Right = {
                    wings['Wing1.R'],
                    wings['Wing1.R']['Wing2.R'],
                    wings['Wing1.R']['Wing2.R']['Wing3.R'],
                    wings['Wing1.R']['Wing2.R']['Wing3.R']['Wing4.R'],
                    wings['Wing1.R']['Wing2.R']['Wing3.R']['Wing4.R']['Wing5.R'],
                    wings['Wing1.R']['Wing2.R']['Wing3.R']['Wing4.R']['Wing5.R']['Wing6.R'],
                    wings['Wing1.R']['Wing2.R']['Wing3.R']['Wing4.R']['Wing5.R']['Wing6.R']['Wing7.R'],
                    wings['Wing1.R']['Wing2.R']['Wing3.R']['Wing4.R']['Wing5.R']['Wing6.R']['Wing7.R']['Wing8.R'],
                },
            }
            local animState = {
                AnimationSpeed = 1,
                CurrentAnimation = 'Idle',
                PlayingLoop = false,
            }

            loopThread = task.spawn(function()
                repeat
                    if animState.PlayingLoop == true then
                        a9 += 1

                        task.wait()

                        if animState.CurrentAnimation == 'Fly' then
                            for wingIndex = 1, 8 do
                                local offset = (8 - wingIndex)
                                local leftWing, rightWing = wingSegments.Left[wingIndex], wingSegments.Right[wingIndex]

                                leftWing.Transform = leftWing.Transform:Lerp(CFrame.Angles(math.rad(0 - (4 * offset) * math.sin((a9 + (offset * 7)) / (15 / animState.AnimationSpeed))), 0, 0), 0.1)
                                rightWing.Transform = rightWing.Transform:Lerp(CFrame.Angles(math.rad(0 - (4 * offset) * math.sin((a9 + (offset * 7)) / (15 / animState.AnimationSpeed))), 0, 0), 0.1)
                            end
                        elseif animState.CurrentAnimation == 'Glide' then
                            for wingIndex = 1, 8 do
                                local offset = (8 - wingIndex)
                                local leftWing, rightWing = wingSegments.Left[wingIndex], wingSegments.Right[wingIndex]

                                leftWing.Transform = leftWing.Transform:Lerp(CFrame.Angles(math.rad((offset * 1.1) + offset * math.cos((a9 + offset * 10) / (3 / animState.AnimationSpeed))), 0, math.rad(((4 * offset) / 2) + (offset) * math.sin((a9 + offset * 10) / (6 / animState.AnimationSpeed)))), 0.1)
                                rightWing.Transform = rightWing.Transform:Lerp(CFrame.Angles(math.rad((offset * 1.1) + offset * math.cos((a9 - offset * 10) / (3 / animState.AnimationSpeed))), 0, math.rad(
-((4 * offset) / 2) - (offset) * math.sin((a9 + offset * 10) / (6 / animState.AnimationSpeed)))), 0.1)
                            end
                        elseif animState.CurrentAnimation == 'Idle' then
                            for wingIndex = 1, 8 do
                                local offset = (8 - wingIndex)
                                local leftWing, rightWing = wingSegments.Left[wingIndex], wingSegments.Right[wingIndex]

                                leftWing.Transform = leftWing.Transform:Lerp(CFrame.Angles(0, 0, math.rad((offset * 1.1) - (offset / 4) * math.sin((a9 + offset * 10) / (30 / animState.AnimationSpeed)))), 0.1)
                                rightWing.Transform = rightWing.Transform:Lerp(CFrame.Angles(0, 0, math.rad(
-(offset * 1.1) + (offset / 4) * math.sin((a9 + offset * 10) / (30 / animState.AnimationSpeed)))), 0.1)
                            end
                        end
                    else
                        task.wait()
                    end
                until nil
            end)

            game.ContentProvider:PreloadAsync({
                helioWings.Summon,
                helioWings.Attachment.BurstCore,
            })

            local function PlayAnimation(animName)
                if animName == 'Appear' then
                    animState.PlayingLoop = false
                    helioWings.Transparency = 1

                    helioWings.Summon:Play()
                    wait(0.2)
                    helioWings.Attachment.FallOff:Emit(20)
                    helioWings.Attachment.BurstCore:Emit(5)
                    helioWings.Attachment.Burst:Emit(20)
                    wait(0.3)

                    helioWings.Transparency = 0
                    animState.PlayingLoop = true

                    PlayAnimation('Idle')
                else
                    animState.CurrentAnimation = animName
                    animState.PlayingLoop = true
                end
            end

            return PlayAnimation, loopThread
        end
        local animateMotoredParts = function(mainWeldo)
            task.spawn(function()
                local left = mainWeldo.l
                local leftC0 = left.C0
                local right = mainWeldo.r
                local rightC0 = right.C0
                local bd = 0
                local lastPos = Vector3.new(0, 0, 0)
                local lastVel = Vector3.new(0, 0, 0)

                repeat
                    runSvc.Stepped:Wait()

                    local rotVelocity = mainWeldo.RotVelocity
                    local position = mainWeldo.Position
                    local deltaPos = position - lastPos
                    local deltaVel = rotVelocity - lastVel

                    if deltaPos.Y < -0.2 then
                        deltaPos = Vector3.new(deltaPos.X, -0.2, deltaPos.Z)
                    elseif deltaPos.Y > 0.2 then
                        deltaPos = Vector3.new(deltaPos.X, 0.2, deltaPos.Z)
                    end
                    if deltaPos.X < -0.1 then
                        deltaPos = Vector3.new(-0.1, deltaPos.Y, deltaPos.Z)
                    elseif deltaPos.X > 0.1 then
                        deltaPos = Vector3.new(0.1, deltaPos.Y, deltaPos.Z)
                    end
                    if deltaPos.Z < -0.1 then
                        deltaPos = Vector3.new(deltaPos.X, deltaPos.Y, -0.1)
                    elseif deltaPos.Z > 0.1 then
                        deltaPos = Vector3.new(deltaPos.X, deltaPos.Y, 0.1)
                    end

                    bd += 1

                    left.C0 = left.C0:Lerp(leftC0 * CFrame.new(0, 0 + 0.3 * math.sin(bd / 30), 0 + 0.4 * math.cos(bd / 120)) * CFrame.Angles(math.rad(0 - (30 * (deltaPos.Y / 0.2)) + 5 * math.sin(bd / 30)), math.rad(lastVel.Y * 5), 0), 0.1)
                    right.C0 = right.C0:Lerp(rightC0 * CFrame.new(0, 0 + 0.3 * math.cos(bd / 30), 0 + 0.4 * math.sin(bd / 120)) * CFrame.Angles(math.rad(0 - (30 * (deltaPos.Y / 0.2)) + 5 * math.cos(bd / 30)), math.rad(lastVel.Y * 5), 0), 0.1)
                    lastPos = deltaVel
                    lastVel = rotVelocity
                until not mainWeldo.Parent
            end)
        end
        local animateBones = function(tailModel, rootPart)
            task.spawn(function()
                local boneStates = {}

                for boneIndex = 1, 6 do
                    local bone = tailModel:FindFirstChild('Bone.00' .. boneIndex, true)

                    if bone then
                        boneStates[boneIndex] = {
                            bone.Transform,
                            bone,
                        }
                    end
                end

                local bc = 0
                local prevRotVel = rootPart.RotVelocity
                local prevPosY = rootPart.Position.Y
                local lerpedVel = prevRotVel

                repeat
                    runSvc.Stepped:Wait()

                    bc += 1

                    if not rootPart.Parent.Parent then
                        tailModel:Destroy()

                        return
                    end

                    local posY = rootPart.Position.Y
                    local rotVel = rootPart.RotVelocity
                    local deltaVel = rotVel - prevRotVel
                    local posDiff = prevPosY - posY

                    lerpedVel = lerpedVel:Lerp(deltaVel, 0.2)

                    if posDiff > 1 then
                        posDiff = 1
                    elseif posDiff < -1 then
                        posDiff = -1
                    end

                    for boneIndex, bone in pairs(boneStates)do
                        local phase = bc + (35 / boneIndex)

                        bone[2].Transform = bone[2].Transform:Lerp(bone[1] * CFrame.Angles(math.rad(10 / boneIndex), 0, math.rad(0 - 15 * math.cos(phase / 10))) * CFrame.Angles(
-math.rad((25 * posDiff)), 0, math.rad(lerpedVel.Y * 25)), 0.1)
                    end

                    prevRotVel = rotVel
                    prevPosY = posY
                until not tailModel.Parent
            end)
        end
        local setBodyPartTransparency = function(model, target, hide)
            local transparency = 1

            if hide == true then
                transparency = 0
            end
            if target == 'All' then
                for index, child in pairs(model:GetChildren())do
                    if child:IsA('BasePart') and (child.Name == 'Torso' or child.Name == 'Head' or child.Name == 'Right Leg' or child.Name == 'Left Leg' or child.Name == 'Right Arm' or child.Name == 'Left Arm') then
                        if child.Name == 'Head' then
                            child.Transparency = transparency

                            for index, descendant in pairs(child:GetDescendants())do
                                if descendant.Name == 'FaceMount' then
                                    descendant.Transparency = transparency
                                elseif descendant:IsA('BasePart') then
                                    descendant.Transparency = transparency
                                elseif descendant:IsA('Decal') and descendant.Name == 'ComeOnStepItUp' then
                                    descendant.Transparency = transparency
                                end
                            end
                        else
                            child.Transparency = transparency
                        end
                    elseif child:IsA('Accessory') and child:FindFirstChild('Handle') then
                        child.Handle.Transparency = transparency
                    end
                end
            else
                if typeof(target) == 'string' then
                    for index, child in pairs(model:GetChildren())do
                        if string.find(child.Name, target) then
                            if child:IsA('BasePart') then
                                child.Transparency = transparency
                            elseif child:IsA('Model') then
                                for index, descendant in pairs(child:GetDescendants())do
                                    if descendant:IsA('BasePart') then
                                        descendant.Transparency = transparency
                                    end
                                end
                            end
                        end
                    end
                else
                    target.Transparency = transparency
                end
            end
        end
        local createWeld = function(basePart, attachPart)
            local weld = Instance.new('Weld')

            weld.Part0 = basePart.Parent
            weld.Part1 = attachPart.Parent
            weld.C0 = basePart.CFrame
            weld.C1 = attachPart.CFrame
            weld.Parent = basePart.Parent

            return weld
        end
        local createNamedWeld = function(name, parent, part0, part1, c0, c1)
            local weld = Instance.new('Weld')

            weld.Name = name
            weld.Part0 = part0
            weld.Part1 = part1
            weld.C0 = c0
            weld.C1 = c1
            weld.Parent = parent

            return weld
        end

        local function findFirstMatchingAttachment(instance, attachName)
            for index, child in pairs(instance:GetChildren())do
                if child:IsA('Attachment') and child.Name == attachName then
                    return child
                elseif not child:IsA('Accoutrement') and not child:IsA('Tool') then
                    local result = findFirstMatchingAttachment(child, attachName)

                    if result then
                        return result
                    end
                end
            end
        end

        local attachToHandle = function(character, accessory)
            local handle = accessory:FindFirstChild('Handle')

            if handle then
                handle.CanCollide = false
                handle.Massless = true
                handle.CanTouch = false
                handle.CanQuery = false

                local attachment = handle:FindFirstChildOfClass('Attachment')

                if attachment then
                    local matchAttach = findFirstMatchingAttachment(character, attachment.Name)

                    if matchAttach then
                        createWeld(matchAttach, attachment)
                    end
                else
                    local head = character:FindFirstChild('Head')

                    if head then
                        local attachmentPoint = accessory.AttachmentPoint

                        createNamedWeld('HeadWeld', head, head, handle, CFrame.new(0, 0.5, 0), attachmentPoint)
                    end
                end
            end
        end
        local buildHairAccessories = function(be)
            local hairs = {}

            if be.HairAccessory then
                local assetIds = string.split(be.HairAccessory, ',')

                for index, assetId in pairs(assetIds)do
                    local accessory

                    if tonumber(assetId) then
                        if assetFolder:FindFirstChild(assetId) then
                            accessory = assetFolder[assetId]:Clone()
                        else
                            if runSvc:IsStudio() then
                                accessory = replicatedStorage.LoadAsset:InvokeServer(tonumber(assetId)):FindFirstChildOfClass('Accessory', true)
                            else
                                accessory = game:GetObjects('rbxassetid://' .. assetId)[1]
                            end

                            local mesh = accessory:WaitForChild('Handle'):FindFirstChildOfClass('SpecialMesh')

                            if mesh then
                                mesh.TextureId = 'rbxassetid://7740973748'
                            else
                                accessory.Handle.TextureID = 'rbxassetid://7740973748'
                            end

                            accessory.Name = assetId
                            accessory:Clone().Parent = assetFolder
                        end

                        hairs[index] = accessory
                    end
                end
            end

            return hairs
        end
        local selectRaceMorph = function(raceName, fallback)
            local faces = {}
            local defaultFace
            local prefix = string.sub(raceName, 1, 5)

            if raceName == 'Auroran' or raceName == 'Celestial' then
                local auchura = facesFolder:FindFirstChild('Auchura')
                local nilsa = facesFolder:FindFirstChild('Nilsa')
                local debtCollector = facesFolder:FindFirstChild('DebtCollector')

                if raceName == 'Auroran' and auchura then
                    return {
                        Default = auchura,
                        Decals = {auchura},
                    }
                end
                if raceName == 'Celestial' and nilsa then
                    local decalList = {nilsa}

                    if debtCollector then
                        decalList[#decalList + 1] = debtCollector
                    else
                    end

                    return {
                        Default = nilsa,
                        Decals = decalList,
                    }
                end
            end

            for index, faceFolder in pairs((fallback or facesFolder):GetChildren())do
                if string.find(faceFolder.Name, prefix) then
                    faces[#faces + 1] = faceFolder

                    if faceFolder:FindFirstChild(raceName .. 'Default') then
                        defaultFace = faceFolder
                    end
                end
            end

            if #faces == 0 then
                if fallback then
                    local fallbackFaces = {
                        Default = fallback:FindFirstChildOfClass('Decal'),
                        Decals = fallback:GetChildren(),
                    }
                    local extraFolder = extraDeepFaces:FindFirstChild(raceName)

                    if extraFolder then
                        for index, decal in pairs(extraFolder:GetChildren())do
                            if decal:IsA('Decal') then
                                decal.Name = raceName .. 'Extra' .. index
                                fallbackFaces.Decals[#fallbackFaces.Decals + 1] = decal
                            end
                        end
                    end

                    return fallbackFaces
                else
                    local expressionNames = {
                        'Carefree',
                        'Concerned',
                        'Confident',
                        'Furious',
                        'Unimpressed',
                    }
                    local expressionFaces = {}

                    for index, exprName in pairs(expressionNames)do
                        local expression = facesFolder:FindFirstChild(exprName)

                        if expression then
                            expressionFaces[#expressionFaces + 1] = expression
                        end
                    end

                    if #expressionFaces == 0 then
                        local genericFace = facesFolder:FindFirstChild('GenericFace')

                        return {
                            Default = genericFace,
                            Decals = {genericFace},
                        }
                    end

                    return {
                        Default = facesFolder:FindFirstChild('Confident') or expressionFaces[1],
                        Decals = expressionFaces,
                    }
                end
            else
                if not defaultFace then
                    defaultFace = faces[1]
                end

                local resultFaces = {
                    Default = defaultFace,
                    Decals = faces,
                }
                local extraFolder = extraDeepFaces:FindFirstChild(raceName)

                if extraFolder then
                    for index, decal in pairs(extraFolder:GetChildren())do
                        if decal:IsA('Decal') then
                            decal.Name = raceName .. 'Extra' .. index
                            resultFaces.Decals[#resultFaces.Decals + 1] = decal
                        end
                    end
                end

                return resultFaces
            end
        end
        local applyMorph = function(face, mount, eyeColor, scleraColor, markName)
            local faceClone = face:Clone()

            markName = markName or 'ComeOnStepItUp'

            local existing = mount:FindFirstChild(markName)

            if existing then
                existing:Destroy()
            end

            for index, child in pairs(faceClone:GetChildren())do
                if string.find(child.Name, 'Shape') then
                    local scleraClone = scleraFolder[child.Name]:Clone()

                    scleraClone.Name = markName
                    scleraClone.Color3 = scleraColor
                    scleraClone.Face = Enum.NormalId.Front
                    scleraClone.Parent = mount
                elseif child:IsA('Decal') then
                    child.Name = markName
                    child.Face = Enum.NormalId.Front
                    child.Parent = mount
                elseif child:IsA('Model') then
                    for index, part in pairs(child:GetChildren())do
                        createNamedWeld('a', faceClone, mount, part, part:FindFirstChildOfClass('Attachment').CFrame:Inverse(), CFrame.new(0, 0, 0))

                        part.Color = eyeColor
                        part.Parent = faceClone
                    end

                    child:Destroy()
                end
            end

            faceClone.Name = markName
            faceClone.Color3 = eyeColor
            faceClone.ZIndex = 10

            if faceClone:IsA('Decal') then
                faceClone.Face = Enum.NormalId.Front
            end

            faceClone.Parent = mount
        end
        local hidePartByName = function(targetName, parent)
            for index, child in pairs(parent:GetChildren())do
                if child.Name == targetName then
                    if child:IsA('Model') then
                        for index, descendant in pairs(child:GetDescendants())do
                            if descendant:IsA('BasePart') then
                                descendant.Transparency = 1
                            end
                        end
                    else
                        child.Transparency = 1
                    end
                end
            end
        end
        local loadAnimation = function(character, animator)
            local humanoid = character:FindFirstChildOfClass('Humanoid')

            if humanoid and animator then
                local idleAnim, runAnim, runningConn

                if animator.Parent:FindFirstChild('Idle') then
                    if runSvc:IsStudio() and string.find(animator.Parent.Idle.AnimationId, 'rbxassetid') then
                        animator.Parent.Idle.AnimationId = game.KeyframeSequenceProvider:RegisterKeyframeSequence(animator.Parent.Idle:FindFirstChildOfClass('KeyframeSequence'))
                    end

                    idleAnim = animator:LoadAnimation(animator.Parent.Idle)
                end
                if animator.Parent:FindFirstChild('Run') then
                    if runSvc:IsStudio() and string.find(animator.Parent.Run.AnimationId, 'rbxassetid') then
                        animator.Parent.Run.AnimationId = game.KeyframeSequenceProvider:RegisterKeyframeSequence(animator.Parent.Run:FindFirstChildOfClass('KeyframeSequence'))
                    end

                    runAnim = animator:LoadAnimation(animator.Parent.Run)
                end
                if idleAnim or runAnim then
                    runningConn = humanoid.Running:Connect(function(moveSpeed)
                        if animator.Parent then
                            if moveSpeed > 0 then
                                if not runAnim.IsPlaying then
                                    runAnim:Play(0.100000001, 1, moveSpeed / 16)
                                else
                                    runAnim:AdjustSpeed(moveSpeed / 16)
                                end
                                if idleAnim.IsPlaying then
                                    idleAnim:Stop()
                                end
                            else
                                if not idleAnim.IsPlaying then
                                    idleAnim:Play()
                                end
                                if runAnim.IsPlaying then
                                    runAnim:Stop()
                                end
                            end
                        else
                            runningConn:Disconnect()
                        end
                    end)

                    if humanoid.MoveDirection.Magnitude ~= 0 then
                        runAnim:Play(0.100000001, 1, humanoid.WalkSpeed / 16)
                    else
                        idleAnim:Play()
                    end
                end
            end
        end

        local function ApplyDeepwokenAccourtment(ornament, mountPart, bm, noClone)
            if ornament:IsA('Model') then
                local ornamentClone = ornament:Clone()

                ornamentClone.Name = math.random(1, 100000000)
                ornamentClone.Parent = (mountPart.Parent:FindFirstChild('CustomOrnaments') or mountPart)

                if ornamentClone:FindFirstChild('HideType') then
                    hidePartByName(ornamentClone.HideType.Value, mountPart.Parent)
                end

                local shirt, pants = ornamentClone:FindFirstChildOfClass('Shirt'), ornamentClone:FindFirstChildOfClass('Pants')

                if shirt then
                    local existingShirt = mountPart.Parent:FindFirstChildOfClass('Shirt')

                    if existingShirt then
                        existingShirt.ShirtTemplate = shirt.ShirtTemplate
                    end

                    shirt:Destroy()
                end
                if pants then
                    local existingPants = mountPart.Parent:FindFirstChildOfClass('Pants')

                    if existingPants then
                        existingPants.PantsTemplate = pants.PantsTemplate
                    end

                    pants:Destroy()
                end

                for index, child in pairs(ornamentClone:GetChildren())do
                    if child:IsA('BasePart') then
                        ApplyDeepwokenAccourtment(child, mountPart, bm, true)
                    end
                end

                if ornamentClone:FindFirstChild('HideBody') then
                    setBodyPartTransparency(mountPart.Parent, ornamentClone.HideBody.Value)
                end
                if ornamentClone:FindFirstChild('TailWeld') then
                    if runSvc:IsStudio() then
                        if mountPart.Parent.Parent == workspace then
                            animateBones(ornamentClone, mountPart)
                        end
                    else
                        if mountPart.Parent.Parent:IsA('Folder') then
                            animateBones(ornamentClone, mountPart)
                        end
                    end
                end
                if ornamentClone:FindFirstChildOfClass('AnimationController') then
                    if runSvc:IsStudio() then
                        if mountPart.Parent.Parent == workspace then
                            loadAnimation(mountPart.Parent, ornamentClone.AnimationController)
                        end
                    else
                        if mountPart.Parent.Parent:IsA('Folder') then
                            loadAnimation(mountPart.Parent, ornamentClone.AnimationController)
                        end
                    end
                end
                if ornamentClone:FindFirstChild('MainWeldo') then
                    animateMotoredParts(ornamentClone.MainWeldo)
                end

                return ornamentClone
            else
                local part

                if noClone then
                    part = ornament
                else
                    part = ornament:Clone()
                end
                if part:FindFirstChild('HideType') then
                    hidePartByName(part.HideType.Value, mountPart.Parent)
                end
                if part:FindFirstChild('HideBody') then
                    setBodyPartTransparency(mountPart.Parent, part.HideBody.Value)
                end
                if part:IsA('BasePart') then
                    part.CanCollide = false
                    part.Massless = true
                    part.CanQuery = false
                end
                if part.Name == 'HelioWingsP' then
                    part.HelioWings.Color = getColorValue(bm.CurrentVarient, 'CustomColor1')

                    if (mountPart.Parent.Parent == workspace or mountPart.Parent.Parent:IsA('Folder')) then
                        part.HelioWings.Transparency = 1

                        task.spawn(function()
                            local playAnimation, loopThread = animateWings(part.RootPart)
                            local character = mountPart.Parent
                            local humanoid = character:FindFirstChildOfClass('Humanoid')
                            local parentConn
                            local animationConn

                            animationConn = part:GetPropertyChangedSignal('Parent'):Connect(function(
                            )
                                if not part.Parent or not part.Parent.Parent then
                                    parentConn:Disconnect()
                                    coroutine.close(loopThread)
                                    animationConn:Disconnect()
                                end
                            end)
                            parentConn = humanoid.AnimationPlayed:Connect(function(
                                animation
                            )
                                if not animation then
