                                    legWeld.C0 = CFrame.new(-1, -1, 0, 0, 0, 
-1, 0, 1, 0, 1, 0, 0)
                                    legWeld.C1 = CFrame.new(-0.475, 0.232, 0.714) * CFrame.Angles(math.rad(0.679), math.rad(
-104.985), math.rad(-5.089))

                                    local armWeld = Instance.new('Weld', character['Torso'])

