-1, 0, 1, 0, 1, 0, 0)
                                    armWeld.C1 = CFrame.new(0.48, 0.828, -0.148) * CFrame.Angles(math.rad(6.284), math.rad(
-96.337), math.rad(-0.695))

                                    local headWeld = Instance.new('Weld', character['Torso'])

