                                    headWeld.Part0 = character['Torso']
                                    headWeld.C0 = CFrame.new(0, 1, 0, -1, 0, 0, 0, 0, 1, 0, 1, 
-0)
                                    headWeld.C1 = CFrame.new(0, -0.717000008, 0, 
-1, 0, 0, 0, 0.950549364, 0.310573518, 0, 0.310573518, -0.950549364)

                                    local rightLegWeld = Instance.new('Weld', character['Torso'])

                                    rightLegWeld.Part1 = character['Right Leg']
                                    rightLegWeld.Part0 = character['Torso']
                                    rightLegWeld.C0 = CFrame.new(1, -1, 0, 0, 0, 1, 0, 1, 
-0, -1, 0, 0)
                                    rightLegWeld.C1 = CFrame.new(0.43, 0.313, 0.493) * CFrame.Angles(math.rad(
-4.58), math.rad(98.899), math.rad(34.643))

