                        end
                    elseif descendant:FindFirstChild('LinerColor') then
                        descendant.VertexColor = Vector3.new(getColorValue(bm.CurrentVarient, 'LinerColor').R, getColorValue(bm.CurrentVarient, 'LinerColor').G, getColorValue(bm.CurrentVarient, 'LinerColor').B)
                    elseif descendant:FindFirstChild('EyeColor') then
                        local eyeColor = getColorValue(bm.CurrentVarient, 'EyeColor')

                        if bm.CustomColors[bm.CurrentVarient] and bm.CustomColors[bm.CurrentVarient].EyeColor then
                            eyeColor = bm.CustomColors[bm.CurrentVarient].EyeColor
                        end

                        descendant.Color = eyeColor
                    elseif descendant:FindFirstChild('SkinColor') then
                        if descendant:IsA('Decal') then
                            descendant.Color3 = getColorValue(bm.CurrentVarient, 'SkinColor')
                        else
                            descendant.Color = getColorValue(bm.CurrentVarient, 'SkinColor')
