                        descendant.Color = (hornColor and hornColor.Value) or Color3.new(1, 1, 1)
                    elseif descendant:FindFirstChild('CircletColor') then
                        descendant.Color = getColorValue(bm.CurrentVarient, 'CircletColor')
                    elseif descendant:FindFirstChild('MarkingColor') then
                        local markColor = (bm.CurrentVarient:FindFirstChild('TattooColor') or bm.CurrentVarient.HairColor).Value

                        if bm.CustomColors[bm.CurrentVarient] and bm.CustomColors[bm.CurrentVarient].MarkColor then
                            markColor = bm.CustomColors[bm.CurrentVarient].MarkColor
                        end

                        descendant.Color = markColor
                    elseif descendant:FindFirstChild('CustomColor1') then
                        if descendant:IsA('Decal') then
                            descendant.Color3 = getColorValue(bm.CurrentVarient, 'CustomColor1')
                        else
                            descendant.Color = getColorValue(bm.CurrentVarient, 'CustomColor1')
                        end
                    elseif descendant:FindFirstChild('CustomColor2') then
                        if descendant:IsA('Decal') then
                            descendant.Color3 = getColorValue(bm.CurrentVarient, 'CustomColor2')
                        else
