                    if bm.CustomColors[bm.CurrentVarient] and bm.CustomColors[bm.CurrentVarient].EyeColor then
                        eyeColor = bm.CustomColors[bm.CurrentVarient].EyeColor
                    end

                    part.Color = eyeColor
                elseif part:FindFirstChild('SkinColor') then
                    part.Color = getColorValue(bm.CurrentVarient, 'SkinColor')
                elseif part:FindFirstChild('HornColor') then
                    local hornColor = bm.CurrentVarient:FindFirstChild('HornColor') or (bm.CurrentVarient.Parent and bm.CurrentVarient.Parent:FindFirstChild('HornColor'))

                    part.Color = (hornColor and hornColor.Value) or Color3.new(1, 1, 1)
                elseif part:FindFirstChild('SkullColor') then
                    part.Color = getColorValue(bm.CurrentVarient, 'SkullColor')
                elseif part:FindFirstChild('CircletColor') then
                    part.Color = getColorValue(bm.CurrentVarient, 'CircletColor')
                elseif part:FindFirstChild('MarkingColor') then
                    local markColor = (bm.CurrentVarient:FindFirstChild('TattooColor') or bm.CurrentVarient.HairColor).Value

                    if bm.CustomColors[bm.CurrentVarient] and bm.CustomColors[bm.CurrentVarient].MarkColor then
                        markColor = bm.CustomColors[bm.CurrentVarient].MarkColor
                    end

                    part.Color = markColor
                elseif part:FindFirstChild('CustomColor1') then
                    part.Color = getColorValue(bm.CurrentVarient, 'CustomColor1')
                elseif part:FindFirstChild('CustomColor2') then
                    part.Color = getColorValue(bm.CurrentVarient, 'CustomColor2')
                elseif part:FindFirstChild('CustomColor3') then
                    part.Color = getColorValue(bm.CurrentVarient, 'CustomColor3')
                end
                if part:IsA('BasePart') then
                    part.Anchored = false
                end
                if not noClone then
                    part.Parent = (mountPart.Parent:FindFirstChild('CustomOrnaments') or mountPart)
                end

                local weld = Instance.new('Weld', part)

                if ornament.Name == 'Necklace' then
                    weld.Part0 = mountPart.Parent.Torso
                elseif ornament:GetAttribute('Part0') then
                    weld.Part0 = mountPart.Parent[ornament:GetAttribute('Part0')]
                else
                    weld.Part0 = mountPart
                end

                weld.Part1 = part

                if part:FindFirstChildOfClass('Attachment') then
                    weld.C0 = part:FindFirstChildOfClass('Attachment').CFrame:Inverse()
                end

                return part
            end
        end

        local collectPartsByPattern = function(raceName)
            local ornaments = {}

            for index, folder in pairs(customAccoutrements:GetChildren())do
                if string.find(folder.Name, raceName) then
                    for index, item in pairs(folder:GetChildren())do
                        ornaments[#ornaments + 1] = item
                    end
                end
            end

            if #ornaments > 0 then
                return ornaments
            end

            for index, folder in pairs(raceOrnaments:GetChildren())do
                if string.find(folder.Name, raceName) then
                    for index, item in pairs(folder:GetChildren())do
                        ornaments[#ornaments + 1] = item
                    end
                end
            end

            if #ornaments > 0 then
                return ornaments
            end

            return nil
        end
        local bl = function(variantFolder)
            local variants = {}
            local defaultName = (variantFolder:FindFirstChild('DefaultVariant') or {
                Value = variantFolder.Name,
            }).Value

            if variantFolder:FindFirstChild('SkinColor') then
                variants[defaultName] = variantFolder
            end

            for index, child in pairs(variantFolder:GetChildren())do
                if child:FindFirstChild('SkinColor') then
                    variants[child.Name] = child
                end
            end

            if not variants[defaultName] then
                local firstKey, firstVariant = next(variants)

                if firstVariant then
                    defaultName = firstKey
                end
            end

            return variants, defaultName
        end
        local bm = function(raceName)
            if not raceMarking then
                return nil
            end

            local markingFolder = raceMarking:FindFirstChild(raceName)

            if markingFolder then
                local markings = markingFolder:GetChildren()

                if #markings > 0 then
                    return markings
                end
            end

            local matchedName = raceName == 'Adret' and 'Maudet' or raceName
            local result = {}

            for index, item in pairs(raceMarking:GetChildren())do
                if string.find(item.Name, matchedName) then
                    result[#result + 1] = item
                end
            end

            if #result < 1 then
                for index, item in pairs(raceMarking:GetChildren())do
                    if item:FindFirstChild('Default') and item:IsA('Decal') then
                        result[#result + 1] = item
                    end
                end

                if #result < 1 then
                    return nil
                else
                    return result
                end
            else
                return result
            end
        end
        local bn = function(raceName)
            if not browsFolder then
                return nil
            end

            local bo = browsFolder:FindFirstChild(raceName) or browsFolder:FindFirstChild('Default')

            if bo then
                local brows = bo:GetChildren()

                if #brows > 0 then
                    return brows
                end
            end

            return nil
        end
        local createUserThumbnail = function()
            local outfitData = fetchUserOutfits(raceConfig['You.'].Target_Id)

            for index, child in pairs(configMain.UserConfig.ScrollingFrame.ChoiceTemplate:GetChildren())do
                if child:IsA('ViewportFrame') then
                    child:Destroy()
                end
            end

            local thumbnail = templateButtons.ThumbnailViewportConfig:Clone()

            thumbnail.ImageLabel.Image = 'rbxthumb://type=Avatar&id=' .. outfitData.UserId .. '&w=352&h=352'
            thumbnail.LayoutOrder = 0

            if raceConfig['You.'].Outfit_Id == 'UserId' then
                thumbnail.Selected.Visible = true
            end

            thumbnail.Clickable.MouseButton1Click:Connect(function()
                raceConfig['You.'].Outfit_Id = 'UserId'

                for index, child in pairs(configMain.UserConfig.ScrollingFrame.ChoiceTemplate:GetChildren())do
                    if child:IsA('ViewportFrame') then
                        if child == thumbnail then
                            child.Selected.Visible = true
                        else
                            child.Selected.Visible = false
                        end
                    end
                end
            end)

            thumbnail.Parent = configMain.UserConfig.ScrollingFrame.ChoiceTemplate

            for index, outfitId in pairs(outfitData.Outfits)do
                local thumbnail = templateButtons.ThumbnailViewportConfig:Clone()

                thumbnail.ImageLabel.Image = 'rbxthumb://type=Outfit&id=' .. outfitId .. '&w=420&h=420'
                thumbnail.LayoutOrder = index + 1

                if raceConfig['You.'].Outfit_Id == outfitId then
                    thumbnail.Selected.Visible = true
                end

                thumbnail.Clickable.MouseButton1Click:Connect(function()
                    raceConfig['You.'].Outfit_Id = outfitId

                    for index, child in pairs(configMain.UserConfig.ScrollingFrame.ChoiceTemplate:GetChildren())do
                        if child:IsA('ViewportFrame') then
                            if child == thumbnail then
                                child.Selected.Visible = true
                            else
                                child.Selected.Visible = false
                            end
                        end
                    end
                end)

                thumbnail.Parent = configMain.UserConfig.ScrollingFrame.ChoiceTemplate
            end

            configMain.UserConfig.ScrollingFrame.ChoiceTemplate.Folder.Overlay.Size = UDim2.new(1, 0, 0, configMain.UserConfig.ScrollingFrame.ChoiceTemplate.UIGridLayout.AbsoluteContentSize.Y + 12)
            configMain.UserConfig.ScrollingFrame.CanvasSize = UDim2.fromOffset(configMain.UserConfig.ScrollingFrame.UIListLayout.AbsoluteContentSize.X, configMain.UserConfig.ScrollingFrame.UIListLayout.AbsoluteContentSize.Y)
        end
        local setupCharacterViewport = function(kind, raceName)
            if (kind == 'InGame' and not raceData[raceName]) then
                local viewport = templateButtons:WaitForChild('CharacterViewport'):Clone()
                local dummy = viewport.WorldModel.ThumbnailDummy

                viewport.Clickable.MouseButton1Click:Connect(function()
                    if pageLayout.ScrollWheelInputEnabled then
                        pageLayout:JumpTo(viewport)
