        local oathColors = {
            ['Visionshaper'] = Color3.fromRGB(221, 53, 255),
            ['Jetstriker'] = Color3.fromRGB(123, 215, 255),
        }
        local findOathForCharacter = function(character)
            local player = players:GetPlayerFromCharacter(character)

            if player and player:FindFirstChild('Backpack') then
                for index, item in pairs(player.Backpack:GetChildren())do
                    local findIndex = string.find(item.Name, 'Talent:Oath:')

                    if item:IsA('Folder') and findIndex then
                        local oathName = string.gsub(string.sub(item.Name, findIndex), ' ', '')

                        if oathColors[oathName] then
                            return oathColors[oathName], oathName
                        else
                            return false, nil
                        end
                    end
                end
            end

            return false, nil
        end
        local outfitFolder = Instance.new('Folder', nil)
        local userFolder = Instance.new('Folder', nil)
        local fetchAssetUrl = function(assetId)
            local ok, result = pcall(function()
                local body

                if runSvc:IsStudio() then
                    body = game.ReplicatedStorage.HttpRequest:InvokeServer('https://assetdelivery.roproxy.com/v1/asset/?ID=' .. assetId)
                else
                    body = game:HttpGet('https://assetdelivery.roblox.com/v1/asset/?ID=' .. assetId)
                end

                local urlStart = string.find(body, '<url>')
                local urlEnd = string.find(body, '</url>', urlStart)

                if urlStart and urlEnd then
                    return string.sub(body, urlStart + 5, urlEnd - 1)
                end
            end)

            if ok then
                return result
            else
                return 'rbxassetid://0'
            end
        end
        local buildHumanoidModel = function(head, torso, rightArm, leftArm, rightLeg, leftLeg)
            local humanoidDescription = Instance.new('HumanoidDescription')

            humanoidDescription.Head = head
            humanoidDescription.Torso = torso
            humanoidDescription.RightArm = rightArm
            humanoidDescription.LeftArm = leftArm
            humanoidDescription.RightLeg = rightLeg
            humanoidDescription.LeftLeg = leftLeg

            local model = players:CreateHumanoidModelFromDescription(humanoidDescription, Enum.HumanoidRigType.R6, Enum.AssetTypeVerification.ClientOnly)
            local meshes = {}

            for index, child in pairs(model:GetChildren())do
                if child:IsA('CharacterMesh') then
                    meshes[#meshes + 1] = child
                    child.Parent = nil
                end
            end

            model:Destroy()

            return meshes
        end
        local loadOutfitFromSelection = function()
            local outfitId = raceConfig['You.'].Outfit_Id
            local humanoidDescription
            local folder

            if outfitId == 'UserId' then
                if userFolder:FindFirstChild(raceConfig['You.'].Target_Id) then
                    return userFolder[raceConfig['You.'].Target_Id]:GetChildren()
                else
                    folder = Instance.new('Folder', userFolder)
                    folder.Name = raceConfig['You.'].Target_Id
                    humanoidDescription = players:GetHumanoidDescriptionFromUserId(raceConfig['You.'].Target_Id)
                end
            else
                if outfitFolder:FindFirstChild(outfitId) then
                    return outfitFolder[outfitId]:GetChildren()
                else
                    folder = Instance.new('Folder', outfitFolder)
                    folder.Name = outfitId
                    humanoidDescription = players:GetHumanoidDescriptionFromOutfitId(outfitId)
                end
            end

            for index, accessory in pairs(humanoidDescription:GetAccessories(true))do
                if not accessory.IsLayered then
                    local accessoryClone

                    if runSvc:IsStudio() then
                        accessoryClone = replicatedStorage.LoadAsset:InvokeServer(accessory.AssetId):FindFirstChildOfClass('Accessory', true)
                    else
                        accessoryClone = game:GetObjects('rbxassetid://' .. accessory.AssetId)[1]
                    end

                    accessoryClone.Parent = folder
                end
            end

            Instance.new('Decal', folder).Texture = (humanoidDescription.Face == 0 and 'rbxasset://textures/face.png') or 'rbxthumb://type=Asset&id=' .. humanoidDescription.Face .. '&w=420&h=420'

            local bodyColors = Instance.new('BodyColors', folder)

            bodyColors.TorsoColor3 = humanoidDescription.TorsoColor
            bodyColors.HeadColor3 = humanoidDescription.HeadColor
            bodyColors.LeftArmColor3 = humanoidDescription.LeftArmColor
            bodyColors.RightArmColor3 = humanoidDescription.RightArmColor
            bodyColors.LeftLegColor3 = humanoidDescription.LeftLegColor
            bodyColors.RightLegColor3 = humanoidDescription.RightLegColor

            if humanoidDescription.Shirt ~= 0 then
                local shirt = Instance.new('Shirt', folder)

                shirt.ShirtTemplate = fetchAssetUrl(humanoidDescription.Shirt)
            end
            if humanoidDescription.Pants ~= 0 then
                local pants = Instance.new('Pants', folder)

                pants.PantsTemplate = fetchAssetUrl(humanoidDescription.Pants)
            end

            for index, mesh in pairs(buildHumanoidModel(humanoidDescription.Head, humanoidDescription.Torso, humanoidDescription.RightArm, humanoidDescription.LeftArm, humanoidDescription.RightLeg, humanoidDescription.LeftLeg))do
                mesh.Parent = folder
            end

            return folder:GetChildren()
        end
