        local applyWeaponColor = function(character, effectName, forceApply)
            local effect = enchantmentEffects:FindFirstChild(effectName)
            local player = players:GetPlayerFromCharacter(character) or localPlayer
            local attachNode = workspace:FindFirstChild('Thrown') and workspace.Thrown:FindFirstChild('Attach_' .. player.Name)
            local handWeapon = attachNode and attachNode:FindFirstChild('HandWeapon')
            local extraWeapon = attachNode and attachNode:FindFirstChild('ExtraHandWeapon')
            local sheathedWeapon = attachNode and attachNode:FindFirstChild('SheathedWeapon')

            if effect then
                if handWeapon or sheathedWeapon then
                    for index, weapon in pairs({handWeapon, sheathedWeapon})do
                        if weapon and weapon:IsA('MeshPart') then
                            weapon.Color = effect.Color
                            weapon.Material = effect.Material
                            weapon.Transparency = effect.Transparency
                            weapon.Reflectance = effect.Reflectance

                            for index, descendant in pairs(weapon:GetDescendants())do
                                if descendant:IsA('ParticleEmitter') then
                                    descendant.Texture = 'rbxassetid://0'
                                elseif descendant:IsA('Sound') and descendant.Looped and descendant.IsPlaying then
                                    descendant.Volume = 0
                                elseif descendant:IsA('PointLight') then
                                    descendant.Enabled = false
                                elseif descendant:IsA('SurfaceAppearance') then
                                    if not descendant:GetAttribute('OgColorMap') then
                                        descendant:SetAttribute('OgColorMap', descendant.ColorMap)
                                        descendant:SetAttribute('OgMetalnessMap', descendant.MetalnessMap)
                                        descendant:SetAttribute('OgNormalMap', descendant.NormalMap)
                                        descendant:SetAttribute('OgRoughnessMap', descendant.RoughnessMap)
                                    end

                                    descendant.ColorMap = 'rbxassetid://0'
                                    descendant.MetalnessMap = 'rbxassetid://0'
                                    descendant.NormalMap = 'rbxassetid://0'
                                    descendant.RoughnessMap = 'rbxassetid://0'
                                end
                            end

                            if forceApply then
                                for index, descendant in pairs(weapon:GetDescendants())do
                                    if descendant:IsA('BasePart') then
                                        if descendant.Transparency ~= 1 then
                                            if not descendant:GetAttribute('OgColor') then
                                                descendant:SetAttribute('OgColor', descendant.Color)
                                                descendant:SetAttribute('Material', descendant.Material.Name)
                                                descendant:SetAttribute('Transparency', descendant.Transparency)
                                                descendant:SetAttribute('Reflectance', descendant.Reflectance)
                                            end

                                            descendant.Color = effect.Color
                                            descendant.Material = effect.Material
                                            descendant.Transparency = effect.Transparency
                                            descendant.Reflectance = effect.Reflectance
                                        end
                                    end
                                end
                            end

