                            end

                            if forceApply then
                                for index, descendant in pairs(torsoChild:GetDescendants())do
                                    if descendant:IsA('BasePart') then
                                        if descendant.Transparency ~= 1 then
                                            if not descendant:GetAttribute('OgColor') then
                                                descendant:SetAttribute('OgColor', descendant.Color)
                                                descendant:SetAttribute('Material', descendant.Material.Name)
                                                descendant:SetAttribute('Transparency', descendant.Transparency)
                                                descendant:SetAttribute('Reflectance', descendant.Reflectance)
                                            end

                                            descendant.Color = effect.Color
                                            descendant.Material = effect.Material
                                            descendant.Transparency = effect.Transparency
                                            descendant.Reflectance = effect.Reflectance
                                        end
                                    end
                                end
                            end

                            for index, effChild in pairs(effect:GetChildren())do
                                if effChild:IsA('Attachment') then
                                    if torsoChild:FindFirstChild(effChild.Name) then
                                        for index, child in pairs(effChild:GetChildren())do
                                            local clone = child:Clone()

                                            clone.Parent = torsoChild[effChild.Name]
                                            clone.Name = 'CUSTOM_ENCH_FX'
                                        end
                                    end
                                else
                                    local clone = effChild:Clone()

                                    clone.Parent = torsoChild
                                    clone.Name = 'CUSTOM_ENCH_FX'
                                end
                            end
                        end
                    end
                end
            else
                if handWeapon or sheathedWeapon then
                    for index, weapon in pairs({handWeapon, sheathedWeapon})do
                        if weapon and weapon:IsA('MeshPart') then
                            weapon.Color = Color3.new(1, 1, 1)
                            weapon.Transparency = 0
                            weapon.Reflectance = 0
                            weapon.Material = Enum.Material.Metal

                            for index, descendant in pairs(weapon:GetDescendants())do
                                if descendant.Name == 'CUSTOM_ENCH_FX' then
                                    descendant:Destroy()
                                elseif descendant:IsA('BasePart') and descendant:GetAttribute('OgColor') then
                                    descendant.Color = descendant:GetAttribute('OgColor')
                                    descendant.Transparency = descendant:GetAttribute('Transparency')
                                    descendant.Reflectance = descendant:GetAttribute('Reflectance')
                                    descendant.Material = descendant:GetAttribute('Material')
                                elseif descendant:IsA('SurfaceAppearance') and descendant:GetAttribute('OgColorMap') then
                                    descendant.ColorMap = descendant:GetAttribute('OgColorMap')
                                    descendant.MetalnessMap = descendant:GetAttribute('OgMetalnessMap')
                                    descendant.NormalMap = descendant:GetAttribute('OgNormalMap')
                                    descendant.RoughnessMap = descendant:GetAttribute('OgRoughnessMap')
                                elseif descendant:IsA('ParticleEmitter') or descendant:IsA('PointLight') then
                                    descendant.Parent = fxFolder
                                elseif descendant:IsA('Sound') and descendant.Looped and descendant.IsPlaying then
                                    descendant.Volume = 0
                                end
                            end
                        end
                    end
                end
                if extraWeapon then
                    for index, weapon in pairs({extraWeapon})do
                        if weapon:IsA('MeshPart') then
                            weapon.Color = Color3.new(1, 1, 1)
                            weapon.Transparency = 0
                            weapon.Reflectance = 0
                            weapon.Material = Enum.Material.Metal

                            for index, descendant in pairs(weapon:GetDescendants())do
                                if descendant.Name == 'CUSTOM_ENCH_FX' then
                                    descendant:Destroy()
                                elseif descendant:IsA('BasePart') and descendant:GetAttribute('OgColor') then
                                    descendant.Color = descendant:GetAttribute('OgColor')
                                    descendant.Transparency = descendant:GetAttribute('Transparency')
                                    descendant.Reflectance = descendant:GetAttribute('Reflectance')
                                    descendant.Material = descendant:GetAttribute('Material')
                                elseif descendant:IsA('SurfaceAppearance') and descendant:GetAttribute('OgColorMap') then
                                    descendant.ColorMap = descendant:GetAttribute('OgColorMap')
                                    descendant.MetalnessMap = descendant:GetAttribute('OgMetalnessMap')
                                    descendant.NormalMap = descendant:GetAttribute('OgNormalMap')
                                    descendant.RoughnessMap = descendant:GetAttribute('OgRoughnessMap')
                                elseif descendant:IsA('ParticleEmitter') or descendant:IsA('PointLight') then
                                    descendant.Parent = fxFolder
                                elseif descendant:IsA('Sound') and descendant.Looped and descendant.IsPlaying then
                                    descendant.Volume = 0
                                end
                            end
                        end
                    end
                end
                if character:FindFirstChild('Torso') then
                    for index, torsoChild in pairs(character.Torso:GetChildren())do
                        if torsoChild.Name == 'WeldedBack' then
                            if torsoChild then
                                torsoChild.Color = Color3.new(1, 1, 1)
                                torsoChild.Transparency = 0
                                torsoChild.Reflectance = 0
                                torsoChild.Material = Enum.Material.Metal

                                for index, descendant in pairs(torsoChild:GetDescendants())do
                                    if descendant.Name == 'CUSTOM_ENCH_FX' then
                                        descendant:Destroy()
                                    elseif descendant:IsA('BasePart') and descendant:GetAttribute('OgColor') then
                                        descendant.Color = descendant:GetAttribute('OgColor')
                                        descendant.Transparency = descendant:GetAttribute('Transparency')
                                        descendant.Reflectance = descendant:GetAttribute('Reflectance')
                                        descendant.Material = descendant:GetAttribute('Material')
                                    elseif descendant:IsA('SurfaceAppearance') and descendant:GetAttribute('OgColorMap') then
                                        descendant.ColorMap = descendant:GetAttribute('OgColorMap')
                                        descendant.MetalnessMap = descendant:GetAttribute('OgMetalnessMap')
                                        descendant.NormalMap = descendant:GetAttribute('OgNormalMap')
                                        descendant.RoughnessMap = descendant:GetAttribute('OgRoughnessMap')
                                    end
                                end
                            end
                        end
                    end
                end
                if character:FindFirstChild('OffhandedWeldedBack') then
                    local offhandBack = character.OffhandedWeldedBack

                    offhandBack.Color = Color3.new(1, 1, 1)
                    offhandBack.Transparency = 0
                    offhandBack.Reflectance = 0
                    offhandBack.Material = Enum.Material.Metal

                    for index, descendant in pairs(offhandBack:GetDescendants())do
                        if descendant.Name == 'CUSTOM_ENCH_FX' then
                            descendant:Destroy()
                        elseif descendant:IsA('BasePart') and descendant:GetAttribute('OgColor') then
                            descendant.Color = descendant:GetAttribute('OgColor')
                            descendant.Transparency = descendant:GetAttribute('Transparency')
                            descendant.Reflectance = descendant:GetAttribute('Reflectance')
                            descendant.Material = descendant:GetAttribute('Material')
                        elseif descendant:IsA('SurfaceAppearance') and descendant:GetAttribute('OgColorMap') then
                            descendant.ColorMap = descendant:GetAttribute('OgColorMap')
                            descendant.MetalnessMap = descendant:GetAttribute('OgMetalnessMap')
                            descendant.NormalMap = descendant:GetAttribute('OgNormalMap')
                            descendant.RoughnessMap = descendant:GetAttribute('OgRoughnessMap')
                        end
                    end
                end
            end
        end

        local function ApplyToCharacter(bC, player, force, cosmeticOnly)
            local currentConfig = (bC or raceConfig[pageLayout.CurrentPage.Name])
            local targetPlayer = (player or localPlayer)
            local character = targetPlayer.Character
            local oathColor = findOathForCharacter(character)

            if not character then
                targetPlayer.CharacterAdded:Wait()

                character = targetPlayer.Character
            end
            if characterConnections[targetPlayer.UserId] then
                if characterConnections[targetPlayer.UserId][1] and not characterConnections[targetPlayer.UserId][3] then
                    characterConnections[targetPlayer.UserId][1]:Disconnect()

                    characterConnections[targetPlayer.UserId] = {nil, nil, false}
                    characterConnections[targetPlayer.UserId][1] = targetPlayer.CharacterAdded:Connect(function(
                        newCharacter
                    )
                        if characterConnections[targetPlayer.UserId][2] then
                            characterConnections[targetPlayer.UserId][2]:Disconnect()
                        end

                        characterConnections[targetPlayer.UserId][2] = newCharacter.ChildAdded:Connect(function(
                            newChild
                        )
                            if (newChild:IsA('MeshPart') or newChild:IsA('Accessory')) and newChild.Name ~= 'CustomOrnaments' and not characterConnections[targetPlayer.UserId][3] then
                                characterConnections[targetPlayer.UserId][3] = true

                                delay(0.4, function()
                                    ApplyToCharacter(currentConfig, targetPlayer)

                                    characterConnections[targetPlayer.UserId][3] = false
                                end)
                            end
                        end)

                        delay(0.4, function()
                            characterConnections[targetPlayer.UserId][3] = true

                            ApplyToCharacter(currentConfig, targetPlayer)

                            characterConnections[targetPlayer.UserId][3] = false
                        end)
                    end)
                    characterConnections[targetPlayer.UserId][2] = character.ChildAdded:Connect(function(
                        newChild
                    )
                        if (newChild:IsA('MeshPart') or newChild:IsA('Accessory')) and newChild.Name ~= 'CustomOrnaments' and not characterConnections[targetPlayer.UserId][3] then
                            characterConnections[targetPlayer.UserId][3] = true

                            delay(0.4, function()
                                ApplyToCharacter(currentConfig, targetPlayer)

                                characterConnections[targetPlayer.UserId][3] = false
                            end)
                        end
                    end)
                end
            else
                characterConnections[targetPlayer.UserId] = {nil, nil, false}
                characterConnections[targetPlayer.UserId][1] = targetPlayer.CharacterAdded:Connect(function(
                    newCharacter
                )
                    if characterConnections[targetPlayer.UserId][2] then
                        characterConnections[targetPlayer.UserId][2]:Disconnect()
                    end

                    characterConnections[targetPlayer.UserId][2] = newCharacter.ChildAdded:Connect(function(
                        newChild
                    )
                        if (newChild:IsA('MeshPart') or newChild:IsA('Accessory')) and newChild.Name ~= 'CustomOrnaments' and not characterConnections[targetPlayer.UserId][3] then
                            characterConnections[targetPlayer.UserId][3] = true

                            delay(0.4, function()
                                ApplyToCharacter(currentConfig, targetPlayer)

                                characterConnections[targetPlayer.UserId][3] = false
                            end)
                        end
                    end)

                    delay(0.4, function()
                        characterConnections[targetPlayer.UserId][3] = true

                        ApplyToCharacter(currentConfig, targetPlayer)

                        characterConnections[targetPlayer.UserId][3] = false
                    end)
                end)
                characterConnections[targetPlayer.UserId][2] = character.ChildAdded:Connect(function(newChild)
                    if (newChild:IsA('MeshPart') or newChild:IsA('Accessory')) and newChild.Name ~= 'CustomOrnaments' and not characterConnections[targetPlayer.UserId][3] then
                        characterConnections[targetPlayer.UserId][3] = true

                        delay(0.4, function()
                            ApplyToCharacter(currentConfig, targetPlayer)

                            characterConnections[targetPlayer.UserId][3] = false
                        end)
                    end
                end)
            end

            characterConnections[targetPlayer.UserId][3] = true

            if not force then
                wait(0.8)
            end
            if character:FindFirstChild('CustomOrnaments') then
                character.CustomOrnaments:Destroy()
            end

            do
                local shirt = character:FindFirstChildOfClass('Shirt')
                local pants = character:FindFirstChildOfClass('Pants')

                if not templateCache[targetPlayer.UserId] then
                    templateCache[targetPlayer.UserId] = {
                        ShirtTemplate = shirt and shirt.ShirtTemplate,
                        PantsTemplate = pants and pants.PantsTemplate,
                    }
                end

                local savedTemplates = templateCache[targetPlayer.UserId]

                if shirt and savedTemplates.ShirtTemplate then
                    shirt.ShirtTemplate = savedTemplates.ShirtTemplate
                end
                if pants and savedTemplates.PantsTemplate then
                    pants.PantsTemplate = savedTemplates.PantsTemplate
                end
            end

            if not cosmeticOnly then
                setBodyPartTransparency(character, 'All', true)

                local bodyParts = {
                    Head = true,
                    Torso = true,
                    HumanoidRootPart = true,
                    ['Right Arm'] = true,
                    ['Left Arm'] = true,
                    ['Right Leg'] = true,
                    ['Left Leg'] = true,
                }

                for index, child in pairs(character:GetChildren())do
                    if child:IsA('MeshPart') and not bodyParts[child.Name] and (raceOrnaments:FindFirstChild(child.Name, true) or customAccoutrements:FindFirstChild(child.Name, true)) then
                        child.Transparency = 1

                        for index, descendant in pairs(child:GetDescendants())do
                            if descendant:IsA('Decal') or descendant:IsA('BasePart') then
                                descendant.Transparency = 1
                            end
                        end
                    elseif child:IsA('CharacterMesh') then
                        child:Destroy()
                    elseif child:IsA('Accessory') then
                        if currentConfig.Outfit_Id then
                            child:WaitForChild('Handle').Transparency = 1
                        else
                            child:WaitForChild('Handle').Transparency = 0

                            local mesh = child.Handle:FindFirstChildOfClass('SpecialMesh')

                            if mesh then
                                mesh.VertexColor = Vector3.new(getColorValue(currentConfig.CurrentVarient, 'HairColor').R, getColorValue(currentConfig.CurrentVarient, 'HairColor').G, getColorValue(currentConfig.CurrentVarient, 'HairColor').B)
                            end
                        end
                    elseif string.find(child.Name, 'KhanCirclet') or string.find(child.Name, 'CapraSkull') or string.find(child.Name, 'CapraMask') or string.find(child.Name, 'CapraHorns') or child.Name == 'KhanHair' or child.Name == 'CanorHair' or child.Name == 'TiranFeathers' then
                        child.Transparency = 1
                    end
                end
                for index, child in pairs(character:WaitForChild('Head'):GetChildren())do
                    if child:IsA('BasePart') then
                        for index, descendant in pairs(child:GetChildren())do
                            if descendant:IsA('Decal') then
                                if descendant.Name == 'ComeOnStepItUp' or descendant.Name == 'ComeOnStepItUpMark' then
                                    descendant:Destroy()
                                else
                                    descendant.Transparency = 1
                                end
                            end
                        end
                    end
                end

                if character:FindFirstChild('VespMask') then
                    character.VespMask.Transparency = 1
                    character.VespMask:FindFirstChildOfClass('Decal').Transparency = 1
                end
            end

            Instance.new('Folder', character).Name = 'CustomOrnaments'

            if currentConfig.Outfit_Id and not cosmeticOnly then
                setBodyPartTransparency(character, 'Equipment', false)
                setBodyPartTransparency(character, 'Cosmetic', false)
                setBodyPartTransparency(character, 'Ring', false)

                for index, outfitItem in pairs(loadOutfitFromSelection())do
                    local clone = outfitItem:Clone()

                    if clone:IsA('Accessory') then
                        clone.Handle.Anchored = false

                        attachToHandle(character, clone)
                        task.wait()

                        clone.Parent = character.CustomOrnaments
                    elseif clone:IsA('Decal') then
                        applyMorph(clone:Clone(), character:WaitForChild('Head'):WaitForChild('FaceMount'), Color3.new(1, 1, 1))
                    elseif clone:IsA('Shirt') then
                        local shirt = character:FindFirstChildOfClass('Shirt')

                        if shirt then
                            shirt.ShirtTemplate = clone.ShirtTemplate
                        else
                            shirt:Clone().Parent = character
                        end
                    elseif clone:IsA('Pants') then
                        local pants = character:FindFirstChildOfClass('Pants')

                        if pants then
                            pants.PantsTemplate = clone.PantsTemplate
                        else
                            pants:Clone().Parent = character
                        end
                    elseif clone:IsA('CharacterMesh') then
                        clone:Clone().Parent = character
                    elseif clone:IsA('BodyColors') then
                        if character:FindFirstChild('Head') then
                            character['Head'].Color = clone.HeadColor3

                            if character.Head:FindFirstChild('FaceMount') then
                                character.Head['FaceMount'].Color = clone.HeadColor3
                            end
                            if character.Head:FindFirstChild('MarkingMount') then
                                character.Head['MarkingMount'].Color = clone.HeadColor3
                            end
                        end
                        if character:FindFirstChild('Torso') then
                            character['Torso'].Color = clone.TorsoColor3
                        end
                        if character:FindFirstChild('Right Arm') then
                            character['Right Arm'].Color = clone.RightArmColor3
                        end
                        if character:FindFirstChild('Left Arm') then
                            character['Left Arm'].Color = clone.LeftArmColor3
                        end
                        if character:FindFirstChild('Right Leg') then
                            character['Right Leg'].Color = clone.RightLegColor3
                        end
                        if character:FindFirstChild('Left Leg') then
                            character['Left Leg'].Color = clone.LeftLegColor3
                        end
                    end
                end
            else
                local eyeColor = getColorValue(currentConfig.CurrentVarient, 'EyeColor')
                local markColor = (currentConfig.CurrentVarient:FindFirstChild('TattooColor') or currentConfig.CurrentVarient.HairColor).Value

                if raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.RespectOathEyeColor then
                    if oathColor then
                        eyeColor = oathColor
                    else
                        if currentConfig.CustomColors[currentConfig.CurrentVarient] and currentConfig.CustomColors[currentConfig.CurrentVarient].EyeColor then
                            eyeColor = currentConfig.CustomColors[currentConfig.CurrentVarient].EyeColor
                        end
                    end
                else
                    if currentConfig.CustomColors[currentConfig.CurrentVarient] and currentConfig.CustomColors[currentConfig.CurrentVarient].EyeColor then
                        eyeColor = currentConfig.CustomColors[currentConfig.CurrentVarient].EyeColor
                    end
                end
                if currentConfig.CustomColors[currentConfig.CurrentVarient] and currentConfig.CustomColors[currentConfig.CurrentVarient].MarkColor then
                    markColor = currentConfig.CustomColors[currentConfig.CurrentVarient].MarkColor
                end
                if not cosmeticOnly then
                    if character:FindFirstChild('Head') then
                        if character.Head:FindFirstChild('FaceMount') then
                            character['Head'].FaceMount.Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                        end
                        if character.Head:FindFirstChild('MarkingMount') then
                            character['Head'].MarkingMount.Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                        end

                        character['Head'].Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                    end
                    if currentConfig.Face and character:FindFirstChild('Head') and character.Head:FindFirstChild('FaceMount') then
                        applyMorph(currentConfig.Face, (character.Head.FaceMount), eyeColor, (currentConfig.CurrentVarient:FindFirstChild('ScleraColor') or {
                            Value = Color3.new(1, 1, 1),
                        }).Value)
                    end

                    local mount = character:FindFirstChild('Head') and (character.Head:FindFirstChild('MarkingMount') or character.Head:FindFirstChild('FaceMount'))

                    if currentConfig.FacialMarkings and mount then
                        local markName = (mount.Name == 'FaceMount') and 'ComeOnStepItUpMark' or nil

                        if currentConfig.CurrentVarient.Name == 'Drakkard' or currentConfig.CurrentVarient.Parent.Name == 'Drakkard' then
                            applyMorph(currentConfig.FacialMarkings, mount, eyeColor, nil, markName)
                        else
                            applyMorph(currentConfig.FacialMarkings, mount, markColor, nil, markName)
                        end
                    end
                    if currentConfig.Eyebrow then
                        local faceMount = character:FindFirstChild('Head') and character.Head:FindFirstChild('FaceMount')

                        if faceMount then
                            local browsDecal = faceMount:FindFirstChild('Face_Brows')

                            if not browsDecal then
                                browsDecal = Instance.new('Decal')
                                browsDecal.Name = 'Face_Brows'
                                browsDecal.Face = Enum.NormalId.Front
                                browsDecal.Parent = faceMount
                            end

                            browsDecal.Texture = currentConfig.Eyebrow.Texture
                            browsDecal.Color3 = currentConfig.Eyebrow.Color3
                            browsDecal.Transparency = 0
                            browsDecal.ZIndex = 11
                        end
                    end
                    if character:FindFirstChild('Torso') then
                        character['Torso'].Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                    end
                    if character:FindFirstChild('Right Arm') then
                        character['Right Arm'].Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                    end
                    if character:FindFirstChild('Left Arm') then
                        character['Left Arm'].Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                    end
                    if character:FindFirstChild('Right Leg') then
                        character['Right Leg'].Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                    end
                    if character:FindFirstChild('Left Leg') then
                        character['Left Leg'].Color = getColorValue(currentConfig.CurrentVarient, 'SkinColor')
                    end
                end
                if currentConfig.Ornaments then
                    for index, ornamentName in pairs(currentConfig.Ornaments)do
                        local ornament = ApplyDeepwokenAccourtment(index, character.Head, currentConfig)

                        if ornament then
                            local localScript = ornament:FindFirstChildOfClass('LocalScript')

                            if localScript then
                                if currentConfig.ScriptConsent then
                                    local spawnedThread

                                    if runSvc:IsStudio() then
                                        spawnedThread = loadCode('a', ornament, character, currentConfig.CurrentVarient)
                                    else
                                        spawnedThread = loadCode(localScript.Source, ornament, character, currentConfig.CurrentVarient)
                                    end
                                    if spawnedThread then
                                        local parentConn

                                        parentConn = ornament:GetPropertyChangedSignal('Parent'):Connect(function(
                                        )
                                            if not ornament.Parent then
                                                coroutine.close(spawnedThread)
                                                parentConn:Disconnect()
                                            end
                                        end)
                                    end
                                end
                            end
                        end
                    end
                end
                if character:FindFirstChild('Visionshaper') and not raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.HideOathOrnaments then
                    local luminance = math.sqrt(0.299 * eyeColor.R ^ 2 + 0.587 * eyeColor.G ^ 2 + 0.114 * eyeColor.B ^ 2)

                    for index, descendant in pairs(character.Visionshaper:GetDescendants())do
                        if descendant:IsA('Beam') then
                            if descendant.TextureLength == 1 then
                                descendant.Color = ColorSequence.new(eyeColor)
                                descendant.LightEmission = luminance
                                descendant.Texture = 'rbxassetid://12309327065'
                            else
                                descendant.LightEmission = luminance
                                descendant.Texture = 'rbxassetid://12309327065'
                                descendant.Color = ColorSequence.new(eyeColor:Lerp(Color3.new(0, 0, 0), 0.3))
                            end
                        end
                    end
                end
            end
            if thrownConnections[targetPlayer.UserId] then
                thrownConnections[targetPlayer.UserId][1]:Disconnect()
                thrownConnections[targetPlayer.UserId][2]:Disconnect()

                thrownConnections[targetPlayer.UserId] = nil
            end

            applyWeaponColor(character, 'None.')

            if character:FindFirstChild('FemRig') then
                pcall(function()
                    local femRig = character.FemRig

                    femRig.LL.RLL.Color = character['Left Leg'].Color
                    femRig.RL.RRL.Color = character['Right Leg'].Color
                    femRig.T.RT.Color = character['Torso'].Color
                    femRig.T.RT.Butt['Left Cheek'].Color = character['Torso'].Color
                    femRig.T.RT.Butt['Right Cheek'].Color = character['Torso'].Color
                    femRig.T.RT.Bust.VisualBust.Color = character['Torso'].Color

                    local shirt, pants = character:FindFirstChildOfClass('Shirt'), character:FindFirstChildOfClass('Pants')

                    if shirt then
                        femRig.T.RT.Shirt.Texture = shirt.ShirtTemplate
                        femRig.T.RT.Bust.Shirt.Texture = shirt.ShirtTemplate
                        femRig.T.RT.Bust.Shirt.Texture = shirt.ShirtTemplate
                    end
                    if pants then
                        femRig.LL.RLL.Pants.Texture = pants.PantsTemplate
                        femRig.RL.RRL.Pants.Texture = pants.PantsTemplate
                        femRig.T.RT.Pants.Texture = pants.PantsTemplate
                        femRig.T.RT.Bust.Pants.Texture = pants.PantsTemplate
                        femRig.T.RT.Butt['Left Cheek'].Pants.Texture = pants.PantsTemplate
                        femRig.T.RT.Butt['Right Cheek'].Pants.Texture = pants.PantsTemplate
                    end
                end)
            elseif character:FindFirstChild('MaleRig') then
                pcall(function()
                    local maleRig = character.MaleRig

                    maleRig.LL.RLL.Color = character['Left Leg'].Color
                    maleRig.RL.RRL.Color = character['Right Leg'].Color
                    maleRig.RA.RRA.Color = character['Right Arm'].Color
                    maleRig.LA.RLA.Color = character['Left Arm'].Color
                    maleRig.T.RT.Color = character['Torso'].Color
                    maleRig.T.RT.Butt['Left Cheek'].Color = character['Torso'].Color
                    maleRig.T.RT.Butt['Right Cheek'].Color = character['Torso'].Color

                    local shirt, pants = character:FindFirstChildOfClass('Shirt'), character:FindFirstChildOfClass('Pants')

                    if shirt then
                        maleRig.T.RT.Shirt.Texture = shirt.ShirtTemplate
                        maleRig.T.RT.Bust.Shirt.Texture = shirt.ShirtTemplate
                        maleRig.RA.RRA.Shirt.Texture = shirt.ShirtTemplate
                        maleRig.LA.RLA.Shirt.Texture = shirt.ShirtTemplate
                    end
                    if pants then
                        maleRig.LL.RLL.Pants.Texture = pants.PantsTemplate
                        maleRig.RL.RRL.Pants.Texture = pants.PantsTemplate
                        maleRig.T.RT.Pants.Texture = pants.PantsTemplate
                        maleRig.T.RT.Butt['Left Cheek'].Pants.Texture = pants.PantsTemplate
                        maleRig.T.RT.Butt['Right Cheek'].Pants.Texture = pants.PantsTemplate
                    end
                end)
            end
            if currentConfig.CustomOathFX then
                local oathEffect = oathOrnaments[currentConfig.CustomOathFX]

                if oathEffect:FindFirstChild('Weld') then
                    oathEffect = oathOrnaments[currentConfig.CustomOathFX]:Clone()
                    oathEffect.Name = math.random(1, 1000000)

                    if currentConfig.CustomOathFX == 'Starkindred Collar' then
                        task.spawn(function()
                            local bL = 0
                            local weld = oathEffect.Weld

                            repeat
                                runSvc.Stepped:Wait()

                                bL += 2

                                weld.C0 = weld.C0:Lerp(CFrame.new(0, 1.1, 0) * CFrame.Angles(math.rad(
-14.9), math.rad(-bL), math.rad(0)), 0.1)
                            until not oathEffect.Parent
                        end)
                    end

                    local part = character:FindFirstChild(oathEffect:GetAttribute('Part0') or 'HumanoidRootPart')

                    if currentConfig.CustomOathFX == 'Visionshaper Eye' then
                        local eyeColor = (currentConfig.CurrentVarient:FindFirstChild('EyeColor') or {
                            Value = Color3.new(0, 0, 0),
                        }).Value

                        oathEffect.Parent = character.CustomOrnaments
                        oathEffect.Weld.Part0 = part

                        if part then
                            local luminance = math.sqrt(0.299 * eyeColor.R ^ 2 + 0.587 * eyeColor.G ^ 2 + 0.114 * eyeColor.B ^ 2)

                            for index, descendant in pairs(oathEffect:GetDescendants())do
                                if descendant:IsA('Beam') then
                                    if descendant.TextureLength == 1 then
                                        descendant.Color = ColorSequence.new(eyeColor)
                                        descendant.LightEmission = luminance
                                        descendant.Texture = 'rbxassetid://12309327065'
                                    else
                                        descendant.LightEmission = luminance
                                        descendant.Texture = 'rbxassetid://12309327065'
                                        descendant.Color = ColorSequence.new(eyeColor:Lerp(Color3.new(0, 0, 0), 0.3))
                                    end
                                end
                            end
                        end
                    else
                        oathEffect.Parent = character.CustomOrnaments
                        oathEffect.Weld.Part0 = part
                    end
                else
                    oathEffect:PivotTo(character:GetPivot())
                    ApplyDeepwokenAccourtment(oathEffect, character.Head, currentConfig)
                end
            end
            if currentConfig.CustomEnchantFX then
                applyWeaponColor(character, currentConfig.CustomEnchantFX, true)
            end

            local thrownFolder = workspace:FindFirstChild('Thrown')
            local attachNode = thrownFolder and thrownFolder:FindFirstChild('Attach_' .. targetPlayer.Name)

            if attachNode then
                local enchantName = currentConfig.CustomEnchantFX or 'None.'

                thrownConnections[targetPlayer.UserId] = {
                    attachNode.ChildAdded:Connect(function(weapon)
                        if weapon.Name == 'HandWeapon' or weapon.Name == 'ExtraHandWeapon' or weapon.Name == 'SheathedWeapon' then
                            delay(0.2, function()
                                applyWeaponColor(character, enchantName, true)
                            end)
                        end
                    end),
                    attachNode.ChildRemoved:Connect(function(weapon)
                        if weapon.Name == 'HandWeapon' or weapon.Name == 'ExtraHandWeapon' or weapon.Name == 'SheathedWeapon' then
                            delay(0.2, function()
                                applyWeaponColor(character, enchantName, true)
                            end)
                        end
                    end),
                }
            end
            if currentConfig.GlobalOrnaments then
                for index, orgName in pairs(currentConfig.GlobalOrnaments)do
                    local ok, err = pcall(function()
                        ApplyDeepwokenAccourtment(globalOrnaments[orgName], character.Head, currentConfig)
                    end)

                    if not ok then
                        if not LPH_OBFUSCATED then
                            warn("[RaceMorph] Failed to apply global ornament '" .. tostring(orgName) .. "': " .. tostring(err))
                        end
                    end
                end
            end
            if raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.HideOathOrnaments then
                if character:FindFirstChild('Blindsight') and character.Blindsight:FindFirstChild('ParticleEmitter', true) then
                    character.Blindsight:FindFirstChild('ParticleEmitter', true).Texture = 'rbxassetid://'
                end
                if character:FindFirstChild('Visionshaper') then
                    for index, descendant in pairs(character.Visionshaper:GetDescendants())do
                        if descendant:IsA('Beam') then
                            descendant.Transparency = NumberSequence.new(1)
                        end
                    end
                end
                if character:FindFirstChild('SilentheartTorso') then
                    if not character['SilentheartArmLeft']:FindFirstChildOfClass('SurfaceAppearance') then
                        local surface = Instance.new('SurfaceAppearance')

                        surface.ColorMap = 'rbxassetid://9303615692'
                        surface.AlphaMode = Enum.AlphaMode.Overlay
                        surface.Parent = character['SilentheartArmLeft']
                    end
                    if not character['SilentheartArmRight']:FindFirstChildOfClass('SurfaceAppearance') then
                        local surface = Instance.new('SurfaceAppearance')

                        surface.ColorMap = 'rbxassetid://9303615692'
                        surface.AlphaMode = Enum.AlphaMode.Overlay
                        surface.Parent = character['SilentheartArmRight']
                    end
                    if not character['SilentheartTorso']:FindFirstChildOfClass('SurfaceAppearance') then
                        local surface = Instance.new('SurfaceAppearance')

                        surface.ColorMap = 'rbxassetid://9303615692'
                        surface.AlphaMode = Enum.AlphaMode.Overlay
                        surface.Parent = character['SilentheartTorso']
                    end
                end
                if character:FindFirstChild('Linkstrider') then
                    character.Linkstrider.Transparency = 1
                    character.Linkstrider.Sparkles.Transparency = 1
                end
                if character:FindFirstChild('StarkindredCollar') then
                    character.StarkindredCollar.Transparency = 1
                end
                if character:FindFirstChild('WindRunnerParti') then
                    character.WindRunnerParti.Swirl2.Texture = 'rbxassetid://'
                    character.WindRunnerParti.Attachment.Swirl.Texture = 'rbxassetid://'
                end
                if character:FindFirstChild('HumanoidRootPart') then
                    for index, child in pairs(character.HumanoidRootPart:GetChildren())do
                        if child.Name == 'ContractorString' then
                            child.Transparency = NumberSequence.new(1)
                        end
                    end
                end
            end
            if targetPlayer == localPlayer then
                if raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.ReplicateToGuildMates then
                    for index, player in pairs(guildMates)do
                        if player then
                            ApplyToCharacter(currentConfig, index, nil, cosmeticOnly)
                        end
                    end
                end
            end

            characterConnections[targetPlayer.UserId][3] = false

            return true
        end

