        local updateHsvPicker = function(color)
            bF, sat, value = color:ToHSV()
            colorPicker.Hue.Button.BackgroundColor3 = Color3.fromHSV(bF, 1, 1)
            colorPicker.SaturationValue.ImageLabel.ImageColor3 = Color3.fromHSV(bF, 1, 1)
            colorPicker.SaturationValue.Button.BackgroundColor3 = Color3.fromHSV(bF, sat, value)
            colorPicker.Confirm.BackgroundColor3 = Color3.fromHSV(bF, sat, value)
            colorPicker.Cancel.BackgroundColor3 = Color3.fromHSV(bF, sat, value)
            colorPicker.Hue.Button.Position = UDim2.new(0.587, 0, 0, 160 * (1 - bF))
            colorPicker.SaturationValue.Button.Position = UDim2.fromOffset(145 * (1 - sat), 145 * (1 - value))
        end
        local hueFrame = colorPicker:WaitForChild('Hue')
