        local function flashcopy(bT)
            local valueType = type(bT)
            local copy

            if valueType == 'table' then
                copy = {}

                for key, val in next, bT, nil do
                    if typeof(key) == 'Instance' then
                        key = key.Name
                    end
                    if typeof(val) == 'Instance' then
                        val = val.Name
                    elseif typeof(val) == 'Color3' then
                        val = val:ToHex()
                    end

                    copy[flashcopy(key)] = flashcopy(val)
                end

                setmetatable(copy, flashcopy(getmetatable(bT)))
            else
                copy = bT
            end

            return copy
        end

        local saveMorphPreferences = function()
            local copy = flashcopy(raceConfig)
            local json = game.HttpService:JSONEncode(copy)

            if runSvc:IsStudio() then
                if assetFolder:FindFirstChild(localPlayer.UserId .. '_' .. dataSlot) then
                    assetFolder[localPlayer.UserId .. '_' .. dataSlot]:Destroy()
                end

                local stringValue = Instance.new('StringValue', assetFolder)

                stringValue.Name = localPlayer.UserId .. '_' .. dataSlot
                stringValue.Value = json
            else
                pcall(writefile, 'PalantirX/Morphs/Preferences/' .. localPlayer.UserId .. '_' .. dataSlot .. '.txt', json)
            end
        end
        local loadMorphPreferences = function()
            local json

            if runSvc:IsStudio() then
                if assetFolder:FindFirstChild(localPlayer.UserId .. '_' .. dataSlot) then
                    json = assetFolder[localPlayer.UserId .. '_' .. dataSlot].Value
                else
                    return nil
                end
            else
                if isfile('PalantirX/Morphs/Preferences/' .. localPlayer.UserId .. '_' .. dataSlot .. '.txt') then
                    json = readfile('PalantirX/Morphs/Preferences/' .. localPlayer.UserId .. '_' .. dataSlot .. '.txt')
                else
                    return nil
                end
            end
            if json then
                local decoded = game.HttpService:JSONDecode(json)

                raceConfig = decoded

                for key, val in pairs(raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF)do
                    if configDefaults[key] == nil and key ~= 'LastRace' then
                        raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF[key] = nil
                    end
                end

                return true
            end
        end

        runSvc.RenderStepped:Connect(function()
            local mousePos = userInput:GetMouseLocation()

            if userInput:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
                if bK == true then
                    local deltaY = (hueStart[1] - mousePos.Y)
                    local newPos = UDim2.new(0.587, 0, 0, hueStart[2] - deltaY)

                    if newPos.Y.Offset > 160 then
                        newPos = UDim2.new(0.587, 0, 0, 160)
                    elseif newPos.Y.Offset < 0 then
                        newPos = UDim2.new(0.587, 0, 0, 0)
                    end

                    bF = 1 - newPos.Y.Offset / 160
                    colorPicker.Hue.Button.BackgroundColor3 = Color3.fromHSV(bF, 1, 1)
                    colorPicker.SaturationValue.ImageLabel.ImageColor3 = Color3.fromHSV(bF, 1, 1)
                    colorPicker.SaturationValue.Button.BackgroundColor3 = Color3.fromHSV(bF, sat, value)
                    colorPicker.Confirm.BackgroundColor3 = Color3.fromHSV(bF, sat, value)
                    colorPicker.Hue.Button.Position = newPos
                elseif svDragging == true then
                    local delta = bM[1] - mousePos
                    local newPos = UDim2.fromOffset(bM[2].X.Offset - delta.X, bM[2].Y.Offset - delta.Y)

                    if newPos.X.Offset > 145 then
                        newPos = UDim2.new(0, 145, 0, newPos.Y.Offset)
                    elseif newPos.X.Offset < 0 then
                        newPos = UDim2.new(0, 0, 0, newPos.Y.Offset)
                    end
                    if newPos.Y.Offset > 145 then
                        newPos = UDim2.new(0, newPos.X.Offset, 0, 145)
                    elseif newPos.Y.Offset < 0 then
                        newPos = UDim2.new(0, newPos.X.Offset, 0, 0)
                    end

                    value = 1 - (newPos.Y.Offset / 145)
                    sat = 1 - (newPos.X.Offset / 145)
                    colorPicker.SaturationValue.Button.BackgroundColor3 = Color3.fromHSV(bF, sat, value)
                    colorPicker.SaturationValue.Button.Position = newPos
                    colorPicker.Confirm.BackgroundColor3 = Color3.fromHSV(bF, sat, value)
                end
            end
        end)
        userInput.InputBegan:Connect(function(input, gameProcessed)
            if gameProcessed then
                if input.UserInputType == Enum.UserInputType.MouseButton1 then
                    if bI == true and svDragging == false then
                        bK = true
                        hueStart = {
                            userInput:GetMouseLocation().Y,
                            colorPicker.Hue.Button.Position.Y.Offset,
                        }
                    elseif draggingSv == true and bK == false then
                        svDragging = true
                        bM = {
