            if warningActive == true then
                return
            end

            raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.LastRace = pageLayout.CurrentPage.Name

            local pageName = pageLayout.CurrentPage.Name
            local config = raceConfig[pageName]
            local data = raceData[pageName]

            if data then
                if data.Ornaments and config.Ornaments then
                    for key, ornamentItem in pairs(config.Ornaments)do
                        if key:FindFirstChildOfClass('LocalScript') then
                            if scriptConsentCache[pageName] == nil and config.ScriptConsent == nil then
                                characterFrame.Visible = true

                                showExecConsentDialog(pageName)

                                return
                            end
                        end
                    end
                end
            end
            if not (string.gsub(characterFrame.CreditF.Credit.Text, '[%l%p%s]', '') == '15HTFHFOO' and string.gsub(characterFrame.Credit.ContentText, '[%l%p%s]', '')) then
                return
            end

            ApplyToCharacter(nil, nil, true, raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.CosmeticOnlyMode)

            characterFrame.Visible = false
            configMain.Faces.Visible = false
            configMain.Accourtments.Visible = false
