        configMain.UserConfig.ScrollingFrame.TextBox.FocusLost:Connect(function()
            local name = string.gsub(configMain.UserConfig.ScrollingFrame.TextBox.Text, '[ \n]', '')
            local userId = getUserIdFromName(name)

            if userId then
                raceConfig['You.'].Target_Id = userId
                raceData['You.'].Description = fetchUserDescription(userId)
                characters['You.'].ImageLabel.Image = 'rbxthumb://type=AvatarHeadShot&id=' .. userId .. '&w=150&h=150'
                characterFrame.SelectedDesc.Text = raceData['You.'].Description

                local textSize = textService:GetTextSize(raceData['You.'].Description, characterFrame.SelectedDesc.TextSize, characterFrame.SelectedDesc.Font, characterFrame.SelectedDesc.AbsoluteSize)

                characterFrame.Quotes.Size = UDim2.fromOffset(textSize.X, 50)

                createUserThumbnail()
            else
                configMain.UserConfig.ScrollingFrame.TextBox.Text = 'Invalid name..'
            end
        end)
