                    else
                        characterFrame.Visible = false
                        configMain.Faces.Visible = false
                        configMain.Accourtments.Visible = false
                        configMain.Varients.Visible = false
                        configMain.Eyebrows.Visible = false
                        configMain.Markings.Visible = false
                        characterFrame.ColorPicker.Visible = false
                        configMain.Settings.Visible = false
                        characterFrame.CreditF.Visible = false
                        configMain.GlobalAccourtments.Visible = false
                        configMain.UserConfig.Visible = false
                        gradient.UIGradient.Offset = Vector2.new(1, 0)
                        configuration.Size = UDim2.new(0, 0, 1, -30)
                        pageLayout.ScrollWheelInputEnabled = true
                    end
                end
            end
        end)

        characterFrame.Visible = false
        morphGui.Parent = guiParent
        getgenv().race_morph_menu_loaded = true
        getgenv().race_morph_menu_frame = characterFrame

        if loaded then
            if raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.LastRace then
                local lastRace = raceConfig.CON_FIG_DEEZ_NUTS_IN_YO_MOUF.LastRace
                local config = raceConfig[lastRace]
