            end
        end
    end
    function module.close()
        if getgenv().race_morph_menu_frame then
            getgenv().race_morph_menu_frame.Visible = false
        end
    end
    function module.detach()
        module.close()
    end

    return module
end


return aa()

]=],
    ["Features/Exploits/RunItBackSpoofer"] = [=[
local aa = function()
    local module = {}
    local effectTracker = a["Game/EffectTracker"]()
    local keyHandling = a["Game/KeyHandling"]()
    local configuration = a["Utility/Configuration"]()
    local players = game:GetService('Players')
    local fireServer = Instance.new('UnreliableRemoteEvent').FireServer
    local ag = 0
    local ah = false
    local ai = 0
    local fireFallDamageRemote = function()
        if not configuration.expectToggleValue('RunItBackAlloySpoofer') then
            return
        end
        if not (effectTracker.has('RunitBack') and effectTracker.has('FrenziedSlashDamage')) then
            return
        end
        if os.clock() - ag < 1 then
            return
        end

        local remote = keyHandling.getRemote('FallDamage')

        if not remote then
            return
        end

        ag = os.clock()

        remote:FireServer(configuration.expectOptionValue('RunItBackFallDamage') or 0, false)
    end
    local getLocalHumanoid = function()
        local player = players.LocalPlayer
        local character = player and player.Character

        return character and character:FindFirstChildOfClass('Humanoid')
    end
    local isGrounded = function()
        local humanoid = getLocalHumanoid()

        return humanoid ~= nil and humanoid.FloorMaterial ~= Enum.Material.Air
    end
    local fireLeftClick = function()
        local remote = keyHandling.getRemote('LeftClick')

        if not remote then
            return
        end

        local player = players.LocalPlayer
        local mouse = player and player:GetMouse()

        pcall(fireServer, remote, false, mouse and mouse.Hit, {
            S = true,
            NOAERIALS = true,
            Space = false,
            Right = false,
            W = true,
            Left = true,
            ctrl = true,
        })
    end
    local fireServerSlide = function()
        local remote = keyHandling.getRemote('ServerSlide')

        if remote then
            pcall(function()
                remote:FireServer(true)
            end)
        end
    end
    local fireSlideStop = function()
        local remote = keyHandling.getRemote('ServerSlideStop')

        if remote then
            pcall(function()
                remote:FireServer()
            end)
        end
    end
    local waitUntilGrounded = function()
        if ah then
            return
        end

        ah = true

        task.spawn(function()
            local startClock = os.clock()

            repeat
                task.wait()
            until isGrounded() or os.clock() - startClock > 0.8

            fireServerSlide()

            local startClock = os.clock()

            repeat
                task.wait()
            until effectTracker.has('Sliding') or os.clock() - startClock > 0.25

            fireLeftClick()
            task.wait(0.05)
            fireSlideStop()

            ah = false
        end)
    end
    local fireSilentheartMoveStacks = function()
        if not configuration.expectToggleValue('SilentheartMoveStacks') then
            return
        end
        if not (effectTracker.has('AerialCD') and effectTracker.has('LightAttack')) then
            return
        end
        if os.clock() - ai < 1 then
            return
        end

        ai = os.clock()

        waitUntilGrounded()
    end
    local onEffectAdded = function(effectName)
        if effectName == 'RunitBack' or effectName == 'FrenziedSlashDamage' then
            fireFallDamageRemote()
        end
        if effectName == 'AerialCD' or effectName == 'LightAttack' then
            fireSilentheartMoveStacks()
        end
    end

    function module.init()
        if module.inited then
            return
        end

        module.inited = true

        effectTracker.onAdded(onEffectAdded)
    end
    function module.detach() end

    return module
end


return aa()

]=],
    ["Features/Exploits/Speedhack"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local feature = a["Features/Feature"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local speedhack = feature.new('Speedhack', runService.PreSimulation, function()
        if configuration.expectToggleValue('Flight') then
            return
        end

        local character = players.LocalPlayer and players.LocalPlayer.Character

        if not character then
            return
        end

        local root = character:FindFirstChild('HumanoidRootPart')

        if not root then
            return
        end

        local humanoid = character:FindFirstChild('Humanoid')

        if not humanoid then
            return
        end

        root.AssemblyLinearVelocity = root.AssemblyLinearVelocity * Vector3.new(0, 1, 0)

        local movement = humanoid.MoveDirection

        if movement.Magnitude <= 0.001 then
            return
        end

        root.AssemblyLinearVelocity = root.AssemblyLinearVelocity + movement.Unit * configuration.expectOptionValue('SpeedhackSpeed')
    end)

    return speedhack
end


return aa()

]=],
    ["Features/Feature"] = [=[
local aa = function()
    local featureModule = {}

    featureModule.__index = featureModule
    featureModule._registry = {}
    shared.Palantir_Features = featureModule._registry

    function featureModule.new(id, connection, updateFn)
        assert(type(id) == 'string' and #id > 0, 'Feature.new: id must be a non-empty string')
        assert(not featureModule._registry[id], "Feature.new: duplicate id '" .. id .. "'")

        local feature = setmetatable({}, featureModule)

        feature.id = id
        feature.connection = connection
        feature.updateFn = updateFn or function() end
        feature.enabled = false
        feature._activeConn = nil
        featureModule._registry[id] = feature

        return feature
    end
    function featureModule:onEnable() end
    function featureModule:onDisable() end
    function featureModule:enable()
        if self.enabled then
            return
        end

        self.enabled = true

        if self.connection then
            self._activeConn = self.connection:Connect(function(...)
                local ok, err = pcall(self.updateFn, self, ...)

                if not ok then
                    if not LPH_OBFUSCATED then
                        warn(string.format('[Feature %s] update error: %s', self.id, tostring(err)))
                    end
                end
            end)
        end

        local okEnable, errEnable = pcall(self.onEnable, self)

        if not okEnable then
            if not LPH_OBFUSCATED then
                warn(string.format('[Feature %s] onEnable error: %s', self.id, tostring(errEnable)))
            end
        end
    end
    function featureModule:disable(force)
        if not self.enabled and not force then
            return
        end

        self.enabled = false

        local okDisable, errDisable = pcall(self.onDisable, self)

        if not okDisable then
            if not LPH_OBFUSCATED then
                warn(string.format('[Feature %s] onDisable error: %s', self.id, tostring(errDisable)))
            end
        end
        if self._activeConn then
            self._activeConn:Disconnect()

            self._activeConn = nil
        end
    end
    function featureModule:setEnabled(enabled)
        if enabled then
            self:enable()
        else
            self:disable()
        end
    end

    featureModule.init = function() end
    featureModule.detach = function() end

    function featureModule.get(featureId)
        return featureModule._registry[featureId]
    end
    function featureModule.all()
        local features = {}

        for registryId, registryFeature in pairs(featureModule._registry)do
            features[registryId] = registryFeature
        end

        return features
    end
    function featureModule.disableAll()
        local disabledIds = {}

        for regId, regFeature in pairs(featureModule._registry)do
            local wasEnabled = regFeature.enabled
            local okDisableAll, errDisableAll = pcall(regFeature.disable, regFeature, true)

            if not okDisableAll then
                if not LPH_OBFUSCATED then
                    warn(string.format('[Feature %s] disable-all error: %s', regId, tostring(errDisableAll)))
                end
            elseif wasEnabled then
                disabledIds[#disabledIds + 1] = regId
            end
        end

        if #disabledIds > 0 then
            if not LPH_OBFUSCATED then
                warn(string.format('[PalantirX] Disabled on unload: %s', table.concat(disabledIds, ', ')))
            end
        end

        return disabledIds
    end
    function featureModule.bindToggle(featureName, toggleName)
        local boundFeature = featureModule._registry[featureName]
        local toggle = Toggles and Toggles[toggleName]

        if not boundFeature or not toggle then
            return false
        end
        if boundFeature._boundToggle == toggle then
            return true
        end

        boundFeature._boundToggle = toggle

        boundFeature:setEnabled(toggle.Value == true)

        if type(toggle.OnChanged) == 'function' then
            toggle:OnChanged(function()
                boundFeature:setEnabled(toggle.Value == true)
            end)
        end

        return true
    end
    function featureModule.bindToggles(bindings)
        for bindId, bindToggleName in pairs(bindings)do
            featureModule.bindToggle(bindId, bindToggleName)
        end
    end

    return featureModule
end


return aa()

