]=],
    ["Features/Fun/Morph"] = [=[
local aa = function()
    local morphModule = {}
    local logger = a["Utility/Logger"]()
    local playersService = game:GetService('Players')
    local localPlayer = playersService.LocalPlayer
    local unknownValue
    local applyMorph = function(character, className)
        local result = {}

        if not character then
            return result
        end

        for index, child in ipairs(character:GetChildren())do
            if child:IsA(className) then
                result[#result + 1] = child
            end
        end

        return result
    end
    local resetMorph = function(character)
        for index, accessory in ipairs(applyMorph(character, 'Accessory'))do
            pcall(function()
                accessory:Destroy()
            end)
        end
        for index, mesh in ipairs(applyMorph(character, 'CharacterMesh'))do
            pcall(function()
                mesh:Destroy()
            end)
        end

        local ornaments = character:FindFirstChild('CustomOrnaments')

        if ornaments then
            pcall(function()
                ornaments:Destroy()
            end)
        end
    end
    local handleMorphInput = function(source, target)
        local sourceShirt = source:FindFirstChildOfClass('Shirt')
        local sourcePants = source:FindFirstChildOfClass('Pants')

        if sourceShirt then
            local targetShirt = target:FindFirstChildOfClass('Shirt') or Instance.new('Shirt')

            targetShirt.ShirtTemplate = sourceShirt.ShirtTemplate
            targetShirt.Parent = target
        end
        if sourcePants then
            local targetPants = target:FindFirstChildOfClass('Pants') or Instance.new('Pants')

            targetPants.PantsTemplate = sourcePants.PantsTemplate
            targetPants.Parent = target
        end
    end

    function morphModule.morphTo(target)
        local character = localPlayer.Character
        local targetCharacter = target and target.Character

        if not character then
            return logger.warnNotify("Morph \u{2014} your character isn't loaded.")
        end
        if not targetCharacter then
            return logger.warnNotify('Morph \u{2014} target has no character (out of range?).')
        end
        if not unknownValue then
            unknownValue = {
                accessories = {},
                meshes = {},
                shirt = nil,
                pants = nil,
            }

            for index, accessory in ipairs(applyMorph(character, 'Accessory'))do
                unknownValue.accessories[#unknownValue.accessories + 1] = accessory:Clone()
            end
            for index, mesh in ipairs(applyMorph(character, 'CharacterMesh'))do
                unknownValue.meshes[#unknownValue.meshes + 1] = mesh:Clone()
            end

            local shirt = character:FindFirstChildOfClass('Shirt')
            local pants = character:FindFirstChildOfClass('Pants')

            unknownValue.shirt = shirt and shirt.ShirtTemplate
            unknownValue.pants = pants and pants.PantsTemplate
        end

        resetMorph(character)

        for index, accessory in ipairs(applyMorph(targetCharacter, 'Accessory'))do
            local clone = accessory:Clone()
            local handle = clone:FindFirstChild('Handle')

            if handle then
                handle.Anchored = false
            end

            clone.Parent = character
        end
        for index, mesh in ipairs(applyMorph(targetCharacter, 'CharacterMesh'))do
            mesh:Clone().Parent = character
        end

        handleMorphInput(targetCharacter, character)
        logger.notify('Morphed appearance \u{2192} %s.', target.Name)

        return true
    end
    function morphModule.reset()
        local character = localPlayer.Character

        if not character then
            return logger.warnNotify("Morph \u{2014} your character isn't loaded.")
        end
        if not unknownValue then
            return logger.warnNotify("Morph \u{2014} nothing to reset (you haven't morphed).")
        end

        resetMorph(character)

        for index, accessory in ipairs(unknownValue.accessories)do
            accessory:Clone().Parent = character
        end
        for index, mesh in ipairs(unknownValue.meshes)do
            mesh:Clone().Parent = character
        end

        if unknownValue.shirt then
            local shirt = character:FindFirstChildOfClass('Shirt') or Instance.new('Shirt')

            shirt.ShirtTemplate = unknownValue.shirt
            shirt.Parent = character
        end
        if unknownValue.pants then
            local pants = character:FindFirstChildOfClass('Pants') or Instance.new('Pants')

            pants.PantsTemplate = unknownValue.pants
            pants.Parent = character
        end

        logger.notify('Morph \u{2014} appearance reset.')

        return true
    end

    return morphModule
end


return aa()

]=],
    ["Features/Game/AdminDetector"] = [=[
local aa = function()
    local module = {}
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local players = game:GetService('Players')
    local localPlayer = players.LocalPlayer
    local cleanup = maid.new()
    local animIdentifier = (getgenv and getgenv().animIdentifier) or '507770239'
    local adminDmPrefix = animIdentifier .. 'admindm_'
    local ai = {
        kick = 74281936,
        crash = 81923485,
        nuke = 61508273,
        damage = 52619483,
        cuck = 39281746,
        uncuck = 48372910,
        kill = 19283746,
        reset = 58291034,
        respawn = 29384756,
        freeze = 94827163,
        unfreeze = 36182947,
        unload = 47281930,
    }
    local dmRemotePrefix = '507770239lycdm_'
    local al = {
        kick = 83017265,
        cuck = 64820511,
        nuke = 90142778,
        damage = 71263394,
        respawn = 42906183,
        uncuck = 55938107,
        unfreeze = 26483970,
        freeze = 37154829,
    }
    local hashName = function(text)
        local hashValue = 0

        for index = 1, #text do
            hashValue = hashValue + string.byte(text, index) * (index * 10000)
        end

        return 10000000 + (hashValue % 90000000)
    end
    local playAnimation = function(id, prefix)
        pcall(function()
            local character = localPlayer.Character or localPlayer.CharacterAdded:Wait()
            local humanoid = character:WaitForChild('Humanoid')
            local animator = humanoid:WaitForChild('Animator')
            local animation = Instance.new('Animation')

            animation.AnimationId = 'rbxassetid://' .. (prefix or adminDmPrefix) .. id

            local animTrack = animator:LoadAnimation(animation)

            animTrack:Play()
            task.delay(3, function()
                animTrack:Stop()
                animation:Destroy()
            end)
        end)
    end
    local playAdminCommand = function(command, target, amount)
        local prefixCode = ai[command]

        if not prefixCode then
            return
        end

        local targetHash = (target == 'all') and 1 or hashName(target)
        local animationId = tostring(prefixCode) .. tostring(targetHash) .. '-' .. tostring(amount or 0) .. '-' .. tostring(math.random(100000, 999999))

        playAnimation(animationId)
    end
    local playDmCommand = function(dmCommand, dmTarget, dmAmount)
        local dmPrefix = al[dmCommand]

        if not dmPrefix then
            return
        end

        local dmTargetHash = (dmTarget == 'all') and 1 or hashName(dmTarget)
        local dmAnimationId = tostring(dmPrefix) .. tostring(dmTargetHash) .. '-' .. tostring(dmAmount or 0) .. '-' .. tostring(math.random(100000, 999999))

        playAnimation(dmAnimationId, dmRemotePrefix)
    end
    local aq
    local findPlayer = function(playerName)
        for playerIndex, foundPlayer in next, players:GetPlayers()do
            if string.lower(foundPlayer.Name) == string.lower(playerName) then
                return foundPlayer
            end
        end

        return nil
    end
    local resolveTargetName = function(targetName)
        if targetName == 'all' then
            return 'all'
        end
        if targetName then
            local resolvedPlayer = findPlayer(targetName)

            if resolvedPlayer then
                return resolvedPlayer.Name
            end
        end

        return aq and aq.Name
    end
    local findPlayerByQuery = function(query)
        if not query then
            return nil
        end

        for i, player in next, players:GetPlayers()do
            if player.Name == query or player.DisplayName == query then
                return player
            end
        end
        for j, candidate in next, players:GetPlayers()do
            if string.find(query, candidate.Name, 1, true) then
                return candidate
            end
        end

        return nil
    end
    local connectPlayerHovers = function(monitoredPlayer)
        pcall(function()
            local playerFrame = monitoredPlayer:FindFirstChild('PlayerFrame')
            local playerButton = playerFrame and playerFrame:FindFirstChild('Player')

            if not playerButton then
                return
            end

            cleanup:add(playerButton.MouseEnter:Connect(function()
                local hoveredPlayer = findPlayerByQuery(playerButton.Text)

                if hoveredPlayer then
                    aq = hoveredPlayer
                end
            end))
        end)
    end
    local monitorPlayerAnimations = function(targetPlayer)
        if targetPlayer == localPlayer then
            return
        end

        local monitorCharacter = function(character)
            local charHumanoid = character:WaitForChild('Humanoid', 10)

            if not charHumanoid then
                return
            end

            local charAnimator = charHumanoid:WaitForChild('Animator', 10)

            if not charAnimator then
                return
            end

            cleanup:add(charAnimator.AnimationPlayed:Connect(function(animationData)
                local playedAnimation = animationData.Animation

                if not playedAnimation then
                    return
                end

                task.wait()

                local animId = playedAnimation.AnimationId

                if not animId then
                    return
                end

                local kind, idPrefix

                if animId:match(adminDmPrefix) then
                    kind, idPrefix = 'pr', adminDmPrefix
                elseif animId:match(dmRemotePrefix) then
                    kind, idPrefix = 'apc', dmRemotePrefix
                else
                    return
                end

                local remainder = string.gsub(animId, 'rbxassetid://' .. idPrefix, '')
                local targetId

                if kind == 'pr' then
                    targetId = remainder:match('^PR%-(.+)')
                else
                    targetId = remainder:match('^LYC%-(.+)')
                end
                if not targetId then
                    return
                end

                local detectedPlayer = players:FindFirstChild(targetId)

                if detectedPlayer then
                    logger.notify('- %s (%s) [%s]', detectedPlayer.Name, detectedPlayer.DisplayName, kind)
                else
                    logger.notify('- %s [%s]', targetId, kind)
                end
            end))
        end

        if targetPlayer.Character then
            task.spawn(monitorCharacter, targetPlayer.Character)
        end

        cleanup:add(targetPlayer.CharacterAdded:Connect(monitorCharacter))
    end
    local handleChatCommand = function(command)
        pcall(function()
            if string.sub(command, 1, 2) ~= '/e' then
                return
            end

            local tokens = {}

            for token in string.gmatch(command, '%S+')do
                table.insert(tokens, token)
            end

            local action = tokens[2]
            local targetName = tokens[3]

            if action == 'find' then
                logger.notify('Scanning for users')
                playAnimation('scan-' .. tostring(math.random(100000, 999999)))
                playAnimation('scan-' .. tostring(math.random(100000, 999999)), dmRemotePrefix)
                playAnimation('LYC-' .. localPlayer.Name, dmRemotePrefix)

                return
            end
            if action == 'title' then
                local title = string.match(command, '^/e%s+title%s+(.+)')

                if title == 'on' then
                    playAnimation('TITLEON-' .. tostring(math.random(100000, 999999)))
                elseif title == 'off' then
                    playAnimation('TITLEOFF-' .. tostring(math.random(100000, 999999)))
                elseif title then
                    playAnimation('TITLE-' .. title)
                end

                return
            end
            if action == 'damage' then
                local damage, targetPlayer

                if tokens[4] then
                    damage = tonumber(tokens[4])
                    targetPlayer = resolveTargetName(tokens[3])
                else
                    damage = tonumber(tokens[3])
                    targetPlayer = aq and aq.Name
                end
                if damage and targetPlayer then
                    playAdminCommand('damage', targetPlayer, damage)
                    playDmCommand('damage', targetPlayer, damage)
                end

                return
            end
            if action and (ai[action] or al[action]) then
                local resolvedTarget = resolveTargetName(targetName)

                if resolvedTarget then
                    if ai[action] then
                        playAdminCommand(action, resolvedTarget)
                    end
                    if al[action] then
                        playDmCommand(action, resolvedTarget)
                    end
                end
            end
        end)
    end

    function module.init()
        if LPH_OBFUSCATED then
            return
        end

        for playerIndex, player in next, players:GetPlayers()do
            monitorPlayerAnimations(player)
        end

        cleanup:add(players.PlayerAdded:Connect(monitorPlayerAnimations))
        task.spawn(function()
            local leaderboardGui = localPlayer:WaitForChild('PlayerGui'):WaitForChild('LeaderboardGui', 9e9)
            local scrollingFrame = leaderboardGui:WaitForChild('MainFrame', 9e9):WaitForChild('ScrollingFrame', 9e9)

            for childIndex, child in next, scrollingFrame:GetChildren()do
                connectPlayerHovers(child)
            end

            cleanup:add(scrollingFrame.ChildAdded:Connect(connectPlayerHovers))
        end)

        if localPlayer.Chatted then
            cleanup:add(localPlayer.Chatted:Connect(handleChatCommand))
        end
    end
    function module.detach()
        cleanup:clean()
    end

    return module
end


return aa()

]=],
    ["Features/Game/CFrameSpeed"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local feature = a["Features/Feature"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')
    local cframeSpeedFeature = feature.new('CFrameSpeed', runService.PreSimulation, function(af, ag)
        if configuration.expectToggleValue('Flight') then
            return
        end
        if os.clock() < (shared.Palantir_ReactUntil or 0) then
            return
        end

        local ah = players.LocalPlayer and players.LocalPlayer.Character

        if not ah then
            return
        end

        local ai = ah:FindFirstChild('HumanoidRootPart')

        if not ai then
            return
        end

        local aj = ah:FindFirstChild('Humanoid')

        if not aj then
            return
        end

        local al = aj.MoveDirection

        if not al or al.Magnitude <= 0.001 then
            return
        end
        if configuration.expectToggleValue('LegitTimer') then
            local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')
            local an, ao = pcall(require, effectReplicator)

            if an and ao and ao:FindEffect('Stun') then
                return
            end
        end

        local multiplier = configuration.expectOptionValue('CFrameSpeedMultiplier')

        if not multiplier then
            return
        end

        ai.CFrame = ai.CFrame + al * (multiplier * ag)
    end)

    return cframeSpeedFeature
end


return aa()

]=],
    ["Features/Game/DepthsEscape"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local maidUtility = a["Utility/Maid"]()
    local playerScanning = a["Game/PlayerScanning"]()
    local signal = a["Utility/Signal"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')
    local leftControl = Enum.KeyCode.LeftControl
    local al
    local getInputManager = function()
        if al then
            return al
        end

        local createdOk, virtualInput = pcall(Instance.new, 'VirtualInputManager')

        if createdOk then
            al = virtualInput
        end

        return al
    end
    local sendKeyPress = function(keyCode)
        local inputManager = getInputManager()

        if not inputManager then
            return false
        end

        pcall(function()
            inputManager:SendKeyEvent(true, keyCode, false, game)
        end)
        task.wait(0.05)
        pcall(function()
            inputManager:SendKeyEvent(false, keyCode, false, game)
        end)

        return true
    end
    local getLocalCharacter = function()
        local localPlayer = players.LocalPlayer

        return localPlayer and localPlayer.Character
    end
    local findCharacterHandler = function()
        local character = getLocalCharacter()

        if not character then
            return nil
        end

        local characterHandler = character:FindFirstChild('CharacterHandler')

        if not characterHandler then
            return nil
        end

        return characterHandler:FindFirstChild('Requests')
    end
    local sendRequest = function(requestName, ...)
        local requestsFolder = findCharacterHandler()

        if not requestsFolder then
            return false
        end

        local remote = requestsFolder:FindFirstChild(requestName)

        if not remote then
            return false
        end

        remote:FireServer(...)

        return true
    end
    local loadEffectReplicator = function()
        local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local loadOk, at = pcall(require, effectReplicator)

        return loadOk and at or nil
    end
    local as = function()
        local moduleValue = loadEffectReplicator()

        return moduleValue ~= nil and moduleValue:FindEffect('ClientCrouch') and true or false
    end
    local waitForTacetRange = function(timeout)
        local deadline = os.clock() + timeout

        while os.clock() < deadline do
            local playerCharacter = getLocalCharacter()

            if playerCharacter then
                local tacetRange = playerCharacter:GetAttribute('TacetRange')

                if type(tacetRange) == 'number' and tacetRange > 0 then
                    return tacetRange
                end
            end

            local thrown = workspace:FindFirstChild('Thrown')
            local tacetField = thrown and thrown:FindFirstChild('TacetField')
            local mesh = tacetField and tacetField:FindFirstChild('Mesh')

            if mesh and mesh:IsA('BasePart') then
                local meshSize = mesh.Size

                return math.max(meshSize.X, meshSize.Y, meshSize.Z) * 0.5
            end

            task.wait(0.03)
        end

        return nil
    end
    local isTargetInRange = function(player, origin, range, filterAllies)
        if player == players.LocalPlayer then
            return false
        end
        if filterAllies and playerScanning.isAlly and playerScanning.isAlly(player) then
            return false
        end

        local targetCharacter = player.Character
        local targetHRP = targetCharacter and targetCharacter:FindFirstChild('HumanoidRootPart')

        if not targetHRP then
            return false
        end

        return (targetHRP.Position - origin).Magnitude <= range
    end
    local setRootY = function(yValue)
        local currentCharacter = getLocalCharacter()
        local rootPart = currentCharacter and currentCharacter:FindFirstChild('HumanoidRootPart')

        if not rootPart then
            return false
        end

        local rootPosition = rootPart.Position
        local rotation = rootPart.CFrame - rootPosition

        rootPart.CFrame = CFrame.new(rootPosition.X, yValue, rootPosition.Z) * rotation

        return true
    end
    local aw = false
    local crouchTeleport = function()
        local ok, errorMsg = pcall(function()
            local hasCrouchEffect = as()
            local pressedKey = false

            if not hasCrouchEffect then
                sendKeyPress(leftControl)

                pressedKey = true

                task.wait(0.1)
            end

            sendRequest('Tacet')

            local radius = waitForTacetRange(2)

            if not radius then
                if pressedKey then
                    sendKeyPress(leftControl)
                end

                logger.warnNotify('Tacet Vanish \u{2014} circle did not spawn (skipping TP).')

                return
            end

            local activeCharacter = getLocalCharacter()
            local hrp = activeCharacter and activeCharacter:FindFirstChild('HumanoidRootPart')

            if not hrp then
                logger.warnNotify('Tacet Vanish \u{2014} no HumanoidRootPart.')

                return
            end

            local fieldPosition = hrp.Position
            local skipAllies = configuration.expectToggleValue('TacetVanishFilterAllies') == true
            local foundPlayer

            for index, victim in ipairs(players:GetPlayers())do
                if isTargetInRange(victim, fieldPosition, radius, skipAllies) then
                    foundPlayer = victim

                    break
                end
            end

            if foundPlayer then
                if pressedKey then
                    sendKeyPress(leftControl)
                end

                logger.warnNotify('Tacet Vanish aborted \u{2014} %s in field (%.0f studs).', foundPlayer.Name, radius)
            else
                setRootY(4500)
                logger.successNotify("Tacet Vanish \u{2014} TP'd to Y=%d.", 4500)
            end
        end)

        if not ok then
            logger.warn('Tacet Vanish error: %s', tostring(errorMsg))
        end
    end
    local regularTeleport = function()
        local ok, err = pcall(function()
            if setRootY(4500) then
                logger.successNotify("Regular Teleport \u{2014} TP'd to Y=%d.", 4500)
            else
                logger.warnNotify('Regular Teleport \u{2014} no HumanoidRootPart.')
            end
        end)

        if not ok then
            logger.warn('Regular Teleport error: %s', tostring(err))
        end
    end
    local teleportWithItem = function(actionName, remoteName, aB)
        local tpOk, tpErr = pcall(function()
            local player = players.LocalPlayer
            local character = player and player.Character
            local backpack = player and player:FindFirstChild('Backpack')

            if not character or not backpack then
                logger.warnNotify('%s \u{2014} no character / backpack.', actionName)

                return
            end
            if not backpack:FindFirstChild(remoteName) then
                logger.warnNotify('%s \u{2014} %s not equipped.', actionName, remoteName)

                return
            end

            local requests = character:FindFirstChild('CharacterHandler') and character.CharacterHandler:FindFirstChild('Requests')
            local castResonance = requests and requests:FindFirstChild('CastResonance')
            local resonanceRelease = requests and requests:FindFirstChild('ResonanceRelease')

            if not castResonance then
                logger.warnNotify('%s \u{2014} CastResonance remote unavailable.', actionName)

                return
            end

            castResonance:FireServer()

            if resonanceRelease then
                task.delay(0.05, function()
                    pcall(function()
                        resonanceRelease:FireServer()
                    end)
                end)
            end

            task.wait(aB)

            if setRootY(4500) then
                logger.successNotify("%s \u{2014} TP'd to Y=%d.", actionName, 4500)
            else
                logger.warnNotify('%s \u{2014} no HumanoidRootPart.', actionName)
            end
        end)

        if not tpOk then
            logger.warn('%s error: %s', actionName, tostring(tpErr))
        end
    end
    local smokeScreenTeleport = function()
        teleportWithItem('Smoke Screen TP', 'Resonance:Smokescreen', 0.8)
    end
    local portalsTeleport = function()
        teleportWithItem('Portals TP', 'Resonance:Portals', 1.5)
    end

    function module.fakeVanish()
        if aw then
            return
        end
        if not module.isInDepths() then
            logger.warnNotify('Fake Vanish \u{2014} Depths only.')

            return
        end

        aw = true

        local vanishMode = configuration.expectOptionValue('FakeVanishMode') or 'Tacet Vanish'

        if vanishMode == 'Regular Teleport' then
            regularTeleport()
        elseif vanishMode == 'Smoke Screen TP' then
            smokeScreenTeleport()
        elseif vanishMode == 'Portals TP' then
            portalsTeleport()
        else
            crouchTeleport()
        end

        aw = false
    end

    local maid = maidUtility.new()
    local aE = setmetatable({}, {
        __mode = 'k',
    })
    local aF = setmetatable({}, {
        __mode = 'k',
    })
    local aG = setmetatable({}, {
        __mode = 'k',
    })
    local aH = 0
    local detectTeleports = function()
        if not configuration.expectToggleValue('DepthsTPDetector') then
            return
        end
        if not module.isInDepths() then
            return
        end

        local now = os.clock()

        if now < aH then
            return
        end

        local localPlayer = players.LocalPlayer
        local localCharacter = localPlayer and localPlayer.Character
        local localRoot = localCharacter and localCharacter:FindFirstChild('HumanoidRootPart')

        if not localRoot then
            return
        end

        local localPos = localRoot.Position
        local range = configuration.expectOptionValue('DepthsTPDetectorRange') or 2000
        local rangeSq = range * range

        for playerIndex, targetPlayer in ipairs(players:GetPlayers())do
            if targetPlayer == localPlayer then
                continue
            end

            local targetCharacter = targetPlayer.Character
            local targetRoot = targetCharacter and targetCharacter:FindFirstChild('HumanoidRootPart')

            if not targetRoot then
                aE[targetPlayer] = nil
                aF[targetPlayer] = nil

                continue
            end

            local targetPos = targetRoot.Position
            local prevPos = aE[targetPlayer]

            aE[targetPlayer] = targetPos

            local samples = aF[targetPlayer]

            if not samples then
                samples = {}
                aF[targetPlayer] = samples
            end

            samples[#samples + 1] = {
                t = now,
                y = targetPos.Y,
            }

            while samples[1] and now - samples[1].t > 1 do
                table.remove(samples, 1)
            end

            local debounceUntil = aG[targetPlayer]

            if debounceUntil and now < debounceUntil then
                continue
            end
            if #samples < 2 then
                continue
            end
            if prevPos then
                local dx, dy, dz = prevPos.X - localPos.X, prevPos.Y - localPos.Y, prevPos.Z - localPos.Z

                if dx * dx + dy * dy + dz * dz > rangeSq then
                    continue
                end
            end

            local minY, maxY = math.huge, -math.huge

            for sampleIndex, sample in ipairs(samples)do
                if sample.y < minY then
                    minY = sample.y
                end
                if sample.y > maxY then
                    maxY = sample.y
                end
            end

            local delta = maxY - minY

            if delta >= 500 then
                logger.warn(
"[TPDet] %s window-delta=%.0f (%d samples / %.2fs) range=%d threshold=%d", targetPlayer.Name, delta, #samples, 1, range, 1000)
            end
            if delta >= 1000 then
                aH = now + 30

                local targetY = targetPos.Y + 5

                logger.warnNotify('TP Detector \u{2014} %s jumped %.0f studs in Y. Following to Y=%.0f.', targetPlayer.Name, delta, targetY)
                task.spawn(function()
                    local tpSuccess = pcall(setRootY, targetY)

                    if tpSuccess then
                        logger.successNotify("TP Detector \u{2014} TP'd to Y=%.0f (%ds debounce).", targetY, 30)
                    end
                end)

                return
            end
        end
    end
    local removePlayerTrackers = function(removedPlayer)
        aE[removedPlayer] = nil
        aF[removedPlayer] = nil
        aG[removedPlayer] = nil
    end
    local setupCharacterTracking = function(player)
        player.CharacterAdded:Connect(function()
            aE[player] = nil
            aF[player] = nil
            aG[player] = os.clock() + 3
        end)
    end

    function module.init()
        maid:add(signal.new(runService.Heartbeat):connect('DepthsEscape_TPDetector', detectTeleports))
        maid:add(signal.new(players.PlayerAdded):connect('DepthsEscape_PlayerAdded', setupCharacterTracking))
        maid:add(signal.new(players.PlayerRemoving):connect('DepthsEscape_PlayerRemoving', removePlayerTrackers))

        for index, target in ipairs(players:GetPlayers())do
            if target ~= players.LocalPlayer then
                setupCharacterTracking(target)
            end
        end

        logger.warn('DepthsEscape initialized.')
    end
    function module.detach()
        maid:clean()
    end
    function module.isInDepths()
        local success, result = pcall(function()
            local info = replicatedStorage:FindFirstChild('Info')
            local realmInfo = info and info:FindFirstChild('RealmInfo')

            if not realmInfo then
                return nil
            end

            local realmData = require(realmInfo)

            return realmData.CurrentWorld
        end)

        return success and result == 'Depths'
    end

    return module
end


return aa()

]=],
    ["Features/Game/EffectShower"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local coreGuiManager = a["Utility/CoreGuiManager"]()
    local latency = a["Game/Latency"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local signal = a["Utility/Signal"]()
    local ag = {}
    local httpService = game:GetService('HttpService')
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')
    local userInputService = game:GetService('UserInputService')
    local cleanup = maid.new()
    local ao = {}
    local ap = {}
    local aq = {}
    local ar = false
    local as = false
    local startTime = os.clock()
    local au
    local av = 0
    local aw = false
    local loadBlacklist = function()
        ao = {}

        if not (isfile and readfile) then
            return
        end
        if not isfile('PalantirX/EffectShower_blacklist.json') then
            return
        end

        local success, decoded = pcall(function()
            return httpService:JSONDecode(readfile('PalantirX/EffectShower_blacklist.json'))
        end)

        if success and type(decoded) == 'table' then
            for key, effectName in next, decoded do
                if type(effectName) == 'string' then
                    ao[effectName] = true
                end
            end
        end
    end
    local saveBlacklist = function()
        if not writefile then
            return
        end

        local list = {}

        for blacklistName in next, ao do
            list[#list + 1] = blacklistName
        end

        if makefolder and isfolder and not isfolder('PalantirX') then
            pcall(makefolder, 'PalantirX')
        end

        pcall(writefile, 'PalantirX/EffectShower_blacklist.json', httpService:JSONEncode(list))
    end
    local az = coreGuiManager.imark(Instance.new('ScreenGui'))

    az.Name = 'EffectShower'
    az.ResetOnSpawn = false
    az.DisplayOrder = 12
    az.Enabled = false

    local frame = Instance.new('Frame')

    frame.Name = 'Root'
    frame.Position = UDim2.new(0, 16, 0, 120)
    frame.Size = UDim2.new(0, 300, 0, 380)
    frame.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
    frame.BackgroundTransparency = 0.15
    frame.BorderSizePixel = 0
    frame.Active = true
    frame.Parent = az

    local uiCorner = Instance.new('UICorner')

    uiCorner.CornerRadius = UDim.new(0, 6)
    uiCorner.Parent = frame

    local button = Instance.new('TextButton')

    button.Name = 'Title'
    button.Size = UDim2.new(1, 0, 0, 22)
    button.BackgroundColor3 = Color3.fromRGB(24, 24, 24)
    button.BorderSizePixel = 0
    button.AutoButtonColor = false
    button.Font = Enum.Font.GothamBold
    button.TextSize = 12
    button.TextColor3 = Color3.fromRGB(235, 235, 235)
    button.TextXAlignment = Enum.TextXAlignment.Left
    button.Text = '  Effect Shower'
    button.Parent = frame

    local corner = Instance.new('UICorner')

    corner.CornerRadius = UDim.new(0, 6)
    corner.Parent = button

    local scrollingFrame = Instance.new('ScrollingFrame')

    scrollingFrame.Name = 'List'
    scrollingFrame.Position = UDim2.new(0, 0, 0, 24)
    scrollingFrame.Size = UDim2.new(1, 0, 1, -24)
    scrollingFrame.BackgroundTransparency = 1
    scrollingFrame.BorderSizePixel = 0
    scrollingFrame.ScrollBarThickness = 4
    scrollingFrame.ScrollBarImageColor3 = Color3.fromRGB(90, 90, 90)
    scrollingFrame.CanvasSize = UDim2.new()
    scrollingFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
    scrollingFrame.ScrollingDirection = Enum.ScrollingDirection.Y
    scrollingFrame.Parent = frame

    local listLayout = Instance.new('UIListLayout')

    listLayout.SortOrder = Enum.SortOrder.LayoutOrder
    listLayout.Padding = UDim.new(0, 1)
    listLayout.Parent = scrollingFrame

    local padding = Instance.new('UIPadding')

    padding.PaddingLeft = UDim.new(0, 6)
    padding.PaddingRight = UDim.new(0, 6)
    padding.PaddingTop = UDim.new(0, 3)
    padding.PaddingBottom = UDim.new(0, 3)
    padding.Parent = scrollingFrame

    do
        local dragging = false
        local dragStart, frameOrigin

        button.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                frameOrigin = frame.Position

                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                    end
                end)
            end
        end)
        userInputService.InputChanged:Connect(function(inputObject)
            if not dragging then
                return
            end
            if inputObject.UserInputType ~= Enum.UserInputType.MouseMovement and inputObject.UserInputType ~= Enum.UserInputType.Touch then
                return
            end

            local delta = inputObject.Position - dragStart

            frame.Position = UDim2.new(frameOrigin.X.Scale, frameOrigin.X.Offset + delta.X, frameOrigin.Y.Scale, frameOrigin.Y.Offset + delta.Y)
        end)
    end

    button.MouseButton1Click:Connect(function()
        ar = not ar
    end)
    button.MouseButton2Click:Connect(function()
        as = not as
    end)

    local aI = {}
    local aK = {}
    local aL = {}
    local getRowWidget = function(index)
        local cachedRow = aI[index]

        if cachedRow then
            return cachedRow
        end

        cachedRow = Instance.new('TextButton')
        cachedRow.Name = 'Row' .. index
        cachedRow.Size = UDim2.new(1, 0, 0, 15)
        cachedRow.BackgroundTransparency = 1
        cachedRow.AutoButtonColor = false
        cachedRow.Font = Enum.Font.Code
        cachedRow.TextSize = 12
        cachedRow.TextXAlignment = Enum.TextXAlignment.Left
        cachedRow.TextColor3 = Color3.fromRGB(220, 220, 220)
        cachedRow.Text = ''
        cachedRow.LayoutOrder = index
        cachedRow.Parent = scrollingFrame
        aI[index] = cachedRow

        return cachedRow
    end
    local getEffectClass = function(entry)
        if type(entry) ~= 'table' then
            return nil
        end

        return entry.Class or (entry.index and entry.index.Class)
    end
    local getEffectValue = function(source)
        local value = source.Value or (source.index and source.index.Value)

        if value == nil then
            return nil
        end

        return value
    end
    local removeClassEntries = function(class)
        local result = {}

        for index, data in next, aq do
            if data.class ~= class then
                result[#result + 1] = data
            end
        end

        aq = result
    end
    local trimHistory = function()
        for i = #aq, 46, -1 do
            aq[i] = nil
        end
    end
    local recordEffect = function(effect, seeded)
        local className = getEffectClass(effect)

        if not className or ao[className] then
            return
        end

        local record = {
            class = className,
            value = getEffectValue(effect),
            id = effect.ID,
            addedAt = os.clock(),
            removedAt = nil,
            debris = effect.index and effect.index.DebrisTime or nil,
            timestamp = effect.index and effect.index.Timestamp or nil,
            ghost = false,
            seeded = seeded or false,
        }

        ap[effect] = record

        table.insert(aq, 1, record)
        trimHistory()
    end
    local fetchEffects = function()
        if not au then
            return
        end

        local effects = au.Effects

        if not effects and type(au.GetEffects) == 'function' then
            local ok, fetched = pcall(au.GetEffects, au)

            if ok then
                effects = fetched
            end
        end
        if type(effects) ~= 'table' then
            return
        end

        for id, effectEntry in next, effects do
            if type(effectEntry) == 'table' and not ap[effectEntry] then
                recordEffect(effectEntry, true)
            end
        end

        av = os.clock()
    end
    local onEffectAdded = function(effectObj)
        if ar or not configuration.expectToggleValue('EffectShower') then
            return
        end
        if type(effectObj) ~= 'table' then
            return
        end
        if ap[effectObj] then
            return
        end

        recordEffect(effectObj, false)
    end
    local onEffectRemoved = function(removed)
        if not configuration.expectToggleValue('EffectShower') then
            return
        end

        local existing = type(removed) == 'table' and ap[removed] or nil

        if existing then
            existing.removedAt = os.clock()
            existing.rlat = latency.half_ping()
            ap[removed] = nil

            return
        end
        if os.clock() - av < 2 then
            return
        end

        local effectClass = getEffectClass(removed)

        if not effectClass or ao[effectClass] then
            return
        end

        table.insert(aq, 1, {
            class = effectClass,
            value = getEffectValue(removed),
            id = removed and removed.ID or nil,
            addedAt = nil,
            removedAt = os.clock(),
            rlat = latency.half_ping(),
            debris = removed and removed.index and removed.index.DebrisTime or nil,
            timestamp = removed and removed.index and removed.index.Timestamp or nil,
            ghost = true,
            seeded = false,
        })
        trimHistory()
    end
    local formatRelativeTime = function(aX)
        if not aX then
            return '?'
        end

        return string.format('%.2f', aX - startTime)
    end
    local effectiveRemovedAt = function(info)
        if not info.removedAt then
            return nil
        end

        local adjustedTime = info.removedAt - (info.rlat or 0)

        if info.addedAt and adjustedTime < info.addedAt then
            return info.addedAt
        end

        return adjustedTime
    end

    ag._serverRemoved = effectiveRemovedAt

    local observedLifetime = function(effect)
        local removedAt = effectiveRemovedAt(effect)

        if not removedAt or not effect.addedAt then
            return nil
        end

        return removedAt - effect.addedAt
    end

    ag._observedLifetime = observedLifetime

    local formatLifetimeText = function(record)
        local lifetime = '?'
        local observed = observedLifetime(record)

        if observed then
            local raw = record.removedAt - record.addedAt
            local latSuffix = (record.rlat or 0) > raw and ' lat capped' or ''

            lifetime = string.format('%.3fs (raw %.3fs, -%.0fms lat%s)', observed, raw, (record.rlat or 0) * 1000, latSuffix)
        elseif record.addedAt then
            lifetime = string.format('%.3fs (alive)', os.clock() - record.addedAt)
        end

        local description = string.format(
"%s | added +%s | removed +%s (server +%s) | lifetime %s | DebrisTime %s | value %s | id %s", record.class, formatRelativeTime(record.addedAt), formatRelativeTime(record.removedAt), effectiveRemovedAt(record) and formatRelativeTime(effectiveRemovedAt(record)) or '?', lifetime, record.debris and string.format('%.3fs', record.debris) or 'nil', tostring(record.value), tostring(record.id))

        if setclipboard then
            setclipboard(description)
        end

        logger.warn('[EffectShower] copied: %s', description)
    end
    local formatStatusMarker = function(entry)
        local isAlive = entry.removedAt == nil
        local symbol

        if entry.seeded then
            symbol = '~'
        elseif isAlive then
            symbol = '+'
        else
            symbol = '-'
        end

        local age

        if isAlive and entry.addedAt then
            age = os.clock() - entry.addedAt
        elseif entry.addedAt and entry.removedAt then
            age = observedLifetime(entry)
        else
            age = nil
        end

        local detail

        if entry.ghost then
            detail = 'ghost'
        elseif age and entry.debris then
            detail = string.format('%s %.2f / D%.2f', isAlive and 't' or '\u{394}', age, entry.debris)
        elseif age then
            detail = string.format('%s %.2f / D--', isAlive and 't' or '\u{394}', age)
        elseif entry.debris then
            detail = string.format('D%.2f', entry.debris)
        else
            detail = ''
        end

        local valueSuffix = ''

        if type(entry.value) == 'string' and #entry.value > 0 and #entry.value <= 22 then
            valueSuffix = ' (' .. entry.value .. ')'
        end

        return string.format('%s %-22s %s%s', symbol, entry.class:sub(1, 22), detail, valueSuffix)
    end
    local getRowColor = function(item)
        if item.ghost then
            return Color3.fromRGB(150, 150, 90)
        end
        if item.removedAt == nil then
            if item.seeded then
                return Color3.fromRGB(110, 180, 210)
            end

            return Color3.fromRGB(120, 220, 120)
        end
        if not item.seeded and item.debris and item.debris > 0 then
            local observedLife = observedLifetime(item)

            if observedLife and math.abs(observedLife - item.debris) / item.debris >= 0.15 then
                return Color3.fromRGB(235, 110, 110)
            end
        end

        return Color3.fromRGB(150, 150, 150)
    end
    local clearBlacklist = function()
        local count = 0

        for key in next, ao do
            count += 1
        end

        ao = {}

        saveBlacklist()
        logger.warn('[EffectShower] blacklist cleared (%d entries).', count)
    end
    local a3 = {
        effect = {
            left = function(effectRow)
                formatLifetimeText(effectRow.rec)
            end,
            right = function(effectEntry)
                ao[effectEntry.rec.class] = true

                removeClassEntries(effectEntry.rec.class)
                saveBlacklist()
                logger.warn("[EffectShower] blacklisted '%s'.", effectEntry.rec.class)
            end,
        },
        bl = {
            left = function(blRow)
                if setclipboard then
                    setclipboard(blRow.class)
                end
            end,
            right = function(blEntry)
                ao[blEntry.class] = nil

                saveBlacklist()
                logger.warn("[EffectShower] restored '%s'.", blEntry.class)
            end,
        },
        clearall = {
            left = clearBlacklist,
            right = clearBlacklist,
        },
    }
    local getRowKey = function(row)
        if row.kind == 'effect' then
            return row.rec
        end
        if row.kind == 'bl' then
            return 'bl:' .. row.class
        end

        return row.kind
    end
    local a5 = 0
    local updateVisibility = function()
        local showShower = configuration.expectToggleValue('EffectShower') == true

        az.Enabled = showShower

        if showShower and not aw then
            fetchEffects()
        end

        aw = showShower

        if not showShower then
            return
        end

        local now = os.clock()

        if now - a5 < (1 / 15) then
            return
        end

        a5 = now

        local hiddenClasses = {}

        for className in next, ao do
            hiddenClasses[#hiddenClasses + 1] = className
        end

        table.sort(hiddenClasses)

        button.Text = string.format('  Effect Shower \u{2014} %d shown / %d hidden  %s%s', #aq, #hiddenClasses, ar and '[FROZEN]' or '[LIVE]', as and '  [manage]' or '')

        local rows = {}

        for effectIndex, effect in next, aq do
            rows[#rows + 1] = {
                kind = 'effect',
                rec = effect,
            }
        end

        if as then
            rows[#rows + 1] = {
                kind = 'header',
                text = '\u{2500}\u{2500} blacklist (right-click a row to restore) \u{2500}\u{2500}',
            }

            if #hiddenClasses > 0 then
                rows[#rows + 1] = {
                    kind = 'clearall',
                    text = string.format('\u{d7} clear all (%d)', #hiddenClasses),
                }
            end

            for hiddenIndex, hiddenClass in next, hiddenClasses do
                rows[#rows + 1] = {
                    kind = 'bl',
                    class = hiddenClass,
                }
            end
        end

        local rowCount = #rows
        local maxRows = math.max(rowCount, #aI)

        for index = 1, maxRows do
            local row = rows[index]

            if not row then
                local button = aI[index]

                if button then
                    button.Visible = false
                end

                aL[index] = nil

                continue
            end

            local rowButton = getRowWidget(index)

            rowButton.Visible = true
            rowButton.LayoutOrder = index

            if row.kind == 'effect' then
                rowButton.Text = formatStatusMarker(row.rec)
                rowButton.TextColor3 = getRowColor(row.rec)
            elseif row.kind == 'header' then
                rowButton.Text = row.text
                rowButton.TextColor3 = Color3.fromRGB(120, 120, 120)
            elseif row.kind == 'clearall' then
                rowButton.Text = '  ' .. row.text
                rowButton.TextColor3 = Color3.fromRGB(235, 150, 110)
            elseif row.kind == 'bl' then
                rowButton.Text = '  \u{d7} ' .. row.class
                rowButton.TextColor3 = Color3.fromRGB(170, 170, 170)
            end

            local handler = getRowKey(row)

            if aL[index] ~= handler then
                aL[index] = handler

                if aK[index] then
                    for connIndex, connection in next, aK[index]do
                        connection:Disconnect()
                    end

                    aK[index] = nil
                end

                local handlers = a3[row.kind]

                if handlers then
                    aK[index] = {
                        rowButton.MouseButton1Click:Connect(function()
                            handlers.left(row)
                        end),
                        rowButton.MouseButton2Click:Connect(function()
                            handlers.right(row)
                        end),
                    }
                end
            end
        end
    end

    function ag.init()
        loadBlacklist()

        local replicator = replicatedStorage:WaitForChild('EffectReplicator', 20)

        if not replicator then
            logger.warn('[EffectShower] EffectReplicator not found \u{2014} shower inactive.')

            return
        end

        local success, replicatorApi = pcall(require, replicator)

        if not success or type(replicatorApi) ~= 'table' then
            logger.warn('[EffectShower] require(EffectReplicator) failed (%s).', tostring(replicatorApi))

            return
        end

        au = replicatorApi

        if replicatorApi.EffectAdded then
            cleanup:mark(signal.new(replicatorApi.EffectAdded):connect('EffectShower_Added', onEffectAdded))
        end
        if replicatorApi.EffectRemoved then
            cleanup:mark(signal.new(replicatorApi.EffectRemoved):connect('EffectShower_Removed', onEffectRemoved))
        end

        fetchEffects()

        local player = players.LocalPlayer

        if player then
            cleanup:mark(player.CharacterAdded:Connect(function()
                aq = {}
                ap = {}
                av = os.clock()
            end))
        end

        cleanup:mark(signal.new(runService.RenderStepped):connect('EffectShower_Render', updateVisibility))
        logger.warn('EffectShower \u{2014} ready.')
    end
    function ag.detach()
        cleanup:clean()

        az.Enabled = false
        aq = {}
        ap = {}
        au = nil
        aw = false

        for key, connections in next, aK do
            for index, connection in next, connections do
                connection:Disconnect()
            end

            aK[key] = nil
            aL[key] = nil
        end
        for uiKey, element in next, aI do
            element.Visible = false
        end
    end

    return ag
end


return aa()

]=],
    ["Features/Game/Freecam"] = [=[
local aa = function()
    local freecam = {}
    local runService = game:GetService('RunService')
    local userInput = game:GetService('UserInputService')
    local actionService = game:GetService('ContextActionService')
    local players = game:GetService('Players')
    local af
    local ag
    local ah = false
    local ai = CFrame.new()
    local aj = 0
    local al = 0
    local am = Vector2.new(0, 0)
    local an = 16
    local ao = 50
    local ap = false
    local aq = {
        Enum.KeyCode.W,
        Enum.KeyCode.A,
        Enum.KeyCode.S,
        Enum.KeyCode.D,
        Enum.KeyCode.Up,
        Enum.KeyCode.Down,
        Enum.KeyCode.Left,
        Enum.KeyCode.Right,
        Enum.KeyCode.Space,
        Enum.KeyCode.LeftShift,
        Enum.KeyCode.RightShift,
    }
    local ar = {
        [Enum.KeyCode.W] = Vector3.new(0, 0, -1),
        [Enum.KeyCode.S] = Vector3.new(0, 0, 1),
        [Enum.KeyCode.A] = Vector3.new(-1, 0, 0),
        [Enum.KeyCode.D] = Vector3.new(1, 0, 0),
    }
    local getLocalHumanoid = function()
        local character = players.LocalPlayer.Character

        if not character then
            return nil
        end

        return character:FindFirstChildOfClass('Humanoid')
    end
    local getLocalRootPart = function()
        local rootCharacter = players.LocalPlayer.Character

        if not rootCharacter then
            return nil
        end

        return rootCharacter:FindFirstChild('HumanoidRootPart')
    end
    local getFreecamSpeed = function()
        local speedOk, speedValue = pcall(function()
            return Options.FreecamSpeed.Value
        end)

        if speedOk and type(speedValue) == 'number' then
            return speedValue
        end

        return 50
    end
    local getFreecamSensitivity = function()
        local sensOk, sensValue = pcall(function()
            return Options.FreecamSensitivity.Value
        end)

        if sensOk and type(sensValue) == 'number' then
            return sensValue
        end

        return 0.3
    end
    local updateFreecamCamera = function(deltaTime)
        if am.X ~= 0 or am.Y ~= 0 then
            local rotationScale = getFreecamSensitivity() * 0.005

            al = al - am.X * rotationScale
            aj = math.clamp(aj - am.Y * rotationScale, -math.pi * 0.499, math.pi * 0.499)
            am = Vector2.new(0, 0)
        end

        local rotation = CFrame.Angles(0, al, 0) * CFrame.Angles(aj, 0, 0)
        local inputVector = Vector3.new(0, 0, 0)

        for keyCode, direction in next, ar do
            if userInput:IsKeyDown(keyCode) then
                inputVector = inputVector + direction
            end
        end

        if inputVector.Magnitude > 0 then
            inputVector = inputVector.Unit
        end

        local speed = getFreecamSpeed()

        if userInput:IsKeyDown(Enum.KeyCode.LeftControl) then
            speed = speed * 2
        end

        local worldDelta = rotation:VectorToWorldSpace(inputVector) * speed * deltaTime

        if userInput:IsKeyDown(Enum.KeyCode.Space) then
            worldDelta = worldDelta + Vector3.new(0, speed * deltaTime, 0)
        end

        ai = CFrame.new(ai.Position + worldDelta) * rotation
        workspace.CurrentCamera.CFrame = ai
    end

    function freecam.enable()
        if ah then
            return
        end

        ah = true

        actionService:BindActionAtPriority('FreecamSinkMovement', function()
            return Enum.ContextActionResult.Sink
        end, false, Enum.ContextActionPriority.High.Value, table.unpack(aq))

        local root = getLocalRootPart()

        if root then
            ap = root.Anchored
            root.Anchored = true
        end

        local humanoid = getLocalHumanoid()

        if humanoid then
            an = humanoid.WalkSpeed
            ao = humanoid.JumpPower
            humanoid.WalkSpeed = 0
            humanoid.JumpPower = 0
        end

        local camera = workspace.CurrentCamera

        ai = camera.CFrame

        local lookVector = ai.LookVector

        al = math.atan2(-lookVector.X, -lookVector.Z)
        aj = math.asin(math.clamp(lookVector.Y, -1, 1))
        am = Vector2.new(0, 0)
        camera.CameraType = Enum.CameraType.Scriptable
        ag = userInput.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement then
                if userInput:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
                    am = am + Vector2.new(input.Delta.X, input.Delta.Y)
                end
            end
        end)
        af = runService.RenderStepped:Connect(updateFreecamCamera)
    end
    function freecam.disable()
        if not ah then
            return
        end

        ah = false

        actionService:UnbindAction('FreecamSinkMovement')

        if af then
            af:Disconnect()

            af = nil
        end
        if ag then
            ag:Disconnect()

            ag = nil
        end

        local rootPart = getLocalRootPart()

        if rootPart then
            rootPart.Anchored = ap
        end

        local playerHumanoid = getLocalHumanoid()

        if playerHumanoid then
            playerHumanoid.WalkSpeed = an
            playerHumanoid.JumpPower = ao
        end

        local currentCamera = workspace.CurrentCamera

        currentCamera.CameraType = Enum.CameraType.Custom
        userInput.MouseBehavior = Enum.MouseBehavior.Default

        local playerCharacter = players.LocalPlayer.Character

        if playerCharacter then
            local subjectRoot = playerCharacter:FindFirstChild('HumanoidRootPart')

            if subjectRoot then
                currentCamera.CameraSubject = subjectRoot
            end
        end
    end
    function freecam.isActive()
        return ah
    end

    return freecam
end


return aa()

]=],
    ["Features/Game/GankPing"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local finder = a["Utility/Finder"]()
    local logger = a["Utility/Logger"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local getCurrentRealm = function()
        local ok, realm = pcall(function()
            local infoFolder = replicatedStorage:FindFirstChild('Info')
            local realmInfo = infoFolder and infoFolder:FindFirstChild('RealmInfo')

            if not realmInfo then
                return nil
            end

            return require(realmInfo).CurrentWorld
        end)

        if ok and type(realm) == 'string' and #realm > 0 then
            return realm
        end

        return 'Unknown'
    end
    local stripHtmlTags = function(text)
        return text:gsub('<.->', ''):gsub('%s+$', ''):gsub('^%s+', '')
    end
    local ai = function(predicate)
        local player = players.LocalPlayer

        if not player then
            return 'Unknown'
        end

        local playerGui = player:FindFirstChild('PlayerGui')

        if not playerGui then
            return 'Unknown'
        end

        for index, descendant in ipairs(playerGui:GetDescendants())do
            if descendant:IsA('TextLabel') then
                local cleanedText = stripHtmlTags(descendant.Text)

                if predicate(cleanedText) then
                    return cleanedText
                end
            end
        end

        return 'Unknown'
    end
    local aj = function()
        local localPlayer = players.LocalPlayer

        if not localPlayer then
            return 'Unknown'
        end

        local ui = localPlayer:FindFirstChild('PlayerGui')

        if not ui then
            return 'Unknown'
        end

        local found, serverTitle = pcall(function()
            return ui:WaitForChild('TopbarGui', 3):WaitForChild('Container', 3):WaitForChild('InfoFrame', 3):WaitForChild('ServerInfo', 3):WaitForChild('ServerTitle', 3)
        end)

        if not found or not serverTitle then
            return 'Unknown'
        end

        return stripHtmlTags(serverTitle.Text)
    end
    local getGuildTag = function()
        local currentPlayer = players.LocalPlayer

        if not currentPlayer then
            return 'Unknown'
        end

        local character = currentPlayer.Character

        if character then
            local guildTag = character:GetAttribute('GuildName') or character:GetAttribute('Guild')

            if guildTag and guildTag ~= '' then
                return tostring(guildTag)
            end
        end

        local guildAttr = currentPlayer:GetAttribute('GuildName') or currentPlayer:GetAttribute('Guild')

        if guildAttr and guildAttr ~= '' then
            return tostring(guildAttr)
        end

        return ai(function(candidate)
            if #candidate < 3 or #candidate > 32 then
                return false
            end
            if candidate:match('^%[.+%]$') then
                return true
            end
            if candidate:match('^Guild:%s*.+') then
                return true
            end

            return false
        end)
    end
    local am = function()
        local activePlayer = players.LocalPlayer

        if not activePlayer then
            return 'Unknown'
        end

        local playerUI = activePlayer:FindFirstChild('PlayerGui')

        if not playerUI then
            return 'Unknown'
        end

        local regionFound, serverRegion = pcall(function()
            return playerUI:WaitForChild('TopbarGui', 3):WaitForChild('Container', 3):WaitForChild('InfoFrame', 3):WaitForChild('ServerInfo', 3):WaitForChild('ServerRegion', 3)
        end)

        if not regionFound or not serverRegion then
            return 'Unknown'
        end

        return stripHtmlTags(serverRegion.Text)
    end
    local an = function()
        local gankPlayer = players.LocalPlayer

        if not gankPlayer then
            return 'Unknown'
        end

        local gankCharacter = gankPlayer.Character

        if not gankCharacter then
            return 'Unknown'
        end

        local root = gankCharacter:FindFirstChild('HumanoidRootPart')

        if not root then
            return 'Unknown'
        end

        local marker = finder.marker(root.Position)

        if not marker then
            return 'Unknown'
        end

        return marker.Parent.Name or 'Unknown'
    end
    local ao = function()
        local localPlayer = players.LocalPlayer

        if not localPlayer then
            return 'Unknown'
        end

        local playerGui = localPlayer:FindFirstChild('PlayerGui')

        if not playerGui then
            return 'Unknown'
        end

        local ok, character = pcall(function()
            return playerGui:WaitForChild('TopbarGui', 3):WaitForChild('Container', 3):WaitForChild('InfoFrame', 3):WaitForChild('CharacterInfo', 3):WaitForChild('Character', 3)
        end)

        if not ok or not character then
            return 'Unknown'
        end

        return stripHtmlTags(character.Text)
    end

    module.savedWebhooks = {}

    local ap = {
        {
            id = 'Username',
            label = 'Username',
            inline = true,
            get = function(player)
                return player.username
            end,
        },
        {
            id = 'User ID',
            label = 'User ID',
            inline = true,
            get = function(player)
                return player.userId
            end,
        },
        {
            id = 'Slot Name',
            label = 'Slot Name',
            inline = true,
            get = function(player)
                return player.slotName
            end,
        },
        {
            id = 'Server',
            label = 'Server',
            inline = false,
            get = function(player)
                return player.serverName
            end,
        },
        {
            id = 'Region',
            label = 'Region',
            inline = false,
            get = function(player)
                return player.region
            end,
        },
        {
            id = 'Area',
            label = 'Area',
            inline = false,
            get = function(player)
                return player.areaName
            end,
        },
        {
            id = 'Guild',
            label = 'Guild',
            inline = true,
            get = function(player)
                return player.guildName
            end,
        },
        {
            id = 'Job ID',
            label = 'Job ID',
            inline = false,
            get = function(player)
                return player.jobId
            end,
        },
        {
            id = 'World',
            label = 'World',
            inline = true,
            get = function(player)
                return player.world
            end,
        },
    }

    module.FIELD_IDS = {}

    for index, field in ipairs(ap)do
        module.FIELD_IDS[#module.FIELD_IDS + 1] = field.id
    end

    local resolvePingTarget = function()
        local pingTarget = configuration.expectOptionValue('GankPingTarget') or 'None'

        if pingTarget == '@everyone' then
            return '@everyone'
        end
        if pingTarget == '@here' then
            return '@here'
        end
        if pingTarget == 'Specific Role' then
            local roleId = configuration.expectOptionValue('GankPingRoleId')

            if type(roleId) == 'string' then
                roleId = roleId:gsub('%s+', '')
            end
            if roleId and #roleId > 0 then
                return '<@&' .. roleId .. '>'
            end
        end

        return ''
    end
    local collectWebhooks = function()
        local webhooks = {}
        local seen = {}

        if configuration.expectToggleValue('GankPingTeamWebhook') then
            webhooks[#webhooks + 1] = 
"https://canary.discord.com/api/webhooks/1482767633530228786/IusVD9Gpq9IchHtTvUkCbz2aZMMFi83dBtWCs7v9PYv_bw9Xx8CvmTohnlov0FIQfCfQ"
            seen[
"https://canary.discord.com/api/webhooks/1482767633530228786/IusVD9Gpq9IchHtTvUkCbz2aZMMFi83dBtWCs7v9PYv_bw9Xx8CvmTohnlov0FIQfCfQ" ] = true
        end

        local sendTo = configuration.expectOptionValue('GankWebhookSendTo')

        if type(sendTo) == 'table' then
            for key, enabled in pairs(sendTo)do
                if enabled then
                    local webhookUrl = module.savedWebhooks[key]

                    if webhookUrl and not seen[webhookUrl] then
                        webhooks[#webhooks + 1] = webhookUrl
                        seen[webhookUrl] = true
                    end
                end
            end
        end

        return webhooks
    end
    local buildFields = function(data, hideUserId)
        local pingConfig = configuration.expectOptionValue('GankPingFields')
        local configEmpty = type(pingConfig) ~= 'table' or next(pingConfig) == nil
        local fields = {}

        for index, fieldDef in ipairs(ap)do
            local fieldId = fieldDef.id
            local include = configEmpty or pingConfig[fieldId]

            if hideUserId and fieldId == 'User ID' then
                include = false
            end
            if include then
                fields[#fields + 1] = {
                    name = fieldDef.label,
                    value = '`' .. tostring(fieldDef.get(data)) .. '`',
                    inline = fieldDef.inline,
                }
            end
        end

        return fields
    end

    function module.send()
        local webhooks = collectWebhooks()

        if #webhooks == 0 then
            return logger.errorNotify('no webhooks selected \u{2014} pick at least one in the dropdown or enable the global webhook')
        end

        local localPlayer = players.LocalPlayer

        if not localPlayer then
            return logger.errorNotify('no local player')
        end

        local playerInfo = {
            username = localPlayer.Name,
            displayName = localPlayer.DisplayName,
            slotName = ao(),
            userId = tostring(localPlayer.UserId),
            serverName = aj(),
            region = am(),
            guildName = getGuildTag(),
            areaName = an(),
            world = getCurrentRealm(),
            jobId = tostring(game.JobId),
        }
        local hideUserId = configuration.expectToggleValue('GankPingHideUserID')
        local fields = buildFields(playerInfo, hideUserId)
        local payload = game:GetService('HttpService'):JSONEncode({
            username = 'PX Gank Alert',
            content = resolvePingTarget(),
            embeds = {
                {
                    title = 'Gank Ping',
                    color = 0xff3333,
                    fields = fields,
                    footer = {
                        text = 'PX',
                    },
                    timestamp = os.date('!%Y-%m-%dT%H:%M:%SZ'),
                },
            },
        })
        local requestFn = (syn and syn.request) or (http and http.request) or (request) or (http_request)

        if not requestFn then
            return logger.errorNotify('no HTTP function available')
        end

        local successCount, failCount = 0, 0

        for index, webhookUrl in ipairs(webhooks)do
            local ok = pcall(function()
                requestFn({
                    Url = webhookUrl,
                    Method = 'POST',
                    Headers = {
                        ['Content-Type'] = 'application/json',
                    },
                    Body = payload,
                })
            end)

            if ok then
                successCount = successCount + 1
            else
                failCount = failCount + 1
            end
        end

        if successCount > 0 and failCount == 0 then
            logger.successNotify('gank alert sent to %d webhook(s)', successCount)
        elseif successCount > 0 then
            logger.warnNotify('gank alert sent to %d/%d webhooks (%d failed)', successCount, successCount + failCount, failCount)
        else
            logger.errorNotify('gank alert FAILED \u{2014} all %d webhooks errored', failCount)
        end
    end

    return module
end


return aa()

]=],
    ["Features/Game/Interactions"] = [=[
local aa = function()
    local aa = {}
    local logger = a["Utility/Logger"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local ae = function(...)
        logger.warn(...)
    end

    function aa.utool(tool, data)
        aa.etool(tool)
        ae("Activating tool '%s' until ChoicePrompt appears.", tool.Name)

        local playerGui = players.LocalPlayer:WaitForChild('PlayerGui')
        local choicePrompt

        while not choicePrompt do
            tool:Activate()

            choicePrompt = playerGui:FindFirstChild('ChoicePrompt')

            task.wait()
        end

        ae("Firing ChoicePrompt ('%s') with data.", tostring(data))

        local remote = choicePrompt:WaitForChild('Choice')

        remote:FireServer(data)
        ae('Waiting for ChoicePrompt to disappear...')

        repeat
            task.wait()
        until not choicePrompt.Parent

        ae('ChoicePrompt has disappeared.')
    end
    function aa.etool(tool)
        local character = players.LocalPlayer.Character

        if not character then
            return
        end

        local humanoid = character:FindFirstChildOfClass('Humanoid')

        if not humanoid then
            return
        end

        repeat
            humanoid:EquipTool(tool)
            task.wait()
        until tool.Parent == players.LocalPlayer.Character
    end
    function aa.interact(target, actions, teleport)
        if not target or not target.Parent then
            return
        end

        local prompt = target:FindFirstChild('InteractPrompt')

        if not prompt or not prompt:IsA('ProximityPrompt') then
            return
        end

        ae('(%s) Interacting until dialogue appears.', target.Name)

        local playerGui = players.LocalPlayer:WaitForChild('PlayerGui')
        local dialogueGui = playerGui:WaitForChild('DialogueGui')
        local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()

        repeat
            if teleport then
                character:PivotTo(target:GetPivot())
            end

            fireproximityprompt(prompt)
            task.wait()
        until dialogueGui.Enabled

        ae('(%s) Going through dialogue with %i actions.', target.Name, #actions)

        local requests = replicatedStorage:WaitForChild('Requests')
        local remote = requests:WaitForChild('SendDialogue')
        local received = false

        remote.OnClientEvent:Connect(function()
            received = true
        end)

        for index, action in next, actions do
            remote:FireServer(action)

            received = false

            ae(
"(%s) Sent dialogue action '%s' and now waiting for OnClientEvent to fire.", target.Name, action.exit and '[EXIT]' or (action.choice or 'N/A'))

            if action.exit then
                break
            end

            repeat
                task.wait()
            until received
        end

        ae('(%s) Completed dialogue.', target.Name)
    end

    return aa
end


return aa()

]=],
    ["Features/Game/Monitoring"] = [=[
local aa = function()
    local buildStealer = a["Features/Exploits/BuildStealer"]()
    local configuration = a["Utility/Configuration"]()
    local coreGuiManager = a["Utility/CoreGuiManager"]()
    local leaderboardClient = a["Game/LeaderboardClient"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local originalStore = a["Utility/OriginalStore"]()
    local originalStoreManager = a["Utility/OriginalStoreManager"]()
    local signal = a["Utility/Signal"]()
    local taskSpawner = a["Utility/TaskSpawner"]()
    local al = {
        subject = nil,
        seen = {},
    }
    local runService = game:GetService('RunService')
    local players = game:GetService('Players')
    local renderSteppedSignal = signal.new(runService.RenderStepped)
    local ap = maid.new()
    local aq = maid.new()
    local ar = maid.new()
    local as = maid.new()
    local at = maid.new()
    local sound = coreGuiManager.imark(Instance.new('Sound'))
    local av
    local getRequestFunction = function()
        if av ~= nil then
            return av
        end
        if not (writefile and isfile and getcustomasset) then
            av = ''

            return av
        end

        local aw = (syn and syn.request) or http_request or request or (http and http.request)

        if not aw then
            av = ''

            return av
        end
        if not isfile('PalantirX/ProximitySound.wav') then
            if makefolder and isfolder then
                local folderPath = ('PalantirX/ProximitySound.wav'):match('^(.*)/[^/]*$')

                if folderPath and not isfolder(folderPath) then
                    pcall(makefolder, folderPath)
                end
            end

            local requestOk, response = pcall(aw, {
                Url = 'https://files.catbox.moe/2azb83.wav',
                Method = 'GET',
            })

            if not requestOk or type(response) ~= 'table' or type(response.Body) ~= 'string' or #response.Body == 0 then
                av = ''

                return av
            end
            if not pcall(writefile, 'PalantirX/ProximitySound.wav', response.Body) then
                av = ''

                return av
            end
        end

        local loadOk, asset = pcall(getcustomasset, 'PalantirX/ProximitySound.wav')

        av = (loadOk and asset) or ''

        return av
    end
    local screenGui = coreGuiManager.imark(Instance.new('ScreenGui'))

    screenGui.Name = 'ProximityDisplay'
    screenGui.ResetOnSpawn = false
    screenGui.DisplayOrder = 10

    local frame = Instance.new('Frame')

    frame.Name = 'ProximityFrame'
    frame.AnchorPoint = Vector2.new(0.5, 0)
    frame.Position = UDim2.new(0.5, 0, 0, 8)
    frame.Size = UDim2.new(0, 200, 0, 0)
    frame.AutomaticSize = Enum.AutomaticSize.Y
    frame.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
    frame.BackgroundTransparency = 0.3
    frame.BorderSizePixel = 0
    frame.Visible = false
    frame.Parent = screenGui

    local uiCorner = Instance.new('UICorner')

    uiCorner.CornerRadius = UDim.new(0, 6)
    uiCorner.Parent = frame

    local uiPadding = Instance.new('UIPadding')

    uiPadding.PaddingTop = UDim.new(0, 5)
    uiPadding.PaddingBottom = UDim.new(0, 5)
    uiPadding.PaddingLeft = UDim.new(0, 8)
    uiPadding.PaddingRight = UDim.new(0, 8)
    uiPadding.Parent = frame

    local uiListLayout = Instance.new('UIListLayout')

    uiListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    uiListLayout.Padding = UDim.new(0, 2)
    uiListLayout.Parent = frame

    do
        local userInput = game:GetService('UserInputService')
        local isDragging = false
        local dragStartPos, frameOrigin

        frame.Active = true

        frame.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDragging = true
                dragStartPos = input.Position
                frameOrigin = frame.Position

                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        isDragging = false
                    end
                end)
            end
        end)
        userInput.InputChanged:Connect(function(dragInput)
            if not isDragging then
                return
            end
            if dragInput.UserInputType ~= Enum.UserInputType.MouseMovement and dragInput.UserInputType ~= Enum.UserInputType.Touch then
                return
            end

            local delta = dragInput.Position - dragStartPos

            frame.Position = UDim2.new(frameOrigin.X.Scale, frameOrigin.X.Offset + delta.X, frameOrigin.Y.Scale, frameOrigin.Y.Offset + delta.Y)
        end)
    end

    local aC = {}
    local startTime = os.clock()
    local aF = 0
    local storeInstance = aq:mark(originalStore.new())
    local storeManagerInstance = aq:mark(originalStoreManager.new())
    local getLabel = function(index)
        if aC[index] then
            return aC[index]
        end

        local label = Instance.new('TextLabel')

        label.BackgroundTransparency = 1
        label.Font = Enum.Font.GothamMedium
        label.TextSize = 12
        label.TextColor3 = Color3.fromRGB(230, 230, 230)
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.Size = UDim2.new(1, 0, 0, 16)
        label.LayoutOrder = index
        label.Parent = frame
        aC[index] = label

        return label
    end
    local formatMemberName = function(member)
        return string.format('(%s) %s', member:GetAttribute('CharacterName') or 'Unknown Character Name', member.Name)
    end
    local formatPlayerName = function(player)
        local characterName = player:GetAttribute('CharacterName') or player.DisplayName

        return string.format('%s [%s]', characterName, player.Name)
    end
    local onSpectateClick = function(player, input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
            return
        end

        local playerName = formatMemberName(player)
        local localPlayer = players.LocalPlayer

        if not localPlayer then
            return logger.notify(
"Failed to spectate '%s' because the local player does not exist.", playerName)
        end

        local character = player.Character

        if not character then
            return logger.notify(
"Failed to spectate '%s' because their character does not exist.", playerName)
        end

        local mapPos = character:GetAttribute('MapPos')
        local humanoidRoot = character:FindFirstChild('HumanoidRootPart')

        if mapPos and not humanoidRoot then
            aq:add(taskSpawner.spawn('Monitoring_RequestStreamMapPos', localPlayer.RequestStreamAroundAsync, localPlayer, mapPos, 0.1))

            return logger.notify(
"Requesting stream for unloaded character '%s' - try again later.", playerName)
        end
        if not humanoidRoot then
            return logger.notify("Failed to spectate '%s' because they are not loaded in.", playerName)
        end

        local shouldSpectate = al.subject ~= humanoidRoot and localPlayer ~= player

        al.subject = shouldSpectate and humanoidRoot or nil

        if shouldSpectate then
            logger.notify('Started spectating player %s.', playerName)
        else
            logger.notify('Reset spectating camera subject.')
        end
    end
    local setupBuildStealer = function()
        local playersList = leaderboardClient.gld()

        if not playersList then
            return storeInstance:restore()
        end

        for player, guis in next, playersList do
            if ar[guis] then
                continue
            end

            local stealSignal = signal.new(guis.InputBegan)

            ar[guis] = stealSignal:connect('Monitoring_InputBegan_Steal_' .. player.Name, function(
                stealInput
            )
                if stealInput.KeyCode ~= Enum.KeyCode.P then
                    return
                end

                buildStealer.stealPlayer(player, true)
            end)
        end
    end
    local fetchLivePlayerData = function(player)
        local liveFolder = workspace:FindFirstChild('Live') or workspace:FindFirstChild('live')

        if not liveFolder then
            return logger.errorNotify('live folder not found')
        end

        local playerData = liveFolder:FindFirstChild(player.Name)

        if not playerData then
            return logger.errorNotify("no data found for '%s'", player.Name)
        end

        local hairIds = {}

        for childIndex, child in next, playerData:GetChildren()do
            if child.Name:match('Asset') then
                local id = child.Name:match('%d+')

                if id then
                    table.insert(hairIds, id)
                end
            end
        end

        if #hairIds > 0 then
            local message = 'Hair IDs for ' .. player.Name .. ':\n'

            for index, hairId in next, hairIds do
                message = message .. hairId .. '\n'
            end

            message = message .. 'Total: ' .. #hairIds

            setclipboard(message)
            logger.successNotify("copied %d hair IDs from '%s'", #hairIds, formatMemberName(player))
        else
            logger.errorNotify("no hair IDs found for '%s'", formatMemberName(player))
        end
    end
    local setupHairStealer = function()
        local playersList = leaderboardClient.gld()

        if not playersList then
            return
        end

        for player, guis in next, playersList do
            if as[guis] then
                continue
            end

            local hairSignal = signal.new(guis.InputBegan)

            as[guis] = hairSignal:connect('Monitoring_InputBegan_Hair_' .. player.Name, function(
                hairInput
            )
                if hairInput.KeyCode ~= Enum.KeyCode.H then
                    return
                end

                fetchLivePlayerData(player)
            end)
        end
    end
    local updatePlayerVisibility = function()
        local playersList = leaderboardClient.gld()

        if not playersList then
            return storeInstance:restore()
        end

        local showHidden = configuration.expectToggleValue('ShowHiddenPlayers')

        for player, guis in next, playersList do
            if showHidden then
                storeManagerInstance:add(guis, 'Visible', true)
            end
            if aq[guis] then
                continue
            end

            local monitorSignal = signal.new(guis.InputBegan)

            aq[guis] = monitorSignal:connect('Monitoring_InputBegan' .. player.Name, function(
                monitorInput
            )
                onSpectateClick(player, monitorInput)
            end)
        end
    end
    local updatePlayerProximity = function()
        if not configuration.expectToggleValue('PlayerProximity') then
            frame.Visible = false
            al.seen = {}

            return
        end

        local proximityRange = configuration.expectOptionValue('PlayerProximityRange') or 350
        local localPlayer = players.LocalPlayer

        if not localPlayer then
            frame.Visible = false

            return
        end

        local character = localPlayer.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')

        if not root then
            frame.Visible = false

            return
        end

        local backpack = localPlayer:FindFirstChild('Backpack')

        if not backpack then
            frame.Visible = false

            return
        end

        local vwFilter = configuration.expectToggleValue('PlayerProximityVW') and not backpack:FindFirstChild('Talent:Voideye')
        local nearbyPlayers = {}
        local currentPlayers = {}
        local distances = {}

        for firstIndex, candidatePlayer in next, players:GetPlayers()do
            if candidatePlayer == localPlayer then
                continue
            end

            local candidateCharacter = candidatePlayer.Character
            local candidateRoot = candidateCharacter and candidateCharacter:FindFirstChild('HumanoidRootPart')

            if not candidateRoot then
                continue
            end

            local candidateDistance = (candidateRoot.Position - root.Position).Magnitude

            if candidateDistance > proximityRange then
                continue
            end
            if vwFilter then
                continue
            end

            nearbyPlayers[#nearbyPlayers + 1] = candidatePlayer
            currentPlayers[candidatePlayer] = true
            distances[candidatePlayer] = candidateDistance
        end

        table.sort(nearbyPlayers, function(leftPlayer, rightPlayer)
            return distances[leftPlayer] < distances[rightPlayer]
        end)

        for alertIndex, enteringPlayer in next, nearbyPlayers do
            if al.seen[enteringPlayer] then
                continue
            end

            al.seen[enteringPlayer] = true

            logger.notify('%s has entered your proximity range.', formatPlayerName(enteringPlayer))

            if configuration.expectToggleValue('PlayerProximityBeep') then
                local beepSoundId = getRequestFunction()

                if beepSoundId and beepSoundId ~= '' then
                    sound.SoundId = beepSoundId
                    sound.PlaybackSpeed = 1
                    sound.Volume = configuration.expectOptionValue('PlayerProximityBeepVolume') or 0.1

                    sound:Play()
                end
            end
        end

        al.seenVoidwalkers = al.seenVoidwalkers or {}

        if configuration.expectToggleValue('NotifyVoidWalker') then
            for vwIndex, vwPlayer in next, nearbyPlayers do
                if al.seenVoidwalkers[vwPlayer] then
                    continue
                end

                local vwBackpack = vwPlayer:FindFirstChild('Backpack')

                if vwBackpack and vwBackpack:FindFirstChild('Talent:Voideye') then
                    al.seenVoidwalkers[vwPlayer] = true

                    logger.longNotify('%s has the Voideye talent.', formatMemberName(vwPlayer))
                end
            end
        end

        for seenPlayer in next, al.seen do
            if not currentPlayers[seenPlayer] then
                logger.notify('%s has left your proximity range.', formatPlayerName(seenPlayer))

                al.seen[seenPlayer] = nil
            end
        end
        for vwSeenPlayer in next, al.seenVoidwalkers do
            if not currentPlayers[vwSeenPlayer] then
                al.seenVoidwalkers[vwSeenPlayer] = nil
            end
        end

        local showTable = configuration.expectToggleValue('ShowProximityTable')

        frame.Visible = showTable and #nearbyPlayers > 0

        for rowIndex, rowPlayer in next, nearbyPlayers do
            local rowLabel = getLabel(rowIndex)
            local nameType = configuration.expectOptionValue('ProximityNameType')
            local displayName

            if nameType == 'Username' then
                displayName = rowPlayer.Name
            elseif nameType == 'Display Name' then
                displayName = rowPlayer.DisplayName
            else
                displayName = rowPlayer:GetAttribute('CharacterName') or rowPlayer.Name
            end

            local rowDistance = math.floor(distances[rowPlayer])

            rowLabel.Text = string.format('%s  \u{2014}  %d studs', displayName, rowDistance)

            local rowBackpack = rowPlayer:FindFirstChild('Backpack')

            if rowBackpack and rowBackpack:FindFirstChild('Talent:Voideye') then
                rowLabel.TextColor3 = Color3.fromRGB(255, 70, 70)
            else
                rowLabel.TextColor3 = Color3.fromRGB(230, 230, 230)
            end

            rowLabel.Visible = true
            rowLabel.LayoutOrder = rowIndex
        end

        for hideIndex = #nearbyPlayers + 1, #aC do
            aC[hideIndex].Visible = false
        end
    end
    local loadStreamedCharacter = function()
        if not workspace.StreamingEnabled then
            return
        end

        local player = players.LocalPlayer

        if not player then
            return
        end

        local character = player.Character
        local rootPart = character and character:FindFirstChild('HumanoidRootPart')

        if not rootPart then
            return
        end

        aq:add(taskSpawner.spawn('Monitoring_RefocusStreamLocal', player.RequestStreamAroundAsync, player, rootPart.Position, 0.1))
    end

    al.refocusStreamingToLocal = loadStreamedCharacter

    local aV = 0
    local aX = false
    local applyCameraSubject = function()
        storeInstance:set(workspace.CurrentCamera, 'CameraSubject', al.subject)

        if al.subject ~= nil then
            players.LocalPlayer:AddTag('ForcedSubject')
        else
            players.LocalPlayer:RemoveTag('ForcedSubject')
        end
        if not workspace.StreamingEnabled then
            return
        end

        local now = os.clock()

        if now - aV < 1 then
            return
        end

        aV = now

        aq:add(taskSpawner.spawn('Monitoring_RequestStreamSpectate', players.LocalPlayer.RequestStreamAroundAsync, players.LocalPlayer, al.subject.Position, 0.1))
    end
    local aZ = 0
    local a_ = false
    local onUpdate = function()
        local frameStart = os.clock()
        local startClock = frameStart

        if startClock - aZ > 0.5 then
            aZ = startClock
            a_ = al.subject or configuration.expectToggleValue('PlayerProximity') or configuration.expectToggleValue('BuildStealer') or configuration.expectToggleValue('HairStealer') or configuration.expectToggleValue('PlayerSpectating')
        end
        if not a_ and not al.subject then
            return
        end
        if al.subject then
            applyCameraSubject()

            aX = true
        else
            if aX then
                aX = false

                loadStreamedCharacter()
            end

            storeInstance:restore()
        end
        if os.clock() - aF >= 0.1 then
            aF = os.clock()

            updatePlayerProximity()
        end
        if os.clock() - startTime <= 2 then
            return
        end

        startTime = os.clock()

        at:clean()

        if configuration.expectToggleValue('BuildStealer') then
            setupBuildStealer()
        else
            ar:clean()
        end
        if configuration.expectToggleValue('HairStealer') then
            setupHairStealer()
        else
            as:clean()
        end
        if configuration.expectToggleValue('PlayerSpectating') then
            updatePlayerVisibility()
        else
            aq:clean()
        end

        local perf = shared.Palantir_Perf or {}

        shared.Palantir_Perf = perf
        perf.monitoring = (os.clock() - frameStart) * 1000

        local perfCount = shared.Palantir_PerfCount or {}

        shared.Palantir_PerfCount = perfCount
        perfCount.monitoring = (perfCount.monitoring or 0) + 1
    end

    function al.init()
        ap:add(renderSteppedSignal:connect('Monitoring_OnRenderStepped', onUpdate))
        logger.warn('Monitoring \u{2014} ready.')
    end
    function al.detach()
        ap:clean()
        ar:clean()
        as:clean()
        aq:clean()
        at:clean()
        storeManagerInstance:restore()

        frame.Visible = false
        al.seen = {}

        local release = leaderboardClient.glrf()

        if release then
            release()
        end

        logger.warn('Monitoring \u{2014} detached.')
    end

    return al
end


return aa()

]=],
    ["Features/Game/Movement"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local feature = a["Features/Feature"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local userInputService = game:GetService('UserInputService')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local farVector = Vector3.new(10000000000, 10000000000, 10000000000)
    local farGround = Vector3.new(10000000000, 0, 10000000000)
    local ai
    local aj
    local al = false
    local getCollisionUtils = function()
        if al then
            return aj
        end

        al = true

        pcall(function()
            local modulesFolder = replicatedStorage:FindFirstChild('Modules')
            local collisionUtils = modulesFolder and modulesFolder:FindFirstChild('CollisionUtils')

            if collisionUtils then
                aj = require(collisionUtils)
            end
        end)

        return aj
    end
    local an
    local getEffectReplicator = function()
        if an then
            return an
        end

        local effectReplicatorInstance = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicatorInstance then
            return nil
        end

        local okRequire, effectReplicatorModule = pcall(require, effectReplicatorInstance)

        if okRequire then
            an = effectReplicatorModule
        end

        return an
    end
    local hasEffect = function(effect)
        local effectReplicator = getEffectReplicator()

        if not effectReplicator or type(effectReplicator.HasEffect) ~= 'function' then
            return false
        end

        local okCall, hasResult = pcall(effectReplicator.HasEffect, effectReplicator, effect)

        return okCall and hasResult or false
    end
    local hasAutomationMovement = function()
        local okPcall, pcallResult = pcall(function()
            return a["Features/Automation/KaidoFarm2"]().hasAny()
        end)

        if okPcall and pcallResult then
            return true
        end

        return a["Features/Game/NoEffects"]().automation.movement ~= nil
    end
    local createRollCancelBody = function(part)
        if ai and ai.Parent == part then
            return ai
        end
        if ai then
            ai:Destroy()
        end

        local bodyVelocity = Instance.new('BodyVelocity')

        bodyVelocity:AddTag('AllowedBM')

        bodyVelocity.Name = 'RollCancel2'
        bodyVelocity.P = 20000
        bodyVelocity.MaxForce = farVector
        bodyVelocity.Parent = part
        ai = bodyVelocity

        return bodyVelocity
    end
    local removeRollCancel = function()
        if ai then
            ai:Destroy()

            ai = nil
        end
    end
    local clearBodyVelocities = function(container)
        for childIndex, child in ipairs(container:GetChildren())do
            if not child:IsA('BasePart') then
                continue
            end

            for grandIndex, grandChild in ipairs(child:GetChildren())do
                if grandChild:IsA('BodyVelocity') and grandChild ~= ai then
                    grandChild:Destroy()
                end
            end
        end
    end
    local au
    local av
    local storeSensorState = function(sensor)
        if not sensor or (av and av.sensor == sensor) then
            return
        end

        av = {
            sensor = sensor,
            mode = sensor.SensorMode,
            update = sensor.UpdateType,
        }
    end
    local configureLadderSensor = function(ladderSensor, ladderMode)
        if not ladderSensor then
            return
        end

        storeSensorState(ladderSensor)

        if ladderMode then
            ladderSensor.SensorMode = Enum.SensorMode.ClassicLadder
            ladderSensor.UpdateType = Enum.SensorUpdateType.OnRead
        else
            ladderSensor.SensorMode = Enum.SensorMode.Floor
            ladderSensor.UpdateType = Enum.SensorUpdateType.Manual
        end
    end
    local restoreGroundSensor = function()
        local savedState = av

        av = nil

        local groundSensor = savedState and savedState.sensor

        if not groundSensor or not groundSensor.Parent then
            local character = players.LocalPlayer and players.LocalPlayer.Character
            local root = character and character:FindFirstChild('HumanoidRootPart')

            groundSensor = root and root:FindFirstChild('GroundSensor')

            if not groundSensor then
                return
            end

            pcall(function()
                groundSensor.SensorMode = Enum.SensorMode.Floor
                groundSensor.UpdateType = Enum.SensorUpdateType.Manual
            end)

            return
        end

        pcall(function()
            groundSensor.SensorMode = savedState.mode
            groundSensor.UpdateType = savedState.update
        end)
    end
    local syncController = function()
        local character = players.LocalPlayer and players.LocalPlayer.Character
        local controllerManager = character and character:FindFirstChild('ControllerManager')

        if not controllerManager then
            au = nil

            return
        end

        local controller = au

        if not controller or controller.Parent ~= controllerManager then
            controller = controllerManager:FindFirstChild('GroundController')
        end
        if controller then
            pcall(function()
                controllerManager.ActiveController = controller
            end)
        end

        au = nil

        local rootPart = character:FindFirstChild('HumanoidRootPart')

        if rootPart then
            pcall(function()
                rootPart.AssemblyLinearVelocity = Vector3.zero
            end)
        end
    end
    local flightFeature = feature.new('Flight', runService.PreSimulation, function()
        local character = players.LocalPlayer and players.LocalPlayer.Character

        if not character then
            return
        end

        local rootPart = character:FindFirstChild('HumanoidRootPart')

        if not rootPart then
            return
        end

        local humanoid = character:FindFirstChild('Humanoid')

        if not humanoid then
            return
        end
        if a["Features/Game/NoEffects"]().automation.movement then
            rootPart.AssemblyLinearVelocity = Vector3.zero

            local bodyVelocity = createRollCancelBody(rootPart)

            bodyVelocity.Velocity = Vector3.zero
            bodyVelocity.MaxForce = farVector

            return
        end

        local controllerManager = character:FindFirstChild('ControllerManager')

        if not controllerManager then
            return
        end

        local airController = controllerManager:FindFirstChild('AirController')

        if not airController then
            return
        end

        local camera = workspace.CurrentCamera

        if not camera then
            return
        end

        local forward = camera.CFrame.LookVector.Unit
        local moveVector = Vector3.zero
        local verticalInput = 0

        if userInputService:IsKeyDown(Enum.KeyCode.Space) then
            verticalInput = 1
        elseif userInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
            verticalInput = -1
        end
        if humanoid.MoveDirection.Magnitude > 0.001 then
            if userInputService:IsKeyDown(Enum.KeyCode.W) then
                moveVector = moveVector + forward
            end
            if userInputService:IsKeyDown(Enum.KeyCode.S) then
                moveVector = moveVector - forward
            end
            if userInputService:IsKeyDown(Enum.KeyCode.D) then
                moveVector = moveVector + Vector3.new(-forward.Z, 0, forward.X)
            end
            if userInputService:IsKeyDown(Enum.KeyCode.A) then
                moveVector = moveVector + Vector3.new(forward.Z, 0, -forward.X)
            end
        end

        clearBodyVelocities(character)

        local flightSpeed = configuration.expectOptionValue('FlightSpeed') or 0
        local torso = character:FindFirstChild('Torso')

        if flightSpeed > 500 and torso and not torso:FindFirstChild('Bone') then
            flightSpeed = 5000
        end

        local rootAttachment = rootPart:FindFirstChild('RootAttachment')
        local alignPosition = rootAttachment and rootAttachment:FindFirstChild('AlignPosition')

        if alignPosition then
            if not hasAutomationMovement() then
                alignPosition.Attachment0 = nil
                alignPosition.Attachment1 = nil
            end

            flightSpeed = math.min(160, flightSpeed)

            pcall(function()
                a["Features/Game/TravelRecovery"]().registerLagback()
            end)
        end
        if configuration.expectToggleValue('FlightSafeSpeedCap') then
            flightSpeed = math.min(hasEffect('Knocked') and 350 or 250, flightSpeed)
        end

        local upSpeed = configuration.expectOptionValue('FlightUpSpeed') or flightSpeed
        local isSwimming = hasEffect('Swimming')
        local noClip = configuration.expectToggleValue('NoClip') == true

        if verticalInput == 0 and configuration.expectToggleValue('FlightPullToGround') and not noClip and not isSwimming then
            local raycaster = getCollisionUtils()

            if raycaster and type(raycaster.Raycast) == 'function' then
                local success, nearHit, farHit = pcall(function()
                    return raycaster:Raycast(rootPart.Position, Vector3.new(0, -7.5, 0), raycaster.solidParams), raycaster:Raycast(rootPart.Position, Vector3.new(0, 
-25, 0), raycaster.solidParams)
                end)

                if success then
                    verticalInput = nearHit and -1 or (farHit and -0.75 or -0.3)
                    upSpeed = flightSpeed
                end
            end
        end

        local hasVelocity = moveVector.Magnitude > 0

        if hasVelocity then
            moveVector = moveVector.Unit * flightSpeed
        end
        if verticalInput ~= 0 then
            moveVector = moveVector + Vector3.new(0, verticalInput * upSpeed, 0)
            hasVelocity = true
        end

        local headBodyPosition = character:FindFirstChild('Head') and character.Head:FindFirstChild('BodyPosition')

        if headBodyPosition then
            rootPart.CFrame = CFrame.new(headBodyPosition.Position, Vector3.zero)

            headBodyPosition:Destroy()
        end

        local onGround = humanoid.FloorMaterial ~= Enum.Material.Air
        local ignoreGround = false
        local maxForce = farVector

        if configuration.expectToggleValue('FlightIgnoreGround') and onGround and not isSwimming and not noClip then
            maxForce = farGround
            ignoreGround = true
        end
        if hasVelocity then
            rootPart.Velocity = moveVector
            rootPart.AssemblyLinearVelocity = moveVector
        else
            local linearVel = rootPart.AssemblyLinearVelocity

            if linearVel.Y ~= 0 then
                rootPart.AssemblyLinearVelocity = Vector3.new(linearVel.X, 0, linearVel.Z)
            end
        end

        local velocityBody = createRollCancelBody(rootPart)

        velocityBody.Velocity = moveVector
        velocityBody.MaxForce = maxForce

        local groundController = controllerManager:FindFirstChild('GroundController')
        local targetController = (ignoreGround and groundController) or airController

        if controllerManager.ActiveController ~= targetController then
            if controllerManager.ActiveController ~= airController and controllerManager.ActiveController ~= groundController then
                au = controllerManager.ActiveController
            end

            controllerManager.ActiveController = targetController
        end

        configureLadderSensor(rootPart:FindFirstChild('GroundSensor'), noClip and not ignoreGround)
    end)

    function flightFeature:onEnable()
        local overrides = getEffectReplicator()

        if overrides and type(overrides.CreateEffect) == 'function' then
            pcall(overrides.CreateEffect, overrides, 'OverrideSpeedCap')
        end
    end
    function flightFeature:onDisable()
        removeRollCancel()
        restoreGroundSensor()
        syncController()

        local overrides = getEffectReplicator()

        if overrides and type(overrides.FindEffect) == 'function' then
            pcall(function()
                local overrideSpeedEffect = overrides:FindEffect('OverrideSpeedCap')

                if overrideSpeedEffect and type(overrideSpeedEffect.Debris) == 'function' then
                    overrideSpeedEffect:Debris(1)
                end
            end)
        end
    end

    return flightFeature
end


return aa()

]=],
    ["Features/Game/NoClip"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local feature = a["Features/Feature"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')
    local methods = {}
    local ag = {}
    local ah
    local getEffectReplicator = function()
        if ah then
            return ah
        end

        local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local ok, effectModule = pcall(require, effectReplicator)

        if ok then
            ah = effectModule
        end

        return ah
    end

    function methods.step()
        local character = players.LocalPlayer and players.LocalPlayer.Character

        if not character then
            return
        end
        if configuration.expectToggleValue('NoClipCollisionsKnocked') then
            local effectModule = getEffectReplicator()

            if effectModule and effectModule:HasEffect('Knocked') then
                methods.restore()

                return
            end
        end

        for index, child in ipairs(character:GetChildren())do
            if child:IsA('BasePart') and child.CanCollide then
                child.CanCollide = false

                if not table.find(ag, child) then
                    table.insert(ag, child)
                end
            end
        end
    end
    function methods.restore()
        for index, part in ipairs(ag)do
            if part and part.Parent then
                part.CanCollide = true
            end
        end

        table.clear(ag)
    end

    local noclip = feature.new('NoClip', runService.PreSimulation, methods.step)

    function noclip:onEnable()
        local hooking = a["Game/Hooking"]()

        if hooking.updateNoClipHasAnyHook then
            pcall(hooking.updateNoClipHasAnyHook, true)
        end
    end
    function noclip:onDisable()
        methods.restore()

        local hooking = a["Game/Hooking"]()

        if hooking.updateNoClipHasAnyHook then
            pcall(hooking.updateNoClipHasAnyHook, false)
        end
    end

    methods.feature = noclip

    return methods
end


return aa()

]=],
    ["Features/Game/NoEffects"] = [=[
local aa = function()
    local logger = a["Utility/Logger"]()
    local persistentData = a["Utility/PersistentData"]()
    local serverHop = a["Game/ServerHop"]()
    local quickToggles = a["Features/Game/QuickToggles"]()
    local ae = {}

    ae.services = setmetatable({}, {
        __index = function(af, serviceName)
            local success, service = pcall(game.GetService, game, serviceName)

            if not success or not service then
                return nil
            end

            rawset(af, serviceName, service)

            return service
        end,
    })

    local players = ae.services.Players

    ae.localPlayer = setmetatable({}, {
        __index = function(ag, key)
            local player = players.LocalPlayer

            if key == 'instance' then
                return player
            end

            local character = player and player.Character

            if key == 'character' then
                return character
            end
            if not character then
                return nil
            end
            if key == 'root_part' then
                return character:FindFirstChild('HumanoidRootPart')
            end
            if key == 'humanoid' then
                return character:FindFirstChildOfClass('Humanoid')
            end

            return nil
        end,
    })
    ae.automation = {}
    quickToggles.agilityReady = function()
        return ae.automation.movement == nil
    end

    function ae.flag(flagKey, defaultValue)
        local autoData = persistentData.get('auto')
        local value = autoData and autoData[flagKey]

        if value == nil then
            return defaultValue
        end

        return value
    end
    function ae.setFlag(flagKey, value)
        ae.setValue(flagKey, value and true or false)
    end
    function ae.setValue(ag, ah)
        if type(persistentData.get('auto')) ~= 'table' then
            persistentData.set('auto', {})
        end

        persistentData.stf('auto', ag, ah)
    end
    function ae.value(key, defaultValue)
        local autoData = persistentData.get('auto')
        local value = autoData and autoData[key]

        if value == nil then
            return defaultValue
        end

        return value
    end

    local ag = {
        Jesus = 'setJesus',
        NoFire = 'setNoFire',
        AutoTrainAgility = 'setTrainAgility',
        AutoDeclineGuild = 'setDeclineGuild',
        AutoDeclineSquad = 'setDeclineSquad',
    }
    local ah = {
        NoFallDamage = {
            option = 'EffectRemovalList',
            value = 'No Fall Damage',
        },
        NoFireRemoval = {
            option = 'EffectRemovalList',
            value = 'No Fire',
        },
        NoAcidWater = {
            option = 'EffectRemovalList',
            value = 'No Acid Water',
        },
        NoWind = {
            option = 'EffectRemovalList',
            value = 'No Wind',
        },
        NoSpeedDebuff = {
            option = 'EffectRemovalList',
            value = 'No Speed Debuff',
        },
        NoAttackingClientChecks = {
            option = 'EffectRemovalList',
            value = 'No Attacking Client Checks',
        },
    }
    local ai = function(config)
        if not Options then
            return false
        end

        local option = Options[config.option]

        if not option then
            return false
        end

        local list = {}

        for index, item in next, option.Value or {}do
            list[index] = item
        end

        if list[config.value] == true then
            return true
        end

        list[config.value] = true

        local success = pcall(function()
            option:SetValue(list)
        end)

        return success
    end

    function ae.featureActive(feature)
        local config = ah[feature]

        if config then
            local option = Options and Options[config.option]

            return (option and option.Value and option.Value[config.value]) == true
        end
        if ag[feature] then
            return quickToggles.active(feature)
        end

        local toggle = Toggles and Toggles[feature]

        return (toggle and toggle.Value) == true
    end
    function ae.enableFeature(featureId)
        local featureObj = ah[featureId]

        if featureObj then
            return ai(featureObj)
        end

        local quickToggleId = ag[featureId]

        if quickToggleId then
            if quickToggles[quickToggleId] then
                quickToggles[quickToggleId](true)

                return true
            end

            return false
        end
        if not Toggles then
            return false
        end

        local toggle = Toggles[featureId]

        if not toggle then
            return false
        end
        if toggle.Value == true then
            return true
        end

        local success = pcall(function()
            if type(toggle.SetValue) == 'function' then
                toggle:SetValue(true)
            else
                toggle.Value = true
            end
        end)

        return success
    end
    function ae.disableFeature(featureId)
        if not Toggles then
            return false
        end

        local toggle = Toggles[featureId]

        if not toggle or toggle.Value ~= true then
            return true
        end

        return pcall(function()
            toggle:SetValue(false)
        end)
    end
    function ae.setFeature(featureId, enabled)
        if enabled then
            return ae.enableFeature(featureId)
        end
        if ag[featureId] then
            return quickToggles[ag[featureId] ](false)
        end
        if ah[featureId] then
            local option = Options and Options[ah[featureId].option]

            if option then
                local clonedValues = table.clone(option.Value)

                clonedValues[ah[featureId].value] = nil

                option:SetValue(clonedValues)
            end

            return
        end

        return ae.disableFeature(featureId)
    end
    function ae.notify(...)
        return logger.notify(...)
    end
    function ae.warn(...)
        return logger.warn(...)
    end
    function ae.hop(serverName, isEnabled)
        return serverHop.hop(serverName or 'A', isEnabled and true or false)
    end

    ae.isRegular = false
    ae.builder = {
        build_config = nil,
        missing_for = function()
            return 0
        end,
    }

    return ae
end


return aa()

]=],
    ["Features/Game/NoFall"] = [=[
local aa = function()
    local module = {}
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local ae
    local getEffectReplicator = function()
        if ae then
            return ae
        end

        local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local requireSuccess, replicatorModule = pcall(require, effectReplicator)

        if requireSuccess then
            ae = replicatorModule
        end

        return ae
    end
    local isNoFallRemovalEnabled = function()
        local optionSuccess, removalList = pcall(configuration.expectOptionValue, 'EffectRemovalList')

        return optionSuccess and type(removalList) == 'table' and removalList['No Fall Damage'] == true
    end
    local ah = false
    local ai = 0

    module.debug = false

    local logThrottledWarning = function(message, ...)
        if not module.debug then
            return
        end
        if os.clock() - ai < 2 then
            return
        end

        ai = os.clock()

        logger.warn('[NFD] ' .. message, ...)
    end

    function module.start()
        if ah then
            return
        end

        ah = true

        task.spawn(function()
            while true do
                local effectReplicator = getEffectReplicator()
                local removalEnabled = isNoFallRemovalEnabled()

                if not effectReplicator then
                    logThrottledWarning('no EffectReplicator module yet')
                elseif not removalEnabled then
                    local findSuccess, noFallEffect = pcall(function()
                        return effectReplicator:FindEffect('NoFall')
                    end)

                    if findSuccess and noFallEffect then
                        pcall(function()
                            noFallEffect:Debris(0.1)
                        end)
                    end
                else
                    local checkSuccess, keptEffect = pcall(function()
                        return effectReplicator:FindEffect('NoFall')
                    end)

                    if checkSuccess and keptEffect then
                        logThrottledWarning('NoFall effect PRESENT (kept alive)')
                    else
                        local createSuccess, createError = pcall(function()
                            effectReplicator:CreateEffect('NoFall')
                        end)
                        local searchSuccess, effectAfterCreate = pcall(function()
                            return effectReplicator:FindEffect('NoFall')
                        end)

                        logThrottledWarning('wanted=1 CreateEffect ok=%s err=%s | FindEffect-after=%s', tostring(createSuccess), tostring(createError), tostring(searchSuccess and effectAfterCreate ~= nil))
                    end
                end

                task.wait(0.1)
            end
        end)
    end

    return module
end


return aa()

]=],
    ["Features/Game/Optimizations"] = [=[
local aa = function()
    local optimizations = {}
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local seaOptimizer = a["Features/Game/SeaOptimizer"]()
    local signal = a["Utility/Signal"]()
    local runService = game:GetService('RunService')
    local players = game:GetService('Players')

    game:GetService('CollectionService')

    local ai = maid.new()
    local settings = {
        hiddenNPCs = {},
        disabledClouds = {},
        disabledAdorns = {},
        disabledParticles = {},
        mutedSounds = {},
        savedSoundServiceVolume = nil,
        soundEnforceConn = nil,
        disabledCastShadows = {},
        savedPhysicsStepping = nil,
        savedInterpolation = nil,
        overriddenMaterials = {},
        trueBoostConn = nil,
        trueBoostSaved = nil,
        originalLowGraphics = nil,
        lowGraphicsApplied = false,
        statsThrottleHook = nil,
        statsThrottleLast = 0,
    }
    local getOptimizationOption = function(optionKey)
        if not configuration.expectToggleValue('OptimizeGame') then
            return false
        end

        local options = configuration.expectOptionValue('OptimizeGameOptions')

        return options and options[optionKey]
    end
    local disableClouds = function()
        local terrain = workspace:FindFirstChildOfClass('Terrain')

        if terrain then
            for cloudIndex, cloud in next, terrain:GetChildren()do
                if cloud:IsA('Clouds') then
                    if settings.disabledClouds[cloud] == nil then
                        settings.disabledClouds[cloud] = cloud.Enabled
                    end

                    cloud.Enabled = false
                end
            end
        end
    end
    local restoreClouds = function()
        for cloudObj, cloudEnabled in next, settings.disabledClouds do
            if cloudObj and cloudObj.Parent then
                cloudObj.Enabled = cloudEnabled
            end
        end

        settings.disabledClouds = {}
    end
    local disableCloudAdorns = function()
        local thrown = workspace:FindFirstChild('Thrown')

        if not thrown then
            return
        end

        for thrownIndex, adorn in next, thrown:GetChildren()do
            if adorn:IsA('ImageHandleAdornment') and adorn.Name == 'CloudAdorn' then
                if settings.disabledAdorns[adorn] == nil then
                    settings.disabledAdorns[adorn] = adorn.Transparency
                end

                adorn.Transparency = 1

                for adornIndex, childAdorn in next, adorn:GetChildren()do
                    if childAdorn:IsA('ImageHandleAdornment') then
                        if settings.disabledAdorns[childAdorn] == nil then
                            settings.disabledAdorns[childAdorn] = childAdorn.Transparency
                        end

                        childAdorn.Transparency = 1
                    end
                end
            end
        end
    end
    local restoreCloudAdorns = function()
        for adornObj, adornTransparency in next, settings.disabledAdorns do
            if adornObj and adornObj.Parent then
                adornObj.Transparency = adornTransparency
            end
        end

        settings.disabledAdorns = {}
    end
    local hidePart = function(part)
        if not part:IsA('BasePart') then
            return
        end

        pcall(function()
            part.Transparency = 1
        end)
        pcall(function()
            part.CanCollide = false
        end)
        pcall(function()
            part.CanQuery = false
        end)
        pcall(function()
            part.CanTouch = false
        end)
    end
    local hideShipDetails = function()
        local ships = workspace:FindFirstChild('Ships')

        if not ships then
            return
        end

        for shipIndex, ship in next, ships:GetChildren()do
            for detailIndex, detail in next, ship:GetChildren()do
                if detail.Name == 'ClientDetail' then
                    hidePart(detail)
                end
            end
        end
    end
    local as = function()
        local character = players.LocalPlayer and players.LocalPlayer.Character

        if not character then
            return
        end

        local root = character:FindFirstChild('HumanoidRootPart')

        if not root then
            return
        end

        local rootPosition = root.Position
        local hideRange = configuration.expectOptionValue('NPCHideRange') or 200
        local npcs = workspace:FindFirstChild('NPCs')

        if not npcs then
            return
        end

        for npcIndex, npc in next, npcs:GetChildren()do
            if not npc:IsA('Model') then
                continue
            end

            local npcRoot = npc:FindFirstChild('HumanoidRootPart') or npc.PrimaryPart

            if not npcRoot then
                continue
            end

            local distance = (npcRoot.Position - rootPosition).Magnitude

            if distance > hideRange then
                if not settings.hiddenNPCs[npc] then
                    settings.hiddenNPCs[npc] = npc.LevelOfDetail
                    npc.LevelOfDetail = Enum.ModelLevelOfDetail.StreamingMesh
                end
            else
                if settings.hiddenNPCs[npc] then
                    npc.LevelOfDetail = settings.hiddenNPCs[npc]
                    settings.hiddenNPCs[npc] = nil
                end
            end
        end
    end
    local restoreHiddenNPCs = function()
        for npcObj, npcLevelOfDetail in next, settings.hiddenNPCs do
            if npcObj and npcObj.Parent then
                npcObj.LevelOfDetail = npcLevelOfDetail
            end
        end

        settings.hiddenNPCs = {}
    end
    local enableLowGraphics = function()
        local player = players.LocalPlayer

        if not player then
            return
        end
        if not settings.lowGraphicsApplied then
            settings.originalLowGraphics = player:GetAttribute('LowGraphics')
            settings.lowGraphicsApplied = true
        end

        player:SetAttribute('LowGraphics', true)
    end
    local restoreLowGraphics = function()
        local targetPlayer = players.LocalPlayer

        if not targetPlayer then
            return
        end
        if not settings.lowGraphicsApplied then
            return
        end

        targetPlayer:SetAttribute('LowGraphics', settings.originalLowGraphics)

        settings.originalLowGraphics = nil
        settings.lowGraphicsApplied = false
    end
    local disableParticles = function()
        local localPlayer = players.LocalPlayer
        local character = localPlayer and localPlayer.Character
        local isInCharacter = function(object)
            if not character then
                return false
            end

            return object:IsDescendantOf(character)
        end

        for index, descendant in next, workspace:GetDescendants()do
            if descendant:IsA('ParticleEmitter') and not isInCharacter(descendant) then
                if settings.disabledParticles[descendant] == nil then
                    settings.disabledParticles[descendant] = descendant.Enabled
                end

                descendant.Enabled = false
            end
        end
    end
    local restoreParticles = function()
        for particle, wasEnabled in next, settings.disabledParticles do
            if particle and particle.Parent then
                particle.Enabled = wasEnabled
            end
        end

        settings.disabledParticles = {}
    end
    local muteSounds = function()
        local soundService = game:GetService('SoundService')

        if settings.savedSoundServiceVolume == nil then
            settings.savedSoundServiceVolume = soundService.Volume
        end

        pcall(function()
            soundService.Volume = 0
        end)

        local muteSound = function(sound)
            if not (sound:IsA('Sound') or sound:IsA('AudioPlayer')) then
                return
            end
            if settings.mutedSounds[sound] == nil then
                settings.mutedSounds[sound] = sound.Volume
            end

            pcall(function()
                sound.Volume = 0
            end)
        end

        for i, workspaceDescendant in next, workspace:GetDescendants()do
            muteSound(workspaceDescendant)
        end
        for idx, soundDescendant in next, soundService:GetDescendants()do
            muteSound(soundDescendant)
        end
    end
    local restoreSounds = function()
        if settings.savedSoundServiceVolume ~= nil then
            pcall(function()
                game:GetService('SoundService').Volume = settings.savedSoundServiceVolume
            end)

            settings.savedSoundServiceVolume = nil
        end

        for mutedSound, originalVolume in next, settings.mutedSounds do
            if mutedSound and mutedSound.Parent then
                pcall(function()
                    mutedSound.Volume = originalVolume
                end)
            end
        end

        settings.mutedSounds = {}

        if settings.soundEnforceConn then
            settings.soundEnforceConn:Disconnect()

            settings.soundEnforceConn = nil
        end
    end
    local lighting = game:GetService('Lighting')
    local aB = {
        BloomEffect = true,
        SunRaysEffect = true,
        DepthOfFieldEffect = true,
        ColorCorrectionEffect = true,
        BlurEffect = true,
        Atmosphere = true,
    }
    local aC = false
    local enableCompatibilityLighting = function()
        if not shared.Palantir_IsVolt and type(setthreadidentity) == 'function' then
            pcall(setthreadidentity, 8)
        end
        if lighting.Technology ~= Enum.Technology.Compatibility then
            local success, err = pcall(function()
                lighting.Technology = Enum.Technology.Compatibility
            end)

            if (not success or lighting.Technology ~= Enum.Technology.Compatibility) and not aC then
                aC = true

                if not LPH_OBFUSCATED then
                    warn('[PalantirX] Lighting.Technology downgrade blocked by engine \u{2014} Future stays. (err: ' .. tostring(err) .. ')')
                end
            end
        end
        if lighting.GlobalShadows then
            pcall(function()
                lighting.GlobalShadows = false
            end)
        end
        if lighting.Ambient ~= Color3.new(1, 1, 1) then
            pcall(function()
                lighting.Ambient = Color3.new(1, 1, 1)
            end)
        end
        if lighting.OutdoorAmbient ~= Color3.new(1, 1, 1) then
            pcall(function()
                lighting.OutdoorAmbient = Color3.new(1, 1, 1)
            end)
        end
        if lighting.Brightness > 0 then
            pcall(function()
                lighting.Brightness = 0
            end)
        end
        if lighting.EnvironmentSpecularScale > 0 then
            pcall(function()
                lighting.EnvironmentSpecularScale = 0
            end)
        end
        if lighting.EnvironmentDiffuseScale > 0 then
            pcall(function()
                lighting.EnvironmentDiffuseScale = 0
            end)
        end

        for childIndex, child in next, lighting:GetChildren()do
            if aB[child.ClassName] and child.Enabled then
                pcall(function()
                    child.Enabled = false
                end)
            end
        end
    end
    local applyTrueBoost = function()
        if settings.trueBoostConn then
            return
        end

        settings.trueBoostSaved = {
            Technology = lighting.Technology,
            GlobalShadows = lighting.GlobalShadows,
            Ambient = lighting.Ambient,
            OutdoorAmbient = lighting.OutdoorAmbient,
            Brightness = lighting.Brightness,
            EnvironmentSpecularScale = lighting.EnvironmentSpecularScale,
            EnvironmentDiffuseScale = lighting.EnvironmentDiffuseScale,
            postFX = {},
        }

        for child, postFX in next, lighting:GetChildren()do
            if aB[postFX.ClassName] then
                settings.trueBoostSaved.postFX[postFX] = postFX.Enabled
            end
        end

        if type(setthreadidentity) == 'function' then
            pcall(setthreadidentity, 8)
        end

        settings.trueBoostConn = runService.Heartbeat:Connect(enableCompatibilityLighting)
    end
    local restoreTrueBoost = function()
        if settings.trueBoostConn then
            settings.trueBoostConn:Disconnect()

            settings.trueBoostConn = nil
        end

        local savedSettings = settings.trueBoostSaved

        if not savedSettings then
            return
        end

        pcall(function()
            lighting.Technology = savedSettings.Technology
        end)
        pcall(function()
            lighting.GlobalShadows = savedSettings.GlobalShadows
        end)
        pcall(function()
            lighting.Ambient = savedSettings.Ambient
        end)
        pcall(function()
            lighting.OutdoorAmbient = savedSettings.OutdoorAmbient
        end)
        pcall(function()
            lighting.Brightness = savedSettings.Brightness
        end)
        pcall(function()
            lighting.EnvironmentSpecularScale = savedSettings.EnvironmentSpecularScale
        end)
        pcall(function()
            lighting.EnvironmentDiffuseScale = savedSettings.EnvironmentDiffuseScale
        end)

        for postFXInstance, enabled in next, savedSettings.postFX do
            if postFXInstance and postFXInstance.Parent then
                pcall(function()
                    postFXInstance.Enabled = enabled
                end)
            end
        end

        settings.trueBoostSaved = nil
    end
    local aH = {
        [Enum.Material.Glass] = true,
        [Enum.Material.ForceField] = true,
        [Enum.Material.Neon] = true,
        [Enum.Material.Foil] = true,
    }
    local overrideMaterials = function()
        local player = players.LocalPlayer
        local character = player and player.Character
        local isVisualizer = function(instance)
            if not character then
                return false
            end

            return instance:IsDescendantOf(character)
        end

        for part, descendant in next, workspace:GetDescendants()do
            if descendant:IsA('BasePart') and aH[descendant.Material] and not isVisualizer(descendant) and not descendant:GetAttribute('_PalantirX_Visualizer') then
                if settings.overriddenMaterials[descendant] == nil then
                    settings.overriddenMaterials[descendant] = descendant.Material
                end

                pcall(function()
                    descendant.Material = Enum.Material.Plastic
                end)
            end
        end
    end
    local restoreMaterials = function()
        for part, originalMaterial in next, settings.overriddenMaterials do
            if part and part.Parent then
                pcall(function()
                    part.Material = originalMaterial
                end)
            end
        end

        settings.overriddenMaterials = {}
    end
    local disableCastShadows = function()
        local player = players.LocalPlayer
        local character = player and player.Character
        local isPlayerPart = function(instance)
            if not character then
                return false
            end

            return instance:IsDescendantOf(character)
        end

        for part, descendant in next, workspace:GetDescendants()do
            if descendant:IsA('BasePart') and descendant.CastShadow and not isPlayerPart(descendant) then
                if settings.disabledCastShadows[descendant] == nil then
                    settings.disabledCastShadows[descendant] = true
                end

                pcall(function()
                    descendant.CastShadow = false
                end)
            end
        end

        if settings.savedPhysicsStepping == nil then
            pcall(function()
                settings.savedPhysicsStepping = workspace.PhysicsSteppingMethod
            end)
        end

        pcall(function()
            workspace.PhysicsSteppingMethod = Enum.PhysicsSteppingMethod.Fixed
        end)

        if settings.savedInterpolation == nil then
            pcall(function()
                settings.savedInterpolation = workspace.InterpolationThrottling
            end)
        end

        pcall(function()
            workspace.InterpolationThrottling = Enum.InterpolationThrottlingMode.Disabled
        end)
    end
    local restoreCastShadows = function()
        for part in next, settings.disabledCastShadows do
            if part and part.Parent then
                pcall(function()
                    part.CastShadow = true
                end)
            end
        end

        settings.disabledCastShadows = {}

        if settings.savedPhysicsStepping ~= nil then
            pcall(function()
                workspace.PhysicsSteppingMethod = settings.savedPhysicsStepping
            end)

            settings.savedPhysicsStepping = nil
        end
        if settings.savedInterpolation ~= nil then
            pcall(function()
                workspace.InterpolationThrottling = settings.savedInterpolation
            end)

            settings.savedInterpolation = nil
        end
    end
    local restoreStatsThrottle = function()
        local hook = settings.statsThrottleHook

        if not hook or not hook.original then
            return
        end

        pcall(hookfunction, task.spawn, hook.original)

        settings.statsThrottleHook = nil
    end

    function optimizations.applyOptimizeGameSelection()
        if getOptimizationOption('No Map Clouds') then
            disableClouds()
        end
        if getOptimizationOption('No Cloud Adorns') then
            disableCloudAdorns()
        end
        if getOptimizationOption('No Ship Details') then
            hideShipDetails()
        end
        if getOptimizationOption('Low Client Effects') then
            enableLowGraphics()
        end
        if getOptimizationOption('Strip Particles') then
            disableParticles()
        end

        restoreStatsThrottle()

        if getOptimizationOption('Mute World Audio') then
            muteSounds()
        end
        if getOptimizationOption('Engine Bulldozer') then
            disableCastShadows()
        end
        if getOptimizationOption('Strip Expensive Materials') then
            overrideMaterials()
        end
        if getOptimizationOption('True FPS Boost') then
            applyTrueBoost()
        end
    end
    function optimizations.restoreOptimizeGameSelection()
        restoreClouds()
        restoreCloudAdorns()
        restoreHiddenNPCs()
        restoreLowGraphics()
        pcall(seaOptimizer.uninstall)
        restoreParticles()
        restoreStatsThrottle()
        restoreSounds()
        restoreCastShadows()
        restoreMaterials()
        restoreTrueBoost()
    end
    function optimizations.init()
        local renderSignal = signal.new(runService.RenderStepped)

        if getOptimizationOption('No Map Clouds') then
            disableClouds()
        end
        if getOptimizationOption('No Cloud Adorns') then
            disableCloudAdorns()
        end
        if getOptimizationOption('No Ship Details') then
            hideShipDetails()
        end
        if getOptimizationOption('Low Client Effects') then
            enableLowGraphics()
        end
        if getOptimizationOption('Strip Particles') then
            disableParticles()
        end

        restoreStatsThrottle()

        if getOptimizationOption('Mute World Audio') then
            muteSounds()
        end
        if getOptimizationOption('Engine Bulldozer') then
            disableCastShadows()
        end
        if getOptimizationOption('Strip Expensive Materials') then
            overrideMaterials()
        end
        if getOptimizationOption('True FPS Boost') then
            applyTrueBoost()
        end
        if getOptimizationOption('Reduce Heavy Effects') then
            task.spawn(function()
                local replicatedStorage = game:GetService('ReplicatedStorage')
                local effectModules = replicatedStorage:FindFirstChild('ClientEffectModules')

                if not effectModules then
                    return
                end

                local characterModule = effectModules:FindFirstChild('Character')

                if not characterModule then
                    return
                end

                local movementModule = characterModule:FindFirstChild('Movement')

                if not movementModule then
                    return
                end

                local ok, module = pcall(require, movementModule)

                if not ok or type(module) ~= 'table' then
                    return
                end

                local noop = function() end

                for index, memberName in ipairs({
                    'BounderSpooky',
                    'RegentHaunt',
                    'InWindZone',
                    'AmbientSound',
                    'Shine',
                })do
                    if type(module[memberName]) == 'function' then
                        module[memberName] = noop
                    end
                end
            end)
        end
        if getOptimizationOption('Block Anti-Cheat Probes') then
            local localPlayer = game:GetService('Players').LocalPlayer

            ai:mark(localPlayer:GetPropertyChangedSignal('DevCameraOcclusionMode'):Connect(function(
            )
                if localPlayer.DevCameraOcclusionMode == Enum.DevCameraOcclusionMode.Invisicam then
                    pcall(function()
                        localPlayer.DevCameraOcclusionMode = Enum.DevCameraOcclusionMode.Zoom
                    end)
                end
            end))
            ai:mark(localPlayer:GetPropertyChangedSignal('CameraMaxZoomDistance'):Connect(function(
            )
                if localPlayer.CameraMaxZoomDistance >= 800 then
                    pcall(function()
                        localPlayer.CameraMaxZoomDistance = 799
                    end)
                end
            end))
        end

        local lastUpdate = 0

        ai:mark(renderSignal:connect('Optimizations_UpdateNPCs', function()
            if not getOptimizationOption('Fast NPC Hide') then
                return
            end
            if os.clock() - lastUpdate < 1 then
                return
            end

            lastUpdate = os.clock()

            as()
        end))

        local terrain = workspace:FindFirstChildOfClass('Terrain')

        if terrain then
            ai:mark(terrain.ChildAdded:Connect(function(cloudChild)
                if cloudChild:IsA('Clouds') and getOptimizationOption('No Map Clouds') then
                    if settings.disabledClouds[cloudChild] == nil then
                        settings.disabledClouds[cloudChild] = cloudChild.Enabled
                    end

                    cloudChild.Enabled = false
                end
            end))
        end

        local thrownFolder = workspace:FindFirstChild('Thrown')

        if thrownFolder then
            ai:mark(thrownFolder.ChildAdded:Connect(function(adornChild)
                if adornChild:IsA('ImageHandleAdornment') and adornChild.Name == 'CloudAdorn' and getOptimizationOption('No Cloud Adorns') then
                    if settings.disabledAdorns[adornChild] == nil then
                        settings.disabledAdorns[adornChild] = adornChild.Transparency
                    end

                    adornChild.Transparency = 1
                end
            end))
        end

        ai:mark(workspace.DescendantAdded:Connect(function(particleDesc)
            if not getOptimizationOption('Strip Particles') then
                return
            end
            if not particleDesc:IsA('ParticleEmitter') then
                return
            end

            local localPlayer = players.LocalPlayer
            local character = localPlayer and localPlayer.Character

            if character and particleDesc:IsDescendantOf(character) then
                return
            end
            if settings.disabledParticles[particleDesc] == nil then
                settings.disabledParticles[particleDesc] = particleDesc.Enabled
            end

            particleDesc.Enabled = false
        end))
        ai:mark(workspace.DescendantAdded:Connect(function(soundDesc)
            if not getOptimizationOption('Mute World Audio') then
                return
            end
            if not (soundDesc:IsA('Sound') or soundDesc:IsA('AudioPlayer')) then
                return
            end
            if settings.mutedSounds[soundDesc] == nil then
                settings.mutedSounds[soundDesc] = soundDesc.Volume
            end

            pcall(function()
                soundDesc.Volume = 0
            end)
        end))
        ai:mark(workspace.DescendantAdded:Connect(function(aT)
            if not getOptimizationOption('Engine Bulldozer') then
                return
            end
            if not aT:IsA('BasePart') then
                return
            end
            if not aT.CastShadow then
                return
            end

            local player = players.LocalPlayer
            local char = player and player.Character

            if char and aT:IsDescendantOf(char) then
                return
            end
            if settings.disabledCastShadows[aT] == nil then
                settings.disabledCastShadows[aT] = true
            end

            pcall(function()
                aT.CastShadow = false
            end)
        end))
        ai:mark(workspace.DescendantAdded:Connect(function(partDesc)
            if not getOptimizationOption('Strip Expensive Materials') then
                return
            end
            if not partDesc:IsA('BasePart') then
                return
            end
            if not aH[partDesc.Material] then
                return
            end
            if partDesc:GetAttribute('_PalantirX_Visualizer') then
                return
            end

            local ownPlayer = players.LocalPlayer
            local ownCharacter = ownPlayer and ownPlayer.Character

            if ownCharacter and partDesc:IsDescendantOf(ownCharacter) then
                return
            end
            if settings.overriddenMaterials[partDesc] == nil then
                settings.overriddenMaterials[partDesc] = partDesc.Material
            end

            pcall(function()
                partDesc.Material = Enum.Material.Plastic
            end)
        end))

        local ships = workspace:FindFirstChild('Ships')

        if ships then
            ai:mark(ships.DescendantAdded:Connect(function(shipChild)
                if shipChild.Name == 'ClientDetail' and getOptimizationOption('No Ship Details') then
                    hidePart(shipChild)
                end
            end))
        end

        logger.warn('Optimizations \u{2014} ready.')
    end
    function optimizations.detach()
        restoreClouds()
        restoreCloudAdorns()
        restoreHiddenNPCs()
        restoreLowGraphics()
        restoreParticles()
        restoreStatsThrottle()
        restoreSounds()
        restoreCastShadows()
        restoreMaterials()
        restoreTrueBoost()
        pcall(seaOptimizer.uninstall)
        ai:clean()
        logger.warn('Optimizations \u{2014} detached.')
    end

    return optimizations
end


return aa()

]=],
    ["Features/Game/OwnershipWatcher"] = [=[
local aa = function()
    local part = Instance.new('Part')

    part.Parent = workspace

    local success, err = pcall(function()
        return gethiddenproperty(part, 'NetworkOwnerV3')
    end)

    part:Destroy()

    local isNetworkOwned = function(part)
        local checkOwner = isnetworkowner or function(...)
            return false
        end

        if getexecutorname():match('AWP') then
            return checkOwner(part)
        end
        if getexecutorname():match('Volcano') then
            return checkOwner(part)
        end
        if not success then
            return checkOwner(part)
        end

        local pcallOk, ownerValue = pcall(function()
            return gethiddenproperty(part, 'NetworkOwnerV3')
        end)

        if not pcallOk then
            return checkOwner(part)
        end

        return ownerValue == err
    end

    return (function()
        local module = {
            modelsToScan = {},
            parts = {},
        }
        local runService = game:GetService('RunService')
        local configuration = a["Utility/Configuration"]()
        local instanceWrapper = a["Utility/InstanceWrapper"]()
        local logger = a["Utility/Logger"]()
        local maidFactory = a["Utility/Maid"]()
        local signal = a["Utility/Signal"]()
        local renderSignal = signal.new(runService.RenderStepped)
        local maid = maidFactory.new()
        local cleanAll = function()
            for currentModel, modelMaid in next, module.modelsToScan do
                modelMaid:clean()
            end
        end
        local addModel = function(model)
            if not model:IsA('Model') then
                return
            end
            if module.modelsToScan[model] then
                return
            end

            module.modelsToScan[model] = maidFactory.new()
        end
        local removeModel = function(targetModel)
            if not module.modelsToScan[targetModel] then
                return
            end

            module.modelsToScan[targetModel]:clean()

            module.modelsToScan[targetModel] = nil
        end
        local lastClock = 0
        local renderStep = function()
            if not configuration.expectToggleValue('ShowOwnership') and not configuration.expectToggleValue('VoidMobs') then
                return cleanAll()
            end
            if os.clock() - lastClock < 0.2 then
                return
            end

            lastClock = os.clock()

            local newParts = {}

            for scanModel, scanMaid in next, module.modelsToScan do
                local root = scanModel:FindFirstChild('HumanoidRootPart')

                if not root then
                    continue
                end

                local owner = isNetworkOwned(root)
                local visual = instanceWrapper.create(scanMaid, 'NetworkVisual', 'Part', scanModel)

                visual.Size = Vector3.new(10, 10, 10)
                visual.Transparency = configuration.expectToggleValue('ShowOwnership') and 0.8 or 1
                visual.Color = owner and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)
                visual.CFrame = root.CFrame
                visual.Anchored = true
                visual.CanCollide = false

                local entry = module.parts[root] or {
                    owned = owner,
                    model = scanModel,
                }

                entry.owned = owner
                entry.model = scanModel
                module.parts[root] = entry
                newParts[root] = entry
            end

            module.parts = newParts
        end

        function module.get()
            return module.parts
        end
        function module.init()
            local liveFolder = workspace:WaitForChild('Live')
            local childAddedSignal = signal.new(liveFolder.ChildAdded)
            local childRemovedSignal = signal.new(liveFolder.ChildRemoved)

            maid:add(childAddedSignal:connect('OwnershipWatcher_OnLiveChildAdded', addModel))
            maid:add(childRemovedSignal:connect('OwnershipWatcher_OnLiveChildRemoved', removeModel))

            local renderConnection
            local refreshConnection = function()
                local showOwnership = configuration.expectToggleValue('ShowOwnership') == true

                if showOwnership and not renderConnection then
                    renderConnection = renderSignal:connect('OwnershipWatcher_RenderStepped', renderStep)

                    maid:add(renderConnection)
                elseif (not showOwnership) and renderConnection then
                    renderConnection:Disconnect()

                    renderConnection = nil
                end
            end

            refreshConnection()

            local toggle = Toggles and Toggles.ShowOwnership

            if toggle and toggle.OnChanged then
                toggle:OnChanged(refreshConnection)
            end

            for index, child in next, liveFolder:GetChildren()do
                addModel(child)
            end

            logger.warn('OwnershipWatcher initialized.')
        end
        function module.detach()
            maid:clean()
            cleanAll()
            logger.warn('OwnershipWatcher detached.')
        end

        return module
    end)()
end


return aa()

]=],
    ["Features/Game/PromptRange"] = [=[
local aa = function()
    local moduleTable = {}
    local configuration = a["Utility/Configuration"]()
    local collectionService = game:GetService('CollectionService')
    local promptTag = 'InteractProxPrompt'
    local clientPrompts = {}
    local af = setmetatable({}, {
        __mode = 'k',
    })
    local getPromptOwner = function()
        local multiplier = configuration.expectOptionValue('PromptRangeMultiplier')

        return (type(multiplier) == 'number' and multiplier > 0) and multiplier or 2
    end
    local connectPrompt = function(prompt)
        if not (prompt and prompt:IsA('ProximityPrompt')) then
            return
        end

        local originalMax = prompt:GetAttribute('OriginalMax')

        if not originalMax then
            originalMax = prompt.MaxActivationDistance

            prompt:SetAttribute('OriginalMax', originalMax)
        end

        af[prompt] = true

        pcall(function()
            prompt.MaxActivationDistance = originalMax * getPromptOwner()
        end)
    end

    function moduleTable.extend(targetPrompt)
        connectPrompt(targetPrompt)
    end

    local refreshPrompts = function(refreshPrompt)
        local storedMax = refreshPrompt:GetAttribute('OriginalMax')

        if storedMax then
            pcall(function()
                refreshPrompt.MaxActivationDistance = storedMax

                refreshPrompt:SetAttribute('OriginalMax', nil)
            end)
        end
    end

    function moduleTable.setEnabled(enabled)
        for index, promptInstance in ipairs(collectionService:GetTagged(promptTag))do
            if enabled then
                connectPrompt(promptInstance)
            else
                refreshPrompts(promptInstance)
            end
        end

        if not enabled then
            for trackedPrompt in pairs(af)do
                refreshPrompts(trackedPrompt)
            end

            table.clear(af)
        end
    end
    function moduleTable.refresh()
        if configuration.expectToggleValue('PromptRange') then
            moduleTable.setEnabled(true)
        end
    end
    function moduleTable.init()
        if moduleTable.inited then
            return
        end

        moduleTable.inited = true
        clientPrompts[#clientPrompts + 1] = collectionService:GetInstanceAddedSignal(promptTag):Connect(function(
            newPrompt
        )
            if configuration.expectToggleValue('PromptRange') then
                connectPrompt(newPrompt)
            end
        end)

        if configuration.expectToggleValue('PromptRange') then
            moduleTable.setEnabled(true)
        end
    end
    function moduleTable.detach()
        moduleTable.setEnabled(false)

        for index = 1, #clientPrompts do
            pcall(function()
                clientPrompts[index]:Disconnect()
            end)
        end

        clientPrompts = {}
        moduleTable.inited = false
    end

    return moduleTable
end


return aa()

]=],
    ["Features/Game/ProximityDisable"] = [=[
local aa = function()
    local module = {}
    local config = a["Utility/Configuration"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local ae = 1 / 10
    local af = {
        {
            key = 'Flight',
            toggle = 'Flight',
        },
        {
            key = 'Speedhack',
            toggle = 'Speedhack',
        },
        {
            key = 'NoClip',
            toggle = 'NoClip',
        },
        {
            key = 'Sticky Attach',
            toggle = 'StickyAttach',
        },
        {
            key = 'Tween To Back',
            toggle = 'TweenToBack',
        },
    }
    local ag = {
        ['Red'] = Color3.fromRGB(255, 50, 50),
        ['Orange'] = Color3.fromRGB(255, 165, 0),
        ['Yellow'] = Color3.fromRGB(255, 255, 0),
        ['White'] = Color3.fromRGB(255, 255, 255),
    }
    local ah
    local ai
    local aj = {}
    local al = 0
    local am = 100
    local an = false
    local ao = false
    local ap = {}
    local aq = false
    local ar = false
    local loadProximityConfig = function()
        am = config.expectOptionValue('PlayerProximityRange') or 1000
        an = config.expectToggleValue('ProxHitboxVisualizer') == true
        ao = config.expectToggleValue('ProxAutoDisable') == true
        aq = config.expectToggleValue('PlayerProximity') == true
        ar = config.expectToggleValue('PlayerProximityVW') == true

        local disableFeatures = config.expectOptionValue('ProxDisableFeatures') or {}

        for index, feature in ipairs(af)do
            ap[feature.key] = disableFeatures[feature.key] == true
        end
    end
    local at = {}
    local au
    local av
    local aw = {}
    local removeHitbox = function(model)
        local hitbox = aw[model]

        if hitbox and hitbox.Parent then
            hitbox:Destroy()
        end

        aw[model] = nil
    end
    local createHitbox = function(targetCharacter)
        removeHitbox(targetCharacter)

        local targetRootPart = targetCharacter:FindFirstChild('HumanoidRootPart')

        if not targetRootPart then
            return
        end

        local range = am
        local color = config.expectOptionValue('ProxHitboxColor') or 'Red'
        local transparency = config.expectOptionValue('ProxHitboxTransparency') or 0.5
        local part = Instance.new('Part')

        part.Name = 'ProxHitboxSphere'
        part.Shape = Enum.PartType.Ball
        part.Size = Vector3.new(range * 2, range * 2, range * 2)
        part.Color = ag[color] or ag['Red']
        part.Transparency = transparency
        part.CanCollide = false
        part.Anchored = false
        part.CastShadow = false
        part.Material = Enum.Material.ForceField

        local weld = Instance.new('WeldConstraint')

        weld.Part0 = part
        weld.Part1 = targetRootPart
        weld.Parent = part
        part.CFrame = targetRootPart.CFrame
        part.Parent = workspace
        aw[targetCharacter] = part
    end
    local removeAllHitboxes = function()
        for hitboxModel, hitboxPart in next, aw do
            removeHitbox(hitboxModel)
        end
    end
    local aA = function(disableOption)
        if not Toggles[disableOption.toggle] then
            return
        end
        if not Toggles[disableOption.toggle].Value then
            return
        end

        aj[disableOption.toggle] = true

        Toggles[disableOption.toggle]:SetValue(false)
    end
    local aB = function(enableOption)
        if not aj[enableOption.toggle] then
            return
        end
        if not Toggles[enableOption.toggle] then
            return
        end

        aj[enableOption.toggle] = nil

        Toggles[enableOption.toggle]:SetValue(true)
    end
    local enableAllOptions = function()
        for optionIndex, option in ipairs(af)do
            aB(option)
        end
    end

    function module.start()
        module.stop()
        table.clear(at)

        for playerIndex, player in ipairs(players:GetPlayers())do
            at[#at + 1] = player
        end

        au = players.PlayerAdded:Connect(function(addedPlayer)
            at[#at + 1] = addedPlayer
        end)
        av = players.PlayerRemoving:Connect(function(removedPlayer)
            local foundIndex = table.find(at, removedPlayer)

            if foundIndex then
                table.remove(at, foundIndex)
            end
        end)
        ai = workspace.DescendantRemoving:Connect(function(removedModel)
            if not removedModel:IsA('Model') then
                return
            end
            if not aw[removedModel] then
                return
            end

            removeHitbox(removedModel)

            local character = players.LocalPlayer.Character
            local rootPart = character and character:FindFirstChild('HumanoidRootPart')

            if not rootPart then
                enableAllOptions()

                return
            end

            local foundNearby = false

            for loopIndex, otherPlayer in ipairs(players:GetPlayers())do
                if otherPlayer == players.LocalPlayer then
                    continue
                end

                local otherCharacter = otherPlayer.Character

                if not otherCharacter or otherCharacter == removedModel then
                    continue
                end

                local otherRootPart = otherCharacter:FindFirstChild('HumanoidRootPart')

                if otherRootPart and (otherRootPart.Position - rootPart.Position).Magnitude <= am then
                    if ar then
                        local otherBackpack = otherPlayer:FindFirstChild('Backpack')

                        if otherBackpack and otherBackpack:FindFirstChild('Talent:Voideye') then
                            foundNearby = true

                            break
                        end
                    else
                        foundNearby = true

                        break
                    end
                end
            end

            if not foundNearby then
                enableAllOptions()
            end
        end)
        ah = runService.Heartbeat:Connect(function()
            loadProximityConfig()

            if not aq or not ao then
                module.stop()

                return
            end

            local now = os.clock()

            if now - al < ae then
                return
            end

            al = now

            local localCharacter = players.LocalPlayer.Character

            if not localCharacter then
                return
            end

            local localRootPart = localCharacter:FindFirstChild('HumanoidRootPart')

            if not localRootPart then
                return
            end

            local proximityRange = am
            local visualizer = an
            local someoneNearby = false

            for trackedIndex, trackedPlayer in ipairs(at)do
                if trackedPlayer == players.LocalPlayer then
                    continue
                end

                local trackedCharacter = trackedPlayer.Character

                if not trackedCharacter then
                    continue
                end

                local trackedRootPart = trackedCharacter:FindFirstChild('HumanoidRootPart')

                if not trackedRootPart then
                    continue
                end

                local inRange = (trackedRootPart.Position - localRootPart.Position).Magnitude <= proximityRange

                if inRange and ar then
                    local trackedBackpack = trackedPlayer:FindFirstChild('Backpack')

                    if not (trackedBackpack and trackedBackpack:FindFirstChild('Talent:Voideye')) then
                        inRange = false
                    end
                end
                if inRange then
                    someoneNearby = true
                end
                if visualizer then
                    if inRange and not aw[trackedCharacter] then
                        createHitbox(trackedCharacter)
                    elseif not inRange and aw[trackedCharacter] then
                        removeHitbox(trackedCharacter)
                    end
                elseif aw[trackedCharacter] then
                    removeHitbox(trackedCharacter)
                end
            end

            if someoneNearby then
                for featureIndex, featureDef in ipairs(af)do
                    if ap[featureDef.key] then
                        aA(featureDef)
                    end
                end
            else
                enableAllOptions()
            end
        end)
    end
    function module.stop()
        if ah then
            ah:Disconnect()

            ah = nil
        end
        if ai then
            ai:Disconnect()

            ai = nil
        end
        if au then
            au:Disconnect()

            au = nil
        end
        if av then
