            av = nil
        end

        table.clear(at)
        enableAllOptions()

        aj = {}

        removeAllHitboxes()
    end
    function module.refreshSpheres()
        for sphereId, sphereData in next, aw do
            createHitbox(sphereId)
        end
    end

