]=],
    ["Features/Game/QuickToggles"] = [=[
local aa = function()
    local delayedTask = a["Utility/DelayedTask"]()
    local keyHandling = a["Game/KeyHandling"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local placeIds = a["Game/PlaceIds"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local toggles = {}
    local cleaner = maid.new()
    local getLocalPlayer = function()
        return players.LocalPlayer
    end
    local getPlayerCharacter = function()
        local player = getLocalPlayer()

        return player and player.Character
    end
    local getCharacterRoot = function()
        local character = getPlayerCharacter()

        return character and character:FindFirstChild('HumanoidRootPart')
    end
    local an
    local getEffectsModule = function()
        if an then
            return an
        end

        local replicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not replicator then
            return nil
        end

        local success, effectsModule = pcall(require, replicator)

        an = success and effectsModule or nil

        return an
    end
    local ap
    local onChoicePrompt = function(prompt)
        if prompt.Name ~= 'ChoicePrompt' then
            return
        end

        local title = prompt:FindFirstChild('Title', true)

        if not title then
            return
        end
        if toggles.declineGuild and title.Text:find('Join Guild') then
            logger.notify('Declined a guild invite.')
            pcall(function()
                delayedTask.method(prompt.Choice, 'FireServer', false)

                prompt.Enabled = false
            end)

            return
        end
        if toggles.declineSquad and title.Text:find('Squad Invitation') then
            local desc = prompt:FindFirstChild('Desc', true)
            local inviter = 'someone'

            if desc then
                pcall(function()
                    inviter = desc.Text:split('join ')[2]:split("'s")[1]
                end)
            end

            logger.notify("Declined a squad invite from '%s'.", tostring(inviter))
            pcall(function()
                delayedTask.method(prompt.Choice, 'FireServer', false)

                prompt.Enabled = false
            end)
        end
    end

    toggles.declineGuild = false
    toggles.declineSquad = false

    function toggles.setDeclineGuild(enabled)
        toggles.declineGuild = enabled and true or false

        if enabled then
            toggles.initDeclineInvites()
        end
    end
    function toggles.setDeclineSquad(enabledSquad)
        toggles.declineSquad = enabledSquad and true or false

        if enabledSquad then
            toggles.initDeclineInvites()
        end
    end
    function toggles.initDeclineInvites()
        if ap then
            return
        end

        local localPlayer = getLocalPlayer()
        local playerGui = localPlayer and localPlayer:FindFirstChildOfClass('PlayerGui')

        if not playerGui then
            return
        end

        ap = playerGui.ChildAdded:Connect(onChoicePrompt)

        cleaner:add(ap)
    end

    local ar
    local as

    function toggles.setJesus(jesusEnabled)
        if not jesusEnabled then
            if as then
                as:Disconnect()

                as = nil
            end
            if ar then
                ar.Parent = nil
            end

            local effects = getEffectsModule()
            local effect = effects and effects:FindEffect('NoSwim')

            if effect then
                pcall(function()
                    effect:Debris(0.1)
                end)
            end

            return
        end
        if not ar then
            ar = Instance.new('Part')
            ar.Transparency = 1
            ar.Size = Vector3.new(2048, 1, 2048)
            ar.Anchored = true
            ar.CanCollide = true
            ar.Name = 'FakeWater'

            cleaner:mark(ar)
        end
        if not placeIds.isEtrean() and not placeIds.isEastern() then
            return
        end

        ar.Parent = workspace
        as = runService.Heartbeat:Connect(function()
            local root = getCharacterRoot()

            if not placeIds.isEtrean() and not placeIds.isEastern() then
                if ar.Parent then
                    ar.Parent = nil

                    local effectHandler = getEffectsModule()
                    local noSwim = effectHandler and effectHandler:FindEffect('NoSwim')

                    if noSwim then
                        pcall(function()
                            noSwim:Debris(0.1)
                        end)
                    end
                end

                return
            end
            if not root then
                return
            end
            if not ar.Parent then
                ar.Parent = workspace
            end

            ar.CFrame = CFrame.new(root.CFrame.X, -3, root.CFrame.Z)

            local effectController = getEffectsModule()

            if effectController and not effectController:HasEffect('NoSwim') then
                pcall(function()
                    effectController:CreateEffect('NoSwim')
                end)
            end
        end)

        cleaner:add(as)
    end

    local at

    function toggles.setNoFire(enabled)
        if not enabled then
            if at then
                at:Disconnect()

                at = nil
            end

            return
        end
        if at then
            return
        end

        local combat = getEffectsModule()

        if not combat or not combat.EffectAdded then
            return
        end

        at = combat.EffectAdded:Connect(function(effect)
            if effect.Class ~= 'Burning' then
                return
            end

            pcall(function()
                keyHandling.getRemote('ServerSlide'):FireServer(true)
                keyHandling.getRemote('ServerSlideStop'):FireServer()
            end)
        end)

        cleaner:add(at)
    end

    local au
    local av = false
    local isPlayerNearby = function(distance)
        local character = getCharacterRoot()

        if not character then
            return false
        end

        for index, player in ipairs(players:GetPlayers())do
            if player == getLocalPlayer() or not player.Character then
                continue
            end

            local root = player.Character:FindFirstChild('HumanoidRootPart')

            if root and (character.Position - root.Position).Magnitude <= distance then
                return true
            end
        end

        return false
    end
    local hasAnkleWeight = function()
        local playerCharacter = getPlayerCharacter()
        local leftLeg = playerCharacter and playerCharacter:FindFirstChild('Left Leg')

        return leftLeg and leftLeg:FindFirstChild('AnkleWeight') ~= nil
    end

    function toggles.setTrainAgility(enabled)
        if not enabled then
            if au then
                au:Disconnect()

                au = nil
            end

            return
        end
        if au then
            return
        end

        au = runService.Heartbeat:Connect(LPH_NO_VIRTUALIZE(function()
            if av or not getCharacterRoot() then
                return
            end

            local combat = getEffectsModule()

            if combat and (combat:HasEffect('Knocked') or combat:FindEffect('Danger') or combat:FindEffect('Action') or combat:FindEffect('LightAttack') or combat:FindEffect('UsingAbility')) then
                return
            end
            if toggles.agilityReady and not toggles.agilityReady() then
                return
            end
            if not hasAnkleWeight() or isPlayerNearby(100) then
                return
            end

            av = true

            local heartbeat = au
            local playerCharacter = getPlayerCharacter()

            pcall(function()
                keyHandling.getRemote('Dodge'):FireServer('roll', nil, nil, false)
            end)
            task.delay(0.15, function()
                if au ~= heartbeat or getPlayerCharacter() ~= playerCharacter then
                    return
                end
                if toggles.agilityReady and not toggles.agilityReady() then
                    return
                end

                pcall(function()
                    if combat and combat:FindEffect('ClientDodge') then
                        local feintEffect = combat:CreateEffect('ClientFeint')

                        if feintEffect then
                            feintEffect:Debris(0.1)
                        end
                    end

                    keyHandling.getRemote('StopDodge'):FireServer({
                        W = false,
                        Right = true,
                        S = false,
                        NOAERIALS = false,
                    }, combat and combat:HasEffect('LightAttack'))
                end)
            end)
            task.delay(0.5, function()
                av = false
            end)
        end))

        cleaner:add(au)
    end
    function toggles.active(toggleName)
        if toggleName == 'Jesus' then
            return as ~= nil
        elseif toggleName == 'NoFire' then
            return at ~= nil
        elseif toggleName == 'AutoTrainAgility' then
            return au ~= nil
        elseif toggleName == 'AutoDeclineGuild' then
            return toggles.declineGuild
        elseif toggleName == 'AutoDeclineSquad' then
            return toggles.declineSquad
        end

        return false
    end
    function toggles.init() end
    function toggles.detach()
        toggles.declineGuild = false
        toggles.declineSquad = false

        toggles.setJesus(false)
        toggles.setNoFire(false)
        toggles.setTrainAgility(false)
        cleaner:clean()

        ap = nil
        as = nil
        at = nil
        au = nil
        ar = nil
    end

    return toggles
end


return aa()

