            ax:set(genericBlur, 'Size', 0)
        end

        local underwaterBlur = lighting:FindFirstChild('UnderwaterBlur')

        if underwaterBlur then
            ax:set(underwaterBlur, 'Size', 0)
        end
    end
    local a9 = maidInstance:mark(originalStore.new())
    local b = maidInstance:mark(originalStore.new())
    local ba = maidInstance:mark(originalStore.new())
    local bb = maidInstance:mark(originalStore.new())
    local bc = {}
    local bd = false
    local getFullBrightLevel = function()
        local level = config.expectOptionValue('FullBrightLevel')

        if type(level) ~= 'number' then
            return 5
        end
        if level < 0 then
            return 0
        end
        if level > 10 then
            return 10
        end

        return level
    end
    local getFullBrightColor = function()
        local grayValue = math.floor(getFullBrightLevel() * 25.5 + 0.5)

        return Color3.fromRGB(grayValue, grayValue, grayValue)
