    local getBrightness = function()
        return getFullBrightLevel()
    end
    local getExposureOffset = function()
        return getFullBrightLevel() * 0.15
    end
    local enforceLightingValue = function(propertyName, getter)
        lighting[propertyName] = getter()

        local connection = lighting:GetPropertyChangedSignal(propertyName):Connect(function()
            local computedValue = getter()

            if lighting[propertyName] ~= computedValue then
                lighting[propertyName] = computedValue
            end
