        b:set(lighting, 'OutdoorAmbient', getFullBrightColor())
        ba:set(lighting, 'Brightness', getBrightness())
        bb:set(lighting, 'ExposureCompensation', getExposureOffset())
        enforceLightingValue('Ambient', getFullBrightColor)
        enforceLightingValue('OutdoorAmbient', getFullBrightColor)
        enforceLightingValue('Brightness', getBrightness)
        enforceLightingValue('ExposureCompensation', getExposureOffset)
    end
    local applyLightingSettings = function()
