            if not data2 then
                continue
            end

            entry2:set(entry2.data, 'Parent', nil)
        end
    end
    local findAcidRemote = function()
        if as then
            return
        end

        local requests = replicatedStorage:FindFirstChild('Requests')

        if not requests then
            return
        end

        local acidRemote = requests:FindFirstChild('AcidRemote')

        if not acidRemote then
            return
        end

        as = acidRemote
        as.Name = 'AcidRemote_Original'
        remoteEvent1.Parent = requests
    end
    local removeAcidRemote = function()
        if not as then
            return
        end

        as.Name = 'AcidRemote'
        remoteEvent1.Parent = nil
    end
    local br = {
        'Terror',
        'TerrorTendril',
        'TerrorTendril2',
