    local bs = {}
    local bt = {}
    local bu
    local bv = false
    local hideElement = function(target)
        if not target or bs[target] then
            return
        end

        bs[target] = true

        az:set(target, 'Visible', false)

        bt[#bt + 1] = target:GetPropertyChangedSignal('Visible'):Connect(function(
        )
            if bv and target.Visible then
                target.Visible = false
            end
        end)
    end
    local enableOverlay = function()
        bv = true

        local player = players.LocalPlayer
        local playerGui = player and player:FindFirstChild('PlayerGui')

        if not playerGui then
            return
        end

        local overlayGui = playerGui:FindFirstChild('OverlayGui')

        if not overlayGui then
            return
        end

        for index3, terrorName in next, br do
            hideElement(overlayGui:FindFirstChild(terrorName))
        end

        if not bu then
            bu = overlayGui.ChildAdded:Connect(function(child)
                for index4, candidateName in next, br do
                    if child.Name == candidateName then
                        hideElement(child)

                        break
                    end
                end
            end)
        end
    end
    local disableOverlay = function()
        bv = false

        for index5, connection in next, bt do
            connection:Disconnect()
        end

        bt = {}

        if bu then
