    local bz = {
        'Health',
        'Armor',
        'Posture',
    }
    local bA = {}
    local bB = {}
    local removeGuiElement = function(guiTarget)
        if not guiTarget then
            return
        end

        pcall(function()
            if guiTarget:IsA('GuiObject') then
                guiTarget.Visible = false
            end
        end)
        pcall(function()
            guiTarget.Parent = nil
        end)
        pcall(function()
            guiTarget:Destroy()
        end)
    end
    local removeHarrowGui = function(gui)
        if not gui then
            return
        end

        for index, child in ipairs(gui:GetChildren())do
            if child.Name == 'HarrowGUI' then
                removeGuiElement(child)
            end
        end
    end
    local showHoverGui = function(instance)
        if not instance then
            return
        end

        for childIndex, hoverChild in ipairs(instance:GetChildren())do
