        showHoverGui(target)

        if bA[target] then
            return
        end

        bA[target] = target.DescendantAdded:Connect(function(descendant)
            if descendant.Name == 'HarrowGUI' then
                removeGuiElement(descendant)
            elseif descendant.Name == 'Hover' and descendant.Parent == target then
                showHoverGui(target)
            end
        end)
    end
    local trackStatGuis = function()
        local player = players.LocalPlayer
        local playerGui = player and player:FindFirstChild('PlayerGui')
        local statsGui = playerGui and playerGui:FindFirstChild('StatsGui')
        local combatStats = statsGui and statsGui:FindFirstChild('CombatStats')

        if not combatStats then
            return
        end

        for guiIndex, guiName in ipairs(bz)do
            trackGuiElement(combatStats:FindFirstChild(guiName))
