    ["Features/Game/SeaOptimizer"] = [=[
local aa = function()
    local module = {}
    local config = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local ae
    local af
    local enabled = false
    local ah = {}
    local counter = 0
    local sin = math.sin
    local floor = math.floor
    local identity = CFrame.identity
    local newVector3 = Vector3.new
    local getGridOffset = function(position, ap)
        local gridX = floor(position.X * 0.25)
        local gridZ = floor(position.Z * 0.25)
        local gridT = floor(ap * 8)
        local key = gridX * 33554432 + gridZ * 1024 + gridT
        local cached = ah[key]

        if cached then
            return cached
        end

        local result = af(position, ap)

        ah[key] = result

        local now = os.clock()

        if now - counter > 1 then
            ah = {}
            counter = now
        end

        return result
    end
    local computeWaveOffset = function(cheapPosition, phase)
        local waveX = sin(cheapPosition.X * 0.1 + phase * 1) * 0.5
        local waveZ = sin(cheapPosition.Z * 0.1 + phase * 1 * 0.7) * 0.5

        return {
            Position = newVector3(0, waveX + waveZ, 0),
            Rotation = identity,
        }
    end

    function module.install()
        if enabled then
            return
        end
        if not ae then
            local modulesFolder = replicatedStorage:FindFirstChild('Modules')
            local wavesModule = modulesFolder and modulesFolder:FindFirstChild('Waves')

            if not wavesModule then
                return logger.warn(
"SeaOptimizer: ReplicatedStorage.Modules.Waves not found, skipping.")
            end

            local ok, waves = pcall(require, wavesModule)

            if not ok or type(waves) ~= 'table' or type(waves.getWaveAt) ~= 'function' then
                return logger.warn('SeaOptimizer: Waves module shape unexpected, skipping.')
            end

            ae = waves
            af = waves.getWaveAt
        end

        local mode = config.expectOptionValue('SeaOptimizerMode') or 'Cache'

        if mode == 'Cheap' then
            ae.getWaveAt = computeWaveOffset
        else
            ah = {}
            counter = os.clock()
            ae.getWaveAt = getGridOffset
        end

        enabled = true
    end
    function module.uninstall()
        if not enabled or not ae or not af then
            return
        end

        ae.getWaveAt = af
        ah = {}
        enabled = false
    end
    function module.toggle(enable)
        if enable then
            module.install()
        else
            module.uninstall()
        end
    end
    function module.init()
        if config.expectToggleValue('SeaOptimizer') then
            module.install()
        end
    end
    function module.detach()
        module.uninstall()
    end

    return module
end


return aa()

