    local tweening = a["Features/Game/Tweening"]()
    local runService = game:GetService('RunService')
    local af
    local tweenToBack = feature.new('TweenToBack', runService.PreSimulation, function()
        local target = finder.geir(300, config.expectToggleValue('AttachIgnorePlayers'))

        if not target then
            af = nil

            return
        end

        local character = config.expectToggleValue('StickyAttach') and af or target[1]

        if not character or not character.Parent then
            af = nil

            return
        end

        local rootPart = character:FindFirstChild('HumanoidRootPart')

        if not rootPart then
            return
        end

        local humanoid = character:FindFirstChild('Humanoid')

        if not humanoid or humanoid.Health <= 0 then
            af = nil

            return
        end

        af = af or character

        local offset = CFrame.new(0, config.expectOptionValue('HeightOffset'), config.expectOptionValue('BackOffset'))
        local targetPosition = (rootPart.CFrame * offset).Position

        tweening.goal('TweenToBack', CFrame.lookAt(targetPosition, rootPart.Position), false)
    end)

    function tweenToBack:onDisable()
        af = nil
    end

    return tweenToBack
end


return aa()

