                            firetouchinterest(officePit, root, 1)
                            firetouchinterest(officePit, root, 0)
                        end)
                    end
                end
            end
            if destination == 'TrialOfOne' then
                teleportMaid:add(taskSpawner.spawn('Teleport_TrialStream', players.LocalPlayer.RequestStreamAroundAsync, players.LocalPlayer, Vector3.new(
-959.787659, 146.996887, -6659.63037), 0.1))

                repeat
                    task.wait(0.1)
                    task.spawn(function()
                        players.LocalPlayer:RequestStreamAroundAsync(Vector3.new(
-959.787659, 146.996887, -6659.63037), 1000)
                    end)
                until workspace:FindFirstChild('OneEntrance')

                local oneEntrance = workspace:FindFirstChild('OneEntrance')

                if not oneEntrance then
                    return
                end

                local replicator = replicatedStorage:FindFirstChild('EffectReplicator')

                if not replicator then
                    return
                end

                local effectReplicator = require(replicator)

                if not effectReplicator then
                    return
                end
                if effectReplicator:FindEffect('Knocked') then
                    return teleport.stop()
                end

                character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()

                local root = character:WaitForChild('HumanoidRootPart')
                local entranceCFrame = oneEntrance.CFrame

                for iteration = 1, 300 do
                    character:PivotTo(entranceCFrame)
                    firetouchinterest(oneEntrance, root, 0)
                    firetouchinterest(oneEntrance, root, 1)
                    firetouchinterest(oneEntrance, root, 0)
                    firetouchinterest(oneEntrance, root, 1)
                    task.wait()
                end
            end
        end)
    end

    function teleport.start(destination)
        if not destination then
            return error('Destination must be provided for teleporting.')
        end

        noEffects.enableFeature('NoFallDamage')

        if destination == 'EasternLuminant' or destination == 'EtreanLuminant' then
            if au and au.destination == destination and au.state == 'running' then
                return
            end

            onTeleportFinished()

            teleport.destination = nil

            local aX = as
            local character = localPlayer.Character
            local targetPosition = destination == 'EtreanLuminant' and Vector3.new(-514.263, 665.174316, 
-4772.3208) or Vector3.new(-2632.86084, 628.632935, -6707.99805)

            au = {
                destination = destination,
                state = 'running',
                reason = 'Loading region portal',
            }
            at = task.defer(function()
                local isStillValid = function()
                    local humanoid = character and character:FindFirstChildOfClass('Humanoid')

                    return aX == as and localPlayer.Character == character and humanoid and humanoid.Health > 0
                end
                local success, errorResult = pcall(function()
                    local portal

                    for attempt = 1, 15 do
                        if not isStillValid() then
                            return
                        end

                        portal = destination == 'EtreanLuminant' and findPartByRealm('Etrean') or destination == 'EasternLuminant' and (findPartByRealm('Eastern') or findPartByRealm('East'))

                        if portal then
                            break
                        end

                        au.reason = 'Loading region portal (' .. attempt .. '/15)'

                        pcall(localPlayer.RequestStreamAroundAsync, localPlayer, targetPosition, 0.5)
                        task.wait(0.5)
                    end

                    if not isStillValid() then
                        return
                    end
                    if not portal then
                        error('Region portal did not stream in')
                    end

                    au.reason = 'Activating region portal'

                    for a1 = 1, 100 do
                        if not isStillValid() then
                            return
                        end
                        if not portal.Parent then
                            error('Region portal unloaded')
                        end

                        character:PivotTo(portal.CFrame)
                        fireTouchInterest(character, portal)
                        task.wait(0.1)
                    end

                    error('Region portal did not confirm a transfer')
                end)

                if aX ~= as then
                    return
                end

                au.state = 'failed'
                au.reason = success and 'Character changed during region transfer' or tostring(errorResult)
                at = nil
            end)

            return
        end

        onTeleportFinished()
        resetState()

        teleport.destination = destination
    end
    function teleport.regionStatus()
        return au
    end
    function teleport.stop(skipReposition)
        onTeleportFinished()
        resetState()

        teleport.destination = nil
        teleport.gdp = nil

        clearQueue()

        if skipReposition then
            return
        end

        local groundPart = aE

        if groundPart then
            local raycastParams = RaycastParams.new()

            raycastParams.FilterType = Enum.RaycastFilterType.Exclude

            local currentCharacter = localPlayer.Character

            if currentCharacter then
                raycastParams.FilterDescendantsInstances = {currentCharacter}
            end

            local raycastResult = workspace:Raycast(groundPart.Position, Vector3.new(0, -50000, 0), raycastParams)

            if raycastResult then
                groundPart.CFrame = CFrame.new(raycastResult.Position + Vector3.new(0, 3, 0))
            end
        end
    end
    function teleport.toWaypoints(waypoints, callback)
        assert(type(waypoints) == 'table' and #waypoints > 0, 'waypoints must be a non-empty table of CFrames')
        noEffects.enableFeature('NoFallDamage')

        local playerCharacter = localPlayer.Character or localPlayer.CharacterAdded:Wait()
        local humanoidRootPart = playerCharacter:WaitForChild('HumanoidRootPart')
        local startIndex = 1
        local firstWaypointPosition = waypoints[1].Position

        if (Vector3.new(firstWaypointPosition.X, humanoidRootPart.Position.Y, firstWaypointPosition.Z) - humanoidRootPart.Position).Magnitude <= 100 then
            startIndex = 2
        end

        startNoCollideLoop()
        task.spawn(function()
            for index = startIndex, #waypoints do
                local isLast = (index == #waypoints)

                enqueueTarget('Teleport_Waypoint_' .. index, waypoints[index], not isLast)
            end

            waitUntilReached('Teleport_Waypoint_' .. #waypoints)
            stopNoCollideLoop()

            if callback then
                callback()
            end
        end)
    end
    function teleport.warp(warpPoint)
        noEffects.enableFeature('NoFallDamage')

        local character = localPlayer.Character or localPlayer.CharacterAdded:Wait()
        local humanoidRootPart = character:WaitForChild('HumanoidRootPart')

        task.spawn(function()
            aO = false

            local warpHeight = humanoidRootPart.Position.Y + 15000

            humanoidRootPart.CFrame = CFrame.new(humanoidRootPart.Position.X, warpHeight, humanoidRootPart.Position.Z)

            enqueueTarget('Teleport_Warp_Across', CFrame.new(warpPoint.Position.X, warpHeight, warpPoint.Position.Z), true)
            waitUntilReached('Teleport_Warp_Across')

            if not aO then
                humanoidRootPart.CFrame = warpPoint
            end
        end)
    end
    function teleport.cancelWaypoints()
        clearQueue()
    end
    function teleport.getGuildDoorNames()
        local seenGuilds = {}
        local doorNames = {}

        for index, door in next, workspace:GetChildren()do
            if door.Name:sub(1, 9) == 'GuildDoor' then
                local guildName = door:GetAttribute('GuildName')

                if guildName and not seenGuilds[guildName] then
                    seenGuilds[guildName] = true
                    doorNames[#doorNames + 1] = guildName
                end
            end
        end

        table.sort(doorNames)

        return doorNames
    end
    function teleport.warpGuildDoor(query)
        if not query or query == '' then
            return
        end

        local targetDoor = (function()
            for loopIndex, instance in next, workspace:GetChildren()do
                if not instance.Name:match('GuildDoor') then
                    continue
                end

                local doorGuildName = instance:GetAttribute('GuildName')

                if doorGuildName and doorGuildName:lower():match(query:lower()) then
                    return instance
                end
            end
        end)()

        if not targetDoor then
            return
        end

        local playerCharacter = localPlayer.Character or localPlayer.CharacterAdded:Wait()
        local rootPart = playerCharacter:WaitForChild('HumanoidRootPart', 5)

        if not rootPart then
            return
        end

        local targetCFrame = targetDoor:GetAttribute('TargetCFrame')

        if not targetCFrame then
            return
        end

        noEffects.enableFeature('NoFallDamage')
        task.spawn(function()
            pcall(players.LocalPlayer.RequestStreamAroundAsync, players.LocalPlayer, targetCFrame.Position, 1000)
            playerCharacter:PivotTo(CFrame.new(targetCFrame.Position - Vector3.new(0, 100, 0)))
        end)
    end
    function teleport.init()
        teleportMaid:mark(playerGuiDispatcher.subscribeAdded(parseLabelPosition))

        local renderSignal = signal.new(runService.RenderStepped)

        teleportMaid:mark(renderSignal:connect('Teleport_RenderStepped', handleDestination))
    end
    function teleport.detach()
        onTeleportFinished()
        clearQueue()

        if heartbeatConnection then
            heartbeatConnection:Disconnect()

            heartbeatConnection = nil
        end

        teleportMaid:clean()
    end

    return teleport
end


return aa()

]=],
    ["Features/Game/TravelRecovery"] = [=[
local aa = function()
    local executeQueue = a["Features/Automation/ExecutionQueue"]()
    local persistentData = a["Utility/PersistentData"]()
    local latency = a["Game/Latency"]()
    local runService = game:GetService('RunService')
    local players = game:GetService('Players')
    local af = {}
    local ag = {}
    local ah = 0
    local ai = 0
    local aj
    local ak = 0
    local startLatencyTracking = function()
        ak = ak + 1

        if aj then
            return
        end

        ai = latency.rtt() or 0
        aj = runService.Heartbeat:Connect(function()
            ai = latency.rtt() or 0
        end)
    end
    local stopLatencyTracking = function()
        ak = math.max(0, ak - 1)

        if ak > 0 or not aj then
            return
        end

        aj:Disconnect()

        aj = nil
    end

    local function safeNaN(value)
        if value == value then
            return value
        end

        local valueType = typeof(value)

        if valueType == 'Vector3' then
            return Vector3.new(safeNaN(value.X), safeNaN(value.Y), safeNaN(value.Z))
        end
        if valueType == 'CFrame' then
            local position = safeNaN(value.Position)
            local rotation = value.Rotation

            if rotation ~= rotation then
                rotation = CFrame.identity
            end

            return CFrame.new(position) * rotation
        end
        if valueType == 'number' then
            return value == value and value or 0
        end

        return value
    end

    local getRootPart = function()
        local character = players.LocalPlayer and players.LocalPlayer.Character

        return character and character:FindFirstChild('HumanoidRootPart')
    end
    local resolveValue = function(resolve)
        if typeof(resolve) == 'function' then
            return resolve()
        end

        return resolve
    end

    function af.new(target, aq, speed)
        speed = speed or 190

        local root = getRootPart()
        local connection
        local state
        local handle = {}
        local queue = executeQueue.active

        if queue and queue.stopMovement then
            queue.stopMovement()
        end

        local lastLogTick, lastMoveTick = os.clock(), os.clock()
        local retryCount, lastDistance = 0
        local objectiveKey = typeof(target) == 'CFrame' and string.format('%s:%d:%d:%d', queue and queue.owner.id or 'travel', math.floor(target.X), math.floor(target.Y), math.floor(target.Z)) or nil
        local slot = tostring(players.LocalPlayer:GetAttribute('DataSlot') or '')
        local finish = function(reason)
            if state then
                return
            end

            state = reason

            if queue and queue.stopMovement == handle.stop then
                queue.stopMovement = nil
            end
            if connection then
                connection:Disconnect()
            end

            ag[handle] = nil

            stopLatencyTracking()
        end

        startLatencyTracking()

        connection = runService.PreSimulation:Connect(function(deltaTime)
            if queue and not executeQueue.valid(queue) then
                return finish('cancelled')
            end
            if not root or getRootPart() ~= root or not root.Parent then
                return finish('cancelled')
            end

            local ok, destination = pcall(resolveValue, target)

            if not ok or typeof(destination) ~= 'CFrame' or destination.Position.Magnitude >= 1000000 then
                return finish('invalid')
            end

            local offset = destination.Position - root.Position
            local distance = offset.Magnitude

            if distance ~= distance then
                return finish('invalid')
            end
            if objectiveKey and os.clock() - lastLogTick >= 1 then
                lastLogTick = os.clock()

                if not lastDistance or lastDistance - distance >= 5 then
                    lastDistance, lastMoveTick = distance, os.clock()

                    if queue then
                        executeQueue.progress(queue.owner, 'travel distance decreased')
                    end
                elseif os.clock() - lastMoveTick >= 20 then
                    retryCount = retryCount + 1
                    lastDistance, lastMoveTick = distance, os.clock()

                    if queue then
                        queue.owner.progress = 'Retrying travel (' .. math.min(retryCount, 2) .. '/2): no distance progress'
                    end
                    if retryCount > 2 then
                        local autoData = persistentData.get('auto') or {}
                        local travelRecord = autoData.travel_recovery
                        local isMatch = type(travelRecord) == 'table' and travelRecord.objective == objectiveKey and travelRecord.slot == slot

                        if queue then
                            queue.owner.progress = isMatch and 'Switching servers: travel stalled again' or 'Switching servers: travel stalled'
                        end

                        finish('stalled')
                        persistentData.stf('auto', 'travel_recovery', {
                            objective = objectiveKey,
                            slot = slot,
                            job = game.JobId,
                        })

                        if queue then
                            queue.owner.hopRequested = true
                            queue.owner.hopping = true
                        end

                        task.defer(function()
                            if queue and (queue.owner.generation ~= queue.generation or not queue.owner:armed()) then
                                return
                            end

                            local noEffects = a["Features/Game/NoEffects"]()

                            noEffects.hop(slot, true)
                        end)

                        return
                    end

                    root.AssemblyLinearVelocity = Vector3.zero
                end
            end

            root.AssemblyLinearVelocity = Vector3.zero

            if distance <= 0.5 then
                if objectiveKey then
                    local recoveryRecord = (persistentData.get('auto') or {}).travel_recovery

                    if type(recoveryRecord) == 'table' and recoveryRecord.objective == objectiveKey and recoveryRecord.slot == slot then
                        persistentData.stf('auto', 'travel_recovery', nil)
                    end
                end

                root.CFrame = destination

                return finish('arrived')
            end

            local step = aq and speed * math.max(0.6, 1 - ai) or speed
            local rootAttachment = root:FindFirstChild('RootAttachment')

            if rootAttachment and rootAttachment:FindFirstChild('AlignPosition') then
                ah = tick()
            end
            if tick() - ah < 1 then
                step = math.min(80, step * 0.75)
            end

            root.CFrame = safeNaN(root.CFrame + safeNaN(offset.Unit * math.min(step * deltaTime, distance)))
        end)
        handle.stop = function()
            finish('cancelled')
        end

        if queue then
            queue.stopMovement = handle.stop
        end

        handle.wait = function()
            while not state do
                if not root or getRootPart() ~= root or not root.Parent then
                    finish('cancelled')
                else
                    task.wait()
                end
            end

            return state == 'arrived', state
        end
        handle.status = function()
            return state
        end
        ag[handle] = true

        return handle
    end
    function af.stopAll()
        local items = {}

        for id in pairs(ag)do
            items[#items + 1] = id
        end
        for index, ar in ipairs(items)do
            ar.stop()
        end
    end
    function af.registerLagback()
        ah = tick()
    end

    return af
end


return aa()

]=],
    ["Features/Game/Tweening"] = [=[
local aa = function()
    local module = {
        active = false,
        queue = {},
    }
    local configuration = a["Utility/Configuration"]()
    local players = game:GetService('Players')
    local runService = game:GetService('RunService')

    module.update = function(deltaTime)
        module.active = false

        local current = module.current()

        if not current then
            return
        end

        local goalInstance = typeof(current.goal) == 'Instance' and current.goal or nil

        if goalInstance and not goalInstance.Parent then
            return module.stop(current.identifier)
        end

        local character = players.LocalPlayer and players.LocalPlayer.Character

        if not character then
            return
        end

        local root = character:FindFirstChild('HumanoidRootPart')

        if not root then
            return
        end

        module.active = true

        local rootPosition = root.Position
        local goalTransform = typeof(current.goal) == 'Instance' and current.goal.CFrame or current.goal
        local goalPosition = goalTransform.Position
        local distance = (goalPosition - rootPosition).Magnitude

        if distance <= 0.01 then
            return
        end

        local direction = (goalPosition - rootPosition) / distance
        local moveAmount = (configuration.expectOptionValue('TweenStudsPerSecond') or 200) * deltaTime
        local newPosition

        if moveAmount >= distance then
            newPosition = goalPosition
        else
            newPosition = rootPosition + (direction * moveAmount)
            newPosition = Vector3.new(newPosition.X, goalPosition.Y, newPosition.Z)
        end

        local orientation = (goalTransform - goalTransform.Position)
        local component1, component2, component3, component4, component5, component6, component7, component8, component9, component10, component11, component12 = orientation:GetComponents()

        if component4 == component4 and component5 == component5 and component6 == component6 and component7 == component7 and component8 == component8 and component9 == component9 and component10 == component10 and component11 == component11 and component12 == component12 then
            root.CFrame = CFrame.new(newPosition) * orientation
        else
            root.CFrame = CFrame.new(newPosition)
        end

        current.reached = false

        if (goalPosition - newPosition).Magnitude >= 1 then
            return
        end
        if current.swc then
            return module.stop(current.identifier)
        end

        current.reached = true
    end

    function module.get(identifier)
        for index, entry in next, module.queue do
            if entry.identifier == identifier then
                return index, entry
            end
        end

        return nil
    end
    function module.wait(identifier)
        local index, entry = module.get(identifier)

        if not entry then
            return
        end

        repeat
            task.wait()
        until entry.reached
    end
    function module.current()
        return module.queue[#module.queue]
    end
    function module.goal(identifier, goal, stopWhenComplete)
        local index, entry = module.get(identifier)

        if entry then
            entry.goal, entry.swc, entry.reached = goal, stopWhenComplete, false
        else
            table.insert(module.queue, 1, {
                identifier = identifier,
                goal = goal,
                swc = stopWhenComplete,
                reached = false,
            })
        end
    end
    function module.stop(identifier)
        local index = module.get(identifier)

        if index then
            table.remove(module.queue, index)
        end
    end

    do
        local noClip = a["Features/Game/NoClip"]()
        local didStep = false

        runService.Heartbeat:Connect(function(step)
            module.update(step)

            if module.active then
                noClip.step()

                didStep = true
            elseif didStep then
                if not configuration.expectToggleValue('NoClip') then
                    noClip.restore()
                end

                didStep = false
            end
        end)
    end

    return module
end


return aa()

