]=],
    ["Features/Visuals/AnimationReveal"] = [=[
local aa = function()
    local api = {}
    local configuration = a["Utility/Configuration"]()
    local players = game:GetService('Players')
    local ad = 0
    local getAnimationCategory = function(animationTrack)
        local priority = animationTrack.Priority

        if configuration.expectToggleValue('RevealHideAboveAction') and (priority == Enum.AnimationPriority.Action2 or priority == Enum.AnimationPriority.Action3 or priority == Enum.AnimationPriority.Action4) then
            return 0
        end
        if configuration.expectToggleValue('RevealCore') and priority == Enum.AnimationPriority.Core then
            return 1
        end
        if configuration.expectToggleValue('RevealIdle') and priority == Enum.AnimationPriority.Idle then
            return 1
        end
        if configuration.expectToggleValue('RevealZeroWeight') and animationTrack.WeightCurrent <= 0.01 then
            return 1
        end
        if configuration.expectToggleValue('RevealLowWeight') then
            local lowWeightThreshold = tonumber(configuration.expectOptionValue('RevealLowWeightThreshold')) or 0.5

            if animationTrack.WeightCurrent < lowWeightThreshold then
                return 1
            end
        end

        return nil
    end

    function api.tick()
        if not configuration.expectToggleValue('RevealAnimations') then
            return
        end

        local now = os.clock()

        if now - ad < 0.03 then
            return
        end

        ad = now

        local localPlayer = players.LocalPlayer

        for index, player in ipairs(players:GetPlayers())do
            if player == localPlayer then
                continue
            end

            local character = player.Character

            if not character then
                continue
            end

            local humanoid = character:FindFirstChildOfClass('Humanoid')
            local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')

            if not animator then
                continue
            end

            local ok, tracks = pcall(function()
                return animator:GetPlayingAnimationTracks()
            end)

            if not ok then
                continue
            end

            for trackIndex, track in ipairs(tracks)do
                local weight = getAnimationCategory(track)

                if weight ~= nil then
                    pcall(function()
                        track:AdjustWeight(weight, 0)
                    end)
                end
            end
        end
    end

    return api
end


return aa()

