            conns = {},
            last = {},
        }
    end
    local onCharacterRemoved = function(player, characterModel)
        local nameType = config.expectOptionValue('PlayerNameType')

        if nameType == 'Character Name' then
            return player:GetAttribute('CharacterName') or player.DisplayName
        elseif nameType == 'Roblox Username' then
            return player.Name
        end

        return player.DisplayName
    end
    local updateNameTag = function(playerModel, espItem)
        local character = playerModel.Character
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')

        if not humanoid then
            return
        end

        local last = espItem.last
        local as, maxHealth = humanoid.Health, humanoid.MaxHealth

        if as ~= last.h or maxHealth ~= last.mh then
            last.h, last.mh = as, maxHealth

            local healthRatio = (maxHealth and maxHealth > 0) and math.clamp(as / maxHealth, 0, 1) or 0

            espItem.barFill.Size = UDim2.fromScale(1, healthRatio)
            espItem.barFill.BackgroundColor3 = Color3.fromRGB(220, 60, 60):Lerp(enemyColor, healthRatio)

            local level = character:GetAttribute('Level') or -1

            espItem.infoLabel.Text = string.format('[%d/%d] [Lv. %d]', math.floor(as + 0.5), math.floor(maxHealth + 0.5), level)
        end

        local playerName = onCharacterRemoved(playerModel, character)

        if playerName ~= last.nm then
            last.nm = playerName
            espItem.nameLabel.Text = playerName
        end
    end
    local setEnabled = function(targetPlayer)
        if targetPlayer == players.LocalPlayer or espItems[targetPlayer] then
            return
        end

        local respawnHandler = function(newCharacter)
            if espItems[targetPlayer] then
                for index, connection in ipairs(espItems[targetPlayer].conns)do
                    pcall(function()
                        connection:Disconnect()
                    end)
                end

                pcall(function()
                    espItems[targetPlayer].gui:Destroy()
                end)

                espItems[targetPlayer] = nil
            end
            if not onCharacterAdded() then
                return
            end

            newCharacter:WaitForChild('HumanoidRootPart', 5)

            local espItemData = updateEspItem(newCharacter)

            if not espItemData then
                return
            end

            espItems[targetPlayer] = espItemData

            local humanoidModel = newCharacter:FindFirstChildOfClass('Humanoid')

            if humanoidModel then
                espItemData.conns[#espItemData.conns + 1] = humanoidModel.HealthChanged:Connect(function(
                )
                    if espItems[targetPlayer] then
                        updateNameTag(targetPlayer, espItems[targetPlayer])
                    end
                end)
            end

            updateNameTag(targetPlayer, espItemData)
        end
        local characterConn = targetPlayer.CharacterAdded:Connect(respawnHandler)

        if targetPlayer.Character then
            respawnHandler(targetPlayer.Character)
        end

        espItems[targetPlayer] = espItems[targetPlayer] or {
            conns = {characterConn},
            last = {},
        }

        if espItems[targetPlayer].conns then
            espItems[targetPlayer].conns[#espItems[targetPlayer].conns + 1] = characterConn
        end
    end
    local onCameraChanged = function(camera)
        local entry = espItems[camera]

        if not entry then
            return
        end

        for index, connection in ipairs(entry.conns or {})do
            pcall(function()
                connection:Disconnect()
            end)
        end

        if entry.gui then
            pcall(function()
                entry.gui:Destroy()
            end)
        end

        espItems[camera] = nil
    end
    local init = function()
        for camKey in next, espItems do
            onCameraChanged(camKey)
        end

        espItems = {}
    end

    function module.init()
        if espEnabled then
            return
        end

        espEnabled = true

        players.PlayerAdded:Connect(function(player)
            if onCharacterAdded() then
                setEnabled(player)
            end
        end)
        players.PlayerRemoving:Connect(onCameraChanged)

        local timer = 0

        currentTarget = runService.Heartbeat:Connect(function(delta)
            timer = timer + delta

            if timer < 0.5 then
                return
            end

            timer = 0

            if onCharacterAdded() then
                for indexPlayer, candidate in ipairs(players:GetPlayers())do
                    if candidate ~= players.LocalPlayer and not (espItems[candidate] and espItems[candidate].gui) then
                        setEnabled(candidate)
                    end
                end
                for key, espEntry in next, espItems do
                    if espEntry.gui then
                        updateNameTag(key, espEntry)
                    end
                end
            elseif next(espItems) then
                init()
            end
        end)
    end
    function module.detach()
        espEnabled = false

        if currentTarget then
            currentTarget:Disconnect()

            currentTarget = nil
        end

        init()
    end

    return module
end


return aa()

]=],
    ["Features/Visuals/Group"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local referencedMap = a["Utility/ReferencedMap"]()
    local players = game:GetService('Players')
    local palantirEvents = setmetatable({}, referencedMap)

    palantirEvents.__index = palantirEvents
    palantirEvents.object = function(instance, element)
        instance.count = instance.count + 1

        if not instance.warned and instance.count >= 500 then
            logger.warnNotify(
"(%s) Too many objects will cause your elements to stop updating.", element.identifier)

            instance.warned = true
        end
        if instance.count >= 500 then
            return
        end

        element:update()
    end
    palantirEvents._cacheTime = 0
    palantirEvents._splitUpdates = false
    palantirEvents._splitFrames = 4

    local reachRadius = 800 * 800

    palantirEvents._autoSplitActive = false

    local renderJumpPlates = function()
        local player = shared.Palantir_LP or players.LocalPlayer
        local character = player and player.Character
        local rootPart = character and character:FindFirstChild('HumanoidRootPart')

        if not rootPart then
            return 0
        end

        local rootPos = rootPart.Position
        local nearbyCount = 0

        for index, otherPlayer in next, players:GetPlayers()do
            if otherPlayer ~= player then
                local otherCharacter = otherPlayer.Character
                local otherRoot = otherCharacter and otherCharacter:FindFirstChild('HumanoidRootPart')

                if otherRoot then
                    local delta = otherRoot.Position - rootPos

                    if delta.X * delta.X + delta.Y * delta.Y + delta.Z * delta.Z <= reachRadius then
                        nearbyCount = nearbyCount + 1

                        if nearbyCount > 3 then
                            break
                        end
                    end
                end
            end
        end

        return nearbyCount
    end
    local isValidPlayer = function(target)
        if target.__type == 'FilteredESP' and target.object then
            return target.object
        end

        return target
    end
    local applyVisualEffect = function(element, camera, screenWidth, screenHeight)
        local entity = element.entity

        if not entity or not entity.Parent then
            return false
        end

        local position

        if entity:IsA('BasePart') then
            position = entity.Position
        elseif entity:IsA('Model') then
            local primaryPart = entity.PrimaryPart

            if primaryPart then
                position = primaryPart.Position
            else
                local rootPart = entity:FindFirstChild('HumanoidRootPart')

                if rootPart then
                    position = rootPart.Position
                end
            end
        end
        if not position then
            return false
        end

        local viewportPoint = camera:WorldToViewportPoint(position)

        return viewportPoint.Z < 0 or viewportPoint.X < -300 or viewportPoint.Y < -300 or viewportPoint.X > screenWidth + 300 or viewportPoint.Y > screenHeight + 300
    end

    palantirEvents.update = LPH_NO_VIRTUALIZE(function(element)
        local elements = element:data()

        if not configuration.idToggleValue(element.identifier, 'Enable') then
            return element:hide()
        end

        local now = os.clock()

        if now - palantirEvents._cacheTime > 0.5 then
            palantirEvents._cacheTime = now
            palantirEvents._splitUpdates = configuration.expectToggleValue('ESPSplitUpdates') == true
            palantirEvents._splitFrames = configuration.expectOptionValue('ESPSplitFrames') or 4

            if not palantirEvents._splitUpdates then
                local jumpCount = renderJumpPlates()

                palantirEvents._autoSplitActive = jumpCount > 3
            else
                palantirEvents._autoSplitActive = false
            end
        end

        local splitActive = palantirEvents._splitUpdates or palantirEvents._autoSplitActive
        local frames = palantirEvents._splitUpdates and palantirEvents._splitFrames or 4
        local camera = workspace.CurrentCamera
        local screenWidth, screenHeight = 0, 0

        if camera then
            local viewportSize = camera.ViewportSize

            screenWidth, screenHeight = viewportSize.X, viewportSize.Y
        end
        if splitActive then
            local total = #elements
            local chunkSize = math.ceil(total / frames)
            local partIndex = element.part
            local start = (partIndex - 1) * chunkSize + 1
            local finish = math.min(partIndex * chunkSize, total)

            for i = start, finish do
                local ay = elements[i]

                if ay then
                    local target = isValidPlayer(ay)

                    if camera and target.entity and applyVisualEffect(target, camera, screenWidth, screenHeight) then
                        if target.hideAll then
                            target:hideAll()
                        end

                        continue
                    end

                    element:object(ay)
                end
            end

            element.part = element.part + 1

            if element.part > frames then
                element.count = 0
                element.part = 1
            end
        else
            for index, at in next, elements do
                local target = isValidPlayer(at)

                if camera and target.entity and applyVisualEffect(target, camera, screenWidth, screenHeight) then
                    if target.hideAll then
                        target:hideAll()
                    end

                    continue
                end

                element:object(at)
            end

            element.part = 1
            element.count = 0
        end

        element.updated = true
    end)
    palantirEvents.build = LPH_NO_VIRTUALIZE(function(event)
        if not configuration.idToggleValue(event.identifier, 'Enable') then
            return
        end

        local camera = workspace.CurrentCamera
        local viewportSize = camera and camera.ViewportSize
        local viewportX = viewportSize and viewportSize.X or 0
        local viewportY = viewportSize and viewportSize.Y or 0

        for key, value in next, event:data()do
            local player = isValidPlayer(value)

            if player.elements then
                if camera and applyVisualEffect(player, camera, viewportX, viewportY) then
                    if player.hideAll then
                        player:hideAll()
                    end

                    continue
                end

                player:build()
            end
        end
    end)
    palantirEvents.hide = function(event)
        if not event.updated then
            return
        end

        for key, value in next, event:data()do
            value:visible(false)
        end

        event.updated = false
    end
    palantirEvents.detach = function(event)
        for key, value in next, event:data()do
            value:detach()
        end
    end

    function palantirEvents.new(identifier)
        local event = setmetatable(referencedMap.new(), palantirEvents)

        event.part = 1
        event.count = 0
        event.warned = false
        event.updated = true
        event.identifier = identifier

        return event
    end

    return palantirEvents
end


return aa()

