    ["Features/Visuals/InvisibleReveal"] = [=[
local aa = function()
    local module = {}
    local configuration = a["Utility/Configuration"]()
    local players = game:GetService('Players')
    local isPlayerInvisible = function(character)
        local success, result = pcall(function()
            return character:HasTag('InTacet') or character:GetAttribute('Invisible') == true
        end)

        return success and result
    end
    local resetLocalTransparency = function(model)
        for index, descendant in ipairs(model:GetDescendants())do
            if descendant:IsA('BasePart') and descendant.LocalTransparencyModifier ~= 0 then
                descendant.LocalTransparencyModifier = 0
            end
        end
    end

    function module.tick()
        if not configuration.expectToggleValue('AntiTacet') then
            return
        end

        local localPlayer = players.LocalPlayer

        for index, player in ipairs(players:GetPlayers())do
            if player == localPlayer then
                continue
            end

            local character = player.Character

            if character and isPlayerInvisible(character) then
                resetLocalTransparency(character)
            end
        end
    end

    return module
end


return aa()

]=],
    ["Features/Visuals/Objects/AttributeData"] = [=[
local aa = function()
    local module = {}

    module.__index = module

    function module:possible(other)
        local maxMental = math.max(self.base['Intelligence'], self.base['Willpower'], self.base['Charisma'])
        local maxPhysical = math.max(self.base['Strength'], self.base['Fortitude'], self.base['Agility'])

        for stat, points in pairs(other)do
            if self.weapon[stat] and self.weapon[stat] < points then
                return false
            end
            if self.attunement[stat] and self.attunement[stat] < points then
                return false
            end
            if self.base[stat] and self.base[stat] < points then
                return false
            end
            if stat == 'Mind' and maxMental < points then
                return false
            end
            if stat == 'Body' and maxPhysical < points then
                return false
            end
        end

        return true
    end
    function module:points()
        local total = 0

        for weaponStat, weaponPoints in pairs(self.weapon)do
            total = total + weaponPoints
        end
        for attunementStat, attunementPoints in pairs(self.attunement)do
            total = total + attunementPoints
        end
        for baseStat, basePoints in pairs(self.base)do
            total = total + basePoints
        end

        return total
    end
    function module:compare(target)
        for cmpWeaponStat, cmpWeaponPoints in pairs(self.weapon)do
            if target.weapon[cmpWeaponStat] == cmpWeaponPoints then
                continue
            end

            return false
        end
        for cmpAttunementStat, cmpAttunementPoints in pairs(self.attunement)do
            if target.attunement[cmpAttunementStat] == cmpAttunementPoints then
                continue
            end

            return false
        end
        for cmpBaseStat, cmpBasePoints in pairs(self.base)do
            if target.base[cmpBaseStat] == cmpBasePoints then
                continue
            end

            return false
        end

        return true
    end
    function module:load(data)
        if typeof(data.weapon) == 'table' then
            self.weapon = data.weapon
        end
        if typeof(data.attunement) == 'table' then
            self.attunement = data.attunement
        end
        if typeof(data.base) == 'table' then
            self.base = data.base
        end
    end
    function module.new(source)
        local obj = setmetatable({}, module)

        obj.weapon = {}
        obj.attunement = {}
        obj.base = {}

        if source then
            obj:load(source)
        end

        return obj
    end

    return module
end


return aa()

