]=],
    ["Features/Visuals/Objects/BuilderData"] = [=[
local aa = function()
    local attributeData = a["Features/Visuals/Objects/AttributeData"]()
    local configuration = a["Utility/Configuration"]()
    local deepwokenData = a["Features/Visuals/Objects/DeepwokenData"]()
    local exports = {}

    exports.__index = exports

    function exports:attributes(attributes)
        return (self:ipre(attributes) == 0) and self.pre or self.post
    end
    function exports:ipre(attributes)
        local total = 0

        for statName, statValue in next, attributes do
            if typeof(statName) ~= 'string' or not statName:match('Stat') then
                continue
            end
            if typeof(statValue) ~= 'number' then
                continue
            end

            total = total + statValue
        end

        local prePoints = self.pre:points()
        local shrineOverride = configuration.expectOptionValue('ShrineOverrideState')

        if not configuration.expectToggleValue('ShrineDetectionOverride') then
            shrineOverride = nil
        end
        if shrineOverride == 'Pre-Shrine' then
            return 0
        end
        if shrineOverride == 'Post-Shrine' then
            return 1
        end
        if shrineOverride == 'Must Shrine' then
            return 2
        end
        if not self:dshrine() then
            return 1
        end
        if total < prePoints then
            return 0
        end
        if total == prePoints then
            return 2
        end

        return 1
    end
    function exports:dshrine()
        return not self.pre:compare(self.post)
    end
    function exports:load(data)
        if typeof(data.talents) == 'table' then
            self.talents = data.talents
        end
        if typeof(data.mantras) == 'table' then
            self.mantras = data.mantras
        end

        for index, talentName in next, self.talents do
            local talentClean = talentName:gsub('%s*%[.-%]$', '')

            if talentClean ~= talentName then
                self.talents[index] = talentClean
            end
        end
        for index, mantraName in next, self.mantras do
            local mantraClean = mantraName:gsub('%s*%[.-%]$', '')

            if mantraClean ~= mantraName then
                self.mantras[index] = mantraClean
            end
        end

        if typeof(data.preShrine) == 'table' then
            self.pre:load(data.preShrine)
        end
        if typeof(data.attributes) == 'table' then
            self.post:load(data.attributes)
        end

        local stats = data.stats

        if typeof(stats) ~= 'table' then
            return
        end

        local traits = stats.traits

        if typeof(traits) ~= 'table' then
            return
        end

        self.traits['Vitality'] = traits['Vitality'] or 0
        self.traits['Erudition'] = traits['Erudition'] or 0
        self.traits['Proficiency'] = traits['Proficiency'] or 0
        self.traits['Songchant'] = traits['Songchant'] or 0
    end
    function exports.new(ae, af)
        local instance = setmetatable({}, exports)

        instance.ddata = deepwokenData.new(af)
        instance.talents = {}
        instance.mantras = {}
        instance.pre = attributeData.new()
        instance.post = attributeData.new()
        instance.traits = {
            ['Vitality'] = 0,
            ['Erudition'] = 0,
            ['Proficiency'] = 0,
            ['Songchant'] = 0,
        }

        if ae then
            instance:load(ae)
        end

        return instance
    end

    return exports
end


return aa()

