]=],
    ["Features/Visuals/Objects/DeepwokenData"] = [=[
local aa = function()
    local module = {}

    module.__index = module

    function module:get(name)
        return self.talents[string.lower(name)] or self.mantras[string.lower(name)]
    end
    function module:possible(name, filter)
        local item = self:get(name)

        if not item then
            return false
        end

        local reqs = item.reqs

        if not reqs then
            return false
        end

        local merged = {}

        for req, count in pairs(reqs.base)do
            merged[req] = count
        end
        for req, count in pairs(reqs.weapon)do
            merged[req] = count
        end
        for req, count in pairs(reqs.attunement)do
            merged[req] = count
        end

        return filter:possible(merged)
    end
    function module:load(data)
        if typeof(data.talents) == 'table' then
            self.talents = data.talents
        end
        if typeof(data.mantras) == 'table' then
            self.mantras = data.mantras
        end
    end
    function module.new(data)
        local ac = setmetatable({}, module)

        ac.talents = {}
        ac.mantras = {}

        if data then
            ac:load(data)
        end

        return ac
    end

    return module
end


return aa()

