local aa = function()
    local configuration = a["Utility/Configuration"]()
    local drawingLib = a["GUI/DrawingLib"]()
    local maid = a["Utility/Maid"]()
    local signal = a["Utility/Signal"]()
    local taskSpawner = a["Utility/TaskSpawner"]()
    local af = {}

    af.__index = af
    af.__type = 'EntityESP'

    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local tweenService = game:GetService('TweenService')
    local aj = {
        time = 0,
        cacheVersion = 0,
        boxThickness = 1,
        customBoxColor = false,
        boxColor = Color3.new(1, 1, 1),
        boxOpacity = 0.65,
        boxFill = true,
        boxFillColor = Color3.fromRGB(12, 12, 12),
        boxFillOpacity = 0.45,
        barWidth = 6,
        barHeight = 3,
        barOutline = true,
        barOutlineColor = Color3.fromRGB(10, 10, 10),
        barBackground = true,
        barBackgroundColor = Color3.fromRGB(25, 25, 25),
        barSeparators = true,
        barSeparatorColor = Color3.fromRGB(15, 15, 15),
        fontSize = 13,
        font = 2,
        textOutline = true,
        textOutlineColor = Color3.new(0, 0, 0),
        textBackground = true,
        textBackgroundColor = Color3.fromRGB(12, 12, 12),
        textBackgroundOpacity = 0.6,
        ids = {},
    }
    local onSettingsChanged = function()
        local startTime = os.clock()

        if startTime - aj.time < 0.2 then
            return
        end

        aj.time = startTime
        aj.cacheVersion = aj.cacheVersion + 1
        aj.boxThickness = configuration.expectOptionValue('ESPBoxThickness') or 1
        aj.customBoxColor = configuration.expectToggleValue('ESPCustomBoxColor') == true
        aj.boxColor = configuration.expectOptionValue('ESPBoxColor') or Color3.new(1, 1, 1)
        aj.boxOpacity = (configuration.expectOptionValue('ESPBoxOpacity') or 65) / 100
        aj.boxFill = configuration.expectToggleValue('ESPBoxFill') ~= false
        aj.boxFillColor = configuration.expectOptionValue('ESPBoxFillColor') or Color3.fromRGB(12, 12, 12)
        aj.boxFillOpacity = (configuration.expectOptionValue('ESPBoxFillOpacity') or 45) / 100
        aj.barWidth = configuration.expectOptionValue('ESPBarWidth') or 6
        aj.barHeight = configuration.expectOptionValue('ESPBarHeight') or 3
        aj.barOutline = configuration.expectToggleValue('ESPBarOutline') ~= false
        aj.barOutlineColor = configuration.expectOptionValue('ESPBarOutlineColor') or Color3.fromRGB(10, 10, 10)
        aj.barBackground = configuration.expectToggleValue('ESPBarBackground') ~= false
        aj.barBackgroundColor = configuration.expectOptionValue('ESPBarBackgroundColor') or Color3.fromRGB(25, 25, 25)
        aj.barSeparators = configuration.expectToggleValue('ESPBarSeparators') ~= false
        aj.barSeparatorColor = configuration.expectOptionValue('ESPBarSeparatorColor') or Color3.fromRGB(15, 15, 15)
        aj.fontSize = configuration.expectOptionValue('FontSize') or 13
        aj.font = drawingLib.mapFont(configuration.expectOptionValue('Font') or 'Plex')

        local textOutline = configuration.expectToggleValue('ESPTextOutline')

        aj.textOutline = textOutline == nil or textOutline
        aj.textOutlineColor = configuration.expectOptionValue('ESPTextOutlineColor') or Color3.new(0, 0, 0)
        aj.textBackground = configuration.expectToggleValue('ESPTextBackground') ~= false
        aj.textBackgroundColor = configuration.expectOptionValue('ESPTextBackgroundColor') or Color3.fromRGB(12, 12, 12)
        aj.textBackgroundOpacity = (configuration.expectOptionValue('ESPTextBackgroundOpacity') or 60) / 100
    end
    local applyEspStyle = function(group)
        if group._styleVersion == aj.cacheVersion then
            return
        end

        group._styleVersion = aj.cacheVersion

        if group.box then
            group.box.inner.Thickness = math.max(aj.boxThickness, 1)
            group.box.inner.Color = aj.customBoxColor and aj.boxColor or Color3.fromRGB(180, 180, 180)
            group.box.inner.Transparency = aj.boxOpacity
            group.box.outer.Transparency = aj.boxOpacity

            if group.box.bg then
                group.box.bg.Color = aj.boxFillColor
                group.box.bg.Transparency = aj.boxFillOpacity
            end
        end

        for side, entries in next, group.elements do
            local isHorizontal = side == 'left' or side == 'right'

