        end

        local cframe = root.CFrame
        local position = cframe.Position
        local minX, minY, minZ = math.huge, math.huge, math.huge
        local maxX, maxY, maxZ = -math.huge, -math.huge, -math.huge
        local found = false

        for childIndex, child in next, model:GetChildren()do
            if child:IsA('BasePart') and (child.Position - position).Magnitude <= 8 then
                found = true

                local localPosition = cframe:PointToObjectSpace(child.Position)
                local size = child.Size
                local halfX, halfY, halfZ = size.X * 0.5, size.Y * 0.5, size.Z * 0.5

                if localPosition.X - halfX < minX then
                    minX = localPosition.X - halfX
                end
                if localPosition.Y - halfY < minY then
                    minY = localPosition.Y - halfY
                end
                if localPosition.Z - halfZ < minZ then
                    minZ = localPosition.Z - halfZ
                end
                if localPosition.X + halfX > maxX then
                    maxX = localPosition.X + halfX
                end
                if localPosition.Y + halfY > maxY then
                    maxY = localPosition.Y + halfY
                end
                if localPosition.Z + halfZ > maxZ then
                    maxZ = localPosition.Z + halfZ
                end
            end
