    ["Features/Visuals/Objects/FilteredESP"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local ab = {}

    ab.__index = ab
    ab.__type = 'FilteredESP'

    local textMatchesAnyPattern = function(patterns, text)
        for index, pattern in next, patterns do
            if not text:lower():match(pattern:lower()) then
                continue
            end

            return true
        end

        return false
    end

    function ab:visible(visible)
        self.object:visible(visible)
    end
    function ab:detach()
        self.object:detach()
    end

    ab.update = LPH_NO_VIRTUALIZE(function(entry)
        local espObject = entry.object
        local identifier = entry.identifier
        local label = espObject.label

        if configuration.idToggleValue(identifier, 'FilterObjects') then
            local filterList = configuration.idOptionValues(identifier, 'FilterLabelList')
            local filterType = configuration.idOptionValue(identifier, 'FilterLabelListType')
            local matches = textMatchesAnyPattern(filterList, label)

            if filterType == 'Hide Labels Out Of List' and not matches then
                return entry:visible(false)
            end
            if filterType == 'Hide Labels In List' and matches then
                return entry:visible(false)
            end
        end

        espObject:update()

        entry.delayTimestamp = espObject.delayTimestamp
    end)

    function ab.new(object)
        local instance = setmetatable({}, ab)

        instance.object = object
        instance.identifier = object.identifier
        instance.delayTimestamp = object.delayTimestamp

        return instance
    end

    return ab
end


return aa()

