]=],
    ["Features/Visuals/Objects/PlayerESP"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local drawingLib = a["GUI/DrawingLib"]()
    local entityESP = a["Features/Visuals/Objects/EntityESP"]()
    local playerScanning = a["Game/PlayerScanning"]()

    game:GetService('ReplicatedStorage')

    local countThrownWelds = function(character)
        local thrownFolder = workspace:FindFirstChild('Thrown')

        if not thrownFolder then
            return 0
        end

        local weldCount = 0

        for index, thrownChild in next, thrownFolder:GetChildren()do
            if thrownChild.Name:find('MetalCombo', 1, true) then
                local weld = thrownChild:FindFirstChild('Weld') or thrownChild:FindFirstChildOfClass('Weld')
                local weldPart0 = weld and weld.Part0

                if weldPart0 and weldPart0.Parent == character then
                    weldCount = weldCount + 1
                end
            end
        end

        return weldCount
    end
    local entityESPClass = setmetatable({}, {__index = entityESP})

    entityESPClass.__index = entityESPClass
    entityESPClass.__type = 'PlayerESP'

    local players = game:GetService('Players')
    local hasOathItem = function(candidatePlayer)
        local backpack = candidatePlayer:FindFirstChildOfClass('Backpack')

        if not backpack then
            return false
        end

        for itemIndex, backpackItem in next, backpack:GetChildren()do
            if not backpackItem.Name:match('Oath') then
                continue
            end

            return true
        end

        return false
    end

    entityESPClass._updateBar = function(ai, configId, barName, bar, statValue)
        if not bar then
            return
        end

        local toggleEnabled = configuration.idToggleValue(configId, barName)

        bar.visible = toggleEnabled

        if not toggleEnabled then
            return
        end

        local fraction = 0

        if statValue then
            local statMaxValue = statValue.MaxValue

            if type(statMaxValue) == 'number' and statMaxValue > 0 then
                fraction = statValue.Value / statMaxValue
            end
        end

        ai.mbs(bar, bar.vertical, fraction)

        local fill = ai.gb(bar)

        if not fill then
            return
        end

        fill.Color = configuration.idOptionValue(configId, barName .. 'Color') or Color3.new(0, 0, 0)
    end
    entityESPClass.update = LPH_NO_VIRTUALIZE(function(esp)
        local localPlayer = players.LocalPlayer
        local localCharacter = localPlayer.Character
        local localHumanoid = localCharacter and localCharacter:FindFirstChildOfClass('Humanoid')
        local localRoot = localCharacter and localCharacter:FindFirstChild('HumanoidRootPart')

        if not localRoot then
            return esp:visible(false)
        end
        if not localHumanoid then
            return esp:visible(false)
        end

        local entity = esp.entity
        local player = esp.player
        local identifier = esp.identifier
        local targetHumanoid = entity:FindFirstChildOfClass('Humanoid')

        if not targetHumanoid then
            return esp:visible(false)
        end

        local targetRoot = entity:FindFirstChild('HumanoidRootPart')

        if not targetRoot then
            return esp:visible(false)
        end
        if playerScanning.isAlly(player) and configuration.idToggleValue(identifier, 'HideIfAlly') and configuration.idToggleValue(identifier, 'MarkAllies') then
            return esp:visible(false)
        end

        local healthStatus = 'NEUTRAL'
        local healthDelta = localHumanoid.Health - targetHumanoid.Health
        local healthColor = Color3.new(1, 1, 1)

        if healthDelta < 0 then
            healthStatus = 'UNDER'
        end
        if healthDelta < -50 then
            healthColor = Color3.new(1, 0, 0)
        end
        if healthDelta > 0 then
            healthStatus = 'OVER'
        end
        if healthDelta > 50 then
            healthColor = Color3.new(0, 1, 0)
        end

        local healthContainer = esp.fcontainer
        local distance = (localRoot.Position - targetRoot.Position).Magnitude

        if healthContainer and healthContainer.text then
            esp:utext(healthContainer, string.format('%s\n%iHP', healthStatus, math.ceil(healthDelta)))

            healthContainer.text.Color = healthColor
            healthContainer.visible = configuration.idToggleValue(identifier, 'ShowHealthComparison') and distance <= 150
        end

        esp._updateBar(esp, identifier, 'ArmorBar', esp.abar, entity:FindFirstChild('Armor'))
        esp._updateBar(esp, identifier, 'PostureBar', esp.pbar, entity:FindFirstChild('BreakMeter'))
        esp._updateBar(esp, identifier, 'BloodBar', esp.bbar, entity:FindFirstChild('Blood'))
        esp._updateBar(esp, identifier, 'TempoBar', esp.tbar, entity:FindFirstChild('Tempo'))
        esp._updateBar(esp, identifier, 'SanityBar', esp.sbar, entity:FindFirstChild('Sanity'))

        local rodBar = esp.rbar

        if rodBar then
            local rodToggle = configuration.idToggleValue(identifier, 'RodBar')

            rodBar.visible = rodToggle

            if rodToggle then
                local thrownComboCount = countThrownWelds(entity)

                esp.mbs(rodBar, false, math.clamp(thrownComboCount / 9, 0, 1))

                local rodFill = esp.gb(rodBar)

                if rodFill then
                    if thrownComboCount >= 5 then
                        rodFill.Color = Color3.fromRGB(220, 40, 40)
                    else
                        rodFill.Color = configuration.idOptionValue(identifier, 'RodBarColor') or Color3.fromRGB(150, 150, 150)
                    end
                end
            end
        end

        esp._hpOverlayFrac = 0

        if configuration.idToggleValue(identifier, 'PoserDamagePredict') then
            local poserStored = shared.Palantir_PoserStored
            local poserData = poserStored and poserStored[player]

            if poserData and (os.clock() - poserData.at) < 300 and targetHumanoid.MaxHealth and targetHumanoid.MaxHealth > 0 then
                esp._hpOverlayFrac = math.clamp(poserData.dmg / targetHumanoid.MaxHealth, 0, 0.7)
            end
        end

        local level = entity:GetAttribute('Level') or -1
        local nameType = configuration.idOptionValue(identifier, 'PlayerNameType')
        local playerName = 'Unknown Player'

        if nameType == 'Character Name' then
            playerName = player:GetAttribute('CharacterName')
        elseif nameType == 'Roblox Display Name' then
            playerName = player.DisplayName
        elseif nameType == 'Roblox Username' then
            playerName = player.Name
        end

        esp.label = playerName

        local labelParts = {
            ('[%i/%i]'):format(targetHumanoid.Health or -1, targetHumanoid.MaxHealth or -1),
            ('[Power %i]'):format(level),
        }
        local updateStatLabel = function(labelPrefix, toggleName, statName, maxField)
            if not configuration.idToggleValue(identifier, toggleName) then
                return
            end

            local statObject = entity:FindFirstChild(statName)

            if not statObject then
                return
            end

            local maxValue = maxField and statObject[maxField] or statObject.MaxValue

            if not maxValue or maxValue <= 0 then
                return
            end

            local percent = math.floor((statObject.Value / maxValue) * 100 + 0.5)

            labelParts[#labelParts + 1] = ('[%s %i%%]'):format(labelPrefix, percent)
        end

        if configuration.idToggleValue(identifier, 'ShowHealthPercent') and targetHumanoid.MaxHealth > 0 then
            local healthPercent = math.floor((targetHumanoid.Health / targetHumanoid.MaxHealth) * 100 + 0.5)

            labelParts[#labelParts + 1] = ('[%s %i%%]'):format('HP', healthPercent)
        end

        updateStatLabel('Sanity', 'ShowSanityPercent', 'Sanity')
        updateStatLabel('Ether', 'ShowEtherPercent', 'Ether')
        updateStatLabel('Posture', 'ShowPosturePercent', 'BreakMeter')
        updateStatLabel('Tempo', 'ShowTempoPercent', 'Tempo')

        local dangerExpiration = targetHumanoid:GetAttribute('DangerExpiration')
        local dangerTime = dangerExpiration and math.ceil(dangerExpiration - workspace:GetServerTimeNow())

        if configuration.idToggleValue(identifier, 'ShowDangerTime') and dangerTime and dangerTime >= 0 then
            labelParts[#labelParts + 1] = ('[%s]'):format(dangerTime >= 60 and os.date('%Mm %Ss', dangerTime) or os.date('%Ss', dangerTime))
        end

        entityESP.update(esp, labelParts)

        local nameText = esp.ncontainer and esp.ncontainer.text

        if not nameText then
            return
        end

        local targetBackpack = player:FindFirstChildOfClass('Backpack')

        if not targetBackpack then
            return
        end
        if configuration.idToggleValue(identifier, 'MarkSackUsers') and entity:FindFirstChild('Sack') then
            nameText.Color = configuration.idOptionValue(identifier, 'SackColor')
        end
        if configuration.idToggleValue(identifier, 'MarkOathUsers') and hasOathItem(player) then
            nameText.Color = configuration.idOptionValue(identifier, 'OathColor')
        end
        if configuration.idToggleValue(identifier, 'MarkAllies') and playerScanning.isAlly(player) then
            nameText.Color = configuration.idOptionValue(identifier, 'AlPalantirolor')
        end

        local subText = esp.dcontainer and esp.dcontainer.text

        if subText then
            subText.Color = nameText.Color
        end
    end)
    entityESPClass.extra = function(entity)
        entity.abar = entity:add('ArmorBar', 'left', 6)

        entity:cgb(entity.abar, false, true, Color3.new(1, 1, 1))

        entity.pbar = entity:add('PostureBar', 'bottom', 3)

        entity:cgb(entity.pbar, false, false, Color3.new(1, 1, 1))

        entity.bbar = entity:add('BloodBar', 'bottom', 3)

        entity:cgb(entity.bbar, false, false, Color3.new(1, 1, 1))

        entity.tbar = entity:add('TempoBar', 'bottom', 3)

        entity:cgb(entity.tbar, false, false, Color3.new(1, 1, 1))

        entity.sbar = entity:add('SanityBar', 'bottom', 3)

        entity:cgb(entity.sbar, false, false, Color3.new(1, 1, 1))

        entity.rbar = entity:add('RodBar', 'bottom', 6)

        entity:cgb(entity.rbar, false, false, Color3.new(0.6, 0.6, 0.6))

        entity.fcontainer = entity:add('Flags', 'right', 16)
        entity.fcontainer.text = drawingLib.text({Size = 8})
    end

    function entityESPClass.new(uuid, player, world)
        local instance = setmetatable(entityESP.new(world, uuid, 'Unknown Player'), entityESPClass)

        instance.player = player
        instance.identifier = uuid

        instance:setup()
        instance:build()
        instance:update()

        return instance
    end

    return entityESPClass
end


return aa()

]=],
    ["Features/Visuals/SoundVisualizer"] = [=[
local aa = function()
    local soundVisualizer = {}
    local effectReplicator = a["Game/EffectReplicator"]()
    local partTriggers = a["Game/Timings/PartTriggers"]()
    local audioScanner = a["Game/Timings/AudioScanner"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')

    soundVisualizer.maxEntries = 300
    soundVisualizer.radius = 150
    soundVisualizer.logging = true
    soundVisualizer.always = false
    soundVisualizer.watching = false
    soundVisualizer.stacking = true
    soundVisualizer.kinds = {
        effect = true,
        part = true,
        sound = true,
    }
    soundVisualizer.sampleWindow = 8
    soundVisualizer.maxSamples = 480
    soundVisualizer.maxVisuals = 24
    soundVisualizer.seen = 0
    soundVisualizer.dropped = 0

    local ah = {}
    local ai = {}
    local aj = {}
    local ak = {}
    local al = false
    local am = {}
    local broadcastPayload = function(payload)
        for i = 1, #ai do
            pcall(ai[i], payload)
        end
    end
    local runCallbacks = function()
        for j = 1, #aj do
            pcall(aj[j])
        end
    end
    local getRootPart = function()
        local localPlayer = players.LocalPlayer
        local character = localPlayer and localPlayer.Character

        return character and character:FindFirstChild('HumanoidRootPart')
    end
    local getPosition = function(instance, fallback, override)
        if typeof(override) == 'Vector3' then
            return override
        end
        if instance then
            local part = instance:FindFirstChild('HumanoidRootPart') or instance:FindFirstChildWhichIsA('BasePart', true)

            if part then
                return part.Position
            end
        end

        local current = fallback

        while current and current ~= workspace do
            if current:IsA('BasePart') then
                return current.Position
            end
            if current:IsA('Attachment') then
                return current.WorldPosition
            end

            current = current.Parent
        end

        return nil
    end
    local readProperty = function(target, key)
        local ok, result = pcall(function()
            return target[key]
        end)

        if ok then
            return result
        end

        return nil
    end
    local formatValue = function(value)
        local valueType = typeof(value)

        if valueType == 'Vector3' then
            return string.format('%.2f, %.2f, %.2f', value.X, value.Y, value.Z)
        end
        if valueType == 'CFrame' then
            local position = value.Position

            return string.format('%.2f, %.2f, %.2f', position.X, position.Y, position.Z)
        end
        if valueType == 'Color3' then
            return string.format('%d, %d, %d', value.R * 255, value.G * 255, value.B * 255)
        end
        if valueType == 'Instance' then
            local success, fullName = pcall(function()
                return value:GetFullName()
            end)

            return success and fullName or value.Name
        end
        if valueType == 'EnumItem' then
            return value.Name
        end
        if valueType == 'number' then
            if value == math.floor(value) then
                return string.format('%d', value)
            end

            return string.format('%.3f', value)
        end

        return tostring(value)
    end

    soundVisualizer._show = formatValue

    local at = {
        'ClassName',
        'Size',
        'Position',
        'Orientation',
        'Transparency',
        'Color',
        'Material',
        'Anchored',
        'CanCollide',
        'CanTouch',
        'CanQuery',
        'AssemblyLinearVelocity',
        'Massless',
        'Shape',
    }
    local au = {
        'ClassName',
        'SoundId',
        'AssetId',
        'Volume',
        'PlaybackSpeed',
        'TimeLength',
        'TimePosition',
        'Looped',
        'Playing',
        'RollOffMinDistance',
        'RollOffMaxDistance',
        'RollOffMode',
        'SoundGroup',
        'PlayOnRemove',
    }
    local av = {
        ParticleEmitter = true,
        Trail = true,
        Beam = true,
        Smoke = true,
        Fire = true,
        Sparkles = true,
        PointLight = true,
        SpotLight = true,
        SurfaceLight = true,
    }
    local aw = {
        'char',
        'part',
        'att',
        'pos',
        'Pos',
        'rPos',
        'cf',
        'effrange',
        'low_graphics',
    }
    local collectProperties = function(object, properties)
        local rows = {}

        if not object then
            return rows
        end

        for index = 1, #properties do
            local property = properties[index]
            local propValue = readProperty(object, property)

            if propValue ~= nil then
                rows[#rows + 1] = {
                    property,
                    formatValue(propValue),
                }
            end
        end

        return rows
    end
    local cloneVisual = function(safeClone)
        local ok, clonedVisual = pcall(function()
            local wasArchivable = safeClone.Archivable

            safeClone.Archivable = true

            local aA = safeClone:Clone()

            safeClone.Archivable = wasArchivable

            return aA
        end)

        if ok then
            return clonedVisual
        end

        return nil
    end
    local captureVisual = function(state, visualInstance)
        if state.visualCount >= soundVisualizer.maxVisuals then
            return
        end
        if state.grabbed[visualInstance] or not av[visualInstance.ClassName] then
            return
        end

        state.grabbed[visualInstance] = true

        local clonedVisual = cloneVisual(visualInstance)

        if clonedVisual then
            clonedVisual.Parent = state.visual
            state.visualCount = state.visualCount + 1
        end
    end
    local processDescendants = function(state, visualInstance)
        local ok, descendants = pcall(function()
            return visualInstance:GetDescendants()
        end)

        if ok then
            for index = 1, #descendants do
                captureVisual(state, descendants[index])
            end
        end

        local ok, connection = pcall(function()
            return visualInstance.DescendantAdded:Connect(function(descendant)
                captureVisual(state, descendant)
            end)
        end)

        return ok and connection or nil
    end

    soundVisualizer._grabVisuals = processDescendants

    local startStopwatch = function(state, trackedInst)
        if state.stopWatch then
            state.stopWatch()
        end

        local startTime = os.clock()
        local stopped = false
        local conn
        local finish = function(fate)
            if stopped then
                return
            end

            stopped = true
            state.sampled = true
            state.fate = fate
            state.died = os.clock() - startTime
            state.stopWatch = nil

            if conn then
                conn:Disconnect()
            end
            if state.grabConn then
                pcall(function()
                    state.grabConn:Disconnect()
                end)

                state.grabConn = nil
            end

            -- Keep `am` bounded: remove this stopwatch's connection once it
            -- finishes, otherwise every captured event leaves a live PreRender
            -- connection (and its closure state) behind, growing `am` unbounded.
            if conn then
                for i = #am, 1, -1 do
                    if am[i] == conn then
                        table.remove(am, i)

                        break
                    end
                end
            end

            broadcastPayload(state)
        end

        state.stopWatch = finish
        conn = runService.PreRender:Connect(function()
            local elapsed = os.clock() - startTime

            if not state.placed then
                state.placed = true

                local origin = getRootPart()
                local here = getPosition(nil, trackedInst, nil)

                if origin and here then
                    state.dist = (here - origin.Position).Magnitude

                    if state.dist > soundVisualizer.radius then
                        soundVisualizer.dropped = soundVisualizer.dropped + 1

                        finish('out of range')
                        soundVisualizer.remove(state)

                        return
                    end
                end
            end
            if readProperty(trackedInst, 'Parent') == nil then
                return finish('destroyed')
            end
            if #state.samples < soundVisualizer.maxSamples then
                local sample = {t = elapsed}

                if state.kind == 'sound' then
                    sample.position = tonumber(readProperty(trackedInst, 'TimePosition')) or 0
                    sample.volume = tonumber(readProperty(trackedInst, 'Volume')) or 0
                    sample.playing = readProperty(trackedInst, 'Playing') and 1 or 0
                else
                    local posValue = readProperty(trackedInst, 'Position')

                    if typeof(posValue) == 'Vector3' then
                        sample.x, sample.y, sample.z = posValue.X, posValue.Y, posValue.Z
                    end

                    local sizeValue = readProperty(trackedInst, 'Size')

                    if typeof(sizeValue) == 'Vector3' then
                        sample.size = sizeValue.Magnitude
                    end

                    sample.transparency = tonumber(readProperty(trackedInst, 'Transparency')) or 0
                end

                state.samples[#state.samples + 1] = sample
            end
            if elapsed >= soundVisualizer.sampleWindow or #state.samples >= soundVisualizer.maxSamples then
                finish('still alive')
            end
        end)
        am[#am + 1] = conn
    end

    function soundVisualizer.fateText(state)
        if not state.inst then
            return 'no instance to follow'
        end
        if not state.sampled then
            return 'watching\u{2026}'
        end

        local diedText = state.died and string.format('%.2fs', state.died) or '?'

        if state.fate == 'destroyed' then
            return 'destroyed after ' .. diedText
        end

        return (state.fate or '?') .. ' at ' .. diedText
    end
    function soundVisualizer.travel(source)
        local samples = source.samples

        if not samples or #samples < 2 then
            return nil
        end

        local total = 0
        local prev

        for index = 1, #samples do
            local sample = samples[index]

            if sample.x then
                if prev then
                    local dx, dy, dz = sample.x - prev.x, sample.y - prev.y, sample.z - prev.z

                    total = total + math.sqrt(dx * dx + dy * dy + dz * dz)
                end

                prev = sample
            end
        end

        if not prev then
            return nil
        end

        return total
    end

    local logEvent = function(kind, trigger, entity, inst, position, data)
        if not (al and soundVisualizer.logging) then
            return
        end
        if not (soundVisualizer.watching or soundVisualizer.always) then
            return
        end
        if not soundVisualizer.kinds[kind] then
            return
        end
        if ak[trigger] then
            return
        end

        soundVisualizer.seen = soundVisualizer.seen + 1

        local dist
        local originPos = getRootPart()
        local eventPos = getPosition(entity, inst, position)

        if originPos and eventPos then
            dist = (eventPos - originPos.Position).Magnitude
        end
        if dist and dist > soundVisualizer.radius and not inst then
            soundVisualizer.dropped = soundVisualizer.dropped + 1

            return
        end

        local player = entity and players:GetPlayerFromCharacter(entity)
        local sourceType = 'World'

        if player then
            sourceType = 'Player'
        elseif entity then
            sourceType = 'Mob'
        end
        if soundVisualizer.stacking then
            for entryIndex = #ah, 1, -1 do
                local entry = ah[entryIndex]

                if entry.trigger == trigger and entry.entity == entity then
                    entry.count = entry.count + 1
                    entry.at = os.clock()
                    entry.dist = dist

                    broadcastPayload(entry)

                    return
                end
            end
        end

        local newEntry = {
            kind = kind,
            trigger = trigger,
            id = trigger:match('^%w+:(.*)$') or trigger,
            at = os.clock(),
            count = 1,
            entity = entity,
            source = sourceType,
            sourceName = (player and player.Name) or (entity and entity.Name) or 'world',
            dist = dist,
            inst = inst,
            samples = {},
            sampled = false,
            fate = nil,
            props = {},
            grabbed = setmetatable({}, {
                __mode = 'k',
            }),
            visualCount = 0,
        }
        local ok, model = pcall(function()
            return Instance.new('Model')
        end)

        newEntry.visual = ok and model or nil

        if newEntry.visual then
            newEntry.visual.Name = 'Preview'
        end
        if inst then
            newEntry.path = formatValue(inst)
            newEntry.class = readProperty(inst, 'ClassName')
            newEntry.props = collectProperties(inst, kind == 'sound' and au or at)

            if kind == 'sound' then
                newEntry.soundId = readProperty(inst, 'AssetId') or readProperty(inst, 'SoundId')
                newEntry.length = tonumber(readProperty(inst, 'TimeLength'))
                newEntry.volume = tonumber(readProperty(inst, 'Volume')) or 0.5
                newEntry.speed = tonumber(readProperty(inst, 'PlaybackSpeed')) or 1
            else
                local size = readProperty(inst, 'Size')

                newEntry.size = typeof(size) == 'Vector3' and size or nil

                if newEntry.visual and readProperty(inst, 'ClassName') ~= nil then
                    local clone = cloneVisual(inst)

                    if clone then
                        pcall(function()
                            clone.Anchored = true
                            clone.CanCollide = false
                        end)

                        clone.Parent = newEntry.visual
                        newEntry.visualCount = newEntry.visualCount + 1
                        newEntry.hasBody = true
                    end
                end
            end

            newEntry.grabConn = processDescendants(newEntry, inst)
        end
        if kind == 'effect' then
            newEntry.path = newEntry.path or '(no instance)'
            newEntry.data = data

            for propsIndex = 1, #aw do
                local propName = aw[propsIndex]
                local propValue = type(data) == 'table' and data[propName] or nil

                if propValue ~= nil then
                    newEntry.props[#newEntry.props + 1] = {
                        propName,
                        formatValue(propValue),
                    }
                end
            end

            if type(data) == 'table' then
                for mapKey, mapValue in next, data do
                    local isFiltered = false

                    for filterIndex = 1, #aw do
                        if aw[filterIndex] == mapKey then
                            isFiltered = true

                            break
                        end
                    end

                    if not isFiltered and type(mapKey) == 'string' and typeof(mapValue) ~= 'table' then
                        newEntry.props[#newEntry.props + 1] = {
                            mapKey,
                            formatValue(mapValue),
                        }
                    end
                end
            end
        end

        ah[#ah + 1] = newEntry

        while#ah > soundVisualizer.maxEntries do
            local oldest = table.remove(ah, 1)

            if oldest.stopWatch then
                oldest.stopWatch()
            end
            if oldest.visual then
                pcall(function()
                    oldest.visual:Destroy()
                end)
            end
        end

        broadcastPayload(newEntry)

        if inst then
            startStopwatch(newEntry, inst)
        end
    end

    soundVisualizer._record = logEvent

    function soundVisualizer.remove(entry)
        for entryIndex = #ah, 1, -1 do
            if ah[entryIndex] == entry then
                table.remove(ah, entryIndex)

                break
            end
        end

        broadcastPayload(entry)
    end
    function soundVisualizer.entries()
        return ah
    end
    function soundVisualizer.onEntry(queuedEntry)
        ai[#ai + 1] = queuedEntry
    end
    function soundVisualizer.clear()
        soundVisualizer.seen = 0
        soundVisualizer.dropped = 0

        for index = 1, #ah do
            if ah[index].stopWatch then
                ah[index].stopWatch()
            end
            if ah[index].visual then
                pcall(function()
                    ah[index].visual:Destroy()
                end)
            end
        end

        ah = {}
    end

    soundVisualizer.assetRoots = {
        'Assets',
        'Sounds',
        'Debris',
        'Effects',
        'Particles',
    }

    function soundVisualizer.template(templateEntry)
        if templateEntry.templateResolved then
            return templateEntry.templateInst
        end

        templateEntry.templateResolved = true
        templateEntry.templateInst = nil

        local id = templateEntry.id

        if templateEntry.kind == 'sound' then
            local soundsFolder = replicatedStorage:FindFirstChild('Sounds')

            if soundsFolder then
                local idDigits = tostring(templateEntry.soundId or id):match('%d+')

                if idDigits then
                    local fetchOk, descendants = pcall(function()
                        return soundsFolder:GetDescendants()
                    end)

                    if fetchOk then
                        for descendantIndex = 1, #descendants do
                            local descendant = descendants[descendantIndex]
                            local assetId = readProperty(descendant, 'SoundId') or readProperty(descendant, 'AssetId')

                            if assetId and tostring(assetId):match('%d+') == idDigits then
                                templateEntry.templateInst = descendant

                                return descendant
                            end
                        end
                    end
                end
            end

            return nil
        end
        if type(id) ~= 'string' or id == '' then
            return nil
        end

        for rootIndex = 1, #soundVisualizer.assetRoots do
            local rootFolder = replicatedStorage:FindFirstChild(soundVisualizer.assetRoots[rootIndex])

            if rootFolder then
                local foundOk, foundInstance = pcall(function()
                    return rootFolder:FindFirstChild(id, true)
                end)

                if foundOk and foundInstance then
                    templateEntry.templateInst = foundInstance

                    return foundInstance
                end
            end
        end

        return nil
    end
    function soundVisualizer.build(buildEntry)
        local modelOk, model = pcall(function()
            return Instance.new('Model')
        end)

        if not modelOk then
            return nil, 'no Model'
        end

        model.Name = 'Preview'

        if buildEntry.visual and buildEntry.visualCount > 0 then
            local captureOk = pcall(function()
                for partIndex, part in next, buildEntry.visual:GetChildren()do
                    local partInstance = cloneVisual(part)

                    if partInstance then
                        partInstance.Parent = model
                    end
                end
            end)

            if captureOk and #model:GetChildren() > 0 then
                return model, 'captured'
            end
        end

        local template = soundVisualizer.template(buildEntry)

        if template then
            local templateInstance = cloneVisual(template)

            if templateInstance then
                templateInstance.Parent = model

                return model, 'template'
            end
        end

        model:Destroy()

        return nil, 'nothing found'
    end
    function soundVisualizer.hasVisual(probeEntry)
        return probeEntry.visual ~= nil and probeEntry.visualCount > 0
    end
    function soundVisualizer.rebuild(rebuildEntry)
        if rebuildEntry.kind ~= 'sound' then
            return nil
        end

        local templateRef = soundVisualizer.template(rebuildEntry)
        local sound = templateRef and cloneVisual(templateRef) or nil

        if not sound then
            local createOk, newSound = pcall(function()
                return Instance.new('Sound')
            end)

            if not createOk or not rebuildEntry.soundId then
                return nil
            end

            sound = newSound
            sound.SoundId = rebuildEntry.soundId
            sound.Volume = rebuildEntry.volume or 0.5
            sound.PlaybackSpeed = rebuildEntry.speed or 1
        end

        local attachOk = pcall(function()
            sound.Looped = false
            sound.Parent = workspace.CurrentCamera
        end)

        if not attachOk then
            pcall(function()
                sound:Destroy()
            end)

            return nil
        end

        return sound
    end
    function soundVisualizer.replay(effect)
        if effect.kind ~= 'effect' then
            return false, 'not an effect'
        end

        local requestsFolder = replicatedStorage:FindFirstChild('Requests')
        local effectRemote = requestsFolder and requestsFolder:FindFirstChild('ClientEffectDirect')

        if not effectRemote then
            return false, 'ClientEffectDirect is missing'
        end

        local success, fireEffect = pcall(function()
            effectRemote:Fire(effect.id, effect.data)
        end)

        if not success then
            return false, tostring(fireEffect)
        end

        return true
    end

    soundVisualizer.captureTime = 0.6

    function soundVisualizer.capture(effectData, callback)
        if effectData.kind ~= 'effect' then
            if callback then
                callback(false, 'not an effect')
            end

            return
        end
        if effectData.capturing then
            return
        end
        if not effectData.visual then
            if callback then
                callback(false, 'no preview holder')
            end

            return
        end

        effectData.capturing = true

        local startCount = effectData.visualCount
        local connection
        local onDescendant = function(descendant)
            if effectData.visualCount >= soundVisualizer.maxVisuals then
                return
            end
            if effectData.grabbed[descendant] or not av[descendant.ClassName] then
                return
            end

            effectData.grabbed[descendant] = true

            local instance = cloneVisual(descendant)

            if instance then
                instance.Parent = effectData.visual
                effectData.visualCount = effectData.visualCount + 1
            end
        end
        local captureOk, captureErr = pcall(function()
            connection = workspace.DescendantAdded:Connect(onDescendant)
        end)

        if not captureOk then
            effectData.capturing = false

            if callback then
                callback(false, tostring(captureErr))
            end

            return
        end

        local replayOk, replayResult = soundVisualizer.replay(effectData)

        task.delay(soundVisualizer.captureTime, function()
            if connection then
                connection:Disconnect()
            end

            effectData.capturing = false
            effectData.templateResolved = false

            if callback then
                if not replayOk then
                    callback(false, replayResult or 'replay failed')
                else
                    callback(true, effectData.visualCount - startCount)
                end
            end
        end)
    end
    function soundVisualizer.blacklist(value)
        if not value or value == '' or ak[value] then
            return
        end

        ak[value] = true

        for index = #ah, 1, -1 do
            if ah[index].trigger == value then
                if ah[index].stopWatch then
                    ah[index].stopWatch()
                end

                table.remove(ah, index)
            end
        end

        runCallbacks()
    end
    function soundVisualizer.unblacklist(entry)
        if not ak[entry] then
            return
        end

        ak[entry] = nil

        runCallbacks()
    end
    function soundVisualizer.isBlacklisted(key)
        return ak[key] == true
    end
    function soundVisualizer.blacklisted()
        local result = {}

        for blacklistKey in next, ak do
            result[#result + 1] = blacklistKey
        end

        table.sort(result)

        return result
    end
    function soundVisualizer.onBlacklistChanged(listener)
        aj[#aj + 1] = listener
    end
    function soundVisualizer.distanceText(effectRef)
        if not effectRef.dist then
            return 'world'
        end

        return string.format('%dst', math.floor(effectRef.dist + 0.5))
    end
    function soundVisualizer.details(effectObj)
        local lines = {
            'kind      ' .. effectObj.kind,
            'trigger   ' .. effectObj.trigger,
            'source    ' .. effectObj.source .. '  (' .. effectObj.sourceName .. ')',
            'distance  ' .. soundVisualizer.distanceText(effectObj),
            'count     ' .. tostring(effectObj.count),
            'fate      ' .. soundVisualizer.fateText(effectObj),
        }

        if effectObj.size then
            lines[#lines + 1] = 'size      ' .. formatValue(effectObj.size)
        end

        local travelled = soundVisualizer.travel(effectObj)

        if travelled then
            lines[#lines + 1] = string.format('travelled %.2f studs', travelled)
        end
        if effectObj.path then
            lines[#lines + 1] = 'path      ' .. effectObj.path
        end
        if #effectObj.props > 0 then
            lines[#lines + 1] = ''

            for arrayIndex = 1, #effectObj.props do
                local prop = effectObj.props[arrayIndex]

                lines[#lines + 1] = string.format('%-10s%s', prop[1], prop[2])
            end
        end

        return lines
    end
    function soundVisualizer.sampleAt(soundData, aE)
        local samples = soundData.samples

        if not samples or #samples == 0 then
            return nil
        end

        local sampleIndex = math.floor(aE * (#samples - 1)) + 1

        if sampleIndex < 1 then
            sampleIndex = 1
        end
        if sampleIndex > #samples then
            sampleIndex = #samples
        end

        return samples[sampleIndex]
    end
    function soundVisualizer.init()
        if al then
            return
        end

        al = true

        effectReplicator.onTrigger(function(aD, aE, aF, aG, aH, aI, aJ)
            logEvent('effect', aE, aD, aH, aI, aJ)
        end)
        partTriggers.onTrigger(function(aD, aE, aF, aG, aH)
            logEvent('part', aE, aD, aH)
        end)
        audioScanner.onTrigger(function(aD, aE, aF, aG, aH)
            logEvent('sound', aE, aD, aH)
        end)
    end
    function soundVisualizer.detach()
        al = false

        soundVisualizer.clear()

        for index = 1, #am do
            pcall(function()
                am[index]:Disconnect()
            end)
        end

        am = {}
        ah = {}
        ai = {}
        aj = {}
        ak = {}
    end

    return soundVisualizer
end


return aa()

]=],
    ["Features/Visuals/TalentCards"] = [=[
local aa = function()
    local module = {}
    local library = a["GUI/Library"]()
    local configuration = a["Utility/Configuration"]()
    local logger = a["Utility/Logger"]()
    local maidModule = a["Utility/Maid"]()
    local originalStoreManager = a["Utility/OriginalStoreManager"]()
    local signal = a["Utility/Signal"]()
    local players = game:GetService('Players')
    local httpService = game:GetService('HttpService')
    local runService = game:GetService('RunService')
    local maid = maidModule.new()
    local store = originalStoreManager.new()
    local an
    local ao
    local ap
    local aq = false
    local ar = {}
    local as = false
    local at = {}
    local au = {}
    local av = 0
    local greenColor = Color3.fromRGB(0, 255, 120)
    local amberColor = Color3.fromRGB(255, 187, 0)
    local redColor = Color3.fromRGB(255, 0, 100)
    local httpRequest = function(options)
        local requestFn = (syn and syn.request) or http_request or request or (http and http.request)

        if not requestFn then
            return nil
        end

        local success, result = pcall(requestFn, options)

        return success and result or nil
    end
    local cleanName = function(name)
        if not name or name == '' then
            return ''
        end
        if at[name] then
            return at[name]
        end

        local cleaned = name:gsub(' %[HVY%]', ''):gsub(' %[LHT%]', ''):gsub(' %[MED%]', ''):lower():gsub('%s*%[.-%]%s*', ' '):gsub('^%d+', ''):gsub('z%w+divider', ''):gsub('[^%a%d]', '')

        at[name] = cleaned

        return cleaned
    end
    local meetsRequirements = function(talent, stats)
        if not talent or not stats then
            return false
        end
        if talent.requirements and talent.requirements.stats then
            for stat, required in pairs(talent.requirements.stats)do
                if (stats[stat] or 0) < required then
                    return false
                end
            end

            return true
        end
        if talent.reqs then
            for index, category in ipairs({
                'base',
                'weapon',
                'attunement',
            })do
                local reqs = talent.reqs[category]

                if reqs then
                    for key, value in pairs(reqs)do
                        if value > 0 and (stats[key] or 0) < value then
                            return false
                        end
                    end
                end
            end

            return true
        end

        return false
    end
    local mergeAttributes = function(attributes)
        if not attributes then
            return {}
        end

        local merged = {}

        for index, category in ipairs({
            'weapon',
            'attunement',
            'base',
        })do
            if attributes[category] then
                for key, value in pairs(attributes[category])do
                    merged[key] = value
                end
            end
        end

        return merged
    end
    local normalizeData = function(data)
        if not data then
            return nil
        end

        return {
            talents = data.talents or {},
            mantras = data.mantras or {},
            attributes = mergeAttributes(data.attributes),
            preShrine = mergeAttributes(data.preShrine),
        }
    end
    local findDescendant = function(root, ...)
        local current = root

        for index, name in ipairs({...})do
            if not current then
                return nil
            end

            current = current:FindFirstChild(name)
        end

        return current
    end
    local getBackpackGui = function()
        local playerGui = players.LocalPlayer and players.LocalPlayer:FindFirstChild('PlayerGui')

        return playerGui and playerGui:FindFirstChild('BackpackGui')
    end
    local setupTalentCards = function()
        if not an or as then
            return
        end

        as = true

        local success = pcall(function()
            local container = findDescendant(getBackpackGui(), 'RightFrame', 'TalentSheet', 'Container', 'TalentScroll')

            if not container then
                return
            end

            for index, card in pairs(ar)do
                if card then
                    pcall(function()
                        card:Destroy()
                    end)
                end
            end

            table.clear(ar)

            local template

            for index, descendant in ipairs(container:GetDescendants())do
                if (descendant:IsA('Frame') or descendant:IsA('TextButton')) and not descendant.Name:find('Missing_') then
                    if descendant:FindFirstChild('Title') and descendant:FindFirstChild('Icon') then
                        template = descendant

                        break
                    end
                end
            end

            if not template then
                return
            end

            local parent = container

            for index, descendant in ipairs(container:GetDescendants())do
                if descendant.Name == 'Outfit' or descendant.Name == 'Quest' or descendant.Name == 'Race' then
                    parent = descendant

                    break
                end
            end

            local existing = {}

            for index, descendant in ipairs(container:GetDescendants())do
                local title = descendant:FindFirstChild('Title')

                if title and not descendant.Name:find('Missing_') then
                    existing[cleanName(title.Text)] = true
                end
            end
            for index, talent in ipairs(an.talents or {})do
                local title = cleanName(talent)

                if not existing[title] then
                    local card = template:Clone()

                    card.Name = 'Missing_' .. title
                    card.BackgroundColor3 = Color3.new(1, 1, 1)
                    card.BackgroundTransparency = 0.95

                    local title = card:FindFirstChild('Title')

                    if title then
                        title.Text = talent
                        title.TextColor3 = library.AccentColor
                        title.TextTransparency = 0
                    end

                    local icon = card:FindFirstChild('Icon')

                    if icon then
                        icon.Visible = false
                    end

                    local stroke = card:FindFirstChildOfClass('UIStroke') or Instance.new('UIStroke', card)

                    stroke.Enabled, stroke.Transparency, stroke.Thickness = true, 0.8, 1
                    stroke.Color = Color3.new(1, 1, 1)

                    table.insert(ar, card)

                    card.Parent = parent
                end
            end
        end)

        task.delay(0.5, function()
            as = false
        end)

        return success
    end
    local createCard = function(card, parentFrame)
        if not card or not an or not ao then
            return
        end

        local title = card:FindFirstChild('Title')
        local border = card:FindFirstChild('Border')
        local cardFrame = card:FindFirstChild('CardFrame')

        if cardFrame then
            border = border or cardFrame:FindFirstChild('Border')
            title = title or cardFrame:FindFirstChild('Title')
        end
        if not border then
            for index, child in ipairs(card:GetChildren())do
                if child:IsA('ImageLabel') and child.Name ~= 'Icon' then
                    border = child

                    break
                end
            end
        end
        if not title and not border then
            return
        end

        local titleText = (title and title.Text ~= '') and title.Text or card.Name
        local spellName = cleanName(titleText)
        local talentKey = titleText:lower()

        if spellName:match('roll2') or spellName:match('fold') then
            return
        end

        local color = redColor

        for i, mantra in ipairs(an.mantras or {})do
            if cleanName(mantra):match(spellName) then
                color = greenColor

                break
            end
        end

        if au[spellName] then
            local talent = ao.talents and ao.talents[talentKey]

            if talent then
                local isPreShrine = meetsRequirements(talent, an.preShrine) and not meetsRequirements(talent, an.attributes)

                color = isPreShrine and amberColor or greenColor
            else
                color = greenColor
            end
        end
        if card.Name:find('Missing_') then
            local missingTalent = ao.talents and ao.talents[talentKey]

            if missingTalent then
                local isPreShrineOnly = meetsRequirements(missingTalent, an.preShrine) and not meetsRequirements(missingTalent, an.attributes)

                color = isPreShrineOnly and Color3.fromRGB(247, 0, 255) or amberColor
            else
                color = amberColor
