            an = normalizeData(buildData)

            local talentsResponse = httpRequest({
                Url = 'https://new.deepwoken.co/api/proxy/get?type=all',
                Method = 'GET',
                Headers = headers,
            })
            local talents = {}

            if talentsResponse and talentsResponse.StatusCode == 200 then
                local decodeOk, talentsData = pcall(function()
                    return httpService:JSONDecode(talentsResponse.Body)
                end)

                if decodeOk and talentsData then
                    for talentIndex, talent in ipairs(talentsData.talents or {})do
                        if talent and talent.name then
                            talents[talent.name:lower()] = talent
                        end
                    end
                end
            end

            ao = {talents = talents}

            table.clear(au)

            for buildIndex, buildTalent in ipairs(an.talents or {})do
                au[cleanName(buildTalent)] = true
            end

            local talentScroll = findDescendant(getBackpackGui(), 'RightFrame', 'TalentSheet', 'Container', 'TalentScroll')

            if talentScroll then
                maid['talent_scroll_added'] = talentScroll.ChildAdded:Connect(function(
                    child
                )
                    if not child.Name:find('Missing_') then
                        task.delay(0.2, setupTalentCards)
                    end
                end)
            end

            setupTalentCards()

            aq = false

            logger.notify('Talent Highlighter \u{2014} build loaded (%d talents).', #(an.talents or {}))
        end)
    end
    local cleanup = function()
        store:restore()

        maid['talent_scroll_added'] = nil

        for key, instance in pairs(ar)do
            if instance then
                pcall(function()
                    instance:Destroy()
                end)
            end
        end

        table.clear(ar)
        table.clear(at)
        table.clear(au)

        an, ao, ap = nil, nil, nil
    end
    local updateTalentHighlighter = function()
        local enabled = configuration.expectToggleValue('TalentHighlighter')

        if not enabled then
            if ap then
                cleanup()
            end

            return
        end

        local buildLink = configuration.expectOptionValue('BuildAssistanceLink')
        local extractedId = type(buildLink) == 'string' and buildLink:match('id=([%w%d]+)') or nil

        if not extractedId then
            return
        end
        if extractedId ~= ap then
            ap = extractedId

            fetchBuildData(extractedId)
        end
        if not an or not ao then
            return
        end

        local now = tick()

        if now - av < 0.5 then
            return
        end

        av = now

        pcall(function()
            local screenGui = getBackpackGui()
            local playerGui = players.LocalPlayer and players.LocalPlayer:FindFirstChild('PlayerGui')
            local talentSheet = screenGui and findDescendant(screenGui, 'RightFrame', 'TalentSheet')

            if talentSheet and talentSheet.Visible then
                local rightTalentScroll = findDescendant(talentSheet, 'Container', 'TalentScroll')

                if rightTalentScroll then
                    for scrollIndex, scrollChild in ipairs(rightTalentScroll:GetChildren())do
                        createCard(scrollChild, rightTalentScroll)
                    end

                    local displayCard = findDescendant(talentSheet, 'TalentDisplay', 'CardFrame')

                    if displayCard then
                        createCard(displayCard, rightTalentScroll)
                    end

                    local ownedFrame = rightTalentScroll:FindFirstChild('Owned')

                    if ownedFrame then
                        for ownedIndex, ownedCard in ipairs(ownedFrame:GetChildren())do
                            local title = ownedCard:FindFirstChild('Title')
                            local cardTitle = (title and title.Text) or ownedCard.Name
                            local normalized = cleanName(cardTitle)
                            local isOwned = false

                            for talentItemIndex, talentItem in ipairs(an.talents or {})do
                                if cleanName(talentItem) == normalized then
                                    isOwned = true

                                    break
                                end
                            end

                            local color = isOwned and greenColor or redColor

                            if title then
                                store:add(title, 'TextColor3', color)
                                store:add(title, 'TextTransparency', 0.25)

                                local stroke = title:FindFirstChildOfClass('UIStroke')

                                if stroke then
                                    store:add(stroke, 'Color', color)
                                    store:add(stroke, 'Transparency', 0.25)
                                end
                            end

                            local border = ownedCard:FindFirstChild('Border')

                            if border and border:IsA('ImageLabel') and border.Name ~= 'Icon' then
                                store:add(border, 'ImageColor3', color)
                            end
                        end
                    end
                end
            end

            local talentGui = playerGui and playerGui:FindFirstChild('TalentGui')
            local choiceFrame = talentGui and talentGui:FindFirstChild('ChoiceFrame')

            if choiceFrame and choiceFrame.Visible then
                for choiceIndex, choiceChild in ipairs(choiceFrame:GetChildren())do
                    if not choiceChild:IsA('UIComponent') then
                        createCard(choiceChild, nil)
                    end
                end
            end

            local deckFrame = findDescendant(screenGui, 'LeftFrame', 'DeckFrame')

            if deckFrame and deckFrame.Visible then
                local deckTalentScroll = deckFrame:FindFirstChild('TalentScroll')

                if deckTalentScroll then
                    for deckIndex, cardButton in ipairs(deckTalentScroll:GetChildren())do
                        if cardButton:IsA('TextButton') then
                            createCard(cardButton:FindFirstChild('CardFrame'), nil)
                        end
                    end
                end

                local mantraScroll = deckFrame:FindFirstChild('MantraScroll')

                if mantraScroll then
                    for mantraIndex, mantraCard in ipairs(mantraScroll:GetChildren())do
                        createCard(mantraCard, nil)
                    end
                end
            end

            local choicePrompt = playerGui and playerGui:FindFirstChild('ChoicePrompt')

            if choicePrompt then
                local scrollFrame = choicePrompt:FindFirstChild('ScrollingFrame', true)

                if scrollFrame then
                    for promptIndex, promptChild in ipairs(scrollFrame:GetChildren())do
                        local cardFrame = promptChild:FindFirstChild('CardFrame')

                        if cardFrame then
                            createCard(cardFrame, nil)
                        end
                    end
                end
            end

            refreshSheets()
        end)
    end

    function module.init()
        local heartbeatChanged = signal.new(runService.Heartbeat)

        maid:add(heartbeatChanged:connect('TalentHighlighter_Update', updateTalentHighlighter))
        logger.warn('TalentHighlighter initialized.')
    end
    function module.detach()
        maid:clean()
        cleanup()
        logger.warn('TalentHighlighter detached.')
    end

    return module
end


return aa()

