    local getStat = function(character, statId)
        if statId == 'HP' then
            local humanoid = character:FindFirstChildOfClass('Humanoid')

            if humanoid and humanoid.MaxHealth and humanoid.MaxHealth > 0 then
                return humanoid.Health, humanoid.MaxHealth
            end

            return nil, nil
        end

        local attributeName = bl[statId]

        if not attributeName then
            return nil, nil
        end

        local attribute = character:FindFirstChild(attributeName)

        if not attribute then
            return nil, nil
        end

        local maxValue = attribute.MaxValue

        if type(maxValue) ~= 'number' or maxValue <= 0 then
            return nil, nil
        end

        return attribute.Value, maxValue
    end
    local renderDepthsBars = LPH_NO_VIRTUALIZE(function()
        local rowsRef = getOrCreateGankAssist()
        local barsConfig = configuration.expectOptionValue('DepthsAssistanceBars')

        if type(barsConfig) ~= 'table' then
            barsConfig = {HP = true}
        end

        local includeSelf = configuration.expectToggleValue('DepthsAssistanceIncludeSelf') ~= false
        local localPlayer = players.LocalPlayer
        local activePlayers = {}
        local rowIndex = 0
        local renderPlayer = function(player)
            local playerCharacter = player.Character

            if not playerCharacter then
                return
            end

            local root = playerCharacter:FindFirstChild('HumanoidRootPart')

            if not root then
                return
            end

            rowIndex = rowIndex + 1

            local row = rowsRef.rows[player]

            if not row then
                row = createRow(rowsRef.container, rowIndex)
                rowsRef.rows[player] = row
            else
                row.frame.LayoutOrder = rowIndex
            end

            row.name.Text = player.DisplayName or player.Name
            activePlayers[player] = true

            local barIndex = 0

            for index, barType in ipairs(bk)do
                if barsConfig[barType] then
                    barIndex = barIndex + 1

                    local barRow = getOrCreateBar(row, barType, barIndex)
                    local current, total = getStat(playerCharacter, barType)

                    if current and total then
                        local ratio = math.clamp(current / total, 0, 1)

                        barRow.fill.Size = UDim2.new(ratio, 0, 1, 0)
                        barRow.label.Text = string.format('%s %.0f%%', barType, ratio * 100)
                    else
                        barRow.fill.Size = UDim2.new(0, 0, 1, 0)
                        barRow.label.Text = barType .. ' -'
                    end
                end
            end

            pruneDisabledBars(row, barsConfig)
        end

        if includeSelf and localPlayer then
            renderPlayer(localPlayer)
        end

        for playerIndex, otherPlayer in ipairs(players:GetPlayers())do
            if otherPlayer ~= localPlayer and playerScanning.isAlly(otherPlayer) then
                renderPlayer(otherPlayer)
            end
        end
        for trackedPlayer, rowRef in next, rowsRef.rows do
            if not activePlayers[trackedPlayer] then
                pcall(function()
                    rowRef.frame:Destroy()
                end)

                rowsRef.rows[trackedPlayer] = nil
            end
        end
    end)
    local bv
    local cleanupLowHpNotifier = function()
        bv = nil

        removeGuiByName('PalantirX_LowHpNotifier')
    end
    local getOrCreateLowHpNotifier = function()
        if bv and bv.screenGui and bv.screenGui.Parent then
            return bv
        end

        cleanupLowHpNotifier()

        local screenGui = coreGuiManager.imark(Instance.new('ScreenGui'))

        screenGui.Name = 'PalantirX_LowHpNotifier'
        screenGui.ResetOnSpawn = false
        screenGui.DisplayOrder = 1500

        if not screenGui.Parent then
            local success = pcall(function()
                screenGui.Parent = game:GetService('CoreGui')
            end)

            if not success then
                screenGui.Parent = players.LocalPlayer:WaitForChild('PlayerGui')
            end
        end

        bv = {
            screenGui = screenGui,
            signs = {},
        }

        return bv
    end
    local createLowHpSign = function(parent)
        local billboard = Instance.new('BillboardGui')

        billboard.Name = 'LowHpSign'
        billboard.Size = UDim2.new(0, 130, 0, 30)
        billboard.StudsOffset = Vector3.new(0, 3.2, 0)
        billboard.AlwaysOnTop = true
        billboard.Parent = parent

        local label = Instance.new('TextLabel')

        label.Name = 'Label'
