        label.Text = '\u{26a0} LOW HP'
        label.Parent = billboard

        return {
            billboard = billboard,
            label = label,
        }
    end
    local updateLowHpNotifier = LPH_NO_VIRTUALIZE(function()
        local notifier = getOrCreateLowHpNotifier()
        local threshold = configuration.expectOptionValue('DepthsAssistanceLowHpThreshold') or 30
        local localPlayer = players.LocalPlayer
        local lowHpPlayers = {}
        local trackLowHpPlayer = function(player)
            if player == localPlayer then
                return
            end

            local character = player.Character

            if not character then
                return
            end

            local root = character:FindFirstChild('Head') or character:FindFirstChild('HumanoidRootPart')
            local humanoid = character:FindFirstChildOfClass('Humanoid')

            if not root or not humanoid or humanoid.MaxHealth <= 0 or humanoid.Health <= 0 then
                return
            end

            local hpPercent = humanoid.Health / humanoid.MaxHealth * 100

            if hpPercent > threshold then
                return
            end

            lowHpPlayers[player] = true

            local existingSign = notifier.signs[player]

            if not existingSign or not existingSign.billboard.Parent then
                existingSign = createLowHpSign(notifier.screenGui)
                notifier.signs[player] = existingSign
            end

            existingSign.billboard.Adornee = root
            existingSign.label.Text = string.format('\u{26a0} %.0f%% HP', hpPercent)
        end

        for index, candidate in ipairs(players:GetPlayers())do
            if playerScanning.isAlly(candidate) then
                trackLowHpPlayer(candidate)
            end
        end
        for signedPlayer, signEntry in next, notifier.signs do
            if not lowHpPlayers[signedPlayer] then
                pcall(function()
                    signEntry.billboard:Destroy()
                end)

                notifier.signs[signedPlayer] = nil
            end
        end
    end)
    local bA = {
        ['rbxassetid://7600160919'] = true,
        ['rbxassetid://7600224169'] = true,
        ['rbxassetid://7600450739'] = true,
        ['rbxassetid://7600485223'] = true,
    }
    local bB = {}

    shared.Palantir_PoserStored = bB

    local bC, bD = 0
    local sampleThrownDamage = function()
        local bE = os.clock()

        if bE - bC < 0.2 then
            return bD
        end

        bC = bE
        bD = nil

        local currentPlayer = players.LocalPlayer
        local thrownFolder = workspace:FindFirstChild('Thrown')

        if not currentPlayer or not thrownFolder then
            return nil
        end

        local attachPart = thrownFolder:FindFirstChild('Attach_' .. currentPlayer.Name)
        local handWeapon = attachPart and attachPart:FindFirstChild('HandWeapon')
        local stats = handWeapon and handWeapon:FindFirstChild('Stats')

        if not stats then
            return nil
        end

        local damage = stats:FindFirstChild('Damage')
        local damageValue = damage and damage.Value

        if type(damageValue) ~= 'number' then
            return nil
        end

        local computedDamage = damageValue
        local scaling = stats:FindFirstChild('Scaling')
        local playerCharacter = currentPlayer.Character

        if scaling and playerCharacter then
            for statIndex, stat in next, scaling:GetChildren()do
                local value = stat.Value

                if type(value) == 'number' and value ~= 0 then
                    if math.abs(value) < 1 then
                        value = value * 100
                    end

                    local statValue = playerCharacter:GetAttribute('Stat_' .. stat.Name) or playerCharacter:GetAttribute('Stat' .. stat.Name) or playerCharacter:GetAttribute(stat.Name) or 0

                    computedDamage = computedDamage + (damageValue * value * statValue / 1000 * 0.75)
                end
            end
        end

        bD = computedDamage

        return computedDamage
    end
    local findThrownTarget = function()
        local localPlayer = players.LocalPlayer
        local character = localPlayer and localPlayer.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')

        if not root then
            return nil
        end

        local origin = root.Position
        local lookVector = root.CFrame.LookVector
        local rangeSq, target = (16 * 16)

        for index, player in ipairs(players:GetPlayers())do
            if player ~= localPlayer then
                local character = player.Character
                local root = character and character:FindFirstChild('HumanoidRootPart')
                local humanoid = character and character:FindFirstChildOfClass('Humanoid')

                if root and humanoid and humanoid.Health > 0 then
                    local offset = root.Position - origin
                    local distSq = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z

                    if distSq <= rangeSq and lookVector:Dot(offset.Unit) > 0.2 then
                        target, rangeSq = player, distSq
                    end
                end
            end
        end

        return target
    end
    local predictPoserDamage = function()
        if not configuration.idToggleValue('Player', 'PoserDamagePredict') then
            return
        end

        local damage = sampleThrownDamage()

        if not damage or damage <= 0 then
            return
        end

        local target = findThrownTarget()

        if not target then
            return
        end

        local humanoid = target.Character and target.Character:FindFirstChildOfClass('Humanoid')
        local threshold = (humanoid and humanoid.MaxHealth or 0) * 0.7
        local record = bB[target]

        if not record then
            record = {
                dmg = 0,
                at = 0,
            }
            bB[target] = record
        end

        record.dmg = record.dmg + damage

        if threshold > 0 and record.dmg > threshold then
            record.dmg = threshold
        end

        record.at = os.clock()
    end
    local onAnimationPlayed = function(animData)
        local anim = animData and animData.Animation
        local animationId = anim and tostring(anim.AnimationId)

        if not animationId then
            return
        end
        if animationId == 'rbxassetid://9767020777' then
            table.clear(bB)
        elseif bA[animationId] then
            predictPoserDamage()
        end
    end
    local hookCharacter = function(character)
        if not character then
            return
        end

        local humanoid = character:FindFirstChildOfClass('Humanoid') or character:WaitForChild('Humanoid', 5)

        if not humanoid then
            return
        end

        local animator = humanoid:FindFirstChildOfClass('Animator') or humanoid:WaitForChild('Animator', 5)

        if not animator then
            return
        end

        mainMaid:add(signal.new(animator.AnimationPlayed):connect('Visuals_PoserAnim', onAnimationPlayed))
    end
    local setupPoser = function()
        local localPlayer = players.LocalPlayer

        if not localPlayer then
            return
        end
        if localPlayer.Character then
            taskSpawner.spawn('Visuals_PoserHook', function()
                hookCharacter(localPlayer.Character)
            end)
        end

        mainMaid:add(signal.new(localPlayer.CharacterAdded):connect('Visuals_PoserCharAdded', function(
            character
        )
            table.clear(bB)
            taskSpawner.spawn('Visuals_PoserHook', function()
                hookCharacter(character)
            end)
        end))
    end
    local markCardFrame = function(frame)
        if frame.Name == 'CardFrame' then
            aG[frame] = true
        end
