    local buildTraitMap = function()
        local drinfo = av.drinfo
        local bdata = av.bdata

        if not drinfo or not bdata then
            return
        end

        local traits = bdata.traits
        local traitMap = {
            Vitality = drinfo['TraitHealth'],
            Erudition = drinfo['TraitEther'],
            Proficiency = drinfo['TraitWeaponDamage'],
            Songchant = drinfo['TraitMantraDamage'],
        }

        for frame in next, aG do
            local title = frame:FindFirstChild('Title')
            local border = frame:FindFirstChild('Border')

            if not title or not border then
                continue
            end

            local titleText = string.gsub(title.Text, '^%s*(.-)%s*$', '%1')
            local talentIndex = table.find(bdata.talents, titleText) or table.find(bdata.mantras, titleText)

            if talentIndex then
                local differs = bdata.ddata:possible(titleText, bdata.pre) and not bdata.ddata:possible(titleText, bdata.post)

                aV:add(border, 'ImageColor3', differs and Color3.new(255, 0, 255) or Color3.new(0, 255, 0))

                continue
            end

            local color = Color3.new(255, 0, 0)

            for key, value in next, traitMap do
                if title.Text:match(key) and traits[key] ~= value then
                    color = Color3.new(0, 255, 0)

                    break
                end
            end

            aV:add(border, 'ImageColor3', color)
        end
    end
    local bN = function(frame)
        local buildData = av.bdata

        if not buildData or not av.drinfo or not buildData:dshrine() then
            return
        end

        local panels = frame:FindFirstChild('Panels')
        local powerInfoFrame = panels and panels:FindFirstChild('InfoFrame')
        local powerSheets = powerInfoFrame and powerInfoFrame:FindFirstChild('Sheets')
        local powerRoot = powerSheets and powerSheets:FindFirstChild('Power')
        local powerBackground = powerRoot and powerRoot:FindFirstChild('Background')

        if not powerBackground then
            return
        end

        local powerState = buildData:ipre(av.drinfo)
        local powerColor = powerState == 0 and Color3.fromRGB(97, 4, 113) or powerState == 1 and Color3.fromRGB(37, 129, 236) or Color3.fromRGB(245, 137, 5)

        aV:add(powerBackground, 'BackgroundColor3', powerColor)
    end
    local populateStats = function(statScreen)
        if not av.drinfo or not av.bdata then
            return
        end

        local attrPanels = statScreen:FindFirstChild('Panels')
        local attributeFrame = attrPanels and attrPanels:FindFirstChild('AttributeFrame')
        local attrSheets = attributeFrame and attributeFrame:FindFirstChild('Sheets')

        if not attrSheets then
            return
        end

        local drinfo = av.drinfo
        local requirements, powerMode = buildMoveParts(av.bdata)

        for buttonIndex, button in next, attrSheets:GetDescendants()do
            if not button:IsA('TextButton') then
                continue
            end

            local requirementCount = requirements[button.Name]

            if not requirementCount then
                continue
            end

            local bY = button:FindFirstChild('Background')
            local bZ = button:FindFirstChild('Value')
            local b_ = button:FindFirstChild('Abbrev')

            if not bY or not bZ or not b_ then
                continue
            end

            local b0 = tonumber(drinfo['Stat' .. button.Name])

            if not b0 then
                continue
            end

            local b1 = (powerMode == 0 and b0 <= 0) and b0 or tonumber(bZ.Text)

            if not b1 then
                continue
            end

            aV:add(bY, 'BackgroundColor3', valueColor(b1, requirementCount))
            aV:add(b_, 'Text', string.format('GET (%i)', requirementCount))
        end
    end
