    local bQ
    local bR
    local bS
    local bT
    local populateTalents = function(talentScreen)
        local info = av.drinfo
        local data = av.bdata

        if not info or not data then
            return
        end

        local talentSheet = talentScreen:FindFirstChild('TalentSheet')
        local container = talentSheet and talentSheet:FindFirstChild('Container')
        local scroll = container and container:FindFirstChild('TalentScroll')

        if not scroll then
            return
        end
        if data == bQ and scroll == bR and (not bS or bS.Parent == scroll) and (not bT or bT.Parent == scroll) then
            return
        end

        task.wait()

        local template
        local groupTemplate

        for groupIndex, groupFrame in next, scroll:GetChildren()do
            if groupFrame:IsA('Frame') and groupFrame:FindFirstChild('Title') then
                if not groupTemplate then
                    groupTemplate = groupFrame
                end

                for itemIndex, itemFrame in next, groupFrame:GetChildren()do
                    if itemFrame:IsA('Frame') and itemFrame:FindFirstChild('Title') then
                        template = itemFrame

                        break
                    end
                end

                if template then
                    break
                end
            end
        end

        if not template or not groupTemplate then
            return
        end

        secondaryMaid:clean()

        aH = {}

        local talents = table.clone(data.talents)
        local talentLookup = {}

        for talentKey, talentName in next, talents do
            local talentDisplay = stripSuffix(talentName)

            talentLookup[talentDisplay] = talentKey
            talentLookup[talentName] = talentKey
        end
        for descIndex, descendant in next, scroll:GetDescendants()do
            if not descendant:IsA('TextLabel') then
                continue
            end
            if descendant.Name ~= 'Title' then
                continue
            end

            local matchedTalent = talentLookup[descendant.Text]

            if not matchedTalent then
                continue
            end

            aV:add(descendant, 'TextColor3', Color3.fromRGB(9, 255, 0))

            local matchedData = talents[matchedTalent]

            talentLookup[stripSuffix(matchedData)] = nil
            talentLookup[matchedData] = nil
            talents[matchedTalent] = nil
        end

        local missingGroup = instanceWrapper.mark(secondaryMaid, 'missingTalentGroup', groupTemplate:Clone())

        for cleanupIndex, cleanupChild in next, missingGroup:GetChildren()do
            if cleanupChild:IsA('Frame') then
                cleanupChild:Destroy()
            end
        end

        missingGroup.Name = 'LMissingTalents'
        missingGroup.LayoutOrder = 9990

        local titleLabel = missingGroup:FindFirstChild('Title')

        if titleLabel then
            titleLabel.Text = 'MISSING'
            titleLabel.TextColor3 = Color3.fromRGB(255, 0, 2)
        end

        local hasMissing = false
        local layoutOrder = 1

        for missingKey, missingTalent in next, talents do
            local missingData = data.ddata:get(missingTalent)

            if not missingData then
                continue
            end

            hasMissing = true

            local missingDisplay = stripSuffix(missingTalent)
            local missingItem = instanceWrapper.mark(secondaryMaid, missingTalent, template:Clone())
            local isNewTalent = data.ddata:possible(missingTalent, data.pre) and not data.ddata:possible(missingTalent, data.post)

            missingItem.Name = 'M' .. missingDisplay
            missingItem.LayoutOrder = layoutOrder
            layoutOrder = layoutOrder + 1

            local missingIcon = missingItem:FindFirstChild('Icon')

            if missingIcon then
                missingIcon:Destroy()
            end

            local missingTitle = missingItem:FindFirstChild('Title')

            if missingTitle then
                missingTitle.Name = 'M' .. missingDisplay
                missingTitle.Text = missingDisplay
                missingTitle.TextColor3 = isNewTalent and Color3.fromRGB(255, 4, 255) or Color3.fromRGB(255, 0, 2)
                missingTitle.TextTransparency = 0.4
            end

            missingItem.Parent = missingGroup
            aH['M' .. missingDisplay] = missingData
        end

        if hasMissing then
            missingGroup.Parent = scroll
        end

        local missingMantraGroup = instanceWrapper.mark(secondaryMaid, 'missingMantraGroup', groupTemplate:Clone())

        for mantraCleanIndex, mantraCleanChild in next, missingMantraGroup:GetChildren()do
            if mantraCleanChild:IsA('Frame') then
                mantraCleanChild:Destroy()
            end
        end

        missingMantraGroup.Name = 'XMissingMantras'
        missingMantraGroup.LayoutOrder = 9995

        local mantraGroupTitle = missingMantraGroup:FindFirstChild('Title')

        if mantraGroupTitle then
            mantraGroupTitle.Text = 'MISSING MANTRAS'
            mantraGroupTitle.TextColor3 = Color3.fromRGB(255, 0, 2)
        end

        local ownedSet = {}
        local backpack = players.LocalPlayer and players.LocalPlayer:FindFirstChild('Backpack')

        if backpack then
            for bpIndex, backpackItem in next, backpack:GetChildren()do
                local itemDisplayName = backpackItem:GetAttribute('DisplayName')

                if itemDisplayName then
                    ownedSet[itemDisplayName] = true
                    ownedSet[stripSuffix(itemDisplayName)] = true
                end
            end
        end

        local hasMissingMantras = false
        local mantraOrder = 1

        for mantraIndex, mantra in next, data.mantras do
            local mantraData = data.ddata:get(mantra)

            if not mantraData then
                continue
            end

            local mantraDisplay = resolveMantra(stripSuffix(mantra))
            local isOwned = ownedSet[mantraDisplay] or false

            hasMissingMantras = true

            local mantraItem = instanceWrapper.mark(secondaryMaid, mantra, template:Clone())
            local isNewMantra = (data.ddata:possible(mantra, data.pre) and not data.ddata:possible(mantra, data.post))

            mantraItem.Name = 'Z' .. mantraDisplay
            mantraItem.LayoutOrder = mantraOrder
            mantraOrder = mantraOrder + 1

            local mantraIcon = mantraItem:FindFirstChild('Icon')

            if mantraIcon then
                mantraIcon:Destroy()
            end

            local mantraTitle = mantraItem:FindFirstChild('Title')

            if mantraTitle then
                mantraTitle.Name = 'Z' .. mantraDisplay
                mantraTitle.Text = mantraDisplay
                mantraTitle.TextColor3 = isOwned and Color3.fromRGB(9, 255, 0) or isNewMantra and Color3.fromRGB(255, 4, 255) or Color3.fromRGB(255, 0, 2)
                mantraTitle.TextTransparency = 0.4

                if isOwned then
                    mantraTitle.TextColor3 = Color3.fromRGB(9, 255, 0)
                end
            end

            mantraItem.Parent = missingMantraGroup
            aH['Z' .. mantraDisplay] = mantraData
        end

        if hasMissingMantras then
            missingMantraGroup.Parent = scroll
        end

        bQ = data
        bR = scroll
        bS = hasMissing and missingGroup or nil
        bT = hasMissingMantras and missingMantraGroup or nil
    end
    local populateCharacterStats = function(character)
        if not av.drinfo or not av.bdata then
            return
        end

        local panels = character:FindFirstChild('Panels')
        local attributeFrame = panels and panels:FindFirstChild('AttributeFrame')
        local sheets = attributeFrame and attributeFrame:FindFirstChild('Sheets')

        if not sheets then
