            local statColor = statColors[skillButton.Name]

            if not statColor then
                continue
            end

            local trainLabel = skillButton:FindFirstChild('Train')

            if not trainLabel or not trainLabel.Visible then
                continue
            end

            local valueLabel = skillButton:FindFirstChild('Value')

            if not valueLabel then
                continue
            end

            local statValue = tonumber(drInfo['Stat' .. skillButton.Name])

            if not statValue then
                continue
            end

            local finalValue = (statType == 0 and statValue <= 0) and statValue or tonumber(valueLabel.Text)

            if not finalValue then
                continue
            end

            aV:add(trainLabel, 'ImageColor3', valueColor(finalValue, statColor))
        end
    end
    local openBackpackGui = function()
        local now = os.clock()

        if now - a2 <= 0.05 then
            return
        end

        a2 = now

        local player = players.LocalPlayer
        local playerGui = player and player:FindFirstChild('PlayerGui')
        local backpackGui = playerGui and playerGui:FindFirstChild('BackpackGui')

        if not backpackGui then
            return
        end

        local rightFrame = backpackGui:FindFirstChild('RightFrame')

        if not rightFrame then
            return
        end

        local talentSheet = rightFrame:FindFirstChild('TalentSheet')
        local talentScroll = talentSheet and talentSheet:FindFirstChild('Container') and talentSheet.Container:FindFirstChild('TalentScroll')

        if not talentScroll then
            return
        end

        local talentDisplay = talentSheet:FindFirstChild('TalentDisplay')
        local cardFrame = talentDisplay and talentDisplay:FindFirstChild('CardFrame')

        if not cardFrame then
            return
        end

        local icon = cardFrame:FindFirstChild('Icon')
        local statsLabel = cardFrame:FindFirstChild('Stats')
        local titleLabel = cardFrame:FindFirstChild('Title')
        local details = cardFrame:FindFirstChild('Details')
        local descriptionLabel = details and details:FindFirstChild('Desc')
        local classLabel = details and details:FindFirstChild('Class')

        if not icon or not statsLabel or not classLabel or not descriptionLabel or not titleLabel then
            return
        end

        local mousePos = userInputService:GetMouseLocation() - guiService:GetGuiInset()
        local guiObjects = playerGui:GetGuiObjectsAtPosition(mousePos.X, mousePos.Y)
        local foundLabels = {}
        local isHovering = false
        local currentTalent

        for objKey, guiObject in next, guiObjects do
            if not isHovering and guiObject:IsDescendantOf(talentSheet) then
                isHovering = true
            end
            if guiObject:IsA('TextLabel') and aH[guiObject.Name] then
                foundLabels[guiObject.Name] = guiObject
            elseif guiObject:IsA('Frame') then
                local titleChild = guiObject:FindFirstChild('Title')

                if titleChild and titleChild:IsA('TextLabel') and aH[titleChild.Name] then
                    foundLabels[titleChild.Name] = titleChild
                end
            end
        end
        for talentKey, savedLabel in next, aI do
            if not foundLabels[talentKey] then
                if savedLabel and typeof(savedLabel) == 'Instance' and savedLabel:IsA('TextLabel') then
                    savedLabel.TextTransparency = 0.4
                end

                aI[talentKey] = nil
            end
        end
        for labelKey, hoveredLabel in next, foundLabels do
            local talentData = aH[labelKey]

            if not talentData then
                continue
            end

            hoveredLabel.TextTransparency = 0.1
            aI[labelKey] = hoveredLabel
            currentTalent = currentTalent or talentData
        end

        talentDisplay.Visible = isHovering
        statsLabel.Text = ''

        if not currentTalent then
            return
        end

        descriptionLabel.Text = currentTalent.desc or 'N/A'
        titleLabel.Text = currentTalent.name or 'N/A'
        classLabel.Text = currentTalent.category or '???'
        icon.ImageRectOffset = Vector2.new(0, 0)
        icon.Image = 'rbxassetid://94097748688985'

        local rarityColor = a4[string.lower(currentTalent.rarity or 'N/A')]

        if rarityColor then
            cardFrame.BackgroundColor3 = rarityColor
        end

        local requirements = currentTalent.reqs
        local reqStrings = {}

        if requirements.power ~= '0' then
            reqStrings[#reqStrings + 1] = string.format('PWR %s', requirements.power)
        end

        appendStatLabels(requirements.base, reqStrings)
        appendStatLabels(requirements.weapon, reqStrings)
        appendStatLabels(requirements.attunement, reqStrings)

        statsLabel.Text = table.concat(reqStrings, ', ')
    end
    local checkAutoProgression = function()
        local autoData = a["Utility/PersistentData"]().get('auto')

        if autoData and autoData.auto_progression then
            aP = false

            return true
        end

        return false
    end
    local bY = function()
        if checkAutoProgression() then
            return
        end

        local buildData = av.bdata

        if not buildData then
            return
        end

        local deckInfo = av.drinfo

        if not deckInfo then
            return
        end

        local requests = replicatedStorage:FindFirstChild('Requests')

        if not requests then
            return
        end

        local cards = requests:FindFirstChild('Cards')

        if not cards then
            return
        end

        local favourCardRemote = cards:FindFirstChild('FavourCard')

        if not favourCardRemote then
            return
        end

        local removeFavourRemote = cards:FindFirstChild('RemoveFavour')

        if not removeFavourRemote then
            return
        end

        local cardsList = {}
        local cardSet = {}
        local index = 0

        for talentKey, talent in next, buildData.talents do
            local talentName = resolveMantra(stripSuffix(talent))

            index = index + 1
            cardsList[index] = talentName
            cardSet[talentName] = true
        end
        for mantraKey, mantra in next, buildData.mantras do
            local mantraName = resolveMantra(stripSuffix(mantra))
            local resolvedMantra = mantraAliases[mantraName] or mantraName

            index = index + 1
            cardsList[index] = resolvedMantra
            cardSet[resolvedMantra] = true
        end

        local favouredCards = deckInfo.CardsFavoured
        local foretoldCards = deckInfo.CardsForetold
        local cardsToFavour, favourIndex = {}, 0

        for cardKey, cardName in next, cardsList do
            if not (favouredCards and favouredCards[cardName]) then
                favourIndex = favourIndex + 1
                cardsToFavour[favourIndex] = cardName
            end
        end

        local removeList, removeIndex = {}, 0

        if favouredCards then
            for favouredCard, favouredValue in next, favouredCards do
                if not cardSet[favouredCard] and not (foretoldCards and foretoldCards[favouredCard]) then
                    removeIndex = removeIndex + 1
                    removeList[removeIndex] = favouredCard
                end
            end
        end

        aR = cardsList
        aP = true
        aQ = buildData

        taskSpawner.spawn('Visuals_AutoFavourCards', function()
            for favourKey, favourCard in next, cardsToFavour do
                if checkAutoProgression() then
                    return
                end

                pcall(favourCardRemote.InvokeServer, favourCardRemote, favourCard)
                task.wait(0.1)
            end
            for removeKey, removeCard in next, removeList do
                if checkAutoProgression() then
                    return
                end

                pcall(removeFavourRemote.InvokeServer, removeFavourRemote, removeCard)
                task.wait(0.1)
            end

            logger.notify('Favoured %d cards, unfavoured %d non-build cards.', #cardsToFavour, #removeList)
        end)
    end
    local handleBackpackGui = function()
