    local buildMantraMap = function()
        local drinfo = av.drinfo

        if not drinfo or not drinfo.AvailableMantras then
            return
        end

        local mantraMap = {}

        for classKey, mantra in next, drinfo.AvailableMantras do
            if mantra.Name then
                mantraMap[mantra.Name] = mantra
            end
        end
        for choiceFrame in next, aG do
            local parent = choiceFrame.Parent

            if not parent then
                continue
            end

            local grandparent = parent.Parent

            if not grandparent or grandparent.Name ~= 'ChoiceFrame' then
                continue
            end

            local details = choiceFrame:FindFirstChild('Details')

            if not details then
                continue
            end

            local classLabel = details:FindFirstChild('Class')

            if not classLabel or classLabel.Text ~= 'Mystery' then
                continue
            end

            local mantra = mantraMap[parent.Name]

            if not mantra then
                continue
            end

            local titleLabel = choiceFrame:FindFirstChild('Title')

            if titleLabel and mantra.MantraName then
                aY:add(titleLabel, 'Text', mantra.MantraName)
            end
            if mantra.Class then
                aY:add(classLabel, 'Text', mantra.Class)
            end

            local descLabel = details:FindFirstChild('Desc')

            if descLabel and mantra.Desc then
                aY:add(descLabel, 'Text', mantra.Desc)
            end
        end
    end
