    local trackDescendants = function(parent, label, onAdd, onRemove, childOnly)
        local relation = childOnly and 'Child' or 'Descendant'
        local addedSignal = signal.new(childOnly and parent.ChildAdded or parent.DescendantAdded)
        local removedSignal = signal.new(childOnly and parent.ChildRemoved or parent.DescendantRemoving)

        mainMaid:add(addedSignal:connect(string.format('Visuals_%sOn%sAdded', label, relation), onAdd))
        mainMaid:add(removedSignal:connect(string.format('Visuals_%sOn%sRemoved', label, relation), onRemove))
        profiler.run(string.format('Visuals_%sAddInitial', label), function()
            for index, child in next, (childOnly and parent:GetChildren() or parent:GetDescendants())do
                onAdd(child)
            end
        end)
    end
    local co
    local untrackInstance = function(instance)
        for index, tracker in next, aL do
            local entry = tracker:remove(instance)

            if entry then
                entry:detach()
            end
        end
    end
