    co = function(item)
        local name = item.Name

        if name == 'Layer2Floor2' then
            return trackDescendants(item, 'Layer2Floor2', co, untrackInstance, true)
        end
        if name == 'TrueAvatarBossRoom' then
            return trackDescendants(item, 'TrueAvatarBossRoom', onAltarAdded, untrackInstance, false)
        end
        if name == 'BellKeys' then
            for childIndex, child in next, item:GetDescendants()do
                if child:IsA('BasePart') and child.Name == 'BellKey' then
                    return insertEsp(child, partEsp.new('BellKey', child, 'Bell Key'))
                end
            end

            return
        end
        if name == 'JobBoard' then
            return insertEsp(item, modelEsp.new('JobBoard', item, 'Job Board'))
        end
        if name == 'BigArtifact' and item:IsA('Model') then
            return insertEsp(item, modelEsp.new('Artifact', item, 'Artifact'))
        end
        if name == 'WindrunnerOrb' and item:IsA('BasePart') then
            return insertEsp(item, partEsp.new('WindrunnerOrb', item, 'Windrunner Orb'))
        end
        if name == 'DepthsWhirlpool' then
            return insertEsp(item, modelEsp.new('Whirlpool', item, 'Whirlpool'))
        end
        if name == 'Sack' then
            return insertEsp(item, partEsp.new('BagDrop', item, 'Sack'))
        end
        if name == 'MinistryCacheIndicator' then
            return insertEsp(item, partEsp.new('MinistryCacheIndicator', item, 'Ministry Cache Indicator'))
        end
        if name == 'GuildBanner' then
            return insertEsp(item, modelEsp.new('GuildBanner', item, 'Guild Banner'))
        end
        if name == 'Obelisk' then
            return insertEsp(item, obeliskEsp.new('Obelisk', item, 'Obelisk'))
        end
        if name == 'RareObelisk' then
            return insertEsp(item, modelEsp.new('RareObelisk', item, 'Rare Obelisk'))
        end
        if name == 'HealBrick' then
            return insertEsp(item, partEsp.new('HealBrick', item, 'Heal Brick'))
        end
        if name == 'MantraObelisk' then
            return insertEsp(item, modelEsp.new('MantraObelisk', item, 'Mantra Obelisk'))
        end
        if name:match('GuildDoor') then
            return insertEsp(item, partEsp.new('GuildDoor', item, item:GetAttribute('GuildName') or 'Unidentified Guild Door'))
        end
        if name:match('ArmorBrick') then
            local billboardGui = item:FindFirstChild('BillboardGui')
            local textLabel = billboardGui and billboardGui:FindFirstChild('TextLabel')

            return insertEsp(item, partEsp.new('ArmorBrick', item, textLabel and textLabel.Text or 'Unknown Armor Brick'))
        end
        if name:match('Boundary') then
            return insertEsp(item, partEsp.new('VOIBoundaryESP', item, item.Name))
        end
        if item:GetAttribute('Rarity') and item:IsA('MeshPart') then
            return insertEsp(item, partEsp.new('VOIWeaponESP', item, item.Name))
        end

        mainMaid:mark(taskSpawner.spawn('Visuals_BRWeaponCheck', function()
            if item:IsA('MeshPart') and item:WaitForChild('InteractPrompt', 0.1) and not name:match('Barrel') then
                insertEsp(item, partEsp.new('BRWeapon', item, name))
            end
        end))
    end

    local markAttachment = function(part)
        if part.Name == 'Attachment' or part:IsA('Attachment') then
            aK[part] = true
