    local onPlayerAdded = function(player)
        if player == players.LocalPlayer then
            return
        end

        local charAddedSignal = signal.new(player.CharacterAdded)
        local charRemovingSignal = signal.new(player.CharacterRemoving)
        local destroyingSignal = signal.new(player.Destroying)
        local addedTask, removingTask, destroyTask

        addedTask = mainMaid:add(charAddedSignal:connect('Visuals_OnCharacterAdded', function(character)
            insertEsp(player, playerEsp.new('Player', player, character))
        end))
        removingTask = mainMaid:add(charRemovingSignal:connect('Visuals_OnCharacterRemoving', function()
            untrackInstance(player)
        end))
        destroyTask = mainMaid:add(destroyingSignal:connect('Visuals_OnPlayerDestroying', function()
            mainMaid[addedTask] = nil
            mainMaid[removingTask] = nil
            mainMaid[destroyTask] = nil
        end))

        if player.Character then
            insertEsp(player, playerEsp.new('Player', player, player.Character))
        end
    end

    function av.init()
        local liveFolder = workspace:WaitForChild('Live')
        local npcsFolder = workspace:WaitForChild('NPCs')
        local ingredientsFolder = workspace:WaitForChild('Ingredients')
        local thrownFolder = workspace:WaitForChild('Thrown')
        local terrainFolder = workspace:WaitForChild('Terrain')
        local shopsFolder = workspace:WaitForChild('Shops')

        trackDescendants(terrainFolder, 'Terrain', markAttachment, untrackInstance, true)
        trackDescendants(workspace, 'Workspace', co, untrackInstance, true)
        trackDescendants(thrownFolder, 'Thrown', onMiscObjectAdded, untrackInstance, true)
        trackDescendants(liveFolder, 'Live', onMobAdded, untrackInstance, true)
        trackDescendants(npcsFolder, 'NPCs', onNpcAdded, untrackInstance, true)
        trackDescendants(ingredientsFolder, 'Ingredients', onIngredientAdded, untrackInstance, true)
        trackDescendants(players, 'Players', onPlayerAdded, untrackInstance, true)
        trackDescendants(shopsFolder, 'Shops', onShopAdded, untrackInstance, true)

        for loopIndex, descendant in next, replicatedStorage:WaitForChild('MarkerWorkspace'):GetDescendants()do
            if descendant.Name == 'AreaMarker' then
                insertEsp(descendant, filteredEsp.new(partEsp.new('AreaMarker', descendant, descendant.Parent.Name or 'Unidentified Area Marker')))
            end
        end

        local localPlayer = players.LocalPlayer
        local playerGui = localPlayer:WaitForChild('PlayerGui')

        mainMaid:mark(taskSpawner.spawn('Visuals_UIVanityWait', function()
            playerGui:WaitForChild('UIVanity', 10)
            mainMaid:add(playerGuiDispatcher.subscribeAdded(markCardFrame))
            mainMaid:add(playerGuiDispatcher.subscribeRemoved(unmarkCardFrame))
            mainMaid:add(renderStepped:connect('Visuals_RenderStepped', renderFrame))
            playerGuiDispatcher.replayAdded(markCardFrame)
        end))

        local dataReplication = require(replicatedStorage:WaitForChild('Info'):WaitForChild('DataReplication'))
        local success, result = pcall(function()
            return dataReplication.GetData()
        end)

        if success and type(result) == 'table' then
            av.drinfo = result
        else
            logger.warn('GetData() failed, reading stats directly from character...')

            local currentPlayer = players.LocalPlayer
            local characterInstance = currentPlayer and currentPlayer.Character
            local humanoid = characterInstance and characterInstance:FindFirstChildOfClass('Humanoid')

            if humanoid then
                local statTable = {}
                local statNames = {
                    'Agility',
                    'Strength',
                    'Fortitude',
                    'Intelligence',
                    'Willpower',
                    'Charisma',
                    'ElementBlood',
                    'ElementFire',
                    'ElementIce',
                    'ElementLightning',
                    'ElementWind',
                    'ElementShadow',
                    'ElementMetal',
                    'WeaponHeavy',
                    'WeaponMedium',
                    'WeaponLight',
                }

                for statIndex, statName in ipairs(statNames)do
                    local statKey = 'Stat' .. statName

                    statTable[statKey] = humanoid:GetAttribute(statKey) or characterInstance:GetAttribute(statKey) or 0
                end

                statTable['TraitHealth'] = humanoid:GetAttribute('TraitHealth') or characterInstance:GetAttribute('TraitHealth') or 0
                statTable['TraitEther'] = humanoid:GetAttribute('TraitEther') or characterInstance:GetAttribute('TraitEther') or 0
                statTable['TraitWeaponDamage'] = humanoid:GetAttribute('TraitWeaponDamage') or characterInstance:GetAttribute('TraitWeaponDamage') or 0
                statTable['TraitMantraDamage'] = humanoid:GetAttribute('TraitMantraDamage') or characterInstance:GetAttribute('TraitMantraDamage') or 0
                av.drinfo = statTable

                logger.warn(
"Successfully read stats from character attributes (fallback mode).")
            else
                av.drinfo = nil

                logger.warn(
"Could not read character attributes - BuildAssistance disabled.")
            end
        end

        setupPoser()
        logger.warn('Visuals initialized.')
    end
    function av.detach()
        pcall(cleanupGankAssist)
        pcall(cleanupLowHpNotifier)
        pcall(function()
            table.clear(bB)
        end)
        pcall(function()
            mainMaid:clean()
        end)

        for index, connection in next, aL do
            pcall(function()
                connection:detach()
            end)
        end

        aO = nil
        aP = false
        aQ = nil
        aR = {}

        secondaryMaid:clean()
        logger.warn('Visuals detached.')
    end

    return av
end


return aa()

