    local getOrCreateFrame = function(cache, key, instanceType, properties)
        local frame = cache[key]

        if not frame then
            frame = createInstance(instanceType, properties, graphPlot)
            cache[key] = frame
        end

        frame.Visible = true

        return frame
    end
    local hideFrames = function(frames, startIndex)
        for i = startIndex, #frames do
            frames[i].Visible = false
        end
    end
    local computeTickStep = function(range, targetTicks)
        local rawStep = range / math.max(targetTicks, 1)
        local magnitude = 10 ^ math.floor(math.log10(math.max(rawStep, 1e-9)))
        local normalized = rawStep / magnitude
        local factor

        if normalized <= 1 then
            factor = 1
        elseif normalized <= 2 then
            factor = 2
        elseif normalized <= 5 then
            factor = 5
        else
            factor = 10
        end

        return factor * magnitude
    end
    local renderGraph = function(data, config)
        graphTitle.Text = config.title

        local samples = data.samples or {}

        if #samples < 2 then
            hideFrames(aW, 1)
            hideFrames(aX, 1)
            hideFrames(aY, 1)

            graphHint.Text = data.sampled and 'not enough samples were captured for this animation.' or 'sampling\u{2026} the graph fills in as the animation plays.'

            return
        end

        local sampleStep = math.max(1, math.floor(#samples / 220))
        local downsampled = {}

        for n = 1, #samples, sampleStep do
            downsampled[#downsampled + 1] = samples[n]
        end

        if downsampled[#downsampled] ~= samples[#samples] then
            downsampled[#downsampled + 1] = samples[#samples]
        end

        local maxValue, minValue = -math.huge, math.huge

        for idx = 1, #downsampled do
            local sampleValue = downsampled[idx][config.field] or 0

            maxValue = math.max(maxValue, sampleValue)
            minValue = math.min(minValue, sampleValue)
        end

        minValue = math.min(minValue, 0)

        if maxValue - minValue < 1e-6 then
            maxValue = minValue + 1
        end

        local padding = (maxValue - minValue) * 0.08

        maxValue = maxValue + padding

        local maxTime = math.max(downsampled[#downsampled].t, 1e-6)
        local valueSpan = maxValue - minValue

        config.plotFraction = function(plotVal)
            return math.clamp((plotVal - minValue) / valueSpan, 0, 1)
        end

        local yTickCount = 0
        local labelIndex = 0
        local valueStep = computeTickStep(valueSpan, 4)
        local firstTick = math.ceil(minValue / valueStep) * valueStep

        for tickValue = firstTick, maxValue, valueStep do
            local tickFraction = (tickValue - minValue) / valueSpan

            yTickCount = yTickCount + 1

            local hGrid = getOrCreateFrame(aX, yTickCount, 'Frame', {
                BackgroundColor3 = panelGrey,
                BorderSizePixel = 0,
                ZIndex = 103,
            })

            hGrid.Position = UDim2.new(0, 0, 1 - tickFraction, 0)
            hGrid.Size = UDim2.new(1, 0, 0, 1)
            labelIndex = labelIndex + 1

            local yTickLabel = aY[labelIndex]

            if not yTickLabel then
                yTickLabel = createInstance('TextLabel', {
                    FontFace = monoFont,
                    TextColor3 = dimGrey,
                    TextSize = 10,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    BackgroundTransparency = 1,
                    ZIndex = 103,
                }, graphFrame)
                aY[labelIndex] = yTickLabel
            end

            yTickLabel.Visible = true
            yTickLabel.Text = string.format('%.2f%s', tickValue, config.unit)
            yTickLabel.Position = UDim2.new(0, 2, 0, 44 + (1 - tickFraction) * 190 - 6)
            yTickLabel.Size = UDim2.new(0, 46 - 6, 0, 12)
            yTickLabel.TextXAlignment = Enum.TextXAlignment.Right
        end

        local timeStep = computeTickStep(maxTime, 4)

        for timeTick = timeStep, maxTime, timeStep do
            local timeFraction = timeTick / maxTime

            yTickCount = yTickCount + 1

            local vGrid = getOrCreateFrame(aX, yTickCount, 'Frame', {
                BackgroundColor3 = panelGrey,
                BorderSizePixel = 0,
                ZIndex = 103,
            })

            vGrid.Position = UDim2.new(timeFraction, 0, 0, 0)
            vGrid.Size = UDim2.new(0, 1, 1, 0)
            labelIndex = labelIndex + 1

            local xTickLabel = aY[labelIndex]

            if not xTickLabel then
                xTickLabel = createInstance('TextLabel', {
                    FontFace = monoFont,
                    TextColor3 = dimGrey,
                    TextSize = 10,
                    BackgroundTransparency = 1,
                    ZIndex = 103,
                }, graphFrame)
                aY[labelIndex] = xTickLabel
            end

            xTickLabel.Visible = true
            xTickLabel.Text = string.format('%.2fs', timeTick)
            xTickLabel.Position = UDim2.new(0, 46 + timeFraction * contentHeight - 20, 0, 44 + 190 + 4)
            xTickLabel.Size = UDim2.new(0, 40, 0, 12)
            xTickLabel.TextXAlignment = Enum.TextXAlignment.Center
        end

        hideFrames(aX, yTickCount + 1)
        hideFrames(aY, labelIndex + 1)

        local segmentCount = 0
        local toX = function(sample)
            return (sample.t / maxTime) * contentHeight
        end
        local toY = function(pt)
            local entryValue = pt[config.field] or 0

            return 190 - ((entryValue - minValue) / valueSpan) * 190
        end

        for segmentIndex = 1, #downsampled - 1 do
            local x1, y1 = toX(downsampled[segmentIndex]), toY(downsampled[segmentIndex])
            local x2, y2 = toX(downsampled[segmentIndex + 1]), toY(downsampled[segmentIndex + 1])
            local dx, dy = x2 - x1, y2 - y1
            local length = math.sqrt(dx * dx + dy * dy)

            if length >= 0.01 then
                segmentCount = segmentCount + 1

                local segment = getOrCreateFrame(aW, segmentCount, 'Frame', {
                    BackgroundColor3 = Color3.fromRGB(235, 235, 235),
                    BorderSizePixel = 0,
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    ZIndex = 104,
                })

                segment.Position = UDim2.new(0, (x1 + x2) / 2, 0, (y1 + y2) / 2)
                segment.Size = UDim2.new(0, length + 1, 0, 2)
                segment.Rotation = math.deg(math.atan2(dy, dx))
            end
        end

        hideFrames(aW, segmentCount + 1)

        local lastSample = downsampled[#downsampled]

        graphHint.Text = string.format('%d samples over %.2fs\nstarts %.2f%s, ends %.2f%s%s', #samples, lastSample.t, downsampled[1][config.field] or 0, config.unit, lastSample[config.field] or 0, config.unit, data.sampled and '' or ' (still sampling)')
    end
    local updatePlotLayout = function(plot)
        aO = plot
        graphFrame.Visible = plot ~= nil

        local hasPlot = plot ~= nil

        mainFrame.Size = UDim2.new(0, hasPlot and fourthColX or windowWidth, 0, 392)
        listPanel.Position = UDim2.new(0, hasPlot and secondColX or firstColWidth, 0, 40)
        detailsPanel.Position = UDim2.new(0, hasPlot and thirdColX or (firstColWidth + 232 + 8), 0, 40)

        if not hasPlot then
            aR = nil
            aQ = false
            graphOverlay.Visible = false
            graphSelection.Visible = false
            graphReadout.Visible = false
        end
        if hasPlot and aH then
            renderGraph(aH, plot)
        end
    end
    local findNearestSample = function(animation, fraction)
        local samples = animation and animation.samples

        if not samples or #samples == 0 then
            return nil, 0
        end

        local totalTime = samples[#samples].t
        local targetTime = math.clamp(fraction, 0, 1) * totalTime
        local nearestSample, bestDiff

        for index = 1, #samples do
            local diff = math.abs(samples[index].t - targetTime)

            if not bestDiff or diff < bestDiff then
                nearestSample, bestDiff = samples[index], diff
            end
        end

        return nearestSample, targetTime
    end
    local scrubTimeline = function(position)
        if not (aI and aH) then
            return
        end

        local sample = findNearestSample(aH, position)

        if not sample then
            return
        end

        aJ = true
        setPlaying.Image = 'rbxassetid://10734919336'

        local length = aI.Length or 0

        if length > 0 then
            aI.TimePosition = math.clamp(sample.position or 0, 0, length)
        end
    end
    local updateGraphOverlay = function()
        if not (aO and aH and aR) then
            graphOverlay.Visible = false
            graphSelection.Visible = false
            graphReadout.Visible = false

            return
        end

        local foundSample, bo = findNearestSample(aH, aR)

        if not foundSample then
            graphOverlay.Visible = false
            graphSelection.Visible = false
            graphReadout.Visible = false

            return
        end

        local value = foundSample[aO.field] or 0

        graphOverlay.Visible = true
        graphOverlay.Position = UDim2.new(aR, 0, 0, 0)
        graphSelection.Visible = true
        graphSelection.Position = UDim2.new(aR, 0, aO.plotFraction and (1 - aO.plotFraction(value)) or 0.5, 0)
        graphReadout.Visible = true
        graphReadout.Position = UDim2.new(aR, 0, 0, 20)
        graphReadout.Text = string.format('t %.3fs   %s %.2f%s', bo, aO.title, value, aO.unit)
    end
    local updateDetailsPanel = function()
        if not aH then
            nameRow.Text = '-'
            lengthRow.Text = '-'
            priorityRow.Text = '-'

            for key, button in next, {
                setAnimationId,
                setIsPlaying,
                setLooped,
                setSpeed,
                setTimePosition,
                fadeField,
                setFade,
                setEntity,
            }do
                button.Text = '-'
                button.TextColor3 = midGrey
            end

            return
        end

        local track = aH.track

        nameRow.Text = (aH.name ~= '' and aH.name) or 'Animation'
        lengthRow.Text = string.format('%.3f', aH.length or 0)
        priorityRow.Text = (tostring(aH.priority):gsub('Enum.AnimationPriority%.', ''))
        setAnimationId.Text = profiler.shortId(aH.id)
        setSpeed.Text = string.format('%.2f', aH.speed or 0)
        fadeField.Text = profiler.fadeText(aH)
        setFade.Text = string.format('%.2f / %.2f', aH.weightCurrent or 0, aH.weightTarget or 0)
        setEntity.Text = string.format('%s (%s)', aH.sourceName, aH.source)
        setEntity.TextColor3 = aH.source == 'Player' and lightGrey or midGrey

        local playing = false
        local timePosition = 0
        local looped = aH.looped

        if track then
            local success = pcall(function()
                playing = track.IsPlaying and true or false
                timePosition = tonumber(track.TimePosition) or 0
                looped = track.Looped and true or false
            end)

            if not success then
                aH.track = nil
            end
        end

        setLabelValue(setIsPlaying, playing)
        setLabelValue(setLooped, looped and true or false)

        setTimePosition.Text = string.format('%.5f', timePosition)
    end
    local clearScene = function()
        auxMaid:clean()

        aI = nil

        for index, child in next, worldModel:GetChildren()do
            if child:IsA('Model') then
                child:Destroy()
            end
        end

        statusLabel.Visible = true
    end
    local loadEntity = function(config)
        clearScene()

        if not config then
            return false
        end

        local entity = config.entity or (players.LocalPlayer and players.LocalPlayer.Character)

        if not entity or not entity.Parent then
            statusLabel.Text = 'entity is gone'

            return false
        end

        local ok, clone = pcall(function()
            local wasArchivable = entity.Archivable

            entity.Archivable = true

            local duplicate = entity:Clone()

            entity.Archivable = wasArchivable

            return duplicate
        end)

        if not ok or not clone then
            statusLabel.Text = 'could not clone entity'

            return false
        end

        auxMaid:add(clone)

        clone.Parent = worldModel

        if not clone:FindFirstChildWhichIsA('BasePart', true) then
            statusLabel.Text = 'entity has no parts'

            return false
        end

        clone:PivotTo(CFrame.new(0, 0, 0))

        local boundingCFrame, boundingSize = clone:GetBoundingBox()
        local center = boundingCFrame.Position

        camera.CFrame = CFrame.lookAt(center - Vector3.new(0, 0, boundingSize.Magnitude), center)

        local animator = clone:FindFirstChildWhichIsA('Animator', true)

        if not animator then
            statusLabel.Text = 'no animator'

            return false
        end

        for trackIndex, existingTrack in next, animator:GetPlayingAnimationTracks()do
            existingTrack:Stop()
        end

        local animation = createInstance('Animation', {
            AnimationId = config.id,
        })

        auxMaid:add(animation)

        local loadOk, animTrack = pcall(animator.LoadAnimation, animator, animation)

        if not loadOk or not animTrack then
            statusLabel.Text = 'could not load animation'

            return false
        end

        aI = animTrack

        pcall(stateListener.own, animTrack)

        aI.Priority = Enum.AnimationPriority.Action
        aI.Looped = true

        aI:Play(0, 1, animationLogger.playbackSpeed)

        aJ = false
        setPlaying.Image = 'rbxassetid://10734923549'
        statusLabel.Visible = false

        return true
    end
    local lookupAction = function(id)
        local lookup = configSection.as

        if not (id and lookup) then
            return nil
        end

        local lookupOk, result = pcall(lookup.index, lookup, id:match('(%d+)%s*$') or id)

        return lookupOk and result or nil
    end
    local countActionMarkers = function()
        w = lookupAction(aH and aH.id)

        local actionStack = w and w.actions and w.actions:stack()
        local duration = (aI and aI.Length) or 0
        local markerCount = 0

        if actionStack and duration > 0 then
            for index = 1, #actionStack do
                local action = actionStack[index]
                local bx = action:when()

                if bx >= 0 and bx <= duration then
                    markerCount = markerCount + 1

                    local marker = previewState[markerCount]

                    if not marker then
                        marker = createInstance('Frame', {
                            Name = 'Marker',
                            BorderSizePixel = 0,
                            Size = UDim2.new(0, 2, 1, 0),
                            ZIndex = 105,
                        }, progressTrack)
                        previewState[markerCount] = marker
                    end

                    marker.BackgroundColor3 = x[action._type] or Color3.fromRGB(200, 200, 200)
                    marker.Position = UDim2.new(bx / duration, -1, 0, 0)
                    marker.Visible = true
                end
            end
        end

        for lateIndex = markerCount + 1, #previewState do
            previewState[lateIndex].Visible = false
        end
    end
    local frameStartTime = 0
    local updatePlaybackFrame = function()
        local currentTime = (aI and aI.TimePosition) or 0
        local lastTime = frameStartTime

        frameStartTime = currentTime

        if aP or aQ or aJ then
            return
        end
        if not (w and aH and aH.entity and aH.entity.Parent) then
            return
        end
        if currentTime < lastTime then
            lastTime = -1
        end
        if currentTime - lastTime > 0.25 then
            return
        end

        local activeStack = w.actions and w.actions:stack()

        if not activeStack then
            return
        end

        for probeIndex = 1, #activeStack do
            local probeAction = activeStack[probeIndex]
            local probeTime = probeAction:when()

            if probeTime > lastTime and probeTime <= currentTime then
                local hitbox = probeAction.hitbox

                if not hitbox or (hitbox.X == 0 and hitbox.Y == 0 and hitbox.Z == 0) then
                    hitbox = w.hitbox
                end
                if hitbox and (hitbox.X > 0 or hitbox.Y > 0 or hitbox.Z > 0) then
                    local wasVisualizing = hitboxProbe.visualize

                    hitboxProbe.visualize = true

                    local facing = w.fhb

                    if probeAction.fhb ~= nil then
                        facing = probeAction.fhb
                    end

                    pcall(hitboxProbe.test, aH.entity, hitbox, {
                        shape = probeAction.htype or w.htype,
                        facing = facing,
                        shift = probeAction.hso or w.hso,
                    })

                    hitboxProbe.visualize = wasVisualizing
                end
            end
        end
    end
    local onEntrySelected = function(entry)
        aH = entry
        aK = true
        w = lookupAction(entry and entry.id)

        updateDetailsPanel()

        if aO then
            renderGraph(entry, aO)
        end
        if stepIndex <= 0 then
            loadEntity(entry)

            return
        end

        clearScene()

        statusLabel.Text = string.format('playing in %ds', stepIndex)

        task.delay(stepIndex, function()
            if aH == entry then
                loadEntity(entry)
            end
        end)
    end
    local createRowButtons = function(rowCount)
        for slot = #aM + 1, rowCount do
            local rowButton = createInstance('TextButton', {
                Name = 'Row' .. slot,
                Text = '',
                AutoButtonColor = false,
                BackgroundColor3 = backgroundDark,
                BorderSizePixel = 0,
                LayoutOrder = slot,
