    function drawingLib.getBoundingBox(part, size)
        local cam = workspace.CurrentCamera

        if not cam then
            return nil
        end

        local minX, minY = math.huge, math.huge
        local maxX, maxY = -math.huge, -math.huge
        local posX, posY, posZ = part.X, part.Y, part.Z
        local rightX, upX, lookX = part.RightVector.X, part.UpVector.X, part.LookVector.X
        local rightY, upY, lookY = part.RightVector.Y, part.UpVector.Y, part.LookVector.Y
        local rightZ, upZ, lookZ = part.RightVector.Z, part.UpVector.Z, part.LookVector.Z
        local sizeX, sizeY, sizeZ = size.X, size.Y, size.Z
        local worldToViewport = cam.WorldToViewportPoint

        for cornerIndex = 0, 7 do
            local signX = (cornerIndex % 2 == 0 and 1 or -1)
            local signY = (math.floor(cornerIndex / 2) % 2 == 0 and 1 or -1)
            local signZ = (math.floor(cornerIndex / 4) % 2 == 0 and 1 or -1)
            local offsetX, offsetY, offsetZ = signX * sizeX, signY * sizeY, signZ * sizeZ
            local cornerWorldX = posX + offsetX * rightX + offsetY * upX + offsetZ * lookX
            local cornerWorldY = posY + offsetX * rightY + offsetY * upY + offsetZ * lookY
            local cornerWorldZ = posZ + offsetX * rightZ + offsetY * upZ + offsetZ * lookZ
            local cornerScreen, cornerVisible = worldToViewport(cam, Vector3.new(cornerWorldX, cornerWorldY, cornerWorldZ))

            if not cornerVisible then
