        local gui = createTypeGui(drawable._type)

        if gui then
            gui.Parent = aj
        end

        local slotIndex

        if as and #as > 0 then
            slotIndex = table.remove(as)
            am[slotIndex] = {drawable, gui}
        else
            slotIndex = #am + 1
            am[slotIndex] = {drawable, gui}
        end

        drawable._sgIdx = slotIndex

        startRenderLoop()

        return drawable
    end
    local removeElement = function(target)
        if not target._sgIdx then
            return
        end

        local stored = am[target._sgIdx]

        if stored and stored[2] then
            stored[2]:Destroy()
        end

        am[target._sgIdx] = false
        as = as or {}

        table.insert(as, target._sgIdx)

        target._sgIdx = nil
    end

    if streamproofDisabled then
        am = {}
    end

    local av
    local aw
    local ax

    if immediateEnabled then
        av = {}
        aw = {}
    end

    local ay = {}
    local ayCount = 0
    local az = {
        [0] = Enum.Font.SourceSans,
        [1] = Enum.Font.SourceSans,
        [2] = Enum.Font.Code,
        [3] = Enum.Font.Code,
    }
    local measureText = function(text, size, font)
        if text == nil or text == '' then
            return Vector2.zero
        end

        local cacheKey = text .. '|' .. tostring(size) .. '|' .. tostring(font)
        local cached = ay[cacheKey]

        if cached then
            return cached
        end

        local resolvedFont = az[font] or Enum.Font.SourceSans
        local ok, measured = pcall(function()
            return textService:GetTextSize(text, size, resolvedFont, Vector2.new(9999, 9999))
        end)

        if ok and measured then
            -- Cap the cache. The previous guard used #ay on a string-keyed
            -- table (always 0) and a never-set _lastKey, so it never fired and
            -- the cache grew without bound on the immediate-drawing path.
            if ayCount >= 4096 then
                ay = {}
                ayCount = 0
            end

            ay[cacheKey] = measured
            ayCount = ayCount + 1

            return measured
        end

        return Vector2.new(#text * size * 0.5, size)
    end
    local registerDrawing = function(drawing)
        local freeIndex = table.remove(aw) or (#av + 1)

        drawing._idx = freeIndex
        av[freeIndex] = drawing

        return drawing
    end
    local unregisterDrawing = function(item)
        if type(item) ~= 'table' or not item._idx then
            return
        end

        av[item._idx] = false

        table.insert(aw, item._idx)

        item._idx = nil
    end
    local startImmediateRender = function()
        if ax then
            return
        end

        ax = immediateDrawing.GetPaint(0):Connect(function()
            for slot = 1, #av do
                local element = av[slot]

                if element and element.Visible then
                    local style = element._type
                    local transparency = element.Transparency or 1

                    if style == 'filled_square' then
                        immediateDrawing.FilledRectangle(element.Position, element.Size, element.Color, transparency, element.Rounding or 0)
                    elseif style == 'outline_square' then
                        immediateDrawing.Rectangle(element.Position, element.Size, element.Color, transparency, element.Rounding or 0, element.Thickness or 1)
                    elseif style == 'line' then
                        immediateDrawing.Line(element.From, element.To, element.Color, transparency, element.Thickness or 1)
                    elseif style == 'text' then
                        if element.Text ~= element._lastText or element.Size ~= element._lastSize or element.Font ~= element._lastFont then
                            element.TextBounds = measureText(element.Text, element.Size, element.Font)
                            element._lastText = element.Text
                            element._lastSize = element.Size
                            element._lastFont = element.Font
                        end
                        if element.Outline then
                            immediateDrawing.OutlinedText(element.Position, element.Font, element.Size, element.Color, transparency, element.OutlineColor or Color3.new(0, 0, 0), transparency, element.Text, element.Center or false)
                        else
                            immediateDrawing.Text(element.Position, element.Font, element.Size, element.Color, transparency, element.Text, element.Center or false)
                        end
                    end
                end
            end
        end)
    end

    function drawingLib.text(options)
        if streamproofDisabled then
            return createElement({
                _type = 'text',
                Visible = false,
                Center = options and options.Center or false,
                Outline = true,
                OutlineColor = Color3.fromRGB(10, 10, 10),
                Size = options and options.Size or 13,
                Font = options and options.Font or 2,
                Color = options and options.Color or Color3.fromRGB(220, 220, 220),
                Text = '',
                Position = Vector2.zero,
                TextBounds = Vector2.zero,
            })
        end
        if immediateEnabled then
            startImmediateRender()

            return registerDrawing({
                _type = 'text',
                Visible = false,
                Center = options and options.Center or false,
                Outline = true,
                OutlineColor = Color3.fromRGB(10, 10, 10),
                Size = options and options.Size or 13,
                Font = options and options.Font or 2,
                Color = options and options.Color or Color3.fromRGB(220, 220, 220),
                Text = '',
                Position = Vector2.zero,
                TextBounds = Vector2.zero,
            })
        end

        local textObject = Drawing.new('Text')

        textObject.Visible = false
        textObject.Center = options and options.Center or false
        textObject.Outline = true
        textObject.OutlineColor = Color3.fromRGB(10, 10, 10)
        textObject.Size = options and options.Size or 13
        textObject.Font = options and options.Font or 2
        textObject.Color = options and options.Color or Color3.fromRGB(220, 220, 220)
        textObject.Text = ''

        return textObject
    end

    local drawFilledSquare = function(fillColor, fillTransparency)
        if streamproofDisabled then
            return createElement({
                _type = 'filled_square',
                Visible = false,
                Color = fillColor or Color3.new(1, 1, 1),
                Transparency = fillTransparency or 0,
                Position = Vector2.zero,
                Size = Vector2.zero,
                Filled = true,
            })
        end
        if immediateEnabled then
            startImmediateRender()

            return registerDrawing({
                _type = 'filled_square',
                Visible = false,
                Color = fillColor or Color3.new(1, 1, 1),
                Transparency = fillTransparency or 0,
                Position = Vector2.zero,
                Size = Vector2.zero,
                Filled = true,
            })
        end

        local filledSquare = Drawing.new('Square')

        filledSquare.Visible = false
        filledSquare.Filled = true
        filledSquare.Color = fillColor or Color3.new(1, 1, 1)
        filledSquare.Transparency = fillTransparency or 0

        return filledSquare
    end
    local drawOutlineSquare = function(outlineColor, outlineTransparency, thickness)
        if streamproofDisabled then
            return createElement({
                _type = 'outline_square',
                Visible = false,
                Color = outlineColor or Color3.new(1, 1, 1),
                Transparency = outlineTransparency or 0,
                Thickness = thickness or 1,
                Position = Vector2.zero,
                Size = Vector2.zero,
                Filled = false,
            })
        end
        if immediateEnabled then
            startImmediateRender()

            return registerDrawing({
                _type = 'outline_square',
                Visible = false,
                Color = outlineColor or Color3.new(1, 1, 1),
                Transparency = outlineTransparency or 0,
                Thickness = thickness or 1,
                Position = Vector2.zero,
                Size = Vector2.zero,
                Filled = false,
            })
        end

        local outlineSquare = Drawing.new('Square')

        outlineSquare.Visible = false
        outlineSquare.Filled = false
        outlineSquare.Thickness = thickness or 1
        outlineSquare.Color = outlineColor or Color3.new(1, 1, 1)
        outlineSquare.Transparency = outlineTransparency or 0

        return outlineSquare
    end

    function drawingLib.box()
        return {
            bg = drawFilledSquare(Color3.fromRGB(12, 12, 12), 0.45),
            outer = drawOutlineSquare(Color3.fromRGB(10, 10, 10), 0.6, 1),
            inner = drawOutlineSquare(Color3.fromRGB(180, 180, 180), 0.35, 1),
        }
    end
    function drawingLib.bar(color)
        return {
            outline = drawFilledSquare(Color3.fromRGB(10, 10, 10), 0.3),
            bg = drawFilledSquare(Color3.fromRGB(25, 25, 25), 1),
            fill = drawFilledSquare(color or Color3.new(1, 1, 1), 1),
            overlay = drawFilledSquare(Color3.fromRGB(170, 70, 235), 1),
        }
    end
    function drawingLib.textBg()
        return drawFilledSquare(Color3.fromRGB(12, 12, 12), 0.4)
    end
    function drawingLib.updateTextBg(background, text, paddingX, paddingY, visible)
        paddingX = paddingX or 4
        paddingY = paddingY or 2

        local textBounds

        if type(text) == 'table' and text._type == 'text' then
            if text.Text ~= text._lastText or text.Size ~= text._lastSize or text.Font ~= text._lastFont then
                text.TextBounds = measureText(text.Text, text.Size, text.Font)
                text._lastText = text.Text
                text._lastSize = text.Size
                text._lastFont = text.Font
            end

            textBounds = text.TextBounds
        else
            textBounds = text.TextBounds
        end
        if visible == false or not textBounds or textBounds.X <= 0 then
            background.Visible = false

            return
        end

        local width = textBounds.X + paddingX * 2
        local height = textBounds.Y + paddingY * 2

        if text.Center then
            background.Position = Vector2.new(text.Position.X - width / 2, text.Position.Y - paddingY)
        else
            background.Position = Vector2.new(text.Position.X - paddingX, text.Position.Y - paddingY)
        end

        background.Size = Vector2.new(width, height)
        background.Visible = text.Visible
    end
    function drawingLib.separators(count)
        local separators = {}

        for index = 1, count do
            if streamproofDisabled then
                separators[index] = createElement({
                    _type = 'line',
                    Visible = false,
                    Color = Color3.fromRGB(15, 15, 15),
                    Transparency = 0,
                    Thickness = 1,
                    From = Vector2.zero,
                    To = Vector2.zero,
                })
            elseif immediateEnabled then
                startImmediateRender()

                separators[index] = registerDrawing({
                    _type = 'line',
                    Visible = false,
                    Color = Color3.fromRGB(15, 15, 15),
                    Transparency = 0,
                    Thickness = 1,
                    From = Vector2.zero,
                    To = Vector2.zero,
                })
            else
                local line = Drawing.new('Line')

                line.Visible = false
                line.Color = Color3.fromRGB(15, 15, 15)
                line.Thickness = 1
                separators[index] = line
            end
        end

        return separators
    end
    function drawingLib.updateBar(bar, x, y, width, height, progress, vertical, color, lines)
        progress = math.clamp(progress, 0, 1)

        local outlineSize = Vector2.new(width + 2, height + 2)
        local position = Vector2.new(x, y)
        local size = Vector2.new(width, height)

        bar.outline.Position = Vector2.new(x - 1, y - 1)
        bar.outline.Size = outlineSize
        bar.bg.Position = position
        bar.bg.Size = size

        if vertical then
            local fillSize = math.max(math.floor(height * progress), 0)

            bar.fill.Position = Vector2.new(x, y + height - fillSize)
            bar.fill.Size = Vector2.new(width, fillSize)
        else
            local fillSize = math.max(math.floor(width * progress), 0)

            bar.fill.Position = position
            bar.fill.Size = Vector2.new(fillSize, height)
        end
        if color then
            bar.fill.Color = color
        end
        if lines then
            local lineCount = #lines + 1

            for index, line in next, lines do
                if vertical then
                    local pos = y + math.floor(height * (index / lineCount))

                    line.From = Vector2.new(x, pos)
                    line.To = Vector2.new(x + width, pos)
                else
                    local pos = x + math.floor(width * (index / lineCount))

                    line.From = Vector2.new(pos, y)
                    line.To = Vector2.new(pos, y + height)
                end
            end
        end
    end
    function drawingLib.setBarVisible(bar, visible, lines, showOutline, showBg, showFill)
        bar.outline.Visible = visible and (showOutline ~= false)
        bar.bg.Visible = visible and (showBg ~= false)
        bar.fill.Visible = visible

        if bar.overlay then
            bar.overlay.Visible = false
        end
        if lines then
            local lineVisible = visible and (showFill ~= false)

            for index, line in next, lines do
                line.Visible = lineVisible
            end
        end
    end
    function drawingLib.setBarOverlay(bar, x, y, width, height, overlayProgress, fillProgress, vertical)
        local overlay = bar.overlay

        if not overlay then
            return
        end

        overlayProgress = math.clamp(overlayProgress, 0, 1)
        fillProgress = math.clamp(fillProgress, 0, overlayProgress)

        if fillProgress <= 0 then
            overlay.Visible = false

            return
        end
        if vertical then
            local overlaySize = height * overlayProgress
            local overlayFillSize = math.max(math.floor(height * fillProgress), 1)
            local overlayPos = y + height - overlaySize

            overlay.Position = Vector2.new(x, overlayPos)
            overlay.Size = Vector2.new(width, overlayFillSize)
        else
            local overlaySize = width * overlayProgress
            local overlayFillSize = math.max(math.floor(width * fillProgress), 1)

            overlay.Position = Vector2.new(x + overlaySize - overlayFillSize, y)
            overlay.Size = Vector2.new(overlayFillSize, height)
        end

        overlay.Visible = true
    end
    function drawingLib.setBoxVisible(box, visible, showBg)
        box.outer.Visible = visible
        box.inner.Visible = visible

        if box.bg then
            box.bg.Visible = visible and (showBg ~= false)
        end
    end
    function drawingLib.updateBox(box, position, size)
        box.outer.Position = position
        box.outer.Size = size
        box.inner.Position = position
        box.inner.Size = size

        if box.bg then
            box.bg.Position = position
            box.bg.Size = size
        end
    end
    function drawingLib.remove(target)
        if type(target) ~= 'table' then
            if target and type(target) ~= 'string' and type(target) ~= 'number' and type(target) ~= 'boolean' then
                pcall(function()
                    target:Remove()
                end)
            end

            return
        end
        if target._type then
            if target._sgIdx then
                removeElement(target)

                return
            end
            if immediateEnabled and target._idx then
                unregisterDrawing(target)

                return
            end
        end

        for key, child in next, target do
            drawingLib.remove(child)
        end
    end

    drawingLib.usingImmediate = immediateEnabled
    drawingLib.immediateAvailable = immediateGraphicsAvailable
    drawingLib.usingScreenGui = streamproofDisabled

    return drawingLib
end


return aa()

