]=],
    ["GUI/SaveManager"] = [=[
local aa = function()
    local httpService = game:GetService'HttpService'
    local toEndpointData = function(position)
        return {
            xScale = position.X.Scale,
            xOffset = position.X.Offset,
            yScale = position.Y.Scale,
            yOffset = position.Y.Offset,
        }
    end
    local toUDim2 = function(positionData)
        return UDim2.new(positionData.xScale, positionData.xOffset, positionData.yScale, positionData.yOffset)
    end
    local saveManager = {}

    do
        saveManager.Folder = 'PalantirX/Configs'
        saveManager.Ignore = {}
        saveManager.Parser = {
            Toggle = {
                Save = function(optionKey, option)
                    return {
                        type = 'Toggle',
                        idx = optionKey,
                        value = option.Value,
                    }
                end,
                Load = function(optionKey, option)
                    if Toggles[optionKey] then
                        Toggles[optionKey]:SetValue(option.value)
                    end
                end,
            },
            Slider = {
                Save = function(optionKey, option)
                    return {
                        type = 'Slider',
                        idx = optionKey,
                        value = tostring(option.Value),
                    }
                end,
                Load = function(optionKey, option)
                    if Options[optionKey] then
                        Options[optionKey]:SetValue(option.value)
                    end
                end,
            },
            Dropdown = {
                Save = function(optionKey, option)
                    return {
                        type = 'Dropdown',
                        idx = optionKey,
                        value = option.Value,
                        values = option.SaveValues and option.Values or nil,
                        mutli = option.Multi,
                    }
                end,
                Load = function(optionKey, option)
                    if Options[optionKey] then
                        Options[optionKey]:SetValue(option.value)

                        if not option.values then
                            return
                        end

                        Options[optionKey]:SetValues(option.values)
                    end
                end,
            },
            ColorPicker = {
                Save = function(optionKey, option)
                    return {
                        type = 'ColorPicker',
                        idx = optionKey,
                        hue = option.Hue,
                        sat = option.Sat,
                        vib = option.Vib,
                        transparency = option.Transparency,
                        rainbow = option.Rainbow,
                    }
                end,
                Load = function(optionKey, option)
                    if Options[optionKey] then
                        Options[optionKey].Rainbow = option.rainbow

                        Options[optionKey]:SetValue({
                            option.hue,
                            option.sat,
                            option.vib,
                        }, option.transparency)
                        Options[optionKey]:Display()
                    end
                end,
            },
            KeyPicker = {
                Save = function(optionKey, option)
                    return {
                        type = 'KeyPicker',
                        idx = optionKey,
                        mode = option.Mode,
                        key = option.Value,
                    }
                end,
                Load = function(optionKey, option)
                    if Options[optionKey] then
                        Options[optionKey]:SetValue{
                            option.key,
                            option.mode,
                        }
                    end
                end,
            },
            Input = {
                Save = function(optionKey, option)
                    return {
                        type = 'Input',
                        idx = optionKey,
                        text = option.Value,
                    }
                end,
                Load = function(optionKey, option)
                    if Options[optionKey] and type(option.text) == 'string' then
                        Options[optionKey]:SetValue(option.text)
                    end
                end,
            },
        }

        function saveManager.SetIgnoreIndexes(ae, ignoreIndexes)
            for index, ignoreIndex in next, ignoreIndexes do
                ae.Ignore[ignoreIndex] = true
            end
        end
        function saveManager.SetFolder(ae, folder)
            ae.Folder = folder

            ae:BuildFolderTree()
        end
        function saveManager.Save(ae, configName)
            if not configName then
                return false, 'no config file is selected'
            end

            local filePath = ae.Folder .. '/' .. configName .. '.json'
            local saveData = {
                objects = {},
                keybindFramePosition = toEndpointData(ae.Library.KeybindFrame.Position),
                watermarkFramePosition = toEndpointData(ae.Library.Watermark.Position),
                infoLoggerFramePosition = toEndpointData(ae.Library.InfoLoggerFrame.Position),
                infoLoggerBlacklistHistory = ae.Library.InfoLoggerData.KeyBlacklistHistory,
                infoLoggerBlacklist = ae.Library.InfoLoggerData.KeyBlacklistList,
                infoLoggerCycle = ae.Library.InfoLoggerData.InfoLoggerCycle,
                animationVisualizerFramePosition = ae.Library.AnimationVisualizerFrame and toEndpointData(ae.Library.AnimationVisualizerFrame.Position) or nil,
                depthsAssistanceFramePosition = typeof(shared.Palantir_DepthsAssistancePos) == 'UDim2' and toEndpointData(shared.Palantir_DepthsAssistancePos) or nil,
                overrideData = ae.Library.OverrideData,
            }

            for toggleKey, toggle in next, Toggles do
                if ae.Ignore[toggleKey] then
                    continue
                end

                table.insert(saveData.objects, ae.Parser[toggle.Type].Save(toggleKey, toggle))
            end
            for optionKey, option in next, Options do
                if not ae.Parser[option.Type] then
                    continue
                end
                if ae.Ignore[optionKey] then
                    continue
                end

                table.insert(saveData.objects, ae.Parser[option.Type].Save(optionKey, option))
            end

            local ok, json = pcall(httpService.JSONEncode, httpService, saveData)

            if not ok then
                local badEntries = {}
                local goodObjects = {}

                for i, object in ipairs(saveData.objects)do
                    local encodedOk = pcall(httpService.JSONEncode, httpService, object)

                    if encodedOk then
                        goodObjects[#goodObjects + 1] = object
                    else
                        badEntries[#badEntries + 1] = tostring(object and object.idx or '?')
                    end
                end

                saveData.objects = goodObjects

                local ok, ao = pcall(httpService.JSONEncode, httpService, saveData)

                if not ok then
                    saveData.overrideData = {}
                    saveData.infoLoggerBlacklist = {}
                    saveData.infoLoggerBlacklistHistory = {}
                    ok, ao = pcall(httpService.JSONEncode, httpService, saveData)
                end
                if not ok then
                    return false, 'failed to encode data: ' .. tostring(json)
                end

                writefile(filePath, ao)

                if #badEntries > 0 then
                    return true, string.format('saved with %d entry/entries skipped (bad data): %s', #badEntries, table.concat(badEntries, ', '))
                end

                return true, 
"saved (overrideData and InfoLogger blobs reset due to invalid bytes)"
            end

            writefile(filePath, json)

            return true
        end
        function saveManager.Load(ae, configName)
            if not configName then
                return false, 'no config file is selected'
            end

            local filePath = ae.Folder .. '/' .. configName .. '.json'

            if not isfile(filePath) then
                return false, 'invalid file'
            end

            local ok, decodedData = pcall(httpService.JSONDecode, httpService, readfile(filePath))

            if not ok then
                return false, 'decode error'
            end
            if decodedData.keybindFramePosition then
                ae.Library.KeybindFrame.Position = toUDim2(decodedData.keybindFramePosition)
            end
            if decodedData.watermarkFramePosition then
                ae.Library.Watermark.Position = toUDim2(decodedData.watermarkFramePosition)
            end
            if decodedData.infoLoggerFramePosition then
                ae.Library.InfoLoggerFrame.Position = toUDim2(decodedData.infoLoggerFramePosition)
            end
            if decodedData.infoLoggerBlacklistHistory then
                ae.Library.InfoLoggerData.KeyBlacklistHistory = decodedData.infoLoggerBlacklistHistory
            end
            if decodedData.animationVisualizerFramePosition and ae.Library.AnimationVisualizerFrame then
                ae.Library.AnimationVisualizerFrame.Position = toUDim2(decodedData.animationVisualizerFramePosition)
            end
            if decodedData.depthsAssistanceFramePosition then
                shared.Palantir_DepthsAssistancePos = toUDim2(decodedData.depthsAssistanceFramePosition)
            end

            local timingList = Options.TimingOverrideList

            if decodedData.overrideData and timingList then
                ae.Library.OverrideData = decodedData.overrideData

                local overrideKeys = {}

                for overrideName, overrideValue in next, decodedData.overrideData do
                    overrideKeys[#overrideKeys + 1] = overrideName
                end

                timingList:SetValues(overrideKeys)
            end

            local migrationMap = {
                EnableAutoDefense = 'EnableAutoParry',
                EnableAutoDefenseKeybind = 'EnableAutoParryKeybind',
            }

            for index, object in next, decodedData.objects do
                if type(object.idx) == 'string' and object.idx:match('^FerrymanLoot') then
                    continue
                end
                if migrationMap[object.idx] then
                    object.idx = migrationMap[object.idx]
                end
                if ae.Parser[object.type] then
                    task.spawn(function()
                        ae.Parser[object.type].Load(object.idx, object)
                    end)
                end
            end

            if decodedData.infoLoggerBlacklist then
                ae.Library.InfoLoggerData.KeyBlacklistList = decodedData.infoLoggerBlacklist

                ae.Library:RefreshInfoLogger()

                if Options and Options.BlacklistedKeys then
                    Options.BlacklistedKeys:SetValues(ae.Library:KeyBlacklists())
                end
            end
            if decodedData.infoLoggerCycle then
                ae.Library.InfoLoggerData.InfoLoggerCycle = decodedData.infoLoggerCycle

                ae.Library:RefreshInfoLogger()

                if Options and Options.BlacklistedKeys then
                    Options.BlacklistedKeys:SetValues(ae.Library:KeyBlacklists())
                end
            end

            task.defer(function()
                ae.Library:UpdateDependencyBoxes()
            end)

            return true
        end
        function saveManager.IgnoreThemeSettings(ae)
            ae:SetIgnoreIndexes{
                'BackgroundColor',
                'MainColor',
                'AccentColor',
                'OutlineColor',
                'FontColor',
                'ThemeManager_ThemeList',
                'ThemeManager_CustomThemeList',
                'ThemeManager_CustomThemeName',
            }
        end
        function saveManager.BuildFolderTree(ae)
            if not isfolder'PalantirX' then
                makefolder'PalantirX'
            end
            if not isfolder(ae.Folder) then
                makefolder(ae.Folder)
            end
        end
        function saveManager.RefreshConfigList(ae)
            local files = listfiles(ae.Folder)
            local configs = {}

            for i = 1, #files do
                local file = files[i]

                if file:sub(-5) == '.json' then
                    local cursor = file:find('.json', 1, true)
                    local extensionIndex = cursor
                    local scanChar = file:sub(cursor, cursor)

                    while scanChar ~= '/' and scanChar ~= '\\' and scanChar ~= '' do
                        cursor = cursor - 1
                        scanChar = file:sub(cursor, cursor)
                    end

                    if scanChar == '/' or scanChar == '\\' then
                        table.insert(configs, file:sub(cursor + 1, extensionIndex - 1))
                    end
                end
            end

            return configs
        end
        function saveManager.SetLibrary(ae, library)
            ae.Library = library
        end
        function saveManager.LoadAutoloadConfig(ae)
            if isfile(ae.Folder .. '/autoload.txt') then
                local configName = readfile(ae.Folder .. '/autoload.txt')
                local ok, err = ae:Load(configName)

                if not ok then
                    return ae.Library:Notify('failed to load autoload config: ' .. err)
                end

                ae.Library:Notify(string.format('autoloaded config %q', configName))
            end
        end
        function saveManager.BuildConfigSection(ae, library)
            assert(ae.Library, 'Must set SaveManager.Library')

            local groupbox = library:AddRightGroupbox'Config Manager'

            groupbox:AddInput('SaveManager_ConfigName', {
                Text = 'Config name',
            })
            groupbox:AddDropdown('SaveManager_ConfigList', {
                Text = 'Config list',
                Values = ae:RefreshConfigList(),
                AllowNull = true,
            })
            groupbox:AddDivider()
            groupbox:AddButton('Create config', function()
                local configName = Options.SaveManager_ConfigName.Value

                if configName:gsub(' ', '') == '' then
                    return ae.Library:Notify('enter a config name', 2)
                end

                local ok, result = ae:Save(configName)

                if not ok then
                    return ae.Library:Notify('failed to save config: ' .. result)
                end
                if type(result) == 'string' then
                    ae.Library:Notify(string.format('config %q created (%s)', configName, result))
                else
                    ae.Library:Notify(string.format('config %q created', configName))
                end

                Options.SaveManager_ConfigList:SetValues(ae:RefreshConfigList())
                Options.SaveManager_ConfigList:SetValue(nil)
            end):AddButton('Load config', function()
                local selectedConfig = Options.SaveManager_ConfigList.Value
                local ok, result = ae:Load(selectedConfig)

                if not ok then
                    return ae.Library:Notify('failed to load config: ' .. result)
                end

                ae.Library:Notify(string.format('config %q loaded', selectedConfig))
            end)
            groupbox:AddButton('Overwrite config', function()
                local selectedConfig = Options.SaveManager_ConfigList.Value
                local ok, result = ae:Save(selectedConfig)

                if not ok then
                    return ae.Library:Notify('failed to overwrite config: ' .. result)
                end
                if type(result) == 'string' then
                    ae.Library:Notify(string.format('config %q overwritten (%s)', selectedConfig, result))
                else
                    ae.Library:Notify(string.format('config %q overwritten', selectedConfig))
                end
            end)
            groupbox:AddButton('Refresh list', function()
                Options.SaveManager_ConfigList:SetValues(ae:RefreshConfigList())
                Options.SaveManager_ConfigList:SetValue(nil)
            end)
            groupbox:AddButton('Set as autoload', function()
                local selectedConfig = Options.SaveManager_ConfigList.Value

                writefile(ae.Folder .. '/autoload.txt', selectedConfig)
                saveManager.AutoloadLabel:SetText('Current autoload config: ' .. selectedConfig)
                ae.Library:Notify(string.format('%q set to autoload', selectedConfig))
            end)

            saveManager.AutoloadLabel = groupbox:AddLabel('Current autoload config: none', true)

            if isfile(ae.Folder .. '/autoload.txt') then
                local autoloadName = readfile(ae.Folder .. '/autoload.txt')

                saveManager.AutoloadLabel:SetText('Current autoload config: ' .. autoloadName)
            end

            saveManager:SetIgnoreIndexes{
                'SaveManager_ConfigList',
                'SaveManager_ConfigName',
            }
        end

        saveManager:BuildFolderTree()
    end

    return saveManager
end


return aa()

