            if crypt and crypt.base64decode then
                return crypt.base64decode(encodedText)
            end
            if crypt and crypt.base64 and crypt.base64.decode then
                return crypt.base64.decode(encodedText)
            end
        end)

        if decodeOk and decodeResult then
            return decodeResult
        end

        encodedText = encodedText:gsub('[^' .. 
"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/" .. '=]', '')

        return (encodedText:gsub('.', function(symbol)
            if symbol == '=' then
                return ''
            end

            local bitString, charValue = '', ((
"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):find(symbol) - 1)

            for bitPos = 6, 1, -1 do
                bitString = bitString .. (charValue % 2 ^ bitPos - charValue % 2 ^ (bitPos - 1) > 0 and '1' or '0')
            end

            return bitString
        end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(octet)
            if #octet ~= 8 then
                return ''
            end

            local byteValue = 0

            for byteIndex = 1, 8 do
                byteValue = byteValue + (octet:sub(byteIndex, byteIndex) == '1' and 2 ^ (8 - byteIndex) or 0)
            end

            return string.char(byteValue)
