    local aj = {}
    local loadAsset = function(path)
        if aj[path] then
            return aj[path]
        end
        if not isfile(path) then
            return nil
        end

        local asset

        if getcustomasset then
            local customOk, customAsset = pcall(getcustomasset, path)

            if customOk and customAsset then
                asset = customAsset
            end
        end
        if not asset and getsynasset then
            local synOk, synAsset = pcall(getsynasset, path)

            if synOk and synAsset then
                asset = synAsset
            end
        end
        if asset then
            aj[path] = asset
        end

        return asset
    end
    local getObjectPath = function(object)
        local parts = {}
        local current = object
        local rootGui = ad.Library and ad.Library.ScreenGui

        while current and current ~= rootGui do
            table.insert(parts, 1, current.Name .. ':' .. current.ClassName)

            current = current.Parent
        end

        return table.concat(parts, '/')
    end
    local getInstanceName = function(instance)
        local name = instance.Name

        if name == 'Frame' or name == '' then
            local parent = instance.Parent

            if parent then
                return parent.Name .. '>' .. instance.ClassName
            end
        end

        return name
    end

    function ad:ScanImages()
        self.AvailableImages = {}

        local allowedExtensions = {
            png = true,
            jpg = true,
            jpeg = true,
            webp = true,
            bmp = true,
        }

        if not isfolder(self.ImageFolder) then
            return
        end

        local success, files = pcall(listfiles, self.ImageFolder)

        if not success then
            return
        end

        for index, filePath in ipairs(files)do
            if isfolder(filePath) then
                continue
            end

            local fileName = filePath:match('[/\\]([^/\\]+)$') or filePath
            local extension = fileName:match('%.([^%.]+)$')

            if not extension or not allowedExtensions[extension:lower()] then
                continue
            end

            local fileUrl = self.ImageFolder .. '/' .. fileName
            local contentId = loadAsset(fileUrl)

            if contentId then
                table.insert(self.AvailableImages, {
                    name = fileName,
                    path = fileUrl,
                    url = contentId,
                })
            end
        end

        table.sort(self.AvailableImages, function(leftItem, rightItem)
            return leftItem.name < rightItem.name
        end)
    end
    function ad:GetConfigForFrame(frame)
        local frameName = getObjectPath(frame)
        local overrideConfig = self.FrameOverrides[frameName]

        if overrideConfig and overrideConfig.fileName then
            return overrideConfig
        end
        if self.GlobalConfig.enabled and self.GlobalConfig.fileName then
            return self.GlobalConfig
        end

        return nil
    end

    local isDescendant = function(descendant, ancestor)
        if not ancestor then
            return false
        end

        return descendant == ancestor or descendant:IsDescendantOf(ancestor)
    end

    function ad:ApplyAll()
        local library = self.Library
        local screenGui = library.ScreenGui

        if not screenGui then
            return
        end

        self:RemoveAll(true)

        local panel = self.Panel
        local applyToFrame = function(frame)
            if isDescendant(frame, panel) then
                return
            end
            if frame.BackgroundTransparency >= 1 then
                return
            end
            if frame:FindFirstChild('_TE_BG') then
                return
            end

            local config = self.FrameOverrides[getObjectPath(frame)]
            local selectedConfig

            if config and config.fileName then
                selectedConfig = config
            else
                if frame.ZIndex >= 10 then
                    return
                end
                if (frame.AbsoluteSize.X * frame.AbsoluteSize.Y) < 8000 then
                    return
                end
                if self.GlobalConfig.enabled and self.GlobalConfig.fileName then
                    selectedConfig = self.GlobalConfig
                end
            end
            if not selectedConfig then
                return
            end

            local imagePath = self.ImageFolder .. '/' .. selectedConfig.fileName
            local contentId = loadAsset(imagePath)

            if not contentId then
                return
            end
            if self.TrueOriginals[frame] == nil then
                self.TrueOriginals[frame] = frame.BackgroundTransparency
            end

            self.OriginalTransparencies[frame] = self.TrueOriginals[frame]
            frame.BackgroundTransparency = selectedConfig.boxTransparency or 0.25

            local imageLabel = Instance.new('ImageLabel')

            imageLabel.Name = '_TE_BG'
            imageLabel.BackgroundTransparency = 1
            imageLabel.ImageTransparency = selectedConfig.transparency or 0.6
            imageLabel.Size = UDim2.new(1, 0, 1, 0)
            imageLabel.ScaleType = Enum.ScaleType.Crop
            imageLabel.Image = contentId
            imageLabel.ImageColor3 = Color3.new(selectedConfig.imageColor and selectedConfig.imageColor[1] or 1, selectedConfig.imageColor and selectedConfig.imageColor[2] or 1, selectedConfig.imageColor and selectedConfig.imageColor[3] or 1)
            imageLabel.BorderSizePixel = 0
            imageLabel.ZIndex = 0
            imageLabel.Parent = frame
            self.AppliedLabels[frame] = imageLabel
        end

        local function scan(parent, depth)
            if depth > 30 then
                return
            end

            for childIndex, child in pairs(parent:GetChildren())do
                if isDescendant(child, panel) then
                    continue
                end
                if (child:IsA('Frame') or child:IsA('ScrollingFrame')) and child.Visible then
                    applyToFrame(child)
                    scan(child, depth + 1)
                end
            end
        end

        scan(screenGui, 0)
        self:StartMonitor()
        self:SaveConfig()
    end
    function ad:RemoveAll(skipSave)
        self.MonitorActive = false

        for frame, label in pairs(self.AppliedLabels)do
            if label and label.Parent then
                label:Destroy()
            end
        end
        for originalFrame, transparency in pairs(self.OriginalTransparencies)do
            if originalFrame and originalFrame.Parent then
                originalFrame.BackgroundTransparency = transparency
            end
        end

        self.AppliedLabels = {}
        self.OriginalTransparencies = {}

        if not skipSave then
            self:SaveConfig()
            self:SetStatus('Cleared all backgrounds')
        end
    end
    function ad:AssignToFrame(targetFrame)
        if not self.SelectedImage then
            return self:SetStatus('Select an image first')
        end

        local frameKey = getObjectPath(targetFrame)

        self.FrameOverrides[frameKey] = {
            fileName = self.SelectedImage,
            transparency = self.GlobalConfig.transparency,
            boxTransparency = self.GlobalConfig.boxTransparency,
            imageColor = self.GlobalConfig.imageColor,
        }

        self:ApplyAll()
        self:SetStatus('Assigned to: ' .. getInstanceName(targetFrame))
    end
    function ad:RemoveFromFrame(frameToRemove)
        local overrideKey = getObjectPath(frameToRemove)

        self.FrameOverrides[overrideKey] = nil

        self:ApplyAll()
        self:SetStatus('Removed override from: ' .. getInstanceName(frameToRemove))
    end
    function ad:SetGlobal()
        if not self.SelectedImage then
            return self:SetStatus('Select an image first')
        end

        self.GlobalConfig.enabled = true
        self.GlobalConfig.fileName = self.SelectedImage

        self:ApplyAll()
        self:SetStatus('Global: ' .. self.SelectedImage)
    end
    function ad:ClearGlobal()
        self.GlobalConfig.enabled = false
        self.GlobalConfig.fileName = nil

        self:ApplyAll()
        self:SetStatus('Global cleared')
    end
    function ad:StartMonitor()
        if self.MonitorActive then
            return
        end

        self.MonitorActive = true

        local library = self.Library
        local screenGui = library.ScreenGui
        local panel = self.Panel

        task.spawn(function()
            while self.MonitorActive do
                task.wait(0.15)

                if not self.MonitorActive or not screenGui then
                    break
                end

                local function processFrame(container, depth)
                    if depth > 30 then
                        return
                    end

                    for childIndex, child in pairs(container:GetChildren())do
                        if isDescendant(child, panel) then
                            continue
                        end
                        if (child:IsA('Frame') or child:IsA('ScrollingFrame')) and child.Visible then
                            if not child:FindFirstChild('_TE_BG') and not self.AppliedLabels[child] then
                                if child.BackgroundTransparency < 1 then
                                    local override = self.FrameOverrides[getObjectPath(child)]
                                    local config

                                    if override and override.fileName then
                                        config = override
                                    elseif child.ZIndex < 10 and (child.AbsoluteSize.X * child.AbsoluteSize.Y) >= 8000 and self.GlobalConfig.enabled and self.GlobalConfig.fileName then
                                        config = self.GlobalConfig
                                    end
                                    if config then
                                        local image = loadAsset(self.ImageFolder .. '/' .. config.fileName)

                                        if image then
                                            if self.TrueOriginals[child] == nil then
                                                self.TrueOriginals[child] = child.BackgroundTransparency
                                            end

                                            self.OriginalTransparencies[child] = self.TrueOriginals[child]
                                            child.BackgroundTransparency = config.boxTransparency or 0.25

                                            local imageLabel = Instance.new('ImageLabel')

                                            imageLabel.Name = '_TE_BG'
                                            imageLabel.BackgroundTransparency = 1
                                            imageLabel.ImageTransparency = config.transparency or 0.6
                                            imageLabel.Size = UDim2.new(1, 0, 1, 0)
                                            imageLabel.ScaleType = Enum.ScaleType.Crop
                                            imageLabel.Image = image
                                            imageLabel.ImageColor3 = Color3.new(config.imageColor and config.imageColor[1] or 1, config.imageColor and config.imageColor[2] or 1, config.imageColor and config.imageColor[3] or 1)
                                            imageLabel.BorderSizePixel = 0
                                            imageLabel.ZIndex = 0
                                            imageLabel.Parent = child
                                            self.AppliedLabels[child] = imageLabel
                                        end
                                    end
                                end
                            end

                            processFrame(child, depth + 1)
                        end
                    end
                end

                processFrame(screenGui, 0)
            end
        end)
    end
    function ad:GetCurrentColors()
        local libraryRef = self.Library
        local colors = {}

        for index, colorName in ipairs(ae)do
            colors[colorName] = libraryRef[colorName]
        end

        return colors
    end
    function ad:ApplyColors(colors)
        local library = self.Library

        for key, colorValue in pairs(colors)do
            if typeof(colorValue) == 'Color3' then
                library[key] = colorValue

                if Options and Options[key] then
                    Options[key]:SetValueRGB(colorValue)
                end
            elseif type(colorValue) == 'string' then
                local parsedColor = Color3.fromHex(colorValue)

                library[key] = parsedColor

                if Options and Options[key] then
                    Options[key]:SetValueRGB(parsedColor)
                end
            elseif type(colorValue) == 'table' and colorValue.hue then
                library[key] = Color3.fromHSV(colorValue.hue, colorValue.sat, colorValue.vib)

                if Options and Options[key] then
                    Options[key].Rainbow = colorValue.rainbow

                    Options[key]:SetValue({
                        colorValue.hue,
                        colorValue.sat,
                        colorValue.vib,
                    }, colorValue.transparency)
                    Options[key]:Display()
                end
            end
        end

        if self.ThemeManager then
            self.ThemeManager:ThemeUpdate()
        end

        self:RefreshColorSwatches()
    end
    function ad:RefreshColorSwatches()
        if not self.ColorSwatches then
            return
        end

        local library = self.Library

        for swatchKey, swatch in pairs(self.ColorSwatches)do
            if swatch.swatch and swatch.swatch.Parent and library[swatchKey] then
                swatch.swatch.BackgroundColor3 = library[swatchKey]
            end
        end
    end
    function ad:SetupPlacementMode()
        local library = self.Library
        local screenGui = library.ScreenGui

        if not screenGui then
            return
        end

        local highlightFrame = library:Create('Frame', {
            Name = '_TE_Highlight',
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Size = UDim2.new(0, 0, 0, 0),
            ZIndex = 180,
            Visible = false,
            Parent = screenGui,
        })

        library:Create('UIStroke', {
            Color = library.AccentColor,
            Thickness = 2,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = highlightFrame,
        })

        local highlightLabel = library:Create('TextLabel', {
            BackgroundColor3 = library.AccentColor,
            BackgroundTransparency = 0.1,
            Size = UDim2.new(1, 0, 0, 16),
            Position = UDim2.new(0, 0, 0, -16),
            Text = '',
            TextColor3 = Color3.new(0, 0, 0),
            TextSize = 10,
            FontFace = library.Font,
            TextXAlignment = Enum.TextXAlignment.Center,
            ZIndex = 181,
            Parent = highlightFrame,
        })

        library:Create('UICorner', {
            CornerRadius = UDim.new(0, 2),
            Parent = highlightLabel,
        })

        self.HighlightBox = highlightFrame
        self.HighlightLabel = highlightLabel

        userInputService.InputChanged:Connect(function(input)
            if not self.PlacementMode then
                return
            end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement then
                return
            end

            local mouseLocation = userInputService:GetMouseLocation()
            local playerGui = players.LocalPlayer:FindFirstChildOfClass('PlayerGui')

            if not playerGui then
                return
            end

            local guiObjects = playerGui:GetGuiObjectsAtPosition(mouseLocation.X, mouseLocation.Y - 36)
            local hoveredFrame

            for index, obj in ipairs(guiObjects)do
                if not (obj:IsA('Frame') or obj:IsA('ScrollingFrame')) then
                    continue
                end
                if not obj:IsDescendantOf(screenGui) then
                    continue
                end
                if isDescendant(obj, self.Panel) then
                    continue
                end
                if obj.Name == '_TE_Highlight' or obj.Name == '_TE_Overlay' then
                    continue
                end
                if obj.BackgroundTransparency >= 1 then
                    continue
                end

                hoveredFrame = obj

                break
            end

            if hoveredFrame then
                self.HoveredFrame = hoveredFrame
                highlightFrame.Position = UDim2.fromOffset(hoveredFrame.AbsolutePosition.X, hoveredFrame.AbsolutePosition.Y)
                highlightFrame.Size = UDim2.fromOffset(hoveredFrame.AbsoluteSize.X, hoveredFrame.AbsoluteSize.Y)
                highlightLabel.Text = getInstanceName(hoveredFrame) .. ' (' .. math.floor(hoveredFrame.AbsoluteSize.X) .. 'x' .. math.floor(hoveredFrame.AbsoluteSize.Y) .. ')'
                highlightFrame.Visible = true
            else
                self.HoveredFrame = nil
                highlightFrame.Visible = false
            end
        end)
        userInputService.InputBegan:Connect(function(input)
            if not self.PlacementMode then
                return
            end
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                if self.HoveredFrame then
                    self:AssignToFrame(self.HoveredFrame)
                end

                self:ExitPlacementMode()
            elseif input.UserInputType == Enum.UserInputType.MouseButton2 or input.KeyCode == Enum.KeyCode.Escape then
                self:ExitPlacementMode()
            end
        end)

        local overlayButton = library:Create('TextButton', {
            Name = '_TE_Overlay',
            BackgroundTransparency = 0.95,
            BackgroundColor3 = Color3.new(0, 0, 0),
            Size = UDim2.new(1, 0, 1, 0),
            ZIndex = 170,
            Text = '',
            AutoButtonColor = false,
            Visible = false,
            Parent = screenGui,
        })

        self.Overlay = overlayButton
    end
    function ad:EnterPlacementMode()
        if not self.SelectedImage then
            return self:SetStatus('Select an image first')
        end

        self.PlacementMode = true

        if self.Overlay then
            self.Overlay.Visible = true
        end

        self:SetStatus(
"PLACE MODE: hover & click any frame (right-click/esc to cancel)")
    end
    function ad:ExitPlacementMode()
        self.PlacementMode = false
        self.HoveredFrame = nil

        if self.Overlay then
            self.Overlay.Visible = false
        end
        if self.HighlightBox then
            self.HighlightBox.Visible = false
        end

        self:SetStatus('Ready')
    end

    local clampByteValue = function(value)
        value = tonumber(value) or 0

        if value < 0 then
            return 0
        end
        if value > 255 then
            return 255
        end

        return math.floor(value + 0.5)
    end
    local hexToColor = function(hexString)
        hexString = (hexString or ''):gsub('#', ''):gsub('%s', '')

        if #hexString == 3 then
            hexString = hexString:sub(1, 1) .. hexString:sub(1, 1) .. hexString:sub(2, 2) .. hexString:sub(2, 2) .. hexString:sub(3, 3) .. hexString:sub(3, 3)
        end
        if #hexString ~= 6 then
            return nil
        end

        local red = tonumber(hexString:sub(1, 2), 16)
        local green = tonumber(hexString:sub(3, 4), 16)
        local blue = tonumber(hexString:sub(5, 6), 16)

        if not (red and green and blue) then
            return nil
        end

        return Color3.fromRGB(red, green, blue)
    end
    local colorToHex = function(color)
        return string.format('%02x%02x%02x', math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
    end

    function ad:BuildInlineColorPicker(parent)
        local library = self.Library
        local panel = library:Create('Frame', {
            Name = 'InlineColorPicker',
            BackgroundColor3 = Color3.fromRGB(20, 20, 20),
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, 70),
            LayoutOrder = 3,
            Visible = false,
            ZIndex = 203,
            Parent = parent,
        })

        library:Create('UICorner', {
            CornerRadius = UDim.new(0, 3),
            Parent = panel,
        })
        library:Create('UIStroke', {
            Color = Color3.fromRGB(40, 40, 40),
            Thickness = 1,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = panel,
        })

        local titleLabel = library:Create('TextLabel', {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, -28, 0, 14),
            Position = UDim2.new(0, 8, 0, 4),
            Text = 'Editing',
            TextColor3 = Color3.fromRGB(170, 170, 170),
            TextSize = 10,
            FontFace = library.Font,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 204,
            Parent = panel,
        })
        local closeButton = library:Create('TextButton', {
            BackgroundTransparency = 1,
            Size = UDim2.new(0, 20, 0, 14),
            Position = UDim2.new(1, -22, 0, 4),
            Text = 'X',
            TextColor3 = Color3.fromRGB(140, 140, 140),
            TextSize = 11,
            FontFace = library.Font,
            ZIndex = 204,
            Parent = panel,
        })

        closeButton.MouseButton1Click:Connect(function()
            self:CloseColorPicker()
        end)

        local previewFrame = library:Create('Frame', {
            BackgroundColor3 = Color3.new(0, 0, 0),
            BorderSizePixel = 0,
            Size = UDim2.new(0, 42, 0, 42),
            Position = UDim2.new(0, 8, 0, 22),
            ZIndex = 204,
            Parent = panel,
        })

        library:Create('UICorner', {
            CornerRadius = UDim.new(0, 3),
            Parent = previewFrame,
        })
        library:Create('UIStroke', {
            Color = Color3.fromRGB(55, 55, 55),
            Thickness = 1,
            Parent = previewFrame,
        })

        local createField = function(labelText, x, y, width, container)
            local label = library:Create('TextLabel', {
                BackgroundTransparency = 1,
                Size = UDim2.new(0, 14, 0, 18),
                Position = UDim2.new(0, x - 12, 0, y),
                Text = labelText,
                TextColor3 = Color3.fromRGB(120, 120, 120),
                TextSize = 10,
                FontFace = library.Font,
                TextXAlignment = Enum.TextXAlignment.Right,
                ZIndex = 204,
                Parent = container,
            })
            local textBox = library:Create('TextBox', {
                BackgroundColor3 = Color3.fromRGB(14, 14, 14),
                BorderSizePixel = 0,
                Size = UDim2.new(0, width, 0, 18),
                Position = UDim2.new(0, x + 4, 0, y),
                Text = '',
                PlaceholderText = '',
                TextColor3 = Color3.fromRGB(210, 210, 210),
                TextSize = 11,
                FontFace = library.Font,
                TextXAlignment = Enum.TextXAlignment.Left,
                ClearTextOnFocus = false,
                ZIndex = 204,
                Parent = container,
            })

            library:Create('UICorner', {
                CornerRadius = UDim.new(0, 3),
                Parent = textBox,
            })
            library:Create('UIPadding', {
                PaddingLeft = UDim.new(0, 5),
                PaddingRight = UDim.new(0, 5),
                Parent = textBox,
            })
            library:Create('UIStroke', {
                Color = Color3.fromRGB(40, 40, 40),
                Thickness = 1,
                Parent = textBox,
            })

            return textBox, label
        end
        local hexBox = createField('#', 70, 24, 100, panel)
        local rBox = createField('R', 70, 46, 28, panel)
        local gBox = createField('G', 116, 46, 28, panel)
        local bBox = createField('B', 162, 46, 28, panel)
        local createButton = function(buttonText, xPos, yPos, buttonWidth, callback)
            local button = library:Create('TextButton', {
                BackgroundColor3 = Color3.fromRGB(28, 28, 28),
                BorderSizePixel = 0,
                Size = UDim2.new(0, buttonWidth, 0, 18),
                Position = UDim2.new(0, xPos, 0, yPos),
                Text = buttonText,
                TextColor3 = Color3.fromRGB(200, 200, 200),
                TextSize = 10,
                FontFace = library.Font,
                AutoButtonColor = false,
                ZIndex = 204,
                Parent = panel,
            })

            library:Create('UICorner', {
                CornerRadius = UDim.new(0, 3),
                Parent = button,
            })
            library:Create('UIStroke', {
                Color = Color3.fromRGB(45, 45, 45),
                Thickness = 1,
                Parent = button,
            })
            button.MouseEnter:Connect(function()
                button.BackgroundColor3 = library.AccentColor
                button.TextColor3 = Color3.new(0, 0, 0)
            end)
            button.MouseLeave:Connect(function()
                button.BackgroundColor3 = Color3.fromRGB(28, 28, 28)
                button.TextColor3 = Color3.fromRGB(200, 200, 200)
            end)
            button.MouseButton1Click:Connect(callback)

            return button
        end

        createButton('Copy', 200, 24, 50, function()
            local aF = self.SelectedColorField

            if not aF or not library[aF] then
                return
            end
            if setclipboard then
                setclipboard('#' .. colorToHex(library[aF]))
                self:SetStatus('Copied #' .. colorToHex(library[aF]))
            end
        end)
        createButton('Paste', 254, 24, 50, function()
            if not getclipboard then
                return
            end

            local success, result = pcall(getclipboard)

            if not success or not result then
                return
            end

            local color = hexToColor(result)

            if color then
                self:WriteColorToSelected(color)
            end
        end)
        hexBox.FocusLost:Connect(function()
            local parsedColor = hexToColor(hexBox.Text)

            if parsedColor then
                self:WriteColorToSelected(parsedColor)
            else
                self:SyncInlinePickerFromField()
            end
        end)

        local applyRgb = function()
            local rgbColor = Color3.fromRGB(clampByteValue(rBox.Text), clampByteValue(gBox.Text), clampByteValue(bBox.Text))

            self:WriteColorToSelected(rgbColor)
        end

        rBox.FocusLost:Connect(applyRgb)
        gBox.FocusLost:Connect(applyRgb)
        bBox.FocusLost:Connect(applyRgb)

        self.InlinePicker = {
            panel = panel,
            title = titleLabel,
            preview = previewFrame,
            hexBox = hexBox,
            rBox = rBox,
            gBox = gBox,
            bBox = bBox,
        }
    end
    function ad:OpenColorPicker(colorField)
        if not self.InlinePicker then
            return
        end
        if self.SelectedColorField == colorField and self.InlinePicker.panel.Visible then
            return self:CloseColorPicker()
        end

        self.SelectedColorField = colorField
        self.InlinePicker.panel.Visible = true
        self.InlinePicker.title.Text = 'Editing: ' .. (af[colorField] or colorField)

        self:SyncInlinePickerFromField()
        self:HighlightSelectedSwatch()
    end
    function ad:CloseColorPicker()
        if self.InlinePicker then
            self.InlinePicker.panel.Visible = false
        end

        self.SelectedColorField = nil

        self:HighlightSelectedSwatch()
    end
    function ad:HighlightSelectedSwatch()
        local library = self.Library

        for swatchKey, swatch in pairs(self.ColorSwatches)do
            if swatch.stroke then
                swatch.stroke.Color = (swatchKey == self.SelectedColorField) and library.AccentColor or Color3.fromRGB(40, 40, 40)
            end
        end
    end
    function ad:SyncInlinePickerFromField()
        local selectedField = self.SelectedColorField

        if not selectedField or not self.InlinePicker then
            return
        end

        local currentColor = (Options and Options[selectedField] and Options[selectedField].Value) or self.Library[selectedField] or Color3.new(0, 0, 0)

        self.InlinePicker.preview.BackgroundColor3 = currentColor
        self.InlinePicker.hexBox.Text = '#' .. colorToHex(currentColor)
        self.InlinePicker.rBox.Text = tostring(math.floor(currentColor.R * 255 + 0.5))
        self.InlinePicker.gBox.Text = tostring(math.floor(currentColor.G * 255 + 0.5))
        self.InlinePicker.bBox.Text = tostring(math.floor(currentColor.B * 255 + 0.5))
    end
    function ad:WriteColorToSelected(newColor)
        local fieldName = self.SelectedColorField

        if not fieldName then
            return
        end
        if Options and Options[fieldName] and Options[fieldName].SetValueRGB then
            Options[fieldName]:SetValueRGB(newColor)
        else
            self.Library[fieldName] = newColor

            if self.ColorSwatches[fieldName] then
                self.ColorSwatches[fieldName].swatch.BackgroundColor3 = newColor
            end
            if self.ThemeManager then
                self.ThemeManager:ThemeUpdate()
            end
        end

        self:SyncInlinePickerFromField()
        self:SaveConfig()
    end
    function ad:BuildPresetsRow(parent)
        local lib = self.Library
        local themeManager = self.ThemeManager
        local presetsFrame = lib:Create('Frame', {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 22),
            LayoutOrder = 4,
            ZIndex = 203,
            Parent = parent,
        })

        lib:Create('TextLabel', {
            BackgroundTransparency = 1,
            Size = UDim2.new(0, 56, 1, 0),
            Text = 'Presets',
            TextColor3 = Color3.fromRGB(110, 110, 110),
            TextSize = 10,
            FontFace = lib.Font,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 204,
            Parent = presetsFrame,
        })

        local scrollFrame = lib:Create('ScrollingFrame', {
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Size = UDim2.new(1, -56, 1, 0),
            Position = UDim2.new(0, 56, 0, 0),
            ScrollBarThickness = 2,
            ScrollBarImageColor3 = Color3.fromRGB(60, 60, 60),
            ScrollingDirection = Enum.ScrollingDirection.X,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.X,
            ZIndex = 204,
            Parent = presetsFrame,
        })

        lib:Create('UIListLayout', {
            FillDirection = Enum.FillDirection.Horizontal,
            Padding = UDim.new(0, 4),
            SortOrder = Enum.SortOrder.LayoutOrder,
            Parent = scrollFrame,
        })

        if not themeManager or not themeManager.BuiltInThemes then
            return
        end

        local themeNames = {}

        for themeName in pairs(themeManager.BuiltInThemes)do
            themeNames[#themeNames + 1] = themeName
        end

        table.sort(themeNames, function(themeA, themeB)
            return (themeManager.BuiltInThemes[themeA][1] or 99) < (themeManager.BuiltInThemes[themeB][1] or 99)
        end)

        for index, presetName in ipairs(themeNames)do
            local themeData = themeManager.BuiltInThemes[presetName][2]
            local accentColor = themeData.AccentColor
            local swatchColor

            if type(accentColor) == 'string' then
                swatchColor = hexToColor(accentColor)
            end
            if not swatchColor and type(themeData.MainColor) == 'string' then
                swatchColor = hexToColor(themeData.MainColor)
            end

            swatchColor = swatchColor or Color3.fromRGB(80, 80, 80)

            local presetButton = lib:Create('TextButton', {
                BackgroundColor3 = Color3.fromRGB(22, 22, 22),
                BorderSizePixel = 0,
                Size = UDim2.new(0, 80, 1, 0),
                Text = '',
                AutoButtonColor = false,
                LayoutOrder = index,
                ZIndex = 205,
                Parent = scrollFrame,
            })

            lib:Create('UICorner', {
                CornerRadius = UDim.new(0, 3),
                Parent = presetButton,
            })
            lib:Create('UIStroke', {
                Color = Color3.fromRGB(42, 42, 42),
                Thickness = 1,
                Parent = presetButton,
            })
            lib:Create('Frame', {
                BackgroundColor3 = swatchColor,
                BorderSizePixel = 0,
                Size = UDim2.new(0, 10, 0, 10),
                Position = UDim2.new(0, 6, 0.5, -5),
                ZIndex = 206,
                Parent = presetButton,
            })
            lib:Create('TextLabel', {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, -22, 1, 0),
                Position = UDim2.new(0, 20, 0, 0),
                Text = presetName,
                TextColor3 = Color3.fromRGB(200, 200, 200),
                TextSize = 10,
                FontFace = lib.Font,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 206,
                Parent = presetButton,
            })
            presetButton.MouseButton1Click:Connect(function()
                themeManager:ApplyTheme(presetName)
                self:RefreshColorSwatches()

                if self.SelectedColorField then
                    self:SyncInlinePickerFromField()
                end

                self:SaveConfig()
                self:SetStatus('Applied preset: ' .. presetName)
            end)
        end
    end
