    function ad:UpdateTransLabel()
        if self.TransLabel then
            self.TransLabel.Text = string.format('Image: %.2f  Box: %.2f', self.GlobalConfig.transparency, self.GlobalConfig.boxTransparency)
        end
    end
    function ad:RefreshLiveTransparency()
        for labelName, imageLabel in pairs(self.AppliedLabels)do
            if imageLabel and imageLabel.Parent then
                imageLabel.ImageTransparency = self.GlobalConfig.transparency
            end
        end
        for backgroundCell, boxTransparency in pairs(self.OriginalTransparencies)do
            if backgroundCell and backgroundCell.Parent then
                backgroundCell.BackgroundTransparency = self.GlobalConfig.boxTransparency
            end
        end

        self:SaveConfig()
    end
    function ad:SetStatus(status)
        if self.StatusLabel then
            self.StatusLabel.Text = status
        end
    end
    function ad:RefreshGallery()
        local library = self.Library
        local galleryFrame = self.GalleryFrame

        if not galleryFrame then
            return
        end

        for cellIndex, cell in ipairs(self.GalleryCells)do
            if cell.frame and cell.frame.Parent then
                cell.frame:Destroy()
            end
        end

        self.GalleryCells = {}

        for imageIndex, image in ipairs(self.AvailableImages)do
            local imageButton = library:Create('ImageButton', {
                BackgroundColor3 = Color3.fromRGB(22, 22, 22),
                BorderSizePixel = 0,
                Image = image.url,
                ScaleType = Enum.ScaleType.Crop,
                ZIndex = 204,
                AutoButtonColor = false,
                Parent = galleryFrame,
            })

            library:Create('UICorner', {
                CornerRadius = UDim.new(0, 4),
                Parent = imageButton,
            })

            local borderStroke = library:Create('UIStroke', {
                Color = Color3.fromRGB(35, 35, 35),
                Thickness = 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                Parent = imageButton,
            })
            local nameLabel = library:Create('TextLabel', {
                BackgroundColor3 = Color3.new(0, 0, 0),
                BackgroundTransparency = 0.3,
                Size = UDim2.new(1, 0, 0, 13),
                Position = UDim2.new(0, 0, 1, -13),
                Text = image.name,
                TextColor3 = Color3.new(1, 1, 1),
                TextSize = 8,
                FontFace = library.Font,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 206,
                Visible = false,
                Parent = imageButton,
            })

            imageButton.MouseEnter:Connect(function()
                nameLabel.Visible = true

                if self.SelectedImage ~= image.name then
                    borderStroke.Color = Color3.fromRGB(80, 80, 80)
                end
            end)
            imageButton.MouseLeave:Connect(function()
                nameLabel.Visible = false

                if self.SelectedImage ~= image.name then
                    borderStroke.Color = Color3.fromRGB(35, 35, 35)
                end
            end)
            imageButton.MouseButton1Click:Connect(function()
                self:SelectImage(image.name)
            end)

            self.GalleryCells[#self.GalleryCells + 1] = {
                frame = imageButton,
                border = borderStroke,
                name = image.name,
            }
        end

        if #self.AvailableImages == 0 then
            library:Create('TextLabel', {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 60),
                Text = 'No images in ' .. self.ImageFolder .. '\nPut .png/.jpg files there',
                TextColor3 = Color3.fromRGB(70, 70, 70),
                TextSize = 11,
                FontFace = library.Font,
                ZIndex = 204,
                Parent = galleryFrame,
            })
        end
    end
    function ad:SelectImage(imageName)
        local themeLibrary = self.Library

        self.SelectedImage = imageName

        for galleryIndex, galleryCell in ipairs(self.GalleryCells)do
            if galleryCell.name == imageName then
                galleryCell.border.Color = themeLibrary.AccentColor
                galleryCell.border.Thickness = 2
            else
                galleryCell.border.Color = Color3.fromRGB(35, 35, 35)
                galleryCell.border.Thickness = 1
            end
        end

        self:SetStatus('Selected: ' .. imageName)
    end
    function ad:ShowImportPicker(anchorButton)
        if not isfolder(self.ExportFolder) then
            return self:SetStatus('No themes folder')
        end

        local success, files = pcall(listfiles, self.ExportFolder)

        if not success then
            return
        end

        local fileNames = {}

        for fileIndex, filePath in ipairs(files)do
            local fileName = filePath:match('[/\\]([^/\\]+)$') or filePath

            if fileName:sub(-5) == '.json' and fileName ~= 'editor_state.json' then
                table.insert(fileNames, fileName)
            end
        end

        if #fileNames == 0 then
            return self:SetStatus('No theme files found')
        end

        local pickLibrary = self.Library
        local screenGui = pickLibrary.ScreenGui
        local existingPicker = screenGui:FindFirstChild('_TE_Picker')

        if existingPicker then
            existingPicker:Destroy()
        end

        local pickerFrame = pickLibrary:Create('Frame', {
            Name = '_TE_Picker',
            BackgroundColor3 = Color3.fromRGB(14, 14, 14),
            BorderSizePixel = 0,
            Size = UDim2.fromOffset(220, math.min(#fileNames * 22 + 4, 160)),
            Position = anchorButton and UDim2.fromOffset(anchorButton.AbsolutePosition.X, anchorButton.AbsolutePosition.Y + anchorButton.AbsoluteSize.Y + 2) or UDim2.new(0.5, 
-110, 0.5, -60),
            ZIndex = 300,
            ClipsDescendants = true,
            Parent = screenGui,
        })

        pickLibrary:Create('UICorner', {
            CornerRadius = UDim.new(0, 4),
            Parent = pickerFrame,
        })
        pickLibrary:Create('UIStroke', {
            Color = pickLibrary.AccentColor,
            Thickness = 1,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = pickerFrame,
        })

        local scrollFrame = pickLibrary:Create('ScrollingFrame', {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 1, 0),
            CanvasSize = UDim2.new(0, 0, 0, #fileNames * 22),
            ScrollBarThickness = 3,
            ZIndex = 301,
            Parent = pickerFrame,
        })

        pickLibrary:Create('UIListLayout', {
            SortOrder = Enum.SortOrder.LayoutOrder,
            Parent = scrollFrame,
        })

        for nameIndex, themeFile in ipairs(fileNames)do
            local pickerButton = pickLibrary:Create('TextButton', {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 22),
                Text = '  ' .. themeFile,
                TextColor3 = Color3.fromRGB(190, 190, 190),
                TextSize = 11,
                FontFace = pickLibrary.Font,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 302,
                AutoButtonColor = false,
                Parent = scrollFrame,
            })

            pickerButton.MouseEnter:Connect(function()
                pickerButton.BackgroundTransparency = 0
                pickerButton.BackgroundColor3 = pickLibrary.AccentColor
                pickerButton.TextColor3 = Color3.new(0, 0, 0)
            end)
            pickerButton.MouseLeave:Connect(function()
                pickerButton.BackgroundTransparency = 1
                pickerButton.TextColor3 = Color3.fromRGB(190, 190, 190)
            end)
            pickerButton.MouseButton1Click:Connect(function()
                pickerFrame:Destroy()

                if self.ImportDropdown then
                    self.ImportDropdown.Text = (themeFile:gsub('%.json$', ''))
                end

                self:ImportFromFile(themeFile)
            end)
        end

        task.delay(8, function()
            if pickerFrame and pickerFrame.Parent then
                pickerFrame:Destroy()
            end
        end)
    end
    function ad:BuildExportData(name)
        local library = self.Library
        local colors = {}

        for index, colorKey in ipairs(ae)do
            if Options and Options[colorKey] then
                local option = Options[colorKey]

                colors[colorKey] = {
                    hue = option.Hue,
                    sat = option.Sat,
                    vib = option.Vib,
                    transparency = option.Transparency,
                    rainbow = option.Rainbow,
                }
            else
                colors[colorKey] = library[colorKey]:ToHex()
            end
        end

        local images = {}
        local resolveImage = function(fileName)
            if not fileName then
                return nil
            end

            local path = self.ImageFolder .. '/' .. fileName

            if not isfile(path) then
                return nil
            end

            local content = readfile(path)
            local hash = computeHash(content)

            if not images[hash] then
                images[hash] = {
                    name = fileName,
                    data = encodeBase64(content),
                }
            end

            return hash
        end
        local global

        if self.GlobalConfig.enabled and self.GlobalConfig.fileName then
            local globalImageId = resolveImage(self.GlobalConfig.fileName)

            if globalImageId then
                global = {
                    image = globalImageId,
                    transparency = self.GlobalConfig.transparency,
                    boxTransparency = self.GlobalConfig.boxTransparency,
                    imageColor = self.GlobalConfig.imageColor,
                }
            end
        end

        local overrides = {}

        for frameName, overrideConfig in pairs(self.FrameOverrides)do
            if overrideConfig.fileName then
                local overrideImageId = resolveImage(overrideConfig.fileName)

                if overrideImageId then
                    overrides[frameName] = {
                        image = overrideImageId,
                        transparency = overrideConfig.transparency,
                        boxTransparency = overrideConfig.boxTransparency,
                        imageColor = overrideConfig.imageColor,
                    }
                end
            end
        end

        return {
            version = 3,
            name = name or 'Unnamed',
            colors = colors,
            global = global,
            overrides = overrides,
            images = images,
        }
    end
    function ad:Export(exportName)
        if not exportName or exportName:gsub('%s', '') == '' then
            return self:SetStatus('Enter a name')
        end

        local data = self:BuildExportData(exportName)
        local encodeOk, json = pcall(httpService.JSONEncode, httpService, data)

        if not encodeOk then
            return self:SetStatus('Encode error')
        end
        if not isfolder(self.ExportFolder) then
            makefolder(self.ExportFolder)
        end

        writefile(self.ExportFolder .. '/' .. exportName .. '.json', json)
        self:SetStatus('Exported: ' .. exportName .. '.json (' .. #json .. ' bytes)')
    end
    function ad:CopyToClipboard(clipboardName)
        local exportData = self:BuildExportData(clipboardName or 'Shared')
        local pcallOk, jsonText = pcall(httpService.JSONEncode, httpService, exportData)

        if not pcallOk then
            return self:SetStatus('Encode error')
        end
        if setclipboard then
            setclipboard(jsonText)
            self:SetStatus('Copied (' .. #jsonText .. ' bytes)')
        else
            self:SetStatus('No clipboard')
        end
    end
    function ad:Import(importJson)
        local decodeOk, decodedData = pcall(httpService.JSONDecode, httpService, importJson)

        if not decodeOk or not decodedData then
            return self:SetStatus('Invalid JSON')
        end
        if not decodedData.images then
            return self:SetStatus('Not a theme editor file')
        end
        if not isfolder(self.ImageFolder) then
            makefolder(self.ImageFolder)
        end

        local imageFiles = {}

        for imageKey, imageData in pairs(decodedData.images)do
            local bytes = decodeBase64(imageData.data)

            if not bytes or #bytes == 0 then
                continue
            end

            local imageFileName = imageData.name or (imageKey .. '.png')

            writefile(self.ImageFolder .. '/' .. imageFileName, bytes)

            aj[self.ImageFolder .. '/' .. imageFileName] = nil
            imageFiles[imageKey] = imageFileName
        end

        if decodedData.colors then
            self:ApplyColors(decodedData.colors)
        end

        self:RemoveAll(true)

        self.FrameOverrides = {}
        self.GlobalConfig = {
            enabled = false,
            fileName = nil,
            transparency = 0.6,
            boxTransparency = 0.25,
            imageColor = {1, 1, 1},
        }

        if decodedData.global and decodedData.global.image then
            local globalFileName = imageFiles[decodedData.global.image]

            if globalFileName then
                self.GlobalConfig = {
                    enabled = true,
                    fileName = globalFileName,
                    transparency = decodedData.global.transparency or 0.6,
                    boxTransparency = decodedData.global.boxTransparency or 0.25,
                    imageColor = decodedData.global.imageColor or {1, 1, 1},
                }
            end
        end
        if decodedData.overrides then
            for overrideKey, overrideData in pairs(decodedData.overrides)do
                local overrideFileName = imageFiles[overrideData.image]

                if overrideFileName then
                    self.FrameOverrides[overrideKey] = {
                        fileName = overrideFileName,
                        transparency = overrideData.transparency or 0.6,
                        boxTransparency = overrideData.boxTransparency or 0.25,
                        imageColor = overrideData.imageColor or {1, 1, 1},
                    }
                end
            end
        end

        self:ScanImages()
        self:RefreshGallery()
        self:ApplyAll()
        self:UpdateTransLabel()
        self:RefreshColorSwatches()
        self:SetStatus('Imported: ' .. (decodedData.name or 'theme') .. ' (colors + images)')
    end
    function ad:ImportFromFile(fileName)
        local filePath = self.ExportFolder .. '/' .. fileName

        if not isfile(filePath) then
            return self:SetStatus('Not found')
        end

        self:Import(readfile(filePath))
    end
    function ad:SaveConfig()
        local library = self.Library
        local colors = {}

        for index, optionKey in ipairs(ae)do
            if Options and Options[optionKey] then
                local colorOption = Options[optionKey]

                colors[optionKey] = {
                    hue = colorOption.Hue,
                    sat = colorOption.Sat,
                    vib = colorOption.Vib,
                    transparency = colorOption.Transparency,
                    rainbow = colorOption.Rainbow,
                }
            elseif library[optionKey] then
                colors[optionKey] = library[optionKey]:ToHex()
            end
        end

        local saveData = {
            colors = colors,
            global = self.GlobalConfig,
            overrides = self.FrameOverrides,
        }
        local success, encodedJson = pcall(httpService.JSONEncode, httpService, saveData)

        if success then
            if not isfolder(self.ExportFolder) then
                makefolder(self.ExportFolder)
            end

            writefile(self.ExportFolder .. '/editor_state.json', encodedJson)
        end
    end
    function ad:LoadConfig()
        local configPath = self.ExportFolder .. '/editor_state.json'

        if not isfile(configPath) then
            return
        end

        local decodeOk, decodedData = pcall(function()
            return httpService:JSONDecode(readfile(configPath))
        end)

        if not decodeOk or not decodedData then
            return
        end

        task.spawn(function()
            task.wait(2.5)

            if decodedData.colors then
                self:ApplyColors(decodedData.colors)
            end

            self:UpdateTransLabel()
            self:RefreshColorSwatches()
        end)
    end
    function ad:Toggle()
        self.Visible = not self.Visible

        if self.Panel then
            self.Panel.Visible = self.Visible
        end
        if not self.Visible then
            self:ExitPlacementMode()
        end
    end
    function ad:SetLibrary(newLibrary)
        self.Library = newLibrary
    end
    function ad:SetThemeManager(themeManager)
        self.ThemeManager = themeManager
    end
    function ad:WriteDefaultThemes()
        local manager = self.ThemeManager

        if not manager or not manager.BuiltInThemes then
            return
        end
        if not isfolder(self.ExportFolder) then
            makefolder(self.ExportFolder)
        end

        for themeName, theme in pairs(manager.BuiltInThemes)do
            local themePath = self.ExportFolder .. '/' .. themeName .. '.json'

            if isfile(themePath) then
                continue
            end

            local themeColors = theme[2]
            local outputColors = {}

            for colorIndex, colorKey in ipairs(ae)do
                local colorValue = themeColors[colorKey]

                if type(colorValue) == 'string' then
                    outputColors[colorKey] = colorValue
                elseif type(colorValue) == 'table' and colorValue.hue then
                    outputColors[colorKey] = {
                        hue = colorValue.hue,
                        sat = colorValue.sat,
                        vib = colorValue.vib,
                        transparency = colorValue.transparency or 0,
                        rainbow = colorValue.rainbow or false,
                    }
                end
            end

            local exportData = {
                version = 3,
                name = themeName,
                colors = outputColors,
                global = nil,
                overrides = {},
                images = {},
            }
            local writeSuccess, outputJson = pcall(httpService.JSONEncode, httpService, exportData)

            if writeSuccess then
                writefile(themePath, outputJson)
            end
        end
    end
    function ad:Init()
        assert(self.Library, 'Must set ThemeEditor.Library first!')

        if not isfolder('PalantirX') then
            makefolder('PalantirX')
        end
        if not isfolder(self.ImageFolder) then
            makefolder(self.ImageFolder)
        end
        if not isfolder(self.ExportFolder) then
            makefolder(self.ExportFolder)
        end

        self:WriteDefaultThemes()
        self:ScanImages()
        self:BuildUI()
        self:RefreshGallery()
        self:LoadConfig()
    end

    return ad
end


return aa()

