        function ab.SetBackgroundImage(ac, fileName, imageTransparency, boxTransparency, targets)
            imageTransparency = imageTransparency or 0.7
            boxTransparency = boxTransparency or 0.3
            targets = targets or ac.BackgroundTargets

            local screenGui = ac.Library and ac.Library.ScreenGui

            if not screenGui then
                return
            end
            if ac.BackgroundImages then
                for index, imageLabel in pairs(ac.BackgroundImages)do
                    if imageLabel and imageLabel.Parent then
                        imageLabel:Destroy()
                    end
