            local backgroundColor = ac.Library.BackgroundColor
            local mainColor = ac.Library.MainColor
            local imageAsset

            if fileName == '__palantirx_default__' then
                imageAsset = ac.DefaultBackgroundAssetId
            else
                local filePath = ac.BackgroundImageFolder .. '/' .. fileName

                if not isfile(filePath) then
                    if ac.Library then
                        ac.Library:Notify'file not found'
                    end

                    return
                end
                if getcustomasset then
                    local customAssetOk, customAsset = pcall(getcustomasset, filePath)

                    if customAssetOk and customAsset then
                        imageAsset = customAsset
                    end
                end
                if not imageAsset and getsynasset then
                    local synAssetOk, synAsset = pcall(getsynasset, filePath)

                    if synAssetOk and synAsset then
                        imageAsset = synAsset
                    end
