            end

            ac.CurrentFileName = fileName
            ac.CurrentImageUrl = imageAsset
            ac.CurrentImageTransparency = imageTransparency
            ac.CurrentBoxTransparency = boxTransparency
            ac.BackgroundTargets = targets

            local classifyTarget = function(frame)
                local frameColor = frame.BackgroundColor3
                local colorsMatch = function(colorA, colorB)
                    return math.abs(colorA.R - colorB.R) < 0.02 and math.abs(colorA.G - colorB.G) < 0.02 and math.abs(colorA.B - colorB.B) < 0.02
                end

