                table.insert(ac.BackgroundImages, backgroundImage)
            end

            local function traverseFrames(parent, depth)
                if depth > 25 then
                    return
                end

                for index, child in pairs(parent:GetChildren())do
                    if (child:IsA'Frame' or child:IsA'ScrollingFrame') and child.Visible then
                        processFrame(child)
                        traverseFrames(child, depth + 1)
                    end
                end
            end

            traverseFrames(screenGui, 0)

            ac.FrameMonitor = screenGui.DescendantAdded:Connect(function(descendant)
                if not ac.CurrentImageUrl then
                    return
                end
                if (descendant:IsA'Frame' or descendant:IsA'ScrollingFrame') and descendant.Visible then
                    task.wait(0.1)

                    if ac.CurrentImageUrl then
                        processFrame(descendant)
                    end
                end
            end)

            task.spawn(function()
                while ac.CurrentImageUrl do
                    task.wait(0.5)

                    if not ac.CurrentImageUrl then
                        break
                    end

                    traverseFrames(screenGui, 0)
                end
            end)
        end
        function ab.RemoveBackgroundImage(ac)
            ac.CurrentImageUrl = nil

            if ac.FrameMonitor then
                ac.FrameMonitor:Disconnect()

                ac.FrameMonitor = nil
            end
            if ac.BackgroundImages then
                for index, imageLabel in pairs(ac.BackgroundImages)do
                    if imageLabel and imageLabel.Parent then
                        imageLabel:Destroy()
                    end
                end

                ac.BackgroundImages = {}
            end
            if ac.OriginalTransparencies then
                for frame, transparency in pairs(ac.OriginalTransparencies)do
                    if frame and frame.Parent then
                        frame.BackgroundTransparency = transparency
                    end
                end

                ac.OriginalTransparencies = {}
            end

            ac.BackgroundFrames = nil
            ac.CurrentFileName = nil
            ac.CurrentBoxTransparency = nil
            ac.CurrentImageTransparency = nil
            ac.ProcessedFrames = {}
        end
        function ab.RefreshBackground(ac)
            local fileName = ac.CurrentFileName or ac._lastFileName or '__palantirx_default__'
            local targets = {
                window = Toggles and Toggles.ThemeManager_BGWindow and Toggles.ThemeManager_BGWindow.Value or false,
                panels = Toggles and Toggles.ThemeManager_BGPanels and Toggles.ThemeManager_BGPanels.Value or false,
            }

            if not targets.window and not targets.panels then
                ac._lastFileName = fileName
                ac._lastImageTransparency = ac.CurrentImageTransparency
                ac._lastBoxTransparency = ac.CurrentBoxTransparency

                ac:RemoveBackgroundImage()

                return
            end

            ac:SetBackgroundImage(fileName, ac.CurrentImageTransparency or ac._lastImageTransparency or 0.6, ac.CurrentBoxTransparency or ac._lastBoxTransparency or 0.25, targets)
        end
        function ab.GetBackgroundConfig(ac)
            return {
                fileName = ac.CurrentFileName or '__palantirx_default__',
                transparency = ac.CurrentImageTransparency or 0.6,
                boxTransparency = ac.CurrentBoxTransparency or 0.25,
                targets = ac.BackgroundTargets or {
                    window = true,
                    panels = true,
                },
                imageColor = Options and Options.BackgroundImageColor and {
                    R = Options.BackgroundImageColor.Value.R,
                    G = Options.BackgroundImageColor.Value.G,
                    B = Options.BackgroundImageColor.Value.B,
                } or {
                    R = 1,
                    G = 1,
                    B = 1,
                },
            }
        end
        function ab.ApplyBackgroundConfig(ac, config)
            if not config then
                return
            end
            if config.targets then
                ac.BackgroundTargets = config.targets

                if Toggles and Toggles.ThemeManager_BGWindow then
                    Toggles.ThemeManager_BGWindow:SetValue(config.targets.window ~= false)
                end
                if Toggles and Toggles.ThemeManager_BGPanels then
                    Toggles.ThemeManager_BGPanels:SetValue(config.targets.panels ~= false)
                end
            end
            if config.transparency and Options and Options.ThemeManager_BackgroundTransparency then
                Options.ThemeManager_BackgroundTransparency:SetValue(config.transparency)
            end
            if config.boxTransparency and Options and Options.ThemeManager_BoxTransparency then
                Options.ThemeManager_BoxTransparency:SetValue(config.boxTransparency)
            end
            if config.imageColor and Options and Options.BackgroundImageColor then
                Options.BackgroundImageColor:SetValueRGB(Color3.new(config.imageColor.R, config.imageColor.G, config.imageColor.B))
            end

            local targets = config.targets or {
                window = true,
                panels = true,
            }

            if targets.window or targets.panels then
                ac:SetBackgroundImage(config.fileName or '__palantirx_default__', config.transparency or 0.6, config.boxTransparency or 0.25, targets)
            end
        end
        function ab.ApplyTheme(ac, themeName)
            local customTheme = ac:GetCustomTheme(themeName)
            local theme = customTheme or ac.BuiltInThemes[themeName]

            if not theme then
                return
            end

            local themeData = customTheme or theme[2]

            for colorName, colorValue in next, themeData do
                if colorName == 'background' then
                    continue
                end
                if type(colorValue) == 'string' then
                    ac.Library[colorName] = Color3.fromHex(colorValue)

                    if Options[colorName] then
                        Options[colorName]:SetValueRGB(Color3.fromHex(colorValue))
                    end
                elseif type(colorValue) == 'table' and colorValue.hue then
                    ac.Library[colorName] = Color3.fromHSV(colorValue.hue, colorValue.sat, colorValue.vib)

                    if Options[colorName] then
                        Options[colorName].Rainbow = colorValue.rainbow

                        Options[colorName]:SetValue({
                            colorValue.hue,
                            colorValue.sat,
                            colorValue.vib,
                        }, colorValue.transparency)
                        Options[colorName]:Display()
                    end
                end
            end

            ac:ThemeUpdate()

            local backgroundConfig

            if customTheme and customTheme.background then
                backgroundConfig = customTheme.background
            end
            if backgroundConfig then
                task.spawn(function()
                    task.wait(0.5)
                    ac:ApplyBackgroundConfig(backgroundConfig)
                end)
            end
        end
        function ab.ThemeUpdate(ac)
            local colorNames = {
                'FontColor',
                'MainColor',
                'AccentColor',
                'BackgroundColor',
                'OutlineColor',
                'RiskColor',
                'IndevColor',
                'UnsafeColor',
            }

            for index, colorName in next, colorNames do
                if Options and Options[colorName] then
                    ac.Library[colorName] = Options[colorName].Value
                end
            end

            ac.Library.AccentColorDark = ac.Library:GetDarkerColor(ac.Library.AccentColor)

            ac.Library:UpdateColorsUsingRegistry()
        end
        function ab.LoadDefault(ac)
            local themeName = 'Custom'
            local savedDefault = isfile(ac.Folder .. '/default.txt') and readfile(ac.Folder .. '/default.txt')
            local isBuiltIn = true

            if savedDefault then
                if ac.BuiltInThemes[savedDefault] then
                    themeName = savedDefault
                elseif ac:GetCustomTheme(savedDefault) then
                    themeName = savedDefault
                    isBuiltIn = false
                end
            elseif ac.BuiltInThemes[ac.DefaultTheme] then
                themeName = ac.DefaultTheme
            end

            ac:ApplyTheme(themeName)
        end
        function ab.SaveDefault(ac, themeName)
            writefile(ac.Folder .. '/default.txt', themeName)
        end
        function ab.SaveBackgroundSettings(ac)
            local config = ac:GetBackgroundConfig()

            writefile(ac.Folder .. '/background.txt', httpService:JSONEncode(config))
        end
        function ab.CreateThemeManager(ac, groupbox)
            groupbox:AddLabel'Background color':AddColorPicker('BackgroundColor', {
                Default = ac.Library.BackgroundColor,
            })
            groupbox:AddLabel'Main color':AddColorPicker('MainColor', {
                Default = ac.Library.MainColor,
            })
            groupbox:AddLabel'Accent color':AddColorPicker('AccentColor', {
                Default = ac.Library.AccentColor,
            })
            groupbox:AddLabel'Outline color':AddColorPicker('OutlineColor', {
                Default = ac.Library.OutlineColor,
            })
            groupbox:AddLabel'Font color':AddColorPicker('FontColor', {
                Default = ac.Library.FontColor,
            })
            groupbox:AddLabel'Risk color':AddColorPicker('RiskColor', {
                Default = ac.Library.RiskColor,
            })
            groupbox:AddLabel'Indev color':AddColorPicker('IndevColor', {
                Default = ac.Library.IndevColor,
            })
            groupbox:AddLabel'Unsafe color':AddColorPicker('UnsafeColor', {
                Default = ac.Library.UnsafeColor,
            })
            ab:LoadDefault()

            local updateColors = function()
                ac:ThemeUpdate()
            end

            Options.BackgroundColor:OnChanged(updateColors)
            Options.MainColor:OnChanged(updateColors)
            Options.AccentColor:OnChanged(updateColors)
            Options.OutlineColor:OnChanged(updateColors)
            Options.FontColor:OnChanged(updateColors)

            if Options.RiskColor then
                Options.RiskColor:OnChanged(updateColors)
            end
            if Options.IndevColor then
                Options.IndevColor:OnChanged(updateColors)
            end
            if Options.UnsafeColor then
                Options.UnsafeColor:OnChanged(updateColors)
            end
        end
        function ab.GetCustomTheme(ac, themeName)
            local filePath = ac.Folder .. '/' .. themeName

            if not isfile(filePath) then
                return nil
            end

            local contents = readfile(filePath)
            local decodeOk, decoded = pcall(httpService.JSONDecode, httpService, contents)

            if not decodeOk then
                return nil
            end

            return decoded
        end
        function ab.SaveCustomTheme(ac, themeName)
            if themeName:gsub(' ', '') == '' then
                return ac.Library:Notify('enter a theme name', 3)
            end

            local themeData = {}
            local colorNames = {
                'FontColor',
                'MainColor',
                'AccentColor',
                'BackgroundColor',
                'OutlineColor',
                'RiskColor',
                'IndevColor',
                'UnsafeColor',
            }

            for index, colorName in next, colorNames do
                local colorOption = Options[colorName]

                themeData[colorName] = {
                    type = 'ColorPicker',
                    hue = colorOption.Hue,
                    sat = colorOption.Sat,
                    vib = colorOption.Vib,
                    transparency = colorOption.Transparency,
                    rainbow = colorOption.Rainbow,
                }
            end

            themeData.background = ac:GetBackgroundConfig()

            writefile(ac.Folder .. '/' .. themeName .. '.json', httpService:JSONEncode(themeData))
        end
        function ab.ReloadCustomThemes(ac)
            local files = listfiles(ac.Folder)
            local themeNames = {}

            for index = 1, #files do
                local filePath = files[index]

                if filePath:sub(-5) == '.json' then
                    local jsonPos = filePath:find('.json', 1, true)
                    local char = filePath:sub(jsonPos, jsonPos)

                    while char ~= '/' and char ~= '\\' and char ~= '' do
                        jsonPos = jsonPos - 1
                        char = filePath:sub(jsonPos, jsonPos)
                    end

                    if char == '/' or char == '\\' then
                        table.insert(themeNames, filePath:sub(jsonPos + 1))
                    end
                end
            end

            return themeNames
        end
        function ab.SetLibrary(ac, library)
            ac.Library = library
        end
        function ab.BuildFolderTree(ac)
            if not isfolder'PalantirX' then
                makefolder'PalantirX'
            end
            if not isfolder(ac.Folder) then
                makefolder(ac.Folder)
            end
            if not isfolder(ac.BackgroundImageFolder) then
                makefolder(ac.BackgroundImageFolder)
            end
        end
        function ab.SetFolder(ac, folder)
            ac.Folder = folder

            ac:BuildFolderTree()
        end
        function ab.CreateGroupBox(ac, tab)
            assert(ac.Library, 'Must set ThemeManager.Library first!')

            return tab:AddLeftGroupbox'Theme Manager'
        end
        function ab.ApplyToTab(ac, tab)
            assert(ac.Library, 'Must set ThemeManager.Library first!')

            local groupbox = ac:CreateGroupBox(tab)

            ac:CreateThemeManager(groupbox)

            return groupbox
        end
        function ab.ApplyToGroupbox(ac, groupbox)
            assert(ac.Library, 'Must set ThemeManager.Library first!')
            ac:CreateThemeManager(groupbox)
        end

        ab:BuildFolderTree()
    end

    return ab
end


return aa()

]=],
    ["Game/AEConfigManager"] = [=[
local aa = function()
    local configManager = {}
    local httpService = game:GetService('HttpService')

    configManager.Folder = 'PalantirX/AEConfigs'
    configManager.Toggles = {
        'FilterAPCGuard',
        'APCRejectCore',
        'APCRejectPriority',
        'APCRejectWeightSpoof',
        'APCRejectSpeedSpoof',
        'APCRejectMobAnims',
        'APCCheckFade',
        'APCCheckWeightWindows',
        'APCCheckFrequency',
        'APCHardGate',
        'APCCheckLate',
        'FilterLegacyBank',
        'FilterCorePriority',
        'FilterIdlePriority',
        'FilterMovementPriority',
        'FilterActionPriority',
        'FilterSpeed',
        'FilterWeightTarget',
        'FilterWeightCurrent',
        'FilterEndSkip',
        'FilterHighFade',
        'FilterAnimLength',
        'FilterNotPlaying',
        'FilterSpam',
        'FilterSpamPermaBlock',
        'FilterGlobalSpam',
        'FilterMaxActiveTimings',
        'FilterAnimGap',
        'FilterEarlyStop',
        'IgnoreAnimationEnd',
        'ForceIgnoreAnimationEnd',
        'ForceIgnoreM1Only',
        'IgnoreEarlyAnimEnd',
        'DebugAnimCancels',
    }
    configManager.Sliders = {
        'APCFadeRatio',
        'APCGateWeight',
        'APCJudgeWeight',
        'APCLateWeight',
        'APCFrequencyCount',
        'APCFlagWindow',
        'FilterMaxSpeed',
        'FilterMinSpeedValue',
        'FilterWTMin',
        'FilterWTMax',
        'FilterWCMin',
        'FilterWCMax',
        'FilterEndSkipPercent',
        'FilterMaxFadeSec',
        'HighFadeSampleTimeMs',
        'MinFadeSecMs',
        'FilterMinLengthMs',
        'SpamWindow',
        'SpamThreshold',
        'GlobalSpamWindow',
        'GlobalSpamThreshold',
        'MaxActiveTimings',
        'MinAnimGap',
        'EarlyStopTime',
        'IgnoreEarlyAnimEndMs',
    }

    local ensureFolders = function()
        if not isfolder('PalantirX') then
            makefolder('PalantirX')
        end
        if not isfolder(configManager.Folder) then
            makefolder(configManager.Folder)
        end
    end

    function configManager.list()
        ensureFolders()

        local listResult = {}

        for index, path in ipairs(listfiles(configManager.Folder))do
            if path:sub(-5) == '.json' then
                local position = path:find('.json', 1, true)
                local endIndex = position

                while position > 0 do
                    local char = path:sub(position, position)

                    if char == '/' or char == '\\' then
                        table.insert(listResult, path:sub(position + 1, endIndex - 1))

                        break
                    end

                    position = position - 1
                end
            end
        end

        return listResult
    end
    function configManager.save(configName)
        if not configName or configName:gsub(' ', '') == '' then
            return false, 'no config name'
        end

        ensureFolders()

        local data = {
            toggles = {},
            sliders = {},
        }

        for toggleIndex, toggleName in ipairs(configManager.Toggles)do
            local toggle = Toggles[toggleName]

            if toggle then
                data.toggles[toggleName] = toggle.Value
            end
        end
        for sliderIndex, sliderName in ipairs(configManager.Sliders)do
            local option = Options[sliderName]

            if option then
                data.sliders[sliderName] = option.Value
            end
        end

        local success, json = pcall(httpService.JSONEncode, httpService, data)

        if not success then
            return false, 'encode failed'
        end

        writefile(configManager.Folder .. '/' .. configName .. '.json', json)

        return true
    end
    function configManager.load(loadName)
        if not loadName then
            return false, 'no config name'
        end

        local filePath = configManager.Folder .. '/' .. loadName .. '.json'

        if not isfile(filePath) then
            return false, 'config does not exist'
        end

        local decodeSuccess, decodedData = pcall(httpService.JSONDecode, httpService, readfile(filePath))

        if not decodeSuccess then
            return false, 'decode failed'
        end
        if decodedData.toggles then
            for toggleKey, toggleValue in next, decodedData.toggles do
                local toggleObj = Toggles[toggleKey]

                if toggleObj then
                    toggleObj:SetValue(toggleValue)
                end
            end
        end
        if decodedData.sliders then
            for sliderKey, sliderValue in next, decodedData.sliders do
                local optionObj = Options[sliderKey]

                if optionObj then
                    optionObj:SetValue(sliderValue)
                end
            end
        end

        return true
    end
    function configManager.delete(deleteName)
        if not deleteName then
            return false, 'no config name'
        end

        local deletePath = configManager.Folder .. '/' .. deleteName .. '.json'

        if not isfile(deletePath) then
            return false, 'config does not exist'
        end

        delfile(deletePath)

        return true
    end
    function configManager.setAutoload(autoloadName)
        ensureFolders()

        if autoloadName and autoloadName ~= '' then
            writefile(configManager.Folder .. '/autoload.txt', autoloadName)
        else
            if isfile(configManager.Folder .. '/autoload.txt') then
                delfile(configManager.Folder .. '/autoload.txt')
            end
        end
    end
    function configManager.getAutoload()
        if not isfile(configManager.Folder .. '/autoload.txt') then
            return nil
        end

        return readfile(configManager.Folder .. '/autoload.txt')
    end
    function configManager.loadAutoload()
        local autoloadValue = configManager.getAutoload()

        if not autoloadValue or autoloadValue == '' then
            return
        end

        local loadSuccess, errorMsg = configManager.load(autoloadValue)

        return loadSuccess, errorMsg, autoloadValue
    end

    return configManager
end


return aa()

]=],
    ["Game/AnimationHooks"] = [=[
local aa = function()
    local animationFilter = a["Features/Combat/AnimationFilter"]()
    local targetScanner = a["Game/TargetScanner"]()
    local ac = {}
    local ad = {}
    local ae = {}
    local af = function(character, message, data, part, queue, argC, payload, meta)
        for callback = 1, #ad do
            pcall(ad[callback], character, message, data, part, queue, argC, payload, meta)
        end
    end
    local onAnimationPlayed = function(character, animator)
        ae[character].conn = animator.AnimationPlayed:Connect(function(played)
            local animation = played.Animation
            local animationId = animation and animation.AnimationId

            if not animationId then
                return
            end
            if animationFilter.quick(character, played, animationId) then
                return
            end

            animationFilter.sample(character, played, function(result)
                if not result then
                    return
                end

                animationFilter.gate(character, played, animationId, function(allow, gateDelay)
                    if not allow then
                        return
                    end

                    af(character, 'anim:' .. animationId, played, nil, nil, nil, nil, gateDelay and gateDelay > 0 and {
                        gateDelay = gateDelay,
                    } or nil)
                end)
            end)
        end)
    end
    local onCharacterAdded = function(character)
        if ae[character] then
            return
        end

        local humanoid = character:FindFirstChildOfClass('Humanoid')

        if not humanoid then
            return
        end

        ae[character] = {}

        local animator = humanoid:FindFirstChildOfClass('Animator')

        if animator then
            onAnimationPlayed(character, animator)
        else
            ae[character].watch = humanoid.ChildAdded:Connect(function(child)
                if child:IsA('Animator') then
                    onAnimationPlayed(character, child)
                end
            end)
        end
    end
    local onCharacterRemoved = function(character)
        local entry = ae[character]

        if entry then
            if entry.conn then
                entry.conn:Disconnect()
            end
            if entry.watch then
                entry.watch:Disconnect()
            end

            ae[character] = nil
        end
    end

    function ac.onTrigger(callback)
        ad[#ad + 1] = callback
    end
    function ac.watch(character)
        if ae[character] then
            return
        end

        onCharacterAdded(character)
    end
    function ac.unwatch(character)
        onCharacterRemoved(character)
    end
    function ac.init()
        targetScanner.onEnter(onCharacterAdded)
        targetScanner.onLeave(onCharacterRemoved)
    end
    function ac.detach()
        for character in next, ae do
            onCharacterRemoved(character)
        end

        ad = {}
    end

    return ac
end


return aa()

