            local virtualUser = game:GetService('VirtualUser')

            virtualUser:CaptureController()
            virtualUser:ClickButton2(Vector2.new())
        end)
    end
    function registry.detach()
        cleanupMaid:clean()
    end

    return registry
end


return aa()

]=],
    ["Game/AttemptTracker"] = [=[
local aa = function()
    local module = {}

    module.__index = module

    function module.new(network)
        return setmetatable({
            attempts = {},
            at = network,
            activeAt = network,
        }, module)
    end
    function module:retry(key)
        self.attempts[key] = (self.attempts[key] or 0) + 1

        return self.attempts[key] <= 2
    end
    function module:clear(key)
        self.attempts[key] = nil
    end
    function module:stalled(signature, now, at)
        if self.signature ~= signature then
            self.signature, self.at, self.activeAt = signature, at, at
        end

        self.activeAt = math.max(self.activeAt, math.min(now or 0, at))

        return at - self.activeAt >= 240 or at - self.at >= 900
    end

    return module
end


return aa()

]=],
    ["Game/CharacterActions"] = [=[
local aa = function()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')
    local module = {}

    module.rollCancel = false
    module.rollCancelDelay = 0.05

    local getCharacter = function()
        local localPlayer = players.LocalPlayer

        return localPlayer and localPlayer.Character
    end
    local getRequests = function()
        local character = getCharacter()
        local characterHandler = character and character:FindFirstChild('CharacterHandler')

        return characterHandler and characterHandler:FindFirstChild('Requests')
    end
    local getEffectReplicator = function()
        local replicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not replicator then
            return nil
        end

        local success, replicatorModule = pcall(require, replicator)

        if success then
            return replicatorModule
        end

        return nil
    end
    local buildCooldowns = function()
        local cooldowns = {}
        local effectModule = getEffectReplicator()

        if not (effectModule and type(effectModule.GetEffects) == 'function') then
            return cooldowns
        end

        local succeeded, effects = pcall(effectModule.GetEffects, effectModule)

        if not succeeded or type(effects) ~= 'table' then
            return cooldowns
        end

        for index, effect in pairs(effects)do
            if type(effect) == 'table' then
                local value = effect.Value or (effect.index and effect.index.Value)

                if value and (effect.Class or (effect.index and effect.index.Class)) == 'ToolLockCD' then
                    cooldowns[tostring(value)] = true
                end
            end
        end

        return cooldowns
    end

    function module.pickMantra(allowed)
        local backpack = players.LocalPlayer and players.LocalPlayer:FindFirstChild('Backpack')

        if not backpack then
            return nil
        end

        local lockedTools = buildCooldowns()

        for childIndex, child in pairs(backpack:GetChildren())do
            if child:IsA('Tool') and not lockedTools[child.Name] then
                local defaultName = child:GetAttribute('DefaultName')

                if defaultName and (allowed == nil or allowed[defaultName] == true) then
                    return child
                end
            end
        end

        return nil
    end
    function module.mantra(allowedMantras)
        local tool = module.pickMantra(allowedMantras)

        if not tool then
            return false
        end

        local requests = getRequests()

        requests = requests and requests:FindFirstChild('ActivateMantra')

        if not requests then
            return false
        end

        requests:FireServer(tool)

        return true
    end
    function module.vent()
        local requestsFolder = getRequests()
        local ventRemote = requestsFolder and requestsFolder:FindFirstChild('Vent')

        if not ventRemote then
            return false
        end

        ventRemote:FireServer()

        return true
    end

    local getKeyBinds = function()
        local keyBinds = replicatedStorage:FindFirstChild('KeyBinds')

        if not keyBinds then
            return nil
        end

        local requireOk, keyBindsModule = pcall(require, keyBinds)

        if not requireOk or not keyBindsModule or type(keyBindsModule.ForceActionDown) ~= 'function' or type(keyBindsModule.ForceActionUp) ~= 'function' then
            return nil
        end

        return keyBindsModule
    end
    local forceAction = function(action)
        local bindsModule = getKeyBinds()

        if not bindsModule then
            return false
        end

        bindsModule.ForceActionDown(action)
        bindsModule.ForceActionUp(action)

        return true
    end
    local pressActionBriefly = function(heldAction)
        local keyBindsApi = getKeyBinds()

        if not keyBindsApi then
            return false
        end

        keyBindsApi.ForceActionDown(heldAction)

        local connection

        connection = runService.Heartbeat:Connect(function()
            connection:Disconnect()
            keyBindsApi.ForceActionUp(heldAction)
        end)

        return true
    end

    function module.jump()
        return pressActionBriefly('Jump')
    end
    function module.feint()
        return forceAction('Feint')
    end
    function module.crouch(target)
        local effects = getEffectReplicator()
        local crouchEffectActive = effects and type(effects.HasEffect) == 'function' and effects:HasEffect('ClientCrouch') or false

        if crouchEffectActive == (target and true or false) then
            return true
        end

        return forceAction('Crouch')
    end
    function module.dodge(cancelRoll)
        local keyBinds = replicatedStorage:FindFirstChild('KeyBinds')

        if not keyBinds then
            return false
        end

        local success, keyBindsModule = pcall(require, keyBinds)

        if not success or not keyBindsModule or type(keyBindsModule.ForceActionDown) ~= 'function' or type(keyBindsModule.ForceActionUp) ~= 'function' then
            return false
        end

        keyBindsModule.ForceActionDown('Dodge')
        keyBindsModule.ForceActionUp('Dodge')

        if module.rollCancel and not cancelRoll then
            task.delay(module.rollCancelDelay, function()
                local effects = getEffectReplicator()
                local feintEffect = effects and type(effects.CreateEffect) == 'function' and effects:CreateEffect('ClientFeint')

                if feintEffect and type(feintEffect.Debris) == 'function' then
                    feintEffect:Debris(0.1)
                end
            end)
        end

        return true
    end

    return module
end


return aa()

