]=],
    ["Game/Data/RingData"] = [=[
local aa = function()
    local aa = a["Features/Game/NoEffects"]()
    local ab = a["Utility/DelayedTask"]()
    local ac = {}
    local ad = {
        {
            stat = 'Strength',
            name = "Dawnfist's Ring",
        },
        {
            stat = 'Agility',
            name = "Maestro's Ring",
        },
        {
            stat = 'Intelligence',
            name = "Rosen's Ring",
        },
        {
            stat = 'Willpower',
            name = "Akira's Ring",
        },
        {
            stat = 'Charisma',
            name = "Prophet's Ring",
        },
    }
    local ae = function(ae)
        if type(ae) == 'table' then
            return tostring(ae.ItemName or ae.Name or ae.name or '')
        end

        return tostring(ae or '')
    end

    function ac.targets(af)
        local ag = {}

        for ah, ai in ipairs(ad)do
            local aj = tonumber(af and af[ai.stat]) or 0

            if aj > 0 then
                ag[#ag + 1] = {
                    name = ai.name,
                    amount = aj,
                }
            end
        end

        table.sort(ag, function(ah, ai)
            if ah.amount == ai.amount then
                return ah.name < ai.name
            end

            return ah.amount > ai.amount
        end)

        local ah = {}

        for ai = 1, math.min(4, #ag)do
            ah[ai] = ag[ai].name
        end

        return ah
    end
    function ac.equipped(af, ag)
        local ah = af and af.Equipment

        for ai = 1, 4 do
            local aj = type(ah) == 'table' and ah['Ring' .. ai]

            if ae(aj):find(ag, 1, true) then
                return true
            end
        end

        return false
    end
    function ac.tool(af)
        local ag = aa.localPlayer.instance

        for ah, ai in ipairs({
            ag and ag:FindFirstChild('Backpack'),
            ag and ag.Character,
        })do
            for aj, ak in ipairs(ai and ai:GetChildren() or {})do
                if ak:IsA('Tool') and (ak:GetAttribute('ItemName') == af or ak.Name == af or ak.Name:sub(1, #af + 1) == af .. '$') then
                    return ak
                end
            end
        end
    end
    function ac.missing(af, ag)
        local ah = {}

        for ai, aj in ipairs(af)do
            if not ac.equipped(ag, aj) and not ac.tool(aj) then
                ah[#ah + 1] = aj
            end
        end

        return ah
    end
    function ac.complete(af, ag)
        for ah, ai in ipairs(af)do
            if not ac.equipped(ag, ai) then
                return false
            end
        end

        return true
    end
    function ac.equipOne(af, ag)
        local ah = aa.localPlayer.humanoid

        if not ah or ah.Health <= 0 then
            return false
        end

        for ai, aj in ipairs(af)do
            if not ac.equipped(ag, aj) then
                local ak = ac.tool(aj)

                if ak then
                    local al = ag and ag.Equipment
                    local am = false

                    for an = 1, 4 do
                        local ao = 'Ring' .. an
                        local ap = type(al) == 'table' and al[ao]

                        if not ap or ap == '' then
                            am = true

                            break
                        end
                    end

                    if not am then
                        local an = aa.services.ReplicatedStorage:FindFirstChild('Requests')
                        local ao = an and an:FindFirstChild('Unequip')

                        if not ao then
                            return false
                        end

                        for ap = 1, 4 do
                            local aq = 'Ring' .. ap
                            local ar = ae(al[aq])
                            local as = false

                            for at, au in ipairs(af)do
                                if ar:find(au, 1, true) then
                                    as = true

                                    break
                                end
                            end

                            if not as then
                                local at, au = pcall(ab.method, ao, 'InvokeServer', aq, true)

                                if not at or not au then
                                    return false
                                end

                                break
                            end
                        end
                    end

                    ah:UnequipTools()
                    ah:EquipTool(ak)
                    task.wait(0.15)

                    if ak.Parent ~= aa.localPlayer.character then
                        return false
                    end

                    ab.call(function()
                        ak:Activate()
                    end)

                    return true
                end
            end
        end

        return false
    end

    return ac
end


return aa()

