    ["Game/EffectBatcher"] = [=[
local aa = function()
    local logger = a["Utility/Logger"]()
    local runService = game:GetService('RunService')
    local effectBatcher = {}

    effectBatcher.on = true
    effectBatcher.max = 60

    local batchSettings = {}
    local effectTypeMap = {}
    local batchQueue = {}
    local activeBatches = {}
    local isEnabled = false
    local currentEffect

    function effectBatcher.flush()
        isEnabled = false

        if currentEffect then
            currentEffect:Disconnect()

            currentEffect = nil
        end

        for index = 1, #activeBatches do
            pcall(activeBatches[index], batchSettings)
        end
    end

    local updateBatches = function()
        if isEnabled then
            return
        end

        isEnabled = true
        currentEffect = runService.Heartbeat:Connect(effectBatcher.flush)
    end

    function effectBatcher.add(trigger, origin)
        if not (effectBatcher.on and type(trigger) == 'string') then
            return
        end
        if batchQueue[trigger] then
            return
        end

        local entry = effectTypeMap[trigger]

        if entry then
            entry.count = entry.count + 1
            entry.at = os.clock()
            entry.from = (origin and origin.Name) or entry.from

            updateBatches()

            return
        end

        local kind, key = trigger:match('^(%a+):(.*)$')

        entry = {
            trigger = trigger,
            kind = kind or '?',
            key = key or trigger,
            from = origin and origin.Name or 'world',
            at = os.clock(),
            count = 1,
        }
        effectTypeMap[trigger] = entry
        batchSettings[#batchSettings + 1] = entry

        while#batchSettings > effectBatcher.max do
            local oldEntry = table.remove(batchSettings, 1)

            effectTypeMap[oldEntry.trigger] = nil
        end

        updateBatches()
    end
    function effectBatcher.entries()
        return batchSettings
    end
    function effectBatcher.onChange(callback)
        activeBatches[#activeBatches + 1] = callback
    end
    function effectBatcher.ignore(ignoredTrigger)
        if not ignoredTrigger or ignoredTrigger == '' then
            return
        end

        batchQueue[ignoredTrigger] = true
        effectTypeMap[ignoredTrigger] = nil

        for settingsIndex = #batchSettings, 1, -1 do
            if batchSettings[settingsIndex].trigger == ignoredTrigger then
                table.remove(batchSettings, settingsIndex)
            end
        end

        updateBatches()
    end
    function effectBatcher.unignore(unignoreKey)
        batchQueue[unignoreKey] = nil

        updateBatches()
    end
    function effectBatcher.ignored()
        local keys = {}

        for ignoredKey in next, batchQueue do
            keys[#keys + 1] = ignoredKey
        end

        table.sort(keys)

        return keys
    end
    function effectBatcher.clear()
        batchSettings = {}
        effectTypeMap = {}

        updateBatches()
    end
    function effectBatcher.text(entryInfo)
        return string.format('%-6s %s  x%d  (%s)', entryInfo.kind, entryInfo.key, entryInfo.count, entryInfo.from)
    end
    function effectBatcher.copy(clipEntry)
        if type(setclipboard) == 'function' then
            pcall(setclipboard, clipEntry.trigger)
        else
            logger.warn('[MissLog] no clipboard on this executor: %s', clipEntry.trigger)
        end
    end
    function effectBatcher.detach()
        if currentEffect then
            currentEffect:Disconnect()

            currentEffect = nil
        end

        isEnabled = false
        batchSettings = {}
        effectTypeMap = {}
        batchQueue = {}
        activeBatches = {}
    end

    return effectBatcher
end


return aa()

