    ["Game/EffectReplicator"] = [=[
local aa = function()
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local module = {}
    local ac = {}
    local ad = {}
    local dispatchEffect = function(target, effectName, part, position, data)
        for index = 1, #ac do
            pcall(ac[index], target, effectName, nil, nil, part, position, data)
        end
    end
    local resolveCharacter = function(info)
        if type(info) ~= 'table' then
            return nil
        end

        local character = info.char or info.Character

        if typeof(character) == 'Instance' then
            return character
        end

        local partRef = info.part

        if typeof(partRef) == 'Instance' then
            local model = partRef:FindFirstAncestorWhichIsA('Model')

            if model then
                return model
            end
        end

        local liveFolder = workspace:FindFirstChild('Live')

        if not liveFolder then
            return nil
        end

        for field, child in next, info do
            if typeof(child) == 'Instance' and child.Parent == liveFolder then
                return child
            end
        end

        return nil
    end
    local resolvePosition = function(descriptor)
        if type(descriptor) ~= 'table' then
            return nil, nil
        end

        local pos = descriptor.pos or descriptor.Pos or descriptor.rPos

        if typeof(pos) == 'CFrame' then
            return nil, pos.Position
        end
        if typeof(pos) == 'Vector3' then
            return nil, pos
        end
        if typeof(descriptor.cf) == 'CFrame' then
            return nil, descriptor.cf.Position
        end
        if typeof(descriptor.part) == 'Instance' then
            return descriptor.part, nil
        end
        if typeof(descriptor.att) == 'Instance' then
            return descriptor.att, nil
        end

        return nil, nil
    end
    local fireEffect = function(effect, payload)
        if type(effect) ~= 'string' then
            return
        end

        local partInstance, worldPos = resolvePosition(payload)

        dispatchEffect(resolveCharacter(payload), 'effect:' .. effect, partInstance, worldPos, payload)
    end
    local playEffects = function(effects)
        if type(effects) ~= 'table' then
            return
        end

        for key, entry in next, effects do
            if type(entry) == 'table' then
                fireEffect(entry.effect, entry.data)
            end
        end
    end

    function module.onTrigger(callback)
        ac[#ac + 1] = callback
    end

    local aj = {}
    local connectRemote = function(event)
        local name = event.Name

        if aj[name] then
            return
        end

        local ok, eventConnection = pcall(function()
            return event:IsA('BindableEvent') and event.Event or event.OnClientEvent
        end)

        if not (ok and eventConnection) then
            return
        end

        aj[name] = true
        ad[#ad + 1] = eventConnection:Connect(name == 'ClientEffectBatch' and playEffects or fireEffect)
    end
    local connectEffectEvents = function(parent)
        for idx, typeName in next, {
            'ClientEffect',
            'ClientEffectLarge',
            'ClientEffectDirect',
            'ClientEffectBatch',
        }do
            local eventInstance = parent:FindFirstChild(typeName)

            if eventInstance then
                connectRemote(eventInstance)
            end
        end

        ad[#ad + 1] = parent.ChildAdded:Connect(function(addedChild)
            if addedChild.Name:match('^ClientEffect') then
                connectRemote(addedChild)
            end
        end)
    end

    function module.init()
        local requests = replicatedStorage:FindFirstChild('Requests')

        if requests then
            return connectEffectEvents(requests)
        end

        ad[#ad + 1] = replicatedStorage.ChildAdded:Connect(function(createdChild)
            if createdChild.Name == 'Requests' then
                connectEffectEvents(createdChild)
            end
        end)
    end
    function module.detach()
        for connIndex = 1, #ad do
            ad[connIndex]:Disconnect()
        end

        ad = {}
        ac = {}
        aj = {}
    end

    return module
end


return aa()

]=],
    ["Game/EffectReplicatorWrapper"] = [=[
local aa = function()
    local logger = a["Utility/Logger"]()
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local ac = {}
    local ad = {}
    local getEffectReplicator = function()
        local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return nil
        end

        local ok, module = pcall(require, effectReplicator)

        return ok and module or nil
    end

    function ac.create(effectName, value, duration)
        if type(effectName) ~= 'string' or #effectName == 0 then
            return false, logger.longNotify('Enter an effect name first.')
        end

        local replicator = getEffectReplicator()

        if not (replicator and type(replicator.CreateEffect) == 'function') then
            return false, logger.warn('[EffectSpawner] no EffectReplicator.')
        end

        local params

        if value ~= nil then
            params = {Value = value}
        end

        local success, created = pcall(function()
            return replicator:CreateEffect(effectName, params)
        end)

        if not success or not created then
            return false, logger.warn('[EffectSpawner] %s could not be created (%s).', effectName, tostring(created))
        end
        if duration and duration > 0 and type(created.Debris) == 'function' then
            pcall(function()
                created:Debris(duration)
            end)
        end

        ad[#ad + 1] = created

        logger.notify('Created %s%s.', effectName, duration and duration > 0 and string.format(' for %.2fs', duration) or '')

        return true
    end
    function ac.remove(effectClass)
        if type(effectClass) ~= 'string' or #effectClass == 0 then
            return false, logger.longNotify('Enter an effect name first.')
        end

        local replicatorModule = getEffectReplicator()

        if not replicatorModule then
            return false, logger.warn('[EffectSpawner] no EffectReplicator.')
        end
        if type(replicatorModule.RemoveEffectsOfClass) == 'function' then
            pcall(function()
                replicatorModule:RemoveEffectsOfClass(effectClass)
            end)
        end

        logger.notify('Removed %s.', effectClass)

        return true
    end
    function ac.clear()
        for index = 1, #ad do
            local result = ad[index]

            if result and result.Parent and type(result.Remove) == 'function' then
                pcall(function()
                    result:Remove()
                end)
            end
        end

        ad = {}
    end

    ac.detach = ac.clear

    return ac
end


return aa()

]=],
    ["Game/EffectTracker"] = [=[
local aa = function()
    local latency = a["Game/Latency"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local signal = a["Utility/Signal"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local ag = {}

    ag._now = tick

    local stateMaid = maid.new()
    local ai
    local aj = {}
    local ak = {}
    local al = {}
    local am
    local negInfinity = -math.huge
    local getEffectClass = function(effect)
        if type(effect) ~= 'table' then
            return nil
        end

        return effect.Class or (effect.index and effect.index.Class)
    end
    local ap = {}

    function ag.onAdded(effect)
        ap[#ap + 1] = effect
    end

    local incrementClassCount = function(effect)
        local className = getEffectClass(effect)

        if not className then
            return
        end

        am = nil

        local count = (aj[className] or 0) + 1

        aj[className] = count

        if count == 1 then
            ak[className] = ag._now()
        end

        al[className] = effect

        for index = 1, #ap do
            pcall(ap[index], className, effect)
        end
    end

    ag._add = incrementClassCount

    local decrementClassCount = function(effect)
        local className = getEffectClass(effect)

        if not className then
            return
        end

        am = nil

        local count = (aj[className] or 1) - 1

        if count <= 0 then
            aj[className] = nil
            ak[className] = nil
            al[className] = nil
        else
            aj[className] = count
        end
    end

    ag._rem = decrementClassCount

    local clearAll = function()
        aj = {}
        ak = {}
        al = {}
        am = nil
    end
    local collectEffects = function()
        if not ai then
            return
        end

        local effects = ai.Effects

        if not effects and type(ai.GetEffects) == 'function' then
            local ok, result = pcall(ai.GetEffects, ai)

            if ok then
                effects = result
            end
        end
        if type(effects) ~= 'table' then
            return
        end

        for key, effect in next, effects do
            incrementClassCount(effect)
        end
    end

    ag._seed = collectEffects
    ag.holdTime = 1 / 120

    function ag.hash()
        local now = os.clock()

        if am and now - negInfinity < ag.holdTime then
            return am
        end

        local hash

        if ai and type(ai.GetEffectsHash) == 'function' then
            local ok, result = pcall(ai.GetEffectsHash, ai, true)

            if ok and type(result) == 'table' then
                hash = result
            end
        end
        if not hash then
            hash = {}

            for name, count in next, aj do
                if count > 0 then
                    hash[name] = true
                end
            end
        end

        am = hash
        negInfinity = now

        return hash
    end
    function ag.has(name)
        return ag.hash()[name] ~= nil
    end
    function ag.any(...)
        local hash = ag.hash()

        for index = 1, select('#', ...)do
            if hash[select(index, ...)] ~= nil then
                return true
            end
        end

        return false
    end
    function ag.since(name)
        if not ag.has(name) then
            return nil
        end

        local effect = al[name]
        local createdAt = effect and effect.CreationTime

        if createdAt then
            return ag._now() - createdAt
        end

        local firstSeen = ak[name]

        if not firstSeen then
            return nil
        end

        return ag._now() - firstSeen
    end
    function ag.left(effectId, subtractLatency)
        if not ag.has(effectId) then
            return nil
        end

        local entry = al[effectId]

        if not entry then
            return nil
        end

        local remaining

        if entry.Expiration then
            remaining = entry.Expiration - ag._now()
        else
            local debrisTime, elapsed = entry.DebrisTime, ag.since(effectId)

            if not debrisTime or not elapsed then
                return nil
            end

            remaining = debrisTime - elapsed
        end
        if subtractLatency then
            remaining = remaining - latency.half_ping()
        end

        return remaining < 0 and 0 or remaining
    end
    function ag.value(effectId)
        local entry = al[effectId]

        if entry then
            return entry.Value
        end

        return nil
    end
    function ag.sum(effectId)
        if ai and type(ai.GetEffectSum) == 'function' then
            local success, result = pcall(ai.GetEffectSum, ai, effectId)

            if success then
                return result
            end
        end

        return nil
    end
    function ag.module()
        return ai
    end
    function ag.init()
        clearAll()

        local replicator = replicatedStorage:WaitForChild('EffectReplicator', 20)

        if not replicator then
            logger.warn('[EffectState] EffectReplicator not found.')

            return
        end

        local success, replicatedModule = pcall(require, replicator)

        if not success or type(replicatedModule) ~= 'table' then
            logger.warn('[EffectState] require failed (%s).', tostring(replicatedModule))

            return
        end

        ai = replicatedModule

        if replicatedModule.EffectAdded then
            stateMaid:mark(signal.new(replicatedModule.EffectAdded):connect('EffectState_Add', incrementClassCount))
        end
        if replicatedModule.EffectRemoved then
            stateMaid:mark(signal.new(replicatedModule.EffectRemoved):connect('EffectState_Rem', decrementClassCount))
        end

        collectEffects()

        local localPlayer = players.LocalPlayer

        if localPlayer then
            stateMaid:mark(localPlayer.CharacterAdded:Connect(clearAll))
        end
    end
    function ag.detach()
        stateMaid:clean()

        ai = nil

        clearAll()
    end

    return ag
end


return aa()

]=],
    ["Game/HitboxProbe"] = [=[
local aa = function()
    local entityHistory = a["Features/Combat/EntityHistory"]()
    local latency = a["Game/Latency"]()
    local playersService = game:GetService('Players')
    local runService = game:GetService('RunService')
    local module = {}

    module.autoSize = Vector3.new(8, 8, 10)
    module.visualize = false
    module.visualTime = 0.35
    module.HIT = Color3.new(0, 1, 0)
    module.MISS = Color3.new(1, 0, 0)
    module.PREDICTED_HIT = Color3.new(1, 0, 1)
    module.PREDICTED_MISS = Color3.new(0.349019, 0.345098, 0.345098)
    module.FACING_HIT = Color3.new(0, 1, 1)
    module.FACING_MISS = Color3.new(1, 1, 0)
    module.PAST_HIT = Color3.new(0.839215, 0.97647, 0.537254)
    module.PAST_MISS = Color3.new(0.564705, 0, 1)

    local overlapParams = OverlapParams.new()

    overlapParams.FilterType = Enum.RaycastFilterType.Include

    local ag
    local ah = {}
    local ai
    local hitboxes = {}
    local ak = {
        Block = Enum.PartType.Block,
        Ball = Enum.PartType.Ball,
        Cylinder = Enum.PartType.Cylinder,
    }

    function module.shape(shape)
        if type(shape) == 'string' then
            return ak[shape]
        end

        return shape
    end

    local predictAimPosition = function(aimPart)
        local halfPing = latency.half_ping()
        local velocity = aimPart.AssemblyLinearVelocity

        if not halfPing or halfPing <= 0 or not velocity then
            return aimPart.CFrame
        end

        return aimPart.CFrame + velocity * halfPing
    end
    local am = {}
    local an
    local createProbePart = function()
        local probePart = Instance.new('Part')

        probePart.Anchored = true
        probePart.CanCollide = false
        probePart.CanQuery = false
        probePart.CanTouch = false
        probePart.CastShadow = false
        probePart.Material = Enum.Material.ForceField
        probePart.Transparency = 0.2
        probePart.Parent = workspace

        return probePart
    end
    local pruneExpiredHits = function(now)
        local changed = false

        for key, boxMap in next, am do
            local dirty = false

            for hitKey, hitMarker in next, boxMap do
                if now - hitMarker.seen > module.visualTime then
                    boxMap[hitKey] = nil

                    pcall(function()
                        hitMarker.part:Destroy()
                    end)
                else
                    dirty = true
                end
            end

            if dirty then
                changed = true
            else
                am[key] = nil
            end
        end

        if not changed and an then
            an:Disconnect()

            an = nil
        end
    end

    function module.clearVisuals()
        for visualKey, visualMap in next, am do
            for innerKey, hitRecord in next, visualMap do
                visualMap[innerKey] = nil

                pcall(function()
                    hitRecord.part:Destroy()
                end)
            end

            am[visualKey] = nil
        end

        if an then
            an:Disconnect()

            an = nil
        end
    end

    local probe = function(cframe, size, partShape, color, hitId, hitType)
        if not module.visualize or shared.Palantir_PanicHide then
            if next(am) then
                module.clearVisuals()
            end

            return
        end

        local aw = os.clock()

        if not hitId then
            local visualPart = createProbePart()

            visualPart.Shape = partShape or Enum.PartType.Block
            visualPart.Size = size
            visualPart.CFrame = cframe
            visualPart.Color = color

            task.delay(module.visualTime, function()
                visualPart:Destroy()
            end)

            return
        end

        local entry = am[hitId]

        if not entry then
            entry = {}
            am[hitId] = entry
        end

        local cacheKey = string.format('%s|%g|%g|%g', hitType or 'direct', size.X, size.Y, size.Z)
        local record = entry[cacheKey]

        if not record then
            record = {
                part = createProbePart(),
            }
            entry[cacheKey] = record
        end

        record.seen = aw

        if not an then
            an = runService.Heartbeat:Connect(function()
                pruneExpiredHits(os.clock())
            end)
        end

        local displayPart = record.part

        displayPart.Shape = partShape or Enum.PartType.Block
        displayPart.Size = size
        displayPart.CFrame = cframe
        displayPart.Color = color

        pruneExpiredHits(aw)
    end

    function module.root(model)
        if not model then
            return nil
        end
        if model:IsA('BasePart') then
            return model
        end
        -- Effects/attacks are often delivered as attachments (e.g.
        -- HumanoidRootPart.BloodSlash). An Attachment has no PrimaryPart, so
        -- climb to the part it is attached to instead of indexing the property.
        if model:IsA('Attachment') then
            local parent = model.Parent

            while parent do
                if parent:IsA('BasePart') then
                    return parent
                end

                parent = parent.Parent
            end

            return nil
        end

        local root = model:FindFirstChild('HumanoidRootPart')

        if root and root:IsA('BasePart') then
            return root
        end
        if model:IsA('Model') and model.PrimaryPart then
            return model.PrimaryPart
        end

        return model:FindFirstChildWhichIsA('BasePart', true)
    end
    function module.test(character, probeSize, options)
        if not character or not probeSize then
            return false
        end

        local root = module.root(character)

        if not root then
            return false
        end

        local localPlayer = playersService.LocalPlayer
        local localCharacter = localPlayer and localPlayer.Character

        if not localCharacter then
            return false
        end

        options = options or {}

        local hitCframe = options.cframe or predictAimPosition(root)

        if options.facing then
            hitCframe = hitCframe * CFrame.new(0, 0, -(probeSize.Z / 2))
        end
        if options.shift and options.shift ~= 0 then
            hitCframe = hitCframe * CFrame.new(0, 0, options.shift)
        end
        if options.offset then
            hitCframe = hitCframe * CFrame.new(options.offset)
        end
        if ai ~= localCharacter then
            ai = localCharacter
            ah[1] = localCharacter
            overlapParams.FilterDescendantsInstances = ah
        end

        local shape = module.shape(options.shape)

        if not ag then
            ag = Instance.new('Part')
            ag.Name = 'PalantirXHitboxProbe'
            ag.Anchored = true
            ag.CanCollide = false
            ag.CanQuery = false
            ag.CanTouch = false
            ag.CastShadow = false
            ag.Transparency = 1
            ag.Parent = workspace
        end

        ag.Shape = shape or Enum.PartType.Block
        ag.Size = probeSize
        ag.CFrame = shape == Enum.PartType.Cylinder and hitCframe * CFrame.Angles(0, 0, math.rad(90)) or hitCframe

