                local rarityColor = Color3.fromHex(rarityHex)
                local background = targetItem.BackgroundColor3

                if math.abs(rarityColor.R - background.R) <= 1 / 255 and math.abs(rarityColor.G - background.G) <= 1 / 255 and math.abs(rarityColor.B - background.B) <= 1 / 255 and not enabledRarities[rarityIndex] then
