local aa = function()
    local module = {}
    local stats = game:GetService('Stats')
    local sampleInterval = 0.05
    local samples = {}
    local total = 0
    local setIdentity = (type(setthreadidentity) == 'function' and setthreadidentity) or (type(setidentity) == 'function' and setidentity) or (type(syn) == 'table' and type(syn.set_thread_identity) == 'function' and syn.set_thread_identity) or nil
    local getIdentity = (type(getthreadidentity) == 'function' and getthreadidentity) or (type(getidentity) == 'function' and getidentity) or (type(syn) == 'table' and type(syn.get_thread_identity) == 'function' and syn.get_thread_identity) or nil
    local ah
    local getDataPing = function()
        if ah and ah.Parent then
            return ah
        end

        ah = stats:FindFirstChild('Data Ping', true)

        return ah
    end
    local getLatency = function()
        local rawValue = getDataPing()

        if not rawValue then
            return nil
        end

        local latency

        if setIdentity and getIdentity then
            local identity = getIdentity()

            pcall(setIdentity, 8)

            local ok, result = pcall(rawValue.GetValue, rawValue)

            pcall(setIdentity, identity)

            if ok then
                latency = result
            end
        else
            local success, fetchedValue = pcall(rawValue.GetValue, rawValue)

            if success then
                latency = fetchedValue
            end
        end
        if type(latency) ~= 'number' then
            return nil
        end

        return latency / 1000
