    -- StatsItem.GetValue throws "not allowed for simulation callbacks" when
    -- invoked from Heartbeat/Stepped/PostSimulation/AnimationPlayed callbacks.
    -- Roblox logs that error even under pcall, so calling getLatency() directly
    -- from those callbacks spams the console every frame and slows the whole
    -- script down. Instead we poll the ping from a plain spawned thread (outside
    -- any simulation callback) and cache it; rtt() just reads the cache.
    local cachedLatency
    local pollThread = task.spawn(function()
        while true do
            cachedLatency = getLatency()
            task.wait(0.5)
        end
    end)

    local recordSample = function(timestamp, rtt)
        total = total + 1
        samples[total] = {timestamp, rtt}

        local cutoff = timestamp - 0.5
        local index = 1

        for position = 1, total do
            if samples[position][1] >= cutoff then
                index = position

                break
            end

            index = position + 1
        end

        if index > 1 then
            local count = 0

            for shiftIndex = index, total do
                count = count + 1
                samples[count] = samples[shiftIndex]
            end
            for clearIndex = count + 1, total do
                samples[clearIndex] = nil
            end

            total = count
        end
        if total > 60 then
            local excess = total - 60

            for keepIndex = 1, 60 do
                samples[keepIndex] = samples[keepIndex + excess]
            end
            for trimIndex = 61, total do
                samples[trimIndex] = nil
            end

            total = 60
        end
