    local maxValue = -math.huge

    function module.rtt()
        local now = os.clock()

        if al and now - maxValue < module.holdTime then
            return al
        end

        local ping = cachedLatency

        if not ping then
            return sampleInterval
        end

        recordSample(now, ping)

        sampleInterval = ping
        al = ping
        maxValue = now

        return ping
    end
