        return cachedLatency or sampleInterval
    end
    function module.get_ping()
        return module.rtt()
    end
    function module.half_ping()
        return module.rtt() / 2
    end
    function module.jitter()
        if total < 2 then
            return 0
        end

        local min, max = math.huge, -math.huge

        for idx = 1, total do
            local sampleValue = samples[idx][2]

            if sampleValue < min then
                min = sampleValue
            end
            if sampleValue > max then
                max = sampleValue
            end
        end

        return max - min
    end
    function module.recentPeakRtt()
        if total < 1 then
            return sampleInterval
        end

        local peak = -math.huge

        for readIndex = 1, total do
            local currentValue = samples[readIndex][2]

            if currentValue > peak then
                peak = currentValue
            end
        end

        if peak < sampleInterval then
            return sampleInterval
        end

        return peak
    end
    function module.rttPessimistic()
        local rtt = module.rtt()
        local peakRtt = module.recentPeakRtt()

        if peakRtt > rtt then
            return peakRtt
        end

        return rtt
    end
    function module.rdelay()
        return math.max(module.rtt() / 2, 0)
    end
    function module.sdelay()
        return math.max(module.rtt() / 2, 0)
    end
