local aa = function()
    local callingState = {calling = false}
    local players = game:GetService('Players')
    local ac
    local ad
    local startTime = os.clock()
    local lastTime = os.clock()
    local isAnonymousClosure = function(func)
        if not func or not islclosure(func) then
            return false
        end

        local info = debug.getinfo(func)

        if info.name ~= nil and info.name ~= '' then
            return false
        end

        local constants = debug.getconstants(func)

        if #constants ~= 1 or constants[1] ~= 'Destroy' then
            return false
        end

        local upvalues = debug.getupvalues(func)

        if not upvalues then
            return false
        end

        return true
    end

    function callingState.glrf()
        if ad and os.clock() - lastTime <= 2 then
            return ad
        end

        for index, connection in next, getconnections(players.PlayerRemoving)do
            local connectionFunc = connection.Function

            if not isAnonymousClosure(connectionFunc) then
                continue
            end

            local funcUpvalues = debug.getupvalues(connectionFunc)

            if not funcUpvalues then
                continue
            end

            local destroyRemote = funcUpvalues[2]

            lastTime = os.clock()
            ad = function()
                if callingState.calling then
                    return
                end

                callingState.calling = true

                destroyRemote()

                callingState.calling = false
            end

            return ad
        end

        return nil
    end
    function callingState.gld()
        if ac and os.clock() - startTime <= 2 then
            return ac
        end

        for connIndex, conn in next, getconnections(players.PlayerRemoving)do
            local hopperbinFunc = conn.Function

            if not isAnonymousClosure(hopperbinFunc) then
                continue
            end

            local hopperbinUpvalues = debug.getupvalues(hopperbinFunc)

            if not hopperbinUpvalues then
                continue
            end

            local destroyFunc = hopperbinUpvalues[1]

            ac = destroyFunc
            startTime = os.clock()

            return destroyFunc
        end

        return nil
    end

    return callingState
end


return aa()

