                    continue
                end

                local matchedItem = findMatchingPattern(notifyItems, itemName)

                if not matchedItem then
                    continue
                end

                scanList[item] = matchedItem

                logger.longNotify("%s has item '%s' in their inventory.", formatPlayerLabel(player), itemName)
            end
            for cachedItem, cachedMatch in next, scanList do
                if table.find(notifyItems, cachedMatch) then
                    continue
                end

                scanList[cachedItem] = nil
            end
        end

        startTime = os.clock()
    end
    local processScanQueue = function()
        local localPlayer = players.LocalPlayer

        if not localPlayer then
            return
        end

        -- Collect a stable snapshot first: mutating state.scanQueue while
        -- iterating it with `next` (the previous code set entries to nil mid-loop)
        -- corrupts the iteration, can skip/revisit players, and can leave the
        -- queue in a broken state that makes the next scan spin.
        local pending = {}

        for queuedPlayer in next, state.scanQueue do
            pending[#pending + 1] = queuedPlayer
        end

        for _, queuedPlayer in ipairs(pending) do
            -- The player may have left the game since they were queued; a stale
            -- Player reference throws "Player objects must be children of
            -- 'Players'" on GetRankInGroup/GetFriendStatus. Drop them.
            if not queuedPlayer or not queuedPlayer:IsDescendantOf(players) then
                state.scanQueue[queuedPlayer] = nil
                state.waitingForLoad[queuedPlayer] = nil

                continue
            end
            if state.scanQueue[queuedPlayer] == nil then
                continue
            end

            if not state.scanDataCache[queuedPlayer] then
                local isStaff, staffRank
                local rankOk, rankErr = pcall(function()
                    isStaff, staffRank = state.getStaffRank(queuedPlayer)
                end)

                if not rankOk then
                    logger.warn(
"Scan player %s ran into error '%s' while getting staff rank.", queuedPlayer.Name, tostring(rankErr))
                    logger.mnnotify('Failed to scan player %s for moderator status.', formatPlayerLabel(queuedPlayer))

                    state.scanQueue[queuedPlayer] = nil

                    continue
                end
                if not isStaff then
                    continue
                end
                if configuration.expectToggleValue('NotifyMod') and staffRank then
                    logger.mnnotify("%s is a staff member with the rank '%s' in group.", formatPlayerLabel(queuedPlayer), staffRank)

                    if configuration.expectToggleValue('NotifyModSound') then
                        sound.SoundId = 'rbxassetid://6045346303'
                        sound.PlaybackSpeed = 1
                        sound.Volume = configuration.expectToggleValue('NotifyModSoundVolume') or 10

                        sound:Play()
                    end
                end

                state.scanDataCache[queuedPlayer] = {staffRank = staffRank}
            end

            local queueBackpack = queuedPlayer:FindFirstChild('Backpack')

            if not queueBackpack then
                continue
            end
            if not collectionService:HasTag(queueBackpack, 'Loaded') or #queueBackpack:GetChildren() < 1 then
                if not state.waitingForLoad[queuedPlayer] then
                    debugLog('Player scanning is waiting for %s to load in the game.', formatPlayerLabel(queuedPlayer))
                end

                state.waitingForLoad[queuedPlayer] = true

                continue
            end

            state.scanQueue[queuedPlayer] = nil
            state.friendCache[queuedPlayer] = localPlayer:GetFriendStatus(queuedPlayer) == Enum.FriendStatus.Friend

            debugLog('Player scanning finished scanning %s in queue.', formatPlayerLabel(queuedPlayer))
        end
    end

    function state.hasModerators()
        for player, scanData in next, state.scanDataCache do
            if not scanData.staffRank then
                continue
            end

            return true
        end

        return false
    end
    function state.isAlly(target)
        local guild = players.LocalPlayer:GetAttribute('Guild')

        return state.friendCache[target] or ((guild and #guild >= 1) and target:GetAttribute('Guild') == guild)
    end

    state.nonStaffRoles = {
        member = true,
        members = true,
        guest = true,
        customer = true,
        buyer = true,
    }

    local isStaffRole = function(roleName)
        return type(roleName) == 'string' and state.nonStaffRoles[roleName:lower()] == true
    end

    function state.getStaffRank(member)
        local az, rank = pcall(member.GetRankInGroup, member, 5212858)

        if az and type(rank) == 'number' and rank > 0 then
            local roleOk, role = pcall(member.GetRoleInGroup, member, 5212858)

            debugLog('[PS] %s GetRankInGroup\u{2192}rank=%d role=%s', member.Name, rank, tostring(roleOk and role or '?'))

            if roleOk and isStaffRole(role) then
                return true, nil
            end

            return true, (roleOk and type(role) == 'string' and role) or string.format('Rank %d', rank)
        end

        local requestOk, aC = fetchUrl((
"https://groups.roblox.com/v2/users/%i/groups/roles?includeLocked=true"):format(member.UserId))

        if not requestOk then
            debugLog('[PS] %s HTTP failed: %s', member.Name, tostring(aC))

            return false, aC
        end
        if not aC or not aC.data then
            debugLog('[PS] %s HTTP returned no data field', member.Name)

            return false, 'response data missing'
        end

        for index, entry in next, aC.data do
            if not entry.group or entry.group.id ~= 5212858 then
                continue
            end
            if not entry.role or entry.role.rank <= 0 then
                continue
            end
            if isStaffRole(entry.role.name) then
                debugLog("[PS] %s is in the group as '%s', which is not staff", member.Name, entry.role.name)

                return true, nil
            end

            debugLog('[PS] %s HTTP found Monad role: %s', member.Name, entry.role.name)

            return true, entry.role.name
        end

        debugLog('[PS] %s scan complete \u{2014} not in Monad group via either API', member.Name)

        return true, nil
    end

    state.update = function()
        if os.clock() - startTime >= 5 then
            startTime = os.clock()

            task.spawn(scanNotifyItems)
        end
        if os.clock() - lastScanTime <= 1 then
            return
        end

        lastScanTime = os.clock()

        if state.scanning then
            return
        end

        state.scanning = true

        task.spawn(function()
            local callOk, err = pcall(processScanQueue)

            state.scanning = false

            if not callOk then
                logger.warn('runPlayerScans threw: %s', tostring(err))
            end
        end)
    end

    function state.friend(friendTarget, friendStatus)
        state.friendCache[friendTarget] = friendStatus == Enum.FriendStatus.Friend
    end
    function state.onPlayerAdded(addedPlayer)
        if addedPlayer == players.LocalPlayer then
            return
        end

        state.scanQueue[addedPlayer] = true
    end
    function state.onPlayerRemoving(removedPlayer)
        state.scanQueue[removedPlayer] = nil
        state.scanDataCache[removedPlayer] = nil
        state.friendCache[removedPlayer] = nil
        state.waitingForLoad[removedPlayer] = nil
    end
    function state.init()
        local playerAddedSignal = signal.new(players.PlayerAdded)
        local playerRemovingSignal = signal.new(players.PlayerRemoving)
        local renderSteppedSignal = signal.new(runService.RenderStepped)
        local friendChangedSignal = signal.new(players.LocalPlayer.FriendStatusChanged)

        cleanupMaid:add(friendChangedSignal:connect('PlayerScanning_OnFriendStatusChanged', state.friend))
        cleanupMaid:add(renderSteppedSignal:connect('PlayerScanning_Update', state.update))
        cleanupMaid:add(playerAddedSignal:connect('PlayerScanning_OnPlayerAdded', state.onPlayerAdded))
        cleanupMaid:add(playerRemovingSignal:connect('PlayerScanning_OnPlayerRemoving', state.onPlayerRemoving))

        for position, existingPlayer in next, players:GetPlayers()do
            state.onPlayerAdded(existingPlayer)
        end
    end
    function state.detach()
        cleanupMaid:clean()
    end

    return state
end


return aa()

]=],
    ["Game/QueuedBlocking"] = [=[
local aa = function()
    local keyHandling = a["Game/KeyHandling"]()
    local effectTracker = a["Game/EffectTracker"]()
    local runService = game:GetService('RunService')
    local queues = {}

    queues.DEFLECT = 1
    queues.NORMAL = 2
    queues._now = os.clock

    local module = {}
    local isActive = false
    local currentAction
    local enqueue = function(action)
        local remote = keyHandling.getRemote(action)

        if remote then
            remote:FireServer()
        end
    end
    local dequeueAll = function()
        if not isActive and next(module) == nil then
            return
        end

        local blocking = effectTracker.has('Blocking')
        local now = queues._now()

        for key, entry in next, module do
            local timedOut = entry.dt and now - entry.at >= entry.dt
            local deflected = entry.kind == queues.DEFLECT and blocking
            local shouldRemove = false

            if entry.ok then
                local success, err = pcall(entry.ok)

                shouldRemove = success and not err
            end
            if timedOut or deflected or shouldRemove then
                module[key] = nil
            end
        end

        local hasQueued = next(module) ~= nil

        if isActive then
            if not hasQueued then
                isActive = false

                enqueue('Unblock')
            end

            return
        end
        if hasQueued and not effectTracker.has('Action') and not effectTracker.has('Knocked') then
            isActive = true

            enqueue('Block')
        end
    end

    queues._pump = dequeueAll

    function queues.invoke(kind, key, al, callback)
        if effectTracker.has('CastingSpell') then
            return false
        end

        local fxModule = effectTracker.module()

        if fxModule and type(fxModule.FindEffect) == 'function' then
            local effect = fxModule:FindEffect('M1Buffering')

            if effect then
                effect:Remove()
            end
        end

        isActive = true

        enqueue('Block')

        local ao = al

        if al then
            ao = al + (0.075 + math.random() * 0.04)
        elseif kind == queues.DEFLECT then
            ao = 0.2
        end

        module[key] = {
            kind = kind,
            at = queues._now(),
            dt = ao,
            ok = callback,
        }

        return true
    end
    function queues.stop(key)
        module[key] = nil
    end
    function queues.held(key)
        return module[key] ~= nil
    end
    function queues.release(key)
        module[key] = nil

        if next(module) ~= nil or not isActive then
            return false
        end

        isActive = false

        enqueue('Unblock')

        return true
    end
    function queues.empty()
        module = {}
    end
    function queues.init()
        if not currentAction then
            currentAction = runService.RenderStepped:Connect(dequeueAll)
        end
    end
    function queues.detach()
        if currentAction then
            currentAction:Disconnect()

            currentAction = nil
        end

        module = {}
        isActive = false
    end

    return queues
end


return aa()

]=],
    ["Game/ServerHop"] = [=[
local aa = function()
    local logger = a["Utility/Logger"]()
    local persistentData = a["Utility/PersistentData"]()
    local ac = {}
    local ad = {}
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local players = game:GetService('Players')
    local teleportService = game:GetService('TeleportService')
    local ah
    local ai
    local aj
    local ak
    local al
    local am = {
        [6473861193] = 'EastLuminant',
        [6032399813] = 'EtreanLuminant',
        [5735553160] = 'Depths',
    }
    local logWarning = function(...)
        logger.warn(...)
    end
    local pruneServerBlacklist = function()
        local blacklist = persistentData.get('sblacklist') or {}

        for serverId, timestamp in next, blacklist do
            if tick() - timestamp < 300 then
                continue
            end

            logWarning('(%s) Removed old entry (%s) from server blacklist.', tostring(serverId), tostring(timestamp))

            blacklist[serverId] = nil
        end

        persistentData.set('sblacklist', blacklist)

        return blacklist
    end
    local filterBlacklistedServers = function()
        local prunedBlacklist = pruneServerBlacklist()

        for reverseIndex = #aj, 1, -1 do
            if not prunedBlacklist[aj[reverseIndex].id] then
                continue
            end

            logWarning('(%s) Removed blacklisted server from available servers.', tostring(aj[reverseIndex].id))
            table.remove(aj, reverseIndex)
        end

        table.sort(aj, function(serverA, serverB)
            local serverAScore = serverA.players >= 3 and serverA.players <= 12 and 0 or 1
            local serverBScore = serverB.players >= 3 and serverB.players <= 12 and 0 or 1

            if serverAScore ~= serverBScore then
                return serverAScore < serverBScore
            end

            return serverA.players > serverB.players
        end)

        return aj
    end
    local blockServer = function(blockedServerId)
        local persistedBlacklist = pruneServerBlacklist()

        persistedBlacklist[blockedServerId] = tick()

        persistentData.set('sblacklist', persistedBlacklist)
    end
    local fireServerRequest = function()
        if not ak or shared.Palantir_Dying then
            return
        end
        if ai and os.clock() - ai < 1 then
            return
        end

        ai = os.clock()
        al = ak.id

        replicatedStorage.Requests.StartMenu.PickServer:FireServer(ak.id)
    end
    local onServerRequestResponse = function(...)
        shared.Palantir_Dying = nil

        local regionIndex = select(4, ...)

        if type(regionIndex) == 'number' and am[regionIndex] then
            persistentData.set('shregion', am[regionIndex])
        end

        local failedServerId = al or ak and ak.id

        if not failedServerId then
            return
        end

        logWarning('(%s) Teleport to server failed. Blacklisting it.', tostring(failedServerId))
        blockServer(failedServerId)

        al = nil
        ak = nil
    end
    local isErrorPromptVisible = function()
        local promptGui = game:GetService('CoreGui'):FindFirstChild('RobloxPromptGui')

        promptGui = promptGui and promptGui:FindFirstChild('promptOverlay')
        promptGui = promptGui and promptGui:FindFirstChild('ErrorPrompt')

        if not promptGui or not promptGui.Visible then
            return false
        end

        local errorMessage = promptGui:FindFirstChild('MessageArea')

        errorMessage = errorMessage and errorMessage:FindFirstChild('ErrorFrame')
        errorMessage = errorMessage and errorMessage:FindFirstChild('ErrorMessage')

        if not errorMessage or not errorMessage:IsA('TextLabel') or not errorMessage.Text:find('Error Code: 771', 1, true) then
            return false
        end

        onServerRequestResponse()

        promptGui.Visible = false

        return true
    end
    local clickReturnToSlots = function()
        for descIndex, descendant in ipairs(players.LocalPlayer.PlayerGui:GetDescendants())do
            if not descendant:IsA('TextButton') and not descendant:IsA('TextLabel') then
                continue
            end
            if descendant.Text:lower():gsub('[%s%p]', '') ~= 'returntoslots' then
                continue
            end

            local button = descendant:IsA('GuiButton') and descendant or descendant:FindFirstAncestorWhichIsA('GuiButton')

            if not button or not button.Visible then
                continue
            end

            local connections = getconnections(button.MouseButton1Click)

            if #connections == 0 then
                connections = getconnections(button.Activated)
            end

            for connectionIndex, connection in ipairs(connections)do
                if connection.Enabled then
                    connection:Fire()
                end
            end

            return true
        end
    end
    local waitForButton = function(buttonName, timeout)
        local playerGui = players.LocalPlayer and players.LocalPlayer:FindFirstChild('PlayerGui')
        local deadline = os.clock() + (timeout or 2)

        while os.clock() < deadline do
            if not playerGui then
                break
            end

            for scanIndex, child in ipairs(playerGui:GetDescendants())do
                if child:IsA('GuiButton') and child.Visible and tostring(child.Name) == tostring(buttonName) then
                    return true
                end
            end

            task.wait(0.05)
        end

        return false
    end
    local startServerHop = function(slot, region)
        local serversFolder = replicatedStorage:WaitForChild('Servers')
        local requestsFolder = replicatedStorage:WaitForChild('Requests')
        local startMenu = requestsFolder:WaitForChild('StartMenu')
        local pickSlot = startMenu:WaitForChild('PickSlot')
        local startTime = os.clock()
        local aD = pruneServerBlacklist()

        aj = nil

        pickSlot:FireServer(slot)

        local retryTime = os.clock() + 1
        local refired = false
        local fetchServers = function(regionName)
            local regionFolder = regionName and serversFolder:FindFirstChild(regionName)

            if not regionFolder then
                return
            end

            local serverList = {}

            for index, serverFolder in ipairs(regionFolder:GetChildren())do
                if not serverFolder:IsA('Folder') or aD[serverFolder.Name] then
                    continue
                end

                local numPlayers = serverFolder:FindFirstChild('NumPlayers')
                local communityServer = serverFolder:FindFirstChild('CommunityServer')
                local eventServer = serverFolder:FindFirstChild('EventServer')
                local regionValue = serverFolder:FindFirstChild('Region')
                local hasServer = communityServer and communityServer.Value ~= '' or eventServer and eventServer.Value ~= ''
                local unknownRegion = regionValue and regionValue.Value == 'Unknown Region'

                if numPlayers and numPlayers:IsA('IntValue') and not hasServer and not unknownRegion then
                    serverList[#serverList + 1] = {
                        id = serverFolder.Name,
                        players = numPlayers.Value,
                    }
                end
            end

            if #serverList > 0 then
                aj = serverList
            end
        end

        repeat
            task.wait(0.1)

            if not refired and os.clock() >= retryTime then
                pickSlot:FireServer(slot)

                refired = true
            end
            if not aj then
                fetchServers(region)
            end
        until aj or os.clock() - startTime >= 10

        if not aj then
            return
        end

        return filterBlacklistedServers()
    end

    function ad.lobby()
        ad.detach()

        local slotId = persistentData.get('shslot')

        if not slotId then
            return error('No server hop slot set in PersistentData.')
        end

        logWarning('(%s) Waiting for filtered server data.', tostring(slotId))

        ac[1] = teleportService.TeleportInitFailed:Connect(onServerRequestResponse)
        ac[2] = replicatedStorage.Requests.TeleportFailed.OnClientEvent:Connect(onServerRequestResponse)
        ah = task.spawn(function()
            task.wait(0.75)

            local serverQueue
            local currentRegion

            while game.PlaceId == 4111023553 do
                if currentRegion ~= persistentData.get('shregion') then
                    serverQueue = nil
                end
                if isErrorPromptVisible() then
                    serverQueue = nil

                    task.wait(1)

                    continue
                end

                shared.Palantir_Dying = nil

                if not serverQueue or #serverQueue == 0 then
                    local aA = clickReturnToSlots()

                    if aA then
                        waitForButton(slotId, 1.5)
                    else
                        task.wait(0.5)
                    end

                    currentRegion = persistentData.get('shregion')
                    serverQueue = startServerHop(slotId, currentRegion)
                end
                if serverQueue and #serverQueue > 0 and not shared.Palantir_Dying then
                    ak = table.remove(serverQueue, 1)
                    ai = nil

                    local hopStartTime = os.clock()
                    local lastCheckTime = 0
                    local isDying = false

                    repeat
                        if isErrorPromptVisible() then
                            isDying = true

                            break
                        end
                        if lastCheckTime == 0 or os.clock() - lastCheckTime >= 3 then
                            fireServerRequest()

                            lastCheckTime = os.clock()
                        end

                        task.wait(0.1)
                    until not ak or game.PlaceId ~= 4111023553 or os.clock() - hopStartTime >= 6

                    if isDying then
                        serverQueue = nil
                    end
                    if ak and game.PlaceId == 4111023553 then
                        blockServer(ak.id)
                    end

                    ak = nil
                    al = nil

                    if game.PlaceId == 4111023553 then
                        task.wait(2)
                    end
                else
                    task.wait(1)
                end
            end
        end)
    end
    function ad.detach()
        if ah then
            task.cancel(ah)

            ah = nil
        end

        for index, connection in pairs(ac)do
            connection:Disconnect()
        end

        ac = {}
        ak = nil
        al = nil
    end

    local ax = {
        'DangerPvP',
        'Danger',
        'Knockdown',
        'Knocked',
        'Stun',
        'InCombat',
        'Combat',
        'Carried',
        'AutoParry',
    }
    local requireEffectReplicator = function()
        local effectReplicator = replicatedStorage:FindFirstChild('EffectReplicator')

        if not effectReplicator then
            return
        end

        local ok, effectsModule = pcall(require, effectReplicator)

        if not ok or not effectsModule or not effectsModule.Effects then
            return
        end

        local classSet = {}

        for position, status in ipairs(ax)do
            classSet[status] = true
        end
        for name, effect in pairs(effectsModule.Effects)do
            if classSet[effect.Class] then
                pcall(function()
                    effect:Remove(true)
                end)
            end
        end
    end

    function ad.rlobby()
        logWarning('Returning to lobby.')

        local requests = replicatedStorage:WaitForChild('Requests')
        local returnToMenu = requests:WaitForChild('ReturnToMenu')
        local playerGui = players.LocalPlayer:WaitForChild('PlayerGui')
        local lastFireTime = 0
        local lastPromptTime = 0

        while task.wait(0.1) do
            requireEffectReplicator()

            local now = os.clock()

            if now - lastFireTime >= 1.5 then
                returnToMenu:FireServer()

                lastFireTime = now
            end

            local choicePrompt = playerGui:FindFirstChild('ChoicePrompt')
            local choice = choicePrompt and choicePrompt:FindFirstChild('Choice')

            if not choice or now - lastPromptTime < 1.5 then
                continue
            end

            choice:FireServer(true)

            lastPromptTime = now
        end
    end
    function ad.hop(slot, useBlacklist)
        persistentData.set('shslot', slot)

        local region = am[game.PlaceId]

        if region then
            persistentData.set('shregion', region)
        end

        logWarning('(%s, %s) Hopping to new server.', tostring(slot), tostring(useBlacklist))

        if useBlacklist then
            local blacklist = pruneServerBlacklist()

            blacklist[game.JobId] = tick()

            persistentData.set('sblacklist', blacklist)
        end
        if game.PlaceId == 4111023553 then
            return ad.lobby()
        end

        return ad.rlobby()
    end

    local az = {}

    shared.Palantir_ConnectionWatch = az

    task.spawn(function()
        local lastTeleportTime = -math.huge

        while shared.Palantir_ConnectionWatch == az do
            local promptGui = game:GetService('CoreGui'):FindFirstChild('RobloxPromptGui')

            promptGui = promptGui and promptGui:FindFirstChild('promptOverlay')
            promptGui = promptGui and promptGui:FindFirstChild('ErrorPrompt')

            local messageArea = promptGui and promptGui:FindFirstChild('MessageArea')

            messageArea = messageArea and messageArea:FindFirstChild('ErrorFrame')
            messageArea = messageArea and messageArea:FindFirstChild('ErrorMessage')

            local messageText = promptGui and promptGui.Visible and messageArea and messageArea:IsA('TextLabel') and messageArea.Text:lower()
            local errorCode = messageText and tonumber(messageText:match('error%s*code:%s*(%d+)'))
            local shouldHandle = messageText and (errorCode == 266 or errorCode == 277 or errorCode == 279 or messageText:find('failed to connect', 1, true) or messageText:find('unable to connect', 1, true) or messageText:find('lost connection', 1, true) or messageText:find('connection timed out', 1, true) or messageText:find('internet connection', 1, true) or messageText:find('no response from server', 1, true))

            if shouldHandle and game.PlaceId ~= 4111023553 and os.clock() - lastTeleportTime >= 3 then
                lastTeleportTime = os.clock()

                local player = players.LocalPlayer

                if player then
                    local autoConfig = persistentData.get('auto')
                    local dataSlot = player:GetAttribute('DataSlot')

                    if dataSlot and type(autoConfig) == 'table' and (autoConfig.auto_titus or autoConfig.auto_ferryman or autoConfig.auto_progression) then
                        persistentData.set('shslot', tostring(dataSlot))
                    end

                    pcall(teleportService.Teleport, teleportService, 4111023553, player)
                end
            end

            task.wait(0.1)
        end
    end)

    return ad
end


return aa()

]=],
    ["Game/StatInference"] = [=[
local aa = function()
    local module = {}
    local ab = {
        ['Heavy Weapons'] = 'WeaponHeavy',
        ['Medium Weapons'] = 'WeaponMedium',
        ['Light Weapons'] = 'WeaponLight',
        Strength = 'Strength',
        Fortitude = 'Fortitude',
        Agility = 'Agility',
        Intelligence = 'Intelligence',
        Willpower = 'Willpower',
        Charisma = 'Charisma',
        Flamecharm = 'ElementFire',
        Frostdraw = 'ElementIce',
        Thundercall = 'ElementLightning',
        Galebreathe = 'ElementWind',
        Shadowcast = 'ElementShadow',
        Ironsing = 'ElementMetal',
        Bloodrend = 'ElementBlood',
    }
    local parseStatChange = function(label)
        local statName, beforeValue, afterValue = tostring(label):match('^%s*(.-)%s*%((%d+)%s*\u{2192}%s*(%d+)%)%s*$')
        local ag = ab[statName]

        beforeValue, afterValue = tonumber(beforeValue), tonumber(afterValue)

        if not ag or not beforeValue or not afterValue or beforeValue - afterValue ~= 1 then
            return nil
        end

        return {
            stat = ag,
            before = beforeValue,
            after = afterValue,
            label = label,
        }
    end

    function module.overshoots(statData, targets)
        local overshoots = {}

        for statKey, value in pairs(statData or {})do
            local target = targets and tonumber(targets[statKey])

            value = tonumber(value)

            if value and value >= 0 and target and target > value then
                overshoots[statKey] = target - value
            end
        end

        return overshoots
    end
    function module.required(data, targetsData)
        local total = 0

        for currentStat, overshoot in pairs(module.overshoots(data, targetsData))do
            total = total + overshoot
        end

        return total
    end
