local aa = function()
    local module = {}

    function module.inferPost(current, before, after, postCount)
        if type(current) ~= 'table' or type(before) ~= 'table' or type(after) ~= 'table' or (tonumber(postCount) or 0) < 8 then
            return false
        end

        local beforeDiff, afterDiff = 0, 0
        local dropped, raised, close = 0, 0, 0
        local statKeys = {}

        for stat in pairs(before)do
            statKeys[stat] = true
        end
        for stat2 in pairs(after)do
            statKeys[stat2] = true
        end
        for statKey in pairs(statKeys)do
            local currentValue = tonumber(current['Stat' .. statKey])
            local beforeValue = tonumber(before[statKey]) or 0
            local afterValue = tonumber(after[statKey]) or 0

            if currentValue == nil then
                return false
            end

            beforeDiff = beforeDiff + math.abs(currentValue - beforeValue)
            afterDiff = afterDiff + math.abs(currentValue - afterValue)

            if beforeValue > 0 and currentValue <= beforeValue - 5 then
                dropped = dropped + 1
            end
            if currentValue >= beforeValue + 5 then
                raised = raised + 1
            end
            if afterValue > 0 and math.abs(currentValue - afterValue) <= 3 then
                close = close + 1
            end
        end

        return dropped >= 2 and (raised >= 1 or close >= 3) and afterDiff + 10 <= beforeDiff * 0.55
    end

    return module
end


return aa()

]=],
    ["Game/TargetScanner"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local playersService = game:GetService('Players')
    local runService = game:GetService('RunService')
    local ad = {}

    ad.radius = 150
    ad.allowed = nil
    ad.maxTargets = nil

    local ae = {}
    local af = {}
    local ag = {}
    local ah = {}
    local ai = {}
    local aj = {}
    local ak
    local getRootPart = function(char)
        return char and char:FindFirstChild('HumanoidRootPart')
    end
    local isAliveTarget = function(target)
        local humanoid = target:FindFirstChildOfClass('Humanoid')

        return humanoid ~= nil and humanoid.Health > 0
    end
    local invokeCallbacks = function(callbacks, argument)
        for ap = 1, #callbacks do
            pcall(callbacks[ap], argument)
        end
    end
    local compareDistances = function(leftEntry, rightEntry)
        return ah[leftEntry] < ah[rightEntry]
    end
    local pruneLiveEntries = function()
        for idx = 1, #ag do
            ah[ag[idx] ] = nil
            ag[idx] = nil
        end

        local localPlayer = playersService.LocalPlayer
        local character = localPlayer and localPlayer.Character
        local rootPart = character and getRootPart(character)
        local liveFolder = rootPart and workspace:FindFirstChild('Live')
        local count = 0

        if liveFolder and rootPart then
            local origin = rootPart.Position
            local radius = ad.radius
            local allowed = ad.allowed
            local restrict = allowed ~= nil and next(allowed) ~= nil

            for childIndex, child in next, liveFolder:GetChildren()do
                if child ~= character then
                    local childRoot = getRootPart(child)

                    if childRoot and isAliveTarget(child) then
                        local distance = (childRoot.Position - origin).Magnitude

                        if distance <= radius then
                            local isPlayer = playersService:GetPlayerFromCharacter(child) ~= nil

                            if not restrict or (isPlayer and allowed.PVP) or (not isPlayer and allowed.PVE) then
                                count = count + 1
                                ag[count] = child
                                ah[child] = distance
                            end
                        end
                    end
                end
            end
        end

        local maxTargets = ad.maxTargets or configuration.expectOptionValue('APMaxTargets')

        if maxTargets and maxTargets > 0 and count > maxTargets then
            table.sort(ag, compareDistances)

            count = maxTargets
        end

        for key in next, af do
            af[key] = nil
        end

        for index = 1, count do
            af[ag[index] ] = true
        end

        for current in next, af do
            if not ae[current] then
                invokeCallbacks(ai, current)
            end
        end
        for previous in next, ae do
            if not af[previous] then
                invokeCallbacks(aj, previous)
            end
        end

        ae, af = af, ae
    end

    ad._scan = pruneLiveEntries

    function ad.onEnter(enterCallback)
        ai[#ai + 1] = enterCallback
    end
    function ad.onLeave(leaveCallback)
        aj[#aj + 1] = leaveCallback
    end
    function ad.is(entry)
        return ae[entry] == true
    end
    function ad.near(other)
        local me = playersService.LocalPlayer
        local meRoot = me and me.Character and getRootPart(me.Character)
        local otherRoot = other and getRootPart(other)

        if not (meRoot and otherRoot) then
            return false
        end

        return (otherRoot.Position - meRoot.Position).Magnitude <= ad.radius
    end
    function ad.list()
        local result = {}

        for tracked in next, ae do
            result[#result + 1] = tracked
        end

        return result
    end
    function ad.init()
        if not ak then
            ak = runService.RenderStepped:Connect(pruneLiveEntries)
        end
    end
    function ad.detach()
        if ak then
            ak:Disconnect()

            ak = nil
        end

        for stale in next, ae do
            invokeCallbacks(aj, stale)
        end

        ae = {}
        af = {}
        ag = {}
        ah = {}
        ai = {}
        aj = {}
    end

    return ad
end


return aa()

