local aa = function()
    local actionModule = {}

    actionModule.__index = actionModule
    actionModule.FALLBACKS = {
        Block = 'fbb',
        Mantra = 'fbn',
        Dodge = 'fbd',
    }

    function actionModule:when()
        return self._when / 1000
    end
    function actionModule:load(data)
        if typeof(data._type) == 'string' then
            self._type = data._type
        end
        if typeof(data.when) == 'number' then
            self._when = data.when
        end
        if typeof(data.name) == 'string' then
            self.name = data.name
        end
        if typeof(data.hitbox) == 'table' then
            self.hitbox = Vector3.new(data.hitbox.X, data.hitbox.Y, data.hitbox.Z)
        end
        if typeof(data.ihbc) == 'boolean' then
            self.ihbc = data.ihbc
        end
        if typeof(data.duih) == 'boolean' then
            self.duih = data.duih
        end
        if typeof(data.fhb) == 'boolean' then
            self.fhb = data.fhb
        end
        if typeof(data.htype) == 'string' then
            self.htype = data.htype
        end

        for key, field in next, actionModule.FALLBACKS do
            if typeof(data[field]) == 'table' then
                self[field] = actionModule.new(data[field])
            end
        end

        if typeof(data.mpoll) == 'number' then
            self.mpoll = data.mpoll
        end
        if typeof(data.hso) == 'number' then
            self.hso = data.hso
        end
        if typeof(data.offset) == 'table' then
            self.offset = Vector3.new(data.offset.X or 0, data.offset.Y or 0, data.offset.Z or 0)
        end
        if typeof(data.bfht) == 'number' then
            self.bfht = data.bfht
        end
        if typeof(data.ibfc) == 'boolean' then
            self.ibfc = data.ibfc
        end
        if typeof(data.iapf) == 'boolean' then
            self.iapf = data.iapf
        end
        if typeof(data.idf) == 'boolean' then
            self.idf = data.idf
        end
        if typeof(data.ihp) == 'boolean' then
            self.ihp = data.ihp
        end
        if typeof(data.nbfb) == 'boolean' then
            self.nbfb = data.nbfb
        end
        if typeof(data.ndfb) == 'boolean' then
            self.ndfb = data.ndfb
        end
        if typeof(data.nrc) == 'boolean' then
            self.nrc = data.nrc
        end
    end
    function actionModule:equals(other)
        if self.offset ~= other.offset then
            return false
        end
        if self._type ~= other._type then
            return false
        end
        if self._when ~= other._when then
            return false
        end
        if self.name ~= other.name then
            return false
        end
        if self.hitbox ~= other.hitbox then
            return false
        end

        for key, field in next, actionModule.FALLBACKS do
            local left, right = self[field], other[field]

            if (left == nil) ~= (right == nil) then
                return false
            end
            if left and not left:equals(right) then
                return false
            end
        end

        if self.htype ~= other.htype then
            return false
        end
        if self.fhb ~= other.fhb then
            return false
        end
        if self.duih ~= other.duih then
            return false
        end
        if self.mpoll ~= other.mpoll then
            return false
        end
        if self.hso ~= other.hso then
            return false
        end
        if self.ibfc ~= other.ibfc then
            return false
        end
        if self.iapf ~= other.iapf then
            return false
        end
        if self.idf ~= other.idf then
            return false
        end
        if self.ihp ~= other.ihp then
            return false
        end
        if self.nbfb ~= other.nbfb then
            return false
        end
        if self.ndfb ~= other.ndfb then
            return false
        end
        if self.nrc ~= other.nrc then
            return false
        end
        if self.bfht ~= other.bfht then
            return false
        end
        if self.ihbc ~= other.ihbc then
            return false
        end

        return true
    end
    function actionModule:clone()
        local clone = actionModule.new()

        clone._type = self._type
        clone._when = self._when
        clone.name = self.name
        clone.hitbox = self.hitbox
        clone.ihbc = self.ihbc
        clone.duih = self.duih
        clone.fhb = self.fhb
        clone.htype = self.htype

        for key, field in next, actionModule.FALLBACKS do
            clone[field] = self[field] and self[field]:clone() or nil
        end

        clone.mpoll = self.mpoll
        clone.hso = self.hso
        clone.offset = self.offset
        clone.bfht = self.bfht
        clone.ibfc = self.ibfc
        clone.iapf = self.iapf
        clone.idf = self.idf
        clone.ihp = self.ihp
        clone.nbfb = self.nbfb
        clone.ndfb = self.ndfb
        clone.nrc = self.nrc

        return clone
    end
    function actionModule:serialize()
        return {
            offset = self.offset and {
                X = self.offset.X,
                Y = self.offset.Y,
                Z = self.offset.Z,
            } or nil,
            _type = self._type,
            when = self._when,
            name = self.name,
            hitbox = {
                X = self.hitbox.X,
                Y = self.hitbox.Y,
                Z = self.hitbox.Z,
            },
            ihbc = self.ihbc,
            duih = self.duih,
            fhb = self.fhb,
            htype = self.htype,
            fbb = self.fbb and self.fbb:serialize() or nil,
            fbn = self.fbn and self.fbn:serialize() or nil,
            fbd = self.fbd and self.fbd:serialize() or nil,
            mpoll = self.mpoll,
            hso = self.hso,
            bfht = self.bfht,
            ibfc = self.ibfc,
            iapf = self.iapf,
            idf = self.idf,
            ihp = self.ihp,
            nbfb = self.nbfb,
            ndfb = self.ndfb,
            nrc = self.nrc,
        }
    end
