        ac.hso = nil
        ac.bfht = nil
        ac.ibfc = nil
        ac.iapf = nil
        ac.idf = nil
        ac.ihp = nil
        ac.nbfb = nil
        ac.ndfb = nil
        ac.nrc = nil

        if action then
            ac:load(action)
        end

        return ac
    end

    return actionModule
end


return aa()

