    ["Game/Timings/ActionContainer"] = [=[
local aa = function()
    local aa = a["Game/Timings/Action"]()
    local ab = {}

    ab.__index = ab

    function ab:clone()
        local cloned = ab.new()

        for name, action in next, self._data do
            cloned:push(action:clone())
        end

        return cloned
    end
    function ab:equals(other)
        if self:count() ~= other:count() then
            return false
        end

        for name, action in next, self._data do
            local otherAction = other:find(name)

            if not otherAction then
                return false
            end
            if not action:equals(otherAction) then
                return false
            end
        end

        return true
    end
    function ab:find(name)
        return self._data[name]
    end
    function ab:remove(action)
        self._data[action.name] = nil

        local index = table.find(self._stack, action)

        if not index then
            return
        end

        table.remove(self._stack, index)
    end
    function ab:push(action)
        local actionName = action.name

        if self._data[actionName] then
            return error(string.format("Action name '%s' already exists in container.", actionName))
        end

        self._data[actionName] = action

        table.insert(self._stack, action)
    end
    function ab:load(items)
        for index, data in next, items do
            self:push(aa.new(data))
        end
    end
    function ab:names()
        local result = {}

        for name in next, self._data do
            table.insert(result, name)
        end

        return result
    end
    function ab:stack()
        return self._stack
    end
    function ab:count()
        return #self._stack
    end
    function ab:clear()
        self._data = {}
        self._stack = {}
    end
    function ab:get()
        return self._data
    end
    function ab:serialize()
        local result = {}

        for name, action in next, self._data do
            table.insert(result, action:serialize())
        end

        return result
    end
    function ab.new(items)
        local instance = setmetatable({}, ab)

        instance._data = {}
        instance._stack = {}

        if items then
            instance:load(items)
        end

        return instance
    end

    return ab
end


return aa()

]=],
    ["Game/Timings/ActionRunner"] = [=[
local aa = function()
    local autoParry = a["Features/Combat/AutoParry2"]()
    local autoParryBlockers = a["Features/Combat/AutoParryBlockers"]()
    local hitboxProbe = a["Game/HitboxProbe"]()
    local characterActions = a["Game/CharacterActions"]()
    local latency = a["Game/Latency"]()
    local logger = a["Utility/Logger"]()
    local moduleManager = a["Game/Timings/ModuleManager"]()
    local queuedBlocking = a["Game/QueuedBlocking"]()
    local scheduler = a["Game/Timings/Scheduler"]()
    local stateListener = a["Features/Combat/StateListener"]()
    local targetScanner = a["Game/TargetScanner"]()
    local players = game:GetService('Players')
    local am = {}

    am.debug = false
    am.after = 0.2
    am.repeatTimeout = 5

    local an = setmetatable({}, {
        __mode = 'k',
    })
    local ao = {}

    function am.onAction(callback)
        ao[#ao + 1] = callback
    end

    local runCallbacks = function(ap, aq, ar, as)
        for subIndex = 1, #ao do
            pcall(ao[subIndex], ap, aq, ar, as)
        end
    end
    local isCompleted = function(target)
        return target == nil or target.done or target.x
    end
    local getActionList = function(name, kind)
        local category = an[name or false]

        if not category then
            category = {}
            an[name or false] = category
        end

        kind = kind or 'any'

        local actionList = category[kind]

        if not actionList then
            actionList = {}
            category[kind] = actionList
        end

        local keptCount = 0

        for listIndex = 1, #actionList do
            if not isCompleted(actionList[listIndex]) then
                keptCount = keptCount + 1
                actionList[keptCount] = actionList[listIndex]
            end
        end
        for clearIndex = keptCount + 1, #actionList do
            actionList[clearIndex] = nil
        end

        return actionList
    end

    function am.cancel(cancelName, cancelType, includeForced)
        local cancelCategory = an[cancelName or false]

        if not cancelCategory then
            return 0
        end

        local cancelledCount = 0

        for entryType, entryList in next, cancelCategory do
            if cancelType == nil or entryType == cancelType then
                local survivors = 0

                for entryIndex = 1, #entryList do
                    local entry = entryList[entryIndex]

                    if entry.forced and not includeForced then
                        survivors = survivors + 1
                        entryList[survivors] = entry
                    elseif entry.cancel then
                        entry:cancel()

                        cancelledCount = cancelledCount + 1
                    end
                end
                for removalIndex = survivors + 1, #entryList do
                    entryList[removalIndex] = nil
                end

                if survivors == 0 then
                    cancelCategory[entryType] = nil
                end
            end
        end

        return cancelledCount
    end
    function am.pending(pendingName, pendingType)
        local pendingCategory = an[pendingName or false]

        if not pendingCategory then
            return 0
        end

        local pendingCount = 0

        for groupType, groupList in next, pendingCategory do
            if pendingType == nil or groupType == pendingType then
                for checkIndex = 1, #groupList do
                    if not isCompleted(groupList[checkIndex]) then
                        pendingCount = pendingCount + 1
                    end
                end
            end
        end

        return pendingCount
    end

    local as = {}
    local at = {}
    local getAfterTime = function(item)
        local after = item and item.after

        if type(after) ~= 'number' then
            return am.after
        end

        return after
    end

    am.window = getAfterTime

    function am.upcoming()
        local upcomingCount = 0

        for bucketName, bucket in next, an do
            for bucketType, bucketList in next, bucket do
                for bucketIndex = 1, #bucketList do
                    local candidate = bucketList[bucketIndex]

                    if not isCompleted(candidate) then
                        local aC = candidate.at

                        if candidate.raw and candidate.cmp then
                            local ok, cmpResult = pcall(candidate.cmp)

                            aC = candidate.raw - ((ok and cmpResult) or 0)
                        end
                        if aC then
                            upcomingCount = upcomingCount + 1
                            as[upcomingCount] = aC
                            at[upcomingCount] = candidate.win or am.after
                        end
                    end
                end
            end
        end

        for wipeIndex = upcomingCount + 1, #as do
            as[wipeIndex] = nil
            at[wipeIndex] = nil
        end

        return as, at
    end
    function am.engaged()
        local engagedCount = 0

        for activeName in next, an do
            if am.pending(activeName ~= false and activeName or nil) > 0 then
                engagedCount = engagedCount + 1
            end
        end

        return engagedCount
    end

    local logDebug = function(context, format, ...)
        if not am.debug then
            return
        end

        logger.notify('[%s] %s', (type(context) == 'table' and context.name) or tostring(context), string.format(format, 
...))
    end

    am.note = logDebug

    local validateAction = function(options, animation, startTime, part)
        if part and not part.Parent then
            return false, 'the part is gone'
        end
        if animation then
            if not options.iae and not animation.IsPlaying then
                return false, 'animation ended'
            end
            if options.iae and not options.ieae and not animation.IsPlaying and (animation.TimePosition or 0) < (animation.Length or 0) then
                return false, 'animation ended early'
            end
        end
        if not startTime then
            return true
        end

        local animTimeout = options.mat
        local elapsed = scheduler._now() - startTime

        if animation then
            if options.iae and animTimeout and animTimeout > 0 and elapsed >= animTimeout / 1000 then
                return false, string.format('past the %gms animation timeout', animTimeout)
            end

            return true
        end

        local timeout = (animTimeout and animTimeout > 0 and animTimeout / 1000) or am.repeatTimeout

        if elapsed >= timeout then
            return false, string.format('nothing happened for %gs', timeout)
        end

        return true
    end
    local targetDistance = function(target)
        local localPlayer = players.LocalPlayer
        local localRoot = localPlayer and localPlayer.Character and hitboxProbe.root(localPlayer.Character)
        local targetRoot = target and hitboxProbe.root(target)

        if not (localRoot and targetRoot) then
            return nil
        end

        return (targetRoot.Position - localRoot.Position).Magnitude
    end
    local isValidTarget = function(character, settings)
        if not (settings.cit and character) then
            return true
        end

        local targetValue = character:FindFirstChild('Target')

        if not targetValue then
            return true
        end

        local player = players.LocalPlayer

        return targetValue.Value == (player and player.Character)
    end
    local isInRange = function(rangeOptions, candidate)
        local minDistance, maxDistance = rangeOptions.imdd, rangeOptions.imxd

        if not ((minDistance and minDistance > 0) or (maxDistance and maxDistance > 0)) then
            return true
        end

        local distance = targetDistance(candidate)

        if not distance then
            return true
        end
        if minDistance and minDistance > 0 and distance < minDistance then
            return false, string.format('%.1f studs is closer than %.1f', distance, minDistance)
        end
        if maxDistance and maxDistance > 0 and distance > maxDistance then
            return false, string.format('%.1f studs is further than %.1f', distance, maxDistance)
        end

        return true
    end
    local withinDeadline = function(attacker, deadline)
        if not deadline then
            return true
        end

        -- Scheduler ticks on Heartbeat, so a timer always fires a fraction of a
        -- frame after its deadline. A zero late window therefore drops every
        -- action (Luma dumps store after = 0 for almost every timing). Treat a
        -- non-positive window as "use the default" instead of "fire exactly".
        local window = getAfterTime(attacker)

        if window <= 0 then
            window = am.after
        end

        return scheduler._now() <= deadline + window
    end
    local pickField = function(primary, fallback, key)
        if primary and primary[key] ~= nil then
            return primary[key]
        end

        return fallback and fallback[key]
    end
    local validateHitbox = function(combatant, hitConfig, activeConfig, hitPart)
        if activeConfig.ihbc or not combatant then
            return true
        end

        local hitbox = activeConfig.hitbox

        if not hitbox or (hitbox.X == 0 and hitbox.Y == 0 and hitbox.Z == 0) then
            return true
        end

        local hit, hitSource

        if hitPart and hitPart:IsA('BasePart') then
            hit = hitboxProbe.test(combatant, hitbox, {
                cframe = hitConfig.uhc and hitPart.CFrame or CFrame.new(hitPart.Position),
                shape = activeConfig.htype or hitConfig.htype,
                shift = activeConfig.hso or hitConfig.hso,
            })
            hitSource = 'part'
        else
            hit, hitSource = hitboxProbe.resolve(combatant, hitbox, hitConfig, activeConfig)
        end
        if hit then
            return true, string.format("In hitbox via '%s' check.", tostring(hitSource))
        end

        return false, 'Not in hitbox.'
    end
    local aD = {}
    local tryParry = function(mover, input, config, actionName, actionStart, callback)
        return autoParry.run(input, callback or function(message, ...)
            logDebug(input, message, ...)
        end, false, config, mover, actionName, actionStart) ~= nil
    end

    aD.Parry = function(parryMover, parryOpponent, parryConfig, comboState, parryCallback)
        return tryParry(parryMover, parryOpponent, parryConfig, 'Parry', comboState and comboState.start, parryCallback)
    end
    aD.Dodge = function(dodgeMover, dodgeOpponent, dodgeConfig, dodgeState, dodgeCallback)
        return tryParry(dodgeMover, dodgeOpponent, dodgeConfig, 'Dodge', dodgeState and dodgeState.start, dodgeCallback)
    end
