        if not trackOk then
            log('Skipped: %s.', trackReason)

            return false
        end

        local inRange, rangeReason = isInRange(actor, foe)

        if not inRange then
            log('Out of range: %s.', rangeReason)

            return false
        end
        if not isValidTarget(foe, actor) then
            log('Not being targeted.')

            return false
        end
