                local token = {done = false}
                local probeHandle

                function token.cancel()
                    token.done = true

                    if probeHandle and probeHandle.cancel then
                        probeHandle:cancel()
                    end
                end

                local awaitContact = function()
                    if token.done then
                        return
                    end

                    logDebug(spec, "Waiting for contact with a %gx%gx%g box on '%s'.", hitbox.X, hitbox.Y, hitbox.Z, (anchor and anchor.Name) or '?')

                    probeHandle = hitboxProbe.await(anchor, hitbox, spec, function()
                        performAction(entity, spec, action, params, true)
                    end, action, function()
                        local keepWaiting, message = validateAction(spec, params and params.track, params and params.start, params and params.part)

                        if not keepWaiting then
                            local probe = probeHandle
                            local probePos = probe and probe.pos

                            logDebug(spec, 
"Gave up waiting for contact: %s. Closest %s studs, %d test(s), alive %dms, last at %s.", message, (probe and probe.closest and string.format('%.1f', probe.closest)) or '?', (probe and probe.tests) or 0, (probe and probe.t0 and (os.clock() - probe.t0) * 1000) or 0, (probePos and string.format('%.0f, %.0f, %.0f', probePos.X, probePos.Y, probePos.Z)) or '?')
                        end

                        return keepWaiting
                    end)
                end

                if aY > 0 then
