                handle = token
            else
                local delayMs = math.max(action:when() - baseDelay - gateDelay * 1000, 0)
                local endTime = scheduler._now() + delayMs

                handle = scheduler.after(delayMs, function()
                    performAction(entity, spec, action, {
                        kind = kind,
                        rollInstead = params.rollInstead,
                        track = params.track,
                        part = params.part,
                        start = params.start,
                        at = endTime,
                    })
                end, action._type)
            end
            if handle then
                handle.win = getAfterTime(spec)

                if spec.forced then
                    handle.forced = true
                end
            end

            local records = getActionList(entity, kind)

            records[#records + 1] = handle
        end

        local animSpeed = params and params.track and params.track.Speed

        logDebug(spec, 'Matched: %d action(s) scheduled. Anim speed %s.', #actions, (type(animSpeed) == 'number' and string.format('%.2f', animSpeed)) or 'n/a')

        return #actions
    end

    moduleManager.engine = moduleManager.engine or {}
    moduleManager.engine.part = function(part, actionSpec)
        return am.run(nil, actionSpec, {
            kind = 'part',
            part = part,
        })
    end

    return am
end


