        profileEntry.stopWatch = finalize
        connection = runService.PreRender:Connect(function()
            local elapsed = os.clock() - startTime
            local aw, ax, ay, az, position = false, 0, 0, 0, 0
            local ok = pcall(function()
                aw = track.IsPlaying and true or false
                ax = tonumber(track.Speed) or 0
                ay = tonumber(track.WeightCurrent) or 0
                az = tonumber(track.WeightTarget) or 0
