    function module.targetCount()
        local count = 0

        for callbackKey in next, callbacks do
            count = count + 1
        end

        return count
    end
    function module.isAllTargets()
        return enabled
    end
    function module.isActive()
        return enabled or next(callbacks) ~= nil
    end
    function module.entries()
        return animations
    end
    function module.blacklist(animId)
        if not animId or states[animId] then
            return
        end

        states[animId] = true

        for index = #animations, 1, -1 do
            if animations[index].id == animId then
                table.remove(animations, index)
            end
        end

        setup()
    end
    function module.unblacklist(stateId)
        if not states[stateId] then
            return
        end

        states[stateId] = nil

        setup()
    end
    function module.isBlacklisted(blacklistId)
        return states[blacklistId] == true
    end
    function module.blacklisted()
        local blacklist = {}

        for stateKey in next, states do
            blacklist[#blacklist + 1] = stateKey
        end

        table.sort(blacklist)

        return blacklist
    end
    function module.onBlacklistChanged(handler)
        helpers[#helpers + 1] = handler
    end
    function module.shortId(assetId)
        return (tostring(assetId):gsub('rbxassetid://', ''))
    end
    function module.fadeText(animation)
        if not animation or animation.fade == nil then
            return 'measuring\u{2026}'
        end
        if animation.fade == math.huge then
            return 'never blended'
        end

        return string.format('%.0fms (%s)', animation.fade * 1000, animation.fadeKind)
    end
    function module.details(anim)
        if not anim then
            return 'No animation selected.'
        end

        return string.format('%s | %s (%s)\nid: %s\nlength %.3fs | speed %.2fx | %s\nweight %.2f \u{2192} %.2f | fade %s', anim.name, anim.source, anim.sourceName, anim.id, anim.length or 0, anim.speed or 0, anim.priority or '?', anim.weightCurrent or 0, anim.weightTarget or 0, module.fadeText(anim))
    end
    function module.clear()
        for loopIndex = 1, #animations do
            if animations[loopIndex].stopWatch then
                animations[loopIndex].stopWatch()
            end
        end

        animations = {}
    end
    function module.onEntry(entry)
        timings[#timings + 1] = entry
    end
    function module.detach()
        module.deselect()
        module.clear()
        maid:clean()

        timings = {}
        helpers = {}
        states = {}
    end

    return module
end


return aa()

