local aa = function()
    local timing = a["Game/Timings/Timing"]()
    local timingModule = setmetatable({}, {__index = timing})

    timingModule.__index = timingModule

    function timingModule:id()
        return self._id
    end
    function timingModule:equals(other)
        if not timing.equals(self, other) then
            return false
        end
        if self.ftag ~= other.ftag then
            return false
        end
        if self.iae ~= other.iae then
            return false
        end
        if self.ieae ~= other.ieae then
            return false
        end
        if self.mat ~= other.mat then
            return false
        end
        if self.cit ~= other.cit then
            return false
        end
        if self.ffh ~= other.ffh then
            return false
        end
        if self.phd ~= other.phd then
            return false
        end
        if self.pfh ~= other.pfh then
            return false
        end
        if self.phds ~= other.phds then
            return false
        end
        if self.phdn ~= other.phdn then
            return false
        end
        if self.pfht ~= other.pfht then
            return false
        end
        if self.dp ~= other.dp then
            return false
        end

        return true
    end
    function timingModule:load(data)
        timing.load(self, data)

        if typeof(data._id) == 'string' then
            self._id = data._id
        end
        if typeof(data.ftag) == 'string' then
            self.ftag = data.ftag
        end
        if typeof(data.iae) == 'boolean' then
            self.iae = data.iae
        end
        if typeof(data.ieae) == 'boolean' then
            self.ieae = data.ieae
        end
        if typeof(data.mat) == 'number' then
            self.mat = data.mat
        end
        if typeof(data.cit) == 'boolean' then
            self.cit = data.cit
        end
        if typeof(data.ffh) == 'boolean' then
            self.ffh = data.ffh
        end
        if typeof(data.phd) == 'boolean' then
            self.phd = data.phd
        end
        if typeof(data.pfh) == 'boolean' then
            self.pfh = data.pfh
        end
        if typeof(data.phds) == 'number' then
            self.phds = data.phds
        end
        if typeof(data.phdn) == 'number' then
            self.phdn = data.phdn
        end
        if typeof(data.pfht) == 'number' then
            self.pfht = data.pfht
        end
        if typeof(data.dp) == 'boolean' then
            self.dp = data.dp
        end
    end
    function timingModule:clone()
        local copy = setmetatable(timing.clone(self), timingModule)

        copy._id = self._id
        copy.ftag = self.ftag
        copy.iae = self.iae
        copy.ieae = self.ieae
        copy.mat = self.mat
        copy.cit = self.cit
        copy.ffh = self.ffh
        copy.phd = self.phd
        copy.pfh = self.pfh
        copy.phds = self.phds
        copy.phdn = self.phdn
        copy.pfht = self.pfht
        copy.dp = self.dp

        return copy
    end
    function timingModule:serialize()
        local result = timing.serialize(self)

        result._id = self._id
        result.ftag = self.ftag
        result.iae = self.iae
        result.ieae = self.ieae
        result.mat = self.mat
        result.cit = self.cit
        result.ffh = self.ffh
        result.phd = self.phd
        result.pfh = self.pfh
        result.phds = self.phds
        result.phdn = self.phdn
        result.pfht = self.pfht
        result.dp = self.dp

        return result
    end
    function timingModule.new(initData)
        local instance = setmetatable(timing.new(), timingModule)

        instance.dp = false
        instance._id = ''
        instance.ftag = 'Any'
        instance.iae = false
        instance.ieae = false
        instance.mat = 2000
        instance.cit = false
        instance.ffh = false
        instance.phd = false
        instance.pfh = false
        instance.phds = 0
        instance.phdn = 0
        instance.pfht = 0.15

        if initData then
            instance:load(initData)
        end

        return instance
    end

    return timingModule
end


return aa()

]=],
    ["Game/Timings/AudioScanner"] = [=[
local aa = function()
    local module = {}
    local ab = {}
    local ac
    local dispatchSound = function(event, args, sound)
        for index = 1, #ab do
            pcall(ab[index], event, args, nil, nil, sound)
        end
    end
    local ae = {
        Sound = true,
        AudioPlayer = true,
    }
    local getSoundId = function(audioObj)
        if not ae[audioObj.ClassName] then
            return nil
        end
        if audioObj:IsA('AudioPlayer') then
            return audioObj.AssetId
        end
        if audioObj:IsA('Sound') then
            return audioObj.SoundId
        end

        return nil
    end
    local reportSound = function(soundObj)
        local id = getSoundId(soundObj)

        if not id then
            return
        end

        dispatchSound(soundObj:FindFirstAncestorWhichIsA('Model'), 'sound:' .. tostring(id), soundObj)
    end

    function module.onTrigger(trigger)
        ab[#ab + 1] = trigger
    end
    function module.init()
        if not ac then
            ac = workspace.DescendantAdded:Connect(reportSound)
        end
    end
    function module.detach()
        if ac then
            ac:Disconnect()

            ac = nil
        end

        ab = {}
    end

    return module
end


return aa()

