    ["Game/Timings/EffectReplicatorHelper"] = [=[
local aa = function()
    local configuration = a["Utility/Configuration"]()
    local feature = a["Features/Feature"]()
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local runService = game:GetService('RunService')
    local getMaxMomentum = function()
        local module = replicatedStorage:FindFirstChild('EffectReplicator')

        if not module then
            return nil
        end

        local ok, mod = pcall(require, module)

        return ok and mod or nil
    end
    local maxMomentum = feature.new('MaxMomentum', runService.PreSimulation, function()
        local af = getMaxMomentum()

        if not af then
            return
        end

        local forceMomentum = af:FindEffect('ForceMomentum')

        if not forceMomentum then
            af:CreateEffect('ForceMomentum')

            return
        end
        if forceMomentum.Value ~= 10 then
            forceMomentum.Value = 10
        end

        forceMomentum.Disabled = not (configuration.expectOptionValue('ActiveSpoofers') or {})['Max Momentum']
    end)

    function maxMomentum:onDisable()
        local ag = getMaxMomentum()

        if not ag then
            return
        end

        local forceMomentum = ag:FindEffect('ForceMomentum')

        if forceMomentum then
            forceMomentum.Disabled = true
        end
    end

    return maxMomentum
end


return aa()

