    ["Game/Timings/EffectTiming"] = [=[
local aa = function()
    local timing = a["Game/Timings/Timing"]()
    local effectTiming = setmetatable({}, {__index = timing})

    effectTiming.__index = effectTiming

    function effectTiming:id()
        return self.ename
    end
    function effectTiming:equals(other)
        if not timing.equals(self, other) then
            return false
        end
        if self.ename ~= other.ename then
            return false
        end
        if self.ilp ~= other.ilp then
            return false
        end
        if self.flp ~= other.flp then
            return false
        end

        return true
    end
    function effectTiming:load(other)
        timing.load(self, other)

        if typeof(other.ename) == 'string' then
            self.ename = other.ename
        end
        if typeof(other.ilp) == 'boolean' then
            self.ilp = other.ilp
        end
        if typeof(other.flp) == 'boolean' then
            self.flp = other.flp
        end
    end
    function effectTiming:clone()
        local cloned = setmetatable(timing.clone(self), effectTiming)

        cloned.ename = self.ename
        cloned.ilp = self.ilp
        cloned.flp = self.flp

        return cloned
    end
    function effectTiming:serialize()
        local data = timing.serialize(self)

        data.ename = self.ename
        data.ilp = self.ilp
        data.flp = self.flp

        return data
    end
    function effectTiming.new(source)
        local result = setmetatable(timing.new(), effectTiming)

        result.ename = ''
        result.ilp = false
        result.flp = false

        if source then
            result:load(source)
        end

        return result
    end

    return effectTiming
end


return aa()

]=],
    ["Game/Timings/FeintCue"] = [=[
local aa = function()
    local logger = a["Utility/Logger"]()
    local module = {}

    module.on = true
    module.debug = false
    module.grace = 0.15

    local ac = {
        REP_SOUND_4954198253 = true,
        REP_SOUND_5115545256 = 2,
        REP_SOUND_1241766316 = true,
    }
    local ad = {}
    local matchesFeintCue = function(track)
        local ok, cue = pcall(function()
            local knownSpeed = ac[tostring(track.Name)]

            if not knownSpeed then
                return nil
            end
            if knownSpeed ~= true and tostring(track.PlaybackSpeed) ~= tostring(knownSpeed) then
                return nil
            end

            return 'feint cue'
        end)

        return ok and cue or nil
    end

    module._is = matchesFeintCue

    local disconnectConnections = function(af)
        local connections = ad[af]

        if not connections then
            return
        end

        ad[af] = nil

        for index = 1, #connections do
            pcall(function()
                connections[index]:Disconnect()
            end)
        end
    end

    module.drop = disconnectConnections

    function module.watch(animator, sound, info, callback)
        if not (module.on and animator) then
            return
        end

        disconnectConnections(animator)

        if info and info.tag == 'Mantra' then
            return
        end

        local handlers = {}

        ad[animator] = handlers

        local startTime = os.clock()
        local fired = false
        local triggerFeint = function(reason)
            if fired or (os.clock() - startTime) < module.grace then
                return
            end
            if sound and not sound.IsPlaying then
                return
            end

            fired = true

            if module.debug then
                logger.trace('[Feint] %s feinted (%s)', tostring(animator.Name), reason)
            end

            disconnectConnections(animator)
            callback()
        end
        local success, connection = pcall(function()
            return animator.DescendantAdded:Connect(function(descendant)
                if descendant.Name == 'Feint' and descendant:IsA('Sound') then
                    local playingConn = descendant:GetPropertyChangedSignal('Playing'):Connect(function(
                    )
                        if descendant.IsPlaying then
                            triggerFeint('feint sound')
                        end
                    end)

                    handlers[#handlers + 1] = playingConn

                    return
                end

                local cue = matchesFeintCue(descendant)

                if cue then
                    triggerFeint(cue)
                end
            end)
        end)

        if success and connection then
            handlers[#handlers + 1] = connection
        end
    end
    function module.detach()
        for target in next, ad do
            disconnectConnections(target)
        end

        ad = {}
    end

    return module
end


return aa()

]=],
    ["Game/Timings/HitboxPartTiming"] = [=[
local aa = function()
    local timingBuilder = a["Menu/TimingBuilder"]()
    local logger = a["Utility/Logger"]()
    local partTiming = a["Game/Timings/PartTiming"]()
    local module = setmetatable({}, {__index = timingBuilder})

    module.__index = module

    function module:check()
        if not timingBuilder.check(self) then
            return false
        end
        if not self.partName.Value or #self.partName.Value <= 0 then
            return logger.longNotify('Please enter a valid part name.')
        end
        if self.container:index(self.partName.Value) then
            return logger.longNotify("The timing ID '%s' is already in the list.", self.partName.Value)
        end

        return true
    end
    function module:exload(config)
        self.useHitboxCFrame:SetRawValue(config.uhc)
        self.partName:SetRawValue(config.pname)
    end
    function module:reset()
        timingBuilder.reset(self)
        self.partName:SetRawValue('')
    end
    function module:cset(data)
        data.name = self.timingName.Value
        data.pname = self.partName.Value
    end
    function module:create()
        local timing = partTiming.new()

        self:cset(timing)

        return timing
    end
    function module:tide(ui)
        self.partName = ui:AddInput(nil, {
            Text = 'Part Name',
        })
    end
    function module:extra(builder)
        self.useHitboxCFrame = self.timingOnly:AddToggle(nil, {
            Text = 'Use Hitbox Rotation',
            Tooltip = 
"Use the part's own rotation for the hitbox instead of just its position.",
            Default = true,
            Callback = self:tnc(function(entry, value)
                entry.uhc = value
            end),
        })
    end
    function module.new(ae, af, ag)
        return setmetatable(timingBuilder.new(ae, af, ag), module)
    end

    return module
end


return aa()

