return function(self, timing)
	local data = Weapon.data(self.entity)
	if not data then
		return
	end

	-- Funny htibox options.
	timing.htype = Enum.PartType.Ball
	timing.fhb = false
	timing.hso = -5

	-- Fallbacks. Reset to normal.
	timing.nvfb = true
	timing.pbfb = false
	timing.ndfb = false
	timing.bfht = 0.3

	-- Prediction settings.
	timing.dp = false
	timing.pfh = true
	timing.phd = true

	-- Prediction history times.
	timing.pfht = 0.25
	timing.phds = 0.6

	if data.type == "Fist" or data.type == "Dagger" then
		timing.pbfb = true
		timing.bfht = 0.6
		timing.phds = data.type == "Dagger" and 0.6 or 0.25
		timing.pfh = false
		timing.dp = true
