        ['DeepWidowSwing'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tif not (self.track and self.entity) then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal speed = self.track.Speed\r\n\tlocal when = 0.3\r\n\r\n\tif speed >= 0.45 and speed <= 0.55 then\r\n\t\twhen = 1.050\r\n\tend\r\n\r\n\tif speed >= 0.75 and speed <= 0.85 then\r\n\t\twhen = 0.750\r\n\tend\r\n\r\n\tif speed >= 0.9 and speed <= 1.0 then\r\n\t\twhen = 0.540\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\r\n\tif self.entity.Name:match(".miniwidow") then\r\n\t\taction.hitbox = Vector3.new(25, 25, 25)\r\n\t\twhen = when / 1.1\r\n\telse\r\n\t\taction.hitbox = Vector3.new(40, 40, 40)\r\n\tend\r\n\r\n\taction._type = "Parry"\r\n\taction._when = when * 1000\r\n\taction.hso = 0\r\n\taction.name = string.format("Deep Widow Swing %.2f %.2f", speed, when)\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['DukeCrouchSlash'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "75177662439153"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    action_type = "Spell", \r\n\r\n    run = function(action)\r\n\t\taction.when = 0.8\r\n\t\taction.type = "Crouch"\r\n\t\taction.hitbox = Vector3.new(50, 25, 50)\r\n        action.offset = CFrame.new(0,0,-25);\r\n\t\taction.name = "Duke Wind Slash"\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeGolemPunch'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "75216423575082"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    action_type = "Spell", \r\n\r\n    run = function(action)\r\n\t\taction.when = 0.9\r\n\t\taction.type = "Dodge"\r\n\t\taction.hitbox = Vector3.new(50, 50, 50)\r\n        action.offset = CFrame.new(0,0,-25);\r\n\t\taction.name = "Golem Punch"\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeGolemSlam'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "112517047632505"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    action_type = "Spell", \r\n\r\n    run = function(action)\r\n\t\taction.when = 0.5\r\n\t\taction.type = "Crouch"\r\n\t\taction.hitbox = Vector3.new(50, 50, 50)\r\n\t\taction.name = "Golem Slam"\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeGolemSlam2'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "82450781977821"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    action_type = "Spell", \r\n\r\n    run = function(action)\r\n\t\taction.when = 0.65\r\n\t\taction.type = "Jump"\r\n\t\taction.hitbox = Vector3.new(50, 50, 50)\r\n\t\taction.name = "Golem Slam"\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeGrasp'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "8285321158"\r\n    },\r\n    action_type = "Spell",\r\n    default_chance = 100,\r\n\r\n    allow_block_input = false,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = false,\r\n\r\n    run = function(action)\r\n        task.wait(0.2 - Latency:get_ping());\r\n\r\n        action.name = "Duke Bomb Grab Short";\r\n        action.when = 0;\r\n        action.hitbox = Vector3.new(2000, 2000, 2000);\r\n        action.half_size_offset = true;\r\n        action.type = "Dodge";\r\n                \r\n        action:push();\r\n\r\n        local has_grab = false;\r\n        local start = tick();\r\n\r\n        while tick() - start < 1 or has_grab do\r\n            has_grab = false;\r\n            local a = workspace:FindFirstChild("Thrown")\r\n            for _, object in (a and a:GetChildren() or {}) do\r\n                if object.Name ~= "GrabPart" then continue; end\r\n\r\n                has_grab = true;\r\n                \r\n                action.name = "Duke Bomb Grab";\r\n                action.when = 0;\r\n                action.ignore_hitbox = true;\r\n                action.ignore_early_end = true;\r\n                action.half_size_offset = true;\r\n                action.type = "Dodge";\r\n\r\n                action:push();\r\n            \r\n                return action;\r\n            end;\r\n            task.wait();\r\n        end;\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeNewStomp'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n  ids = {\r\n      "105478410111896"\r\n  },\r\n  default_chance = 100,\r\n  allow_block_input = false,\r\n  allow_parry_to_roll = true,\r\n  allow_roll_to_parry = true,\r\n  allow_parry_to_block = true,\r\n\r\n  run = function(action)\r\n        local distance = self:distance();\r\n      \r\n        if defender.entity.Name:match(".theduke") then\r\n            if distance > 10 then\r\n                action.when = 1.0 \r\n            else\r\n                action.when = 0.8\r\n            end\r\n            action.name = string.format("Duke Stomp %.2f", distance);\r\n        else\r\n            if distance > 25 then\r\n                action.when = math.min(325 + distance * 13, 3000) / 1000\r\n            else\r\n                action.when = 0.65\r\n            end\r\n            action.name = string.format("Pillars of Erisia %.2f", distance);\r\n        end;\r\n      \r\n        action.hitbox = Vector3.new(40, 20, 60)\r\n        action.half_size_offset = true;\r\n        action.type = "Dodge";\r\n        action:push();\r\n\r\n        return action;\r\n  end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeStomp'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n  ids = {\r\n      "8290626574"\r\n  },\r\n  default_chance = 100,\r\n  allow_block_input = false,\r\n  allow_parry_to_roll = true,\r\n  allow_roll_to_parry = true,\r\n  allow_parry_to_block = true,\r\n\r\n  run = function(action)\r\n        local distance = self:distance();\r\n      \r\n        if defender.entity.Name:match(".theduke") then\r\n            if distance > 10 then\r\n                action.when = 1.0 \r\n            else\r\n                action.when = 0.8\r\n            end\r\n            action.name = string.format("Duke Stomp %.2f", distance);\r\n        else\r\n            action.when = 0.4\r\n            action.name = string.format("Pillars of Erisia %.2f", distance);\r\n        end;\r\n      \r\n        action.hitbox = Vector3.new(40, 20, 60)\r\n        action.half_size_offset = true;\r\n        action.type = "Dodge";\r\n        action:push();\r\n\r\n        return action;\r\n  end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeTripleKick'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "10358800338"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    action_type = "Spell", \r\n\r\n    run = function(action)\r\n\t\taction.when = 0.7\r\n\t\taction.type = "Jump"\r\n\t\taction.hitbox = Vector3.new(50, 50, 50)\r\n        action.offset = CFrame.new(0,0,-25);\r\n\t\taction.name = "Kick 1"\r\n        action:push();\r\n\r\n\t\taction.when = 1.65\r\n\t\taction.type = "Jump"\r\n\t\taction.hitbox = Vector3.new(50, 50, 50)\r\n        action.offset = CFrame.new(0,0,-25);\r\n\t\taction.name = "Kick 2"\r\n        action:push();\r\n\r\n        action.when = 2.500\r\n\t\taction.type = "Jump"\r\n\t\taction.hitbox = Vector3.new(50, 50, 50)\r\n        action.offset = CFrame.new(0,0,-25);\r\n\t\taction.name = "Kick 3"\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DukeWindBlast'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "8286153000"\r\n    },\r\n    action_type = "Spell",\r\n    default_chance = 100,\r\n\r\n    allow_block_input = false,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = false,\r\n\r\n    run = function(action)\r\n        task.wait(0.1 - Latency:get_ping());\r\n\r\n        action.name = "Duke Arrow Short";\r\n        action.when = 0;\r\n        action.hitbox = Vector3.new(100, 100, 100);\r\n        action.half_size_offset = true;\r\n        action.type = "Parry";\r\n                \r\n        action:push();\r\n\r\n        local has_blast = false;\r\n        local start = tick();\r\n\r\n        while tick() - start < 1 or has_blast do\r\n            has_blast = false;\r\n            local a = workspace:FindFirstChild("Thrown")\r\n            for _, object in (a and a:GetChildren() or {}) do\r\n                if object.Name ~= "DukeBlast" then continue; end\r\n\r\n                has_blast = true;\r\n                \r\n                action.name = "Duke Arrow";\r\n                action.when = 0;\r\n                action.ignore_hitbox = true;\r\n                action.ignore_early_end = true;\r\n                action.half_size_offset = true;\r\n                action.type = "Parry";\r\n\r\n                action:push();\r\n            \r\n                return action; \r\n            end;\r\n            task.wait();\r\n        end;\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['DynamicFlourish'] = '\r\nlocal Action = getfenv().Action\r\nlocal Weapon = getfenv().Weapon\r\n\r\nreturn function(self, timing)\r\n\tlocal data = Weapon.data(self.entity)\r\n\tif not data then\r\n\t\treturn\r\n\tend\r\n\r\n\t\r\n\ttiming.htype = Enum.PartType.Block\r\n\ttiming.fhb = false\r\n\ttiming.hso = -5\r\n\r\n\t\r\n\ttiming.nvfb = true\r\n\ttiming.pbfb = false\r\n\ttiming.ndfb = false\r\n\ttiming.bfht = 0.3\r\n\r\n\t\r\n\ttiming.dp = false\r\n\ttiming.pfh = true\r\n\ttiming.phd = true\r\n\ttiming.mto = true\r\n\r\n\t\r\n\ttiming.pfht = 0.25\r\n\ttiming.phds = 0.6\r\n\r\n\tif data.type == "Fist" or data.type == "Dagger" then\r\n\t\ttiming.pbfb = true\r\n\t\ttiming.bfht = 0.6\r\n\t\ttiming.phds = data.type == "Dagger" and 0.6 or 0.25\r\n\t\ttiming.pfh = false\r\n\t\ttiming.dp = true\r\n\tend\r\n\r\n\tif\r\n\t\tdata.type == "Sword"\r\n\t\tor data.type == "Staff"\r\n\t\tor data.type == "Twinblade"\r\n\t\tor data.type == "Spear"\r\n\t\tor data.type == "Club"\r\n\t\tor data.type == "Rifle"\r\n\t\tor data.type == "Pistol"\r\n\tthen\r\n\t\ttiming.pbfb = true\r\n\t\ttiming.bfht = 0.6\r\n\t\ttiming.phd = false\r\n\t\ttiming.ffh = false\r\n\tend\r\n\r\n\tif\r\n\t\tdata.type == "Greathammer"\r\n\t\tor data.type == "Greatcannon"\r\n\t\tor data.type == "Greatsword"\r\n\t\tor data.type == "Greataxe"\r\n\tthen\r\n\t\ttiming.phd = false\r\n\t\ttiming.ffh = false\r\n\t\ttiming.pfht = 0.5\r\n\t\ttiming.dp = false\r\n\tend\r\n\r\n\tlocal windup = nil\r\n\r\n\t\r\n\r\n\tif data.type == "Greataxe" then\r\n\t\twindup = (0.18 / self.track.Speed) + 0.100\r\n\telseif data.type == "Greathammer" then\r\n\t\twindup = (0.14 / self.track.Speed) + 0.140\r\n\telseif data.type == "Greatsword" then\r\n\t\twindup = (0.17 / self.track.Speed) + 0.050\r\n\telseif data.type == "Twinblade" then\r\n\t\twindup = (0.166 / self.track.Speed) + 0.140\r\n\telseif data.type == "Bow" then\r\n\t\twindup = (0.172 / self.track.Speed) + 0.140\r\n\telseif data.type == "Pistol" then\r\n\t\twindup = 0.500 / data.ss\r\n\telseif data.type == "Greatcannon" then\r\n\t\twindup = (0.173 / self.track.Speed) + 0.160\r\n\telseif data.type == "Dagger" then\r\n\t\twindup = (0.165 / self.track.Speed) + 0.100\r\n\telseif data.type == "Rapier" then\r\n\t\twindup = (0.163 / self.track.Speed) + 0.120\r\n\telseif data.type == "Spear" then\r\n\t\twindup = (0.135 / self.track.Speed) + 0.180\r\n\telseif data.type == "Fist" then\r\n\t\twindup = (0.160 / self.track.Speed) + 0.140\r\n\telseif data.type == "Sword" or data.type == "Staff" then\r\n\t\twindup = (0.16 / self.track.Speed) + 0.120\r\n\telseif data.type == "Club" then\r\n\t\twindup = (0.16 / self.track.Speed) + 0.150\r\n\telseif data.type == "Rifle" then\r\n\t\twindup = (0.16 / self.track.Speed) + 0.150\r\n\tend\r\n\r\n\tif not windup then\r\n\t\treturn self:notify(timing, "(%s) No windup for this weapon type.", data.type)\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\taction._when = windup * 950\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(data.length * 2.1, data.length * 2.1, data.length * 2.1)\r\n\taction.name = string.format(\r\n\t\t"(%.2f, %.2f, %.2f) (%.2f) Dynamic Weapon Flourish",\r\n\t\tdata.oss,\r\n\t\tdata.ss,\r\n\t\tself.track.Speed,\r\n\t\tdata.length\r\n\t)\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['DynamicWeapon'] = '\r\nlocal Action = getfenv().Action\r\nlocal Engine = getfenv().Engine\r\nlocal PartTiming = getfenv().PartTiming\r\nlocal ProjectileTracker = getfenv().ProjectileTracker\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\nlocal Weapon = getfenv().Weapon\r\nlocal WeaponRun = getfenv().WeaponRun\r\n\r\nlocal function windup(knd, spd, ss, name)\r\n\tif knd == "Greataxe" then\r\n\t\tif spd ~= 1.0 then\r\n\t\t\treturn (0.171 / spd) + 0.120\r\n\t\tend\r\n\t\treturn (0.171 / spd) + (0.250 / ss)\r\n\tend\r\n\r\n\tif knd == "Greathammer" then\r\n\t\tif spd ~= 1.0 then\r\n\t\t\treturn (0.150 / spd) + 0.200\r\n\t\tend\r\n\t\treturn (0.150 / spd) + (0.250 / ss)\r\n\tend\r\n\r\n\tif knd == "Greatcannon" then\r\n\t\tif spd ~= 1.0 then\r\n\t\t\treturn (0.155 / spd) + 0.160\r\n\t\tend\r\n\t\treturn (0.155 / spd) + 0.300\r\n\tend\r\n\r\n\tif knd == "Rapier" then\r\n\t\treturn (0.155 / spd) + 0.120\r\n\tend\r\n\tif knd == "Rifle" then\r\n\t\treturn (0.174 / spd) + 0.125\r\n\tend\r\n\tif knd == "Club" then\r\n\t\treturn (0.180 / spd) + 0.100\r\n\tend\r\n\tif knd == "Twinblade" then\r\n\t\treturn (0.200 / spd) + 0.050\r\n\tend\r\n\tif knd == "Spear" then\r\n\t\treturn (0.150 / spd) + 0.100\r\n\tend\r\n\tif knd == "Greatsword" then\r\n\t\treturn (0.158 / spd) + 0.150\r\n\tend\r\n\tif knd == "Fist" then\r\n\t\treturn (0.140 / spd) + 0.130\r\n\tend\r\n\tif knd == "Dagger" then\r\n\t\treturn (0.200 / spd) + 0.075\r\n\tend\r\n\tif knd == "Sword" then\r\n\t\treturn (0.200 / spd) + 0.100\r\n\tend\r\n\tif knd == "Staff" then\r\n\t\treturn 0.350\r\n\tend\r\n\tif knd == "Pistol" and not name:match("Shot") then\r\n\t\treturn 0.350 / ss\r\n\tend\r\n\r\n\treturn nil\r\nend\r\n\r\nlocal function facingPass(timing, hold)\r\n\ttiming.phd = false\r\n\ttiming.duih = false\r\n\ttiming.ffh = false\r\n\ttiming.pfht = hold\r\nend\r\n\r\nlocal function evengarde(self, timing)\r\n\tif _G.EvengardeSwingGuard and (os.clock() - _G.EvengardeSwingGuard) < 4 then\r\n\t\treturn\r\n\tend\r\n\r\n\t_G.EvengardeSwingGuard = os.clock()\r\n\r\n\ttiming.ndfb = true\r\n\ttiming.bfht = 0.15\r\n\r\n\tTaskSpawner.spawn("DynamicWeapon_Evengarde", function()\r\n\t\ttask.wait(0.4)\r\n\r\n\t\trepeat\r\n\t\t\tlocal act = Action.new()\r\n\t\t\tact._when = 0\r\n\t\t\tact._type = "Parry"\r\n\t\t\tact.hitbox = Vector3.new(55, 55, 55)\r\n\t\t\tact.name = "Evengarde Sword Swing"\r\n\r\n\t\t\tself:action(timing, act)\r\n\r\n\t\t\ttask.wait(0.01)\r\n\t\tuntil not self:live(timing)\r\n\tend)\r\nend\r\n\r\nlocal function scrapsinger(self, timing)\r\n\tTaskSpawner.spawn("DynamicWeapon_ScrapsingerBullet", function()\r\n\t\tlocal trk = ProjectileTracker.new(function(candidate)\r\n\t\t\treturn candidate.Name == "ScrapsingerBullet_" .. self.entity.Name\r\n\t\tend)\r\n\r\n\t\tlocal blt = trk:wait(function()\r\n\t\t\treturn self:live(timing)\r\n\t\tend)\r\n\t\tif not blt then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal act = Action.new()\r\n\t\tact._when = 0\r\n\t\tact._type = "Parry"\r\n\t\tact.name = "Scrapsinger Bullet"\r\n\r\n\t\tlocal pt = PartTiming.new()\r\n\t\tpt.name = "ScrapsingerBulletProjectile"\r\n\t\tpt.uhc = true\r\n\t\tpt.duih = true\r\n\t\tpt.fhb = true\r\n\t\tpt.hitbox = Vector3.new(20, 35, 15)\r\n\t\tpt.actions:push(act)\r\n\r\n\t\tEngine.part(blt, pt)\r\n\tend)\r\nend\r\n\r\nlocal function animId(self)\r\n\tlocal trk = self.track\r\n\tlocal anim = trk and trk.Animation\r\n\r\n\treturn anim and tostring(anim.AnimationId) or ""\r\nend\r\n\r\nlocal function heavyRunning(self, timing, d)\r\n\tlocal knd = d.type\r\n\tlocal hrp = self.entity:FindFirstChild("HumanoidRootPart")\r\n\tlocal vel = hrp and Vector3.new(hrp.AssemblyLinearVelocity.X, 0, hrp.AssemblyLinearVelocity.Z).Magnitude or 0\r\n\r\n\tif vel >= 7 and WeaponRun then\r\n\t\treturn WeaponRun.run(self, timing, d)\r\n\tend\r\n\r\n\tlocal spd = self.track.Speed\r\n\tlocal box = Vector3.new(d.length * 2.1, d.length * 2.1, d.length * 2.1)\r\n\tlocal windup = 0\r\n\r\n\tif knd == "Greataxe" then\r\n\t\tif spd ~= 1.0 then\r\n\t\t\twindup = (0.171 / spd) + 0.120\r\n\t\telse\r\n\t\t\twindup = (0.171 / spd) + (0.250 / d.ss)\r\n\t\tend\r\n\telseif knd == "Greathammer" then\r\n\t\tif spd ~= 1.0 then\r\n\t\t\twindup = (0.150 / spd) + 0.150\r\n\t\telse\r\n\t\t\twindup = (0.150 / spd) + (0.250 / d.ss)\r\n\t\tend\r\n\tend\r\n\r\n\tif windup <= 0 then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal act = Action.new()\r\n\tact._when = windup * 1000\r\n\tact._type = "Parry"\r\n\tact.hitbox = box\r\n\tact.name = string.format("(%.2f, %.1f) Heavy %s M1", windup, d.length, knd)\r\n\r\n\treturn self:action(timing, act)\r\nend\r\n\r\nreturn function(self, timing)\r\n\tif self.entity.Name:match("evengarde") and timing.name:match("1SwordSwing[12]") then\r\n\t\treturn evengarde(self, timing)\r\n\tend\r\n\r\n\tlocal d = Weapon.data(self.entity)\r\n\tif not d then\r\n\t\treturn\r\n\tend\r\n\r\n\tif not self.entity:FindFirstChild("HumanoidRootPart") then\r\n\t\treturn\r\n\tend\r\n\r\n\ttiming.htype = Enum.PartType.Ball\r\n\ttiming.fhb = false\r\n\ttiming.hso = -5\r\n\r\n\ttiming.nvfb = true\r\n\ttiming.ndfb = false\r\n\ttiming.bfht = 0.3\r\n\r\n\ttiming.dp = false\r\n\ttiming.pfh = true\r\n\ttiming.phd = true\r\n\ttiming.pfht = 0.25\r\n\ttiming.phds = 0.6\r\n\ttiming.mto = true\r\n\r\n\tlocal knd = d.type\r\n\r\n\tif knd == "Fist" or knd == "Dagger" then\r\n\t\tfacingPass(timing, 0.5)\r\n\telseif\r\n\t\tknd == "Sword" or knd == "Staff" or knd == "Twinblade" or knd == "Spear"\r\n\t\tor knd == "Club" or knd == "Rifle" or knd == "Pistol"\r\n\tthen\r\n\t\ttiming.bfht = 0.3\r\n\t\tfacingPass(timing, 0.7)\r\n\telseif\r\n\t\tknd == "Greathammer" or knd == "Greatcannon"\r\n\t\tor knd == "Greatsword" or knd == "Greataxe"\r\n\tthen\r\n\t\tfacingPass(timing, 0.5)\r\n\tend\r\n\r\n\tif animId(self):match("5067090007") and (knd == "Greataxe" or knd == "Greathammer") then\r\n\t\treturn heavyRunning(self, timing, d)\r\n\tend\r\n\r\n\tlocal spd = self.track.Speed\r\n\tlocal box = Vector3.new(d.length * 2.1, d.length * 2.1, d.length * 2.1)\r\n\r\n\tif self.entity.Name:lower():match("titus") and knd == "Fist" then\r\n\t\tlocal a = os.clock() + 5\r\n\t\trepeat\r\n\t\t\tif not self:live(timing) or os.clock() >= a then return end\r\n\t\t\ttask.wait()\r\n\t\tuntil self.track.Speed > 0\r\n\r\n\t\tlocal set = self.track.Speed + 0.2\r\n\r\n\t\tself:notify(timing, "Titus M1 Windup")\r\n\r\n\t\tlocal act = Action.new()\r\n\t\tact._when = (565 * 0.76) / set\r\n\t\tact._type = "Parry"\r\n\t\tact.hitbox = box\r\n\t\tact.name = string.format("(%.2f) Titus M1 Windup", set)\r\n\r\n\t\treturn self:action(timing, act)\r\n\tend\r\n\r\n\tif (knd == "Pistol" and timing.name:match("Shot")) then\r\n\t\tlocal op = spd\r\n\t\tlocal a = os.clock() + 5\r\n\r\n\t\trepeat\r\n\t\t\tif not self:live(timing) or os.clock() >= a then return end\r\n\t\t\ttask.wait()\r\n\t\tuntil self.track.Speed ~= op\r\n\r\n\t\tspd = self.track.Speed\r\n\tend\r\n\r\n\tlocal w\r\n\r\n\tif knd == "Bow" then\r\n\t\tlocal hw = Weapon.handWeapon(self.entity)\r\n\t\tlocal tip = hw and hw:FindFirstChild("TipAttachment")\r\n\r\n\t\tif tip then\r\n\t\t\tlocal rdy = nil\r\n\r\n\t\t\twhile task.wait() and self.track.IsPlaying do\r\n\t\t\t\trdy = tip:FindFirstChild("Spark")\r\n\r\n\t\t\t\tif rdy then\r\n\t\t\t\t\tbreak\r\n\t\t\t\tend\r\n\t\t\tend\r\n\r\n\t\t\tif not rdy then\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\t\tend\r\n\r\n\t\tw = 0.1\r\n\telseif (knd == "Pistol" and timing.name:match("Shot")) then\r\n\t\tw = spd == 0 and 0.100 or (0.075 / spd)\r\n\telseif knd == "Rifle" and animId(self):find("9928485641") then\r\n\t\tw = spd == 0 and 0.100 or (spd * 0.55)\r\n\telse\r\n\t\tw = windup(knd, spd, d.ss, timing.name)\r\n\tend\r\n\r\n\tif not w then\r\n\t\treturn self:notify(timing, "(%s) No windup for this weapon type.", knd)\r\n\tend\r\n\r\n\tif knd == "Pistol" then\r\n\t\tscrapsinger(self, timing)\r\n\tend\r\n\r\n\tlocal act = Action.new()\r\n\tact._when = w * 950\r\n\tact._type = "Parry"\r\n\tact.hitbox = box\r\n\tact.name = string.format(\r\n\t\t"(%.2f, %.2f, %.2f) (%.2f) Dynamic Weapon Swing",\r\n\t\td.oss,\r\n\t\td.ss,\r\n\t\tself.track.Speed,\r\n\t\td.length\r\n\t)\r\n\r\n\treturn self:action(timing, act)\r\nend\r\n',
        ['DynamicWeaponAerial'] = '\r\nlocal Action = getfenv().Action\r\nlocal Weapon = getfenv().Weapon\r\n\r\nreturn function(self, timing)\r\n\tlocal data = Weapon.data(self.entity)\r\n\tif not data then\r\n\t\treturn\r\n\tend\r\n\r\n\ttiming.iae = false\r\n\ttiming.ffh = false\r\n\ttiming.dp = false\r\n\ttiming.pfht = 0.15\r\n\ttiming.phd = false\r\n\ttiming.pfh = true\r\n\ttiming.nvfb = true\r\n\ttiming.hso = 0\r\n\ttiming.mto = true\r\n\r\n\tlocal windup = nil\r\n\tlocal ispeed = self.track.Speed\r\n\r\n\tif data.type == "Dagger" then\r\n\t\twindup = (0.165 / self.track.Speed) + 0.100\r\n\telseif data.type == "Greataxe" then\r\n\t\twindup = (0.168 / self.track.Speed) + 0.125\r\n\telseif data.type == "Twinblade" then\r\n\t\twindup = (0.160 / self.track.Speed) + 0.100\r\n\telseif data.type == "Bow" then\r\n\t\twindup = (0.145 / self.track.Speed) + 0.170\r\n\telseif data.type == "Club" then\r\n\t\twindup = (0.163 / self.track.Speed) + 0.140\r\n\telseif data.type == "Pistol" then\r\n\t\twindup = 0.500 / data.ss\r\n\telseif data.type == "Rifle" and not timing.name:match("Fist") then\r\n\t\tlocal a = os.clock() + 5\r\n\t\trepeat\r\n\t\t\tif not self:live(timing) or os.clock() >= a then return end\r\n\t\t\ttask.wait()\r\n\t\tuntil self.track.Speed ~= ispeed\r\n\r\n\t\twindup = (0.300 / self.track.Speed)\r\n\r\n\t\tif self.track.Speed == 0.0 then\r\n\t\t\twindup = 0.100\r\n\t\tend\r\n\telseif data.type == "Rifle" then\r\n\t\twindup = (0.199 / self.track.Speed) + 0.100\r\n\telseif data.type == "Greatsword" then\r\n\t\twindup = (0.166 / self.track.Speed) + 0.160\r\n\telseif data.type == "Rapier" then\r\n\t\twindup = (0.225 / self.track.Speed) + 0.080\r\n\telseif data.type == "Greatcannon" then\r\n\t\twindup = (0.163 / self.track.Speed) + 0.183\r\n\telseif data.type == "Greathammer" then\r\n\t\twindup = (0.15 / self.track.Speed) + 0.170\r\n\telseif data.type == "Fist" then\r\n\t\twindup = (0.160 / self.track.Speed) + 0.130\r\n\telseif data.type == "Sword" or data.type == "Staff" then\r\n\t\twindup = (0.160 / self.track.Speed) + 0.100\r\n\telseif data.type == "Spear" then\r\n\t\twindup = (0.150 / self.track.Speed) + 0.170\r\n\tend\r\n\r\n\tif not windup then\r\n\t\treturn self:notify(timing, "(%s) No windup for this weapon type.", data.type)\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\taction._when = windup * 950\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(data.length * 2.0, data.length * 3.5, data.length * 3.0)\r\n\taction.name = string.format(\r\n\t\t"(%.2f, %.2f, %.2f) (%.2f) Dynamic Weapon Aerial",\r\n\t\tdata.oss,\r\n\t\tdata.ss,\r\n\t\tself.track.Speed,\r\n\t\tdata.length\r\n\t)\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['DynamicWeaponRun'] = '\r\nlocal a = getfenv().Weapon\r\nlocal b = getfenv().WeaponRun\r\n\r\nreturn function(c, d)\r\n    local e = a.data(c.entity)\r\n    if e then return b.run(c, d, e) end\r\nend\r\n',
        ['DynamicWeaponUpper'] = '\r\nlocal Action = getfenv().Action\r\nlocal Weapon = getfenv().Weapon\r\n\r\nreturn function(self, timing)\r\n\tlocal data = Weapon.data(self.entity)\r\n\tif not data then\r\n\t\treturn\r\n\tend\r\n\r\n\ttiming.ffh = false\r\n\ttiming.phd = false\r\n\ttiming.nvfb = true\r\n\ttiming.pfht = 0.25\r\n\ttiming.phds = 1.0\r\n\ttiming.hso = 0\r\n\ttiming.mto = true\r\n\r\n\tlocal windup = nil\r\n\r\n\tif data.type == "Dagger" then\r\n\t\twindup = (0.166 / self.track.Speed) + 0.120\r\n\telseif data.type == "Greataxe" then\r\n\t\twindup = (0.141 / self.track.Speed) + 0.100\r\n\telseif data.type == "Greathammer" then\r\n\t\twindup = (0.150 / self.track.Speed) + 0.100\r\n\telseif data.type == "Greatsword" then\r\n\t\twindup = (0.157 / self.track.Speed) + 0.100\r\n\telseif data.type == "Greatcannon" then\r\n\t\twindup = (0.166 / self.track.Speed) + 0.100\r\n\telseif data.type == "Twinblade" then\r\n\t\twindup = (0.163 / self.track.Speed) + 0.130\r\n\telseif data.type == "Bow" then\r\n\t\twindup = (0.150 / self.track.Speed) + 0.140\r\n\telseif data.type == "Club" then\r\n\t\twindup = (0.166 / self.track.Speed) + 0.140\r\n\telseif data.type == "Pistol" then\r\n\t\tlocal a = os.clock() + 5\r\n\t\trepeat\r\n\t\t\tif not self:live(timing) or os.clock() >= a then return end\r\n\t\t\ttask.wait()\r\n\t\tuntil self.track.Speed >= 0.1\r\n\r\n\t\twindup = (0.166 / self.track.Speed) + 0.150\r\n\telseif data.type == "Rifle" then\r\n\t\twindup = (0.159 / self.track.Speed) + 0.140\r\n\telseif data.type == "Rapier" then\r\n\t\twindup = (0.181 / self.track.Speed) + 0.130\r\n\telseif data.type == "Fist" then\r\n\t\twindup = (0.150 / self.track.Speed) + 0.120\r\n\telseif data.type == "Sword" or data.type == "Staff" then\r\n\t\twindup = (0.150 / self.track.Speed) + 0.100\r\n\telseif data.type == "Spear" then\r\n\t\twindup = (0.163 / self.track.Speed) + 0.100\r\n\t\twindup = windup + (0.050 / data.ss)\r\n\tend\r\n\r\n\tif not windup then\r\n\t\treturn self:notify(timing, "(%s) No windup for this weapon type.", data.type)\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\taction._when = windup * 950\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(data.length * 2, data.length * 2, data.length * 2.2)\r\n\taction.name = string.format(\r\n\t\t"(%.2f, %.2f, %.2f) (%.2f) Dynamic Weapon Upper",\r\n\t\tdata.oss,\r\n\t\tdata.ss,\r\n\t\tself.track.Speed,\r\n\t\tdata.length\r\n\t)\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['ElderPrimaSixStomp'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n\tids = { "82589408775991" },\r\n\tdefault_chance = 100,\r\n\tallow_block_input = true,\r\n\tallow_parry_to_roll = true,\r\n\taction_type = "Undefined",\r\n\r\n\trun = function(action)\r\n\t\tlocal timings = { 0.550, 1.000, 1.450, 1.800, 2.150, 2.550 } \r\n\r\n\t\tlocal humanoid = defender.entity:FindFirstChildOfClass("Humanoid")\r\n\t\tif not humanoid then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal halfhp = humanoid.Health <= (humanoid.MaxHealth / 2)\r\n\r\n\t\tfor idx = 1, 6 do\r\n\t\t\tlocal when = timings[idx]\r\n\r\n\t\t\tif halfhp then\r\n\t\t\t\twhen = when / 1.25\r\n\t\t\tend\r\n\r\n\t\t\taction.when = when\r\n\t\t\taction.type = "Parry"\r\n\t\t\taction.hitbox = Vector3.new(100, 250, 100)\r\n\t\t\taction.name = string.format("(%.2f) Primadon SixStomp %i", track.Speed, idx)\r\n\t\t\taction:push()\r\n\t\tend\r\n\r\n\t\treturn action\r\n\tend,\r\n}\r\n\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['ElderPrimadonHandSlam'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n\tids = { "139012331361882" },\r\n\tdefault_chance = 100,\r\n\tallow_block_input = true,\r\n\tallow_parry_to_roll = true,\r\n\taction_type = "Undefined",\r\n\r\n\trun = function(action)\r\n\t\tlocal when = ((1200 * 1.21) / track.Speed) / 1000\r\n\t\taction.when = when\r\n\t\taction.type = "Dodge"\r\n\t\taction.hitbox = Vector3.new(80, 250, 140)\r\n\t\taction.name = string.format("(%.2f) Dynamic Primadon Timing", track.Speed)\r\n\t\taction:push()\r\n\r\n\t\treturn action\r\n\tend,\r\n}\r\n\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['ElderPrimadonStomp'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = { "122173613929787" },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    action_type = "Undefined",\r\n\r\n    run = function(action)\r\n        action.when = ((750 * 1.21) / track.Speed) / 1000\r\n        action.type = "Parry"\r\n        action.hitbox = Vector3.new(80, 250, 140)\r\n        action.name = string.format("(%.2f) Dynamic Primadon Timing", track.Speed)\r\n        action:push()\r\n        return action\r\n    end,\r\n}\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['ElderPrimadonUltimateStomp'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = { "82315723491864" },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    action_type = "Undefined",\r\n\r\n    run = function(action)\r\n        action.when = ((2130 * 1.21) / track.Speed) / 1000\r\n        action.type = "Parry"\r\n        action.hitbox = Vector3.new(100, 250, 100)\r\n        action.name = string.format("(%.2f) Dynamic Primadon Timing", track.Speed)\r\n        action:push()\r\n        return action\r\n    end,\r\n}\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['Electrocarve'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\ttiming.ffh = true\r\n\ttiming.fhb = true\r\n\ttiming.hitbox = Vector3.new(14, 14, 14)\r\n\r\n\ttiming.rpue = true\r\n\ttiming._rpd = 100\r\n\ttiming._rsd = 300\r\n\ttiming.iae = true\r\n\ttiming.ieae = true\r\n\ttiming.mat = 2000\r\n\r\n\tlocal rpact = Action.new()\r\n\trpact._type = "Parry"\r\n\trpact.hitbox = Vector3.new(14, 14, 14)\r\n\trpact.name = "Repeat Parry"\r\n\r\n\ttiming.rpact = rpact\r\nend\r\n',
        ['EnforcerPullStart'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "7271659917"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = false,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        if not (aztup and aztup.flags and aztup.flags.no_enforcer_pull) then\r\n            action.when = 0.4;\r\n            action.type = "Dodge";\r\n            action.offset = CFrame.new();\r\n            action.hitbox = Vector3.new(100, 100, 100);\r\n    \r\n            action:push();\r\n        end;\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['EnforcerSpin'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "7019018522"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = false,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.3;\r\n        action.offset = CFrame.new();\r\n        action.hitbox = Vector3.new(16,20,16);\r\n\r\n        action:push();\r\n\r\n        action.when = 0.3;\r\n        action.offset = CFrame.new();\r\n        action.hitbox = Vector3.new(16,20,16);\r\n        action.type = "RPUE Parry";\r\n        action.condition = function()\r\n            return self:is_playing() and defender.entity.Parent;\r\n        end;\r\n\r\n        action.wait = function()\r\n            task.wait(Latency:get_ping());\r\n        end\r\n\r\n        action.should = function()\r\n            return defender:in_hitbox(Vector3.new(16,20,16), CFrame.new(), true);\r\n        end;\r\n\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['EthironBeam'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tlocal hrp = self.entity:FindFirstChild("HumanoidRootPart")\r\n\tif not hrp then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal rarm3 = self.entity:FindFirstChild("RArm3")\r\n\tif not rarm3 then\r\n\t\treturn\r\n\tend\r\n\r\n\tif rarm3:WaitForChild("Attach", 0.1) then\r\n\t\t\r\n\t\t\r\n\t\t\r\n\t\t\r\n\t\ttiming.cit = true\r\n\t\ttiming.mat = 3000\r\n\t\ttiming.fhb = false\r\n\t\ttiming.ieae = true\r\n\t\ttiming.iae = true\r\n\t\ttiming.rpue = true\r\n\t\ttiming.duih = false\r\n\t\ttiming.imdd = 0\r\n\t\ttiming.imxd = 1000\r\n\t\ttiming._rsd = 800\r\n\t\ttiming._rpd = 150\r\n\r\n\t\treturn\r\n\tend\r\n\r\n\t\r\n\tlocal action = Action.new()\r\n\taction._when = 1400\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(800, 800, 800)\r\n\taction.name = "Ethiron Blind Timing"\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['EthironPointSpikes'] = "\r\nlocal a = getfenv().Action\r\n\r\nreturn function(b, c)\r\n    local d = game:GetService('Players').LocalPlayer.Character\r\n    local e = d and d:FindFirstChild('HumanoidRootPart')\r\n    local f = b.data and b.data.points\r\n    if not e or type(f) ~= 'table' then return end\r\n    for _, g in pairs(f) do\r\n        if typeof(g.pos) == 'Vector3' and (g.pos - e.Position).Magnitude < 20 then\r\n            local h = a.new()\r\n            h._type, h._when, h.ihbc = 'Dodge', 600, true\r\n            h.name = 'Ethiron Point Spikes'\r\n            return b:action(c, h)\r\n        end\r\n    end\r\nend\r\n",
        ['FerrymanTeleport'] = '\r\nlocal Action = getfenv().Action\r\nlocal players = getfenv().players\r\n\r\nlocal teleportedAt = tick()\r\nlocal firstAnim = tick()\r\n\r\nreturn function(self, timing)\r\n\tlocal entity = self.entity\r\n\tif not entity then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\taction._type = "Parry"\r\n\r\n\tlocal target = entity:FindFirstChild("Target")\r\n\r\n\tif not target then\r\n\t\tlocal player = players:GetPlayerFromCharacter(entity)\r\n\t\tlocal backpack = player and player:FindFirstChild("Backpack")\r\n\t\tlocal mantra = backpack and backpack:FindFirstChild("Mantra:StrikeWind{{Wind Passage}}")\r\n\r\n\t\tif not mantra then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\taction.name = "Wind Passage"\r\n\t\taction.hitbox = Vector3.new(30, 30, 100)\r\n\t\taction._when = 410\r\n\r\n\t\treturn self:action(timing, action)\r\n\tend\r\n\r\n\tlocal lp = players.LocalPlayer\r\n\tif target.Value ~= (lp and lp.Character) then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal hum = entity:FindFirstChild("Humanoid")\r\n\tif not hum or hum.Health <= 0 then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal hp = (hum.Health / hum.MaxHealth) * 100\r\n\taction.ihbc = true\r\n\r\n\tif hp >= 50 then\r\n\t\tif tick() - teleportedAt > 2 then\r\n\t\t\tif tick() - firstAnim > 3 then\r\n\t\t\t\tfirstAnim = tick()\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\r\n\t\t\tteleportedAt = tick()\r\n\t\t\taction._when = 800\r\n\t\t\taction.name = string.format("Ferryman Teleport [1, %i]", math.round(hp))\r\n\r\n\t\t\treturn self:action(timing, action)\r\n\t\telse\r\n\t\t\tteleportedAt = tick()\r\n\t\t\taction._when = 200\r\n\t\t\taction.name = string.format("Ferryman Teleport [2, %i]", math.round(hp))\r\n\r\n\t\t\treturn self:action(timing, action)\r\n\t\tend\r\n\telse\r\n\t\tif tick() - teleportedAt > 2 then\r\n\t\t\tif tick() - firstAnim > 3 then\r\n\t\t\t\tfirstAnim = tick()\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\r\n\t\t\tteleportedAt = tick()\r\n\t\t\taction._when = 800\r\n\t\t\taction.name = string.format("Ferryman Teleport [3, %i]", math.round(hp))\r\n\r\n\t\t\treturn self:action(timing, action)\r\n\t\telse\r\n\t\t\tteleportedAt = tick()\r\n\t\t\taction._when = 100\r\n\t\t\taction.name = string.format("Ferryman Teleport [4, %i]", math.round(hp))\r\n\r\n\t\t\treturn self:action(timing, action)\r\n\t\tend\r\n\tend\r\nend\r\n',
        ['GigamedShock'] = '\r\nlocal Action = getfenv().Action\r\n\r\nlocal function who(e)\r\n\tif not e then\r\n\t\treturn nil, nil\r\n\tend\r\n\r\n\tlocal r = e:FindFirstChild("HumanoidRootPart")\r\n\tlocal m = (r and r.Parent) or e\r\n\r\n\treturn m:GetAttribute("MOB_rich_name"), m.Name\r\nend\r\n\r\nreturn function(self, timing)\r\n\tlocal rich, model = who(self.entity)\r\n\r\n\tlocal id = string.lower(tostring(rich or "") .. " " .. tostring(model or ""))\r\n\r\n\tif not id:find("gigamed", 1, true) then\r\n\t\treturn self:notify(timing, "Not a Gigamed (%s).", tostring(rich or model or "unnamed"))\r\n\tend\r\n\r\n\tlocal king = id:find("king", 1, true) ~= nil\r\n\r\n\tlocal action = Action.new()\r\n\r\n\taction._when = 200\r\n\taction._type = "Dodge"\r\n\taction.hitbox = king and Vector3.new(60, 60, 60) or Vector3.new(25, 25, 25)\r\n\taction.fhb = false\r\n\taction.hso = 0\r\n\taction.bfht = 0.3\r\n\taction.name = king and "King Gigamed Shock" or "Gigamed Shock"\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['GolemBeam'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tlocal entity = self.entity\r\n\tif not entity then\r\n\t\treturn\r\n\tend\r\n\r\n\tif not workspace:FindFirstChild("Thrown") then\r\n\t\treturn\r\n\tend\r\n\r\n\tif entity.Name:match("prime") then\r\n\t\treturn self:notify(timing, "Prime Golem beam, not handled.")\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\r\n\taction._when = 2300\r\n\taction._type = "Dodge"\r\n\taction.hitbox = Vector3.new(40, 200, 200)\r\n\taction.name = "Dynamic Beam Timing"\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['GolemLaserFire'] = "\r\nlocal a = getfenv().Action\r\n\r\nreturn function(b, c)\r\n    local d = game:GetService('Players').LocalPlayer.Character\r\n    local e = d and d:FindFirstChild('HumanoidRootPart')\r\n    local f = b.data or {}\r\n    if not e or not f.mob or typeof(f.aimPos) ~= 'Vector3' then return end\r\n    local g = f.mob:FindFirstChild('Target')\r\n    if (e.Position - f.aimPos).Magnitude > 30 or g and g.Value ~= d then return end\r\n    local h = a.new()\r\n    h._type, h._when, h.ihbc = 'Dodge', 200, true\r\n    h.name = 'Golem Laser Fire'\r\n    return b:action(c, h)\r\nend\r\n",
        ['GolemSpin'] = '\r\nlocal Action = getfenv().Action\r\nlocal Latency = getfenv().Latency\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\n\r\nlocal function beat()\r\n\tlocal action = Action.new()\r\n\r\n\taction._when = 0\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(25, 49, 25)\r\n\taction.fhb = false\r\n\taction.hso = 0\r\n\taction.bfht = 0.3\r\n\taction.ibfc = false\r\n\taction.iapf = false\r\n\taction.idf = false\r\n\taction.ihp = false\r\n\taction.nbfb = false\r\n\taction.name = "Golem Spin"\r\n\r\n\treturn action\r\nend\r\n\r\nreturn function(self, timing)\r\n\r\n\ttiming.rpue = false\r\n\r\n\tTaskSpawner.spawn("GolemSpin", function()\r\n\t\tlocal lag = (Latency.rdelay() or 0) + (Latency.sdelay() or 0)\r\n\t\tlocal wait = (3.6 - lag) - (os.clock() - self.start)\r\n\r\n\t\tif wait > 0 then\r\n\t\t\ttask.wait(wait)\r\n\t\tend\r\n\r\n\t\tself:notify(timing, "Repeat parry armed.")\r\n\r\n\t\twhile self:live(timing) do\r\n\t\t\tself:action(timing, beat())\r\n\t\t\ttask.wait(math.max(0.15 - lag, 0))\r\n\t\tend\r\n\tend)\r\nend\r\n',
        ['GrandJavelin'] = '\r\nlocal Action = getfenv().Action\r\nlocal Hitbox = getfenv().Hitbox\r\nlocal Latency = getfenv().Latency\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\n\r\nreturn function(self, timing)\r\n\tlocal entity = self.entity\r\n\tif not entity then\r\n\t\treturn\r\n\tend\r\n\r\n\tTaskSpawner.spawn("GrandJavelin", function()\r\n\t\tif Logger then\r\n\t\t\tLogger.notify("Grand Javelin detected")\r\n\t\tend\r\n\r\n\t\ttask.wait(math.max(0, 0.4 - (Latency.rtt() or 0)))\r\n\t\tif not self:live(timing) then return end\r\n\r\n\t\tlocal action = Action.new()\r\n\t\taction._type = "Parry"\r\n\t\taction.name = "Grand Javelin"\r\n\t\taction._when = 0\r\n\t\taction.hso = -15\r\n\t\taction.fhb = false\r\n\t\taction.duih = true\r\n\t\taction.hitbox = Vector3.new(15, 20, 30)\r\n\t\tself:action(timing, action)\r\n\r\n\t\tif not Hitbox then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal start = tick()\r\n\t\tlocal hasJavelin = false\r\n\r\n\t\trepeat\r\n\t\t\tif not self:live(timing) then return end\r\n\t\t\thasJavelin = false\r\n\r\n\t\t\tlocal thrown = workspace:FindFirstChild("Thrown")\r\n\t\t\tif thrown then\r\n\t\t\t\tfor _, object in thrown:GetChildren() do\r\n\t\t\t\t\tif object.Name == "SpearPart" then\r\n\t\t\t\t\t\thasJavelin = true\r\n\r\n\t\t\t\t\t\tif Hitbox.test(object, Vector3.new(10, 10, 80), { cframe = object.CFrame, shift = -40 }) then\r\n\t\t\t\t\t\t\tlocal hit = Action.new()\r\n\t\t\t\t\t\t\thit._type = "Parry"\r\n\t\t\t\t\t\t\thit.name = "Grand Javelin"\r\n\t\t\t\t\t\t\thit._when = 0\r\n\t\t\t\t\t\t\thit.ihbc = true\r\n\t\t\t\t\t\t\tself:action(timing, hit)\r\n\r\n\t\t\t\t\t\t\treturn\r\n\t\t\t\t\t\tend\r\n\t\t\t\t\tend\r\n\t\t\t\tend\r\n\t\t\tend\r\n\r\n\t\t\ttask.wait()\r\n\t\tuntil tick() - start >= 5 or ((tick() - start >= 1) and not hasJavelin)\r\n\tend)\r\nend\r\n',
        ['HitTendril'] = '\r\nlocal Action = getfenv().Action\r\nlocal Finder = getfenv().Finder\r\n\r\nreturn function(self, timing)\r\n\tlocal chaser = Finder.entity(".chaser")\r\n\tif not chaser then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal hrp = chaser:FindFirstChild("HumanoidRootPart")\r\n\tif not hrp then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal part = self.part\r\n\tlocal hasTelegraph = (part and part.Parent == hrp) or hrp:FindFirstChild("TelegraphAttach") ~= nil\r\n\r\n\tlocal action = Action.new()\r\n\taction.ihbc = true\r\n\taction.nbfb = true\r\n\r\n\tif hasTelegraph then\r\n\t\taction._when = 585\r\n\t\taction._type = "Dodge"\r\n\t\taction.name = "Hit Tendril Dodge Timing"\r\n\telse\r\n\t\taction._when = 600\r\n\t\taction._type = "Parry"\r\n\t\taction.name = "Hit Tendril Parry Timing"\r\n\tend\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['Judgment'] = '\r\nlocal Action = getfenv().Action\r\n\r\n\r\n\r\nlocal function hasEffect(name)\r\n\tlocal er = game:GetService("ReplicatedStorage"):FindFirstChild("EffectReplicator")\r\n\r\n\tif not er then\r\n\t\treturn false\r\n\tend\r\n\r\n\tlocal ok, em = pcall(require, er)\r\n\r\n\tif not (ok and type(em) == "table") then\r\n\t\treturn false\r\n\tend\r\n\r\n\t\r\n\t\r\n\tlocal list = em.Effects\r\n\r\n\tif type(list) ~= "table" and type(em.GetEffects) == "function" then\r\n\t\tlocal got, fx = pcall(em.GetEffects, em)\r\n\r\n\t\tif got then\r\n\t\t\tlist = fx\r\n\t\tend\r\n\tend\r\n\r\n\tif type(list) ~= "table" then\r\n\t\treturn false\r\n\tend\r\n\r\n\tfor _, e in next, list do\r\n\t\tif type(e) == "table" then\r\n\t\t\tlocal cls = e.Class or (e.index and e.index.Class)\r\n\r\n\t\t\tif cls == name then\r\n\t\t\t\treturn true\r\n\t\t\tend\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\nreturn function(self, timing)\r\n\ttiming.iae = true\r\n\ttiming.ieae = true\r\n\ttiming.mat = 1000\r\n\r\n\t\r\n\t\r\n\t\r\n\ttask.spawn(function()\r\n\t\ttask.wait(0.2)\r\n\r\n\t\tif not hasEffect("IsJudging") then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal action = Action.new()\r\n\r\n\t\taction._type = "Parry"\r\n\t\taction._when = 300\r\n\t\taction.hitbox = Vector3.new(200, 200, 200)\r\n\t\taction.name = "Judgment"\r\n\r\n\t\tself:action(timing, action)\r\n\tend)\r\nend\r\n',
        ['KickFollowupTitus'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "80865399851806"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        if not defender.entity.Name:find(".titus") or defender.entity:FindFirstChild("Target") and defender.entity:FindFirstChild("Target").Value ~= local_player.character then return action; end\r\n        action.when = 0.3;\r\n        action.type = "Dodge";\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.ignore_hitbox = true;\r\n                \r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['KingCrocSlam'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "9921853885"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    action_type = "M1", \r\n\r\n    run = function(action)\r\n        action.when = 0.7;\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(40, 40, 40);\r\n        action.type = "Jump"\r\n\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['KyrsgardeChampionFiveHitCombo'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "132499670118034"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.64;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 5-Hit Combo 1";\r\n        action:push();\r\n\r\n        action.when = 1.15;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 5-Hit Combo 2";\r\n        action:push();\r\n\r\n        action.when = 2.15;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 5-Hit Combo 3";\r\n        action:push();\r\n\r\n        action.when = 2.70;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 5-Hit Combo 4";\r\n        action:push();\r\n\r\n        action.when = 3.80;\r\n        action.type = "Dodge";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 5-Hit Combo 5";\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['KyrsgardeChampionFourHitCombo'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "127741055541488"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.64;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 4-Hit Combo 1";\r\n        action:push();\r\n\r\n        action.when = 1.34;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 4-Hit Combo 2";\r\n        action:push();\r\n\r\n        action.when = 2.04;\r\n        action.type = "Legit Jump";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 4-Hit Combo 3";\r\n        action:push();\r\n\r\n        action.when = 3.10;\r\n        action.type = "Dodge";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 4-Hit Combo 4";\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['KyrsgardeChampionSpikeCombo'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "133763199472108"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.90;\r\n        action.type = "Dodge";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Spike Combo 1";\r\n        action:push();\r\n\r\n        action.when = 1.55;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Spike Combo 2";\r\n        action:push();\r\n\r\n        action.when = 2.10;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Spike Combo 3";\r\n        action:push();\r\n\r\n        action.when = 3.25;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Spike Combo 4";\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['KyrsgardeChampionSweep'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "80169226986818"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.57;\r\n        action.type = "Legit Jump";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Sweep 1";\r\n        action:push();\r\n\r\n        action.when = 0.75;\r\n        action.type = "Crouch";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Sweep 2";\r\n        action:push();\r\n\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['KyrsgardeChampionThreeHitCombo'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "100777123071173"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.51;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 3-Hit Combo 1";\r\n        action:push();\r\n\r\n        action.when = 1.12;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 3-Hit Combo 2";\r\n        action:push();\r\n\r\n        action.when = 1.26;\r\n        action.type = "Crouch";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion 3-Hit Combo 3";\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['KyrsgardeChampionWindupSlash'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "106268260112496"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.50;\r\n        action.type = "Start Block";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Windup Slash";\r\n        action:push();\r\n\r\n        action.when = 2.00;\r\n        action.type = "End Block";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Ice Champion Windup Slash 2";\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['LionfishBeam'] = '\r\nlocal Action = getfenv().Action\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\n\r\nreturn function(self, timing)\r\n\tif not self.entity then\r\n\t\treturn\r\n\tend\r\n\r\n\tTaskSpawner.spawn("LionfishBeam", function()\r\n\t\tlocal charging = false\r\n\r\n\t\twhile self:live(timing) do\r\n\t\t\ttask.wait()\r\n\r\n\t\t\tlocal _, _, z = self.entity:GetPivot():ToOrientation()\r\n\r\n\t\t\tif z <= (-1.7) then\r\n\t\t\t\tcharging = true\r\n\t\t\tend\r\n\r\n\t\t\tlocal root = charging and z > (-0.9) and self.entity:FindFirstChild("HumanoidRootPart")\r\n\r\n\t\t\tif root then\r\n\t\t\t\tlocal action = Action.new()\r\n\r\n\t\t\t\taction._when = 150\r\n\t\t\t\taction._type = "Forced Full Dodge"\r\n\t\t\t\taction.hitbox = Vector3.new(50, 100, 130)\r\n\r\n\t\t\t\tif self.entity.Name:match("ice") then\r\n\t\t\t\t\taction.name = "Glacial Lionfish Beam Dodge"\r\n\t\t\t\telseif root:FindFirstChild("Fog") then\r\n\t\t\t\t\taction.name = "Corrupted Lionfish Beam Dodge"\r\n\t\t\t\telse\r\n\t\t\t\t\taction.name = "Lionfish Beam Dodge"\r\n\t\t\t\tend\r\n\r\n\t\t\t\treturn self:action(timing, action)\r\n\t\t\tend\r\n\t\tend\r\n\tend)\r\nend\r\n',
        ['LionfishTripleBite'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "5680585677"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        action.when = 0.45;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Lionfish Triple Bite 1";\r\n        action:push();\r\n\r\n        action.when = 1.15;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Lionfish Triple Bite 2";\r\n        action:push();\r\n\r\n        action.when = 1.85;\r\n        action.type = "Parry";\r\n        action.offset = CFrame.new(0, 0, 0);\r\n        action.hitbox = Vector3.new(200, 150, 190);\r\n        action.name = "Lionfish Triple Bite 3";\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['LordSlice'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tlocal distance = self:distance()\r\n\r\n\tlocal action = Action.new()\r\n\r\n\taction._type = "Parry"\r\n\taction._when = (0.375 + distance * 0.012) * 1000\r\n\taction.hitbox = Vector3.new(100, 100, 100)\r\n\taction.name = string.format("(%.2f) ContractorPull", distance)\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['OwlDisperse'] = '\r\nreturn function(self, timing)\r\n\tif not self.entity then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal d = self.data or {}\r\n\tlocal duration = d.Duration or d.dur\r\n\tif not duration then\r\n\r\n\t\tlocal keys = {}\r\n\r\n\t\tfor k, v in next, d do\r\n\t\t\tkeys[#keys + 1] = string.format("%s=%s", tostring(k), typeof(v))\r\n\t\tend\r\n\r\n\t\treturn self:notify(timing, "Effect carried no duration. Payload: %s",\r\n\t\t\t#keys > 0 and table.concat(keys, ", ") or "empty")\r\n\tend\r\n\r\n\ttiming.fhb = false\r\n\ttiming.ndfb = true\r\n\ttiming.rpue = true\r\n\ttiming._rsd = (duration / 2.5) * 1000\r\n\ttiming._rpd = 250\r\n\ttiming.imxd = 120\r\n\ttiming.imdd = 0\r\n\r\n\ttiming.mat = (duration + 0.4) * 1000\r\n\r\n\tself:notify(timing, "(%.2f) Repeat parry armed for the dispersal.", duration)\r\nend\r\n',
        ['PrimaBoulders'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tlocal action = Action.new()\r\n\taction._when = 0\r\n\taction._type = "Dodge"\r\n\taction.duih = true\r\n\taction.hitbox = Vector3.new(15, 15, 15)\r\n\taction.name = "Prima Boulder Dodge"\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['PrimadonGrab'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "9225086332"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        local mob = defender.entity\r\n        if not mob then return action end\r\n        \r\n        local hum = mob:FindFirstChild("Humanoid")\r\n        if not hum then return action end\r\n        \r\n        local timingValue = 0.9\r\n        \r\n        action.when = timingValue\r\n        action.type = "Dodge"\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(110, 250, 110)\r\n        action.name = "Primadon Grab"\r\n        \r\n        action:push()\r\n        return action\r\n    end    \r\n}\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['PrimadonKick'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "6438111139"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n\r\n    run = function(action)\r\n        local mob = defender.entity\r\n        if not mob then return action end\r\n        \r\n        local hum = mob:FindFirstChild("Humanoid")\r\n        if not hum then return action end\r\n        \r\n        local timingValue = mob.Name:match(".monkyking") and 0.6 or 0.9\r\n    \r\n        if hum.Health <= (hum.MaxHealth / 2) then\r\n            timingValue = timingValue / 1.25\r\n        end\r\n        \r\n        action.when = timingValue\r\n        action.type = "Dodge"\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(110, 250, 110)\r\n        action.name = "Primadon Kick"\r\n        \r\n        action:push()\r\n        return action\r\n    end    \r\n}\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['PrimadonMidPunch'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "8365199156"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        local timingValue = (0.6 * 1.12)\r\n        \r\n        action.when = timingValue\r\n        action.type = "Parry"\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(110, 250, 110)\r\n        action.name = "Primadon Mid Punch"\r\n        \r\n        action:push()\r\n        return action\r\n    end    \r\n}\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['PrimadonPunch'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "9225081967"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        local timingValue = (1.05 * 0.7) / track.Speed\r\n        \r\n        action.when = timingValue\r\n        action.type = "Parry"\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(80, 250, 120)\r\n        action.name = "Primadon Punch"\r\n        \r\n        action:push()\r\n        return action\r\n    end    \r\n}\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['PrimadonStomp'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = { "9225098544" },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    ignore_hitbox_check = false,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        local mob = defender.entity\r\n        if not mob then return end\r\n\r\n        local hum = mob:FindFirstChildOfClass("Humanoid")\r\n        if not hum then return end\r\n\r\n        local hitbox = Vector3.new(50, 250, 50)\r\n        if mob.Name:match(".monkyking") then\r\n            hitbox = Vector3.new(80, 250, 80)\r\n        end\r\n\r\n        local when = ((750 * 1.21) / track.Speed) / 1000\r\n        if hum.Health <= (hum.MaxHealth / 2) then\r\n            when = when / 1.21\r\n        end\r\n\r\n        action.when = when\r\n        action.type = "Parry"\r\n        action.hitbox = hitbox\r\n        action.name = "Primadon Stomp"\r\n\r\n        action:push()\r\n        return action\r\n    end\r\n}\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['PrimadonTripleStomp'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tlocal mob = self.entity\r\n\tif not mob then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal hum = mob:FindFirstChild("Humanoid")\r\n\tif not hum then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal baseTimings = { 0.8, 1.4, 2.05 }\r\n\r\n\tif mob.Name:match(".monkyking") and self.track.Speed >= 1.5 and self.track.Speed <= 1.7 then\r\n\t\tbaseTimings = { 0.6, 1, 1.4 }\r\n\tend\r\n\r\n\tif mob.Name:match(".monkyking") and self.track.Speed >= 1.7 and self.track.Speed <= 2.15 then\r\n\t\tbaseTimings = { 0.5, 0.9, 1.4 }\r\n\tend\r\n\r\n\tlocal multiplier = 1.0\r\n\tif hum.Health <= (hum.MaxHealth / 2) then\r\n\t\tmultiplier = 1.25\r\n\tend\r\n\r\n\tfor i = 1, 3 do\r\n\t\tlocal action = Action.new()\r\n\t\taction._type = "Parry"\r\n\t\taction._when = (baseTimings[i] / multiplier) * 1000\r\n\t\taction.fhb = false\r\n\t\taction.hitbox = Vector3.new(110, 250, 110)\r\n\t\taction.name = string.format("Primadon Triple Stomp %d", i)\r\n\r\n\t\tself:action(timing, action)\r\n\tend\r\nend\r\n',
        ['RevengeAgility'] = '\r\nlocal Action = getfenv().Action\r\nlocal Mantra = getfenv().Mantra\r\n\r\nreturn function(self, timing)\r\n\tlocal data = Mantra.data(self.entity, "Mantra:RevengeAgility{{Revenge}}")\r\n\tlocal range = data and (data.rush * 12 + data.drift * 6) or 0\r\n\r\n\tlocal action = Action.new()\r\n\r\n\taction._type = "Parry"\r\n\taction._when = 400\r\n\taction.hitbox = Vector3.new(20, 20, 30 + range)\r\n\taction.fhb = true\r\n\taction.name = "Revenge Agility"\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['RisingFlame'] = '\r\nlocal Action = getfenv().Action\r\nlocal Mantra = getfenv().Mantra\r\n\r\nreturn function(self, timing)\r\n\tlocal data = Mantra.data(self.entity, "Mantra:RisingSlashFire{{Rising Flame}}")\r\n\tlocal range = data and (data.stratus * 12 + data.cloud * 12) or 0\r\n\r\n\tlocal action = Action.new()\r\n\r\n\taction._when = 400\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(30 + range, 25, 30 + range)\r\n\taction.name = "Dynamic Rising Flame Timing"\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['RisingShadow'] = '\r\nlocal Action = getfenv().Action\r\nlocal PartTiming = getfenv().PartTiming\r\nlocal Engine = getfenv().Engine\r\nlocal ProjectileTracker = getfenv().ProjectileTracker\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\nlocal players = getfenv().players\r\n\r\n\r\n\r\nlocal function isTargeted()\r\n\tlocal lp = players.LocalPlayer\r\n\tlocal char = lp and lp.Character\r\n\tlocal hrp = char and char:FindFirstChild("HumanoidRootPart")\r\n\r\n\tif not hrp then\r\n\t\treturn false\r\n\tend\r\n\r\n\tfor _, att in ipairs(hrp:GetChildren()) do\r\n\t\tif att:FindFirstChild("Targetted") or att:FindFirstChild("Targeted") then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n\r\nlocal function trackPart(self, timing)\r\n\tlocal trk = ProjectileTracker.new(function(candidate)\r\n\t\treturn candidate.Name == "TRACKER"\r\n\tend)\r\n\r\n\tlocal part = trk:wait(function()\r\n\t\treturn self:live(timing)\r\n\tend)\r\n\r\n\tif not part then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal lp = players.LocalPlayer\r\n\tlocal minDist = math.huge\r\n\tlocal a = os.clock() + 10\r\n\r\n\trepeat\r\n\t\ttask.wait()\r\n\r\n\t\tlocal root = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")\r\n\r\n\t\tif part.Parent and root then\r\n\t\t\tlocal dist = (root.Position - part.Position).Magnitude\r\n\r\n\t\t\tif dist < minDist then\r\n\t\t\t\tminDist = dist\r\n\t\t\tend\r\n\t\tend\r\n\tuntil not part.Parent or minDist <= 50 or os.clock() >= a or not self:live(timing)\r\n\r\n\tif not part.Parent or minDist > 50 or not self:live(timing) then\r\n\t\treturn\r\n\tend\r\n\r\n\t\r\n\tif not isTargeted() then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\taction._type = "Parry"\r\n\taction._when = 500\r\n\taction.hitbox = Vector3.new(10, 10, 10)\r\n\taction.ihbc = true\r\n\taction.name = string.format("RisingShadowPart-%.2f", minDist)\r\n\r\n\tlocal pt = PartTiming.new()\r\n\tpt.name = "RisingShadowPart"\r\n\tpt.hitbox = Vector3.new(10, 10, 10)\r\n\tpt.actions:push(action)\r\n\r\n\tEngine.part(part, pt)\r\nend\r\n\r\nreturn function(self, timing)\r\n\t\r\n\t\r\n\ttiming.iae = true\r\n\ttiming.ieae = true\r\n\ttiming.mat = 1000\r\n\r\n\t\r\n\tif self:distance() > 16 then\r\n\t\tTaskSpawner.spawn("RisingShadowPart_" .. self.entity.Name, function()\r\n\t\t\ttrackPart(self, timing)\r\n\t\tend)\r\n\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal function parry(when, size)\r\n\t\tlocal action = Action.new()\r\n\r\n\t\taction._type = "Parry"\r\n\t\taction._when = when\r\n\t\taction.hitbox = Vector3.new(size, size, size)\r\n\t\taction.name = "Rising Shadow"\r\n\r\n\t\treturn self:action(timing, action)\r\n\tend\r\n\r\n\tparry(400, 10)\r\n\tparry(600, 15)\r\n\r\n\treturn parry(900, 18)\r\nend\r\n',
        ['RisingThunder'] = '\r\nlocal Action = getfenv().Action\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\n\r\nreturn function(self, timing)\r\n\ttiming.duih = true\r\n\ttiming.hitbox = Vector3.new(20, 20, 20)\r\n\ttiming.mat = 1300\r\n\ttiming.iae = true\r\n\ttiming.ieae = true\r\n\ttiming.bfht = 0.6\r\n\r\n\tlocal distance = self:distance(self.entity)\r\n\r\n\tlocal block = Action.new()\r\n\tblock._when = 250\r\n\tblock._type = "Start Block"\r\n\tblock.name = string.format("(1) Rising Thunder Start (%.1f)", distance)\r\n\tself:action(timing, block)\r\n\r\n\t\r\n\r\n\tlocal entity = self.entity\r\n\tlocal conn\r\n\r\n\tlocal function fireStrike()\r\n\t\tif conn then\r\n\t\t\tconn:Disconnect()\r\n\t\t\tconn = nil\r\n\t\tend\r\n\r\n\t\tself:notify(timing, "(2) Rising Thunder Strike")\r\n\r\n\t\tTaskSpawner.spawn("RisingThunder_" .. entity.Name, function()\r\n\t\t\ttask.wait(750 / 1000)\r\n\r\n\t\t\tif not self:live(timing) then\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\r\n\t\t\tself:notify(timing, "Folder Detected, Executing Parry")\r\n\r\n\t\t\tlocal parry = Action.new()\r\n\t\t\tparry._when = 0\r\n\t\t\tparry._type = "Parry"\r\n\t\t\tparry.ihbc = true\r\n\t\t\tparry.hitbox = Vector3.new(1000, 1000, 1000)\r\n\t\t\tparry.name = "(3) Rising Thunder Parry"\r\n\r\n\t\t\tself:action(timing, parry)\r\n\t\tend)\r\n\tend\r\n\r\n\tconn = entity.DescendantAdded:Connect(function(d)\r\n\t\tif d:IsA("Folder") and d.Name:match("RisingLightning") then\r\n\t\t\tfireStrike()\r\n\t\tend\r\n\tend)\r\n\r\n\t\r\n\tTaskSpawner.spawn("RisingThunder_cleanup_" .. entity.Name, function()\r\n\t\trepeat\r\n\t\t\ttask.wait()\r\n\t\tuntil not self:live(timing)\r\n\r\n\t\tif conn then\r\n\t\t\tconn:Disconnect()\r\n\t\t\tconn = nil\r\n\t\tend\r\n\tend)\r\nend\r\n',
        ['Semtex'] = '\r\nlocal Action = getfenv().Action\r\nlocal Hitbox = getfenv().Hitbox\r\nlocal Latency = getfenv().Latency\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\n\r\nreturn function(self, timing)\r\n\tlocal entity = self.entity\r\n\tif not entity then\r\n\t\treturn\r\n\tend\r\n\r\n\tTaskSpawner.spawn("Semtex", function()\r\n\t\ttask.wait(0.4 - (Latency.rtt() or 0))\r\n\r\n\t\tlocal action = Action.new()\r\n\t\taction._type = "Parry"\r\n\t\taction.name = "Semtex"\r\n\t\taction._when = 0\r\n\t\taction.hso = -15\r\n\t\taction.fhb = false\r\n\t\taction.duih = true\r\n\t\taction.hitbox = Vector3.new(15, 20, 30)\r\n\t\tself:action(timing, action)\r\n\r\n\t\tif not Hitbox then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal start = tick()\r\n\t\tlocal hasJavelin = false\r\n\r\n\t\trepeat\r\n\t\t\thasJavelin = false\r\n\r\n\t\t\tlocal thrown = workspace:FindFirstChild("Thrown")\r\n\t\t\tif thrown then\r\n\t\t\t\tfor _, object in thrown:GetChildren() do\r\n\t\t\t\t\tif object.Name == "Semtex" then\r\n\t\t\t\t\t\thasJavelin = true\r\n\r\n\t\t\t\t\t\tif Hitbox.test(object, Vector3.new(10, 10, 80), { cframe = object.CFrame, shift = -40 }) then\r\n\t\t\t\t\t\t\tlocal hit = Action.new()\r\n\t\t\t\t\t\t\thit._type = "Parry"\r\n\t\t\t\t\t\t\thit.name = "Semtex"\r\n\t\t\t\t\t\t\thit._when = 0\r\n\t\t\t\t\t\t\thit.ihbc = true\r\n\t\t\t\t\t\t\tself:action(timing, hit)\r\n\r\n\t\t\t\t\t\t\treturn\r\n\t\t\t\t\t\tend\r\n\t\t\t\t\tend\r\n\t\t\t\tend\r\n\t\t\tend\r\n\r\n\t\t\ttask.wait()\r\n\t\tuntil (tick() - start >= 1) and not hasJavelin\r\n\tend)\r\nend\r\n',
        ['ShadeDevour'] = '\r\nlocal Action = getfenv().Action\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\n\r\n\r\n\r\n\r\nlocal function modifiers(entity)\r\n\tlocal plr = game:GetService("Players"):GetPlayerFromCharacter(entity)\r\n\tlocal bag = plr and plr:FindFirstChild("Backpack")\r\n\tlocal m = bag and bag:FindFirstChild("Mantra:DevourShadow{{Shade Devour}}")\r\n\tlocal rs = (m and m:GetAttribute("RichStats")) or ""\r\n\r\n\treturn rs:find("%[Blast%]") ~= nil, rs:find("%[Multiplying%]") ~= nil\r\nend\r\n\r\nreturn function(self, timing)\r\n\tlocal blast, multiplying = modifiers(self.entity)\r\n\r\n\ttiming.bfht = 0.5\r\n\ttiming.ieae = true\r\n\ttiming.iae = true\r\n\ttiming.mat = 1500\r\n\r\n\tlocal action = Action.new()\r\n\taction._type = "Parry"\r\n\taction.idf = true\r\n\taction.iapf = true\r\n\r\n\t\r\n\t\r\n\tif multiplying then\r\n\t\t\r\n\t\t\r\n\t\t\r\n\t\t\r\n\t\tlocal function spark(name)\r\n\t\t\tlocal act = Action.new()\r\n\t\t\tact._type = "Parry"\r\n\t\t\tact._when = 0\r\n\t\t\tact.idf = true\r\n\t\t\tact.iapf = true\r\n\t\t\tact.ipc = true\r\n\t\t\tact.hitbox = Vector3.new(29, 29, 29)\r\n\t\t\tact.name = name\r\n\r\n\t\t\tself:action(timing, act)\r\n\t\tend\r\n\r\n\t\tTaskSpawner.spawn("ShadeDevour_MultiplyingSparks", function()\r\n\t\t\ttask.wait(0.1)\r\n\t\t\tspark("Shade Devour (Multiplying) 100")\r\n\r\n\t\t\ttask.wait(0.1)\r\n\t\t\tspark("Shade Devour (Multiplying) 200")\r\n\r\n\t\t\ttask.wait(0.2)\r\n\t\t\tspark("Shade Devour (Multiplying) 400")\r\n\t\tend)\r\n\r\n\t\treturn\r\n\telseif blast then\r\n\t\t\r\n\t\taction._when = 100\r\n\t\taction.hitbox = Vector3.new(29, 29, 29)\r\n\t\taction.name = "Shade Devour (Blast)"\r\n\telse\r\n\t\t\r\n\t\taction._when = 100\r\n\t\taction.hitbox = Vector3.new(29, 29, 29)\r\n\t\taction.fhb = false\r\n\t\taction.name = "Shade Devour"\r\n\tend\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['ShadowEruption'] = '\r\nlocal Action = getfenv().Action\r\nlocal Latency = getfenv().Latency\r\nlocal Mantra = getfenv().Mantra\r\nlocal players = getfenv().players\r\n\r\nreturn function(self, timing)\r\n\tlocal distance = self:distance()\r\n\tlocal data = Mantra.data(self.entity, "Mantra:EruptionShadow{{Shadow Eruption}}")\r\n\tlocal dataTwo = Mantra.data(self.entity, "Mantra:RestraintShadow{{Shadow Chains}}")\r\n\tlocal size = (data and (data.stratus * 5.5 + data.cloud * 4.5)) or 0\r\n\tlocal range = (dataTwo and (dataTwo.perfect * 8 + dataTwo.crystal * 6)) or 0\r\n\tlocal root = self.entity:FindFirstChild("HumanoidRootPart")\r\n\r\n\tif not root then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\taction._type = "Parry"\r\n\r\n\tif root:FindFirstChild("REP_SOUND_5188185503") then\r\n\t\tlocal ping = 0\r\n\r\n\t\tpcall(function()\r\n\t\t\tping = Latency.get_ping() or 0\r\n\t\tend)\r\n\r\n\t\ttask.wait(math.max(0.6 - ping, 0))\r\n\r\n\t\tlocal thrown = workspace:FindFirstChild("Thrown")\r\n\t\tlocal lp = players.LocalPlayer\r\n\t\tlocal lroot = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")\r\n\r\n\t\tif not (thrown and lroot) then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal portal\r\n\r\n\t\tfor _, c in ipairs(thrown:GetChildren())do\r\n\t\t\tif c.Name == "ChainPortalIce" then\r\n\t\t\t\tlocal ok, mag = pcall(function()\r\n\t\t\t\t\treturn (c.Position - lroot.Position).Magnitude\r\n\t\t\t\tend)\r\n\r\n\t\t\t\tif ok and mag <= 20 then\r\n\t\t\t\t\tportal = c\r\n\r\n\t\t\t\t\tbreak\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\tend\r\n\r\n\t\tif not portal then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal beam = portal:WaitForChild("Beam", 5)\r\n\r\n\t\tif not beam then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\trepeat\r\n\t\t\ttask.wait()\r\n\t\tuntil beam.Enabled\r\n\r\n\t\ttiming.ieae = true\r\n\t\taction._when = 500\r\n\t\taction.ihbc = true\r\n\t\taction.hitbox = Vector3.new(50, 50, 50)\r\n\t\taction.name = "Ice Chains"\r\n\telseif workspace:FindFirstChild("Thrown") and workspace.Thrown:FindFirstChild("ChainPortalShadow") then\r\n\t\taction._when = (0.2 + distance * 0.006) * 1000\r\n\t\taction.hitbox = Vector3.new(65 + range, 65 + range, 65 + range)\r\n\t\taction.bfht = 0.45\r\n\t\taction.name = "Shadow Chains"\r\n\telse\r\n\t\taction._when = 0\r\n\t\taction.hitbox = Vector3.new(35 + size, 35 + size, 35 + size)\r\n\t\taction.name = "Shadow Eruption"\r\n\tend\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['ShadowGun'] = '\r\nlocal Action = getfenv().Action\r\nlocal Mantra = getfenv().Mantra\r\n\r\nreturn function(self, timing)\r\n\tlocal data = Mantra.data(self.entity, "Mantra:GunShadow{{Shadow Gun}}")\r\n\tlocal range = data and (data.perfect * 7 + data.crystal * 5) or 0\r\n\tlocal size = data and (data.stratus * 0.4 + data.cloud * 0.3) or 0\r\n\r\n\tlocal action = Action.new()\r\n\r\n\taction._when = 100 * 1.02\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(20 + size, 20 + size, 50 + range)\r\n\taction.name = "Dynamic Shadow Gun Timing"\r\n\r\n\tif data and data.blast then\r\n\t\taction.hitbox = Vector3.new(action.hitbox.X * 2.5, action.hitbox.Y * 2.5, action.hitbox.Z)\r\n\tend\r\n\r\n\ttiming.iae = true\r\n\ttiming.ieae = true\r\n\ttiming.duih = false\r\n\ttiming.mat = 1000\r\n\ttiming.ffh = true\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['SharkoCero'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "91389074160755"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n\r\n    run = function(action)\r\n        repeat\r\n            task.wait()\r\n        until track.TimePosition >= 2.85\r\n    \r\n        action.when = 0\r\n        action.type = "Dodge"\r\n        action.hitbox = Vector3.new(50, 65, 145)\r\n        action.name = string.format("(%.2f) Sharko Cero", track.Speed)\r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['SpikeStabEff'] = '\r\nlocal Action = getfenv().Action\r\nlocal Finder = getfenv().Finder\r\nlocal TaskSpawner = getfenv().TaskSpawner\r\nlocal Latency = getfenv().Latency\r\n\r\nreturn function(self, timing)\r\n\tlocal chaser = Finder.entity(".chaser")\r\n\tif not chaser then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal part = self.part\r\n\r\n\tTaskSpawner.spawn("SpikeStabEff", function()\r\n\t\ttask.wait(0.6 - (Latency.rtt() or 0))\r\n\r\n\t\tif not (part and part.Parent) then\r\n\t\t\treturn\r\n\t\tend\r\n\t\tif self:distance(part) > 20 then\r\n\t\t\treturn\r\n\t\tend\r\n\r\n\t\tlocal action = Action.new()\r\n\t\taction._when = 0\r\n\t\taction._type = "Parry"\r\n\t\taction.ihbc = true\r\n\t\taction.name = "Spike Stab Timing"\r\n\r\n\t\tself:action(timing, action)\r\n\tend)\r\nend\r\n',
        ['SquidwardEruption'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tif not self.track then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal distance = self:distance()\r\n\tlocal speed = self.track.Speed\r\n\r\n\tlocal slow = speed >= 0.2 and speed <= 0.3\r\n\r\n\tlocal action = Action.new()\r\n\r\n\taction._when = slow and 975 or (400 + distance * 4)\r\n\taction._type = slow and "Jump" or "Dodge"\r\n\taction.hitbox = Vector3.new(40, 40, 50)\r\n\taction.name = string.format("(%.2f) (%.2f) Squidward Eruption", distance, speed)\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['StoneKnightSlash'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "85401018793125"\r\n    },\r\n    action_type = "Spell", \r\n    default_chance = 100, \r\n\r\n    allow_block_input = false,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = false,\r\n\r\n    run = function(action)\r\n        task.wait(0.6 - Latency:get_ping());\r\n\r\n        action.name = "Stone Knight Slash";\r\n        action.when = 0;\r\n        action.offset = CFrame.new(0, 0, -15)\r\n        action.hitbox = Vector3.new(15,20,30);\r\n                \r\n        action:push();\r\n\r\n        if general:in_hitbox(local_player.root_part.CFrame, defender.entity.HumanoidRootPart.CFrame, Vector3.new(15,20,35), CFrame.new(0, 0, -10), false) then return action; end\r\n\r\n        local has_javelin = false;\r\n        local start = tick();\r\n\r\n        while tick() - start < 1 or has_javelin do\r\n            has_javelin = false;\r\n            local a = workspace:FindFirstChild("Thrown")\r\n            for _, object in (a and a:GetChildren() or {}) do\r\n                if object.Name ~= "WindSlashProjectileBigSnow" then continue; end\r\n\r\n                has_javelin = true;\r\n                if general:in_hitbox(local_player.root_part.CFrame, object.CFrame, Vector3.new(10, 10, 80), CFrame.new(0, 0, -40), false) then \r\n                    action.name = "Stone Knight Slash";\r\n                    action.when = 0;\r\n                    action.offset = CFrame.new(0, 0, -15)\r\n                    action.ignore_hitbox = true;\r\n                    action.ignore_early_end = true;\r\n\r\n                    action:push();\r\n                \r\n                    return action; \r\n                end\r\n            end;\r\n            task.wait();\r\n        end;\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['Template'] = '\r\nlocal Action = getfenv().Action\r\n\r\nreturn function(self, timing)\r\n\tlocal distance = self:distance()\r\n\r\n\tlocal action = Action.new()\r\n\taction._when = 420\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(15, 15, 40)\r\n\taction.name = string.format("(%.2f) Template Timing", distance)\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n',
        ['ThresherBite'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "8226933122"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true, \r\n    allow_parry_to_block = false,\r\n\r\n    run = function(action)\r\n        action.when = 0.4;\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(40, 30, 40);\r\n                \r\n        action:push();\r\n\r\n        action.when = 0.45 * 2;\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(40, 30, 40);\r\n                \r\n        action:push();\r\n\r\n        action.when = 1.45;\r\n        action.offset = CFrame.new(0, 0, 0)\r\n        action.hitbox = Vector3.new(40, 30, 40);\r\n                \r\n        action:push();\r\n\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['TitusLariat'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n    "93803643628347"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    ignore_hitbox_check = false,\r\n    ignore_early_end = false,\r\n\r\n    run = function(action)\r\n        local distance = self:distance();\r\n        local mob = defender.entity\r\n        if not mob then\r\n            action:push();\r\n            return action;\r\n        end\r\n        \r\n        if mob.Name:match(".titus") then\r\n\r\n            action.when = 0.7;\r\n            action.offset = CFrame.new(0, 0, -20);\r\n            action.hitbox = Vector3.new(20, 50, 40);\r\n            action.type = "Dodge";\r\n            action.name = "TitusLariat";\r\n        else\r\n            if distance > 15 then\r\n                action.when = 0.7;\r\n            else\r\n                action.when = 0.4;\r\n            end\r\n            action.offset = CFrame.new(0, 0, -20);\r\n            action.hitbox = Vector3.new(10, 10, 30);\r\n            action.type = "Parry";\r\n            action.name = "SovereignLariat";\r\n        end\r\n        \r\n        action:push();\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['TitusSkycrash'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n    "118932415770119"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    ignore_hitbox_check = false,\r\n    ignore_early_end = false,\r\n\r\n    run = function(action)\r\n        local mob = defender.entity\r\n        if not mob then\r\n            action:push();\r\n            return action;\r\n        end\r\n        \r\n        if mob.Name:match(".titus") then\r\n\r\naction.hitbox = Vector3.new(0,0,0);\r\naction.offset = CFrame.new(0,0,0);\r\naction.when = 1;\r\naction.type = "";\r\naction:push();\r\naction.delay_until_in_hitbox = false;\r\naction.hitbox = Vector3.new(210,100,130);\r\naction.offset = CFrame.new(0,0,0);\r\naction.when = 1.3;\r\n            action.type = "Dodge";\r\n            action.name = "TitusSkycrash";\r\n        else\r\n\r\n            action.when = 0.1;\r\n            action.offset = CFrame.new(0, 0, -20);\r\n            action.hitbox = Vector3.new(10, 10, 30);\r\n            action.type = "Parry";\r\n            action.name = "SovereignSkycrash";\r\n        end\r\n        \r\n        action:push();\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['TitusThrow'] = '\r\nlocal c = getfenv().MobAction\r\n\r\nreturn function(a, b)\r\n    if not a.entity or not a.track then return end\r\n    local self, defender, track, local_player, Latency, general, task = c.context(a, b)\r\n    local d = (function()\r\nreturn {\r\n    ids = {\r\n        "128613582420698"\r\n    },\r\n    default_chance = 100,\r\n    allow_block_input = true,\r\n    allow_parry_to_roll = true,\r\n    allow_roll_to_parry = true,\r\n    allow_parry_to_block = true,\r\n    ignore_hitbox_check = false,\r\n    ignore_early_end = false,\r\n\r\n    run = function(action)\r\n        local mob = defender.entity if not mob then\r\n            action:push();\r\n            return action;\r\n        end\r\n        \r\n        if mob.Name:match(".titus") then\r\n\r\n            action.when = 0.45;\r\n            action.offset = CFrame.new(0, 0, 0);\r\n            action.hitbox = Vector3.new(34, 34, 34);\r\n            action.type = "Dodge";\r\n            action.name = "TitusThrow";\r\n        else\r\n\r\n            action.when = 0.45;\r\n            action.offset = CFrame.new(0, 0, 0);\r\n            action.hitbox = Vector3.new(34, 34, 34);\r\n            action.type = "Parry";\r\n            action.name = "TitusThrow";\r\n        end\r\n        \r\n        action:push();\r\n        return action;\r\n    end    \r\n};\r\n    end)()\r\n    return c.run(a, b, d)\r\nend\r\n',
        ['UmbralKnight'] = "\r\nlocal a = getfenv().Action\r\n\r\nreturn function(b, c)\r\n    local d = b.data or {}\r\n    if d.Character ~= game:GetService('Players').LocalPlayer.Character then return end\r\n    if type(d.Time) ~= 'number' or type(d.Window) ~= 'number' then return end\r\n    local e = a.new()\r\n    e._type, e._when, e.ihbc = 'Parry', math.max(0, d.Time - d.Window) * 1000, true\r\n    e.name = 'Umbral Knight'\r\n    return b:action(c, e)\r\nend\r\n",
    }
    module.bakedGlobals = {
        ['Mantra'] = '\r\nlocal Mantra = {}\r\n\r\nlocal function count(rs, label)\r\n\treturn tonumber(rs:match("(%d+)%s*[xX]%s*" .. label)) or 0\r\nend\r\n\r\nfunction Mantra.data(entity, name)\r\n\tlocal p = game:GetService("Players"):GetPlayerFromCharacter(entity)\r\n\tlocal bag = p and p:FindFirstChild("Backpack")\r\n\tlocal m = bag and bag:FindFirstChild(name)\r\n\tlocal rs = m and m:GetAttribute("RichStats")\r\n\r\n\tif not rs then\r\n\t\treturn nil\r\n\tend\r\n\r\n\treturn {\r\n\t\tblast = rs:match("%[Blast%]") ~= nil,\r\n\t\tmultiplying = rs:match("%[Multiplying%]") ~= nil,\r\n\t\tspring = rs:match("%[Spring[^%]]*%]") ~= nil,\r\n\t\tdrift = count(rs, "Drift Shard"),\r\n\t\trush = count(rs, "Rush Shard"),\r\n\t\tperfect = count(rs, "Perfect Lens"),\r\n\t\tcrystal = count(rs, "Crystal Lens"),\r\n\t\tstratus = count(rs, "Stratus Stone"),\r\n\t\tcloud = count(rs, "Cloudstone"),\r\n\t\tglass = count(rs, "Glass Stone"),\r\n\t\tmagnifying = count(rs, "Magnifying Stone"),\r\n\t}\r\nend\r\n\r\nfunction Mantra.key(nm)\r\n\treturn nm:match("^Mantra:([^{]+)") or nm\r\nend\r\n\r\nlocal function lcks()\r\n\tlocal o = {}\r\n\tlocal er = game:GetService("ReplicatedStorage"):FindFirstChild("EffectReplicator")\r\n\r\n\tif not er then\r\n\t\treturn o\r\n\tend\r\n\r\n\tlocal ok, em = pcall(require, er)\r\n\r\n\tif not (ok and type(em) == "table" and type(em.GetEffects) == "function") then\r\n\t\treturn o\r\n\tend\r\n\r\n\tlocal got, fx = pcall(em.GetEffects, em)\r\n\r\n\tif not got or type(fx) ~= "table" then\r\n\t\treturn o\r\n\tend\r\n\r\n\tfor _, e in pairs(fx) do\r\n\t\tif type(e) == "table" then\r\n\t\t\tlocal v = e.Value or (e.index and e.index.Value)\r\n\t\t\tif v and (e.Class or (e.index and e.index.Class)) == "ToolLockCD" then\r\n\t\t\t\to[#o + 1] = tostring(v)\r\n\t\t\tend\r\n\t\tend\r\n\tend\r\n\r\n\treturn o\r\nend\r\n\r\nfunction Mantra.find(nm)\r\n\tif type(nm) ~= "string" or nm == "" then\r\n\t\treturn nil\r\n\tend\r\n\r\n\tlocal p = game:GetService("Players").L