        ['MobAction'] = "\r\nlocal a = getfenv().Action\r\nlocal b = getfenv().Latency\r\nlocal c = {}\r\nlocal q = {}\r\n\r\nlocal function d(e, f, g, h, i)\r\n    local j = f * (h or CFrame.identity)\r\n    if i then j = j * CFrame.new(0, 0, -g.Z / 2) end\r\n    local k = j:PointToObjectSpace(e.Position)\r\n    return math.abs(k.X) <= g.X / 2 and math.abs(k.Y) <= g.Y / 2 and math.abs(k.Z) <= g.Z / 2\r\nend\r\n\r\nfunction c.context(e, f)\r\n    local g = game:GetService('Players').LocalPlayer\r\n    local h = g.Character\r\n    local i = h and h:FindFirstChild('HumanoidRootPart')\r\n    local j = os.clock() + 15\r\n    local k = {entity = e.entity}\r\n    function k:in_hitbox(l, m, n)\r\n        return i and e.entity.Parent and d(i.CFrame, e.entity:GetPivot(), l, m, n)\r\n    end\r\n    local l = {\r\n        distance = function() return e:distance() end,\r\n        is_playing = function() return e.track and e.track.IsPlaying and e.entity.Parent ~= nil end,\r\n    }\r\n    local m = {\r\n        get_ping = function() return b.rtt() or 0 end,\r\n        half_ping = function() return b.half_ping() or 0 end,\r\n    }\r\n    local n = {in_hitbox = function(_, ...) return d(...) end}\r\n    local o = setmetatable({}, {__index = task})\r\n    function o.wait(p)\r\n        local function r()\r\n            return os.clock() >= j or g.Character ~= h or not i or not i.Parent\r\n                or not e.entity.Parent or (not f.iae and not e.track.IsPlaying)\r\n        end\r\n        if r() then error(q, 0) end\r\n        local s = task.wait(math.clamp(p or 0.01, 0.01, 15))\r\n        if r() then error(q, 0) end\r\n        return s\r\n    end\r\n    return l, k, e.track, {character = h, root_part = i}, m, n, o\r\nend\r\n\r\nfunction c.run(e, f, g)\r\n    local r = game:GetService('Players').LocalPlayer.Character\r\n    if not r or not r:FindFirstChild('HumanoidRootPart') or not e.entity.Parent then return end\r\n    local h, i = {}, {}\r\n    local j = setmetatable({}, {\r\n        __index = function(_, k)\r\n            if k == 'push' then\r\n                return function(l) h[#h + 1] = i i = {} return l end\r\n            end\r\n            return i[k]\r\n        end,\r\n        __newindex = function(_, k, l) i[k] = l end,\r\n    })\r\n    local r, s = pcall(g.run, j)\r\n    if not r then\r\n        if s == q then return end\r\n        error(s, 0)\r\n    end\r\n    for _, k in ipairs(h) do\r\n        local r = tonumber(k.when) or 0\r\n        if r ~= r or math.abs(r) == math.huge then continue end\r\n        local l = f:clone()\r\n        l.iae = g.ignore_early_end == true or k.ignore_early_end == true\r\n        l.ieae = l.iae\r\n        l.nbfb = g.allow_block_input == false\r\n        local m = a.new()\r\n        m._type = k.type or 'Parry'\r\n        m._when = math.max(0, r) * 1000\r\n        m.name = k.name or f.name\r\n        m.hitbox = k.hitbox or Vector3.new(20, 20, 20)\r\n        m.fhb = k.half_size_offset == true\r\n        m.hso = 0\r\n        m.offset = k.offset and k.offset.Position or nil\r\n        m.ihbc = k.ignore_hitbox == true or g.ignore_hitbox_check == true\r\n        m.duih = k.delay_until_in_hitbox == true\r\n        if m._type == 'Legit Jump' then m._type = 'Jump' end\r\n        if m._type == 'Crouch' then\r\n            m._type = 'Start Crouch'\r\n            e:action(l, m)\r\n            local n = m:clone()\r\n            n._type, n._when, n.ihbc = 'End Crouch', m._when + 600, true\r\n            e:action(l, n)\r\n        elseif m._type == 'RPUE Parry' then\r\n            \r\n            l.rpue, l.rpact, l._rsd, l._rpd = true, m, m._when, 125\r\n            m._type, m._when = 'Parry', 0\r\n            f.rpue, f.rpact, f._rsd, f._rpd = l.rpue, l.rpact, l._rsd, l._rpd\r\n        elseif m._type ~= '' then\r\n            e:action(l, m)\r\n        end\r\n    end\r\nend\r\n\r\nreturn c\r\n",
        ['ProjectileListener'] = '\r\nlocal Maid = getfenv().Maid\r\nlocal Signal = getfenv().Signal\r\n\r\nlocal ProjectileListener = {}\r\nProjectileListener.__index = ProjectileListener\r\n\r\nlocal mde = setmetatable({}, { __mode = "k" })\r\n\r\nfunction ProjectileListener.detach()\r\n\tfor l in next, mde do\r\n\t\tif l.maid then\r\n\t\t\tl.maid:clean()\r\n\t\tend\r\n\tend\r\nend\r\n\r\nfunction ProjectileListener:connect(cb)\r\n\tself.maid:clean()\r\n\r\n\tlocal f = workspace:FindFirstChild("Thrown")\r\n\r\n\tif f then\r\n\t\tself.maid:mark(Signal.new(f.ChildAdded)\r\n\t\t\t:connect(self.id .. "_ProjectileListener", cb))\r\n\r\n\t\treturn\r\n\tend\r\n\r\n\tself.maid:mark(Signal.new(workspace.ChildAdded)\r\n\t\t:connect(self.id .. "_ProjectileListener_Wait", function(c)\r\n\t\t\tif c.Name == "Thrown" then\r\n\t\t\t\tself:connect(cb)\r\n\t\t\tend\r\n\t\tend))\r\nend\r\n\r\nfunction ProjectileListener.new(id)\r\n\tlocal self = setmetatable({ maid = Maid.new(), id = id }, ProjectileListener)\r\n\r\n\tmde[self] = true\r\n\r\n\treturn self\r\nend\r\n\r\nreturn ProjectileListener\r\n',
        ['ProjectileTracker'] = '\r\nlocal Maid = getfenv().Maid\r\nlocal Signal = getfenv().Signal\r\n\r\nlocal ProjectileTracker = {}\r\nProjectileTracker.__index = ProjectileTracker\r\n\r\nlocal clm = setmetatable({}, { __mode = "k" })\r\n\r\nlocal wtg = {}\r\nlocal mad = Maid.new()\r\n\r\nlocal function onAdded(child)\r\n\tif clm[child] then\r\n\t\treturn\r\n\tend\r\n\r\n\tlocal n = #wtg\r\n\tlocal i = 1\r\n\r\n\twhile i <= n do\r\n\t\tlocal trk = wtg[i]\r\n\r\n\t\tif trk.projectile or trk.cancelled or os.clock() >= trk.deadline then\r\n\t\t\twtg[i] = wtg[n]\r\n\t\t\twtg[n] = nil\r\n\t\t\tn = n - 1\r\n\t\telse\r\n\t\t\tlocal a, b = pcall(trk.test, child)\r\n\t\t\tif a and b then\r\n\t\t\ttrk.projectile = child\r\n\t\t\tclm[child] = true\r\n\r\n\t\t\twtg[i] = wtg[n]\r\n\t\t\twtg[n] = nil\r\n\r\n\t\t\treturn\r\n\t\t\tend\r\n\t\t\ti = i + 1\r\n\t\tend\r\n\tend\r\nend\r\n\r\nlocal function bind(folder)\r\n\tmad:mark(Signal.new(folder.ChildAdded):connect("ProjectileTracker_Added", onAdded))\r\nend\r\n\r\nlocal thr = workspace:FindFirstChild("Thrown")\r\n\r\nif thr then\r\n\tbind(thr)\r\nelse\r\n\tmad:mark(Signal.new(workspace.ChildAdded):connect("ProjectileTracker_Thrown", function(child)\r\n\t\tif child.Name == "Thrown" then\r\n\t\t\tbind(child)\r\n\t\tend\r\n\tend))\r\nend\r\n\r\nfunction ProjectileTracker:wait(live)\r\n\twhile not self.projectile and not self.cancelled and os.clock() < self.deadline and live() do\r\n\t\ttask.wait()\r\n\tend\r\n\tself.cancelled = true\r\n\tlocal a = table.find(wtg, self)\r\n\tif a then table.remove(wtg, a) end\r\n\r\n\treturn self.projectile\r\nend\r\n\r\nfunction ProjectileTracker.detach()\r\n\tmad:clean()\r\n\tfor _, a in ipairs(wtg) do a.cancelled = true end\r\n\twtg = {}\r\nend\r\n\r\nfunction ProjectileTracker.new(test)\r\n\tlocal self = setmetatable({ projectile = nil, test = test, deadline = os.clock() + 15 }, ProjectileTracker)\r\n\r\n\twtg[#wtg + 1] = self\r\n\r\n\treturn self\r\nend\r\n\r\nreturn ProjectileTracker\r\n',
        ['TerrainListener'] = '\r\nlocal Maid = getfenv().Maid\r\nlocal Signal = getfenv().Signal\r\n\r\nlocal TerrainListener = {}\r\nTerrainListener.__index = TerrainListener\r\n\r\nlocal mde = setmetatable({}, { __mode = "k" })\r\n\r\nfunction TerrainListener.detach()\r\n\tfor l in next, mde do\r\n\t\tif l.maid then\r\n\t\t\tl.maid:clean()\r\n\t\tend\r\n\tend\r\nend\r\n\r\nfunction TerrainListener:connect(cb)\r\n\tself.maid:clean()\r\n\r\n\tlocal f = workspace:FindFirstChild("Terrain")\r\n\r\n\tif f then\r\n\t\tself.maid:mark(Signal.new(f.ChildAdded)\r\n\t\t\t:connect(self.id .. "_TerrainListener", cb))\r\n\r\n\t\treturn\r\n\tend\r\n\r\n\tself.maid:mark(Signal.new(workspace.ChildAdded)\r\n\t\t:connect(self.id .. "_TerrainListener_Wait", function(c)\r\n\t\t\tif c.Name == "Terrain" then\r\n\t\t\t\tself:connect(cb)\r\n\t\t\tend\r\n\t\tend))\r\nend\r\n\r\nfunction TerrainListener.new(id)\r\n\tlocal self = setmetatable({ maid = Maid.new(), id = id }, TerrainListener)\r\n\r\n\tmde[self] = true\r\n\r\n\treturn self\r\nend\r\n\r\nreturn TerrainListener\r\n',
        ['Waiter'] = '\r\nlocal Latency = getfenv().Latency\r\n\r\nlocal Waiter = {}\r\n\r\nfunction Waiter.ftrack(aid, animator)\r\n\tfor _, t in next, animator:GetPlayingAnimationTracks() do\r\n\t\tlocal a = t.Animation\r\n\r\n\t\tif a and a.AnimationId == aid then\r\n\t\t\treturn t\r\n\t\tend\r\n\tend\r\n\r\n\treturn nil\r\nend\r\n\r\nfunction Waiter.stw(time, cb)\r\n\tlocal t0 = os.clock()\r\n\tlocal d = time - (Latency.rtt() or 0)\r\n\r\n\twhile (os.clock() - t0) <= d do\r\n\t\ttask.wait()\r\n\t\tcb()\r\n\tend\r\nend\r\n\r\nfunction Waiter.fet(aid, animator, live)\r\n\trepeat\r\n\t\tlocal t = Waiter.ftrack(aid, animator)\r\n\r\n\t\tif t then\r\n\t\t\treturn t\r\n\t\tend\r\n\r\n\t\ttask.wait()\r\n\tuntil not live()\r\n\r\n\treturn nil\r\nend\r\n\r\nreturn Waiter\r\n',
        ['Weapon'] = '\r\nlocal Weapon = {}\r\n\r\nlocal function thrownHandWeapon(entityName)\r\n\tlocal thr = workspace:FindFirstChild("Thrown")\r\n\tif not thr then\r\n\t\treturn nil\r\n\tend\r\n\r\n\tlocal att = thr:FindFirstChild("Attach_" .. entityName)\r\n\tif not att then\r\n\t\treturn nil\r\n\tend\r\n\r\n\treturn att:FindFirstChild("HandWeapon")\r\nend\r\n\r\nfunction Weapon.handWeapon(entity)\r\n\tlocal lh = entity:FindFirstChild("LeftHand")\r\n\tlocal rh = entity:FindFirstChild("RightHand")\r\n\r\n\tlocal hw = (lh and lh:FindFirstChild("HandWeapon"))\r\n\t\tor (rh and rh:FindFirstChild("HandWeapon"))\r\n\r\n\tif hw then\r\n\t\treturn hw\r\n\tend\r\n\r\n\treturn thrownHandWeapon(entity.Name)\r\nend\r\n\r\nlocal function nemesis(hw)\r\n\tfor _, inst in next, hw:GetChildren() do\r\n\t\tif inst:IsA("ParticleEmitter") and inst.Texture == "rbxassetid://11889781532" then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\nfunction Weapon.data(entity)\r\n\tlocal hw = Weapon.handWeapon(entity)\r\n\tif not hw then\r\n\t\treturn nil\r\n\tend\r\n\r\n\tlocal sts = hw:FindFirstChild("Stats")\r\n\tif not sts then\r\n\t\treturn nil\r\n\tend\r\n\r\n\tlocal swg = sts:FindFirstChild("SwingSpeed")\r\n\tif not swg then\r\n\t\treturn nil\r\n\tend\r\n\r\n\tlocal len = sts:FindFirstChild("Length")\r\n\tif not len then\r\n\t\treturn nil\r\n\tend\r\n\r\n\tlocal knd = hw:FindFirstChild("Type")\r\n\tif not knd then\r\n\t\treturn nil\r\n\tend\r\n\r\n\treturn {\r\n\t\thw = hw,\r\n\t\tss = swg.Value,\r\n\t\toss = swg:GetAttribute("OldValue") or swg.Value,\r\n\t\tlength = len.Value,\r\n\t\ttype = knd.Value or "N/A",\r\n\t\tnemesis = nemesis(hw),\r\n\t}\r\nend\r\n\r\nreturn Weapon\r\n',
        ['WeaponRun'] = '\r\nlocal Action = getfenv().Action\r\n\r\nlocal WeaponRun = {}\r\n\r\nfunction WeaponRun.run(self, timing, data)\r\n\tif not data then\r\n\t\treturn\r\n\tend\r\n\r\n\ttiming.ffh = true\r\n\ttiming.duih = false\r\n\ttiming.fhb = true\r\n\ttiming.dp = false\r\n\ttiming.nvfb = true\r\n\ttiming.pfht = 0.15\r\n\ttiming.hso = 0\r\n\r\n\tlocal windup = nil\r\n\r\n\tif data.type == "Dagger" then\r\n\t\twindup = (0.147 / self.track.Speed) + 0.140\r\n\telseif data.type == "Greatsword" then\r\n\t\twindup = (0.160 / self.track.Speed) + 0.180\r\n\t\twindup = windup + (0.100 / data.ss)\r\n\telseif data.type == "Greatcannon" then\r\n\t\twindup = (0.160 / self.track.Speed) + 0.180\r\n\t\twindup = windup + (0.100 / data.ss)\r\n\telseif data.type == "Spear" then\r\n\t\twindup = (0.150 / self.track.Speed) + 0.170\r\n\t\twindup = windup + (0.100 / data.ss)\r\n\telseif data.type == "Pistol" then\r\n\t\tlocal a = os.clock() + 5\r\n\t\trepeat\r\n\t\t\tif not self:live(timing) or os.clock() >= a then return end\r\n\t\t\ttask.wait()\r\n\t\tuntil self.track.Speed >= 0.1\r\n\r\n\t\twindup = (0.300 / self.track.Speed)\r\n\telseif data.type == "Rifle" then\r\n\t\twindup = (0.169 / self.track.Speed) + 0.180\r\n\t\twindup = windup + (0.100 / data.ss)\r\n\telseif data.type == "Sword" then\r\n\t\twindup = (0.135 / self.track.Speed) + 0.150\r\n\t\twindup = windup + (0.150 / data.ss)\r\n\telseif data.type == "Rapier" then\r\n\t\twindup = (0.238 / self.track.Speed) + 0.060\r\n\telseif data.type == "Club" then\r\n\t\twindup = (0.173 / self.track.Speed) + 0.140\r\n\t\twindup = windup + (0.150 / data.ss)\r\n\telseif data.type == "Bow" then\r\n\t\twindup = (0.160 / self.track.Speed) + 0.130\r\n\telseif data.type == "Twinblade" then\r\n\t\twindup = (0.164 / self.track.Speed) + 0.140\r\n\t\twindup = windup + (0.150 / data.ss)\r\n\telseif data.type == "Fist" then\r\n\t\twindup = (0.153 / self.track.Speed) + 0.150\r\n\telseif data.type == "Greataxe" then\r\n\t\twindup = (0.150 / self.track.Speed) + 0.100\r\n\t\twindup = windup + (0.100 / data.ss)\r\n\tend\r\n\r\n\tif not windup then\r\n\t\treturn self:notify(timing, "(%s) No windup for this weapon type.", data.type)\r\n\tend\r\n\r\n\tlocal action = Action.new()\r\n\taction._when = windup * 1000\r\n\taction._type = "Parry"\r\n\taction.hitbox = Vector3.new(data.length * 2.5, data.length * 2, data.length * 2.5)\r\n\taction.name =\r\n\t\tstring.format("(%.2f, %.2f, %.2f) (%.2f) Dynamic Weapon Run", data.oss, data.ss, self.track.Speed, data.length)\r\n\r\n\tif data.type == "Twinblade" then\r\n\t\taction.hitbox = Vector3.new(data.length * 2.5, data.length * 2, data.length * 3.5)\r\n\r\n\t\tlocal secondAction = Action.new()\r\n\t\tsecondAction._when = action._when + (300 / data.ss)\r\n\t\tsecondAction._type = "Parry"\r\n\t\tsecondAction.hitbox = action.hitbox\r\n\t\tsecondAction.name = "(2) " .. action.name\r\n\t\tself:action(timing, secondAction)\r\n\tend\r\n\r\n\treturn self:action(timing, action)\r\nend\r\n\r\nreturn WeaponRun\r\n',
