    module.sealed = false

    local modules = filesystem.new('PalantirX/Modules')
    local globals = filesystem.new('PalantirX/Modules/Globals')

    module.engine = {}

    local buildContext = function()
        return {
            Action = action,
            Configuration = configuration,
            Engine = module.engine,
            Finder = finder,
