    local compileChunk = function(chunkName, source)
        local compiled, compileError = loadstring(source, chunkName)

        if not compiled then
            logger.warn('[ModuleManager] %s failed to compile: %s', chunkName, tostring(compileError))

            return nil
        end

        local envTable = buildContext()

        for globalName, globalValue in next, module.globals do
            envTable[globalName] = globalValue
        end

        setfenv(compiled, setmetatable(envTable, {
            __index = function(indexTable, indexKey)
                return getfenv(0)[indexKey]
            end,
        }))

        local ok, result = pcall(compiled)

        if not ok then
            logger.warn('[ModuleManager] %s errored while loading: %s', chunkName, tostring(result))

            return nil
        end

        return result
    end

    function module.add(moduleName, moduleValue)
        module.modules[moduleName] = moduleValue
    end
    function module.load(modName, sourceCode)
        local loaded = compileChunk(modName, sourceCode)

        if type(loaded) ~= 'function' then
            if loaded ~= nil then
                logger.warn('[ModuleManager] %s did not return a function.', modName)
            end

            return false
        end

        module.modules[modName] = loaded

        return true
    end
    function module.loadGlobal(globalKey, globalSource)
        local loadedGlobal = compileChunk(globalKey, globalSource)

        if type(loadedGlobal) ~= 'table' then
            if loadedGlobal ~= nil then
                logger.warn('[ModuleManager] global %s did not return a table.', globalKey)
            end

            return false
        end

        module.globals[globalKey] = loadedGlobal

        return true
    end

    local iterateLuaFiles = function(repo, callback)
        local success, fileList = pcall(repo.list, repo, false)

        if not success or not fileList then
            return
        end

        for index, fileName in next, fileList do
            if fileName:sub(-4) == '.lua' then
                local readOk, fileContent = pcall(repo.read, repo, fileName)

                if readOk and fileContent then
                    callback(fileName:sub(1, -5), fileContent)
                end
            end
        end
    end

    function module.loaded()
        local loadedList = {}

        for modKey in next, module.modules do
            loadedList[#loadedList + 1] = modKey
        end

        table.sort(loadedList)

        return loadedList
    end
    function module.refresh()
        module.detach()

        local globalsToLoad, modulesToLoad = {}, {}

        for bakedGlobalName, bakedGlobalData in next, module.bakedGlobals do
            globalsToLoad[bakedGlobalName] = bakedGlobalData
        end
        for bakedModuleName, bakedModuleData in next, module.baked do
            modulesToLoad[bakedModuleName] = bakedModuleData
        end

        -- Подгружаем импортированные модули Luma (164 чистых модуля для
        -- module-driven таймингов: мантры, свинги мобов и т.д.).
        local lumaOk, lumaModules = pcall(function()
            return a["Game/Timings/LumaModules"]()
        end)

        if lumaOk and typeof(lumaModules) == 'table' then
            for lumaName, lumaSource in next, lumaModules do
                modulesToLoad[lumaName] = lumaSource
            end
        end

        if not module.sealed then
            iterateLuaFiles(globals, function(itemName, itemValue)
                globalsToLoad[itemName] = itemValue
            end)
            iterateLuaFiles(modules, function(modItemName, modItemValue)
                modulesToLoad[modItemName] = modItemValue
            end)
        end

        for toLoadGlobalName, toLoadGlobalSource in next, globalsToLoad do
            module.loadGlobal(toLoadGlobalName, toLoadGlobalSource)
        end
        for toLoadModName, toLoadModSource in next, modulesToLoad do
            module.load(toLoadModName, toLoadModSource)
        end
    end
    function module.detach()
        for detachGlobalName, detachGlobal in next, module.globals do
            if type(detachGlobal.detach) == 'function' then
                pcall(detachGlobal.detach)
            end
        end

        module.modules = {}
        module.globals = {}
    end

    return module
end


return aa()

