]=],
    ["Game/Timings/PartTriggers"] = [=[
local aa = function()
    local aa = {}
    local ab = {}
    local ac = {}
    local configSection = a["Menu/ConfigSection"]()
    local fireCallbacks = function(part, key, ag)
        for callbackIndex = 1, #ab do
            pcall(ab[callbackIndex], part, key, nil, ag, ag)
        end
    end
    local handlePartAdded = function(targetPart)
        fireCallbacks(targetPart, 'part:' .. targetPart.Name, targetPart)
    end

    function aa.onTrigger(callback)
        ab[#ab + 1] = callback
    end

    local connectPartAdded = function(root)
        ac[#ac + 1] = root.DescendantAdded:Connect(handlePartAdded)
    end

    function aa.init()
        local thrown = workspace:FindFirstChild('Thrown')

        if thrown then
            connectPartAdded(thrown)
        else
            ac[#ac + 1] = workspace.ChildAdded:Connect(function(child)
                if child.Name == 'Thrown' then
                    connectPartAdded(child)
                end
            end)
        end

        ac[#ac + 1] = workspace.DescendantAdded:Connect(function(descendant)
            if not (configSection.ps and configSection.ps:index(descendant.Name)) then
                return
            end

            local thrownRoot = workspace:FindFirstChild('Thrown')

            if thrownRoot and descendant:IsDescendantOf(thrownRoot) then
                return
            end

            handlePartAdded(descendant)
        end)
    end
    function aa.detach()
        for connectionIndex = 1, #ac do
            ac[connectionIndex]:Disconnect()
        end

        ac = {}
        ab = {}
    end

    return aa
end


return aa()

]=],
    ["Game/Timings/Scheduler"] = [=[
local aa = function()
    local logger = a["Utility/Logger"]()
    local runService = game:GetService('RunService')
    local ac = {}

    ac._now = os.clock

    local ad = {}
    local ae = 0
    local af = 0
    local ag
    local ah = {}
    local ai = {
        ['Dodge'] = 0,
        ['Forced Full Dodge'] = 0,
    }
    local compareEntries = function(left, right)
        if left.at ~= right.at then
            return left.at < right.at
        end

        return (ai[left.tag] or 1) < (ai[right.tag] or 1)
    end
    local ak = {}

    ak.__index = ak

    function ak:cancel()
        if not self.x then
            self.x = true
            af = af - 1
        end
    end

    local siftUp = function(index)
        local entry = ad[index]

        while index > 1 do
            local parentIndex = math.floor(index / 2)

            if not compareEntries(entry, ad[parentIndex]) then
                break
            end

            ad[index] = ad[parentIndex]
            index = parentIndex
        end

        ad[index] = entry
    end
    local siftDown = function(index)
        local entry = ad[index]
        local limit = math.floor(ae / 2)

        while index <= limit do
            local childIndex = index * 2

            if childIndex < ae and compareEntries(ad[childIndex + 1], ad[childIndex]) then
                childIndex = childIndex + 1
            end
            if not compareEntries(ad[childIndex], entry) then
                break
            end

            ad[index] = ad[childIndex]
            index = childIndex
        end

        ad[index] = entry
    end
    local runTimers = function()
        local now = ac._now()
        local fired = 0
        local liveCount = #ah

        if liveCount > 0 then
            local kept = 0

            for i = 1, liveCount do
                local entry = ah[i]
                local ready = false

                if not entry.x then
                    local ok, offset = pcall(entry.cmp)

                    ready = now >= entry.raw - ((ok and offset) or 0)
                end
                if entry.x then
                elseif ready then
                    af = af - 1
                    entry.x = true

                    local ok, err = pcall(entry.fn)

                    if not ok then
                        logger.warn("[Scheduler] '%s' errored: %s", tostring(entry.tag or '?'), tostring(err))
                    end
                else
                    kept = kept + 1
                    ah[kept] = entry
                end
            end
            for i = liveCount + 1, #ah do
                kept = kept + 1
                ah[kept] = ah[i]
            end
            for i = kept + 1, #ah do
                ah[i] = nil
            end
        end

        while ae > 0 and ad[1].at <= now and fired < 64 do
            local entry = ad[1]

            ad[1] = ad[ae]
            ad[ae] = nil
            ae = ae - 1

            if ae > 0 then
                siftDown(1)
            end
            if not entry.x then
                af = af - 1
                fired = fired + 1
                entry.x = true

                local ok, err = pcall(entry.fn)

                if not ok then
                    logger.warn("[Scheduler] '%s' errored: %s", tostring(entry.tag or '?'), tostring(err))
                end
            end
        end
    end

    ac._pump = runTimers

    function ac.at(ao, callback, tag)
        local entry = setmetatable({
            at = ao,
            fn = callback,
            tag = tag,
            x = false,
        }, ak)

        ae = ae + 1
        ad[ae] = entry

        siftUp(ae)

        af = af + 1

        return entry
    end
    function ac.after(ao, callback, tag)
        return ac.at(ac._now() + ao, callback, tag)
    end
    function ac.live(raw, cmp, callback, tag)
        local entry = setmetatable({
            raw = raw,
            cmp = cmp,
            fn = callback,
            tag = tag,
            x = false,
        }, ak)

        ah[#ah + 1] = entry
        af = af + 1

        return entry
    end
    function ac.pending()
        return af
    end
    function ac.clear()
        for index = 1, ae do
            ad[index] = nil
        end
        for index = #ah, 1, -1 do
            ah[index] = nil
        end

        ae = 0
        af = 0
    end
    function ac.start()
        if not ag then
            ag = runService.Heartbeat:Connect(runTimers)
        end
    end
    function ac.stop()
        if ag then
            ag:Disconnect()

            ag = nil
        end

        ac.clear()
    end

    return ac
end


return aa()

