    timingCodec.seed = 0x5a17c3e9
    timingCodec.bkey = 'PXAP-dev-build-key'
    timingCodec.baked = {}

    local ab = {
        'X',
        'Y',
        'Z',
        '_id',
        '_type',
        'actions',
        'after',
        'alp',
        'animation',
        'bfht',
        'dp',
        'duih',
        'fbb',
        'fbd',
        'fbn',
        'fbv',
        'effect',
        'ename',
        'fhb',
        'flp',
        'hitbox',
        'hso',
        'htype',
        'forced',
        'iae',
        'mant',
        'mchg',
        'iapf',
        'ibfc',
        'idf',
        'ieae',
        'ihbc',
        'ihp',
        'mpoll',
        'ilp',
        'imdd',
        'imxd',
        'mat',
        'name',
        'nbfb',
        'ndfb',
        'nvfb',
        'part',
        'pfh',
        'pfht',
        'phd',
        'phds',
        'pname',
        'rpact',
        'rpd',
        'rpue',
        'rsd',
        'smn',
        'smod',
        'sound',
        'srpn',
        'tag',
        'uhc',
        'umoa',
        'version',
        'when',
    }
    local makeRandomGenerator = function(state)
        return function()
            state = (state * 1103515245 + 12345) % 2147483648

            return state
        end
    end
    local xorBits = function(left, right)
        local result, bitWeight = 0, 1

        while left > 0 or right > 0 do
            local leftBit, rightBit = left % 2, right % 2

            if leftBit ~= rightBit then
                result = result + bitWeight
            end

            left = (left - leftBit) / 2
            right = (right - rightBit) / 2
            bitWeight = bitWeight * 2
        end

        return result
    end
    local ae, af, ag, ah
    local shuffleAlphabet = function()
        local rng = makeRandomGenerator(timingCodec.seed)
        local shuffled = {}

        for copyIndex = 1, #ab do
            shuffled[copyIndex] = ab[copyIndex]
        end
        for position = #shuffled, 2, -1 do
            local swapIndex = rng() % position + 1

            shuffled[position], shuffled[swapIndex] = shuffled[swapIndex], shuffled[position]
        end

        ae, af = {}, {}

        for mapIndex = 1, #shuffled do
            local char = (
"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"):sub(mapIndex, mapIndex)

            ae[shuffled[mapIndex] ] = char
            af[char] = shuffled[mapIndex]
        end

        ag = 2 ^ (rng() % 5 + 1)

        local initBytes = {}

        for byteIndex = 1, 32 do
            initBytes[byteIndex] = string.char(rng() % 256)
        end

        ah = table.concat(initBytes)
    end

    shuffleAlphabet()

    function timingCodec.rekey(seed)
        timingCodec.seed = seed

        shuffleAlphabet()
    end

    local function mgl(value, keyMap, factor)
        if type(value) == 'number' then
            return value * factor
        end
        if type(value) ~= 'table' then
            return value
        end

        local output = {}

        for key, element in next, value do
            output[(type(key) == 'string' and keyMap[key]) or key] = mgl(element, keyMap, factor)
        end

        return output
    end

    local initSBox = function(cipherKey, data)
        local sBox = {}

        for index = 0, 255 do
            sBox[index] = index
        end

        local indexJ = 0

        for permIndex = 0, 255 do
            indexJ = (indexJ + sBox[permIndex] + cipherKey:byte(permIndex % #cipherKey + 1)) % 256
            sBox[permIndex], sBox[indexJ] = sBox[indexJ], sBox[permIndex]
        end

        local outputBytes = {}
        local indexI = 0

        indexJ = 0

        for dataIndex = 1, #data do
            indexI = (indexI + 1) % 256
            indexJ = (indexJ + sBox[indexI]) % 256
            sBox[indexI], sBox[indexJ] = sBox[indexJ], sBox[indexI]
            outputBytes[dataIndex] = string.char(xorBits(data:byte(dataIndex), sBox[(sBox[indexI] + sBox[indexJ]) % 256]))
        end

