        for charCode = 0, 255 do
            dictionary[string.char(charCode)] = charCode
        end

        local outputList, currentString = {}, ''

        for inputIndex = 1, #input do
            local token = input:sub(inputIndex, inputIndex)

            if dictionary[currentString .. token] then
                currentString = currentString .. token
            else
                outputList[#outputList + 1] = dictionary[currentString]

                if nextCode < 4096 then
                    dictionary[currentString .. token] = nextCode
                    nextCode = nextCode + 1
                end

                currentString = token
            end
        end

        if #currentString > 0 then
            outputList[#outputList + 1] = dictionary[currentString]
        end

        local packedBytes = {
            string.char(#outputList % 2),
        }

        for packIndex = 1, #outputList, 2 do
            local firstByte = outputList[packIndex]
            local secondByte = outputList[packIndex + 1] or 0

            packedBytes[#packedBytes + 1] = string.char(math.floor(firstByte / 16))
            packedBytes[#packedBytes + 1] = string.char((firstByte % 16) * 16 + math.floor(secondByte / 256))
            packedBytes[#packedBytes + 1] = string.char(secondByte % 256)
        end

        return table.concat(packedBytes)
    end
    local lzwDecompress = function(compressed)
        local codes = {}

        for offset = 2, #compressed - 2, 3 do
            local firstByte, secondByte, thirdByte = compressed:byte(offset), compressed:byte(offset + 1), compressed:byte(offset + 2)

            codes[#codes + 1] = firstByte * 16 + math.floor(secondByte / 16)
            codes[#codes + 1] = (secondByte % 16) * 256 + thirdByte
        end

        if compressed:byte(1) == 1 then
            codes[#codes] = nil
        end
        if #codes == 0 then
            return ''
        end

        local dictionary, nextCode = {}, 256

        for initCode = 0, 255 do
            dictionary[initCode] = string.char(initCode)
        end

        local previous = dictionary[codes[1] ]

        if not previous then
            return nil
        end

        local result = {previous}

        for index = 2, #codes do
            local currentCode = codes[index]
            local currentString

            if dictionary[currentCode] then
                currentString = dictionary[currentCode]
            elseif currentCode == nextCode then
                currentString = previous .. previous:sub(1, 1)
            else
                return nil
            end

            result[#result + 1] = currentString

            if nextCode < 4096 then
                dictionary[nextCode] = previous .. currentString:sub(1, 1)
                nextCode = nextCode + 1
            end

            previous = currentString
        end

        return table.concat(result)
    end
    local toHex = function(data)
        return (data:gsub('.', function(char)
            return string.format('%02x', char:byte())
        end))
    end
    local fromHex = function(hex)
        if type(hex) ~= 'string' or #hex % 2 ~= 0 or hex:find('%X') then
            return nil
        end

        return (hex:gsub('%x%x', function(pair)
            return string.char(tonumber(pair, 16))
        end))
    end

    function timingCodec.encode(timing)
