    end
    function timingCodec.wrap(wrappedValue)
        return toHex(initSBox(timingCodec.bkey, wrappedValue))
    end
    function timingCodec.unwrap(wrappedHex)
        local bytes = fromHex(wrappedHex)

        if not bytes then
            return nil
        end

        return initSBox(timingCodec.bkey, bytes)
    end
    function timingCodec.pack(packedValue)
        return mgl(packedValue, ae, ag)
    end
    function timingCodec.unpack(unpackedValue)
        return mgl(unpackedValue, af, 1 / ag)
    end

    return timingCodec
end


