    ["Game/Timings/TimingContainer"] = [=[
local aa = function()
    local timingContainer = {}

    timingContainer.__index = timingContainer

    function timingContainer:find(name)
        for key, timing in next, self.timings do
            if timing.name == name then
                return timing
            end
        end
    end
    function timingContainer:index(index)
        return self.timings[index]
    end
    function timingContainer:list()
        local result = {}

        for key, timing in next, self.timings do
            result[#result + 1] = timing
        end

        return result
    end
    function timingContainer:names()
        local result = {}

        for key, timing in next, self.timings do
            result[#result + 1] = timing.name
        end

        table.sort(result)

        return result
    end
    function timingContainer:remove(timing)
        local id = timing:id()

        if not id then
            return
        end

        self.timings[id] = nil
    end
    function timingContainer:equals(other)
        if self:count() ~= other:count() then
            return false
        end

        for key, timing in next, self.timings do
            local otherTiming = other.timings[key]

            if not otherTiming then
                return false
            end
            if not timing:equals(otherTiming) then
                return false
            end
        end

        return true
    end
    function timingContainer:clone()
        local clone = timingContainer.new(self.module)

        for key, timing in next, self.timings do
            clone:push(timing:clone())
        end

        return clone
    end
    function timingContainer:push(timing)
        local id = timing:id()

        if not id then
            return
        end
        if self.timings[id] then
            return error(string.format("Timing identifier '%s' already exists in container.", id))
        end
        if self:find(timing.name) then
            return error(string.format("Timing name '%s' already exists in container.", timing.name))
        end

        self.timings[id] = timing
    end
    function timingContainer:clear()
        self.timings = {}
    end
    function timingContainer:count()
        local count = 0

        for key in next, self.timings do
            count = count + 1
        end

        return count
    end
    function timingContainer:load(data)
        for key, value in next, data do
            local timing = self.module.new(value)
            local id = timing and timing:id()

            if timing and id then
                if self.timings[id] then
                    return error(string.format("Timing identifier '%s' already exists in container.", id))
                end
                if self:find(timing.name) then
                    return error(string.format("Timing name '%s' already exists in container.", timing.name))
                end

                self.timings[id] = timing
            end
        end
    end
    function timingContainer:serialize()
        local result = {}

        for key, timing in next, self.timings do
            result[#result + 1] = timing:serialize()
        end

        return result
    end
    function timingContainer.new(module)
        local container = setmetatable({}, timingContainer)

        container.timings = {}
        container.module = module

        return container
    end

    return timingContainer
end


return aa()

]=],
    ["Game/Timings/TimingSave"] = [=[
local aa = function()
    local timingContainer = a["Game/Timings/TimingContainer"]()
    local animationTiming = a["Game/Timings/AnimationTiming"]()
    local effectTiming = a["Game/Timings/EffectTiming"]()
    local partTiming = a["Game/Timings/PartTiming"]()
    local soundTiming = a["Game/Timings/SoundTiming"]()
    local timings = {}

    timings.__index = timings

    function timings:get()
        return self._data
    end
    function timings:clear()
        for kind, container in next, self._data do
            container:clear()
        end
    end
    function timings:load(data)
        local store = self._data

        if typeof(data.animation) == 'table' then
            store.animation:load(data.animation)
        end
        if typeof(data.effect) == 'table' then
            store.effect:load(data.effect)
        end
        if typeof(data.part) == 'table' then
            store.part:load(data.part)
        end
        if typeof(data.sound) == 'table' then
            store.sound:load(data.sound)
        end
    end
    function timings:clone()
        local copy = timings.new()

        for key, source in next, self._data do
            copy._data[key] = source:clone()
        end

        return copy
    end
    function timings:equals(other)
        if not other or typeof(other) ~= 'table' then
            return false
        end

        for name, mine in next, self._data do
            local otherContainer = other._data[name]

            if not otherContainer then
                return false
            end
            if not mine:equals(otherContainer) then
                return false
            end
        end

        return true
    end
    function timings:count()
        local total = 0

        for category, group in next, self._data do
            total = total + group:count()
        end

        return total
    end
    function timings:serialize()
        local sections = self._data

        return {
            version = 1,
            animation = sections.animation:serialize(),
            effect = sections.effect:serialize(),
            part = sections.part:serialize(),
            sound = sections.sound:serialize(),
        }
    end
    function timings.new(sourceData)
        local instance = setmetatable({}, timings)

        instance._data = {
            animation = timingContainer.new(animationTiming),
            effect = timingContainer.new(effectTiming),
            part = timingContainer.new(partTiming),
            sound = timingContainer.new(soundTiming),
        }

        if sourceData then
            instance:load(sourceData)
        end

        return instance
    end

    return timings
end


return aa()

