    ["Game/Waypoints/DrinkingWater"] = [=[
local aa = function()
    local module = {}

    module.cf = CFrame.new(-2810.89478, 143.126587, 3117.18774, -1.28746033e-5, 
-0.819186091, -0.573527992, -1.00000012, 1.26957893e-5, 4.05311584e-6, 4.05311584e-6, 0.573527992, 
-0.819186211)

    function module.find()
        local waterFolder = workspace.Terrain:FindFirstChild('Water')
        local closestWater, closestDistance

        for index, waterPart in ipairs(waterFolder and waterFolder:GetChildren() or {})do
            if waterPart.Name:find('DrinkingWater', 1, true) and waterPart:FindFirstChild('InteractPrompt') then
                local distance = (waterPart:GetPivot().Position - module.cf.Position).Magnitude

                if distance <= 25 and (not closestDistance or distance < closestDistance) then
                    closestWater, closestDistance = waterPart, distance
                end
            end
        end

        return closestWater
    end

    return module
end


return aa()

]=],
    ["Game/Wipe"] = [=[
local aa = function()
    local module = {}
    local fire = a["Utility/ExecutorInfo"]().fire
    local finder = a["Utility/Finder"]()
    local interactions = a["Features/Game/Interactions"]()
    local logger = a["Utility/Logger"]()
    local persistentData = a["Utility/PersistentData"]()
    local serverHop = a["Game/ServerHop"]()
    local players = game:GetService('Players')
    local replicatedStorage = game:GetService('ReplicatedStorage')
    local flag = false
    local initiateServerHop = function(hopSettings)
        local hopTask = task.spawn(function()
            serverHop.hop(hopSettings.slot, true)
        end)

        task.wait(20)
        pcall(task.cancel, hopTask)

        while persistentData.get('wdata') do
            pcall(function()
                game:GetService('TeleportService'):Teleport(4111023553, players.LocalPlayer)
            end)
            task.wait(10)
        end
    end
    local al = function(...)
        logger.warn(...)
    end
    local getEchoScore = function(echoGui)
        local echoScreen = echoGui and echoGui:FindFirstChild('EchoScoreScreen')
        local mainFrame = echoScreen and echoScreen:FindFirstChild('Main')

        if not echoScreen or not echoScreen.Enabled or not mainFrame or not mainFrame.Visible then
            return nil
        end

        local scoreFrame = mainFrame:FindFirstChild('ScoreFrame')
        local scrollFrame = scoreFrame and scoreFrame:FindFirstChild('Scroll')
        local totalEchoesFrame = scrollFrame and scrollFrame:FindFirstChild('TotalEchoesFrame')
        local scoreVal = totalEchoesFrame and totalEchoesFrame:FindFirstChild('ScoreVal')

        return scoreVal and tonumber((scoreVal.Text:gsub(',', '')))
    end

    function module.pwait()
        local wipeData = persistentData.get('wdata')

        if not wipeData then
            return error('No wipe data set in PersistentData.')
        end

        local startTime = os.clock()

        while task.wait(0.1) do
            if os.clock() - startTime >= 30 then
                return false, 'Fragments of Self did not load'
            end

            local npcs = workspace:FindFirstChild('NPCs')
            local selfNpc = npcs and npcs:FindFirstChild('Self')

            if selfNpc and players.LocalPlayer.Character and players.LocalPlayer.Character:FindFirstChild('HumanoidRootPart') and (players.LocalPlayer.Character.HumanoidRootPart.Position - selfNpc:GetPivot().Position).Magnitude < 200 then
                return true
            end
        end
    end
    function module.pitems()
        local currentWipe = persistentData.get('wdata')

        if not currentWipe then
            return error('No wipe data set in PersistentData.')
        end
        if not next(currentWipe.weapons or {}) then
            return true
        end

        local npcHolder = workspace:WaitForChild('NPCs', 10)
        local pool = npcHolder and npcHolder:WaitForChild('Hippocampal Pool', 10)

        if not pool then
            return false, 'Pass-down pool did not load'
        end

        for weaponKey, weaponName in next, currentWipe.weapons do
            local weapon = finder.weweapon(weaponName)

            if not weapon then
                continue
            end

            interactions.etool(weapon)
            interactions.interact(pool, {
                {
                    choice = '[Inspect]',
                },
                {
                    choice = '[Pass down item]',
                },
                {exit = true},
            }, true)
        end

        return true
    end

    local startEchoRequest = function()
        local localPlayer = players.LocalPlayer
        local npcGroup = workspace:FindFirstChild('NPCs')
        local echoNpc = npcGroup and npcGroup:FindFirstChild('Self')
        local currentArea = tostring(localPlayer:GetAttribute('CurrentArea') or '')
        local rootPart = localPlayer.Character and localPlayer.Character:FindFirstChild('HumanoidRootPart')
        local inArea = echoNpc ~= nil and (currentArea:find('Fragments of Self', 1, true) ~= nil or rootPart and (rootPart.Position - echoNpc:GetPivot().Position).Magnitude < 250)

        if not inArea then
            local requestFolder = replicatedStorage:WaitForChild('Requests', 10)
            local startMenu = requestFolder and requestFolder:WaitForChild('StartMenu', 10)
            local startRemote = startMenu and startMenu:WaitForChild('Start', 10)

            if not startRemote then
                return false, 'Start request did not load'
            end

            al('(Depths) Requesting start.')
            startRemote:FireServer()

            local hopOk, hopError = module.pwait()

            if not hopOk then
                return false, hopError
            end
        end

        al('(Depths) Looking for anyone in the Fragments of Self area.')

        local activeWipe = persistentData.get('wdata')

        if not activeWipe then
            return error('No wipe data set in PersistentData.')
        end

        local itemOk, itemError = module.pitems()

        if not itemOk then
            return false, itemError
        end

        local npcFolder = workspace:WaitForChild('NPCs', 10)
        local selfCharacter = npcFolder and npcFolder:WaitForChild('Self', 10)

        if not selfCharacter then
            return false, 'Self NPC did not load'
        end

        local interactPrompt = selfCharacter:FindFirstChild('InteractPrompt', true)
        local playerGui = localPlayer:WaitForChild('PlayerGui', 10)
        local dialogueGui = playerGui and playerGui:WaitForChild('DialogueGui', 10)
        local requestsFolder = replicatedStorage:WaitForChild('Requests', 10)
        local sendDialogue = requestsFolder and requestsFolder:WaitForChild('SendDialogue', 10)

        if not interactPrompt or not dialogueGui or not sendDialogue then
            return false, 'Self dialogue unavailable'
        end

        local dialogueLines = {
            'What do you mean?',
            "But I don't want to go.",
            "Isn't there something we can do?",
            'What is all this?',
            'So, is this really the end?',
        }
        local getChoices = function()
            local choices = {}

            if not dialogueGui.Enabled then
                return choices
            end

            for descendantIndex, descendant in ipairs(dialogueGui:GetDescendants())do
                local choiceId = descendant:GetAttribute('ChoiceID')

                if type(choiceId) == 'string' and (not descendant:IsA('GuiObject') or descendant.Visible) then
                    choices[choiceId] = true
                end
            end

            return choices
        end
        local hasEndChoice = function()
            if not dialogueGui.Enabled then
                return false
            end

            return getChoices()['[The End]'] == true
        end

        al('(Depths) Opening Self dialogue.')

        local dialogueDeadline = os.clock() + 30
        local retryCount = 0
        local advanceCount = 0

        while localPlayer.Character and os.clock() < dialogueDeadline and not hasEndChoice() do
            if not dialogueGui.Enabled then
                if retryCount >= 3 then
                    break
                end

                retryCount = retryCount + 1

                localPlayer.Character:PivotTo(selfCharacter:GetPivot())
                fire(interactPrompt)

                local reopenTimeout = os.clock() + 2

                repeat
                    task.wait(0.1)
                until dialogueGui.Enabled or os.clock() >= reopenTimeout or not localPlayer.Character

                continue
            end

            local currentChoices = getChoices()
            local selectedChoice

            for lineIndex, line in ipairs(dialogueLines)do
                if currentChoices[line] then
                    selectedChoice = line

                    break
                end
            end

            if selectedChoice then
                advanceCount = advanceCount + 1

                if advanceCount > #dialogueLines then
                    return false, 'Self introduction did not advance'
                end

                sendDialogue:FireServer({choice = selectedChoice})

                local choiceTimeout = os.clock() + 4

                repeat
                    task.wait(0.1)

                    local choiceSet = getChoices()

                    if not choiceSet[selectedChoice] then
                        break
                    end
                until os.clock() >= choiceTimeout or not localPlayer.Character

                if getChoices()[selectedChoice] then
                    return false, 'Self dialogue did not advance from ' .. selectedChoice
                end
            elseif currentChoices.EXIT or currentChoices['[End Dialogue]'] then
                sendDialogue:FireServer({exit = true})

                local exitTimeout = os.clock() + 4

                repeat
                    task.wait(0.1)
                until not dialogueGui.Enabled or os.clock() >= exitTimeout

                if dialogueGui.Enabled then
                    return false, 'Self introduction did not close'
                end
            else
                if next(currentChoices) then
                    return false, 'Unknown Self dialogue choice; wipe was not submitted'
                end

                local waitTimeout = os.clock() + 4

                repeat
                    task.wait(0.1)

                    currentChoices = getChoices()

                    if next(currentChoices) then
                        break
                    end
                until os.clock() >= waitTimeout or not localPlayer.Character

                if not next(currentChoices) then
                    return false, 'Self dialogue choices did not load; wipe was not submitted'
                end
            end
        end

        if not localPlayer.Character then
            return false, 'Character disappeared before wipe submission'
        end
        if not hasEndChoice() then
            return false, 'Self did not offer [The End]'
        end

        local character = localPlayer.Character

        sendDialogue:FireServer({
            choice = '[The End]',
        })

        local confirmTimeout = os.clock() + 12
        local echoScore

        repeat
            echoScore = echoScore or getEchoScore(playerGui)

            task.wait(0.1)
        until localPlayer.Character ~= character or os.clock() >= confirmTimeout

        if localPlayer.Character == character then
            return false, 'Self wipe was not confirmed'
        end

        local resultTimeout = os.clock() + 3

        while not echoScore and os.clock() < resultTimeout do
            echoScore = getEchoScore(playerGui)

            if not echoScore then
                task.wait(0.1)
            end
        end

        al('(Depths) Wiped slot. Removing marker.')
        persistentData.set('wdata', nil)

        local autoState = persistentData.get('auto')

        if autoState and autoState.ferryman_resource_reset_slot == tostring(activeWipe.slot) then
            persistentData.stf('auto', 'ferryman_resource_reset_slot', nil)
        end
        if persistentData.get('efdata') then
            persistentData.stf('efdata', 'wiped', true)
        end

        local autoData = persistentData.get('auto')

        if type(autoData) == 'table' and tostring(autoData.auto_titus_echo_pending_slot or '') == tostring(activeWipe.slot) then
            autoData.auto_titus_echo_cycle = (tonumber(autoData.auto_titus_echo_cycle) or 0) + 1
            autoData.auto_titus_echo_earned = (tonumber(autoData.auto_titus_echo_earned) or 0) + (echoScore or 0)
            autoData.auto_titus_echo_pending_slot = nil

            persistentData.set('auto', autoData)
        end

        return true
    end

    function module.depths()
        if flag then
            return false, 'Wipe already running'
        end

        flag = true

        for attempt = 1, 3 do
            local wipeData = persistentData.get('wdata')

            if not wipeData then
                flag = false

                return true
            end

            al('(Depths) Wipe attempt %d/3.', attempt)

            local done, success, message = false, false, 'Wipe attempt timed out'
            local thread = task.spawn(function()
                local ok, result, errorMsg = pcall(startEchoRequest)

                success, message = ok and result == true, ok and errorMsg or tostring(result)
                done = true
            end)
            local deadline = os.clock() + 90

            repeat
                task.wait(0.1)
            until done or os.clock() >= deadline

            if not done then
                pcall(task.cancel, thread)
            end
            if success or not persistentData.get('wdata') then
                flag = false

                return true
            end

            al('(Depths) Retrying wipe: %s', tostring(message))

            local requests = replicatedStorage:FindFirstChild('Requests')
            local sendDialogue = requests and requests:FindFirstChild('SendDialogue')

            if sendDialogue then
                pcall(function()
                    sendDialogue:FireServer({exit = true})
                end)
            end

            task.wait(1)
        end

        local wipeData = persistentData.get('wdata')

        if wipeData then
            al('(Depths) Wipe retries exhausted; changing server.')
            initiateServerHop(wipeData)
        end

        flag = false

        return false, 'Wipe retries exhausted'
    end
    function module.lobby()
        al('(Lobby) (Step 1) Wiping slot in lobby.')

        local requests = replicatedStorage:WaitForChild('Requests', 10)
        local wipeSlot = requests and requests:WaitForChild('WipeSlot', 10)
        local wipeData = persistentData.get('wdata')

        if not wipeData then
            return error('No wipe data set in PersistentData.')
        end
        if not wipeSlot then
            return serverHop.hop(wipeData.slot, true)
        end
        if wipeData.stage == 'await_fragments' then
            return serverHop.hop(wipeData.slot, false)
        end

        local success = false

        for attempt = 1, 3 do
            local done, succeeded = false, false
            local thread = task.spawn(function()
                local ok, result = pcall(wipeSlot.InvokeServer, wipeSlot, wipeData.slot)

                succeeded = ok and result == true
                done = true
            end)
            local deadline = os.clock() + 4

            repeat
                task.wait(0.1)
            until done or os.clock() >= deadline

            if not done then
                pcall(task.cancel, thread)
            end
            if succeeded then
                success = true

                break
            end

            task.wait(0.6)
        end

        if not success then
            al(
"(Lobby) Wipe request did not complete; changing server before retrying.")

            return serverHop.hop(wipeData.slot, false)
        end

        al('(Lobby) (Step 2) Continuing wipe in Fragments of Self.')

        wipeData.stage = 'await_fragments'

        persistentData.set('wdata', wipeData)
        serverHop.hop(wipeData.slot, false)
    end
    function module.invoke(slot, weapons)
        local wipeData = persistentData.get('wdata')

        persistentData.set('shslot', nil)

        if type(wipeData) ~= 'table' or tostring(wipeData.slot) ~= tostring(slot) then
            wipeData = {
                slot = slot,
                weapons = weapons or {},
            }
        elseif weapons then
            wipeData.weapons = weapons
        end

        persistentData.set('wdata', wipeData)
        al('(Invoke) (Step 1) Marked slot %s in data.', slot)

        if game.PlaceId == 4111023553 then
            return module.lobby()
        end
        if game.PlaceId == 5735553160 then
            local npcs = workspace:FindFirstChild('NPCs')
            local selfFolder = npcs and npcs:FindFirstChild('Self')
            local root = players.LocalPlayer.Character and players.LocalPlayer.Character:FindFirstChild('HumanoidRootPart')

            if tostring(players.LocalPlayer:GetAttribute('CurrentArea') or ''):find('Fragments of Self', 1, true) or selfFolder and root and (root.Position - selfFolder:GetPivot().Position).Magnitude < 250 then
                return module.depths()
            end
        end

        return serverHop.rlobby()
    end

    return module
end


return aa()

]=],
    ["Menu"] = [=[
local aa = function()
    local module = {}
    local loggerTab = a["Menu/LoggerTab"]()
    local automationManager = a["Features/Automation/AutomationManager"]()
    local combatTab = a["Menu/CombatTab"]()
    local configuration = a["Utility/Configuration"]()
    local funTab = a["Menu/FunTab"]()
    local gameTab = a["Menu/GameTab"]()
    local library = a["GUI/Library"]()
    local logger = a["Utility/Logger"]()
    local maid = a["Utility/Maid"]()
    local palantirXTab = a["Menu/PalantirXTab"]()
    local saveManager = a["GUI/SaveManager"]()
    local signal = a["Utility/Signal"]()
    local themeManager = a["GUI/ThemeManager"]()
    local visualsTab = a["Menu/VisualsTab"]()
    local runService = game:GetService('RunService')
    local stats = game:GetService('Stats')
    local players = game:GetService('Players')
    local userInputService = game:GetService('UserInputService')
    local renderStepped = signal.new(runService.RenderStepped)
    local cleanup = maid.new()
    local normalizeVersion = function(formatVersion)
        if not formatVersion or type(formatVersion) ~= 'string' or #formatVersion ~= 4 then
            return formatVersion or 'TEST VERSION'
        end

        local majorVersion = tonumber(formatVersion:sub(1, 3))
        local minorVersion = tonumber(formatVersion:sub(4, 4))

        return majorVersion .. '.' .. minorVersion
    end
    local ax = normalizeVersion(LRM_ScriptVersion)

    module.VERSION = ax

    local ay = 'Unknown'

    pcall(function()
        local marketplaceService = game:GetService('MarketplaceService')
        local productInfo = marketplaceService:GetProductInfo(game.PlaceId)

        ay = productInfo.Name or 'Unknown'
    end)

    local az = 'Palantir X | ' .. ay .. ' | @' .. (LRM_LinkedDiscordID or 'DEV')

    function module.init(initCallback)
        local advanceStep = function()
            if initCallback then
                initCallback()
            else
                task.wait()
            end
        end
        local window
        local windowOk, windowError = pcall(function()
            window = library:CreateWindow({
                Title = az,
                Center = true,
                AutoShow = false,
                Size = UDim2.fromOffset(680, 620),
                TabPadding = 6,
                MenuFadeTime = 0.13,
            })
        end)

        if not windowOk or not window then
            pcall(logger.warn, 'PalantirX: Aztup:CreateWindow failed (%s) \u{2014} Menu cannot render this session.', tostring(windowError))

            return
        end

        themeManager:SetLibrary(library)
        themeManager:SetFolder('PalantirX/Themes')
        saveManager:SetLibrary(library)
        saveManager:IgnoreThemeSettings()
        saveManager:SetFolder('PalantirX/Configs')
        saveManager:SetIgnoreIndexes({
            'Flight',
            'NoClip',
            'Speedhack',
            'InfiniteJump',
            'TweenToObjective',
            'ApBreaker',
            'TitusFarmRelics',
            'TitusBankItems',
            'FerrymanLootAll',
            'FerrymanLootRarities',
            'FerrymanLootItems',
            'FerrymanLootPool',
            'FerrymanLootCategory1',
            'FerrymanLootCategory2',
            'FerrymanLootCategory3',
            'FerrymanLootCategory4',
            'FerrymanLootCategory5',
            'FerrymanLootCategory6',
            'FerrymanLootCategory7',
            'FerrymanLootCategory8',
        })
        advanceStep()

        local initTab = function(tabName, initFunction)
            if type(initFunction) ~= 'function' then
                return false
            end

            local initOk, initError = pcall(initFunction, window)

            if not initOk then
                pcall(logger.warn, 'PalantirX: %s init failed (%s) \u{2014} tab will be empty/missing.', tabName, tostring(initError))
            end

            return initOk
        end

        initTab('CombatTab', combatTab and combatTab.init)
        advanceStep()
        initTab('BuilderTab', loggerTab and loggerTab.init)
        advanceStep()
        initTab('GameTab', gameTab and gameTab.init)
        advanceStep()
        initTab('VisualsTab', visualsTab and visualsTab.init)
        advanceStep()
        initTab('FunTab', funTab and funTab.init)
        advanceStep()
        initTab('AutomationTab', automationManager and automationManager.init)
        advanceStep()
        initTab('PalantirXTab', palantirXTab and palantirXTab.init)
        advanceStep()
        pcall(function()
            if palantirXTab and palantirXTab.wireFunMode then
                palantirXTab.wireFunMode(funTab)
            end
        end)

        local lastUpdate = os.clock()
        local getStatValue = function(statItem)
            if not statItem then
                return 0
            end

            local readOk, statValue = pcall(statItem.GetValue, statItem)

            return (readOk and type(statValue) == 'number') and statValue or 0
        end

        cleanup:add(renderStepped:connect('Menu_WatermarkUpdate', function()
            if os.clock() - lastUpdate <= 0.5 then
                return
            end

            lastUpdate = os.clock()

            local networkStats = stats:FindFirstChild('Network')
            local workspaceStats = stats:FindFirstChild('Workspace')
            local performanceStats = stats:FindFirstChild('PerformanceStats')
            local serverStatsItem = networkStats and networkStats:FindFirstChild('ServerStatsItem') or nil
            local dataPing = getStatValue(serverStatsItem and serverStatsItem:FindFirstChild('Data Ping'))
            local heartbeat = getStatValue(workspaceStats and workspaceStats:FindFirstChild('Heartbeat'))
            local cpuValue = getStatValue(performanceStats and performanceStats:FindFirstChild('CPU'))
            local gpuValue = getStatValue(performanceStats and performanceStats:FindFirstChild('GPU'))
            local watermarkText = string.format('%s | %.2fms | %.1f/s | %.1fms | %.1fms', az, dataPing, heartbeat, cpuValue, gpuValue)

            if configuration.expectToggleValue('ShowDebugInformation') then
                local mouse = players.LocalPlayer and players.LocalPlayer:GetMouse()
                local character = players.LocalPlayer and players.LocalPlayer.Character
                local rootPart = character and character:FindFirstChild('HumanoidRootPart')
                local position = rootPart and rootPart.Position
                local positionString = position and string.format('(%.2f, %.2f, %.2f)', position.X, position.Y, position.Z) or 'N/A'

                watermarkText = watermarkText .. ' | ' .. positionString
                watermarkText = watermarkText .. ' | ' .. (mouse and mouse.Target and mouse.Target:GetFullName() or 'N/A')
            end

            library:SetWatermark(watermarkText)
        end))

        local inputSignal
        local signalOk, signalError = pcall(function()
            inputSignal = signal.new(userInputService.InputBegan)
        end)

        if not signalOk or not inputSignal then
            pcall(logger.warn, 'PalantirX: InputBegan signal creation failed (%s) \u{2014} F8/Equals keybinds inactive.', tostring(signalError))

            inputSignal = nil
        end
        if inputSignal then
            inputSignal:connect('Menu_InputBegan', function(inputObject, isHandled)
                if isHandled then
                    return
                end
                if not configuration.expectToggleValue('ShowDebugInformation') then
                    return
                end
                if inputObject.KeyCode == Enum.KeyCode.F8 then
                    local targetingMouse = players.LocalPlayer and players.LocalPlayer:GetMouse()
                    local target = targetingMouse and targetingMouse.Target

                    if not target then
                        return
                    end

                    target.Name = tostring(math.random(100000, 1000000))

                    return logger.mnnotify("The target has been renamed to '%s' as a marker.", target.Name)
                end
                if inputObject.KeyCode == Enum.KeyCode.Equals and library.Recording then
                    local playerCharacter = players.LocalPlayer and players.LocalPlayer.Character
                    local playerRootPart = playerCharacter and playerCharacter:FindFirstChild('HumanoidRootPart')
                    local playerPosition = playerRootPart and playerRootPart.Position
                    local cframeString = playerPosition and string.format('CFrame.new(%.2f, %.2f, %.2f)', playerPosition.X, playerPosition.Y, playerPosition.Z) or 'N/A'

                    library.PositionList[#library.PositionList + 1] = cframeString
                end
            end)
        end

        pcall(function()
            if Options and Options.MenuKeybind then
                library.ToggleKeybind = Options.MenuKeybind
            end
        end)
        pcall(function()
            saveManager:LoadAutoloadConfig()
        end)
        pcall(function()
            local aeConfigManager = a["Game/AEConfigManager"]()
            local aP, autoloadError, autoloadConfigName = aeConfigManager.loadAutoload()

            if aP and autoloadConfigName then
                library:Notify(string.format('AE autoload %q loaded', autoloadConfigName))
            elseif autoloadError then
                library:Notify(string.format('AE autoload failed: %s', autoloadError))
            end
        end)
        a["Features/Automation/AutoProgression2"]().init()
        pcall(logger.warn, 'Menu initialized.')
    end
    function module.show()
        local hasAnyOk, hasAny = pcall(function()
            return a["Features/Automation/KaidoFarm2"]().hasAny()
        end)

        if hasAnyOk and hasAny then
            return
        end
        if shared.Palantir and shared.Palantir.silent then
            return
        end

        task.spawn(function()
            local success, errResult = pcall(function()
                library:Toggle()
            end)

            if not success then
                pcall(logger.warn, 'PalantirX: Menu.show Aztup:Toggle threw (%s) \u{2014} retrying once.', tostring(errResult))
                pcall(function()
                    library:Toggle()
                end)
            end

            pcall(logger.warn, 'PalantirX: menu shown (Toggle success=%s).', tostring(success))

            task.defer(function()
                pcall(function()
                    if library.SnapDependencyBoxes then
                        library:SnapDependencyBoxes()
                    end
                end)
            end)
        end)
    end
    function module.detach()
        cleanup:clean()

        if loggerTab and loggerTab.detach then
            task.spawn(function()
                pcall(loggerTab.detach)
            end)
        end

        library:Unload()
        logger.warn('Menu detached.')
    end

    return module
end


return aa()

]=],
    ["Menu/AnimationTimingBuilder"] = [=[
local aa = function()
    local timingBuilder = a["Menu/TimingBuilder"]()
    local logger = a["Utility/Logger"]()
    local animationTiming = a["Game/Timings/AnimationTiming"]()
    local timingBuilderModule = setmetatable({}, {__index = timingBuilder})

    timingBuilderModule.__index = timingBuilderModule

    local buildTiming = function(input)
        if type(input) ~= 'string' then
            return ''
        end

        return input:match('(%d+)%s*$') or (input:gsub('%D', ''))
    end

    timingBuilderModule.bareId = buildTiming

    function timingBuilderModule:tide(parent)
        self.animationId = parent:AddInput(nil, {
            Text = 'Animation ID',
            Finished = true,
            Tooltip = 
"Just the number. Paste a full rbxassetid:// link and it gets trimmed for you.",
            Callback = function(value)
                local trimmedId = buildTiming(value)

                if trimmedId ~= value then
                    self.animationId:SetRawValue(trimmedId)
                end
            end,
        })
    end
    function timingBuilderModule:exload(payload)
        self.animationId:SetRawValue(buildTiming(payload._id))
        self.factionTag:SetRawValue(payload.ftag or 'Any')
        self.ignoreAnimationEnd:SetRawValue(payload.iae)
        self.ignoreEarlyAnimationEnd:SetRawValue(payload.ieae)
        self.maxAnimationTimeout:SetRawValue(payload.mat)
        self.checkIfTargeting:SetRawValue(payload.cit)
        self.pastHitboxDetection:SetRawValue(payload.phd)
        self.forceFacingHitbox:SetRawValue(payload.ffh)
        self.predictFacingHitboxes:SetRawValue(payload.pfh)
        self.historySeconds:SetRawValue(payload.phds)
        self.historySteps:SetRawValue(payload.phdn)
        self.extrapolationTime:SetRawValue(payload.pfht)
        self.disablePrediction:SetRawValue(payload.dp)
    end
    function timingBuilderModule:reset()
        timingBuilder.reset(self)
        self.animationId:SetRawValue('')
        self.factionTag:SetRawValue('Any')
        self.ignoreAnimationEnd:SetRawValue(false)
        self.ignoreEarlyAnimationEnd:SetRawValue(false)
        self.maxAnimationTimeout:SetRawValue(2000)
        self.checkIfTargeting:SetRawValue(false)
        self.pastHitboxDetection:SetRawValue(false)
        self.historySeconds:SetRawValue(0.5)
        self.historySteps:SetRawValue(0)
        self.forceFacingHitbox:SetRawValue(false)
        self.predictFacingHitboxes:SetRawValue(false)
        self.disablePrediction:SetRawValue(false)
        self.extrapolationTime:SetRawValue(0.15)
    end
    function timingBuilderModule:check()
        if not timingBuilder.check(self) then
            return false
        end

        local animId = buildTiming(self.animationId.Value)

        if #animId <= 0 then
            return logger.longNotify('Please enter a valid animation ID.')
        end

        local existing = self.container:index(animId)

        if existing then
            return logger.longNotify("The timing ID '%s' (%s) is already in the list.", animId, existing.name)
        end

        return true
    end
    function timingBuilderModule:cset(timingData)
        timingData.name = self.timingName.Value
        timingData._id = buildTiming(self.animationId.Value)
    end
    function timingBuilderModule:create()
        local animation = animationTiming.new()

        self:cset(animation)

        return animation
    end
    function timingBuilderModule:extra(panel)
        self.factionTag = panel:AddDropdown(nil, {
            Text = 'Played By',
            Values = {
                'Any',
                'Mob',
                'Player',
            },
            Default = 1,
            Tooltip = 
"Who is allowed to play this animation. A mob animation coming from a real player is almost always an AP breaker, so 'Mob' makes the engine ignore it.",
            Callback = self:tnc(function(config, faction)
                config.ftag = faction
            end),
        })
        self.ignoreAnimationEnd = self.timingOnly:AddToggle(nil, {
            Text = 'Ignore Anim End',
            Tooltip = 'Keep acting even after the animation stops playing.',
            Default = false,
            Callback = self:tnc(function(record, flag)
                record.iae = flag
            end),
        })

        local timeoutBox = self.timingOnly:AddDependencyBox()

        self.maxAnimationTimeout = timeoutBox:AddInput(nil, {
            Text = 'Anim Timeout',
            Tooltip = 
"How long chained parries may keep going before giving up, in milliseconds.",
            Default = 2000,
            Numeric = true,
            Callback = self:tnc(function(timing, timeout)
                timing.mat = tonumber(timeout)
            end),
        })

        timeoutBox:SetupDependencies({
            {
                self.ignoreAnimationEnd,
                true,
            },
        })

        self.ignoreEarlyAnimationEnd = self.timingOnly:AddToggle(nil, {
            Text = 'Ignore Early End',
            Tooltip = 
"Also keep acting when the animation is cut short -- that is what a feint looks like.",
            Default = false,
            Callback = self:tnc(function(settings, earlyEnd)
                settings.ieae = earlyEnd
            end),
        })
        self.checkIfTargeting = self.timingOnly:AddToggle(nil, {
            Text = 'Check If Targeting',
            Default = false,
            Tooltip = 
"Only answer this move while the attacker's Target points at you. Mobs carry one; players do not, so this never affects PvP.",
            Callback = self:tnc(function(state, targeting)
                state.cit = targeting
            end),
        })
        self.pastHitboxDetection = self.timingOnly:AddToggle(nil, {
            Text = 'Past Hitboxes',
            Default = false,
            Tooltip = 
"Also test where the attacker was a moment ago, to cover lag on their side.",
            Callback = self:tnc(function(entry, pastPos)
                entry.phd = pastPos
            end),
        })

        local historyBox = self.timingOnly:AddDependencyBox()

        self.historySeconds = historyBox:AddSlider(nil, {
            Text = 'History Time',
            Tooltip = 'How far back the past-position test reaches, in seconds.',
            Default = 0.5,
            Min = 0,
            Max = 3,
            Rounding = 2,
            Numeric = true,
            Callback = self:tnc(function(data, seconds)
                data.phds = tonumber(seconds) or 0
            end),
        })
        self.historySteps = historyBox:AddSlider(nil, {
            Text = 'History Steps',
            Tooltip = 
"How many of the recorded positions in that window to test. 0 tests every one, which is the most accurate and the most casts.",
            Default = 0,
            Min = 0,
            Max = 20,
            Rounding = 0,
            Numeric = true,
            Callback = self:tnc(function(model, steps)
                model.phdn = tonumber(steps) or 0
            end),
        })

        historyBox:SetupDependencies({
            {
                self.pastHitboxDetection,
                true,
            },
        })

        self.forceFacingHitbox = self.timingOnly:AddToggle(nil, {
            Text = 'Force Facing',
            Default = false,
            Tooltip = 
"Always test a hitbox aimed at you, without asking whether the attacker's turn actually reaches you in time. Predict Facing is the conditional version.",
            Callback = self:tnc(function(build, force)
                build.ffh = force
            end),
        })
        self.predictFacingHitboxes = self.timingOnly:AddToggle(nil, {
            Text = 'Predict Facing',
            Default = false,
            Tooltip = 
"Aim the hitbox at you when the attacker is mid-turn, instead of where they currently face.",
            Callback = self:tnc(function(item, predict)
                item.pfh = predict
            end),
        })
        self.disablePrediction = self.timingOnly:AddToggle(nil, {
            Text = 'No Prediction',
            Default = false,
            Tooltip = 
"Test only where the attacker is now -- never where they are heading.",
            Callback = self:tnc(function(obj, prediction)
                obj.dp = prediction
            end),
        })
        self.extrapolationTime = self.timingOnly:AddSlider(nil, {
            Text = 'Prediction Time',
            Tooltip = 
"How far ahead the attacker is carried when testing, in seconds.",
            Default = 0.15,
            Min = 0,
            Max = 2,
            Rounding = 3,
            Numeric = true,
            Callback = self:tnc(function(target, secondsAhead)
                target.pfht = tonumber(secondsAhead)
            end),
        })
    end
    function timingBuilderModule.new(startTime, duration, easing)
        return setmetatable(timingBuilder.new(startTime, duration, easing), timingBuilderModule)
    end

    return timingBuilderModule
end


return aa()

