    local actionRunner = a["Game/Timings/ActionRunner"]()
    local autoParry = a["Features/Combat/AutoParry2"]()
    local defenseDebugger = a["Features/Combat/DefenseDebugger"]()
    local module = {}
    local moduleExports = {}
    local noop = function() end
    local initialize = function(moduleExport)
        table.insert(moduleExports, moduleExport)
        noop()
    end

    function module.initAttackAssistanceSection(attackSection)
        local makeCallback = function(featureName)
            return function(enabled)
                local ar = feature.get(featureName)

                if ar then
                    ar:setEnabled(enabled)
                end
            end
        end
        local ardourToggle = attackSection:AddToggle('ArdourSpam', {
            Text = 'Ardour Spam',
            Default = false,
            Tooltip = 
"Fires the Ardour Scream talent's activation remote directly, on a loop.",
            Callback = makeCallback('ArdourSpam'),
        })

        ardourToggle:AddKeyPicker('ArdourSpamKeyBind', {
            Default = 'N/A',
            SyncToggleState = true,
            Text = 'Ardour Spam',
        })

        local modeDropdown = attackSection:AddDropdown('ArdourSpamMode', {
            Text = 'Ardour Spam Mode',
            Values = {
                'Once',
                'Spam',
            },
            Default = 'Spam',
            Tooltip = 
"Once: one activation per keybind press, then it switches itself back off. Spam: keeps firing while the toggle is on.",
        })
        local ardourBox = attackSection:AddDependencyBox()

        ardourBox:AddSlider('ArdourSpamInterval', {
            Text = 'Ardour Spam Interval',
            Min = 0.03,
            Max = 1,
            Default = 0.1,
            Suffix = 's',
            Rounding = 2,
            Tooltip = 
"How often the activation remote is fired while the toggle is on.",
        })
        ardourBox:SetupDependencies({
            {
                modeDropdown,
                'Spam',
            },
        })
    end
    function module.initCombatAssistance(combatSection)
        local autoWispToggle = combatSection:AddToggle('AutoWisp', {
            Text = 'Auto Wisp',
            Default = false,
            Tooltip = 'Casts your Wisp automatically.',
            Unsafe = true,
        })
        local wispBox = combatSection:AddDependencyBox()

        wispBox:AddSlider('AutoWispDelay', {
            Text = 'Auto Wisp Delay',
