            Min = 0,
            Max = 1,
            Suffix = 's',
            Rounding = 2,
        })
        wispBox:SetupDependencies({
            {autoWispToggle, true},
        })

        local goldenTongueToggle = combatSection:AddToggle('AutoGoldenTongue', {
            Text = 'Auto Golden Tongue',
            Default = false,
            Tooltip = 
"Triggers Golden Tongue automatically when ready by firing a random emote.",
        })
        local goldenTongueBox = combatSection:AddDependencyBox()

        goldenTongueBox:AddToggle('CheckIfInCombat', {
            Text = 'Check If In Combat',
            Default = false,
            Tooltip = 
"Only fires when the DangerPvP effect is active (a player is targeting you).",
        })
        goldenTongueBox:SetupDependencies({
            {goldenTongueToggle, true},
        })

        local mantraFollowupToggle = combatSection:AddToggle('AutoMantraFollowup', {
            Text = 'Auto Mantra Followup',
            Default = false,
            Tooltip = 'Auto-triggers the follow-up during a mantra cast.',
        })
        local followupBox = combatSection:AddDependencyBox()

        followupBox:AddToggle('CheckIfMoveHit', {
            Text = 'Check If Move Hit',
            Default = false,
            Tooltip = 'Only fires the follow-up when the cast actually connected.',
        })
        followupBox:SetupDependencies({
            {mantraFollowupToggle, true},
        })
        combatSection:AddToggle('AutoFlowState', {
            Text = 'Auto Flow State',
            Default = false,
            Tooltip = 'Pre-activates flow-state when a relevant move is detected.',
        })
        combatSection:AddToggle('DelayedFeints', {
            Text = 'Delayed Feints',
            Default = false,
            Tooltip = 'Delays your feint to the latest viable moment.',
        })

        local animSpeedToggle = combatSection:AddToggle('AnimationSpeedChanger', {
            Text = 'Animation Speed Changer',
            Default = false,
            Tooltip = 'Varies the playback speed of your animations.',
        })
        local animSpeedBox = combatSection:AddDependencyBox()
        local limitCombatToggle = animSpeedBox:AddToggle('LimitToCombatAnimations', {
            Text = 'Limit To Combat Animations',
            Default = false,
            Tooltip = 'Limits speed variation to combat animations.',
        })
        local combatAnimBox = animSpeedBox:AddDependencyBox()

        combatAnimBox:AddDropdown('LimitToCombatAnimationCategories', {
            Text = 'Combat Animation Types',
            Tooltip = 'Which combat animations the speed variation applies to.',
            Values = {
                'M1',
                'Mantra',
                'Critical',
            },
            Default = 'M1',
            Multi = true,
            AllowNull = false,
        })
        combatAnimBox:SetupDependencies({
            {limitCombatToggle, true},
        })
        animSpeedBox:AddToggle('SwitchBetweenSpeeds', {
            Text = 'Switch Between Speeds',
            Default = false,
            Tooltip = 
"Snaps between the min and max values instead of varying smoothly.",
        })
        animSpeedBox:AddSlider('AnimationSpeedMinimum', {
            Text = 'Animation Speed Minimum',
            Default = 1,
            Min = 0.1,
            Max = 5,
            Suffix = 'x',
            Rounding = 2,
        })
        animSpeedBox:AddSlider('AnimationSpeedMaximum', {
            Text = 'Animation Speed Maximum',
            Default = 1.25,
            Min = 0.1,
            Max = 5,
            Suffix = 'x',
            Rounding = 2,
        })
        animSpeedBox:SetupDependencies({
            {animSpeedToggle, true},
        })

        local actionRollingToggle = combatSection:AddToggle('ActionRolling', {
            Text = 'Action Rolling',
            Default = false,
            Tooltip = 'Auto-rolls during certain actions.',
            Unsafe = true,
        })
        local actionRollBox = combatSection:AddDependencyBox()

        actionRollBox:AddDropdown('ActionRollingActions', {
            Text = 'Action Rolling Actions',
            Values = {
                'Roll On M1',
                'Roll On Critical',
                'Roll On Cast',
                'Roll On Parry',
            },
            Multi = true,
            AllowNull = true,
            Default = {},
        })
        actionRollBox:AddSlider('ActionRollCancelDelay', {
            Text = 'Action Roll Cancel Delay',
            Default = 0.1,
            Min = 0,
            Max = 2,
            Suffix = 's',
            Rounding = 2,
        })
        actionRollBox:AddSlider('ActionRollCooldown', {
            Text = 'Action Roll Cooldown',
            Default = 2,
            Min = 0,
            Max = 5,
            Suffix = 's',
            Rounding = 2,
        })
        actionRollBox:SetupDependencies({
            {actionRollingToggle, true},
        })
        combatSection:AddToggle('M1Hold', {
            Text = 'Hold M1',
            Default = false,
        })
        combatSection:AddToggle('AutoRagdollRecover', {
            Text = 'Auto Ragdoll Recover',
            Default = false,
            Tooltip = 'Recovers from ragdoll automatically.',
            Unsafe = true,
        })
        combatSection:AddToggle('RhythmSpoofer', {
            Text = 'Rhythm Spoofer',
            Default = false,
            Tooltip = 'Fakes Murmur: Rhythm while crouched (press G) \u{2014} plays anim, sonar, and detection pulses without owning the talent.',
            Unsafe = true,
        })

        local players = game:GetService('Players')
        local collectMantraNames = function(container)
            local names = {}

            if not container then
                return names
            end

            for childIndex, child in pairs(container:GetChildren())do
                if child:IsA('Tool') and child.Name:find('Mantra:') and not child.Name:find('RecalledMantra:') then
                    local defaultName = child:GetAttribute('DefaultName')

                    if defaultName and not table.find(names, defaultName) then
                        table.insert(names, defaultName)
                    end
                end
            end

            table.sort(names)

            return names
        end
        local refreshMantras = function()
            local localPlayer = players.LocalPlayer
            local backpack = localPlayer and localPlayer:FindFirstChild('Backpack')
            local mantraNames = collectMantraNames(backpack)

            for exportIndex, dropdown in ipairs(moduleExports)do
                local success = pcall(function()
                    dropdown:SetValues(mantraNames)
                    dropdown:Display()
                end)

                if not success then
                end
            end
        end

        noop = refreshMantras

        local connection
        local watchBackpack = function(backpackContainer)
            if connection then
                connection:Disconnect()
            end
            if not backpackContainer then
                return
            end

            connection = backpackContainer.ChildAdded:Connect(refreshMantras)

            backpackContainer.ChildRemoved:Connect(refreshMantras)
        end
        local setupWatcher = function()
            local currentPlayer = players.LocalPlayer

            if not currentPlayer then
                return
            end

            local foundBackpack = currentPlayer:FindFirstChild('Backpack')

            if foundBackpack then
                watchBackpack(foundBackpack)
            end

            currentPlayer.ChildAdded:Connect(function(addedChild)
                if addedChild.Name == 'Backpack' and addedChild:IsA('Backpack') then
                    watchBackpack(addedChild)
                end
            end)
            currentPlayer.CharacterAdded:Connect(function()
                task.wait(0.5)

                local newBackpack = currentPlayer:FindFirstChild('Backpack')

                if newBackpack then
                    watchBackpack(newBackpack)
                end

                refreshMantras()
            end)
        end

        setupWatcher()

        local backstabToggle = combatSection:AddToggle('BackstabMovestack', {
            Text = 'Backstab Movestacker',
            Default = false,
            Tooltip = 'Auto-casts the selected mantra when you land a backstab.',
            Unsafe = true,
        })
        local backstabBox = combatSection:AddDependencyBox()
        local mantraDropdown = backstabBox:AddDropdown('BackstabMovestackMantras', {
            Text = 'Trigger Mantras',
            Values = {},
            Default = {},
            Multi = true,
            AllowNull = true,
            SaveValues = true,
            Tooltip = 
"Auto-populated from your Backpack. Refreshes when you equip / unequip mantras.",
        })

        initialize(mantraDropdown)
        backstabBox:AddButton('Manual refresh', refreshMantras)
        backstabBox:AddSlider('BackstabMovestackDelay', {
            Text = 'Trigger Delay',
            Default = 0.05,
            Min = 0,
            Max = 0.3,
            Suffix = 's',
            Rounding = 3,
            Tooltip = 'Delay before casting the mantra after Action removal.',
        })
        backstabBox:SetupDependencies({
            {backstabToggle, true},
        })

        local airCounterToggle = combatSection:AddToggle('AutoAirCounter', {
            Text = 'Auto Air Counter',
            Default = false,
            Tooltip = 'Automatically air-counters when an enemy is in range.',
            Unsafe = true,
        })
        local airCounterBox = combatSection:AddDependencyBox()

        airCounterBox:AddToggle('AutoAirCounterAllyCheck', {
            Text = 'Ally Check',
            Default = false,
            Tooltip = 'Skip targets with PVP disabled.',
        })
        airCounterBox:AddToggle('AutoAirCounterOnGround', {
            Text = 'Air Counter On Ground',
            Default = false,
            Tooltip = 'Also fires when grounded (unintended game behavior).',
        })
        airCounterBox:AddSlider('AutoAirCounterRange', {
            Text = 'Air Counter Range',
            Default = 60,
            Min = 10,
            Max = 200,
            Suffix = 'st',
            Rounding = 0,
        })
        airCounterBox:SetupDependencies({
            {airCounterToggle, true},
        })
    end
    function module.initEffectDebuggerSection(debuggerTab)
        local effectDebuggerToggle = debuggerTab:AddToggle('ShowEffectDebugger', {
            Text = 'Show Effect Debugger',
            Default = false,
            Tooltip = 
"Opens a small window listing, for every fallback rung, whether it is available and exactly which effects are blocking it -- with how long each has left.",
            Callback = defenseDebugger.visible,
        })

        effectDebuggerToggle:AddKeyPicker('EffectDebuggerKeyBind', {
            Default = 'N/A',
            SyncToggleState = true,
            Text = 'Effect Debugger',
        })
    end
    function module.initDebuggingSection(debuggingSection)
        debuggingSection:AddToggle('BlockParryState', {
            Text = 'Block Parry State',
            Default = false,
        })
        debuggingSection:AddToggle('BlockDodgeState', {
            Text = 'Block Dodge State',
            Default = false,
        })
        debuggingSection:AddToggle('BlockVentState', {
            Text = 'Block Vent State',
            Default = false,
        })
        debuggingSection:AddToggle('NoBlockingState', {
            Text = 'No Blocking State',
            Default = false,
        })
    end
    function module.initAutoParryMainTab(autoParryTab)
        local enableAutoParry = autoParryTab:AddToggle('EnableAutoParry', {
            Text = 'Enable Auto Parry',
            Default = false,
            Tooltip = 'Master switch for the Auto Parry engine.',
        })

        enableAutoParry:AddKeyPicker('EnableAutoParryKeybind', {
            Default = 'N/A',
            SyncToggleState = true,
            Text = 'Enable Auto Parry',
        })
        autoParryTab:AddToggle('APNotifications', {
            Text = 'Notifications',
            Default = false,
            Tooltip = 
"Narrates what Auto Parry is doing: which timing matched a trigger, whether its hitbox connected and via which check, and why an action was dropped.",
            Callback = function(debugSetting)
                actionRunner.debug = debugSetting
            end,
        })
        autoParryTab:AddToggle('APVisibleHitboxes', {
            Text = 'Visible Hitboxes',
            Default = false,
            Tooltip = 
"Draws the exact box each hitbox check tested. Green = connected, red = missed; magenta and grey are the same two for a predicted hitbox.",
            Callback = function(visualizeSetting)
                hitboxProbe.visualize = visualizeSetting
            end,
        })
        autoParryTab:AddDropdown('MantraSubstitution', {
            Text = 'Mantra Substitution',
            Values = {
                'Prediction',
                'Punishment',
                'Bell',
            },
            Multi = true,
            AllowNull = true,
            Default = {},
            Tooltip = 'Substitutes these mantras for parry or dodge when ready. Not wired to a real cast yet \u{2014} the executor has no mantra action.',
        })

        local rollCancelToggle = autoParryTab:AddToggle('APRollCancel', {
            Text = 'Roll Cancel',
            Default = characterActions.rollCancel,
            Callback = function(rollCancelSetting)
                characterActions.rollCancel = rollCancelSetting
            end,
        })
        local rollCancelBox = autoParryTab:AddDependencyBox()

        rollCancelBox:AddSlider('APRollCancelDelay', {
            Text = 'Roll Cancel Delay',
            Min = 0,
            Max = 2,
            Default = characterActions.rollCancelDelay,
            Suffix = 's',
            Rounding = 2,
            Callback = function(rollCancelDelay)
                characterActions.rollCancelDelay = rollCancelDelay
            end,
        })
        rollCancelBox:SetupDependencies({
            {rollCancelToggle, true},
        })
        autoParryTab:AddDropdown('APFilters', {
            Text = 'Filters',
            Values = {
                'Disable When Textbox Focused',
                'Disable When Window Not Active',
                'Disable While Holding Block',
                'Disable While Using Sightless Beam',
                'Disable During Chime Countdown',
                'Disable While Bell Active',
                'Disable While In Payback',
                'Disable While Periapt Active',
                'Disable While In Tacet',
                "Don't Parry M1 If Enemy Hit",
                "Don't Parry Crit If Enemy Hit",
            },
            Default = {},
            Multi = true,
            Tooltip = "Only 'Disable When Textbox Focused' and 'Disable When Window Not Active' are wired to real checks right now \u{2014} the rest need confirmed effect names before they can gate anything.",
        })
        autoParryTab:AddDivider()
        module.initEffectDebuggerSection(autoParryTab)
    end
    function module.initAutoParryAntiTab(antiExploitTab)
        local antiExploitToggle = antiExploitTab:AddToggle('AntiExploitAnimations', {
            Text = 'Anti-Exploit Animations',
            Default = false,
            Tooltip = 
"Filters inbound animations before Auto Parry reacts. The APC Guard (reference Lycoris/Luma algorithm) is the active engine; the granular filter bank below is legacy and only runs when explicitly enabled.",
            Callback = function(filterOn)
                animationFilter.on = filterOn
            end,
        })

        antiExploitToggle:AddKeyPicker('AntiExploitAnimationsKeybind', {
            Default = 'N/A',
            SyncToggleState = true,
            Text = 'Anti-Exploit Animations',
        })

        local filterBox = antiExploitTab:AddDependencyBox()

        local apcToggle = filterBox:AddToggle('FilterAPCGuard', {
            Text = 'APC Guard (reference algorithm)',
            Default = true,
            Tooltip = 
"Port of the reference AnimatorDefender: rejects priority/weight/speed spoofing, flags entities by animation frequency and low weight, then samples WeightCurrent at 20ms and cancels reactions that fail the fade, ramp or late-weight checks.",
            Callback = function(apcOn)
                animationFilter.apc = apcOn
            end,
        })
        local apcBox = filterBox:AddDependencyBox()

        apcBox:AddToggle('APCRejectCore', {
            Text = 'Reject Core Priority',
