    function module.initAutoParrySettingsTab(tab)
        local allowFailureToggle = tab:AddToggle('APAllowFailure', {
            Text = 'Allow Failure',
            Default = false,
            Tooltip = 'Rolls random chances to miss, roll instead of parry, or ignore a feint \u{2014} for looking less like a bot.',
