        dependencyBox:AddSlider('APFailureRate', {
            Text = 'Failure Rate',
            Min = 0,
            Max = 100,
            Default = 0,
            Suffix = '%',
            Rounding = 0,
            Tooltip = 'Chance to not react at all, as if Auto Parry missed.',
        })
        dependencyBox:AddSlider('APRollInsteadOfParryRate', {
            Text = 'Roll Instead Of Parry Rate',
            Min = 0,
            Max = 100,
            Default = 0,
            Suffix = '%',
            Rounding = 0,
            Tooltip = 'Chance to dodge instead of parry when both are available.',
        })
        dependencyBox:AddSlider('APReactToFeintRate', {
            Text = 'React To Feint Rate',
            Min = 0,
            Max = 100,
            Default = 0,
            Suffix = '%',
            Rounding = 0,
            Tooltip = "Chance to still react to a detected feint instead of holding off. Reserved \u{2014} feint detection isn't wired into dispatch yet.",
        })
        dependencyBox:SetupDependencies({
            {allowFailureToggle, true},
        })

        for option, optionConfig in ipairs({
            {
                key = 'APFallbackBlock',
                text = 'Block Fallback',
                rung = 'Block',
            },
            {
                key = 'APFallbackRoll',
                text = 'Roll Fallback',
                rung = 'Dodge',
            },
        })do
            tab:AddToggle(optionConfig.key, {
                Text = optionConfig.text,
                Default = true,
                Tooltip = string.format(
"Allow Auto Parry to substitute a %s when a parry cannot land.", optionConfig.text:gsub(' Fallback', ''):lower()),
                Callback = function(enabled)
                    autoParry.allowed[optionConfig.rung] = enabled
                end,
            })
        end

        tab:AddToggle('APAutoEquip', {
            Text = 'Auto Equip',
            Default = true,
            Tooltip = 
"Equips a weapon when a timing fires while you have nothing out. Parry, block and vent all need something equipped.",
        })
        tab:AddSlider('APRadius', {
            Text = 'Detection Range',
            Min = 20,
            Max = 1000,
            Default = targetScanner.radius,
            Suffix = 'st',
            Rounding = 0,
            Tooltip = 
"How far out Auto Parry tracks entities. Anything past this is not hooked at all, so its moves are never seen.",
            Callback = function(radius)
                targetScanner.radius = radius
            end,
        })
        tab:AddSlider('APMaxTargets', {
            Text = 'Max Targets',
            Min = 1,
            Max = 32,
            Default = 3,
            Rounding = 0,
            Tooltip = 
"How many entities Auto Parry tracks and listens to, nearest first. Anything past this is not hooked at all.",
        })
        tab:AddSlider('APIgnorePlayers', {
            Text = 'Ignore Players',
            Min = 0,
            Max = 100,
            Default = 0,
            Suffix = '%',
            Rounding = 0,
            Tooltip = 'Chance to ignore a trigger coming from a real player.',
        })
        tab:AddSlider('APIgnoreMobs', {
            Text = 'Ignore Mobs',
            Min = 0,
            Max = 100,
            Default = 0,
            Suffix = '%',
            Rounding = 0,
            Tooltip = 'Chance to ignore a trigger coming from an NPC.',
        })
        tab:AddSlider('APBlockHoldTime', {
            Text = 'Block Hold Time',
            Min = 0.1,
            Max = 2,
            Default = 0.3,
            Suffix = 's',
            Rounding = 2,
        })
    end
    function module.init(settings)
        local combatTab = settings:AddTab('Combat')
        local tabbox = combatTab:AddDynamicTabbox()

        module.initAutoParryMainTab(tabbox:AddTab('Main'))
        module.initAutoParryAntiTab(tabbox:AddTab('Anti'))
        module.initAutoParrySettingsTab(tabbox:AddTab('Settings'))
        module.initAttackAssistanceSection(combatTab:AddDynamicGroupbox('Ap Assistance'))
        module.initCombatAssistance(combatTab:AddDynamicGroupbox('Generic Buff'))

        if not LPH_OBFUSCATED and not LRM_UserNote then
            module.initDebuggingSection(combatTab:AddDynamicGroupbox('Debugging'))
        end
    end

    return module
end


return aa()

