        end

        local names, nameSet = {}, {}

        for index, filename in next, files do
            if filename:sub(-4) == '.dat' then
                local baseName = filename:sub(1, -5)

                nameSet[baseName] = true

                table.insert(names, baseName)
            end
        end
        for bakedName in next, timingCodec.baked do
            if not nameSet[bakedName] then
                table.insert(names, bakedName)
            end
        end

        table.sort(names)

        return names
    end
    function configStore.refresh(dropdown)
        dropdown:SetValues(configStore.list())
    end
    function configStore.autoload(autoloadName)
        if not autoloadName or #autoloadName <= 0 then
            return logger.longNotify('Config name cannot be empty.')
        end

        local writeOk, writeError = pcall(function()
            builderTimingsFile:write('autoload.txt', autoloadName)
        end)

        if not writeOk then
            return logger.warn('Failed to write autoload file (%s).', tostring(writeError))
        end

        logger.notify('Config file %s has been set to auto-load.', autoloadName)
    end
    function configStore.create(createName)
        if not createName or #createName <= 0 then
            return logger.longNotify('Config name cannot be empty.')
        end
        if builderTimingsFile:file(createName .. '.dat') then
            return logger.longNotify('Config file %s already exists.', createName)
        end

        configStore.write(createName)
    end
    function configStore.save(saveName)
        if not saveName or #saveName <= 0 then
            return logger.longNotify('Config name cannot be empty.')
        end
        if not builderTimingsFile:file(saveName .. '.dat') then
            return logger.longNotify('Config file %s does not exist.', saveName)
        end

        configStore.write(saveName)
    end
    function configStore.write(configName)
        if not configName or #configName <= 0 then
            return -1, logger.longNotify('Config name cannot be empty.')
        end

        local marshalOk, serialized = pcall(serializer.marshal, timingCodec.pack(timings:serialize()))

        if not marshalOk then
            return -2, logger.warn('Failed to serialize config %s (%s).', configName, tostring(serialized))
        end

        local encodeOk, encoded = pcall(timingCodec.encode, serialized)

        if not encodeOk then
            return -3, logger.warn('Failed to encode config %s (%s).', configName, tostring(encoded))
        end

        local fileWriteOk, fileWriteError = pcall(function()
            builderTimingsFile:write(configName .. '.dat', encoded)
        end)

        if not fileWriteOk then
            return -4, logger.warn('Failed to write config %s (%s).', configName, tostring(fileWriteError))
        end

        logger.notify('Config file %s has been written to.', configName)

        return 0
    end
    function configStore.clear(clearName)
        if not clearName or #clearName <= 0 then
            return logger.longNotify('Config name cannot be empty.')
        end

        local clearMarshalOk, clearedData = pcall(serializer.marshal, timingSave.new():serialize())

        if not clearMarshalOk then
            return logger.warn('Failed to serialize config %s (%s).', clearName, tostring(clearedData))
        end

        local clearWriteOk, clearWriteError = pcall(function()
            builderTimingsFile:write(clearName .. '.dat', base64.encode(clearedData))
        end)

        if not clearWriteOk then
            return logger.warn('Failed to write config %s (%s).', clearName, tostring(clearWriteError))
        end

        logger.notify('Config file %s has been cleared.', clearName)
    end
    function configStore.load(aq)
        local startTime = os.clock()

        if not aq or #aq <= 0 then
            return logger.longNotify('Config name cannot be empty.')
        end

        local encodedData = timingCodec.baked[aq] and timingCodec.unwrap(timingCodec.baked[aq])

        if not encodedData then
            local readOk, fileData = pcall(function()
                return builderTimingsFile:read(aq .. '.dat')
            end)

            if not readOk then
                return logger.warn('Failed to read config %s (%s).', aq, tostring(fileData))
            end

            encodedData = fileData
        end

        local decoded

        for codecIndex, codec in next, {timingCodec, base64}do
            local decodeOk, decodedBytes = pcall(codec.decode, encodedData)

            if decodeOk and decodedBytes then
                local unmarshalOk, unmarshaled = pcall(deserializer.unmarshal_one, stringUtil.tba(decodedBytes))

                if unmarshalOk and typeof(unmarshaled) == 'table' then
                    decoded = codec == timingCodec and timingCodec.unpack(unmarshaled) or unmarshaled

                    break
                end
            end
        end

        if not decoded then
            return logger.warn('Failed to decode config %s.', aq)
        end

        timings:clear()

        local loadOk, loadError = pcall(timings.load, timings, decoded)

        if not loadOk then
            return logger.warn('Failed to load config %s (%s).', aq, tostring(loadError))
        end

        logger.notify('Config file %s has loaded with %d timings in %.2f seconds.', aq, timings:count(), os.clock() - startTime)

        configStore.llc = timings:clone()
        configStore.llcn = aq
    end
    function configStore.autosave()
        if not configStore.llcn then
            return false, -1, logger.warn('No config name has been loaded for auto-save.')
        end

        logger.warn("Auto-saving timings to '%s' config file.", configStore.llcn)

        return true, configStore.write(configStore.llcn)
    end
    -- Импортирует встроенные тайминги (из Luma) в виде .dat файлов при первом
    -- запуске. Записывает через РЕАЛЬНЫЙ кодек PalantirX, поэтому файлы всегда
    -- валидны независимо от тонкостей арифметики double/int.
    function configStore.importBundledTimings()
        local imports = {
            ['TruthImport'] = 'Game/Timings/TruthTimings',
            ['BaseImport'] = 'Game/Timings/BaseTimings',
        }

        for configName, modulePath in next, imports do
            local ok, data = pcall(function()
                return a[modulePath]()
            end)

            if not ok or typeof(data) ~= 'table' then
                logger.warn('import: failed to load bundled %s (%s).', configName, tostring(data))

                continue
            end

            -- Нормализуем _id: AutoParry (av.find) ищет тайминги по числовому
            -- ID анимации (marker:match('(%d+)%s*$')), а Luma хранит _id как
            -- полный 'rbxassetid://...'. Убираем префикс, иначе auto-parry
            -- никогда не сматчит анимации игроков/мобов.
            -- Также замапливаем module-driven тайминги Luma на модули PalantirX:
            -- обычные свинги/криты оружием -> DynamicWeapon, иначе их smod
            -- (WeaponTest, SwordSwing, ...) отсутствует в PalantirX и
            -- ActionRunner падает с "No module found".
            local weaponSmods = {
                WeaponTest = true, WeaponFlourishTest = true, WeaponAerialAttackTest = true,
                WeaponRunningAttackTest = true, WeaponUppercutTest = true,
                SwordSwing = true, SwordCritical = true, SwordAerial = true,
                GreataxeSwing = true, GreataxeCritical = true,
                GreatswordSwing = true, GreatswordCritical = true, GreatswordUppercut = true,
                SpearSwing = true, SpearCritical = true, SpearUppercut = true,
                RapierSwing = true, RapierCritical = true, KatanaCritical = true,
                DaggerSwing = true, DaggerCritical = true, DaggerAerial = true,
                NavaeSwing = true, NavaeCritical = true,
                JusKaritaSwing = true, JusKaritaCritical = true, JusKaritaUppercut = true,
                LegionSwing = true, LegionMasterySwing = true,
                CurvedCrit = true, CrescentCrit = true, Flourish = true,
                HeavyAerial = true, RunningAttack = true, StrongLeft = true,
                FistAerial = true, FistRunningAttack = true, GreathammerUppercut = true,
                DeepspindleCrit = true, TantoCrit = true, SoulthornCrit = true,
                UmbriteCrit = true, WraithclawCrit = true, ScalesplitterCrit = true,
                WyrmCrit = true, WhalingCrit = true, RailbladeCrit = true, RailbladeAerialCrit = true,
                RifleSpear = true, RifleSpearCrit = true, Scythe = true, DualCurvedBladeCrit = true,
                Icedagger = true, LordsSlice = true, Veinbreaker = true, Edenstaff = true,
                GremorianLongSpear = true, RocketLance = true, Stormbreaker = true,
                ShardBow = true, WindGun = true, ShadowGun = true, GunShot = true,
                RapidSlashes = true, RapidPunches = true, VengefulSlashes = true,
            }

            for _, animTiming in ipairs(data.animation or {}) do
                if typeof(animTiming._id) == 'string' then
                    animTiming._id = animTiming._id:gsub('^rbxassetid://', '')
                end
                if animTiming.umoa and typeof(animTiming.smod) == 'string' and weaponSmods[animTiming.smod] then
                    animTiming.smod = 'DynamicWeapon'
                end
                -- Luma stores after = 0 for nearly every timing, but PalantirX
                -- schedules on Heartbeat: the timer always fires a fraction of a
                -- frame after the deadline, so a zero late window makes the
                -- executor log "Too late to act, dropped" and skip the action.
                if type(animTiming.after) ~= 'number' or animTiming.after <= 0 then
                    animTiming.after = 0.2
                end
            end

            local backup = timings:clone()

            timings:clear()

            local loadOk, loadErr = pcall(timings.load, timings, data)

            if not loadOk then
                logger.warn('import: %s timings.load failed (%s).', configName, tostring(loadErr))
                timings:clear()

                pcall(timings.load, timings, backup:serialize())

                continue
            end

            local writeResult = configStore.write(configName)

            timings:clear()

            pcall(timings.load, timings, backup:serialize())

            if writeResult == 0 then
                logger.warn('import: wrote bundled timings %s (%d timings).', configName, timings:count())
            end
        end
    end
    function configStore.init()
        if configStore.inited then
            return
        end

        configStore.inited = true

        configStore.importBundledTimings()

        local preRenderSignal = signal.new(runService.PreRender)
        local readOk, fileContent = pcall(function()
            return builderTimingsFile:read('autoload.txt')
        end)

        if readOk and fileContent then
            configStore.load(fileContent)
        elseif builderTimingsFile:file('TruthImport.dat') then
            -- Нет autoload — автозагружаем встроенные тайминги TruthImport,
            -- чтобы auto-parry работал на игроках/мобах сразу после запуска.
            configStore.load('TruthImport')
        end

        configStore.as = timings:get().animation
        configStore.es = timings:get().effect
        configStore.ps = timings:get().part
        configStore.ss = timings:get().sound

        cleanupMaid:add(preRenderSignal:connect('BuilderSaveManager_AutoSave', function()
            local lastConfig = configStore.llc

            if not lastConfig then
                return
            end

            local configFileName = configStore.llcn

            if not configFileName then
                return
            end
            if not configuration.expectToggleValue('BuilderPeriodicAutoSave') then
                return
            end
            if configStore.lct and os.clock() - configStore.lct < (configuration.expectOptionValue('BuilderPeriodicAutoSaveInterval') or 60) then
                return
            end

            configStore.lct = os.clock()

            if timings:equals(lastConfig) then
                return
            end

            logger.warn("Auto-saving timings to '%s' config file.", configStore.llcn)
            configStore.write(configStore.llcn)

            configStore.llc = timings:clone()

            logger.notify('Timing auto-save has completed successfully.')
        end))
    end
    function configStore.detach()
        cleanupMaid:clean()

        configStore.inited = false
    end

    return configStore
end


return aa()

]=],
    ["Menu/EffectNameInput"] = [=[
local aa = function()
    local timingBuilder = a["Menu/TimingBuilder"]()
    local logger = a["Utility/Logger"]()
    local effectTiming = a["Game/Timings/EffectTiming"]()
    local module = setmetatable({}, {__index = timingBuilder})

    module.__index = module

    function module:tide(input)
        self.effectName = input:AddInput(nil, {
            Text = 'Effect Name',
        })
    end
    function module:exload(data)
        self.effectName:SetRawValue(data.ename)
        self.ignoreLocalPlayer:SetRawValue(data.ilp)
        self.forceLocalPlayer:SetRawValue(data.flp)
    end
    function module:reset()
        timingBuilder.reset(self)
        self.effectName:SetRawValue('')
        self.ignoreLocalPlayer:SetRawValue(false)
        self.forceLocalPlayer:SetRawValue(false)
    end
    function module:check()
        if not timingBuilder.check(self) then
            return false
        end
        if not self.effectName.Value or #self.effectName.Value <= 0 then
            return logger.longNotify('Please enter a valid effect name.')
        end
        if self.container:index(self.effectName.Value) then
            return logger.longNotify("The timing ID '%s' is already in the list.", self.effectName.Value)
        end

        return true
    end
    function module:cset(timing)
        timing.name = self.timingName.Value
        timing.ename = self.effectName.Value
    end
    function module:create()
        local timing = effectTiming.new()

        self:cset(timing)

        return timing
    end
    function module:extra(entry)
        self.ignoreLocalPlayer = self.timingOnly:AddToggle(nil, {
            Text = 'Ignore Own Effects',
            Default = true,
            Tooltip = 
"Skip this effect when it lands on you rather than on someone else.",
            Callback = self:tnc(function(entry, value)
                entry.ilp = value
            end),
        })
        self.forceLocalPlayer = self.timingOnly:AddToggle(nil, {
            Text = 'Only Own Effects',
            Default = false,
            Tooltip = 'React only when this effect lands on you.',
            Callback = self:tnc(function(entry, value)
                entry.flp = value
            end),
        })
    end
    function module.new(parent, timing, ignoreLocalPlayer)
        return setmetatable(timingBuilder.new(parent, timing, ignoreLocalPlayer), module)
    end

    return module
end


return aa()

