    ["Menu/FunTab"] = [=[
local aa = function()
    local module = {}
    local exploitTab = a["Menu/ExploitTab"]()
    local morph = a["Features/Fun/Morph"]()
    local raceMorph = a["Features/Exploits/RaceMorph"]()
    local flingPlayers = a["Features/Exploits/FlingPlayers"]()
    local tweenService = game:GetService('TweenService')
    local players = game:GetService('Players')
    local coreGui = game:GetService('CoreGui')
    local userInputService = game:GetService('UserInputService')

    game:GetService('RunService')

    local localPlayer = players.LocalPlayer

    module._tab = nil
    module._window = nil

    local getVisibleButtons = function(collectVisibleTabs)
        local visibleButtons = {}

        for _, tab in pairs(collectVisibleTabs.Tabs)do
            if tab.TabButton and tab.TabButton.Visible then
                visibleButtons[#visibleButtons + 1] = tab.TabButton
            end
        end

        return visibleButtons
    end
    local getVisibleTab = function(findVisibleTab)
        for _, tab in pairs(findVisibleTab.Tabs)do
            if tab.TabFrame and tab.TabFrame.Visible then
                return tab
            end
        end

        return nil
    end
    local resizeButtons = function(window, animate)
        local visibleButtons = getVisibleButtons(window)
        local count = math.max(1, #visibleButtons)
        local size = UDim2.new(1 / count, 0, 1, 0)

        for index, button in ipairs(visibleButtons)do
            if animate then
                tweenService:Create(button, TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = size}):Play()
            else
                button.Size = size
            end
        end

        local updateIndicator = function()
            local visibleTab = getVisibleTab(window)

            if visibleTab and visibleTab.UpdateIndicator then
                pcall(visibleTab.UpdateIndicator, visibleTab, animate)
            end
        end

        task.defer(updateIndicator)

        if animate then
            task.delay(0.25, updateIndicator)
        end
    end

    function module.reflow()
        if not module._window then
            return
        end

        resizeButtons(module._window, false)
    end
    function module.setVisible(visible)
        local tab = module._tab
        local window = module._window

        if not tab or not tab.TabButton or not window then
            return
        end
        if visible then
            if tab.TabButton.Visible then
                return
            end

            tab.TabButton.Size = UDim2.new(0, 0, 1, 0)
            tab.TabButton.Visible = true

            resizeButtons(window, true)
        else
            if not tab.TabButton.Visible then
                return
            end
            if tab.TabFrame and tab.TabFrame.Visible then
                for _, as in pairs(window.Tabs)do
                    if as ~= tab and as.TabButton and as.TabButton.Visible and as.ShowTab then
                        as:ShowTab()

                        break
                    end
                end
            end

            tweenService:Create(tab.TabButton, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
                Size = UDim2.new(0, 0, 1, 0),
            }):Play()
            task.delay(0.2, function()
                if tab.TabButton then
                    tab.TabButton.Visible = false
                end

                resizeButtons(window, true)
            end)
        end
    end

    local ao
    local getParticlesGui = function()
        if ao and ao.Parent then
            return ao
        end

        local screenGui = Instance.new('ScreenGui')

        screenGui.Name = 'PalantirX_FunParticles'
        screenGui.IgnoreGuiInset = true
        screenGui.ResetOnSpawn = false
        screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        screenGui.DisplayOrder = 2147483647

        local hasGui = false

        if gethui then
            local ok, gui = pcall(gethui)

            if ok and gui then
                screenGui.Parent = gui
                hasGui = true
            end
        end
        if not hasGui then
            local ok = pcall(function()
                screenGui.Parent = coreGui
            end)

            if not ok then
                screenGui.Parent = localPlayer:WaitForChild('PlayerGui')
            end
        end

        ao = screenGui

        return screenGui
    end
    local createParticle = function(parent, x, y)
        local frame = Instance.new('Frame')

        frame.Size = UDim2.fromOffset(6, 6)
        frame.AnchorPoint = Vector2.new(0.5, 0.5)
        frame.Position = UDim2.fromOffset(x, y)
        frame.BackgroundColor3 = Color3.fromHSV(math.random(), 1, 1)
        frame.BorderSizePixel = 0
        frame.BackgroundTransparency = 0
        frame.ZIndex = 100
        frame.Parent = parent

        local corner = Instance.new('UICorner')

        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = frame

        local dx = math.random(-200, 200)
        local endY = math.random(120, 320)
        local dy = math.random(-90, -10)
        local endPos = UDim2.fromOffset(x + dx, y + endY)

        tweenService:Create(frame, TweenInfo.new(0.9, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
            Position = endPos,
            BackgroundTransparency = 1,
        }):Play()
        tweenService:Create(frame, TweenInfo.new(0.9 * 0.4, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
            Position = UDim2.fromOffset(x + dx * 0.35, y + dy),
        }):Play()
        task.delay(0.9, function()
            if frame then
                pcall(function()
                    frame:Destroy()
                end)
            end
        end)
    end

    function module.spawnRainbowParticles()
        local emitter = getParticlesGui()

        task.spawn(function()
            local startTime = os.clock()
            local interval = 1 / 90

            while os.clock() - startTime < 0.5 do
                local mouseLocation = userInputService:GetMouseLocation()

                createParticle(emitter, mouseLocation.X, mouseLocation.Y)
                task.wait(interval)
            end
        end)
    end
    function module.init(window)
        module._window = window

        local tab = window:AddTab('Fun')

        module._tab = tab

        local soundsGroup = tab:AddLeftGroupbox('Sounds')

        exploitTab.initParrySoundSection(soundsGroup)
        exploitTab.initBlockBreakSoundSection(soundsGroup)

        local morphGroup = tab:AddRightGroupbox('Character Morph')
        local getPlayerNames = function()
            local names = {}

            for index, player in ipairs(players:GetPlayers())do
                if player ~= localPlayer then
                    names[#names + 1] = player.Name
                end
            end

            table.sort(names)

            return names
        end
        local morphDropdown = morphGroup:AddDropdown('MorphTarget', {
            Text = 'Target',
            Values = getPlayerNames(),
            AllowNull = true,
            Tooltip = "Copy this player's visible appearance (accessories / character meshes / clothing) onto your own character. Client-side/local only \u{2014} nobody else sees it, and it may reset on respawn.",
        })

        morphGroup:AddButton('Refresh Players', function()
            morphDropdown:SetValues(getPlayerNames())
        end)
        morphGroup:AddButton('Morph To Target', function()
            local targetName = morphDropdown.Value
            local target = (type(targetName) == 'string' and #targetName > 0) and players:FindFirstChild(targetName) or nil

            if not target then
                return
            end

            morph.morphTo(target)
        end)
        morphGroup:AddButton('Reset Appearance', function()
            morph.reset()
        end)

        local raceMorphGroup = tab:AddRightGroupbox('Race Morph')

        raceMorphGroup:AddButton('Open Race Morph', function()
            raceMorph.open()
        end)
        raceMorphGroup:AddLabel(
"Writes the embedded morph GUI to PalantirX/Morphs on first open. Then F4 toggles it.", true)

        local mobControlGroup = tab:AddLeftGroupbox('Mob Control')

        mobControlGroup:AddToggle('BringMobs', {
            Text = 'Bring Mobs',
            Default = false,
            Tooltip = 'Continuously pull every mob you hold network ownership over to your position plus the offset below. Same ownership gate as Void Mobs \u{2014} they clump on you and follow.',
        })
        mobControlGroup:AddSlider('BringMobsOffsetX', {
            Text = 'Offset X',
            Default = 0,
            Min = -50,
            Max = 50,
            Rounding = 0,
            Suffix = ' studs',
        })
        mobControlGroup:AddSlider('BringMobsOffsetY', {
            Text = 'Offset Y',
            Default = 0,
            Min = -50,
            Max = 50,
            Rounding = 0,
            Suffix = ' studs',
        })
        mobControlGroup:AddSlider('BringMobsOffsetZ', {
            Text = 'Offset Z',
            Default = 0,
            Min = -50,
            Max = 50,
            Rounding = 0,
            Suffix = ' studs',
        })

        local tpMobsDropdown = mobControlGroup:AddDropdown('TPMobsTarget', {
            Text = 'TP Target',
            Values = getPlayerNames(),
            AllowNull = true,
            Tooltip = 
"Send ALL mobs you hold network ownership over to this player's position (plus the offset above). One-shot.",
        })

        mobControlGroup:AddButton('Refresh Players', function()
            tpMobsDropdown:SetValues(getPlayerNames())
        end)
        mobControlGroup:AddToggle('TPMobs', {
            Text = 'Auto TP Mobs To Target',
            Default = false,
            Tooltip = 
"While on, continuously send ALL owned mobs to the TP Target player above (plus the offset). Takes precedence over Bring Mobs when both are on.",
        })
        mobControlGroup:AddToggle('AttachMobsBack', {
            Text = "Attach To Target's Back",
            Default = false,
            Tooltip = 'With Auto TP on, stick the mobs right behind the target (inheriting their facing) instead of on their position + offset \u{2014} so the mobs cling to their back and follow their turns.',
        })
        mobControlGroup:AddToggle('MobExtendRange', {
            Text = 'Extend Range (may rubber-band)',
            Default = false,
            Tooltip = 
"Claim ownership of FAR mobs so you don't have to walk up to each one first. Focuses one unowned mob at a time to pull it under your control, then moves it. Tradeoff: brief focus-holds can rubber-band you slightly, and with many mobs it claims them a few per second rather than all at once.",
        })

        local flingGroup = tab:AddLeftGroupbox('Fling')

        flingGroup:AddToggle('FlingPlayers', {
            Text = 'Fling Players',
            Default = false,
            Tooltip = "Blasts your HumanoidRootPart velocity up (+9e9 Y) with an alternating angular whip every Heartbeat and restores it before render, so you stay put while whoever you're touching gets launched. Only engages while a player is within contact range, so you can still walk around normally \u{2014} just walk into someone to fling them.",
        })

        local comboDropdown = flingGroup:AddDropdown('FlingComboTarget', {
            Text = 'Combo Target',
            Values = getPlayerNames(),
            AllowNull = true,
            Tooltip = 'Who the Fling Combo targets.',
        })

        flingGroup:AddButton('Refresh Players', function()
            comboDropdown:SetValues(getPlayerNames())
        end)
        flingGroup:AddButton('Fling Combo', function()
            flingPlayers.runCombo()
        end)
        flingGroup:AddLabel(
"Tweens 4000 studs up, over the target, drops on them and launches them UP (twice) so they fall and take fall damage. Aborts if you die. Enable No Fall Damage so the descent doesn't kill YOU.", true)

        if tab.TabButton then
            tab.TabButton.Visible = false
        end

        resizeButtons(window, false)
    end

    return module
end


return aa()

