    function module.initGankPingSection(tab)
        local ensureFolder = function()
            if makefolder and not isfolder('PalantirX/Webhooks') then
                makefolder('PalantirX/Webhooks')
            end
        end
        local webhookPath = function(name)
            return 'PalantirX/Webhooks' .. '/' .. name .. '.txt'
        end
        local loadWebhooks = function()
            ensureFolder()

            gankPing.savedWebhooks = {}

            local webhookNames = {}

            if not listfiles then
                return webhookNames
            end

            for fileIndex, filePath in next, listfiles('PalantirX/Webhooks')do
                local fileName = filePath:match('([^/\\]+)%.txt$')

                if fileName and isfile and isfile(filePath) then
                    gankPing.savedWebhooks[fileName] = readfile(filePath)
                    webhookNames[#webhookNames + 1] = fileName
                end
            end

            table.sort(webhookNames)

            return webhookNames
        end
        local webhookName = tab:AddInput('GankWebhookName', {
            Text = 'Webhook Name',
            Placeholder = 'e.g. MyServer',
            Finished = false,
        })
        local webhookUrl = tab:AddInput('GankWebhookURL', {
            Text = 'Webhook URL',
            Placeholder = 'https://discord.com/api/webhooks/...',
            Finished = false,
        })
        local refreshDropdown

        tab:AddButton({
            Text = 'Save Webhook',
            Tooltip = 
"Saves the URL above under the entered name and adds it to the Send To list. Overwrites if the name already exists.",
            Func = function()
                local trimmedName = webhookName.Value:gsub('%s+', '')

                if #trimmedName == 0 then
                    return logger.errorNotify('enter a webhook name')
                end

                local trimmedUrl = webhookUrl.Value:gsub('%s+', '')

                if #trimmedUrl == 0 then
                    return logger.errorNotify('enter a webhook URL')
                end

                ensureFolder()

                if writefile then
                    writefile(webhookPath(trimmedName), trimmedUrl)

                    gankPing.savedWebhooks[trimmedName] = trimmedUrl

                    refreshDropdown()
                    logger.successNotify(string.format("webhook '%s' saved", trimmedName))
                end
            end,
        }):AddButton({
            Text = 'Delete Webhook',
            Tooltip = 
"Deletes the webhook whose name is currently in the Webhook Name input.",
            Func = function()
                local deleteName = webhookName.Value:gsub('%s+', '')

                if #deleteName == 0 then
                    return logger.errorNotify('enter a webhook name to delete')
                end

                local deletePath = webhookPath(deleteName)

                if not isfile or not isfile(deletePath) then
                    return logger.errorNotify(string.format("webhook '%s' not found", deleteName))
                end
                if delfile then
                    pcall(delfile, deletePath)
                end

                gankPing.savedWebhooks[deleteName] = nil

                refreshDropdown()
                logger.successNotify(string.format("deleted '%s'", deleteName))
            end,
        })
        tab:AddDivider()

        local webhookList = loadWebhooks()
        local sendToDropdown = tab:AddDropdown('GankWebhookSendTo', {
            Text = 'Send To',
            Values = webhookList,
            Default = {},
            Multi = true,
            AllowNull = true,
            SaveValues = true,
            Tooltip = 
"Every checked webhook receives the gank ping. Names shown are the labels you chose when saving.",
        })

        refreshDropdown = function()
            local savedNames = {}

            for savedName in pairs(gankPing.savedWebhooks)do
                savedNames[#savedNames + 1] = savedName
            end

            table.sort(savedNames)
            sendToDropdown:SetValues(savedNames)
        end

        tab:AddDivider()
        tab:AddDropdown('GankPingTarget', {
            Text = 'Ping Target',
            Values = {
                'None',
                '@everyone',
                '@here',
                'Specific Role',
            },
            Default = 'None',
            Tooltip = 
"What the message itself pings. Specific Role uses the Role ID below.",
            AllowNull = false,
        })
        tab:AddInput('GankPingRoleId', {
            Text = 'Role ID',
            Placeholder = 
"discord role id (only used when Ping Target = Specific Role)",
            Finished = false,
        })

        local defaultFields = {}

        for index, field in ipairs(gankPing.FIELD_IDS)do
            defaultFields[field] = true
        end

        tab:AddDropdown('GankPingFields', {
            Text = 'Send Info Fields',
            Values = gankPing.FIELD_IDS,
            Default = defaultFields,
            Multi = true,
            AllowNull = true,
            Tooltip = 'Which fields to include in the embed. All on by default.',
        })
        tab:AddDivider()
        tab:AddToggle('GankPingHideUserID', {
            Text = 'Hide User ID',
            Tooltip = 
"Force-hides your User ID even if the field is checked above.",
            Default = false,
        })
        tab:AddToggle('GankPingTeamWebhook', {
            Text = 'Ping Global Webhook',
            Tooltip = 'Also routes alerts through the public webhook.',
            Default = false,
        })

        local lastPingTime = 0
        local sendGankPing = function()
            local elapsed = tick() - lastPingTime

            if elapsed < 300 then
                local cooldownLeft = math.ceil(300 - elapsed)
                local minutes = math.floor(cooldownLeft / 60)
                local seconds = cooldownLeft % 60

                return logger.warnNotify(string.format('gank ping on cooldown (%dm %ds)', minutes, seconds))
            end

            lastPingTime = tick()

            gankPing.send()
        end

        tab:AddButton({
            Text = 'Send Gank Ping',
            Tooltip = 
"Pings every selected webhook with your current session info.",
            Func = function()
                sendGankPing()
            end,
        })

        local keybindLabel = tab:AddLabel('Gank Ping Keybind')

        keybindLabel:AddKeyPicker('GankPingKeybind', {
            Default = 'N/A',
            SyncToggleState = false,
            Text = 'Gank Ping',
            Callback = function()
                sendGankPing()
            end,
        })
    end
    function module.init(ui)
        local gameTab = ui:AddTab('Game')
        local leftTabbox = gameTab:AddLeftTabbox()

        module.initMovementSection(leftTabbox:AddTab('Movement'))

        local combatTab = leftTabbox:AddTab('Combat')

        module.initCharacterCombatSection(combatTab)
        exploitTab.initLocalCharacterExploitsSection(combatTab)
        module.initCharacterMiscSection(leftTabbox:AddTab('Misc'))

        local rightTabbox = gameTab:AddRightTabbox()

        module.initPlayerMonitoringSection(rightTabbox:AddTab('Monitoring'))
        module.initGankPingSection(rightTabbox:AddTab('Gank Ping'))

        local assistanceGroup = gameTab:AddLeftGroupbox('Assistance')

        exploitTab.initNetworkOwnershipSection(assistanceGroup)
        visualsTab.initVisualAssistanceSection(assistanceGroup)
        module.initTechsSection(gameTab:AddRightGroupbox('Techs'))

        local effectsTabbox = gameTab:AddLeftTabbox()
        local effectRemovalsTab = effectsTabbox:AddTab('Effect Removals')

        module.initEffectRemovalsSection(effectRemovalsTab)
        visualsTab.initVisualRemovalsSection(effectRemovalsTab)
        module.initInstanceRemovalsSection(effectsTabbox:AddTab('Instance Removals'))

        if not LPH_OBFUSCATED then
            module.initDebuggingSection(gameTab:AddRightGroupbox('Debugging'))
        end
        if exploitTab.teleportsAllowed() then
            exploitTab.initTeleportsSection(gameTab:AddRightTabbox('Teleports'))
        end
        if depthsEscape.isInDepths() then
            local depthsEscapeGroup = gameTab:AddRightGroupbox('Depths Escape')

            depthsEscapeGroup:AddDropdown('FakeVanishMode', {
                Text = 'Fake Vanish Mode',
                Values = {
                    'Tacet Vanish',
                    'Regular Teleport',
                    'Smoke Screen TP',
                    'Portals TP',
                },
                Default = 'Tacet Vanish',
                Tooltip = 
"Tacet Vanish crouches + fires Tacet + only TPs if the circle spawns and no one's inside. Regular Teleport skips Tacet and TPs straight away. Smoke Screen TP fires Resonance:Smokescreen for cover then TPs after 0.8s. Portals TP fires Resonance:Portals then TPs after 1.5s.",
            })
            depthsEscapeGroup:AddToggle('TacetVanishFilterAllies', {
                Text = 'Filter Allies',
                Tooltip = 
"Skip friends / guildmates when checking who is inside the Tacet field (Tacet Vanish mode only).",
                Default = true,
            })

            local fakeVanishLabel = depthsEscapeGroup:AddLabel('Fake Vanish')

            fakeVanishLabel:AddKeyPicker('FakeVanishKeybind', {
                Default = 'N/A',
                SyncToggleState = false,
                Text = 'Fake Vanish',
                Callback = function()
                    depthsEscape.fakeVanish()
                end,
            })
            depthsEscapeGroup:AddToggle('DepthsTPDetector', {
                Text = 'TP Detector',
                Tooltip = 
"When a nearby player suddenly teleports >4000 studs in Y in one frame (script-TP ambush), auto-TPs you up. Ignores character respawns. 30s debounce.",
                Default = false,
            })
            depthsEscapeGroup:AddSlider('DepthsTPDetectorRange', {
                Text = 'TP Detector Range',
                Tooltip = 
"Only watch players within this many studs. Detected teleports outside this range are ignored.",
                Default = 2000,
                Min = 100,
                Max = 10000,
                Suffix = ' studs',
                Rounding = 0,
            })
        end
    end

    return module
end


return aa()

]=],
    ["Menu/LoggerTab"] = [=[
local aa = function()
    local configSection = a["Menu/ConfigSection"]()
    local moduleManager = a["Game/Timings/ModuleManager"]()
    local animationTimingBuilder = a["Menu/AnimationTimingBuilder"]()
    local soundTimingContainer = a["Game/Timings/SoundTimingContainer"]()
    local effectNameInput = a["Menu/EffectNameInput"]()
    local hitboxPartTiming = a["Game/Timings/HitboxPartTiming"]()
    local animationLogger = a["GUI/AnimationLogger"]()
    local animationProfiler = a["Game/Timings/AnimationProfiler"]()
    local eventLogger = a["GUI/EventLogger"]()
    local soundVisualizer = a["Features/Visuals/SoundVisualizer"]()
    local effectBatcher = a["Game/EffectBatcher"]()
    local maid = a["Utility/Maid"]()

    game:GetService('Players')

    local autoParry = a["Features/Combat/AutoParry2"]()
    local maidInstance = maid.new()
    local tabConfig = {
        abs = nil,
        ebs = nil,
        pbs = nil,
        sbs = nil,
    }

    function tabConfig.refresh()
        if tabConfig.abs then
            tabConfig.abs:reset()
            tabConfig.abs:refresh()
        end
        if tabConfig.ebs then
            tabConfig.ebs:reset()
            tabConfig.ebs:refresh()
        end
        if tabConfig.pbs then
            tabConfig.pbs:reset()
            tabConfig.pbs:refresh()
        end
        if tabConfig.sbs then
            tabConfig.sbs:reset()
            tabConfig.sbs:refresh()
        end
    end
    function tabConfig.initSaveManagerSection(saveSection)
        local autoSaveToggle = saveSection:AddToggle('BuilderPeriodicAutoSave', {
            Text = 'Auto Save Periodically',
            Default = true,
        })
        local dependencyBox = saveSection:AddDependencyBox()

        dependencyBox:AddSlider('BuilderPeriodicAutoSaveInterval', {
            Text = 'Auto Save Interval',
            Min = 1,
            Max = 240,
            Rounding = 0,
            Suffix = 's',
            Default = 60,
        })
        dependencyBox:SetupDependencies({
            {autoSaveToggle, true},
        })

        local configNameInput = saveSection:AddInput('BuilderConfigName', {
            Text = 'Config Name',
        })
        local configListDropdown = saveSection:AddDropdown('BuilderConfigList', {
            Text = 'Config List',
            Values = configSection.list(),
            AllowNull = true,
        })

        saveSection:AddButton('Create Config', function()
            configSection.create(configNameInput.Value)
            configSection.refresh(configListDropdown)
        end):AddButton({
            Text = 'Load Config',
            DoubleClick = true,
            Func = function()
                configSection.load(configListDropdown.Value)
                tabConfig.refresh()
            end,
        })
        saveSection:AddButton({
            Text = 'Overwrite Config',
            DoubleClick = true,
            Func = function()
                configSection.save(configListDropdown.Value)
            end,
        })
        saveSection:AddButton({
            Text = 'Clear Config',
            DoubleClick = true,
            Func = function()
                configSection.clear(configListDropdown.Value)
            end,
        })
        saveSection:AddButton('Refresh List', function()
            configSection.refresh(configListDropdown)
            tabConfig.refresh()
        end)
        saveSection:AddButton('Set To Auto Load', function()
            configSection.autoload(configListDropdown.Value)
        end)
    end
    function tabConfig.initLoggerSection(loggerSection)
        local animationLoggerToggle = loggerSection:AddToggle('ShowAnimationVisualizer', {
            Text = 'Show Animation Logger',
            Default = false,
            Tooltip = 
"Opens the animation logger window: target entities, watch what they play, and replay any logged animation on its own character.",
            Callback = animationLogger.visible,
        })

        animationLoggerToggle:AddKeyPicker('AnimationVisualizerKeyBind', {
            Default = 'N/A',
            SyncToggleState = true,
            Text = 'Animation Logger',
        })
        loggerSection:AddDivider()

        local animationBlacklist = loggerSection:AddDropdown('AnimationLoggerBlacklist', {
            Text = 'Blacklisted Animations',
            Values = animationProfiler.blacklisted(),
            Multi = true,
            AllowNull = true,
            Default = {},
            Tooltip = 
"Right-click a row in the logger window to blacklist it. Tick entries here and unblacklist to start logging them again.",
        })

        animationProfiler.onBlacklistChanged(function()
            animationBlacklist:SetValues(animationProfiler.blacklisted())
            animationBlacklist:Display()
        end)
        loggerSection:AddButton('Unblacklist Selected', function()
            for animId in next, animationBlacklist.Value do
                animationProfiler.unblacklist(animId)
            end

            animationBlacklist:SetValue({})
        end)
        loggerSection:AddDivider()

        local eventLoggerToggle = loggerSection:AddToggle('ShowEventVisualizer', {
            Text = 'Show Event Logger',
            Default = false,
            Tooltip = 
"Opens the event logger window: every effect, thrown part and sound that fires within the radius, with the trigger string a timing would match it by.",
            Callback = eventLogger.visible,
        })

        eventLoggerToggle:AddKeyPicker('EventVisualizerKeyBind', {
            Default = 'N/A',
            SyncToggleState = true,
            Text = 'Event Logger',
        })

        local eventBlacklist = loggerSection:AddDropdown('EventLoggerBlacklist', {
            Text = 'Blacklisted Triggers',
            Values = soundVisualizer.blacklisted(),
            Multi = true,
            AllowNull = true,
            Default = {},
            Tooltip = 
"Blacklist a row from the event logger window. Tick entries here and unblacklist to start logging them again.",
        })

        soundVisualizer.onBlacklistChanged(function()
            eventBlacklist:SetValues(soundVisualizer.blacklisted())
            eventBlacklist:Display()
        end)
        loggerSection:AddDivider()

        local missLogDropdown = loggerSection:AddDropdown('MissLogList', {
            Text = 'Unmatched Triggers',
            Values = {},
            AllowNull = true,
            Default = nil,
            Tooltip = 
"Moves that fired with no timing saved for them. Pick one and copy it, or ignore it for this session.",
        })
        local refreshMissList = function()
            local values = {}

            for index, entry in ipairs(effectBatcher.entries())do
                values[#values + 1] = effectBatcher.text(entry)
            end

            missLogDropdown:SetValues(values)
            missLogDropdown:Display()
        end
        local pendingRefresh = false

        effectBatcher.onChange(function()
            local holder = tabConfig.holder

            if holder and not holder.Visible then
                pendingRefresh = true

                return
            end

            pendingRefresh = false

            refreshMissList()
        end)

        local holderFrame = tabConfig.holder

        if holderFrame and type(holderFrame.GetPropertyChangedSignal) == 'function' then
            maidInstance:add(holderFrame:GetPropertyChangedSignal('Visible'):Connect(function(
            )
                if pendingRefresh and holderFrame.Visible then
                    pendingRefresh = false

                    refreshMissList()
                end
            end))
        end

        loggerSection:AddButton('Copy Unmatched Trigger', function()
            for copyIndex, copyEntry in ipairs(effectBatcher.entries())do
                if effectBatcher.text(copyEntry) == missLogDropdown.Value then
                    return effectBatcher.copy(copyEntry)
                end
            end
        end)
        loggerSection:AddButton('Ignore Unmatched Trigger', function()
            for ignoreIndex, ignoreEntry in ipairs(effectBatcher.entries())do
                if effectBatcher.text(ignoreEntry) == missLogDropdown.Value then
                    effectBatcher.ignore(ignoreEntry.trigger)
                    missLogDropdown:SetValue(nil)

                    return
                end
            end
        end)
        loggerSection:AddButton('Clear Unmatched', function()
            effectBatcher.clear()
            missLogDropdown:SetValue(nil)
        end)
        loggerSection:AddToggle('MissLogEnabled', {
            Text = 'Record Unmatched',
            Default = true,
            Tooltip = 
"Keep the list above filled in. Off costs nothing at all, which is what you want once your timings are built.",
            Callback = function(enabled)
                effectBatcher.on = enabled
            end,
        })
        loggerSection:AddButton('Unblacklist Selected Triggers', function()
            for trigger in next, eventBlacklist.Value do
                soundVisualizer.unblacklist(trigger)
            end

            eventBlacklist:SetValue({})
        end)
    end
    function tabConfig.initModuleManagerSection(moduleSection)
        local moduleListDropdown = moduleSection:AddDropdown('ModuleList', {
            Text = 'Module List',
            Values = moduleManager.loaded(),
            AllowNull = true,
            Multi = false,
        })

        moduleSection:AddButton('Refresh List', function()
            moduleManager.refresh()
            moduleListDropdown:SetValues(moduleManager.loaded())
            moduleListDropdown:SetValue(nil)
            moduleListDropdown:Display()
        end)
    end
    function tabConfig.initIgnoreEffectsSection(ignoreSection)
        ignoreSection:AddDropdown('APIgnoreEffects', {
            Text = 'Ignore Effects',
            Values = autoParry.gateEffects(),
            Default = {},
            Multi = true,
            AllowNull = true,
            Tooltip = 
"Effects the auto-parry treats as NOT present, so it acts even while these are on you (they stop blocking Parry/Block/Mantra/Dodge).",
        })
    end
    function tabConfig.init(configTab)
        local builderTab = configTab:AddTab('Builder')

        tabConfig.holder = configTab.Holder

        animationLogger.bindMenu(configTab.Holder)
        eventLogger.bindMenu(configTab.Holder)
        configSection.init()
        tabConfig.initSaveManagerSection(builderTab:AddDynamicGroupbox('Save Manager'))
        tabConfig.initModuleManagerSection(builderTab:AddDynamicGroupbox('Module Manager'))
        tabConfig.initLoggerSection(builderTab:AddDynamicGroupbox('Logger'))
        tabConfig.initIgnoreEffectsSection(builderTab:AddDynamicGroupbox('Auto Parry'))

        tabConfig.abs = animationTimingBuilder.new('Animation', builderTab:AddDynamicTabbox(), configSection.as)
        tabConfig.pbs = hitboxPartTiming.new('Part', builderTab:AddDynamicTabbox(), configSection.ps)
        tabConfig.ebs = effectNameInput.new('Effect', builderTab:AddDynamicTabbox(), configSection.es)
        tabConfig.sbs = soundTimingContainer.new('Sound', builderTab:AddDynamicTabbox(), configSection.ss)

        tabConfig.abs:init()
        tabConfig.ebs:init()
        tabConfig.pbs:init()
        tabConfig.sbs:init()
    end
    function tabConfig.detach()
        configSection.detach()
        animationProfiler.detach()
        soundVisualizer.detach()
        maidInstance:clean()
    end

    return tabConfig
end


return aa()

]=],
    ["Menu/PalantirXTab"] = [=[
local aa = function()
    local aa = {}
    local library = a["GUI/Library"]()
    local logger = a["Utility/Logger"]()
    local saveManager = a["GUI/SaveManager"]()
    local themeEditor = a["GUI/ThemeEditor"]()
    local themeManager = a["GUI/ThemeManager"]()

    function aa.initCheatSettingsSection(section)
        section:AddToggle('FunMode', {
            Text = 'Fun Mode',
            Tooltip = 'Reveals an extra tab with cosmetic options.',
            Default = false,
        })
        section:AddButton('Toggle Silent Mode', function()
            if not isfile or not delfile or not writefile then
                return
            end

            shared.Palantir.silent = not shared.Palantir.silent

            if not shared.Palantir.silent then
                logger.notify('silent mode off')
            end
            if isfile('smarker.txt') then
                delfile('smarker.txt')
            else
                writefile('smarker.txt', 
"PalantirX silent mode is on. Delete this file to turn it off.")
            end
        end)

        local savedSilent
        local panicToggle = section:AddToggle('PanicHide', {
            Text = 'Panic Hide',
            Default = false,
            Tooltip = 
"Instantly hides all on-screen visuals (menu, watermark, notifications, ESP, hitboxes) and enables silent mode. Press the keybind again to restore.",
            Callback = function(enabled)
                shared.Palantir_PanicHide = enabled

                pcall(function()
                    library.ScreenGui.Enabled = not enabled
                end)
                pcall(function()
                    if shared.Palantir_RefreshHitboxViz then
                        shared.Palantir_RefreshHitboxViz()
                    end
                end)
                pcall(function()
                    if shared.Palantir_RefreshAnimationLogger then
                        shared.Palantir_RefreshAnimationLogger()
                    end
                end)

                if shared.Palantir then
                    if enabled then
                        savedSilent = shared.Palantir.silent
                        shared.Palantir.silent = true
                    else
                        shared.Palantir.silent = savedSilent or false
                        savedSilent = nil
                    end
                end
            end,
        })

        panicToggle:AddKeyPicker('PanicHideKeybind', {
            Default = 'End',
            SyncToggleState = true,
            Text = 'Panic Hide',
        })

        do
            local userInputService = game:GetService('UserInputService')
            local connection = userInputService.InputBegan:Connect(function(input)
                if input.KeyCode == Enum.KeyCode.RightAlt and shared.Palantir_PanicHide then
                    pcall(function()
                        panicToggle:SetValue(false)
                    end)
                end
            end)

            if type(library.Signals) == 'table' then
                table.insert(library.Signals, connection)
            end
        end

        section:AddButton('Unload Cheat', function()
            shared.Palantir.detach()
        end)
        section:AddButton('Theme', function()
            if not themeEditor.Panel then
                themeEditor:Init()
            end

            themeEditor:Toggle()
        end)
        section:AddDivider()
        section:AddSlider('TweenStudsPerSecond', {
            Text = 'Tween Speed',
            Default = 200,
            Min = 50,
            Max = 450,
            Suffix = '/s',
            Rounding = 0,
        })
    end
    function aa.initUISettingsSection(uiSection)
        uiSection:AddSlider('NotificationScale', {
            Text = 'Notification Scale',
            Min = 50,
            Max = 300,
            Default = 70,
            Rounding = 0,
            Suffix = '%',
        })
        uiSection:AddSlider('QuickNotificationSpeed', {
            Text = 'Quick Notification Speed',
            Min = 0.1,
            Max = 2,
            Default = 1,
            Rounding = 2,
            Suffix = 's',
        })
        uiSection:AddDivider()
        uiSection:AddToggle('NotifyInfo', {
            Text = 'Show Info Notifications',
            Default = true,
        })
        uiSection:AddToggle('NotifySuccess', {
            Text = 'Show Success Notifications',
            Default = true,
        })
        uiSection:AddToggle('NotifyWarning', {
            Text = 'Show Warning Notifications',
            Default = true,
        })
        uiSection:AddToggle('NotifyError', {
            Text = 'Show Error Notifications',
            Default = true,
        })
        uiSection:AddToggle('NotificationSounds', {
            Text = 'Notification Sounds',
            Default = true,
            Tooltip = 'Plays UI sounds for clicks and notifications.',
        })
        uiSection:AddToggle('ShowRiskColors', {
            Text = 'Show Risk Colors',
            Default = true,
            Tooltip = 
"Color-codes risky toggle labels: red = Blatant, yellow = Warning, purple = Self-clip only.",
            Callback = function(riskColors)
                if library and library.SetRiskColorsEnabled then
                    library:SetRiskColorsEnabled(riskColors)
                end
            end,
        })
        uiSection:AddDivider()
        uiSection:AddToggle('LoadingScreenEnabled', {
            Text = 'Loading Screen',
            Default = true,
            Tooltip = 'Shows a loading screen on launch.',
        })
        uiSection:AddDivider()

        local menuBind = uiSection:AddLabel('Menu Bind')

        menuBind:AddKeyPicker('MenuKeybind', {
            Default = 'LeftAlt',
            NoUI = true,
            Text = 'Menu Keybind',
        })
        uiSection:AddToggle('ShowKeybindList', {
            Text = 'Show Keybind List',
            Default = false,
            Callback = function(visible)
                if library.KeybindFrame then
                    library.KeybindFrame.Visible = visible
                end
            end,
        })
        uiSection:AddLabel('Title Color'):AddColorPicker('TitleAccentColor', {
            Default = Color3.new(1, 1, 1),
        })
    end

    local tweenService = game:GetService('TweenService')
    local animateElement = function(tab)
        local elements = {}

        for idx, toggle in pairs(Toggles)do
            if not toggle.TextLabel then
                continue
            end

            local tabObj = toggle.Groupbox and (toggle.Groupbox.Tab or toggle.Groupbox)
            local tabName = toggle.Groupbox and (toggle.Groupbox.TabName or (tabObj and tabObj.Name)) or nil

            if not tabName then
                continue
            end

            elements[#elements + 1] = {
                name = toggle.TextLabel.Text,
                tab = tabName,
                tabObj = tabObj,
                frame = toggle.TextLabel.Parent,
            }
        end
        for optIdx, option in pairs(Options)do
            if not option.Text or not option.OuterFrame then
                continue
            end

            local optTabObj = option.Groupbox and (option.Groupbox.Tab or option.Groupbox)
            local optTabName = option.Groupbox and (option.Groupbox.TabName or (optTabObj and optTabObj.Name)) or nil

            if not optTabName then
                continue
            end

            elements[#elements + 1] = {
                name = option.Text,
                tab = optTabName,
                tabObj = optTabObj,
                frame = option.OuterFrame,
            }
        end

        return elements
    end
    local queueTween = function(ui, entry)
        local tabPage = ui.Tabs[entry.tab]

        if tabPage and tabPage.ShowTab then
            tabPage:ShowTab()
        end

        local frame = entry.frame

        if frame then
            local scrollFrame = frame.Parent

            while scrollFrame and not scrollFrame:IsA('ScrollingFrame') do
                scrollFrame = scrollFrame.Parent
            end

            if scrollFrame and scrollFrame:IsA('ScrollingFrame') then
                local targetY = frame.AbsolutePosition.Y - scrollFrame.AbsolutePosition.Y + scrollFrame.CanvasPosition.Y
                local scrollPos = math.max(0, targetY - 40)

                scrollFrame.CanvasPosition = Vector2.new(0, scrollPos)
            end

            task.spawn(function()
                local highlight = Instance.new('Frame')

                highlight.Name = 'SearchHighlight'
                highlight.BackgroundColor3 = library.AccentColor
                highlight.BackgroundTransparency = 0.7
                highlight.BorderSizePixel = 0
                highlight.Size = UDim2.new(1, 4, 1, 4)
                highlight.Position = UDim2.new(0, -2, 0, -2)
                highlight.ZIndex = 50
                highlight.Parent = frame

                tweenService:Create(highlight, TweenInfo.new(0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
                task.wait(0.85)
                highlight:Destroy()
            end)
        end
    end

    function aa.init(uiTab)
        local settingsTab = uiTab:AddTab('Settings')
        local holder = uiTab.Holder:FindFirstChildOfClass('Frame')

        if holder then
            local bar = library:Create('Frame', {
                BackgroundColor3 = Color3.fromRGB(30, 30, 30),
                BorderSizePixel = 0,
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -10, 0.5, 0),
                Size = UDim2.new(0, 28, 0, 20),
                ZIndex = 10,
                ClipsDescendants = true,
                Parent = holder,
            })

            library:Create('UICorner', {
                CornerRadius = UDim.new(0, 3),
                Parent = bar,
            })
            library:Create('UIStroke', {
                Color = Color3.fromRGB(40, 40, 40),
                Thickness = 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                Parent = bar,
            })

            local searchLabel = library:Create('TextLabel', {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 1, 0),
                Text = '...',
                TextColor3 = Color3.fromRGB(70, 70, 70),
                TextSize = 12,
                FontFace = library.Font,
                ZIndex = 12,
                Parent = bar,
            })
            local searchBox = library:Create('TextBox', {
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                PlaceholderText = 'Search...',
                PlaceholderColor3 = Color3.fromRGB(80, 80, 80),
                Text = '',
                TextColor3 = library.FontColor,
                FontFace = library.Font,
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Left,
                ClearTextOnFocus = false,
                Position = UDim2.new(0, 0, 0, 0),
                Size = UDim2.new(1, 0, 1, 0),
                ZIndex = 11,
                Visible = false,
                Parent = bar,
            })

            library:Create('UIPadding', {
                PaddingLeft = UDim.new(0, 8),
                Parent = searchBox,
            })
            library:AddToRegistry(searchBox, {
                TextColor3 = 'FontColor',
            })

            local searchActive = false
            local hoverDelay
            local openSearch = function()
                if searchActive then
                    return
                end

                searchActive = true
                searchLabel.Visible = false
                searchBox.Visible = true

                tweenService:Create(bar, TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                    Size = UDim2.new(0, 160, 0, 20),
                }):Play()
                task.defer(function()
                    searchBox:CaptureFocus()
                end)
            end
            local closeSearch = function()
                if not searchActive then
                    return
                end
                if searchBox:IsFocused() then
                    return
                end
                if searchBox.Text ~= '' then
                    return
                end

                searchActive = false

                tweenService:Create(bar, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
                    Size = UDim2.new(0, 28, 0, 20),
                }):Play()
                task.delay(0.2, function()
                    if not searchActive then
                        searchBox.Visible = false
                        searchLabel.Visible = true
                    end
                end)
            end

            bar.MouseEnter:Connect(function()
                hoverDelay = task.delay(0.4, function()
                    hoverDelay = nil

                    openSearch()
                end)
            end)
            bar.MouseLeave:Connect(function()
                if hoverDelay then
                    task.cancel(hoverDelay)

                    hoverDelay = nil
                end

                closeSearch()
            end)
            bar.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 then
                    if hoverDelay then
                        task.cancel(hoverDelay)

                        hoverDelay = nil
                    end

                    openSearch()
                end
            end)

            local screenGui = holder

            while screenGui and not screenGui:IsA('ScreenGui') do
                screenGui = screenGui.Parent
            end

            local resultsFrame = library:Create('Frame', {
                BackgroundColor3 = library.MainColor,
                BorderSizePixel = 0,
                Size = UDim2.new(0, 200, 0, 0),
                Visible = false,
                ZIndex = 500,
                ClipsDescendants = true,
                Parent = screenGui,
            })

            library:Create('UIStroke', {
                Color = library.OutlineColor,
                Thickness = 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                Parent = resultsFrame,
            })
            library:AddToRegistry(resultsFrame, {
                BackgroundColor3 = 'MainColor',
            })
            library:AddGradient(resultsFrame)
            library:Create('UIListLayout', {
                FillDirection = Enum.FillDirection.Vertical,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Parent = resultsFrame,
            })

            local resultButtons = {}

            for i = 1, 8 do
                local button = library:Create('TextButton', {
                    BackgroundColor3 = library.MainColor,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    Size = UDim2.new(1, 0, 0, 22),
                    FontFace = library.Font,
                    TextColor3 = library.FontColor,
                    TextSize = 12,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Text = '',
                    ZIndex = 502,
                    Visible = false,
                    Parent = resultsFrame,
                })

                library:Create('UIPadding', {
                    PaddingLeft = UDim.new(0, 6),
                    Parent = button,
                })
                button.MouseEnter:Connect(function()
                    button.BackgroundTransparency = 0
                    button.BackgroundColor3 = library.AccentColor
                    button.TextColor3 = Color3.new(0, 0, 0)
                end)
                button.MouseLeave:Connect(function()
                    button.BackgroundTransparency = 1
                    button.TextColor3 = library.FontColor
                end)

                resultButtons[i] = button
            end

            local slotElements = {}
            local updateResults = function(query)
                query = query:lower():gsub('^%s+', ''):gsub('%s+$', '')

                for slotIdx = 1, 8 do
                    resultButtons[slotIdx].Visible = false
                    resultButtons[slotIdx].Text = ''
                end

                slotElements = {}

                if query == '' then
                    resultsFrame.Visible = false

                    return
                end

                local candidates = animateElement(uiTab)
                local matched = {}
                local seen = {}

                for index, candidate in ipairs(candidates)do
                    if candidate.name:lower():find(query, 1, true) then
                        local key = candidate.name .. '|' .. candidate.tab

                        if not seen[key] then
                            seen[key] = true
                            matched[#matched + 1] = candidate
                        end
                    end
                    if #matched >= 8 then
                        break
                    end
                end

                if #matched == 0 then
                    resultsFrame.Visible = false

                    return
                end

                for matchIdx, match in ipairs(matched)do
                    local slotButton = resultButtons[matchIdx]

                    slotButton.Text = match.name .. '  \u{b7}  ' .. match.tab
                    slotButton.Visible = true
                    slotElements[matchIdx] = match
                end

                local barPos = bar.AbsolutePosition
                local barSize = bar.AbsoluteSize

                resultsFrame.Position = UDim2.fromOffset(barPos.X, barPos.Y + barSize.Y + 2)
                resultsFrame.Size = UDim2.fromOffset(math.max(barSize.X, 200), #matched * 22)
                resultsFrame.Visible = true
            end

            for slot = 1, 8 do
                resultButtons[slot].MouseButton1Click:Connect(function()
                    local element = slotElements[slot]

                    if element then
                        queueTween(uiTab, element)

                        searchBox.Text = ''
                        resultsFrame.Visible = false

                        searchBox:ReleaseFocus()
                    end
                end)
            end

            searchBox:GetPropertyChangedSignal('Text'):Connect(function()
                if searchBox:IsFocused() then
                    library:PlayTypeSound()
                end

                updateResults(searchBox.Text)
            end)
            searchBox.FocusLost:Connect(function()
                task.wait(0.15)

                resultsFrame.Visible = false

                closeSearch()
            end)
        end

        local tabbox = settingsTab:AddLeftTabbox()

        aa.initCheatSettingsSection(tabbox:AddTab('Cheat Settings'))
        aa.initUISettingsSection(tabbox:AddTab('UI Settings'))

        local applied = themeManager:ApplyToTab(settingsTab)

        if applied and applied.BoxFrame then
            applied.BoxFrame.Visible = false
        end

        themeEditor:SetLibrary(library)
        themeEditor:SetThemeManager(themeManager)
        saveManager:BuildConfigSection(settingsTab)
    end
    function aa.wireFunMode(element)
        if element and element.reflow then
            pcall(element.reflow)
        end

        local toggles = (getgenv and getgenv().Toggles) or rawget(getfenv(), 'Toggles')
        local funMode = toggles and toggles.FunMode

        if not funMode or not element then
            return
        end

        funMode:OnChanged(function(enabled)
            pcall(element.setVisible, enabled == true)
            pcall(element.spawnRainbowParticles)
        end)
    end

    return aa
end


return aa()

