    end
    function moduleExports:anc(callback)
        return function(...)
            if not self.timingList.Value then
                return logger.warn('No timing selected.')
            end

            local timing = self.container:find(self.timingList.Value)

            if not timing then
                return logger.longNotify('You must select a valid timing to perform this action.')
            end
            if not self.actionList.Value then
                return logger.warn('No action selected.')
            end

            local ah = timing.actions:find(self.actionList.Value)

            if not ah then
                return logger.longNotify('You must select a valid action to perform this action.')
            end

            callback(ah, ...)
        end
    end
    function moduleExports:aload()
        if not (self.timingList.Value and self.actionList.Value) then
            return
        end

        local timing = self.container:find(self.timingList.Value)
        local ag = timing and timing.actions:find(self.actionList.Value)

        if not ag then
            return
        end

        local ah = ag

        self.actionName:SetRawValue(ah.name)
        self.actionDelay:SetRawValue(ah._when or 0)
        self.actionType:SetRawValue(ah._type)
        self.hitboxWidth:SetRawValue(ah.hitbox.X)
        self.hitboxHeight:SetRawValue(ah.hitbox.Y)
        self.hitboxLength:SetRawValue(ah.hitbox.Z)
        self.actionFacing:SetRawValue(ah.fhb ~= false)
        self.actionShiftOffset:SetRawValue(ah.hso or 0)
        self.actionBlockHold:SetRawValue(ah.bfht or 0.3)
        self.actionWaitForContact:SetRawValue(ah.duih or false)
        self.actionIgnoreBlockFacing:SetRawValue(ah.ibfc or false)
        self.actionIgnoreParryFrames:SetRawValue(ah.iapf or false)
        self.actionIgnoreDodgeFrames:SetRawValue(ah.idf or false)
        self.actionIgnoreHighPosture:SetRawValue(ah.ihp or false)
        self.actionNoBlockFallback:SetRawValue(ah.nbfb or false)
        self.actionNoDashFallback:SetRawValue(ah.ndfb or false)
        self.actionNoRollCancel:SetRawValue(ah.nrc or false)
        self.actionMaxPoll:SetRawValue(ah.mpoll or 1500)
        self:exaload(ah)
    end
    function moduleExports:baction(group)
