    function moduleExports:timing()
        local tab = self.tabbox:AddTab('Timings')

        self.timingList = tab:AddDropdown(nil, {
            Text = 'Saved Timings',
            Values = self.container:names(),
            AllowNull = true,
            Callback = function(name)
                self:reset()

                if not name then
                    return logger.warn('No timing value.')
                end

                local timing = self.container:find(name)

                if not timing then
                    return logger.longNotify("The selected timing '%s' does not exist in the list.", name)
                end

                self.timingName:SetRawValue(timing.name)
                self.timingTag:SetRawValue(timing.tag)
                self.initialMaximumDistance:SetRawValue(timing.imxd)
                self.initialMinimumDistance:SetRawValue(timing.imdd)
                self.afterWindow:SetRawValue(timing.after)
                self.forcedActions:SetRawValue(timing.forced)
                self.timingType:SetRawValue(timing.umoa and 'Module' or 'Timing')
                self:mode(timing.umoa)
                self.skipModuleNotification:SetRawValue(timing.smn)
                self.selectedModule:SetRawValue(timing.smod)
                self.skipRepeatNotification:SetRawValue(timing.srpn)
                self.repeatParryDelay:SetRawValue(timing._rpd)
                self.repeatStartDelay:SetRawValue(timing._rsd)
                self.repeatUntilParryEnd:SetRawValue(timing.rpue)

                local repeatAction = timing.rpact

                if repeatAction then
                    self.repeatHitboxLength:SetRawValue(repeatAction.hitbox.Z)
                    self.repeatHitboxWidth:SetRawValue(repeatAction.hitbox.X)
                    self.repeatHitboxHeight:SetRawValue(repeatAction.hitbox.Y)
                    self.repeatFacing:SetRawValue(repeatAction.fhb ~= false)
                    self.repeatShiftOffset:SetRawValue(repeatAction.hso or 0)
                    self.repeatBlockHold:SetRawValue(repeatAction.bfht or 0.3)
                    self.repeatType:SetRawValue(repeatAction._type or 'Parry')
                    self.repeatIgnoreBlockFacing:SetRawValue(repeatAction.ibfc or false)
                    self.repeatIgnoreParryFrames:SetRawValue(repeatAction.iapf or false)
                    self.repeatIgnoreDodgeFrames:SetRawValue(repeatAction.idf or false)
                    self.repeatIgnoreHighPosture:SetRawValue(repeatAction.ihp or false)
                    self.repeatNoBlockFallback:SetRawValue(repeatAction.nbfb or false)
                    self.repeatNoDashFallback:SetRawValue(repeatAction.ndfb or false)
                    self.repeatNoRollCancel:SetRawValue(repeatAction.nrc or false)
                end

                self:exload(timing)
                self:arefresh(timing)
            end,
        })
        self.timingType = tab:AddDropdown(nil, {
            Text = 'Type',
            Values = {
                'Timing',
                'Module',
            },
            Default = 1,
            Tooltip = 
"Build the move from actions here, or hand it to a Lua file in Modules/ that decides everything in code.",
            Callback = function(mode)
                self:mode(mode == 'Module')

                local selectedName = self.timingList and self.timingList.Value

                if not selectedName then
                    return
                end

                local foundTiming = self.container:find(selectedName)

                if foundTiming then
                    foundTiming.umoa = mode == 'Module'
                end
            end,
        })

        local box = tab:AddDependencyBox()

        self.selectedModule = box:AddInput(nil, {
            Text = 'Module Name',
            Finished = true,
            Tooltip = 'File name in Modules/, without the .lua.',
            Callback = self:tnc(function(source, value)
                source.smod = value
            end),
        })
        self.skipModuleNotification = box:AddToggle(nil, {
            Text = 'Skip Module Notify',
            Default = false,
            Callback = self:tnc(function(target, checked)
                target.smn = checked
            end),
        })

        box:SetupDependencies({
            {
                self.timingType,
                'Module',
            },
        })
        tab:AddDivider()

        self.timingName = tab:AddInput(nil, {
            Text = 'Move Name',
            Finished = true,
        })

        self:tide(tab)
        tab:AddButton('Create New Timing', function()
            if not self:check() then
                return
            end

            local newTiming = self:create()

            self.container:push(newTiming)
            self:refresh()
            self.timingList:SetValue(newTiming.name)
            self.timingList:Display()
        end)
        tab:AddButton('Duplicate Selected Timing', self:tnc(function(duplicate)
            if not self:check() then
                return
            end

            local cloned = duplicate:clone()

            self:cset(cloned)
            self.container:push(cloned)
            self:refresh()
            self.timingList:SetValue(cloned.name)
            self.timingList:Display()
        end))
        tab:AddButton('Remove Selected Timing', function()
            local currentName = self.timingList.Value

            if not currentName then
                return logger.longNotify('Please select a timing to remove.')
            end

            local existing = self.container:find(currentName)

            if not existing then
                return logger.longNotify("The selected timing '%s' does not exist in the list.", currentName)
            end

            self.container:remove(existing)
            self:refresh()
        end)
    end
    function moduleExports:builder()
        local tab = self.tabbox:AddTab(self.name)

        self.builderTab = tab
        self.timingTag = tab:AddDropdown(nil, {
            Text = 'Class',
            Values = {
                'Undefined',
                'Critical',
                'Mantra',
                'M1',
            },
            Default = 1,
            Callback = self:tnc(function(ag, ah)
                ag.tag = ah
            end),
        })
        self.initialMinimumDistance = tab:AddSlider(nil, {
            Text = 'Min Distance',
            Min = 0,
            Max = 300,
            Suffix = 'st',
            Default = 0,
            Rounding = 0,
            Callback = self:tnc(function(ag, ah)
                ag.imdd = ah
            end),
        })
        self.initialMaximumDistance = tab:AddSlider(nil, {
            Text = 'Max Distance',
            Min = 0,
            Max = 2500,
            Suffix = 'st',
            Default = 1000,
            Rounding = 0,
            Callback = self:tnc(function(ag, ah)
                ag.imxd = ah
            end),
        })
        self.forcedActions = tab:AddToggle(nil, {
            Text = 'Forced Actions',
            Default = false,
            Tooltip = 
"Keep this move's actions when it re-triggers. An animation that restarts constantly otherwise wipes its own schedule every time.",
            Callback = self:tnc(function(ag, ah)
                ag.forced = ah
            end),
        })
        self.afterWindow = tab:AddSlider(nil, {
            Text = 'Late Window',
            Min = 0,
            Max = 1,
            Default = 0.1,
            Suffix = 's',
            Rounding = 2,
            Callback = self:tnc(function(ag, ah)
                ag.after = ah
            end),
        })
        self.timingOnly = tab:AddDependencyBox()
        self.skipRepeatNotification = self.timingOnly:AddToggle(nil, {
            Text = 'Skip Repeat Notify',
            Default = false,
            Callback = self:tnc(function(ag, ah)
                ag.srpn = ah
            end),
        })

        self:extra(tab)
        self.timingOnly:SetupDependencies({
            {
                self.timingType,
                'Timing',
            },
        })
    end
    function moduleExports:mode(hidden)
        if self.actionTab then
            self.actionTab:SetVisible(not hidden)
        end
        if self.fallbackTab then
            self.fallbackTab:SetVisible(not hidden)
        end
    end
    function moduleExports:init()
        self:timing()
        self:builder()
        self:action()
        self:fallbacks()
        self:mode(false)
    end
    function moduleExports.new(name, tabbox, container)
        local ai = setmetatable({}, moduleExports)

        ai.name = name
        ai.tabbox = tabbox
        ai.container = container

        return ai
    end

    return moduleExports
end


