            if not table.find(filterList, enteredLabel) then
                table.insert(filterList, enteredLabel)
            end

            filterListDropdown:SetValues(filterList)
            filterListDropdown:SetValue({})
            filterListDropdown:Display()
        end)
        filterBox:AddButton('Remove Selected Names', function()
            local filterList = filterListDropdown.Values
