    local loadingScreen = a["Utility/LoadingScreen"]()
    local maid = a["Utility/Maid"]()
    local persistentData = a["Utility/PersistentData"]()
    local menu = a["Menu"]()

    task.wait()

    local features = a["Features"]()

    task.wait()

    local hooking = a["Game/Hooking"]()

    task.wait()

    local keyHandling = a["Game/KeyHandling"]()

    task.wait()

    local controlModule = a["Utility/ControlModule"]()

    task.wait()

    local playerScanning = a["Game/PlayerScanning"]()

    task.wait()
    task.wait()

    local serverHop = a["Game/ServerHop"]()

    task.wait()

    local wipe = a["Game/Wipe"]()
    local newMaid = maid.new()
    local ar = {
        [12559711136] = true,
        [12522889886] = true,
        [12522881268] = true,
        [12522892314] = true,
        [132160566322181] = true,
        [13789332988] = true,
        [8712356310] = true,
    }
    local isPlaceActive = function(placeId)
        return ar[placeId] == true
    end
    local players = game:GetService('Players')
    local startTime = os.clock()

    function aa.init()
        while not game:IsLoaded() do
            task.wait()
        end
        while players.LocalPlayer == nil do
            task.wait()
        end

        if shared.Palantir_RefreshLP then
            shared.Palantir_RefreshLP()
        end

        do
            local player = players.LocalPlayer
            local cleanup = function()
                shared.Palantir_Dying = true
                shared.Palantir_LP = nil
                shared.Palantir_Services = nil
                shared.Palantir_RangeTelegraph = nil
                shared.Palantir_CalcLocalSwingDuration = nil
                shared.Palantir_RefreshLP = nil
                shared.Palantir_InsanityStuckAnimIDs = nil

                pcall(function()
                    newMaid:clean()
                end)
            end

            if player then
                local teleportState = Enum.TeleportState

                pcall(function()
                    player.OnTeleport:Connect(function(newState)
                        if newState == teleportState.Started or newState == teleportState.InProgress or newState == teleportState.WaitingForServer then
                            cleanup()
                        end
                    end)
                end)
            end

