            logger.suppressNotifications()
        end

        do
            local placeLabel = '?'

            if game.PlaceId == 4111023553 then
                placeLabel = 'LOBBY'
            end
            if isPlaceActive(game.PlaceId) then
                placeLabel = 'CHIME_LOBBY'
            end
            if game.PlaceId == 5735553160 then
                placeLabel = 'DEPTHS'
            end
            if not LPH_OBFUSCATED then
                warn(string.format('[PalantirX] Palantir.lua running. PlaceId=%d (%s)', game.PlaceId, placeLabel))
            end
