            local ok, errorResult = xpcall(initFunc, function(err)
                return tostring(err) .. '\n' .. debug.traceback('', 2)
            end)

            if not ok then
                if not LPH_OBFUSCATED then
                    warn(string.format('PalantirX: %s init failed:\n%s\n(continuing)', moduleName, tostring(errorResult)))
                end
            end
        end

