                continue
            end
            if ab:GetPlayerFromCharacter(ah) then
                continue
            end

            local ai = ah:FindFirstChild('HumanoidRootPart')

            if not ai then
                continue
            end
            if (ad - ai.Position).Magnitude > ae then
                continue
            end

            return ah
        end

        return nil
    end
    aa.pnear = function(ad, ae)
        for af, ag in next, ab:GetPlayers()do
            if ag == ab.LocalPlayer then
                continue
            end

            local ah = ag.Character

            if not ah then
                continue
            end

            local ai = ah:FindFirstChild('HumanoidRootPart')

            if not ai then
                continue
            end
            if (ad - ai.Position).Magnitude > ae then
                continue
            end

            return ag
        end

        return nil
    end
    aa.entity = function(ad)
        local ae = workspace:FindFirstChild('Live')

        if not ae then
            return nil
        end

        for af, ag in next, ae:GetChildren()do
            if not ag.Name:match(ad) then
                continue
            end

            return ag
        end
    end
    aa.cdlocked = function(ad)
        local ae = ac:FindFirstChild('EffectReplicator')

        if not ae then
            return nil
        end

        local af = require(ae)

        if not af then
            return nil
        end

        for ag, ah in next, af.Effects do
            if ah.Value ~= ad then
                continue
            end

            return true
        end

        return false
    end
    aa.ncdm = function(ad)
