        if not ae then
            return nil
        end

        local af = require(ae)

        if not af then
            return nil
        end

        local ag = ab.LocalPlayer:FindFirstChild('Backpack')

        if not ag then
            return nil
        end

        for ah, ai in next, ag:GetChildren()do
            if not ai:IsA('Tool') then
                continue
            end
            if not ai.Name:match('Mantra:') or ai.Name:match('Recalled') then
                continue
