        local ah

        for ai, aj in next, af:GetChildren()do
            if not aj:IsA('Model') then
                continue
            end

            local ak = (ad - aj:GetPivot().Position).Magnitude

            if ae and ak > ae then
                continue
            end
            if ah and ak >= ah then
                continue
            end

            ag = aj
            ah = ak
        end

        return ag
    end
    aa.sdparts = function(ad, ae, af)
        local ag = ab.LocalPlayer.Character
        local ah = ag and ag:FindFirstChild('HumanoidRootPart')

        if not ah then
            return
        end

        local ai = {}
        local aj = {}

        for ak, al in next, ad:GetChildren()do
            if not al:IsA('BasePart') then
                continue
            end
            if not ae(al) then
                continue
            end

            local am = (al.Position - ad.Position).Magnitude

            if am > af then
                continue
            end

            ai[#ai + 1] = al
            aj[al] = am
        end

        table.sort(ai, function(ak, al)
            return aj[ak] < aj[al]
        end)

        return ai
