                continue
            end

            local am = al:FindFirstChild('HumanoidRootPart')

            if not am then
                continue
            end

            local an = (am.Position - ag.Position).Magnitude

            if an > ad then
                continue
            end

            table.insert(ah, ak)

            ai[ak] = an
        end

