                continue
            end

            local am = al:FindFirstChild('HumanoidRootPart')

            if not am then
                continue
            end

            local an = (am.Position - ah.Position).Magnitude

            if an > ad then
                continue
            end

            table.insert(ai, al)

            aj[al] = an
        end

        table.sort(ai, function(ak, al)
            return aj[ak] < aj[al]
        end)

