local aa = function()
    local aa = {}
    local ab = game:GetService('CollectionService')
    local ac = a["Utility/Signal"]()

    aa.mark = function(ad, ae, af)
        local ag = ad[ae]

        if ag then
            return ag
        end

        local ah = ac.new(af.AncestryChanged)

        if af:IsA('BodyVelocity') then
            ab:AddTag(af, 'AllowedBM')
        end

        ad[ae] = af

        ad:add(ah:connect('Instance_OnAncestorChange', function(ai)
