        end

        local ai = Instance.new(af, ag)
        local aj = ac.new(ai.AncestryChanged)

        if ai:IsA('BodyVelocity') then
            ab:AddTag(ai, 'AllowedBM')
        end

        ad[ae] = ai

        ad:add(aj:connect('Instance_OnAncestorChange', function(al)
            if ai:IsDescendantOf(game) then
                return
            end

            ad:removeTask(ae)
        end))

        return ai
    end

    return aa
end


return aa()

