            local an, ao = pcall(function()
                return ac:JSONDecode(am)
            end)

            if not an or type(ao) ~= 'table' or type(ao.objects) ~= 'table' then
                return ah
            end

            for ap, aq in next, ao.objects do
                if aq.idx == 'LoadingScreenEnabled' and aq.type == 'Toggle' then
                    ah.enabled = aq.value ~= false
                end
            end

            return ah
        end
        local ai = {
            screenGui = nil,
            label = nil,
        }

        function aa.show()
            if ai.screenGui then
                return
            end

            local aj = ah()

            if not aj.enabled then
                return
            end

            local ak = Instance.new('ScreenGui')

            ak.Name = 'PalantirX_Loading'
            ak.IgnoreGuiInset = true
            ak.ResetOnSpawn = false
            ak.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            ak.DisplayOrder = 2147483646

            pcall(function()
                if gethui then
                    ak.Parent = gethui()
                else
                    ak.Parent = game:GetService('CoreGui')
                end
            end)

            if not ak.Parent then
                ak.Parent = ad.LocalPlayer:WaitForChild('PlayerGui')
            end

            local al = Instance.new('TextLabel')

            al.Size = UDim2.new(1, 0, 0, 300)
            al.Position = UDim2.new(0, 0, 0.5, -150)
            al.BackgroundTransparency = 1
            al.Text = 'PALANTIR X'
            al.Font = Enum.Font.GothamBlack
            al.TextSize = 220
            al.TextColor3 = Color3.fromRGB(235, 235, 240)
            al.TextTransparency = 0
            al.TextStrokeTransparency = 1
            al.ZIndex = 2
            al.Parent = ak
            ai.screenGui = ak
            ai.label = al
        end
        function aa.yield(aj)
            if not ai.screenGui then
                return
            end

            for ak = 1, (aj or 1)do
                af.RenderStepped:Wait()
            end
        end
        function aa.hide()
            if not ai.screenGui then
                return
            end

            local aj = ai.screenGui

            ai.screenGui = nil
            ai.label = nil

            pcall(function()
                aj:Destroy()
            end)
        end

        local aj = function()
            local aj = Instance.new('Sound')

            aj.SoundId = 'rbxassetid://6026984224'
