-- ---------------------------------------------------------------------------
-- Module loader.
--
-- Convention: a[key] returns a THUNK; calling a[key]() evaluates the module
-- chunk once and returns its value (table, function, etc. -- each module
-- returns whatever it returns). Callers always write a[key](), sometimes
-- a[key]()() when the module itself returns a function (VoidTeleport).
-- The RESULT is cached: a[key]() always returns the same module instance,
-- so modules are compiled and executed exactly once. (Caching only the
-- thunk would re-parse + re-run the whole source on every a[key](), which
-- re-executes side effects and leaks Instances/connections/state.)
-- ---------------------------------------------------------------------------
local _cache = {}
local _result = {}

a = setmetatable({}, {
    __index = function(_, key)
        local thunk = _cache[key]
        if thunk then return thunk end

        local src = EMBED[key]
        if type(src) ~= 'string' then
            error(('[PalantirX] module not found: %q'):format(tostring(key)), 2)
        end

        thunk = function()
            local hit = _result[key]
            if hit ~= nil then return hit end

            local chunk, loadErr = loadstring(src, '=modules/' .. key)
            if not chunk then
                error(('[PalantirX] failed to compile %q: %s'):format(tostring(key), tostring(loadErr)), 2)
            end

            local ok, result = pcall(chunk)
            if not ok then
                error(('[PalantirX] failed to load %q: %s'):format(tostring(key), tostring(result)), 2)
            end

            _result[key] = result
            return result
        end

        _cache[key] = thunk
        return thunk
    end,
})

