local ag = a["Palantir"]()
local ah = function()
    if ab and ac then
        pcall(ab.detach)
    end

    shared.Palantir = ag
    shared.Palantir_LoadJobId = game.JobId

    shared.Palantir.init()
end
local ai = function(ai)
    warn('Failed to initialize.')
    warn(ai)
    aa(debug.traceback())
    ag.detach()
end

xpcall(ah, ai)

